type fk_nothing = |

let fk_show_float f =
  if Float.is_nan f then "NaN"
  else if f = Float.infinity then "Infinity"
  else if f = Float.neg_infinity then "-Infinity"
  else if f = 0.0 then (if 1.0 /. f < 0.0 then "-0.0" else "0.0")
  else
    let rec shortest p = let s = Printf.sprintf "%.*e" (p - 1) (Float.abs f) in if p >= 17 || float_of_string s = Float.abs f then s else shortest (p + 1) in
    let s = shortest 1 in
    let i = String.index s 'e' in
    let digits = String.concat "" (String.split_on_char '.' (String.sub s 0 i)) in
    let exponent = String.sub s (i + 1) (String.length s - i - 1) in
    let e = int_of_string (if exponent.[0] = '+' then String.sub exponent 1 (String.length exponent - 1) else exponent) in
    let n = String.length digits in
    let a = Float.abs f in
    let body =
      if a >= 1e-3 && a < 1e7 then
        if e >= 0 then
          (if n > e + 1 then String.sub digits 0 (e + 1) else digits ^ String.make (e + 1 - n) '0') ^ "." ^
            (if n > e + 1 then String.sub digits (e + 1) (n - e - 1) else "0")
        else "0." ^ String.make (- e - 1) '0' ^ digits
      else String.sub digits 0 1 ^ "." ^ (if n > 1 then String.sub digits 1 (n - 1) else "0") ^ "E" ^ string_of_int e
    in
    (if f < 0.0 then "-" else "") ^ body

let fk_show_char c = let b = Buffer.create 4 in Buffer.add_utf_8_uchar b (Uchar.of_int c); Buffer.contents b

let fk_assertion_facts facts =
  let escape v = let b = Buffer.create (String.length v) in String.iter (function '\\' -> Buffer.add_string b "\\\\" | '\n' -> Buffer.add_string b "\\n" | c -> Buffer.add_char b c) v; Buffer.contents b in
  "\nfckt-assertion 1" ^ String.concat "" (List.map (fun (k, v) -> "\n" ^ k ^ " " ^ escape v) facts)

let fk_assertion_failed summary facts = failwith (summary ^ fk_assertion_facts facts)

let fk_assert_equals show where source expected actual =
  if expected = actual then () else
    let e = show expected and a = show actual in
    let source = if source = "" then [] else [("source", source)] in
    failwith (where ^ ": expected:<" ^ e ^ "> but was:<" ^ a ^ ">"
      ^ fk_assertion_facts ([("assertion", "assertEquals"); ("where", where)] @ source @ [("expected", e); ("actual", a)]))

let fk_show_list show l = "[" ^ String.concat ", " (List.map show l) ^ "]"

let fk_show_option show o = match o with Some x -> "Some(" ^ show x ^ ")" | None -> "None"

let fk_show_result show show_error r = match r with Ok x -> "Ok(" ^ show x ^ ")" | Error e -> "Error(" ^ show_error e ^ ")"


type options = { inputs : string list; output : string option; own : string list; others : string list; libraries : string list; no_std : bool; separate : bool; library : string option; test : string option; marker : string option; runner : string option; fixtures : string option; runner_tests : bool; imports : string list; symbols : string option }

let rec show_options (v : options) =
  "Options(" ^ "inputs=" ^ fk_show_list Fun.id v.inputs ^ ", output=" ^ fk_show_option Fun.id v.output ^ ", own=" ^ fk_show_list Fun.id v.own ^ ", others=" ^ fk_show_list Fun.id v.others ^ ", libraries=" ^ fk_show_list Fun.id v.libraries ^ ", noStd=" ^ string_of_bool v.no_std ^ ", separate=" ^ string_of_bool v.separate ^ ", library=" ^ fk_show_option Fun.id v.library ^ ", test=" ^ fk_show_option Fun.id v.test ^ ", marker=" ^ fk_show_option Fun.id v.marker ^ ", runner=" ^ fk_show_option Fun.id v.runner ^ ", fixtures=" ^ fk_show_option Fun.id v.fixtures ^ ", runnerTests=" ^ string_of_bool v.runner_tests ^ ", imports=" ^ fk_show_list Fun.id v.imports ^ ", symbols=" ^ fk_show_option Fun.id v.symbols ^ ")"

module Fckt = struct
  module Text = struct
