  module Lang = struct
    module type Applicative = sig
      type 'a m
      val map : 'a m -> ('a -> 'b) -> 'b m
      val product : 'a m -> 'b m -> ('a * 'b) m
    end

    module type Monad = sig
      type 'a m
      val pure : 'a -> 'a m
      val bind : 'a m -> ('a -> 'b m) -> 'b m
      val map : 'a m -> ('a -> 'b) -> 'b m
      val product : 'a m -> 'b m -> ('a * 'b) m
    end

    module Functions = struct

    end

    module Lazies = struct

    end

    module Options = struct
      let option_filter (this : _ option) (f : _ -> bool) : _ option =
        Option.bind this (fun it -> if f it then Some it else None)

      let option_or_else (this : _ option) (other : unit -> _ option) : _ option =
        match this with
        | Some _ -> this
        | None -> other ()
    end

    module Lists = struct
      let list_count (this : _ list) (f : _ -> bool) : int =
        List.length (List.filter f this)

      let list_is_not_empty (this : _ list) : bool =
        not (List.is_empty this)

      let list_last_or_none (this : _ list) : _ option =
        List.nth_opt (List.rev this) 0

      let list_get_or_none (this : _ list) (index : int) : _ option =
        if index < 0 then None else List.nth_opt (List.drop index this) 0

      let list_single_or_none (this : _ list) : _ option =
        match this with
        | [a] -> Some a
        | _ -> None

      let list_with_index (this : _ list) : (int * _) list =
        List.mapi (fun i a -> (i, a)) this

      let rec list_take_while (this : _ list) (f : _ -> bool) : _ list =
        match this with
        | a :: rest -> if f a then a :: list_take_while rest f else []
        | [] -> []

      let rec list_drop_while (this : _ list) (f : _ -> bool) : _ list =
        match this with
        | a :: rest -> if f a then list_drop_while rest f else this
        | [] -> []

      let rec list_index_of (this : _ list) (x : _) : int =
        match this with
        | a :: rest -> if a = x then 0 else (let i = list_index_of rest x in
               if i < 0 then (-1) else i + 1)
        | [] -> (-1)

      let rec list_zip (this : _ list) (other : _ list) : (_ * _) list =
        match (this, other) with
        | (a :: xs, b :: ys) -> (a, b) :: list_zip xs ys
        | _ -> []

      let list_distinct_by (this : _ list) (key : _ -> _) : _ list =
        let by_key = List.stable_sort (fun x y -> let (k, i, _) = x in
             let (l, j, _) = y in
             compare (k, i) (l, j)) (List.map (fun (i, a) -> (key a, i, a)) (list_with_index this)) in
        let firsts = List.fold_left (fun kept entry -> let (k, _, _) = entry in
             match kept with
             | (l, _, _) :: _ -> if k = l then kept else entry :: kept
             | [] -> [entry]) [] by_key in
        List.map (fun (_, _, a) -> a) (List.stable_sort (fun x y -> let (_, i, _) = x in
            let (_, j, _) = y in
            compare i j) firsts)

      let list_distinct (this : _ list) : _ list =
        list_distinct_by this (fun it -> it)

      let list_sorted (this : _ list) : _ list =
        List.stable_sort compare this

      let list_sorted_by (this : _ list) (key : _ -> _) : _ list =
        List.stable_sort (fun a b -> let fk_arg1 = key a in
           let fk_arg2 = key b in
           compare fk_arg1 fk_arg2) this

      let list_sorted_descending (this : _ list) : _ list =
        List.rev (list_sorted this)

      let list_none (this : _ list) (f : _ -> bool) : bool =
        not (List.exists f this)

      let list_filter_not (this : _ list) (f : _ -> bool) : _ list =
        List.filter (fun it -> not (f it)) this

      let list_map_not_null (this : _ list) (f : _ -> _ option) : _ list =
        List.concat_map (fun a -> match f a with
           | Some b -> [b]
           | None -> []) this

      let list_list_flatten (this : _ list list) : _ list =
        List.concat_map (fun it -> it) this

      let list_sum_of (this : _ list) (f : _ -> int) : int =
        List.fold_left ( + ) 0 (List.map f this)

      let list_take_last (this : _ list) (n : int) : _ list =
        List.drop (List.length this - n) this

      let list_drop_last (this : _ list) (n : int) : _ list =
        List.take (List.length this - n) this

      let rec list_index_of_first (this : _ list) (f : _ -> bool) : int =
        match this with
        | a :: rest -> if f a then 0 else (let i = list_index_of_first rest f in
               if i < 0 then (-1) else i + 1)
        | [] -> (-1)

      let list_partition (this : _ list) (f : _ -> bool) : _ list * _ list =
        let fk_arg1 = List.filter f this in
        let fk_arg2 = list_filter_not this f in
        (fk_arg1, fk_arg2)

      let rec list_chunked (this : _ list) (size : int) : _ list list =
        if List.is_empty this || size <= 0 then [] else (let fk_arg1 = List.take size this in
           let fk_arg2 = list_chunked (List.drop size this) size in
           fk_arg1 :: fk_arg2)

      let list_zip_with_next (this : _ list) : (_ * _) list =
        list_zip this (List.drop 1 this)

      let list_best_by (this : _ list) (key : _ -> _) (beats : _ -> _ -> bool) : _ option =
        match this with
        | [] -> None
        | a :: rest -> Option.map (fun (best, _) -> best) (Some (List.fold_left (fun best b -> let (_, best_key) = best in
                 let k = key b in
                 if beats k best_key then (b, k) else best) (a, key a) rest))

      let list_min_by_or_none (this : _ list) (key : _ -> _) : _ option =
        list_best_by this key (fun a b -> compare a b < 0)

      let list_min_or_none (this : _ list) : _ option =
        list_min_by_or_none this (fun it -> it)

      let list_max_by_or_none (this : _ list) (key : _ -> _) : _ option =
        list_best_by this key (fun a b -> compare a b > 0)

      let list_max_or_none (this : _ list) : _ option =
        list_max_by_or_none this (fun it -> it)

      let list_sorted_by_descending (this : _ list) (key : _ -> _) : _ list =
        List.stable_sort (fun a b -> let fk_arg1 = key b in
           let fk_arg2 = key a in
           compare fk_arg1 fk_arg2) this
    end

    module Maths = struct
      let int_range_to (this : int) (last : int) : int list =
        (fun from e -> List.init (max 0 (e - from)) (fun i -> from + i)) this (last + 1)

      let int_down_to (this : int) (last : int) : int list =
        List.rev (int_range_to last this)
    end

    module Strings = struct
      let rec string_reversed (this : string) : string =
        String.concat "" (List.map Fun.id (List.map (fun it -> fk_show_char it) (List.rev ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) this))))

      let string_is_not_empty (this : string) : bool =
        not (String.equal "" this)

      let rec char_range_to (this : int) (last : int) : int list =
        List.map (fun it -> (fun n -> Uchar.to_int (Uchar.of_int n)) it) (let fk_arg1 = Fun.id this in
         let fk_arg2 = Fun.id last in
         Maths.int_range_to fk_arg1 fk_arg2)

      let string_is_blank (this : string) : bool =
        String.equal "" (String.trim this)

      let string_substring (this : string) (start : int) (end_index : int) : string =
        (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in String.sub s 0 (at 0 n)) ((fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in String.sub s i (String.length s - i)) this start) (end_index - start)

      let string_drop_last (this : string) (n : int) : string =
        (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in String.sub s 0 (at 0 n)) this ((fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) this - n)

      let string_remove_prefix (this : string) (prefix : string) : string =
        if String.starts_with ~prefix:prefix this then (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in String.sub s i (String.length s - i)) this ((fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) prefix) else this

      let string_remove_suffix (this : string) (suffix : string) : string =
        if String.ends_with ~suffix:suffix this then string_drop_last this ((fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) suffix) else this

      let string_contains (this : string) (text : string) : bool =
        (fun s t -> let n = String.length s and m = String.length t in let rec find i = if i + m > n then -1 else if String.sub s i m = t then i else find (i + 1) in let rec count i k = if i >= k then 0 else 1 + count (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) k in let i = find 0 in if i < 0 then -1 else count 0 i) this text >= 0

      let string_substring_before_last (this : string) (delimiter : string) : string =
        let i = (fun s t -> let n = String.length s and m = String.length t in let rec find i = if i < 0 then -1 else if String.sub s i m = t then i else find (i - 1) in let rec count i k = if i >= k then 0 else 1 + count (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) k in let i = find (n - m) in if i < 0 then -1 else count 0 i) this delimiter in
        if i < 0 then this else (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in String.sub s 0 (at 0 n)) this i

      let string_substring_after_last (this : string) (delimiter : string) : string =
        let i = (fun s t -> let n = String.length s and m = String.length t in let rec find i = if i < 0 then -1 else if String.sub s i m = t then i else find (i - 1) in let rec count i k = if i >= k then 0 else 1 + count (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) k in let i = find (n - m) in if i < 0 then -1 else count 0 i) this delimiter in
        if i < 0 then this else (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in String.sub s i (String.length s - i)) this (i + (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) delimiter)

      let string_substring_before (this : string) (delimiter : string) : string =
        let i = (fun s t -> let n = String.length s and m = String.length t in let rec find i = if i + m > n then -1 else if String.sub s i m = t then i else find (i + 1) in let rec count i k = if i >= k then 0 else 1 + count (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) k in let i = find 0 in if i < 0 then -1 else count 0 i) this delimiter in
        if i < 0 then this else (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in String.sub s 0 (at 0 n)) this i

      let string_substring_after (this : string) (delimiter : string) : string =
        let i = (fun s t -> let n = String.length s and m = String.length t in let rec find i = if i + m > n then -1 else if String.sub s i m = t then i else find (i + 1) in let rec count i k = if i >= k then 0 else 1 + count (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) k in let i = find 0 in if i < 0 then -1 else count 0 i) this delimiter in
        if i < 0 then this else (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in String.sub s i (String.length s - i)) this (i + (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) delimiter)

      let string_is_not_blank (this : string) : bool =
        not (string_is_blank this)

      let string_replace (this : string) (old : string) (new_ : string) : string =
        String.concat new_ (List.map Fun.id ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) this old))

      let string_lines (this : string) : string list =
        List.map (fun it -> string_remove_suffix it "\r") ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) this "\n")

      let rec string_repeat (this : string) (n : int) : string =
        if n <= 0 then "" else this ^ string_repeat this (n - 1)

      let char_is_whitespace (this : int) : bool =
        (((((this = 32 || this = 9) || this = 10) || this = 13) || Fun.id this = 160) || Fun.id this = 8232) || Fun.id this = 8233

      let string_trim_start (this : string) : string =
        (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in String.sub s i (String.length s - i)) this (List.length (Lists.list_take_while ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) this) (fun it -> char_is_whitespace it)))

      let string_trim_end (this : string) : string =
        string_drop_last this (List.length (Lists.list_take_while (List.rev ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) this)) (fun it -> char_is_whitespace it)))

      let string_pad_start (this : string) (length : int) (padding : int) : string =
        string_repeat (fk_show_char padding) (length - (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) this) ^ this

      let string_pad_start_default_padding () : int =
        32

      let string_pad_end (this : string) (length : int) (padding : int) : string =
        this ^ string_repeat (fk_show_char padding) (length - (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) this)

      let string_pad_end_default_padding () : int =
        32

      let char_is_digit (this : int) : bool =
        this >= 48 && this <= 57

      let letters =
        [(170, 170); (181, 181); (186, 186); (192, 214); (216, 246); (248, 705); (710, 721); (736, 740); (748, 748); (750, 750); (880, 884); (886, 887); (890, 893); (895, 895); (902, 902); (904, 906); (908, 908); (910, 929); (931, 1013); (1015, 1153); (1162, 1327); (1329, 1366); (1376, 1416); (1488, 1514); (1519, 1522); (1568, 1610); (1646, 1647); (1649, 1747); (1749, 1749); (1765, 1766); (1774, 1775); (1786, 1788); (1791, 1791); (2308, 2361); (2365, 2365); (2384, 2384); (2392, 2401); (2417, 2432); (3585, 3632); (3634, 3635); (3648, 3654); (4256, 4293); (4304, 4346); (4348, 4351); (4352, 4607); (7680, 7957); (7960, 7965); (7968, 8005); (8008, 8013); (8016, 8023); (8025, 8025); (8027, 8027); (8029, 8029); (8031, 8061); (8064, 8116); (8118, 8124); (8126, 8126); (8130, 8132); (8134, 8140); (8144, 8147); (8150, 8155); (8160, 8172); (8178, 8180); (8182, 8188); (8305, 8305); (8319, 8319); (8336, 8348); (11264, 11492); (12353, 12438); (12445, 12447); (12449, 12538); (12540, 12543); (12549, 12591); (12593, 12686); (13312, 19903); (19968, 40959); (40960, 42124); (44032, 55203); (63744, 64255); (64256, 64262); (65313, 65338); (65345, 65370); (65382, 65500); (131072, 195103)]

      let char_is_letter (this : int) : bool =
        (this >= 97 && this <= 122 || this >= 65 && this <= 90) || Fun.id this > 127 && List.exists (fun (from, to_) -> Fun.id this >= from && Fun.id this <= to_) letters

      let char_is_letter_or_digit (this : int) : bool =
        char_is_letter this || char_is_digit this

      let char_uppercase (this : int) : int =
        if this >= 97 && this <= 122 then (fun n -> Uchar.to_int (Uchar.of_int n)) (Fun.id this - 32) else this

      let char_lowercase (this : int) : int =
        if this >= 65 && this <= 90 then (fun n -> Uchar.to_int (Uchar.of_int n)) (Fun.id this + 32) else this

      let char_is_upper_case (this : int) : bool =
        this >= 65 && this <= 90

      let char_is_lower_case (this : int) : bool =
        this >= 97 && this <= 122
    end

    module Results = struct
      let rec list_fold_result (this : _ list) (initial : _) (f : _ -> _ -> (_, _) result) : (_, _) result =
        match this with
        | [] -> Ok initial
        | a :: rest -> match f initial a with
            | Ok b -> list_fold_result rest b f
            | Error e -> Error e

      let list_map_result (this : _ list) (f : _ -> (_, _) result) : (_ list, _) result =
        Result.map (fun it -> List.rev it) (list_fold_result this [] (fun done_ a -> Result.map (fun it -> it :: done_) (f a)))
    end
  end

  module Collections = struct
    type 'a stream =
      | End
      | Next of { value : 'a; rest : 'a stream Lazy.t }

    let rec show_stream show_a (v : 'a stream) =
      match v with
      | End -> "End"
      | Next r -> "Next(" ^ "value=" ^ show_a r.value ^ ", rest=" ^ (fun _ -> "Lazy(...)") r.rest ^ ")"

    module Arrays = struct

    end

    module Maps = struct
      type ('k, 'v) map =
        | MapTip
        | MapNode of { left : ('k, 'v) map; key : 'k; value : 'v; right : ('k, 'v) map; size : int; priority : int }

      let map_size (this : (_, _) map) : int =
        match this with
        | MapTip -> 0
        | MapNode { left = _; key = _; value = _; right = _; size = n; priority = _ } -> n

      let above (p : int) (a : _) (q : int) (b : _) : bool =
        p > q || p = q && compare a b < 0

      let node (left : (_, _) map) (key : _) (value : _) (right : (_, _) map) : (_, _) map =
        let fk_arg1 = let fk_arg1 = map_size left + 1 in
          let fk_arg2 = map_size right in
          fk_arg1 + fk_arg2 in
        let fk_arg2 = Hashtbl.hash key in
        (MapNode { left = left; key = key; value = value; right = right; size = fk_arg1; priority = fk_arg2 } : (_, _) map)

      let rec map_put (this : (_, _) map) (key : _) (value : _) : (_, _) map =
        match this with
        | MapTip -> node (MapTip : (_, _) map) key value (MapTip : (_, _) map)
        | MapNode { left = l; key = k; value = v; right = r; size = _; priority = p } -> let c = compare key k in
            if c = 0 then node l k value r else if c < 0 then (let put = map_put l key value in
                 match put with
                 | MapNode { left = ll; key = lk; value = lv; right = lr; size = _; priority = lp } -> if above lp lk p k then node ll lk lv (node lr k v r) else node put k v r
                 | MapTip -> this) else (let put = map_put r key value in
                 match put with
                 | MapNode { left = rl; key = rk; value = rv; right = rr; size = _; priority = rp } -> if above rp rk p k then node (node l k v rl) rk rv rr else node l k v put
                 | MapTip -> this)

      let empty_map () : (_, _) map =
        (MapTip : (_, _) map)

      let map_of (entries : (_ * _) list) : (_, _) map =
        List.fold_left (fun m entry -> let (k, v) = entry in
           map_put m k v) (empty_map ()) entries

      let list_tuple_to_map (this : (_ * _) list) : (_, _) map =
        map_of this

      let map_is_empty (this : (_, _) map) : bool =
        map_size this = 0

      let map_is_not_empty (this : (_, _) map) : bool =
        map_size this > 0

      let rec map_get (this : (_, _) map) (key : _) : _ option =
        match this with
        | MapTip -> None
        | MapNode { left = l; key = k; value = v; right = r; size = _; priority = _ } -> let c = compare key k in
            if c < 0 then map_get l key else if c > 0 then map_get r key else Some v

      let map_get_or_else (this : (_, _) map) (key : _) (default : unit -> _) : _ =
        match map_get this key with
        | Some v -> v
        | None -> default ()

      let map_get_or_default (this : (_, _) map) (key : _) (default : _) : _ =
        map_get_or_else this key (fun () -> default)

      let map_contains_key (this : (_, _) map) (key : _) : bool =
        map_get this key <> None

      let rec map_split (this : (_, _) map) (key : _) : (_, _) map * _ option * (_, _) map =
        match this with
        | MapTip -> ((MapTip : (_, _) map), None, (MapTip : (_, _) map))
        | MapNode { left = l; key = k; value = v; right = r; size = _; priority = _ } -> let c = compare key k in
            if c = 0 then (l, Some v, r) else if c < 0 then (let (below, found, beyond) = map_split l key in
                 (below, found, node beyond k v r)) else (let (below, found, beyond) = map_split r key in
                 (node l k v below, found, beyond))

      let rec map_put_all (this : (_, _) map) (other : (_, _) map) : (_, _) map =
        match (this, other) with
        | (MapTip, _) -> other
        | (_, MapTip) -> this
        | (MapNode { left = l; key = k; value = v; right = r; size = _; priority = p }, MapNode { left = ol; key = ok; value = ov; right = orr; size = _; priority = op }) -> if above p k op ok then (let (below, found, beyond) = map_split other k in
               let fk_arg1 = map_put_all l below in
               let fk_arg2 = Option.value found ~default:v in
               let fk_arg3 = map_put_all r beyond in
               node fk_arg1 k fk_arg2 fk_arg3) else (let (below, _, beyond) = map_split this ok in
               let fk_arg1 = map_put_all below ol in
               let fk_arg2 = map_put_all beyond orr in
               node fk_arg1 ok ov fk_arg2)

      let rec joined (left : (_, _) map) (right : (_, _) map) : (_, _) map =
        match (left, right) with
        | (MapTip, _) -> right
        | (_, MapTip) -> left
        | (MapNode { left = ll; key = lk; value = lv; right = lr; size = _; priority = lp }, MapNode { left = rl; key = rk; value = rv; right = rr; size = _; priority = rp }) -> if above lp lk rp rk then node ll lk lv (joined lr right) else node (joined left rl) rk rv rr

      let rec map_intersect_keys (this : (_, _) map) (other : (_, _) map) : (_, _) map =
        match (this, other) with
        | (MapTip, _) -> (MapTip : (_, _) map)
        | (_, MapTip) -> (MapTip : (_, _) map)
        | (MapNode { left = l; key = k; value = v; right = r; size = _; priority = _ }, _) -> let (below, found, beyond) = map_split other k in
            let left = map_intersect_keys l below in
            let right = map_intersect_keys r beyond in
            if Option.is_some found then node left k v right else joined left right

      let rec map_subtract_keys (this : (_, _) map) (other : (_, _) map) : (_, _) map =
        match (this, other) with
        | (MapTip, _) -> (MapTip : (_, _) map)
        | (_, MapTip) -> this
        | (_, MapNode { left = ol; key = ok; value = _; right = orr; size = _; priority = _ }) -> let (below, _, beyond) = map_split this ok in
            let fk_arg1 = map_subtract_keys below ol in
            let fk_arg2 = map_subtract_keys beyond orr in
            joined fk_arg1 fk_arg2

      let rec map_remove (this : (_, _) map) (key : _) : (_, _) map =
        match this with
        | MapTip -> this
        | MapNode { left = l; key = k; value = v; right = r; size = _; priority = _ } -> let c = compare key k in
            if c < 0 then node (map_remove l key) k v r else if c > 0 then node l k v (map_remove r key) else joined l r

      let rec map_fold_right (this : (_, _) map) (initial : _) (f : _ -> _ -> _ -> _) : _ =
        match this with
        | MapTip -> initial
        | MapNode { left = l; key = k; value = v; right = r; size = _; priority = _ } -> map_fold_right l (f k v (map_fold_right r initial f)) f

      let map_entries (this : (_, _) map) : (_ * _) list =
        map_fold_right this [] (fun k v rest -> (k, v) :: rest)

      let map_keys (this : (_, _) map) : _ list =
        map_fold_right this [] (fun k _ rest -> k :: rest)

      let map_values (this : (_, _) map) : _ list =
        map_fold_right this [] (fun _ v rest -> v :: rest)

      let map_to_list (this : (_, _) map) : (_ * _) list =
        map_entries this

      let rec map_for_each (this : (_, _) map) (f : _ -> _ -> unit) : unit =
        match this with
        | MapTip -> ()
        | MapNode { left = l; key = k; value = v; right = r; size = _; priority = _ } -> map_for_each l f;
            f k v;
            map_for_each r f

      let rec map_any (this : (_, _) map) (f : _ -> _ -> bool) : bool =
        match this with
        | MapTip -> false
        | MapNode { left = l; key = k; value = v; right = r; size = _; priority = _ } -> (map_any l f || f k v) || map_any r f

      let map_all (this : (_, _) map) (f : _ -> _ -> bool) : bool =
        not (map_any this (fun k v -> not (f k v)))

      let rec map_count (this : (_, _) map) (f : _ -> _ -> bool) : int =
        match this with
        | MapTip -> 0
        | MapNode { left = l; key = k; value = v; right = r; size = _; priority = _ } -> let before = map_count l f in
            let here = if f k v then 1 else 0 in
            before + here + map_count r f

      let rec map_filter (this : (_, _) map) (f : _ -> _ -> bool) : (_, _) map =
        match this with
        | MapTip -> (MapTip : (_, _) map)
        | MapNode { left = l; key = k; value = v; right = r; size = _; priority = _ } -> let left = map_filter l f in
            let keep = f k v in
            let right = map_filter r f in
            if keep then node left k v right else joined left right

      let map_filter_keys (this : (_, _) map) (f : _ -> bool) : (_, _) map =
        map_filter this (fun k _ -> f k)

      let map_filter_values (this : (_, _) map) (f : _ -> bool) : (_, _) map =
        map_filter this (fun _ v -> f v)

      let rec map_map_values (this : (_, _) map) (f : _ -> _ -> _) : (_, _) map =
        match this with
        | MapTip -> (MapTip : (_, _) map)
        | MapNode { left = l; key = k; value = v; right = r; size = n; priority = p } -> let fk_arg1 = map_map_values l f in
            let fk_arg2 = f k v in
            let fk_arg3 = map_map_values r f in
            (MapNode { left = fk_arg1; key = k; value = fk_arg2; right = fk_arg3; size = n; priority = p } : (_, _) map)

      let rec map_map (this : (_, _) map) (f : _ -> _ -> _) : _ list =
        List.map (fun (k, v) -> f k v) (map_entries this)

      let map_map_keys (this : (_, _) map) (f : _ -> _ -> _) : (_, _) map =
        list_tuple_to_map (List.map (fun (k, v) -> (f k v, v)) (map_entries this))

      let map_to_string (this : (_, _) map) (show_key : _ -> string) (show_value : _ -> string) : string =
        ("{" ^ String.concat ", " (List.map Fun.id (map_map this (fun k v -> let fk_arg1 = show_key k ^ "=" in
              let fk_arg2 = show_value v in
              fk_arg1 ^ fk_arg2)))) ^ "}"

      let list_group_by (this : _ list) (key : _ -> _) : (_, _ list) map =
        let fk_arg1 = List.rev this in
        let fk_arg2 = empty_map () in
        List.fold_left (fun m a -> let fk_arg1 = key a in
           let fk_arg2 = a :: map_get_or_else m (key a) (fun () -> []) in
           map_put m fk_arg1 fk_arg2) fk_arg2 fk_arg1

      let list_associate_by (this : _ list) (key : _ -> _) : (_, _) map =
        list_tuple_to_map (List.map (fun it -> (key it, it)) this)

      let list_associate_with (this : _ list) (value : _ -> _) : (_, _) map =
        list_tuple_to_map (List.map (fun it -> (it, value it)) this)

      let list_associate (this : _ list) (entry : _ -> _ * _) : (_, _) map =
        list_tuple_to_map (List.map entry this)
    end

    module Sets = struct
      type 'a set = { items : ('a, unit) Maps.map }

      let rec set_size (this : _ set) : int =
        Maps.map_size (this : _ set).items

      let set_plus (this : _ set) (item : _) : _ set =
        ({ items = Maps.map_put (this : _ set).items item () } : _ set)

      let rec set_for_each (this : _ set) (f : _ -> unit) : unit =
        Maps.map_for_each (this : _ set).items (fun a _ -> f a)

      let rec set_any (this : _ set) (f : _ -> bool) : bool =
        Maps.map_any (this : _ set).items (fun a _ -> f a)

      let rec set_count (this : _ set) (f : _ -> bool) : int =
        Maps.map_count (this : _ set).items (fun a _ -> f a)

      let set_filter (this : _ set) (f : _ -> bool) : _ set =
        ({ items = Maps.map_filter_keys (this : _ set).items f } : _ set)

      let set_to_list (this : _ set) : _ list =
        Maps.map_keys (this : _ set).items

      let rec set_map (this : _ set) (f : _ -> _) : _ list =
        List.map f (set_to_list this)

      let empty_set () : _ set =
        ({ items = Maps.empty_map () } : _ set)

      let set_of (items : _ list) : _ set =
        ({ items = Maps.list_tuple_to_map (List.map (fun it -> (it, ())) items) } : _ set)

      let list_to_set (this : _ list) : _ set =
        set_of this

      let rec set_is_empty (this : _ set) : bool =
        Maps.map_is_empty (this : _ set).items

      let rec set_is_not_empty (this : _ set) : bool =
        Maps.map_is_not_empty (this : _ set).items

      let set_contains (this : _ set) (item : _) : bool =
        Maps.map_contains_key (this : _ set).items item

      let set_minus (this : _ set) (item : _) : _ set =
        ({ items = Maps.map_remove (this : _ set).items item } : _ set)

      let set_union (this : _ set) (other : _ set) : _ set =
        ({ items = Maps.map_put_all (this : _ set).items (other : _ set).items } : _ set)

      let set_intersect (this : _ set) (other : _ set) : _ set =
        ({ items = Maps.map_intersect_keys (this : _ set).items (other : _ set).items } : _ set)

      let set_subtract (this : _ set) (other : _ set) : _ set =
        ({ items = Maps.map_subtract_keys (this : _ set).items (other : _ set).items } : _ set)

      let rec set_all (this : _ set) (f : _ -> bool) : bool =
        Maps.map_all (this : _ set).items (fun a _ -> f a)

      let set_to_string (this : _ set) (show_a : _ -> string) : string =
        ("[" ^ String.concat ", " (List.map Fun.id (List.map show_a (set_to_list this)))) ^ "]"
    end

    module Streams = struct
      let rec stream_take (this : _ stream) (n : int) : _ list =
        match this with
        | End -> []
        | Next { value = a; rest = rest } -> if n <= 0 then [] else if n = 1 then [a] else a :: stream_take (Lazy.force rest) (n - 1)
    end
  end

  module Effects = struct
    type _ Effect.t +=
      | Fail_fail : string -> fk_nothing Effect.t

    type 'fk_answer fail_handler = { fail : string -> (fk_nothing -> 'fk_answer) -> 'fk_answer }

    let handle_fail (h : 'fk_answer fail_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (Fail_fail x0), k -> h.fail x0 (fun v -> Effect.Deep.continue k v)

    type _ Effect.t +=
      | Yielding_yield : 'a -> unit Effect.t

    type ('a, 'fk_answer) yielding_handler = { yield : 'a -> (unit -> 'fk_answer) -> 'fk_answer }

    let handle_yielding (h : ('a, 'fk_answer) yielding_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (Yielding_yield x0), k -> h.yield (Obj.magic x0) (fun v -> Effect.Deep.continue k (Obj.magic v))

    module Failure = struct
      let attempt (block : unit -> _) : (_, string) result =
        handle_fail ({ fail = (fun reason _ -> Error reason) } : _ fail_handler) (fun () -> Ok (block ()))

      module Crash = struct
        let fail (reason : string) : fk_nothing =
          match (fun r -> prerr_endline r; exit 1) reason with
          | _ -> (assert false)
      end
    end

    module Generators = struct
      let sequence (block : unit -> unit) : _ Collections.stream =
        handle_yielding ({ yield = (fun a resume -> (Collections.Next { value = a; rest = Lazy.from_fun (fun () -> resume ()) } : _ Collections.stream)) } : (_, _) yielding_handler) (fun () -> block ();
           (Collections.End : _ Collections.stream))
    end
  end

  module Time = struct
    type duration = { millis : int }

    let rec show_duration (v : duration) =
      "Duration(" ^ "millis=" ^ string_of_int v.millis ^ ")"

    type instant = { millis : int }

    let rec show_instant (v : instant) =
      "Instant(" ^ "millis=" ^ string_of_int v.millis ^ ")"

    type _ Effect.t +=
      | Clock_now : unit -> instant Effect.t

    type 'fk_answer clock_handler = { now : (instant -> 'fk_answer) -> 'fk_answer }

    let handle_clock (h : 'fk_answer clock_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (Clock_now ()), k -> h.now (fun v -> Effect.Deep.continue k v)

    module Times = struct
      let rec instant_plus (this : instant) (d : duration) : instant =
        ({ millis = (this : instant).millis + (d : duration).millis } : instant)
      and duration_plus (this : duration) (other : duration) : duration =
        ({ millis = (this : duration).millis + (other : duration).millis } : duration)

      let instant_until (this : instant) (later : instant) : duration =
        ({ millis = (later : instant).millis - (this : instant).millis } : duration)
    end

    module SystemClock = struct
      let now () : instant =
        ({ millis = (fun _ -> int_of_float (Unix.gettimeofday () *. 1000.)) () } : instant)
    end
  end

  module Concurrent = struct
    type task = { id : int }

    let rec show_task (v : task) =
      "Task(" ^ "id=" ^ string_of_int v.id ^ ")"

    type waker = { id : int }

    let rec show_waker (v : waker) =
      "Waker(" ^ "id=" ^ string_of_int v.id ^ ")"

    module type Executor = sig
      val run : (unit -> waker list) -> (unit -> 'a) -> 'a
    end

    type _ Effect.t +=
      | Concurrent_launch : (unit -> unit) -> task Effect.t
      | Concurrent_join : task -> unit Effect.t
      | Concurrent_pause : unit -> unit Effect.t
      | Concurrent_park : (waker -> unit) -> unit Effect.t
      | Concurrent_wake : waker -> unit Effect.t

    type 'fk_answer concurrent_handler = { launch : (unit -> unit) -> (task -> 'fk_answer) -> 'fk_answer; join : task -> (unit -> 'fk_answer) -> 'fk_answer; pause : (unit -> 'fk_answer) -> 'fk_answer; park : (waker -> unit) -> (unit -> 'fk_answer) -> 'fk_answer; wake : waker -> (unit -> 'fk_answer) -> 'fk_answer }

    let handle_concurrent (h : 'fk_answer concurrent_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (Concurrent_launch x0), k -> h.launch x0 (fun v -> Effect.Deep.continue k v)
      | effect (Concurrent_join x0), k -> h.join x0 (fun v -> Effect.Deep.continue k v)
      | effect (Concurrent_pause ()), k -> h.pause (fun v -> Effect.Deep.continue k v)
      | effect (Concurrent_park x0), k -> h.park x0 (fun v -> Effect.Deep.continue k v)
      | effect (Concurrent_wake x0), k -> h.wake x0 (fun v -> Effect.Deep.continue k v)

    module InTurn = struct
      type run = { mutable ready : (unit -> unit) list; mutable parked : (int, unit -> unit) Collections.Maps.map; mutable joining : (int, (unit -> unit) list) Collections.Maps.map; mutable ended : int list; mutable next : int }

      let rec show_run (v : run) =
        "Run(" ^ "ready=" ^ fk_show_list (fun _ -> "<fun>") v.ready ^ ", parked=" ^ (fun v -> Collections.Maps.map_to_string v string_of_int (fun _ -> "<fun>")) v.parked ^ ", joining=" ^ (fun v -> Collections.Maps.map_to_string v string_of_int (fk_show_list (fun _ -> "<fun>"))) v.joining ^ ", ended=" ^ fk_show_list string_of_int v.ended ^ ", next=" ^ string_of_int v.next ^ ")"

      let woken (state : run) (waker : waker) : unit =
        match Collections.Maps.map_get (state : run).parked (waker : waker).id with
        | Some carry_on -> state.parked <- Collections.Maps.map_remove (state : run).parked (waker : waker).id;
            state.ready <- (state : run).ready @ [carry_on]
        | None -> ()

      let rec loop (state : run) (idle : unit -> waker list) : unit =
        match (state : run).ready with
        | next :: rest -> state.ready <- rest;
            next ();
            loop state idle
        | [] -> if Collections.Maps.map_size (state : run).parked > 0 then (let came = idle () in
               if List.is_empty came then (match Effect.perform (Effects.Fail_fail "every task is waiting, for what nothing will bring") with
                  | _ -> (assert false)) else ();
               List.iter (fun it -> woken state it) came;
               loop state idle) else if Collections.Maps.map_size (state : run).joining > 0 then (match Effect.perform (Effects.Fail_fail "every task is waiting, for one that's waiting too") with
                 | _ -> (assert false)) else ()

      let rec task (state : run) (id : int) (work : unit -> unit) : unit =
        handle_concurrent ({ launch = (fun launched resume -> let next = (state : run).next in
           state.next <- next + 1;
           state.ready <- (state : run).ready @ [(fun () -> task state next launched)];
           resume ({ id = next } : task)); join = (fun joined resume -> if List.mem (joined : task).id (state : run).ended then resume () else state.joining <- Collections.Maps.map_put (state : run).joining (joined : task).id (Option.value (Collections.Maps.map_get (state : run).joining (joined : task).id) ~default:[] @ [(fun () -> resume ())])); pause = (fun resume -> state.ready <- (state : run).ready @ [(fun () -> resume ())]); park = (fun register resume -> let next = (state : run).next in
           state.next <- next + 1;
           state.parked <- Collections.Maps.map_put (state : run).parked next (fun () -> resume ());
           register ({ id = next } : waker)); wake = (fun waker resume -> woken state waker;
           resume ()) } : _ concurrent_handler) (fun () -> work ();
           state.ended <- (state : run).ended @ [id];
           state.ready <- (state : run).ready @ Option.value (Collections.Maps.map_get (state : run).joining id) ~default:[];
           state.joining <- Collections.Maps.map_remove (state : run).joining id)

      let run (idle : unit -> waker list) (block : unit -> _) : _ =
        let state = let fk_arg1 = Collections.Maps.empty_map () in
          let fk_arg2 = Collections.Maps.empty_map () in
          ({ ready = []; parked = fk_arg1; joining = fk_arg2; ended = []; next = 1 } : run) in
        let result = ref None in
        task state 0 (fun () -> result := Some (block ());
           ());
        loop state (fun () -> idle ());
        match ! result with
        | Some value -> value
        | None -> match Effect.perform (Effects.Fail_fail "the block's task never ended") with
            | _ -> (assert false)
    end

    let executor_run_default_idle () : unit -> waker list =
      fun () -> []
  end

  module Io = struct
    type 'a exit = { code : int; value : 'a }

    let rec show_exit show_a (v : 'a exit) =
      "Exit(" ^ "code=" ^ string_of_int v.code ^ ", value=" ^ show_a v.value ^ ")"

    type path = { value : string }

    let rec show_path (v : path) =
      "Path(" ^ "value=" ^ Fun.id v.value ^ ")"

    type _ Effect.t +=
      | Channel_readLineFrom : (in_channel) -> string option Effect.t
      | Channel_readFrom : (in_channel) * int -> (string) Effect.t
      | Channel_writeTo : (out_channel) * (string) -> unit Effect.t
      | Channel_closeInput : (in_channel) -> unit Effect.t
      | Channel_closeOutput : (out_channel) -> unit Effect.t

    type 'fk_answer channel_handler = { read_line_from : (in_channel) -> (string option -> 'fk_answer) -> 'fk_answer; read_from : (in_channel) -> int -> ((string) -> 'fk_answer) -> 'fk_answer; write_to : (out_channel) -> (string) -> (unit -> 'fk_answer) -> 'fk_answer; close_input : (in_channel) -> (unit -> 'fk_answer) -> 'fk_answer; close_output : (out_channel) -> (unit -> 'fk_answer) -> 'fk_answer }

    let handle_channel (h : 'fk_answer channel_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (Channel_readLineFrom x0), k -> h.read_line_from x0 (fun v -> Effect.Deep.continue k v)
      | effect (Channel_readFrom (x0, x1)), k -> h.read_from x0 x1 (fun v -> Effect.Deep.continue k v)
      | effect (Channel_writeTo (x0, x1)), k -> h.write_to x0 x1 (fun v -> Effect.Deep.continue k v)
      | effect (Channel_closeInput x0), k -> h.close_input x0 (fun v -> Effect.Deep.continue k v)
      | effect (Channel_closeOutput x0), k -> h.close_output x0 (fun v -> Effect.Deep.continue k v)

    type _ Effect.t +=
      | Console_print : string -> unit Effect.t
      | Console_println : string -> unit Effect.t
      | Console_readLine : unit -> string Effect.t

    type 'fk_answer console_handler = { print : string -> (unit -> 'fk_answer) -> 'fk_answer; println : string -> (unit -> 'fk_answer) -> 'fk_answer; read_line : (string -> 'fk_answer) -> 'fk_answer }

    let handle_console (h : 'fk_answer console_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (Console_print x0), k -> h.print x0 (fun v -> Effect.Deep.continue k v)
      | effect (Console_println x0), k -> h.println x0 (fun v -> Effect.Deep.continue k v)
      | effect (Console_readLine ()), k -> h.read_line (fun v -> Effect.Deep.continue k v)

    type _ Effect.t +=
      | FileSystem_tryReadBytes : path -> ((string), string) result Effect.t
      | FileSystem_tryWriteBytes : path * (string) * bool -> (unit, string) result Effect.t
      | FileSystem_tryCopy : path * path -> (unit, string) result Effect.t
      | FileSystem_exists : path -> bool Effect.t
      | FileSystem_isDirectory : path -> bool Effect.t
      | FileSystem_tryListFiles : path -> (path list, string) result Effect.t
      | FileSystem_tryMakeDirs : path -> (unit, string) result Effect.t
      | FileSystem_tryDelete : path -> (unit, string) result Effect.t
      | FileSystem_tryOpenForReading : path -> ((in_channel), string) result Effect.t
      | FileSystem_tryOpenForWriting : path * bool -> ((out_channel), string) result Effect.t
      | FileSystem_tryLastModified : path -> (Time.instant, string) result Effect.t
      | FileSystem_tryCanonical : path -> (path, string) result Effect.t
      | FileSystem_workingDirectory : unit -> path Effect.t
      | FileSystem_tryChangeDirectory : path -> (unit, string) result Effect.t

    type 'fk_answer file_system_handler = { try_read_bytes : path -> (((string), string) result -> 'fk_answer) -> 'fk_answer; try_write_bytes : path -> (string) -> bool -> ((unit, string) result -> 'fk_answer) -> 'fk_answer; try_copy : path -> path -> ((unit, string) result -> 'fk_answer) -> 'fk_answer; exists : path -> (bool -> 'fk_answer) -> 'fk_answer; is_directory : path -> (bool -> 'fk_answer) -> 'fk_answer; try_list_files : path -> ((path list, string) result -> 'fk_answer) -> 'fk_answer; try_make_dirs : path -> ((unit, string) result -> 'fk_answer) -> 'fk_answer; try_delete : path -> ((unit, string) result -> 'fk_answer) -> 'fk_answer; try_open_for_reading : path -> (((in_channel), string) result -> 'fk_answer) -> 'fk_answer; try_open_for_writing : path -> bool -> (((out_channel), string) result -> 'fk_answer) -> 'fk_answer; try_last_modified : path -> ((Time.instant, string) result -> 'fk_answer) -> 'fk_answer; try_canonical : path -> ((path, string) result -> 'fk_answer) -> 'fk_answer; working_directory : (path -> 'fk_answer) -> 'fk_answer; try_change_directory : path -> ((unit, string) result -> 'fk_answer) -> 'fk_answer }

    let handle_file_system (h : 'fk_answer file_system_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (FileSystem_tryReadBytes x0), k -> h.try_read_bytes x0 (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_tryWriteBytes (x0, x1, x2)), k -> h.try_write_bytes x0 x1 x2 (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_tryCopy (x0, x1)), k -> h.try_copy x0 x1 (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_exists x0), k -> h.exists x0 (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_isDirectory x0), k -> h.is_directory x0 (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_tryListFiles x0), k -> h.try_list_files x0 (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_tryMakeDirs x0), k -> h.try_make_dirs x0 (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_tryDelete x0), k -> h.try_delete x0 (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_tryOpenForReading x0), k -> h.try_open_for_reading x0 (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_tryOpenForWriting (x0, x1)), k -> h.try_open_for_writing x0 x1 (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_tryLastModified x0), k -> h.try_last_modified x0 (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_tryCanonical x0), k -> h.try_canonical x0 (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_workingDirectory ()), k -> h.working_directory (fun v -> Effect.Deep.continue k v)
      | effect (FileSystem_tryChangeDirectory x0), k -> h.try_change_directory x0 (fun v -> Effect.Deep.continue k v)

    type _ Effect.t +=
      | Polling_whenReadable : (Unix.file_descr) * Concurrent.waker -> unit Effect.t
      | Polling_whenWritable : (Unix.file_descr) * Concurrent.waker -> unit Effect.t
      | Polling_whenPast : Time.instant * Concurrent.waker -> unit Effect.t
      | Polling_waitForAny : unit -> Concurrent.waker list Effect.t

    type 'fk_answer polling_handler = { when_readable : (Unix.file_descr) -> Concurrent.waker -> (unit -> 'fk_answer) -> 'fk_answer; when_writable : (Unix.file_descr) -> Concurrent.waker -> (unit -> 'fk_answer) -> 'fk_answer; when_past : Time.instant -> Concurrent.waker -> (unit -> 'fk_answer) -> 'fk_answer; wait_for_any : (Concurrent.waker list -> 'fk_answer) -> 'fk_answer }

    let handle_polling (h : 'fk_answer polling_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (Polling_whenReadable (x0, x1)), k -> h.when_readable x0 x1 (fun v -> Effect.Deep.continue k v)
      | effect (Polling_whenWritable (x0, x1)), k -> h.when_writable x0 x1 (fun v -> Effect.Deep.continue k v)
      | effect (Polling_whenPast (x0, x1)), k -> h.when_past x0 x1 (fun v -> Effect.Deep.continue k v)
      | effect (Polling_waitForAny ()), k -> h.wait_for_any (fun v -> Effect.Deep.continue k v)

    type _ Effect.t +=
      | Process_tryStart : string * string list -> ((in_channel), string) result Effect.t
      | Process_waitFor : (in_channel) -> int Effect.t
      | Process_runAttached : string * string list -> int Effect.t
      | Process_env : string -> string option Effect.t
      | Process_setEnv : string * string -> unit Effect.t
      | Process_executable : unit -> path Effect.t
      | Process_exit : int -> fk_nothing Effect.t

    type 'fk_answer process_handler = { try_start : string -> string list -> (((in_channel), string) result -> 'fk_answer) -> 'fk_answer; wait_for : (in_channel) -> (int -> 'fk_answer) -> 'fk_answer; run_attached : string -> string list -> (int -> 'fk_answer) -> 'fk_answer; env : string -> (string option -> 'fk_answer) -> 'fk_answer; set_env : string -> string -> (unit -> 'fk_answer) -> 'fk_answer; executable : (path -> 'fk_answer) -> 'fk_answer; exit : int -> (fk_nothing -> 'fk_answer) -> 'fk_answer }

    let handle_process (h : 'fk_answer process_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (Process_tryStart (x0, x1)), k -> h.try_start x0 x1 (fun v -> Effect.Deep.continue k v)
      | effect (Process_waitFor x0), k -> h.wait_for x0 (fun v -> Effect.Deep.continue k v)
      | effect (Process_runAttached (x0, x1)), k -> h.run_attached x0 x1 (fun v -> Effect.Deep.continue k v)
      | effect (Process_env x0), k -> h.env x0 (fun v -> Effect.Deep.continue k v)
      | effect (Process_setEnv (x0, x1)), k -> h.set_env x0 x1 (fun v -> Effect.Deep.continue k v)
      | effect (Process_executable ()), k -> h.executable (fun v -> Effect.Deep.continue k v)
      | effect (Process_exit x0), k -> h.exit x0 (fun v -> Effect.Deep.continue k v)

    type _ Effect.t +=
      | Reader_nextLine : unit -> string option Effect.t
      | Reader_nextBytes : int -> (string) Effect.t

    type 'fk_answer reader_handler = { next_line : (string option -> 'fk_answer) -> 'fk_answer; next_bytes : int -> ((string) -> 'fk_answer) -> 'fk_answer }

    let handle_reader (h : 'fk_answer reader_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (Reader_nextLine ()), k -> h.next_line (fun v -> Effect.Deep.continue k v)
      | effect (Reader_nextBytes x0), k -> h.next_bytes x0 (fun v -> Effect.Deep.continue k v)

    type _ Effect.t +=
      | Writer_write : string -> unit Effect.t
      | Writer_writeBytes : (string) -> unit Effect.t

    type 'fk_answer writer_handler = { write : string -> (unit -> 'fk_answer) -> 'fk_answer; write_bytes : (string) -> (unit -> 'fk_answer) -> 'fk_answer }

    let handle_writer (h : 'fk_answer writer_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (Writer_write x0), k -> h.write x0 (fun v -> Effect.Deep.continue k v)
      | effect (Writer_writeBytes x0), k -> h.write_bytes x0 (fun v -> Effect.Deep.continue k v)

    module Channels = struct
      let write_line (text : string) : unit =
        Effect.perform (Writer_write (text ^ "\n"))

      let rec for_each_line (f : string -> unit) : unit =
        match Effect.perform (Reader_nextLine ()) with
        | Some line -> f line;
            for_each_line f
        | None -> ()

      let remaining_text () : string =
        (fun s -> let b = Buffer.create (String.length s) in let rec go i = if i < String.length s then (let d = String.get_utf_8_uchar s i in Buffer.add_utf_8_uchar b (Uchar.utf_decode_uchar d); go (i + Uchar.utf_decode_length d)) in go 0; Buffer.contents b) (Effect.perform (Reader_nextBytes (-1)))

      let rec remaining_lines () : string list =
        match Effect.perform (Reader_nextLine ()) with
        | Some line -> line :: remaining_lines ()
        | None -> []

      let print_error (text : string) : unit =
        Effect.perform (Channel_writeTo (stderr, Fun.id (text ^ "\n")))

      let reading_from (input : (in_channel)) (body : unit -> _) : _ =
        handle_reader ({ next_line = (fun k -> k ((fun () -> Effect.perform (Channel_readLineFrom input)) ())); next_bytes = (fun x0 k -> k ((fun count -> Effect.perform (Channel_readFrom (input, count))) x0)) } : _ reader_handler) (fun () -> body ())

      let reading_all (input : (in_channel)) (body : unit -> _) : _ =
        let result = Effects.Failure.attempt (fun () -> reading_from input body) in
        Effect.perform (Channel_closeInput input);
        match result with
        | Ok value -> value
        | Error reason -> match Effect.perform (Effects.Fail_fail reason) with
            | _ -> (assert false)

      let writing_all (output : (out_channel)) (body : unit -> _) : _ =
        let result = Effects.Failure.attempt (fun () -> handle_writer ({ write = (fun x0 k -> k ((fun text -> Effect.perform (Channel_writeTo (output, Fun.id text))) x0)); write_bytes = (fun x0 k -> k ((fun bytes -> Effect.perform (Channel_writeTo (output, bytes))) x0)) } : _ writer_handler) (fun () -> body ())) in
        Effect.perform (Channel_closeOutput output);
        match result with
        | Ok value -> value
        | Error reason -> match Effect.perform (Effects.Fail_fail reason) with
            | _ -> (assert false)

      module Local = struct
        let read_line_from (input : (in_channel)) : string option =
          In_channel.input_line input

        let read_from (input : (in_channel)) (count : int) : (string) =
          (fun c n -> if n < 0 then In_channel.input_all c else match In_channel.really_input_string c n with Some s -> s | None -> In_channel.input_all c) input count

        let write_to (output : (out_channel)) (bytes : (string)) : unit =
          (fun o b -> Out_channel.output_string o b; if o == stderr then Out_channel.flush o) output bytes

        let close_input (input : (in_channel)) : unit =
          In_channel.close input

        let close_output (output : (out_channel)) : unit =
          Out_channel.close output
      end
    end

    module Paths = struct
      let path (text : string) : path =
        let absolute = String.starts_with ~prefix:"/" text in
        let names = List.fold_left (fun kept name -> if String.equal "" name || name = "." then kept else if name = ".." then (match kept with
                  | last :: rest -> if last = ".." then name :: kept else rest
                  | [] -> if absolute then [] else [name]) else name :: kept) [] ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) text "/") in
        let joined = String.concat "/" (List.map Fun.id (List.rev names)) in
        ({ value = (if absolute then "/" ^ joined else if String.equal "" joined then "." else joined) } : path)

      let path_resolve (this : path) (other : string) : path =
        if String.starts_with ~prefix:"/" other then path other else path ((this : path).value ^ "/" ^ other)

      let path_names (this : path) : string list =
        List.filter (fun it -> not (String.equal "" it) && it <> ".") ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) (this : path).value "/")

      let path_name (this : path) : string =
        Option.value (Lang.Lists.list_last_or_none (path_names this)) ~default:""

      let string_to_path (this : string) : path =
        path this

      let path_is_absolute (this : path) : bool =
        String.starts_with ~prefix:"/" (this : path).value

      let path_extension (this : path) : string =
        let i = (fun s t -> let n = String.length s and m = String.length t in let rec find i = if i < 0 then -1 else if String.sub s i m = t then i else find (i - 1) in let rec count i k = if i >= k then 0 else 1 + count (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) k in let i = find (n - m) in if i < 0 then -1 else count 0 i) (path_name this) "." in
        if i <= 0 then "" else (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in String.sub s i (String.length s - i)) (path_name this) (i + 1)

      let path_name_without_extension (this : path) : string =
        let i = (fun s t -> let n = String.length s and m = String.length t in let rec find i = if i < 0 then -1 else if String.sub s i m = t then i else find (i - 1) in let rec count i k = if i >= k then 0 else 1 + count (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) k in let i = find (n - m) in if i < 0 then -1 else count 0 i) (path_name this) "." in
        if i <= 0 then path_name this else (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in String.sub s 0 (at 0 n)) (path_name this) i

      let path_parent (this : path) : path option =
        match path_names this with
        | [] -> None
        | [only] -> if only = ".." then Some (path_resolve this "..") else if path_is_absolute this then Some (path "/") else None
        | _ -> Some (path_resolve this "..")

      let path_with_extension (this : path) (extension : string) : path =
        let renamed = path_name_without_extension this ^ "." ^ extension in
        match path_parent this with
        | Some folder -> path_resolve folder renamed
        | None -> path renamed

      let path_relative_to (this : path) (base : path) : path option =
        if (let fk_arg1 = path_is_absolute this in
         let fk_arg2 = path_is_absolute base in
         fk_arg1 <> fk_arg2) || (let fk_arg1 = let fk_arg1 = path_names this in
           let fk_arg2 = List.length (path_names base) in
           List.take fk_arg2 fk_arg1 in
         let fk_arg2 = path_names base in
         fk_arg1 <> fk_arg2) then None else Some (path (String.concat "/" (List.map Fun.id (let fk_arg1 = path_names this in
              let fk_arg2 = List.length (path_names base) in
              List.drop fk_arg2 fk_arg1))))
    end

    module Files = struct
      let or_fail (result : (_, string) result) : _ =
        match result with
        | Ok value -> value
        | Error reason -> match Effect.perform (Effects.Fail_fail reason) with
            | _ -> (assert false)

      let path_read_bytes (this : path) : (string) =
        or_fail (Effect.perform (FileSystem_tryReadBytes this))

      let path_read_text (this : path) : string =
        (fun s -> let b = Buffer.create (String.length s) in let rec go i = if i < String.length s then (let d = String.get_utf_8_uchar s i in Buffer.add_utf_8_uchar b (Uchar.utf_decode_uchar d); go (i + Uchar.utf_decode_length d)) in go 0; Buffer.contents b) (path_read_bytes this)

      let path_reading (this : path) (body : unit -> _) : _ =
        Channels.reading_all (or_fail (Effect.perform (FileSystem_tryOpenForReading this))) body

      let path_read_lines (this : path) : string list =
        path_reading this (fun () -> Channels.remaining_lines ())

      let path_write_bytes (this : path) (bytes : (string)) : unit =
        or_fail (Effect.perform (FileSystem_tryWriteBytes (this, bytes, false)))

      let path_write_text (this : path) (text : string) : unit =
        path_write_bytes this (Fun.id text)

      let path_append_bytes (this : path) (bytes : (string)) : unit =
        or_fail (Effect.perform (FileSystem_tryWriteBytes (this, bytes, true)))

      let path_append_text (this : path) (text : string) : unit =
        path_append_bytes this (Fun.id text)

      let path_exists (this : path) : bool =
        Effect.perform (FileSystem_exists this)

      let path_is_directory (this : path) : bool =
        Effect.perform (FileSystem_isDirectory this)

      let path_list_files (this : path) : path list =
        or_fail (Effect.perform (FileSystem_tryListFiles this))

      let path_make_dirs (this : path) : unit =
        or_fail (Effect.perform (FileSystem_tryMakeDirs this))

      let path_delete (this : path) : unit =
        or_fail (Effect.perform (FileSystem_tryDelete this))

      let path_copy_to (this : path) (target : path) : unit =
        or_fail (Effect.perform (FileSystem_tryCopy (this, target)))

      let path_last_modified (this : path) : Time.instant =
        or_fail (Effect.perform (FileSystem_tryLastModified this))

      let path_canonical (this : path) : path =
        or_fail (Effect.perform (FileSystem_tryCanonical this))

      let change_directory (folder : path) : unit =
        or_fail (Effect.perform (FileSystem_tryChangeDirectory folder))

      let rec path_copy_recursively (this : path) (target : path) : unit =
        if path_is_directory this then (path_make_dirs target;
           List.iter (fun it -> path_copy_recursively it (Paths.path_resolve target (Paths.path_name it))) (path_list_files this)) else path_copy_to this target

      let path_writing (this : path) (body : unit -> _) : _ =
        Channels.writing_all (or_fail (Effect.perform (FileSystem_tryOpenForWriting (this, false)))) body

      let path_appending (this : path) (body : unit -> _) : _ =
        Channels.writing_all (or_fail (Effect.perform (FileSystem_tryOpenForWriting (this, true)))) body

      module Local = struct
        let try_read_bytes (path : path) : ((string), string) result =
          (fun p -> try Ok (In_channel.with_open_bin p In_channel.input_all) with Sys_error e -> Error e) (path : path).value

        let try_write_bytes (path : path) (bytes : (string)) (append : bool) : (unit, string) result =
          (fun p t a -> try Ok (Out_channel.with_open_gen (Open_wronly :: Open_creat :: Open_binary :: (if a then [Open_append] else [Open_trunc])) 0o644 p (fun c -> Out_channel.output_string c t)) with Sys_error e -> Error e) (path : path).value bytes append

        let try_copy (source : path) (target : path) : (unit, string) result =
          (fun a b -> try Ok (In_channel.with_open_bin a (fun ic -> Out_channel.with_open_bin b (fun oc -> let buf = Bytes.create 65536 in let rec go () = let n = In_channel.input ic buf 0 65536 in if n > 0 then (Out_channel.output oc buf 0 n; go ()) in go ())); Unix.chmod b (Unix.stat a).Unix.st_perm) with Sys_error e | Unix.Unix_error (_, _, e) -> Error e) (source : path).value (target : path).value

        let exists (path : path) : bool =
          Sys.file_exists (path : path).value

        let is_directory (path : path) : bool =
          (fun p -> Sys.file_exists p && Sys.is_directory p) (path : path).value

        let try_list_files (path : path) : (path list, string) result =
          Result.map (fun names -> List.map (fun it -> Paths.path_resolve path it) names) ((fun p -> try Ok (List.sort compare (Array.to_list (Sys.readdir p))) with Sys_error e -> Error e) (path : path).value)

        let try_make_dirs (path : path) : (unit, string) result =
          (let rec mk p = if not (Sys.file_exists p) then (let d = Filename.dirname p in if d <> p then mk d; (try Sys.mkdir p 0o755 with Sys_error _ when Sys.is_directory p -> ())) in fun p -> try Ok (mk p) with Sys_error e -> Error e) (path : path).value

        let try_delete (path : path) : (unit, string) result =
          (let rec rm p = if Sys.is_directory p then (Array.iter (fun n -> rm (Filename.concat p n)) (Sys.readdir p); Sys.rmdir p) else Sys.remove p in fun p -> try Ok (if Sys.file_exists p then rm p) with Sys_error e -> Error e) (path : path).value

        let try_open_for_reading (path : path) : ((in_channel), string) result =
          (fun p -> try Ok (open_in_bin p) with Sys_error e -> Error e) (path : path).value

        let try_open_for_writing (path : path) (append : bool) : ((out_channel), string) result =
          (fun p a -> try Ok (open_out_gen (Open_wronly :: Open_creat :: Open_binary :: (if a then [Open_append] else [Open_trunc])) 0o644 p) with Sys_error e -> Error e) (path : path).value append

        let try_last_modified (path : path) : (Time.instant, string) result =
          Result.map (fun it -> ({ Time.millis = it } : Time.instant)) ((fun p -> try Ok (int_of_float ((Unix.stat p).Unix.st_mtime *. 1000.)) with Unix.Unix_error (e, _, _) -> Error (p ^ ": " ^ Unix.error_message e)) (path : path).value)

        let try_canonical (path : path) : (path, string) result =
          Result.map (fun it -> Paths.string_to_path it) ((fun p -> try Ok (Unix.realpath p) with Unix.Unix_error (e, _, _) -> Error (p ^ ": " ^ Unix.error_message e)) (path : path).value)

        let working_directory () : path =
          Paths.string_to_path ((fun _ -> Sys.getcwd ()) ())

        let try_change_directory (path : path) : (unit, string) result =
          (fun p -> try Ok (Sys.chdir p) with Sys_error e -> Error e) (path : path).value
      end
    end

    module Polls = struct
      type wait =
        | Readable of { descriptor : (Unix.file_descr) }
        | Writable of { descriptor : (Unix.file_descr) }
        | Past of { time : Time.instant }

      let rec show_wait (v : wait) =
        match v with
        | Readable r -> "Readable(" ^ "descriptor=" ^ (fun _ -> "<Descriptor>") r.descriptor ^ ")"
        | Writable r -> "Writable(" ^ "descriptor=" ^ (fun _ -> "<Descriptor>") r.descriptor ^ ")"
        | Past r -> "Past(" ^ "time=" ^ Time.show_instant r.time ^ ")"

      let ready (waiting : (wait * Concurrent.waker) list) : Concurrent.waker list =
        if List.is_empty waiting then [] else (let reads = List.concat_map (fun (wait, _) -> match wait with
                | Readable { descriptor = d } -> [d]
                | _ -> []) waiting in
           let writes = List.concat_map (fun (wait, _) -> match wait with
                | Writable { descriptor = d } -> [d]
                | _ -> []) waiting in
           let times = List.concat_map (fun (wait, _) -> match wait with
                | Past { time = t } -> [(t : Time.instant).Time.millis]
                | _ -> []) waiting in
           let timeout = match Lang.Lists.list_min_or_none times with
             | Some soonest -> float_of_int (max (soonest - (Effect.perform (Time.Clock_now ()) : Time.instant).Time.millis) 0) /. 1000.0
             | None -> (-1.0) in
           let (readable, writable) = (fun rs ws t -> try let (r, w, _) = Unix.select rs ws [] t in (r, w) with Unix.Unix_error (Unix.EINTR, _, _) -> ([], [])) reads writes timeout in
           let after = (Effect.perform (Time.Clock_now ()) : Time.instant).Time.millis in
           Lang.Lists.list_distinct (List.concat_map (fun (wait, waker) -> let came = match wait with
                 | Readable { descriptor = d } -> List.mem d readable
                 | Writable { descriptor = d } -> List.mem d writable
                 | Past { time = t } -> (t : Time.instant).Time.millis <= after in
               if came then [waker] else []) waiting))

      let running (executor : (module Concurrent.Executor)) (block : unit -> _) : _ =
        let waiting = ref [] in
        handle_polling ({ when_readable = (fun x0 x1 k -> k ((fun d waker -> waiting := ! waiting @ [((Readable { descriptor = d } : wait), waker)];
               ()) x0 x1)); when_writable = (fun x0 x1 k -> k ((fun d waker -> waiting := ! waiting @ [((Writable { descriptor = d } : wait), waker)];
               ()) x0 x1)); when_past = (fun x0 x1 k -> k ((fun time waker -> waiting := ! waiting @ [((Past { time = time } : wait), waker)];
               ()) x0 x1)); wait_for_any = (fun k -> k ((fun () -> let came = ready (! waiting) in
               let woken_ids = List.map (fun it -> (it : Concurrent.waker).Concurrent.id) came in
               waiting := List.filter (fun (_, waker) -> not (List.mem (waker : Concurrent.waker).Concurrent.id woken_ids)) (! waiting);
               came) ())) } : _ polling_handler) (fun () -> (match executor with
            | (module Value : Concurrent.Executor) -> Value.run) (fun () -> Effect.perform (Polling_waitForAny ())) block)

      let running_default_executor () : (module Concurrent.Executor) =
        (module Concurrent.InTurn : Concurrent.Executor)

      let await_readable (descriptor : (Unix.file_descr)) : unit =
        Effect.perform (Concurrent.Concurrent_park (fun it -> Effect.perform (Polling_whenReadable (descriptor, it))))

      let await_writable (descriptor : (Unix.file_descr)) : unit =
        Effect.perform (Concurrent.Concurrent_park (fun it -> Effect.perform (Polling_whenWritable (descriptor, it))))

      let await_for (duration : Time.duration) (register : Concurrent.waker -> unit) : bool =
        let until = Time.Times.instant_plus (Effect.perform (Time.Clock_now ())) duration in
        Effect.perform (Concurrent.Concurrent_park (fun it -> register it;
            Effect.perform (Polling_whenPast (until, it))));
        (Effect.perform (Time.Clock_now ()) : Time.instant).Time.millis < (until : Time.instant).Time.millis

      let await_readable_for (descriptor : (Unix.file_descr)) (duration : Time.duration) : bool =
        await_for duration (fun it -> Effect.perform (Polling_whenReadable (descriptor, it)))

      let await_writable_for (descriptor : (Unix.file_descr)) (duration : Time.duration) : bool =
        await_for duration (fun it -> Effect.perform (Polling_whenWritable (descriptor, it)))

      let sleep (duration : Time.duration) : unit =
        let until = Time.Times.instant_plus (Effect.perform (Time.Clock_now ())) duration in
        Effect.perform (Concurrent.Concurrent_park (fun it -> Effect.perform (Polling_whenPast (until, it))))
    end

    module Processes = struct
      let streaming (command : string) (args : string list) (body : unit -> _) : _ exit =
        let output = match Effect.perform (Process_tryStart (command, args)) with
          | Ok started -> started
          | Error reason -> match Effect.perform (Effects.Fail_fail reason) with
              | _ -> (assert false) in
        let result = Effects.Failure.attempt (fun () -> Channels.reading_from output body) in
        let code = Effect.perform (Process_waitFor output) in
        match result with
        | Ok value -> ({ code = code; value = value } : _ exit)
        | Error reason -> match Effect.perform (Effects.Fail_fail reason) with
            | _ -> (assert false)

      let run (command : string) (args : string list) : string exit =
        streaming command args (fun () -> Channels.remaining_text ())

      module Local = struct
        let try_start (command : string) (args : string list) : ((in_channel), string) result =
          (fun c a -> try Ok (Unix.open_process_in (Filename.quote_command c a ^ " 2>&1")) with Unix.Unix_error (e, _, _) -> Error (Unix.error_message e)) command args

        let wait_for (output : (in_channel)) : int =
          (fun c -> match Unix.close_process_in c with Unix.WEXITED n -> n | Unix.WSIGNALED n | Unix.WSTOPPED n -> 128 + n) output

        let run_attached (command : string) (args : string list) : int =
          (fun c a -> Sys.command (Filename.quote_command c a)) command args

        let env (name : string) : string option =
          Sys.getenv_opt name

        let set_env (name : string) (value : string) : unit =
          Unix.putenv name value

        let executable () : path =
          Paths.string_to_path ((fun _ -> Sys.executable_name) ())

        let exit (code : int) : fk_nothing =
          match exit code with
          | _ -> (assert false)
      end
    end

    module Terminal = struct
      let print (s : string) : unit =
        print_string s

      let println (s : string) : unit =
        print_endline s

      let read_line () : string =
        read_line ()
    end
  end

  module Parser = struct
    type kind =
      | Identifier
      | IntLiteral
      | FloatLiteral
      | StringLiteral
      | CharLiteral
      | Newline
      | End
      | LeftParen
      | RightParen
      | LeftBrace
      | RightBrace
      | LeftBracket
      | RightBracket
      | Comma
      | Dot
      | Colon
      | Semicolon
      | Assign
      | Arrow
      | Pipe
      | Tilde
      | Bang
      | Underscore
      | At
      | OperatorAssign
      | Plus
      | Minus
      | Star
      | Slash
      | Percent
      | Equal
      | NotEqual
      | Less
      | Greater
      | LessOrEqual
      | GreaterOrEqual
      | And
      | Or
      | Range
      | RangeUntil
      | TypeKeyword
      | ModuleKeyword
      | PrivateKeyword
      | WhenKeyword
      | IfKeyword
      | ElseKeyword
      | IsKeyword
      | TrueKeyword
      | FalseKeyword

    let rec show_kind (v : kind) =
      match v with
      | Identifier -> "Identifier"
      | IntLiteral -> "IntLiteral"
      | FloatLiteral -> "FloatLiteral"
      | StringLiteral -> "StringLiteral"
      | CharLiteral -> "CharLiteral"
      | Newline -> "Newline"
      | End -> "End"
      | LeftParen -> "LeftParen"
      | RightParen -> "RightParen"
      | LeftBrace -> "LeftBrace"
      | RightBrace -> "RightBrace"
      | LeftBracket -> "LeftBracket"
      | RightBracket -> "RightBracket"
      | Comma -> "Comma"
      | Dot -> "Dot"
      | Colon -> "Colon"
      | Semicolon -> "Semicolon"
      | Assign -> "Assign"
      | Arrow -> "Arrow"
      | Pipe -> "Pipe"
      | Tilde -> "Tilde"
      | Bang -> "Bang"
      | Underscore -> "Underscore"
      | At -> "At"
      | OperatorAssign -> "OperatorAssign"
      | Plus -> "Plus"
      | Minus -> "Minus"
      | Star -> "Star"
      | Slash -> "Slash"
      | Percent -> "Percent"
      | Equal -> "Equal"
      | NotEqual -> "NotEqual"
      | Less -> "Less"
      | Greater -> "Greater"
      | LessOrEqual -> "LessOrEqual"
      | GreaterOrEqual -> "GreaterOrEqual"
      | And -> "And"
      | Or -> "Or"
      | Range -> "Range"
      | RangeUntil -> "RangeUntil"
      | TypeKeyword -> "TypeKeyword"
      | ModuleKeyword -> "ModuleKeyword"
      | PrivateKeyword -> "PrivateKeyword"
      | WhenKeyword -> "WhenKeyword"
      | IfKeyword -> "IfKeyword"
      | ElseKeyword -> "ElseKeyword"
      | IsKeyword -> "IsKeyword"
      | TrueKeyword -> "TrueKeyword"
      | FalseKeyword -> "FalseKeyword"

    type position = { line : int; column : int }

    let rec show_position (v : position) =
      "Position(" ^ "line=" ^ string_of_int v.line ^ ", column=" ^ string_of_int v.column ^ ")"

    type annotation = { at : position; name : string; arguments : annotation_argument list; type_arguments : type_ref list }
    and annotation_argument = { name : string option; value : annotation_value }
    and annotation_value =
      | Constant of { expression : expression }
      | Reference of { at : position; name : string; type_arguments : type_ref list option; arguments : annotation_argument list option }
      | ValueList of { at : position; items : annotation_value list }
      | ValueTuple of { at : position; items : annotation_value list }
    and argument = { name : string option; value : expression; text : string option; operands : (string * string) option }
    and branch = { at : position; patterns : pattern list; condition : expression option; body : expression; guard : expression option }
    and expression =
      | IntConstant of { at : position; value : int }
      | FloatConstant of { at : position; value : float }
      | BooleanConstant of { at : position; value : bool }
      | CharConstant of { at : position; value : int }
      | StringTemplate of { at : position; parts : template_part list }
      | Name of { at : position; name : string }
      | Tuple of { at : position; elements : expression list }
      | ListOf of { at : position; items : expression list }
      | Spread of { at : position; list : expression }
      | Call of { at : position; callee : expression; arguments : argument list; type_arguments : type_ref list }
      | Member of { at : position; target : expression; name : string }
      | Binary of { at : position; operator : string; left : expression; right : expression }
      | Unary of { at : position; operator : string; operand : expression }
      | Assign of { at : position; target : expression; value : expression }
      | Lambda of { at : position; parameters : parameter list; body : expression; ignores_arguments : bool }
      | Pipe of { at : position; value : expression; function_ : expression }
      | If of { at : position; condition : expression; then_ : expression; otherwise : expression; has_else : bool }
      | When of { at : position; subject : expression option; branches : branch list }
      | Block of { at : position; statements : statement list; result : expression; ends_in_binding : bool }
      | Monadic of { at : position; monad : expression; block : expression }
      | Compiled of { at : position }
      | Handle of { at : position; handler : expression; block : expression; parameters : parameter list option }
    and parameter = { at : position; name : string; parameter_type : type_ref option; annotations : annotation list; default : expression option }
    and pattern =
      | Wildcard of { at : position }
      | NamePattern of { at : position; name : string }
      | ConstantPattern of { at : position; expression : expression }
      | TuplePattern of { at : position; elements : pattern list }
      | ListPattern of { at : position; elements : pattern list; rest : pattern option }
      | CasePattern of { at : position; name : string; arguments : pattern list option; check : bool; qualifier : string option }
    and statement =
      | Binding of { at : position; name : string; parameters : parameter list option; value_type : type_ref option; value : expression; variable : bool }
      | Evaluation of { at : position; expression : expression }
      | Destructuring of { at : position; pattern : pattern; value : expression }
      | Bind of { at : position; pattern : pattern; value : expression }
    and template_part =
      | TemplateText of { text : string }
      | Interpolation of { expression : expression }
    and type_ref =
      | NamedType of { at : position; name : string; arguments : type_ref list }
      | FunctionType of { at : position; parameters : type_ref list; result : type_ref; effects : annotation list }
      | TupleType of { at : position; elements : type_ref list }
      | EffectsType of { at : position; effects : annotation list }
      | GivenType of { at : position; name : string; given : type_ref }

    let rec show_annotation (v : annotation) =
      "Annotation(" ^ "at=" ^ show_position v.at ^ ", name=" ^ Fun.id v.name ^ ", arguments=" ^ fk_show_list show_annotation_argument v.arguments ^ ", typeArguments=" ^ fk_show_list show_type_ref v.type_arguments ^ ")"
    and show_annotation_argument (v : annotation_argument) =
      "AnnotationArgument(" ^ "name=" ^ fk_show_option Fun.id v.name ^ ", value=" ^ show_annotation_value v.value ^ ")"
    and show_annotation_value (v : annotation_value) =
      match v with
      | Constant r -> "Constant(" ^ "expression=" ^ show_expression r.expression ^ ")"
      | Reference r -> "Reference(" ^ "at=" ^ show_position r.at ^ ", name=" ^ Fun.id r.name ^ ", typeArguments=" ^ fk_show_option (fk_show_list show_type_ref) r.type_arguments ^ ", arguments=" ^ fk_show_option (fk_show_list show_annotation_argument) r.arguments ^ ")"
      | ValueList r -> "ValueList(" ^ "at=" ^ show_position r.at ^ ", items=" ^ fk_show_list show_annotation_value r.items ^ ")"
      | ValueTuple r -> "ValueTuple(" ^ "at=" ^ show_position r.at ^ ", items=" ^ fk_show_list show_annotation_value r.items ^ ")"
    and show_argument (v : argument) =
      "Argument(" ^ "name=" ^ fk_show_option Fun.id v.name ^ ", value=" ^ show_expression v.value ^ ", text=" ^ fk_show_option Fun.id v.text ^ ", operands=" ^ fk_show_option (fun (x0, x1) -> "(" ^ Fun.id x0 ^ ", " ^ Fun.id x1 ^ ")") v.operands ^ ")"
    and show_branch (v : branch) =
      "Branch(" ^ "at=" ^ show_position v.at ^ ", patterns=" ^ fk_show_list show_pattern v.patterns ^ ", condition=" ^ fk_show_option show_expression v.condition ^ ", body=" ^ show_expression v.body ^ ", guard=" ^ fk_show_option show_expression v.guard ^ ")"
    and show_expression (v : expression) =
      match v with
      | IntConstant r -> "IntConstant(" ^ "at=" ^ show_position r.at ^ ", value=" ^ string_of_int r.value ^ ")"
      | FloatConstant r -> "FloatConstant(" ^ "at=" ^ show_position r.at ^ ", value=" ^ fk_show_float r.value ^ ")"
      | BooleanConstant r -> "BooleanConstant(" ^ "at=" ^ show_position r.at ^ ", value=" ^ string_of_bool r.value ^ ")"
      | CharConstant r -> "CharConstant(" ^ "at=" ^ show_position r.at ^ ", value=" ^ fk_show_char r.value ^ ")"
      | StringTemplate r -> "StringTemplate(" ^ "at=" ^ show_position r.at ^ ", parts=" ^ fk_show_list show_template_part r.parts ^ ")"
      | Name r -> "Name(" ^ "at=" ^ show_position r.at ^ ", name=" ^ Fun.id r.name ^ ")"
      | Tuple r -> "Tuple(" ^ "at=" ^ show_position r.at ^ ", elements=" ^ fk_show_list show_expression r.elements ^ ")"
      | ListOf r -> "ListOf(" ^ "at=" ^ show_position r.at ^ ", items=" ^ fk_show_list show_expression r.items ^ ")"
      | Spread r -> "Spread(" ^ "at=" ^ show_position r.at ^ ", list=" ^ show_expression r.list ^ ")"
      | Call r -> "Call(" ^ "at=" ^ show_position r.at ^ ", callee=" ^ show_expression r.callee ^ ", arguments=" ^ fk_show_list show_argument r.arguments ^ ", typeArguments=" ^ fk_show_list show_type_ref r.type_arguments ^ ")"
      | Member r -> "Member(" ^ "at=" ^ show_position r.at ^ ", target=" ^ show_expression r.target ^ ", name=" ^ Fun.id r.name ^ ")"
      | Binary r -> "Binary(" ^ "at=" ^ show_position r.at ^ ", operator=" ^ Fun.id r.operator ^ ", left=" ^ show_expression r.left ^ ", right=" ^ show_expression r.right ^ ")"
      | Unary r -> "Unary(" ^ "at=" ^ show_position r.at ^ ", operator=" ^ Fun.id r.operator ^ ", operand=" ^ show_expression r.operand ^ ")"
      | Assign r -> "Assign(" ^ "at=" ^ show_position r.at ^ ", target=" ^ show_expression r.target ^ ", value=" ^ show_expression r.value ^ ")"
      | Lambda r -> "Lambda(" ^ "at=" ^ show_position r.at ^ ", parameters=" ^ fk_show_list show_parameter r.parameters ^ ", body=" ^ show_expression r.body ^ ", ignoresArguments=" ^ string_of_bool r.ignores_arguments ^ ")"
      | Pipe r -> "Pipe(" ^ "at=" ^ show_position r.at ^ ", value=" ^ show_expression r.value ^ ", function=" ^ show_expression r.function_ ^ ")"
      | If r -> "If(" ^ "at=" ^ show_position r.at ^ ", condition=" ^ show_expression r.condition ^ ", then=" ^ show_expression r.then_ ^ ", otherwise=" ^ show_expression r.otherwise ^ ", hasElse=" ^ string_of_bool r.has_else ^ ")"
      | When r -> "When(" ^ "at=" ^ show_position r.at ^ ", subject=" ^ fk_show_option show_expression r.subject ^ ", branches=" ^ fk_show_list show_branch r.branches ^ ")"
      | Block r -> "Block(" ^ "at=" ^ show_position r.at ^ ", statements=" ^ fk_show_list show_statement r.statements ^ ", result=" ^ show_expression r.result ^ ", endsInBinding=" ^ string_of_bool r.ends_in_binding ^ ")"
      | Monadic r -> "Monadic(" ^ "at=" ^ show_position r.at ^ ", monad=" ^ show_expression r.monad ^ ", block=" ^ show_expression r.block ^ ")"
      | Compiled r -> "Compiled(" ^ "at=" ^ show_position r.at ^ ")"
      | Handle r -> "Handle(" ^ "at=" ^ show_position r.at ^ ", handler=" ^ show_expression r.handler ^ ", block=" ^ show_expression r.block ^ ", parameters=" ^ fk_show_option (fk_show_list show_parameter) r.parameters ^ ")"
    and show_parameter (v : parameter) =
      "Parameter(" ^ "at=" ^ show_position v.at ^ ", name=" ^ Fun.id v.name ^ ", parameterType=" ^ fk_show_option show_type_ref v.parameter_type ^ ", annotations=" ^ fk_show_list show_annotation v.annotations ^ ", default=" ^ fk_show_option show_expression v.default ^ ")"
    and show_pattern (v : pattern) =
      match v with
      | Wildcard r -> "Wildcard(" ^ "at=" ^ show_position r.at ^ ")"
      | NamePattern r -> "NamePattern(" ^ "at=" ^ show_position r.at ^ ", name=" ^ Fun.id r.name ^ ")"
      | ConstantPattern r -> "ConstantPattern(" ^ "at=" ^ show_position r.at ^ ", expression=" ^ show_expression r.expression ^ ")"
      | TuplePattern r -> "TuplePattern(" ^ "at=" ^ show_position r.at ^ ", elements=" ^ fk_show_list show_pattern r.elements ^ ")"
      | ListPattern r -> "ListPattern(" ^ "at=" ^ show_position r.at ^ ", elements=" ^ fk_show_list show_pattern r.elements ^ ", rest=" ^ fk_show_option show_pattern r.rest ^ ")"
      | CasePattern r -> "CasePattern(" ^ "at=" ^ show_position r.at ^ ", name=" ^ Fun.id r.name ^ ", arguments=" ^ fk_show_option (fk_show_list show_pattern) r.arguments ^ ", check=" ^ string_of_bool r.check ^ ", qualifier=" ^ fk_show_option Fun.id r.qualifier ^ ")"
    and show_statement (v : statement) =
      match v with
      | Binding r -> "Binding(" ^ "at=" ^ show_position r.at ^ ", name=" ^ Fun.id r.name ^ ", parameters=" ^ fk_show_option (fk_show_list show_parameter) r.parameters ^ ", valueType=" ^ fk_show_option show_type_ref r.value_type ^ ", value=" ^ show_expression r.value ^ ", variable=" ^ string_of_bool r.variable ^ ")"
      | Evaluation r -> "Evaluation(" ^ "at=" ^ show_position r.at ^ ", expression=" ^ show_expression r.expression ^ ")"
      | Destructuring r -> "Destructuring(" ^ "at=" ^ show_position r.at ^ ", pattern=" ^ show_pattern r.pattern ^ ", value=" ^ show_expression r.value ^ ")"
      | Bind r -> "Bind(" ^ "at=" ^ show_position r.at ^ ", pattern=" ^ show_pattern r.pattern ^ ", value=" ^ show_expression r.value ^ ")"
    and show_template_part (v : template_part) =
      match v with
      | TemplateText r -> "TemplateText(" ^ "text=" ^ Fun.id r.text ^ ")"
      | Interpolation r -> "Interpolation(" ^ "expression=" ^ show_expression r.expression ^ ")"
    and show_type_ref (v : type_ref) =
      match v with
      | NamedType r -> "NamedType(" ^ "at=" ^ show_position r.at ^ ", name=" ^ Fun.id r.name ^ ", arguments=" ^ fk_show_list show_type_ref r.arguments ^ ")"
      | FunctionType r -> "FunctionType(" ^ "at=" ^ show_position r.at ^ ", parameters=" ^ fk_show_list show_type_ref r.parameters ^ ", result=" ^ show_type_ref r.result ^ ", effects=" ^ fk_show_list show_annotation r.effects ^ ")"
      | TupleType r -> "TupleType(" ^ "at=" ^ show_position r.at ^ ", elements=" ^ fk_show_list show_type_ref r.elements ^ ")"
      | EffectsType r -> "EffectsType(" ^ "at=" ^ show_position r.at ^ ", effects=" ^ fk_show_list show_annotation r.effects ^ ")"
      | GivenType r -> "GivenType(" ^ "at=" ^ show_position r.at ^ ", name=" ^ Fun.id r.name ^ ", given=" ^ show_type_ref r.given ^ ")"

    type case_ref = { at : position; owner : string; case_name : string }

    let rec show_case_ref (v : case_ref) =
      "CaseRef(" ^ "at=" ^ show_position v.at ^ ", owner=" ^ Fun.id v.owner ^ ", caseName=" ^ Fun.id v.case_name ^ ")"

    type field = { at : position; name : string; field_type : type_ref; annotations : annotation list; variable : bool; default : expression option; vararg : bool }

    let rec show_field (v : field) =
      "Field(" ^ "at=" ^ show_position v.at ^ ", name=" ^ Fun.id v.name ^ ", fieldType=" ^ show_type_ref v.field_type ^ ", annotations=" ^ fk_show_list show_annotation v.annotations ^ ", variable=" ^ string_of_bool v.variable ^ ", default=" ^ fk_show_option show_expression v.default ^ ", vararg=" ^ string_of_bool v.vararg ^ ")"

    type case_definition = { at : position; name : string; fields : field list; annotations : annotation list }

    let rec show_case_definition (v : case_definition) =
      "CaseDefinition(" ^ "at=" ^ show_position v.at ^ ", name=" ^ Fun.id v.name ^ ", fields=" ^ fk_show_list show_field v.fields ^ ", annotations=" ^ fk_show_list show_annotation v.annotations ^ ")"

    type import = { at : position; path : string list; wildcard : bool; alias : string option }

    let rec show_import (v : import) =
      "Import(" ^ "at=" ^ show_position v.at ^ ", path=" ^ fk_show_list Fun.id v.path ^ ", wildcard=" ^ string_of_bool v.wildcard ^ ", alias=" ^ fk_show_option Fun.id v.alias ^ ")"

    type module_argument = { name : string option; value : type_ref }

    let rec show_module_argument (v : module_argument) =
      "ModuleArgument(" ^ "name=" ^ fk_show_option Fun.id v.name ^ ", value=" ^ show_type_ref v.value ^ ")"

    type application = { functor_ : type_ref; arguments : module_argument list }

    let rec show_application (v : application) =
      "Application(" ^ "functor=" ^ show_type_ref v.functor_ ^ ", arguments=" ^ fk_show_list show_module_argument v.arguments ^ ")"

    type module_parameter = { at : position; name : string; spec : type_ref; default : type_ref option }

    let rec show_module_parameter (v : module_parameter) =
      "ModuleParameter(" ^ "at=" ^ show_position v.at ^ ", name=" ^ Fun.id v.name ^ ", spec=" ^ show_type_ref v.spec ^ ", default=" ^ fk_show_option show_type_ref v.default ^ ")"

    type spec_type = { at : position; name : string; type_parameters : string list }

    let rec show_spec_type (v : spec_type) =
      "SpecType(" ^ "at=" ^ show_position v.at ^ ", name=" ^ Fun.id v.name ^ ", typeParameters=" ^ fk_show_list Fun.id v.type_parameters ^ ")"

    type spec_value = { at : position; name : string; type_parameters : string list; parameters : parameter list option; value_type : type_ref; annotations : annotation list; default : expression option }

    let rec show_spec_value (v : spec_value) =
      "SpecValue(" ^ "at=" ^ show_position v.at ^ ", name=" ^ Fun.id v.name ^ ", typeParameters=" ^ fk_show_list Fun.id v.type_parameters ^ ", parameters=" ^ fk_show_option (fk_show_list show_parameter) v.parameters ^ ", valueType=" ^ show_type_ref v.value_type ^ ", annotations=" ^ fk_show_list show_annotation v.annotations ^ ", default=" ^ fk_show_option show_expression v.default ^ ")"

    type string_part =
      | Text of { text : string }
      | Code of { source : string; at : position }

    let rec show_string_part (v : string_part) =
      match v with
      | Text r -> "Text(" ^ "text=" ^ Fun.id r.text ^ ")"
      | Code r -> "Code(" ^ "source=" ^ Fun.id r.source ^ ", at=" ^ show_position r.at ^ ")"

    type syntax_error = { at : position; message : string }

    let rec show_syntax_error (v : syntax_error) =
      "SyntaxError(" ^ "at=" ^ show_position v.at ^ ", message=" ^ Fun.id v.message ^ ")"

    type token = { kind : kind; text : string; at : position; parts : string_part list }

    let rec show_token (v : token) =
      "Token(" ^ "kind=" ^ show_kind v.kind ^ ", text=" ^ Fun.id v.text ^ ", at=" ^ show_position v.at ^ ", parts=" ^ fk_show_list show_string_part v.parts ^ ")"

    type visibility =
      | Public
      | Internal
      | Private

    let rec show_visibility (v : visibility) =
      match v with
      | Public -> "Public"
      | Internal -> "Internal"
      | Private -> "Private"

    type declaration = { at : position; name : string; definition : definition; visibility : visibility; opaque : bool; annotations : annotation list }
    and definition =
      | RecordDefinition of { type_parameters : string list; fields : field list; private_constructor : bool; annotation : bool; external_ : string option }
      | CasesDefinition of { type_parameters : string list; cases : case_definition list; case_refs : case_ref list; includes : type_ref list }
      | AliasDefinition of { type_parameters : string list; target : type_ref }
      | FunctionDefinition of { type_parameters : string list; receiver : type_ref option; parameters : parameter list option; result : type_ref option; body : expression; external_ : string option; operator : bool }
      | ModuleDefinition of { declarations : declaration list; spec : type_ref option; parameters : module_parameter list; application : application option; type_parameters : string list }
      | SpecDefinition of { types : spec_type list; values : spec_value list; type_parameters : string list; copy_of : type_ref option; parents : type_ref list }

    let rec show_declaration (v : declaration) =
      "Declaration(" ^ "at=" ^ show_position v.at ^ ", name=" ^ Fun.id v.name ^ ", definition=" ^ show_definition v.definition ^ ", visibility=" ^ show_visibility v.visibility ^ ", opaque=" ^ string_of_bool v.opaque ^ ", annotations=" ^ fk_show_list show_annotation v.annotations ^ ")"
    and show_definition (v : definition) =
      match v with
      | RecordDefinition r -> "RecordDefinition(" ^ "typeParameters=" ^ fk_show_list Fun.id r.type_parameters ^ ", fields=" ^ fk_show_list show_field r.fields ^ ", privateConstructor=" ^ string_of_bool r.private_constructor ^ ", annotation=" ^ string_of_bool r.annotation ^ ", external=" ^ fk_show_option Fun.id r.external_ ^ ")"
      | CasesDefinition r -> "CasesDefinition(" ^ "typeParameters=" ^ fk_show_list Fun.id r.type_parameters ^ ", cases=" ^ fk_show_list show_case_definition r.cases ^ ", caseRefs=" ^ fk_show_list show_case_ref r.case_refs ^ ", includes=" ^ fk_show_list show_type_ref r.includes ^ ")"
      | AliasDefinition r -> "AliasDefinition(" ^ "typeParameters=" ^ fk_show_list Fun.id r.type_parameters ^ ", target=" ^ show_type_ref r.target ^ ")"
      | FunctionDefinition r -> "FunctionDefinition(" ^ "typeParameters=" ^ fk_show_list Fun.id r.type_parameters ^ ", receiver=" ^ fk_show_option show_type_ref r.receiver ^ ", parameters=" ^ fk_show_option (fk_show_list show_parameter) r.parameters ^ ", result=" ^ fk_show_option show_type_ref r.result ^ ", body=" ^ show_expression r.body ^ ", external=" ^ fk_show_option Fun.id r.external_ ^ ", operator=" ^ string_of_bool r.operator ^ ")"
      | ModuleDefinition r -> "ModuleDefinition(" ^ "declarations=" ^ fk_show_list show_declaration r.declarations ^ ", spec=" ^ fk_show_option show_type_ref r.spec ^ ", parameters=" ^ fk_show_list show_module_parameter r.parameters ^ ", application=" ^ fk_show_option show_application r.application ^ ", typeParameters=" ^ fk_show_list Fun.id r.type_parameters ^ ")"
      | SpecDefinition r -> "SpecDefinition(" ^ "types=" ^ fk_show_list show_spec_type r.types ^ ", values=" ^ fk_show_list show_spec_value r.values ^ ", typeParameters=" ^ fk_show_list Fun.id r.type_parameters ^ ", copyOf=" ^ fk_show_option show_type_ref r.copy_of ^ ", parents=" ^ fk_show_list show_type_ref r.parents ^ ")"

    type source_file = { imports : import list; declarations : declaration list }

    let rec show_source_file (v : source_file) =
      "SourceFile(" ^ "imports=" ^ fk_show_list show_import v.imports ^ ", declarations=" ^ fk_show_list show_declaration v.declarations ^ ")"

    type _ Effect.t +=
      | Rejecting_reject : position * string -> fk_nothing Effect.t

    type 'fk_answer rejecting_handler = { reject : position -> string -> (fk_nothing -> 'fk_answer) -> 'fk_answer }

    let handle_rejecting (h : 'fk_answer rejecting_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (Rejecting_reject (x0, x1)), k -> h.reject x0 x1 (fun v -> Effect.Deep.continue k v)

    let declaration_default_visibility () : visibility =
      (Public : visibility)

    let declaration_default_opaque () : bool =
      false

    let declaration_default_annotations () : annotation list =
      []

    let parameter_default_annotations () : annotation list =
      []

    let parameter_default_default () : expression option =
      None

    let token_default_parts () : string_part list =
      []

    module Lexer = struct
      type scan = { chars : ((int) array); mutable index : int; mutable line : int; mutable column : int; mutable tokens : token list; mutable open_ : kind list }

      let rec show_scan (v : scan) =
        "Scan(" ^ "chars=" ^ (fun _ -> "<Array>") v.chars ^ ", index=" ^ string_of_int v.index ^ ", line=" ^ string_of_int v.line ^ ", column=" ^ string_of_int v.column ^ ", tokens=" ^ fk_show_list show_token v.tokens ^ ", open=" ^ fk_show_list show_kind v.open_ ^ ")"

      type pieces = { mutable parts : string_part list; mutable text : int list }

      let rec show_pieces (v : pieces) =
        "Pieces(" ^ "parts=" ^ fk_show_list show_string_part v.parts ^ ", text=" ^ fk_show_list fk_show_char v.text ^ ")"

      let ended (s : scan) : bool =
        (s : scan).index >= Array.length (s : scan).chars

      let current (s : scan) : int =
        Array.get (s : scan).chars (s : scan).index

      let advance (s : scan) : unit =
        if Array.get (s : scan).chars (s : scan).index = 10 then (s.line <- (s : scan).line + 1;
           s.column <- 1) else s.column <- (s : scan).column + 1;
        s.index <- (s : scan).index + 1

      let rec matches (chars : ((int) array)) (at : int) (text : int list) : bool =
        match text with
        | [] -> true
        | c :: rest -> (at < Array.length chars && Array.get chars at = c) && matches chars (at + 1) rest

      let starts_with (s : scan) (at : int) (text : string) : bool =
        matches (s : scan).chars at ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) text)

      let looking (s : scan) (text : string) : bool =
        starts_with s (s : scan).index text

      let rec skip_while (s : scan) (keep : int -> bool) : unit =
        if not (ended s) && keep (current s) then (advance s;
           skip_while s keep) else ()

      let position (s : scan) : position =
        ({ line = (s : scan).line; column = (s : scan).column } : position)

      let rec advance_by (s : scan) (n : int) : unit =
        if n > 0 && not (ended s) then (advance s;
           advance_by s (n - 1)) else ()

      let rec skip_until (s : scan) (text : string) : unit =
        if not (ended s) && not (looking s text) then (advance s;
           skip_until s text) else ()

      let rec skip_space_and_comments (s : scan) : unit =
        if not (ended s) then (let c = current s in
           if (c = 32 || c = 9) || c = 13 then (advance s;
              skip_space_and_comments s) else if looking s "//" then (skip_while s (fun it -> it <> 10);
                skip_space_and_comments s) else if looking s "/*" then (let start = position s in
                  advance_by s 2;
                  skip_until s "*/";
                  if ended s then (match Effect.perform (Rejecting_reject (start, "unterminated comment")) with
                     | _ -> (assert false)) else ();
                  advance_by s 2;
                  skip_space_and_comments s) else ()) else ()

      let tokens_default_from () : position =
        ({ line = 1; column = 1 } : position)

      let add (s : scan) (token : token) : unit =
        s.tokens <- token :: (s : scan).tokens

      let continues_line =
        [(Comma : kind); (Dot : kind); (Colon : kind); (Assign : kind); (OperatorAssign : kind); (Arrow : kind); (Pipe : kind); (Tilde : kind); (Bang : kind); (Plus : kind); (Minus : kind); (Star : kind); (Slash : kind); (Percent : kind); (Equal : kind); (NotEqual : kind); (Less : kind); (LessOrEqual : kind); (GreaterOrEqual : kind); (And : kind); (Or : kind); (Range : kind); (RangeUntil : kind); (LeftParen : kind); (LeftBracket : kind); (LeftBrace : kind); (Semicolon : kind); (Newline : kind)]

      let rec past_space (chars : ((int) array)) (at : int) : int =
        if at < Array.length chars && Lang.Strings.char_is_whitespace (Array.get chars at) then past_space chars (at + 1) else at

      let rec line_end (chars : ((int) array)) (at : int) : int =
        if at < Array.length chars && Array.get chars at <> 10 then line_end chars (at + 1) else at

      let rec next_line_continues (s : scan) (from : int) : bool =
        let at = past_space (s : scan).chars from in
        if starts_with s at "//" then next_line_continues s (line_end (s : scan).chars at) else starts_with s at "." && not (starts_with s at "..") || List.exists (fun it -> starts_with s at it) ["|>"; "&&"; "||"]

      let newline (s : scan) (start : position) : unit =
        let in_braces = match (s : scan).open_ with
          | [] -> true
          | innermost :: _ -> innermost = (LeftBrace : kind) in
        let continues = match (s : scan).tokens with
          | [] -> true
          | last :: _ -> List.mem (last : token).kind continues_line in
        if (in_braces && not continues) && not (next_line_continues s (s : scan).index) then add s ({ kind = (Newline : kind); text = "\n"; at = start; parts = token_default_parts () } : token) else ()

      let rec chars_between (chars : ((int) array)) (from : int) (to_ : int) (after : int list) : int list =
        if to_ <= from then after else chars_between chars from (to_ - 1) (Array.get chars (to_ - 1) :: after)

      let text (s : scan) (from : int) (to_ : int) : string =
        String.concat "" (List.map Fun.id (List.map (fun it -> fk_show_char it) (chars_between (s : scan).chars from to_ [])))

      let declaring =
        ["type"; "module"]

      let rec name_follows (chars : ((int) array)) (at : int) : bool =
        if at < Array.length chars && (Array.get chars at = 32 || Array.get chars at = 9) then name_follows chars (at + 1) else (at < Array.length chars && Array.get chars at >= 65) && Array.get chars at <= 90

      let keyword (word : string) : kind option =
        match word with
        | "type" -> Some (TypeKeyword : kind)
        | "module" -> Some (ModuleKeyword : kind)
        | "private" -> Some (PrivateKeyword : kind)
        | "when" -> Some (WhenKeyword : kind)
        | "if" -> Some (IfKeyword : kind)
        | "else" -> Some (ElseKeyword : kind)
        | "is" -> Some (IsKeyword : kind)
        | "true" -> Some (TrueKeyword : kind)
        | "false" -> Some (FalseKeyword : kind)
        | _ -> None

      let kind_of_word (s : scan) (word : string) : kind =
        if word = "_" then (Underscore : kind) else if List.mem word declaring && not (name_follows (s : scan).chars (s : scan).index) then (Identifier : kind) else Option.value (keyword word) ~default:(Identifier : kind)

      let identifier (s : scan) (start : position) : unit =
        let from = (s : scan).index in
        skip_while s (fun it -> Lang.Strings.char_is_letter_or_digit it || it = 95);
        let word = text s from (s : scan).index in
        add s (let fk_arg1 = kind_of_word s word in
         let fk_arg2 = token_default_parts () in
         ({ kind = fk_arg1; text = word; at = start; parts = fk_arg2 } : token))

      let ahead (s : scan) (n : int) : int option =
        if (s : scan).index + n < Array.length (s : scan).chars then Some (Array.get (s : scan).chars ((s : scan).index + n)) else None

      let number (s : scan) (start : position) : unit =
        let from = (s : scan).index in
        skip_while s (fun it -> Lang.Strings.char_is_digit it || it = 95);
        let fraction = ahead s 0 = Some 46 && Option.value (Option.map (fun it -> Lang.Strings.char_is_digit it) (ahead s 1)) ~default:false in
        if fraction then (advance s;
           skip_while s (fun it -> Lang.Strings.char_is_digit it)) else ();
        let exponent = ahead s 0 = Some 101 || ahead s 0 = Some 69 in
        if exponent then (advance s;
           if ahead s 0 = Some 43 || ahead s 0 = Some 45 then advance s else ();
           skip_while s (fun it -> Lang.Strings.char_is_digit it)) else ();
        add s (let fk_arg1 = Lang.Strings.string_replace (text s from (s : scan).index) "_" "" in
         let fk_arg2 = token_default_parts () in
         ({ kind = (if fraction || exponent then (FloatLiteral : kind) else (IntLiteral : kind)); text = fk_arg1; at = start; parts = fk_arg2 } : token))

      let flush (pieces : pieces) : unit =
        if Lang.Lists.list_is_not_empty (pieces : pieces).text then (pieces.parts <- (Text { text = String.concat "" (List.map Fun.id (List.map (fun it -> fk_show_char it) (List.rev (pieces : pieces).text))) } : string_part) :: (pieces : pieces).parts;
           pieces.text <- []) else ()

      let rec skip_raw (s : scan) : unit =
        if not (ended s) && not (looking s "\"\"\"" && not (looking s "\"\"\"\"")) then (advance s;
           skip_raw s) else ()

      let rec skip_quoted (s : scan) : unit =
        if (not (ended s) && current s <> 34) && current s <> 10 then (advance_by s (if current s = 92 then 2 else 1);
           skip_quoted s) else ()

      let skip_string (s : scan) (start : position) : unit =
        if looking s "\"\"\"" then (advance_by s 3;
           skip_raw s;
           if ended s then (match Effect.perform (Rejecting_reject (start, "unterminated raw string")) with
              | _ -> (assert false)) else ();
           advance_by s 3) else (advance s;
           skip_quoted s;
           if ended s || current s = 10 then (match Effect.perform (Rejecting_reject (start, "unterminated string")) with
              | _ -> (assert false)) else ();
           advance s)

      let rec template_end (s : scan) (start : position) (depth : int) : unit =
        if ended s then (match Effect.perform (Rejecting_reject (start, "unterminated string template")) with
           | _ -> (assert false)) else if current s = 34 then (skip_string s start;
             template_end s start depth) else if current s = 123 then (advance s;
               template_end s start (depth + 1)) else if current s = 125 then if depth > 1 then (advance s;
                   template_end s start (depth - 1)) else () else (advance s;
                 template_end s start depth)

      let template (s : scan) (start : position) (pieces : pieces) : bool =
        let opens = current s = 36 && (match ahead s 1 with
           | Some next -> (next = 123 || Lang.Strings.char_is_letter next) || next = 95
           | None -> false) in
        if opens then (flush pieces;
           if ahead s 1 = Some 123 then (advance_by s 2;
              let at = position s in
              let from = (s : scan).index in
              template_end s start 1;
              pieces.parts <- (Code { source = text s from (s : scan).index; at = at } : string_part) :: (pieces : pieces).parts;
              advance s) else (advance s;
              let at = position s in
              let from = (s : scan).index in
              skip_while s (fun it -> Lang.Strings.char_is_letter_or_digit it || it = 95);
              pieces.parts <- (Code { source = text s from (s : scan).index; at = at } : string_part) :: (pieces : pieces).parts)) else ();
        opens

      let rec raw_body (s : scan) (start : position) (pieces : pieces) : unit =
        if ended s then (match Effect.perform (Rejecting_reject (start, "unterminated raw string")) with
           | _ -> (assert false)) else ();
        if looking s "\"\"\"" && not (looking s "\"\"\"\"") then advance_by s 3 else (if not (template s start pieces) then (pieces.text <- current s :: (pieces : pieces).text;
              advance s) else ();
           raw_body s start pieces)

      let finished (pieces : pieces) : string_part list =
        flush pieces;
        List.rev (pieces : pieces).parts

      let raw_string (s : scan) (start : position) : unit =
        advance_by s 3;
        let pieces = ({ parts = []; text = [] } : pieces) in
        raw_body s start pieces;
        add s ({ kind = (StringLiteral : kind); text = ""; at = start; parts = finished pieces } : token)

      let rec hex_digits (s : scan) (from : int) (braced : bool) : unit =
        if (not (ended s) && Lang.Strings.char_is_letter_or_digit (current s)) && (braced || (s : scan).index - from < 4) then (advance s;
           hex_digits s from braced) else ()

      let unicode (s : scan) (start : position) : string =
        let braced = ahead s 0 = Some 123 in
        if braced then advance s else ();
        let from = (s : scan).index in
        hex_digits s from braced;
        let hex = text s from (s : scan).index in
        if braced then (if ahead s 0 <> Some 125 then (match Effect.perform (Rejecting_reject (start, "\\u{...} needs its closing }")) with
              | _ -> (assert false)) else ();
           advance s) else ();
        match int_of_string_opt ("0x" ^ hex) with
        | Some code when (((braced || (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) hex = 4) && code >= 0) && code <= 1114111) && (code < 55296 || code > 57343) -> fk_show_char ((fun n -> Uchar.to_int (Uchar.of_int n)) code)
        | _ -> match Effect.perform (Rejecting_reject (start, "\\u takes four hex digits, as \\u00e9, or a code point in braces, as \\u{1F600}")) with
            | _ -> (assert false)

      let escape (s : scan) (start : position) : string =
        match ahead s 0 with
        | None -> (match Effect.perform (Rejecting_reject (start, "unterminated literal")) with
             | _ -> (assert false))
        | Some e -> advance s;
            match e with
            | 110 -> "\n"
            | 116 -> "\t"
            | 114 -> "\r"
            | 92 -> "\\"
            | 34 -> "\""
            | 39 -> "'"
            | 36 -> "$"
            | 117 -> unicode s start
            | _ -> match Effect.perform (Rejecting_reject (({ line = (s : scan).line; column = (s : scan).column - 1 } : position), "unknown escape \\" ^ fk_show_char e)) with
                | _ -> (assert false)

      let rec quoted_body (s : scan) (start : position) (pieces : pieces) : unit =
        if ended s || current s = 10 then (match Effect.perform (Rejecting_reject (start, "unterminated string")) with
           | _ -> (assert false)) else ();
        if current s = 34 then advance s else (if current s = 92 then (advance s;
              pieces.text <- List.rev ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) (escape s start)) @ (pieces : pieces).text) else if not (template s start pieces) then (pieces.text <- current s :: (pieces : pieces).text;
                advance s) else ();
           quoted_body s start pieces)

      let string (s : scan) (start : position) : unit =
        advance s;
        let pieces = ({ parts = []; text = [] } : pieces) in
        quoted_body s start pieces;
        add s ({ kind = (StringLiteral : kind); text = ""; at = start; parts = finished pieces } : token)

      let char (s : scan) (start : position) : unit =
        advance s;
        let c = match ahead s 0 with
          | None | Some 10 | Some 39 -> (match Effect.perform (Rejecting_reject (start, "empty or unterminated character literal")) with
               | _ -> (assert false))
          | Some 92 -> advance s;
              escape s start
          | Some one -> advance s;
              fk_show_char one in
        if ahead s 0 <> Some 39 then (match Effect.perform (Rejecting_reject (start, "a character literal holds one character")) with
           | _ -> (assert false)) else ();
        advance s;
        add s ({ kind = (CharLiteral : kind); text = c; at = start; parts = token_default_parts () } : token)

      let pair (text : string) : kind option =
        match text with
        | "->" -> Some (Arrow : kind)
        | "|>" -> Some (Pipe : kind)
        | "==" -> Some (Equal : kind)
        | "!=" -> Some (NotEqual : kind)
        | "<=" -> Some (LessOrEqual : kind)
        | ">=" -> Some (GreaterOrEqual : kind)
        | "&&" -> Some (And : kind)
        | "||" -> Some (Or : kind)
        | ".." -> Some (Range : kind)
        | "+=" | "-=" | "*=" | "/=" | "%=" -> Some (OperatorAssign : kind)
        | _ -> None

      let single (c : int) : kind option =
        match c with
        | 40 -> Some (LeftParen : kind)
        | 41 -> Some (RightParen : kind)
        | 123 -> Some (LeftBrace : kind)
        | 125 -> Some (RightBrace : kind)
        | 91 -> Some (LeftBracket : kind)
        | 93 -> Some (RightBracket : kind)
        | 44 -> Some (Comma : kind)
        | 46 -> Some (Dot : kind)
        | 58 -> Some (Colon : kind)
        | 59 -> Some (Semicolon : kind)
        | 61 -> Some (Assign : kind)
        | 126 -> Some (Tilde : kind)
        | 33 -> Some (Bang : kind)
        | 43 -> Some (Plus : kind)
        | 45 -> Some (Minus : kind)
        | 42 -> Some (Star : kind)
        | 47 -> Some (Slash : kind)
        | 37 -> Some (Percent : kind)
        | 60 -> Some (Less : kind)
        | 62 -> Some (Greater : kind)
        | 64 -> Some (At : kind)
        | _ -> None

      let symbol (s : scan) (start : position) : unit =
        let two = if (s : scan).index + 1 < Array.length (s : scan).chars then text s (s : scan).index ((s : scan).index + 2) else "" in
        if looking s "..<" then (advance_by s 3;
           add s ({ kind = (RangeUntil : kind); text = "..<"; at = start; parts = token_default_parts () } : token)) else (match pair two with
           | Some kind -> advance_by s 2;
               add s ({ kind = kind; text = two; at = start; parts = token_default_parts () } : token)
           | None -> let c = current s in
               let kind = match single c with
                 | Some kind -> kind
                 | None -> match Effect.perform (Rejecting_reject (start, "unexpected character '" ^ fk_show_char c ^ "'")) with
                     | _ -> (assert false) in
               advance s;
               (match kind with
                | LeftParen | LeftBrace | LeftBracket -> s.open_ <- kind :: (s : scan).open_
                | RightParen | RightBrace | RightBracket -> s.open_ <- List.drop 1 (s : scan).open_;
                    if kind = (RightBrace : kind) then (match (s : scan).tokens with
                       | last :: rest when (last : token).kind = (Newline : kind) -> s.tokens <- rest
                       | _ -> ()) else ()
                | _ -> ());
               add s ({ kind = kind; text = fk_show_char c; at = start; parts = token_default_parts () } : token))

      let rec all (s : scan) : token list =
        skip_space_and_comments s;
        if ended s then (add s (let fk_arg1 = position s in
            let fk_arg2 = token_default_parts () in
            ({ kind = (End : kind); text = ""; at = fk_arg1; parts = fk_arg2 } : token));
           List.rev (s : scan).tokens) else (let start = position s in
           let c = current s in
           if c = 10 then (advance s;
              newline s start) else if Lang.Strings.char_is_letter c || c = 95 then identifier s start else if Lang.Strings.char_is_digit c then number s start else if looking s "\"\"\"" then raw_string s start else if c = 34 then string s start else if c = 39 then char s start else symbol s start;
           all s)

      let tokens (source : string) (from : position) : (token list, syntax_error) result =
        let scan = ({ chars = Array.of_list ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) source); index = 0; line = (from : position).line; column = (from : position).column; tokens = []; open_ = [] } : scan) in
        handle_rejecting ({ reject = (fun at message _ -> Error ({ at = at; message = message } : syntax_error)) } : _ rejecting_handler) (fun () -> Ok (all scan))
    end

    let argument_default_text () : string option =
      None

    let argument_default_operands () : (string * string) option =
      None

    let field_default_annotations () : annotation list =
      []

    let field_default_variable () : bool =
      false

    let field_default_default () : expression option =
      None

    let field_default_vararg () : bool =
      false

    module Parser = struct
      type check = { subject : expression; pattern : pattern; negated : bool }

      let rec show_check (v : check) =
        "Check(" ^ "subject=" ^ show_expression v.subject ^ ", pattern=" ^ show_pattern v.pattern ^ ", negated=" ^ string_of_bool v.negated ^ ")"

      type parsing = { tokens : ((token) array); mutable index : int; mutable indexes : position list; mutable checks : (expression * check) list; mutable conjunctions : (expression * expression list * position list) list; interface : bool; lines : string list }

      let rec show_parsing (v : parsing) =
        "Parsing(" ^ "tokens=" ^ (fun _ -> "<Array>") v.tokens ^ ", index=" ^ string_of_int v.index ^ ", indexes=" ^ fk_show_list show_position v.indexes ^ ", checks=" ^ fk_show_list (fun (x0, x1) -> "(" ^ show_expression x0 ^ ", " ^ show_check x1 ^ ")") v.checks ^ ", conjunctions=" ^ fk_show_list (fun (x0, x1, x2) -> "(" ^ show_expression x0 ^ ", " ^ fk_show_list show_expression x1 ^ ", " ^ fk_show_list show_position x2 ^ ")") v.conjunctions ^ ", interface=" ^ string_of_bool v.interface ^ ", lines=" ^ fk_show_list Fun.id v.lines ^ ")"

      type spec_member =
        | TypeMember of { spec_type : spec_type }
        | ValueMember of { value : spec_value }

      let rec show_spec_member (v : spec_member) =
        match v with
        | TypeMember r -> "TypeMember(" ^ "specType=" ^ show_spec_type r.spec_type ^ ")"
        | ValueMember r -> "ValueMember(" ^ "value=" ^ show_spec_value r.value ^ ")"

      let parsing_default_interface () : bool =
        false

      let parsing_default_lines () : string list =
        []

      let peek (s : parsing) : token =
        Array.get (s : parsing).tokens (s : parsing).index

      let looking (s : parsing) (kind : kind) : bool =
        (peek s : token).kind = kind

      let next (s : parsing) : token =
        let token = peek s in
        if (s : parsing).index < Array.length (s : parsing).tokens - 1 then s.index <- (s : parsing).index + 1 else ();
        token

      let rec skip_newlines (s : parsing) : unit =
        if looking s (Newline : kind) || looking s (Semicolon : kind) then (next s;
           skip_newlines s) else ()

      let peek_at (s : parsing) (offset : int) : token =
        Array.get (s : parsing).tokens (min ((s : parsing).index + offset) (Array.length (s : parsing).tokens - 1))

      let accepts (s : parsing) (kind : kind) : bool =
        if looking s kind then (next s;
           true) else false

      let describe (token : token) : string =
        match (token : token).kind with
        | End -> "end of file"
        | Newline -> "end of line"
        | StringLiteral -> "a string"
        | _ -> "'" ^ (token : token).text ^ "'"

      let expect (s : parsing) (kind : kind) (what : string) : token =
        if looking s kind then next s else (match let fk_arg1 = (peek s : token).at in
           let fk_arg2 = "expected " ^ what ^ " but found " ^ describe (peek s) in
           Effect.perform (Rejecting_reject (fk_arg1, fk_arg2)) with
           | _ -> (assert false))

      let ident (s : parsing) (what : string) : string =
        (expect s (Identifier : kind) what : token).text

      let rec import_path (s : parsing) (path : string list) : string list * bool =
        if accepts s (Dot : kind) then if accepts s (Star : kind) then (path, true) else import_path s (path @ [ident s "a name to import, or *"]) else (path, false)

      let previous (s : parsing) : token =
        Array.get (s : parsing).tokens ((s : parsing).index - 1)

      let rec import_list (s : parsing) : import list =
        if (looking s (Identifier : kind) && (peek s : token).text = "import") && (peek_at s 1 : token).kind = (Identifier : kind) then (let start = (next s : token).at in
           let (path, wildcard) = import_path s [ident s "a name to import"] in
           let alias = if (not wildcard && looking s (Identifier : kind)) && (peek s : token).text = "as" then (next s;
                Some (ident s "the name to import it as")) else None in
           if List.length path < 2 && not wildcard then (match Effect.perform (Rejecting_reject (start, "import a declaration by its package, as in import geometry.Shapes")) with
              | _ -> (assert false)) else ();
           let next_line = let fk_arg1 = ((peek s : token).at : position).line in
             let fk_arg2 = ((previous s : token).at : position).line in
             fk_arg1 > fk_arg2 in
           if ((not (looking s (End : kind)) && not (looking s (Newline : kind))) && not (looking s (Semicolon : kind))) && not next_line then (match let fk_arg1 = (peek s : token).at in
              let fk_arg2 = "expected end of line after an import but found " ^ describe (peek s) in
              Effect.perform (Rejecting_reject (fk_arg1, fk_arg2)) with
              | _ -> (assert false)) else ();
           skip_newlines s;
           ({ at = start; path = path; wildcard = wildcard; alias = alias } : import) :: import_list s) else []

      let rec dotted (s : parsing) (name : string) : string =
        if looking s (Dot : kind) && (peek_at s 1 : token).kind = (Identifier : kind) then (next s;
           dotted s ((name ^ ".") ^ (next s : token).text)) else name

      let rec comma_separated (s : parsing) (item : unit -> _) : _ list =
        let first = item () in
        if accepts s (Comma : kind) then first :: comma_separated s item else [first]

      let rec until_closed (s : parsing) (closer : kind) (item : unit -> _) : _ list =
        if looking s closer then [] else (let first = item () in
           if accepts s (Comma : kind) then first :: until_closed s closer item else [first])

      let upper (name : string) : bool =
        Option.value (Option.map (fun it -> Lang.Strings.char_is_upper_case it) ((fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in if n < 0 || i >= String.length s then None else Some (Uchar.to_int (Uchar.utf_decode_uchar (String.get_utf_8_uchar s i)))) name 0)) ~default:false

      let upper_ident (s : parsing) (what : string) : string =
        let token = expect s (Identifier : kind) what in
        if not (upper (token : token).text) then (match Effect.perform (Rejecting_reject ((token : token).at, what ^ " must start with an upper-case letter")) with
           | _ -> (assert false)) else ();
        (token : token).text

      let rec qualified (s : parsing) (name : string) : string =
        if (looking s (Dot : kind) && (peek_at s 1 : token).kind = (Identifier : kind)) && upper (peek_at s 1 : token).text then (next s;
           qualified s ((name ^ ".") ^ (next s : token).text)) else name

      let rec type_ref (s : parsing) : type_ref =
        let at = (peek s : token).at in
        if looking s (At : kind) then (let effects = effect_list s in
           if not (looking s (LeftParen : kind)) then (EffectsType { at = at; effects = effects } : type_ref) else (match type_ref s with
              | FunctionType { at = _; parameters = parameters; result = result; effects = more } -> (FunctionType { at = at; parameters = parameters; result = result; effects = effects @ more } : type_ref)
              | _ -> match Effect.perform (Rejecting_reject (at, "an effect goes before a function type, like @Console (String) -> Unit")) with
                  | _ -> (assert false))) else if accepts s (LeftParen : kind) then (let parameters = until_closed s (RightParen : kind) (fun () -> type_ref s) in
             expect s (RightParen : kind) "')'";
             if accepts s (Arrow : kind) then (FunctionType { at = at; parameters = parameters; result = type_ref s; effects = [] } : type_ref) else (match parameters with
                | [] -> (match Effect.perform (Rejecting_reject ((peek s : token).at, "expected '->' after '()' in a function type")) with
                     | _ -> (assert false))
                | [only] -> only
                | _ -> (TupleType { at = at; elements = parameters } : type_ref))) else (let first = if (((looking s (Identifier : kind) && not (upper (peek s : token).text)) && (peek_at s 1 : token).kind = (Dot : kind)) && (peek_at s 2 : token).kind = (Identifier : kind)) && upper (peek_at s 2 : token).text then (next s : token).text else upper_ident s "a type" in
             let name = qualified s first in
             let arguments = if accepts s (Less : kind) then (let read = comma_separated s (fun () -> if looking s (Underscore : kind) then (NamedType { at = (next s : token).at; name = "_"; arguments = [] } : type_ref) else if looking s (Identifier : kind) && (peek_at s 1 : token).kind = (Assign : kind) then (let given = next s in
                            next s;
                            (GivenType { at = (given : token).at; name = (given : token).text; given = type_ref s } : type_ref)) else type_ref s) in
                  expect s (Greater : kind) "'>'";
                  read) else [] in
             (NamedType { at = at; name = name; arguments = arguments } : type_ref))
      and effect_list (s : parsing) : annotation list =
        if looking s (At : kind) then (let at = (next s : token).at in
           let name = dotted s (ident s "an effect's name") in
           let type_arguments = if accepts s (Less : kind) then (let read = comma_separated s (fun () -> type_ref s) in
                expect s (Greater : kind) "'>'";
                read) else [] in
           ({ at = at; name = name; arguments = []; type_arguments = type_arguments } : annotation) :: effect_list s) else []

      let trying (s : parsing) (block : unit -> _) : _ option =
        handle_rejecting ({ reject = (fun _ _ _ -> None) } : _ rejecting_handler) (fun () -> Some (block ()))

      let at_of (e : expression) : position =
        match e with
        | Compiled { at = at } -> at
        | IntConstant { at = at; value = _ } -> at
        | FloatConstant { at = at; value = _ } -> at
        | BooleanConstant { at = at; value = _ } -> at
        | CharConstant { at = at; value = _ } -> at
        | StringTemplate { at = at; parts = _ } -> at
        | Name { at = at; name = _ } -> at
        | Tuple { at = at; elements = _ } -> at
        | ListOf { at = at; items = _ } -> at
        | Spread { at = at; list = _ } -> at
        | Call { at = at; callee = _; arguments = _; type_arguments = _ } -> at
        | Member { at = at; target = _; name = _ } -> at
        | Binary { at = at; operator = _; left = _; right = _ } -> at
        | Unary { at = at; operator = _; operand = _ } -> at
        | Assign { at = at; target = _; value = _ } -> at
        | Lambda { at = at; parameters = _; body = _; ignores_arguments = _ } -> at
        | Pipe { at = at; value = _; function_ = _ } -> at
        | If { at = at; condition = _; then_ = _; otherwise = _; has_else = _ } -> at
        | When { at = at; subject = _; branches = _ } -> at
        | Block { at = at; statements = _; result = _; ends_in_binding = _ } -> at
        | Monadic { at = at; monad = _; block = _ } -> at
        | Handle { at = at; handler = _; block = _; parameters = _ } -> at

      let rec logical_operands (s : parsing) (op : kind) (operand : unit -> expression) (more : expression list) (positions : position list) : expression list * position list =
        if looking s op then (let at = (next s : token).at in
           skip_newlines s;
           let next = operand () in
           logical_operands s op operand (more @ [next]) (positions @ [at])) else (more, positions)

      let check_of (s : parsing) (e : expression) : check option =
        Option.map (fun (_, check) -> check) (List.find_opt (fun (read, _) -> read = e) (s : parsing).checks)

      let rec left_folded (text : string) (left : expression) (more : expression list) (positions : position list) : expression =
        match more with
        | right :: after -> (match positions with
             | at :: later -> left_folded text (Binary { at = at; operator = text; left = left; right = right } : expression) after later
             | [] -> left)
        | [] -> left

      let text_of (op : kind) : string =
        if op = (And : kind) then "&&" else "||"

      let decide (check : check) (at : position) (yes : expression) (no : expression) : expression =
        let (on_t, otherwise) = if (check : check).negated then (no, yes) else (yes, no) in
        (When { at = at; subject = Some (check : check).subject; branches = [({ at = at; patterns = [(check : check).pattern]; condition = None; body = on_t; guard = None } : branch); ({ at = at; patterns = []; condition = None; body = otherwise; guard = None } : branch)] } : expression)

      let rec chain (s : parsing) (op : kind) (operand : expression) (more : expression list) (positions : position list) : expression =
        match more with
        | [] -> operand
        | next :: after -> let rest = chain s op next after (List.drop 1 positions) in
            match check_of s operand with
            | Some check -> if op = (And : kind) then (let fk_arg1 = at_of operand in
                   let fk_arg2 = (BooleanConstant { at = at_of operand; value = false } : expression) in
                   decide check fk_arg1 rest fk_arg2) else (let fk_arg1 = at_of operand in
                   let fk_arg2 = (BooleanConstant { at = at_of operand; value = true } : expression) in
                   decide check fk_arg1 fk_arg2 rest)
            | None -> let fk_arg1 = let fk_arg1 = List.nth_opt positions 0 in
                  let fk_arg2 = at_of operand in
                  Option.value fk_arg1 ~default:fk_arg2 in
                let fk_arg2 = text_of op in
                (Binary { at = fk_arg1; operator = fk_arg2; left = operand; right = rest } : expression)

      let logical (s : parsing) (op : kind) (operand : unit -> expression) : expression =
        let first = operand () in
        if not (looking s op) then first else (let (more, positions) = logical_operands s op operand [] [] in
           if not (Option.is_some (check_of s first)) && List.for_all (fun it -> Option.is_none (check_of s it)) more then left_folded (text_of op) first more positions else (let result = chain s op first more positions in
              if op = (And : kind) && Option.is_some (check_of s first) then s.conjunctions <- (result, first :: more, positions) :: (s : parsing).conjunctions else ();
              result))

      let rec binary_rest (s : parsing) (kinds : kind list) (operand : unit -> expression) (left : expression) : expression =
        if List.mem (peek s : token).kind kinds then (let op = next s in
           skip_newlines s;
           binary_rest s kinds operand (Binary { at = (op : token).at; operator = (op : token).text; left = left; right = operand () } : expression)) else left

      let binary_level (s : parsing) (kinds : kind list) (operand : unit -> expression) : expression =
        binary_rest s kinds operand (operand ())

      let rec check_path (s : parsing) (path : string list) : string list =
        if (looking s (Dot : kind) && (peek_at s 1 : token).kind = (Identifier : kind)) && upper (peek_at s 1 : token).text then (next s;
           check_path s (path @ [(next s : token).text])) else path

      let qualifier (path : string list) : string option =
        if List.length path > 1 then Some (String.concat "." (List.map Fun.id (Lang.Lists.list_drop_last path 1))) else None

      let check_pattern (s : parsing) (at : position) : pattern =
        let path = check_path s [upper_ident s "a type after 'is'"] in
        let fk_arg1 = Option.value (Lang.Lists.list_last_or_none path) ~default:"" in
        let fk_arg2 = qualifier path in
        (CasePattern { at = at; name = fk_arg1; arguments = None; check = true; qualifier = fk_arg2 } : pattern)

      let rec type_checks (s : parsing) (e : expression) : expression =
        if looking s (IsKeyword : kind) || looking s (Bang : kind) && (peek_at s 1 : token).kind = (IsKeyword : kind) then (let negated = accepts s (Bang : kind) in
           let at = (next s : token).at in
           let check = ({ subject = e; pattern = check_pattern s at; negated = negated } : check) in
           let checked = decide check at (BooleanConstant { at = at; value = true } : expression) (BooleanConstant { at = at; value = false } : expression) in
           s.checks <- (checked, check) :: (s : parsing).checks;
           type_checks s checked) else e

      let written (s : parsing) (from : position) (to_ : position) : string option =
        if (List.is_empty (s : parsing).lines || (from : position).line > (to_ : position).line) || (to_ : position).line > List.length (s : parsing).lines then None else (let first = Option.value (Lang.Lists.list_get_or_none (s : parsing).lines ((from : position).line - 1)) ~default:"" in
           let last = Option.value (Lang.Lists.list_get_or_none (s : parsing).lines ((to_ : position).line - 1)) ~default:"" in
           let text = if (from : position).line = (to_ : position).line then if (from : position).column - 1 > (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) first || (to_ : position).column - 1 > (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) first then None else Some (Lang.Strings.string_substring first ((from : position).column - 1) ((to_ : position).column - 1)) else if (from : position).column - 1 > (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) first || (to_ : position).column - 1 > (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) last then None else Some (String.concat " " (List.map Fun.id (List.map (fun it -> String.trim it) (let fk_arg1 = let fk_arg1 = [Lang.Strings.string_substring first ((from : position).column - 1) ((fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) first)] in
                       let fk_arg2 = List.take ((to_ : position).line - (from : position).line - 1) (List.drop (from : position).line (s : parsing).lines) in
                       fk_arg1 @ fk_arg2 in
                     let fk_arg2 = [Lang.Strings.string_substring last 0 ((to_ : position).column - 1)] in
                     fk_arg1 @ fk_arg2)))) in
           Option.map (fun it -> String.trim (Lang.Strings.string_remove_suffix (String.trim it) ",")) text)

      let call_type_arguments (s : parsing) : type_ref list option =
        let start = (s : parsing).index in
        let types = Option.bind (trying s (fun () -> expect s (Less : kind) "'<'";
              let read = comma_separated s (fun () -> type_ref s) in
              expect s (Greater : kind) "'>'";
              if looking s (LeftParen : kind) && (let fk_arg1 = ((previous s : token).at : position).line in
               let fk_arg2 = ((peek s : token).at : position).line in
               fk_arg1 = fk_arg2) then Some read else None)) (fun it -> it) in
        if Option.is_none types then s.index <- start else ();
        types

      let rec module_path (e : expression) : bool =
        match e with
        | Name { at = _; name = name } -> upper name
        | Member { at = _; target = target; name = name } -> upper name && module_path target
        | _ -> false

      let pattern_at (p : pattern) : position =
        match p with
        | Wildcard { at = at } -> at
        | NamePattern { at = at; name = _ } -> at
        | ConstantPattern { at = at; expression = _ } -> at
        | TuplePattern { at = at; elements = _ } -> at
        | ListPattern { at = at; elements = _; rest = _ } -> at
        | CasePattern { at = at; name = _; arguments = _; check = _; qualifier = _ } -> at

      let rec case_path (s : parsing) (path : string list) : string list =
        if accepts s (Dot : kind) then case_path s (path @ [upper_ident s "a case name"]) else path

      let indexed (s : parsing) (e : expression) : (position * expression * argument) option =
        match e with
        | Call { at = at; callee = Member { at = _; target = target; name = "get" }; arguments = [index]; type_arguments = [] } when List.mem at (s : parsing).indexes -> Some (at, target, index)
        | _ -> None

      let conjunction_of (s : parsing) (e : expression) : (expression list * position list) option =
        Option.map (fun (_, operands, positions) -> (operands, positions)) (List.find_opt (fun (read, _, _) -> read = e) (s : parsing).conjunctions)

      let rec if_chain (s : parsing) (at : position) (operand : expression) (more : expression list) (positions : position list) (then_ : expression) (otherwise : expression) (has_else : bool) : expression =
        match check_of s operand with
        | None -> (If { at = at; condition = chain s (And : kind) operand more positions; then_ = then_; otherwise = otherwise; has_else = has_else } : expression)
        | Some check -> let inside = match more with
              | next :: after -> if_chain s at next after (List.drop 1 positions) then_ otherwise has_else
              | [] -> then_ in
            decide check (at_of operand) inside otherwise

      let rec checked_branches (s : parsing) (at : position) (branches : branch list) : expression =
        let index = Lang.Lists.list_index_of_first branches (fun b -> Option.value (Option.map (fun it -> Option.is_some (check_of s it)) (b : branch).condition) ~default:false) in
        let ends_in_else = Option.value (Option.map (fun it -> Option.is_none (it : branch).condition) (Lang.Lists.list_last_or_none branches)) ~default:false in
        if index < 0 || not ends_in_else then (When { at = at; subject = None; branches = branches } : expression) else (match List.drop index branches with
           | branch :: rest -> (let check = Option.bind (branch : branch).condition (fun it -> check_of s it) in
                let otherwise = match rest with
                  | [only] -> (only : branch).body
                  | first :: _ -> checked_branches s (first : branch).at rest
                  | [] -> (branch : branch).body in
                match check with
                | Some c -> let decided = decide c (branch : branch).at (branch : branch).body otherwise in
                    if index = 0 then decided else (When { at = at; subject = None; branches = List.take index branches @ [({ at = (branch : branch).at; patterns = []; condition = None; body = decided; guard = None } : branch)] } : expression)
                | None -> (When { at = at; subject = None; branches = branches } : expression))
           | [] -> (When { at = at; subject = None; branches = branches } : expression))

      let soft_keyword (s : parsing) (word : string) : bool =
        looking s (Identifier : kind) && (peek s : token).text = word

      let rec local_function (s : parsing) (from : int) (depth : int) : bool =
        if from >= Array.length (s : parsing).tokens then false else (match (Array.get (s : parsing).tokens from : token).kind with
           | LeftParen -> local_function s (from + 1) (depth + 1)
           | RightParen -> if depth = 1 then from + 1 < Array.length (s : parsing).tokens && ((Array.get (s : parsing).tokens (from + 1) : token).kind = (Assign : kind) || (Array.get (s : parsing).tokens (from + 1) : token).kind = (Colon : kind)) else local_function s (from + 1) (depth - 1)
           | End -> false
           | _ -> local_function s (from + 1) depth)

      let statement_at (statement : statement) : position =
        match statement with
        | Binding { at = at; name = _; parameters = _; value_type = _; value = _; variable = _ } -> at
        | Evaluation { at = at; expression = _ } -> at
        | Destructuring { at = at; pattern = _; value = _ } -> at
        | Bind { at = at; pattern = _; value = _ } -> at

      let lower (name : string) : bool =
        Option.value (Option.map (fun it -> Lang.Strings.char_is_lower_case it) ((fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in if n < 0 || i >= String.length s then None else Some (Uchar.to_int (Uchar.utf_decode_uchar (String.get_utf_8_uchar s i)))) name 0)) ~default:false

      let takes_block (e : expression) : bool =
        match e with
        | Call { at = _; callee = _; arguments = _; type_arguments = _ } -> true
        | Name { at = _; name = name } -> lower name
        | Member { at = _; target = _; name = name } -> lower name
        | _ -> false

      let rec parameter_tokens (s : parsing) (n : int) : int =
        if (peek_at s n : token).kind = (Identifier : kind) || (peek_at s n : token).kind = (Underscore : kind) then if (peek_at s (n + 1) : token).kind = (Comma : kind) then parameter_tokens s (n + 2) else n + 1 else n

      let rec block_parameters (s : parsing) : parameter list =
        if looking s (Arrow : kind) then [] else (let name = next s in
           accepts s (Comma : kind);
           let fk_arg1 = let fk_arg1 = parameter_default_annotations () in
             let fk_arg2 = parameter_default_default () in
             ({ at = (name : token).at; name = (name : token).text; parameter_type = None; annotations = fk_arg1; default = fk_arg2 } : parameter) in
           let fk_arg2 = block_parameters s in
           fk_arg1 :: fk_arg2)

      let rec parameter_list (s : parsing) (defaults : bool) : parameter list =
        expect s (LeftParen : kind) "'('";
        let read = until_closed s (RightParen : kind) (fun () -> let annotations = annotation_list s in
             let at = (peek s : token).at in
             let name = if accepts s (Underscore : kind) then "_" else ident s "a parameter name" in
             let parameter_type = if accepts s (Colon : kind) then Some (type_ref s) else None in
             let default = if looking s (Assign : kind) then (if not defaults then (match Effect.perform (Rejecting_reject ((peek s : token).at, "only a declared function's parameters can have a default")) with
                     | _ -> (assert false)) else ();
                  next s;
                  Some (expression s)) else None in
             ({ at = at; name = name; parameter_type = parameter_type; annotations = annotations; default = default } : parameter)) in
        expect s (RightParen : kind) "')'";
        read
      and annotation_list (s : parsing) : annotation list =
        if looking s (At : kind) then (let at = (next s : token).at in
           let name = dotted s (ident s "an annotation's name") in
           let type_arguments = if looking s (Less : kind) && (let fk_arg1 = ((previous s : token).at : position).line in
              let fk_arg2 = ((peek s : token).at : position).line in
              fk_arg1 = fk_arg2) then (next s;
                let read = comma_separated s (fun () -> type_ref s) in
                expect s (Greater : kind) "'>'";
                read) else [] in
           let arguments = if looking s (LeftParen : kind) then annotation_arguments s else [] in
           skip_newlines s;
           ({ at = at; name = name; arguments = arguments; type_arguments = type_arguments } : annotation) :: annotation_list s) else []
      and annotation_arguments (s : parsing) : annotation_argument list =
        expect s (LeftParen : kind) "'('";
        let read = until_closed s (RightParen : kind) (fun () -> let name = if looking s (Identifier : kind) && (peek_at s 1 : token).kind = (Assign : kind) then (let named = (next s : token).text in
                  next s;
                  Some named) else None in
             ({ name = name; value = annotation_value s } : annotation_argument)) in
        expect s (RightParen : kind) "')'";
        read
      and annotation_value (s : parsing) : annotation_value =
        let at = (peek s : token).at in
        if (looking s (Tilde : kind) || looking s (Identifier : kind) && (peek_at s 1 : token).kind = (Arrow : kind)) || looking s (LeftParen : kind) && lambda_parameters s then (match Effect.perform (Rejecting_reject ((peek s : token).at, "an annotation's arguments are constants and references, so not a lambda: name a function instead")) with
           | _ -> (assert false)) else ();
