                let fk_arg2 = argument_default_operands () in
                ({ name = None; value = value; text = fk_arg1; operands = fk_arg2 } : argument))]; type_arguments = [] } : expression)
           | None -> Some (Assign { at = (op : token).at; target = e; value = value } : expression)) else None
      and branch_body (s : parsing) : expression =
        let e = expression s in
        Option.value (assignment s e) ~default:e
      and binding_start (s : parsing) : pattern option =
        if (not (looking s (Identifier : kind)) && not (looking s (Underscore : kind))) && not (looking s (LeftParen : kind)) then None else (let start = (s : parsing).index in
           let found = Option.bind (trying s (fun () -> let read = pattern s in
                 if soft_keyword s "by" then (next s;
                    Some read) else None)) (fun it -> it) in
           if Option.is_none found then s.index <- start else ();
           found)
      and destructuring_start (s : parsing) : pattern option =
        let start = (s : parsing).index in
        let found = Option.bind (trying s (fun () -> let read = pattern s in
              match read with
              | TuplePattern read_as_tuple_pattern -> if accepts s (Assign : kind) then Some read else None
              | _ -> None)) (fun it -> it) in
        if Option.is_none found then s.index <- start else ();
        found

      let annotated (d : declaration) (annotations : annotation list) : declaration =
        { (d : declaration) with annotations = annotations @ (d : declaration).annotations }

      let skip (s : parsing) : unit =
        next s;
        ()

      let rec field_items (s : parsing) (varargs : bool) (before : field list) : field list =
        if looking s (RightParen : kind) then before else (let annotations = annotation_list s in
           let variable = (soft_keyword s "var" && (peek_at s 1 : token).kind = (Identifier : kind)) && (peek_at s 2 : token).kind = (Colon : kind) in
           if variable then skip s else ();
           let vararg_at = (peek s : token).at in
           let vararg = (soft_keyword s "vararg" && (peek_at s 1 : token).kind = (Identifier : kind)) && (peek_at s 2 : token).kind = (Colon : kind) in
           if vararg then (next s;
              if not varargs then (match Effect.perform (Rejecting_reject (vararg_at, "only an annotation's last field can be vararg")) with
                 | _ -> (assert false)) else ();
              match List.find_opt (fun it -> (it : field).vararg) before with
              | Some earlier -> (match Effect.perform (Rejecting_reject ((earlier : field).at, "only an annotation's last field can be vararg")) with
                   | _ -> (assert false))
              | None -> ()) else ();
           let at = (peek s : token).at in
           let field = if looking s (Identifier : kind) && (peek_at s 1 : token).kind = (Colon : kind) then (let name = (next s : token).text in
                next s;
                let field_type = type_ref s in
                let default = if accepts s (Assign : kind) then Some (expression s) else None in
                if vararg && Option.is_some default then (match Effect.perform (Rejecting_reject (at, "a vararg field is a list of what it's given, so it has no default: none is an empty list")) with
                   | _ -> (assert false)) else ();
                ({ at = at; name = name; field_type = field_type; annotations = annotations; variable = variable; default = default; vararg = vararg } : field)) else (let fk_arg1 = type_ref s in
                let fk_arg2 = field_default_variable () in
                let fk_arg3 = field_default_default () in
                let fk_arg4 = field_default_vararg () in
                ({ at = at; name = ""; field_type = fk_arg1; annotations = annotations; variable = fk_arg2; default = fk_arg3; vararg = fk_arg4 } : field)) in
           let all = before @ [field] in
           if accepts s (Comma : kind) then field_items s varargs all else all)

      let field_list (s : parsing) (declaration_at : position) (varargs : bool) : field list =
        let fields = field_items s varargs [] in
        let unnamed = List.filter (fun it -> String.equal "" (it : field).name) fields in
        if Lang.Lists.list_is_not_empty unnamed then (match fields with
           | [only] -> [{ (only : field) with name = "value" }]
           | _ -> match Effect.perform (Rejecting_reject (Option.value (Option.map (fun it -> (it : field).at) (List.nth_opt unnamed 0)) ~default:declaration_at, "only a type with a single field can leave it unnamed")) with
               | _ -> (assert false)) else if List.is_empty fields then (match Effect.perform (Rejecting_reject (declaration_at, "a type needs at least one field")) with
             | _ -> (assert false)) else (match List.find_opt (fun it -> (it : field).vararg) (Lang.Lists.list_drop_last fields 1) with
             | Some early -> (match Effect.perform (Rejecting_reject ((early : field).at, "only an annotation's last field can be vararg")) with
                  | _ -> (assert false))
             | None -> fields)

      let after_name =
        [(LeftParen : kind); (Colon : kind); (Assign : kind); (Dot : kind); (Less : kind)]

      let operators =
        ["plus"; "minus"; "times"; "div"; "rem"; "rangeTo"; "rangeUntil"]

      let operator_declaration (s : parsing) (at : position) (d : declaration) : declaration =
        match (d : declaration).definition with
        | FunctionDefinition { type_parameters = type_parameters; receiver = receiver; parameters = parameters; result = result; body = body; external_ = external_; operator = _ } -> let arity = if (d : declaration).name = "unaryMinus" then 0 else if List.mem (d : declaration).name operators then 1 else (match Effect.perform (Rejecting_reject ((d : declaration).at, "there's no operator '" ^ (d : declaration).name ^ "': an operator is one of " ^ String.concat ", " (List.map Fun.id (operators @ ["unaryMinus"])))) with
                   | _ -> (assert false)) in
            if Option.is_none receiver then (match Effect.perform (Rejecting_reject ((d : declaration).at, "an operator is a type's, so it's an extension: operator Type." ^ (d : declaration).name ^ "(...)")) with
               | _ -> (assert false)) else ();
            if Option.value (Option.map (fun it -> List.length it) parameters) ~default:0 <> arity then (match Effect.perform (Rejecting_reject ((d : declaration).at, (d : declaration).name ^ " takes " ^ (if arity = 0 then "no parameters" else "one parameter, the right-hand side"))) with
               | _ -> (assert false)) else ();
            { (d : declaration) with definition = (FunctionDefinition { type_parameters = type_parameters; receiver = receiver; parameters = parameters; result = result; body = body; external_ = external_; operator = true } : definition) }
        | _ -> match Effect.perform (Rejecting_reject (at, "only a function can be an operator")) with
            | _ -> (assert false)

      let module_name (s : parsing) (what : string) : string =
        qualified s (upper_ident s what)

      let rec module_arguments (s : parsing) (before : module_argument list) : module_argument list =
        let name = if looking s (Identifier : kind) && (peek_at s 1 : token).kind = (Assign : kind) then (let read = upper_ident s "a module parameter's name" in
             next s;
             Some read) else None in
        if Option.is_none name && List.exists (fun it -> Option.is_some (it : module_argument).name) before then (match Effect.perform (Rejecting_reject ((peek s : token).at, "a module given by position goes before those given by name")) with
           | _ -> (assert false)) else ();
        let at = (peek s : token).at in
        let all = before @ [({ name = name; value = (NamedType { at = at; name = module_name s "a module, by name"; arguments = [] } : type_ref) } : module_argument)] in
        if accepts s (Comma : kind) && not (looking s (RightParen : kind)) then module_arguments s all else all

      let type_parameter_list (s : parsing) : string list =
        if accepts s (Less : kind) then (let names = comma_separated s (fun () -> let fk_arg1 = if accepts s (At : kind) then "@" else "" in
                let fk_arg2 = upper_ident s "a type parameter" in
                fk_arg1 ^ fk_arg2) in
           expect s (Greater : kind) "'>'";
           names) else []

      let rec comma_separated_until (s : parsing) (closer : kind) (item : unit -> _) : _ list =
        let first = item () in
        if accepts s (Comma : kind) && not (looking s closer) then first :: comma_separated_until s closer item else [first]

      let spec_name (s : parsing) : type_ref =
        match type_ref s with
        | NamedType { at = at; name = name; arguments = arguments } -> (NamedType { at = at; name = name; arguments = arguments } : type_ref)
        | _ -> match Effect.perform (Rejecting_reject ((peek s : token).at, "expected a spec's name")) with
            | _ -> (assert false)

      let module_parameter (s : parsing) : module_parameter =
        let at = (peek s : token).at in
        let name = upper_ident s "a module parameter" in
        expect s (Colon : kind) "':' and the spec the module must follow";
        let spec = spec_name s in
        let default = if accepts s (Assign : kind) then (let default_at = (peek s : token).at in
             Some (NamedType { at = default_at; name = module_name s "the module it's given by default"; arguments = [] } : type_ref)) else None in
        ({ at = at; name = name; spec = spec; default = default } : module_parameter)

      let rec member_items (s : parsing) (item : unit -> _) (before : _ list) : _ list =
        if looking s (RightBrace : kind) then List.rev before else (let read = item () in
           if not (looking s (RightBrace : kind)) then (if not (looking s (Newline : kind)) && not (looking s (Semicolon : kind)) then (match let fk_arg1 = (peek s : token).at in
                 let fk_arg2 = "expected end of line after declaration but found " ^ describe (peek s) in
                 Effect.perform (Rejecting_reject (fk_arg1, fk_arg2)) with
                 | _ -> (assert false)) else ();
              skip_newlines s) else ();
           member_items s item (read :: before))

      let member_list (s : parsing) (item : unit -> _) : _ list =
        skip_newlines s;
        let items = member_items s item [] in
        expect s (RightBrace : kind) "'}'";
        items

      let spec_member (s : parsing) : spec_member =
        let annotations = annotation_list s in
        let at = (peek s : token).at in
        if Lang.Lists.list_is_not_empty annotations && looking s (TypeKeyword : kind) then (match Effect.perform (Rejecting_reject ((peek s : token).at, "a spec's type takes no annotations")) with
           | _ -> (assert false)) else ();
        if accepts s (TypeKeyword : kind) then (let type_name = upper_ident s "a type name" in
           let type_parameters = type_parameter_list s in
           if (looking s (Assign : kind) || looking s (LeftParen : kind)) || looking s (LeftBrace : kind) then (match Effect.perform (Rejecting_reject ((peek s : token).at, "a spec's types are abstract: write just 'type " ^ type_name ^ "', and define it in each module")) with
              | _ -> (assert false)) else ();
           (TypeMember { spec_type = ({ at = at; name = type_name; type_parameters = type_parameters } : spec_type) } : spec_member)) else (let value_name = ident s "a type or a value in the spec" in
           if upper value_name then (match Effect.perform (Rejecting_reject (at, "functions and values start with a lower-case letter")) with
              | _ -> (assert false)) else ();
           let type_parameters = type_parameter_list s in
           let parameters = if looking s (LeftParen : kind) then Some (parameter_list s true) else None in
           (match List.find_opt (fun it -> Option.is_none (it : parameter).parameter_type) (Option.value parameters ~default:[]) with
            | Some untyped -> (match Effect.perform (Rejecting_reject ((untyped : parameter).at, "a spec's parameters need types: " ^ (untyped : parameter).name ^ ": Type")) with
                 | _ -> (assert false))
            | None -> ());
           expect s (Colon : kind) (if Option.is_none parameters then "':' and the value's type" else "':' and the result type");
           let value_type = type_ref s in
           let default = if accepts s (Assign : kind) then (skip_newlines s;
                Some (expression s)) else None in
           (ValueMember { value = ({ at = at; name = value_name; type_parameters = type_parameters; parameters = parameters; value_type = value_type; annotations = annotations; default = default } : spec_value) } : spec_member))

      let spec_body (s : parsing) (start : position) (name : string) (type_parameters : string list) (parents : type_ref list) : declaration =
        let members = member_list s (fun () -> spec_member s) in
        let types = List.concat_map (fun m -> match m with
             | TypeMember { spec_type = t } -> [t]
             | ValueMember { value = _ } -> []) members in
        let values = List.concat_map (fun m -> match m with
             | TypeMember { spec_type = _ } -> []
             | ValueMember { value = v } -> [v]) members in
        let fk_arg1 = declaration_default_visibility () in
        let fk_arg2 = declaration_default_opaque () in
        let fk_arg3 = declaration_default_annotations () in
        ({ at = start; name = name; definition = (SpecDefinition { types = types; values = values; type_parameters = type_parameters; copy_of = None; parents = parents } : definition); visibility = fk_arg1; opaque = fk_arg2; annotations = fk_arg3 } : declaration)

      let effect_declaration (s : parsing) (start : position) : declaration =
        next s;
        let name = upper_ident s "an effect's name" in
        let type_parameters = type_parameter_list s in
        let effect_ = [({ at = start; name = "Effect"; arguments = []; type_arguments = [] } : annotation)] in
        if accepts s (Assign : kind) then (if Lang.Lists.list_is_not_empty type_parameters then (match Effect.perform (Rejecting_reject ((peek s : token).at, "a copy of an effect takes the type parameters of the one it copies: effect " ^ name ^ " = ...")) with
              | _ -> (assert false)) else ();
           let target = (peek s : token).at in
           annotated (let fk_arg1 = (SpecDefinition { types = []; values = []; type_parameters = []; copy_of = Some (NamedType { at = target; name = module_name s "the effect it's a copy of"; arguments = [] } : type_ref); parents = [] } : definition) in
            let fk_arg2 = declaration_default_visibility () in
            let fk_arg3 = declaration_default_opaque () in
            let fk_arg4 = declaration_default_annotations () in
            ({ at = start; name = name; definition = fk_arg1; visibility = fk_arg2; opaque = fk_arg3; annotations = fk_arg4 } : declaration)) effect_) else (if looking s (LeftParen : kind) then (match Effect.perform (Rejecting_reject ((peek s : token).at, "an effect has no fields: its operations go in braces, as in effect " ^ name ^ " { op(x: Int): Unit }")) with
              | _ -> (assert false)) else ();
           if accepts s (LeftBrace : kind) then annotated (spec_body s start name type_parameters []) effect_ else (if Lang.Lists.list_is_not_empty type_parameters then (match Effect.perform (Rejecting_reject ((peek s : token).at, "only an effect with operations takes type parameters, which its operations use")) with
                 | _ -> (assert false)) else ();
              let fk_named4 = declaration_default_visibility () in
              let fk_named5 = declaration_default_opaque () in
              ({ at = start; name = name; definition = (RecordDefinition { type_parameters = []; fields = []; private_constructor = false; annotation = true; external_ = None } : definition); visibility = fk_named4; opaque = fk_named5; annotations = effect_ } : declaration)))

      let rec case_items (s : parsing) (cases : case_definition list) (case_refs : case_ref list) (includes : type_ref list) : case_definition list * case_ref list * type_ref list =
        if looking s (RightBrace : kind) then (cases, case_refs, includes) else (let annotations = annotation_list s in
           let at = (peek s : token).at in
           if Lang.Lists.list_is_not_empty annotations && (looking s (Star : kind) || (peek_at s 1 : token).kind = (Dot : kind)) then (match Effect.perform (Rejecting_reject ((peek s : token).at, "annotate a case where it's declared")) with
              | _ -> (assert false)) else ();
           let (more_cases, more_refs, more_includes) = if accepts s (Star : kind) then (let included = match type_ref s with
                  | NamedType { at = named_at; name = named; arguments = arguments } -> (NamedType { at = named_at; name = named; arguments = arguments } : type_ref)
                  | _ -> match Effect.perform (Rejecting_reject (at, "'*' takes a type with cases")) with
                      | _ -> (assert false) in
                (cases, case_refs, includes @ [included])) else (let case_name = upper_ident s "a variant name" in
                if looking s (Dot : kind) then (let path = case_path s [case_name] in
                   (cases, case_refs @ [(let fk_arg1 = String.concat "." (List.map Fun.id (Lang.Lists.list_drop_last path 1)) in
                    let fk_arg2 = Option.value (Lang.Lists.list_last_or_none path) ~default:case_name in
                    ({ at = at; owner = fk_arg1; case_name = fk_arg2 } : case_ref))], includes)) else (let fields = if accepts s (LeftParen : kind) then (let read = field_list s at false in
                        expect s (RightParen : kind) "')'";
                        read) else [] in
                   (cases @ [({ at = at; name = case_name; fields = fields; annotations = annotations } : case_definition)], case_refs, includes))) in
           accepts s (Comma : kind);
           skip_newlines s;
           case_items s more_cases more_refs more_includes)

      let type_with_cases (s : parsing) (start : position) (name : string) (type_parameters : string list) : declaration =
        skip_newlines s;
        let (cases, case_refs, includes) = case_items s [] [] [] in
        expect s (RightBrace : kind) "'}'";
        let fk_arg1 = declaration_default_visibility () in
        let fk_arg2 = declaration_default_opaque () in
        let fk_arg3 = declaration_default_annotations () in
        ({ at = start; name = name; definition = (CasesDefinition { type_parameters = type_parameters; cases = cases; case_refs = case_refs; includes = includes } : definition); visibility = fk_arg1; opaque = fk_arg2; annotations = fk_arg3 } : declaration)

      let external_function (s : parsing) (d : declaration) : declaration =
        match (d : declaration).definition with
        | FunctionDefinition { type_parameters = type_parameters; receiver = receiver; parameters = parameters; result = result; body = body; external_ = _; operator = operator } -> let ocaml = match body with
              | StringTemplate { at = _; parts = parts } when List.for_all (fun it -> match it with
                     | TemplateText it_as_template_text -> true
                     | _ -> false) parts -> String.concat "" (List.map Fun.id (List.map (fun part -> match part with
                       | TemplateText { text = text } -> text
                       | _ -> "") parts))
              | _ -> match Effect.perform (Rejecting_reject (at_of body, "an external's body is OCaml in a string: \"List.map f this\"")) with
                  | _ -> (assert false) in
            if Option.is_none result || List.exists (fun it -> Option.is_none (it : parameter).parameter_type) (Option.value parameters ~default:[]) then (match Effect.perform (Rejecting_reject ((d : declaration).at, "an external needs the types of its parameters and result")) with
               | _ -> (assert false)) else ();
            { (d : declaration) with definition = (FunctionDefinition { type_parameters = type_parameters; receiver = receiver; parameters = parameters; result = result; body = body; external_ = Some ocaml; operator = operator } : definition) }
        | _ -> d

      let function_ (s : parsing) (start : position) : declaration =
        let receiver = if looking s (LeftParen : kind) || looking s (Identifier : kind) && upper (peek s : token).text then (let t = type_ref s in
             expect s (Dot : kind) "'.' and the name of the extension";
             Some t) else None in
        let name = (expect s (Identifier : kind) "a function name" : token).text in
        if upper name then (match Effect.perform (Rejecting_reject (start, "functions and values start with a lower-case letter")) with
           | _ -> (assert false)) else ();
        let type_parameters = type_parameter_list s in
        let parameters = if looking s (LeftParen : kind) then Some (parameter_list s true) else None in
        let result = if accepts s (Colon : kind) then Some (type_ref s) else None in
        let body = if (s : parsing).interface && not (looking s (Assign : kind)) then (Compiled { at = start } : expression) else (expect s (Assign : kind) "'='";
             skip_newlines s;
             expression s) in
        let fk_arg1 = declaration_default_visibility () in
        let fk_arg2 = declaration_default_opaque () in
        let fk_arg3 = declaration_default_annotations () in
        ({ at = start; name = name; definition = (FunctionDefinition { type_parameters = type_parameters; receiver = receiver; parameters = parameters; result = result; body = body; external_ = None; operator = false } : definition); visibility = fk_arg1; opaque = fk_arg2; annotations = fk_arg3 } : declaration)

      let rec declaration (s : parsing) : declaration =
        let start = (peek s : token).at in
        if looking s (At : kind) then (let annotations = annotation_list s in
           if looking s (End : kind) || looking s (RightBrace : kind) then (match Effect.perform (Rejecting_reject (Option.value (Option.map (fun it -> (it : annotation).at) (Lang.Lists.list_last_or_none annotations)) ~default:start, "an annotation goes before a declaration")) with
              | _ -> (assert false)) else ();
           annotated (declaration s) annotations) else if soft_keyword s "annotation" && (peek_at s 1 : token).kind = (TypeKeyword : kind) then (next s;
             next s;
             let name = upper_ident s "an annotation's name" in
             if looking s (Less : kind) then (match Effect.perform (Rejecting_reject ((peek s : token).at, "an annotation has no type parameters: its fields say what it refers to, like Type or Case<T>")) with
                | _ -> (assert false)) else ();
             if looking s (LeftBrace : kind) || looking s (Assign : kind) then (match Effect.perform (Rejecting_reject ((peek s : token).at, "an annotation is a record: annotation type " ^ name ^ "(field: Type)")) with
                | _ -> (assert false)) else ();
             let fields = if accepts s (LeftParen : kind) then (let read = if looking s (RightParen : kind) then [] else field_list s start true in
                  expect s (RightParen : kind) "')'";
                  read) else [] in
             let fk_arg1 = declaration_default_visibility () in
             let fk_arg2 = declaration_default_opaque () in
             let fk_arg3 = declaration_default_annotations () in
             ({ at = start; name = name; definition = (RecordDefinition { type_parameters = []; fields = fields; private_constructor = false; annotation = true; external_ = None } : definition); visibility = fk_arg1; opaque = fk_arg2; annotations = fk_arg3 } : declaration)) else if soft_keyword s "opaque" && (peek_at s 1 : token).kind = (TypeKeyword : kind) then (next s;
               { (declaration s : declaration) with opaque = true }) else if soft_keyword s "internal" && not (List.mem (peek_at s 1 : token).kind after_name) then (next s;
                 if looking s (PrivateKeyword : kind) then (match Effect.perform (Rejecting_reject ((peek s : token).at, "a private declaration is hidden already; it can't also be internal")) with
                    | _ -> (assert false)) else ();
                 { (declaration s : declaration) with visibility = (Internal : visibility) }) else if soft_keyword s "operator" && not (List.mem (peek_at s 1 : token).kind after_name) then (let fk_arg1 = (next s : token).at in
                   let fk_arg2 = declaration s in
                   operator_declaration s fk_arg1 fk_arg2) else if accepts s (PrivateKeyword : kind) then (if soft_keyword s "internal" then (match Effect.perform (Rejecting_reject ((peek s : token).at, "a private declaration is hidden already; it can't also be internal")) with
                        | _ -> (assert false)) else ();
                     if soft_keyword s "opaque" then (match Effect.perform (Rejecting_reject ((peek s : token).at, "a private type is hidden already; it can't also be opaque")) with
                        | _ -> (assert false)) else ();
                     { (declaration s : declaration) with visibility = (Private : visibility) }) else if accepts s (ModuleKeyword : kind) then module_declaration s start else if (soft_keyword s "effect" && (peek_at s 1 : token).kind = (Identifier : kind)) && upper (peek_at s 1 : token).text then effect_declaration s start else if (soft_keyword s "spec" && (peek_at s 1 : token).kind = (Identifier : kind)) && List.mem (peek_at s 2 : token).kind [(LeftBrace : kind); (Less : kind); (Colon : kind)] then (next s;
                           let name = upper_ident s "a spec name" in
                           let type_parameters = type_parameter_list s in
                           let parents = if accepts s (Colon : kind) then comma_separated s (fun () -> spec_name s) else [] in
                           expect s (LeftBrace : kind) "'{'";
                           spec_body s start name type_parameters parents) else if soft_keyword s "interface" && (peek_at s 1 : token).kind = (Identifier : kind) then (match let fk_arg1 = (peek s : token).at in
                             let fk_arg2 = "write a type with cases as 'type " ^ (peek_at s 1 : token).text ^ " { ... }'" in
                             Effect.perform (Rejecting_reject (fk_arg1, fk_arg2)) with
                             | _ -> (assert false)) else if accepts s (TypeKeyword : kind) then (let name = upper_ident s "a type name" in
                               let type_parameters = type_parameter_list s in
                               if accepts s (LeftBrace : kind) then type_with_cases s start name type_parameters else if accepts s (Assign : kind) then (let fk_arg1 = (AliasDefinition { type_parameters = type_parameters; target = type_ref s } : definition) in
                                    let fk_arg2 = declaration_default_visibility () in
                                    let fk_arg3 = declaration_default_opaque () in
                                    let fk_arg4 = declaration_default_annotations () in
                                    ({ at = start; name = name; definition = fk_arg1; visibility = fk_arg2; opaque = fk_arg3; annotations = fk_arg4 } : declaration)) else (let private_constructor = accepts s (PrivateKeyword : kind) in
                                    expect s (LeftParen : kind) "'(' or '{' after the type name";
                                    let fields = field_list s start false in
                                    expect s (RightParen : kind) "')'";
                                    let fk_arg1 = declaration_default_visibility () in
                                    let fk_arg2 = declaration_default_opaque () in
                                    let fk_arg3 = declaration_default_annotations () in
                                    ({ at = start; name = name; definition = (RecordDefinition { type_parameters = type_parameters; fields = fields; private_constructor = private_constructor; annotation = false; external_ = None } : definition); visibility = fk_arg1; opaque = fk_arg2; annotations = fk_arg3 } : declaration))) else if soft_keyword s "external" && (peek_at s 1 : token).kind = (TypeKeyword : kind) then (next s;
                                 next s;
                                 let name = upper_ident s "a type name" in
                                 let type_parameters = type_parameter_list s in
                                 expect s (Assign : kind) "'=' and the OCaml type, in a string: \"'a array\"";
                                 let ocaml = string_literal s (expect s (StringLiteral : kind) "the OCaml type, in a string: \"'a array\"") in
                                 let text = match ocaml with
                                   | StringTemplate { at = _; parts = [TemplateText { text = text }] } -> text
                                   | _ -> match Effect.perform (Rejecting_reject (at_of ocaml, "an external type is OCaml in a string, without templates")) with
                                       | _ -> (assert false) in
                                 let fk_arg1 = declaration_default_visibility () in
                                 let fk_arg2 = declaration_default_opaque () in
                                 let fk_arg3 = declaration_default_annotations () in
                                 ({ at = start; name = name; definition = (RecordDefinition { type_parameters = type_parameters; fields = []; private_constructor = false; annotation = false; external_ = Some text } : definition); visibility = fk_arg1; opaque = fk_arg2; annotations = fk_arg3 } : declaration)) else if soft_keyword s "external" && ((peek_at s 1 : token).kind = (Identifier : kind) || (peek_at s 1 : token).kind = (LeftParen : kind)) then (next s;
                                   external_function s (function_ s start)) else if looking s (Identifier : kind) || looking s (LeftParen : kind) then function_ s start else (match let fk_arg1 = (peek s : token).at in
                                     let fk_arg2 = "expected a declaration but found " ^ describe (peek s) in
                                     Effect.perform (Rejecting_reject (fk_arg1, fk_arg2)) with
                                     | _ -> (assert false))
      and module_declaration (s : parsing) (start : position) : declaration =
        let name = upper_ident s "a module name" in
        if accepts s (Assign : kind) then (let functor_at = (peek s : token).at in
           let functor_ = module_name s "a functor applied to modules: Functor(Module)" in
           if looking s (Less : kind) then (match Effect.perform (Rejecting_reject ((peek s : token).at, "a functor takes its modules in parentheses: " ^ functor_ ^ "(Module)")) with
              | _ -> (assert false)) else ();
           if not (accepts s (LeftParen : kind)) then (match Effect.perform (Rejecting_reject ((peek s : token).at, "expected modules for " ^ functor_ ^ ": " ^ functor_ ^ "(Module)")) with
              | _ -> (assert false)) else ();
           let arguments = if looking s (RightParen : kind) then [] else module_arguments s [] in
           expect s (RightParen : kind) "')'";
           let fk_arg1 = declaration_default_visibility () in
           let fk_arg2 = declaration_default_opaque () in
           let fk_arg3 = declaration_default_annotations () in
           ({ at = start; name = name; definition = (ModuleDefinition { declarations = []; spec = None; parameters = []; application = Some ({ functor_ = (NamedType { at = functor_at; name = functor_; arguments = [] } : type_ref); arguments = arguments } : application); type_parameters = [] } : definition); visibility = fk_arg1; opaque = fk_arg2; annotations = fk_arg3 } : declaration)) else (if looking s (Less : kind) && (peek_at s 2 : token).kind = (Colon : kind) then (match Effect.perform (Rejecting_reject ((peek s : token).at, "a functor takes its modules in parentheses: module " ^ name ^ "(M: Spec)")) with
              | _ -> (assert false)) else ();
           let type_parameters = type_parameter_list s in
           let parameters = if accepts s (LeftParen : kind) then (let read = comma_separated_until s (RightParen : kind) (fun () -> module_parameter s) in
                expect s (RightParen : kind) "')'";
                read) else [] in
           let spec = if accepts s (Colon : kind) then Some (spec_name s) else None in
           expect s (LeftBrace : kind) "'{' after the module name";
           let declarations = member_list s (fun () -> declaration s) in
           if Lang.Lists.list_is_not_empty type_parameters && Lang.Lists.list_is_not_empty parameters then (match Effect.perform (Rejecting_reject (start, "a functor can't take type parameters too yet")) with
              | _ -> (assert false)) else ();
           let fk_arg1 = declaration_default_visibility () in
           let fk_arg2 = declaration_default_opaque () in
           let fk_arg3 = declaration_default_annotations () in
           ({ at = start; name = name; definition = (ModuleDefinition { declarations = declarations; spec = spec; parameters = parameters; application = None; type_parameters = type_parameters } : definition); visibility = fk_arg1; opaque = fk_arg2; annotations = fk_arg3 } : declaration))

      let declaration_on_its_line (s : parsing) (recovering : bool) : (declaration, syntax_error) result =
        handle_rejecting ({ reject = (fun at message _ -> Error ({ at = at; message = message } : syntax_error)) } : _ rejecting_handler) (fun () -> let d = declaration s in
           if not (looking s (End : kind)) then (let new_line = recovering && (let fk_arg1 = ((peek s : token).at : position).line in
                 let fk_arg2 = ((previous s : token).at : position).line in
                 fk_arg1 > fk_arg2) in
              if (not (looking s (Newline : kind)) && not (looking s (Semicolon : kind))) && not new_line then (match let fk_arg1 = (peek s : token).at in
                 let fk_arg2 = "expected end of line after declaration but found " ^ describe (peek s) in
                 Effect.perform (Rejecting_reject (fk_arg1, fk_arg2)) with
                 | _ -> (assert false)) else ();
              skip_newlines s) else ();
           Ok d)

      let closers =
        [(RightBrace : kind); (RightParen : kind); (RightBracket : kind); (Newline : kind); (Semicolon : kind)]

      let rec skip_to_declaration (s : parsing) : unit =
        if not (looking s (End : kind)) && not (((peek s : token).at : position).column = 1 && not (List.mem (peek s : token).kind closers)) then (next s;
           skip_to_declaration s) else ()

      let rec declaration_list (s : parsing) (done_ : declaration list) (errors : syntax_error list) : declaration list * syntax_error list =
        if looking s (End : kind) then (let fk_arg1 = List.rev done_ in
           let fk_arg2 = List.rev errors in
           (fk_arg1, fk_arg2)) else (match declaration_on_its_line s (Lang.Lists.list_is_not_empty errors) with
           | Ok d -> declaration_list s (d :: done_) errors
           | Error error -> next s;
               skip_to_declaration s;
               declaration_list s done_ (error :: errors))

      let rec bare_names (t : type_ref) : string list =
        match t with
        | NamedType { at = _; name = name; arguments = arguments } -> if List.is_empty arguments && not (Lang.Strings.string_contains name ".") then [name] else List.concat_map (fun it -> bare_names it) arguments
        | TupleType { at = _; elements = elements } -> List.concat_map (fun it -> bare_names it) elements
        | FunctionType { at = _; parameters = parameters; result = result; effects = _ } -> List.concat_map (fun it -> bare_names it) (parameters @ [result])
        | EffectsType { at = _; effects = _ } -> []
        | GivenType { at = _; name = _; given = given } -> bare_names given

      let builtin_types =
        ["Int"; "Float"; "Double"; "String"; "Boolean"; "Unit"; "Char"; "Byte"; "Nothing"; "List"; "Option"; "Lazy"; "Result"]

      let type_parameter_name (name : string) : bool =
        match (fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) name with
        | first :: rest -> (first >= 65 && first <= 90) && List.for_all (fun it -> Lang.Strings.char_is_digit it) rest
        | [] -> false

      let rec with_receiver_type_parameters (declarations : declaration list) (types : string list) : declaration list =
        List.map (fun d -> match (d : declaration).definition with
           | ModuleDefinition { declarations = inside; spec = spec; parameters = parameters; application = application; type_parameters = type_parameters } -> { (d : declaration) with definition = (ModuleDefinition { declarations = with_receiver_type_parameters inside types; spec = spec; parameters = parameters; application = application; type_parameters = type_parameters } : definition) }
           | FunctionDefinition { type_parameters = type_parameters; receiver = Some receiver; parameters = parameters; result = result; body = body; external_ = external_; operator = operator } -> let named = List.filter (fun name -> ((not (List.mem name types) && not (List.mem name builtin_types)) && not (List.mem name type_parameters)) && type_parameter_name name) (Lang.Lists.list_distinct (bare_names receiver)) in
               { (d : declaration) with definition = (FunctionDefinition { type_parameters = named @ type_parameters; receiver = Some receiver; parameters = parameters; result = result; body = body; external_ = external_; operator = operator } : definition) }
           | _ -> d) declarations

      let rec type_names (declarations : declaration list) : string list =
        List.concat_map (fun d -> match (d : declaration).definition with
           | ModuleDefinition { declarations = inside; spec = _; parameters = _; application = _; type_parameters = _ } -> type_names inside
           | RecordDefinition { type_parameters = _; fields = _; private_constructor = _; annotation = _; external_ = _ } | CasesDefinition { type_parameters = _; cases = _; case_refs = _; includes = _ } | AliasDefinition { type_parameters = _; target = _ } -> [(d : declaration).name]
           | SpecDefinition { types = types; values = _; type_parameters = _; copy_of = _; parents = _ } -> List.map (fun it -> (it : spec_type).name) types
           | FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = _; operator = _ } -> []) declarations

      let parsed (source : string) (interface : bool) : (source_file, syntax_error list) result =
        match Lexer.tokens source (Lexer.tokens_default_from ()) with
        | Error error -> Error [error]
        | Ok tokens -> let s = let fk_arg1 = Array.of_list tokens in
              let fk_arg2 = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) source "\n" in
              ({ tokens = fk_arg1; index = 0; indexes = []; checks = []; conjunctions = []; interface = interface; lines = fk_arg2 } : parsing) in
            handle_rejecting ({ reject = (fun at message _ -> Error [({ at = at; message = message } : syntax_error)]) } : _ rejecting_handler) (fun () -> skip_newlines s;
               let imports = import_list s in
               let (declarations, errors) = declaration_list s [] [] in
               if List.is_empty errors then Ok ({ imports = imports; declarations = with_receiver_type_parameters declarations (type_names declarations) } : source_file) else Error errors)

      let parse_interface (source : string) : (source_file, syntax_error list) result =
        parsed source true

      let parse (source : string) : (source_file, syntax_error list) result =
        parsed source false
    end
  end

  module Checker = struct
    module Diagnostics = struct
      type diagnostic = { file : string option; at : Parser.position; message : string }

      let rec show_diagnostic (v : diagnostic) =
        "Diagnostic(" ^ "file=" ^ fk_show_option Fun.id v.file ^ ", at=" ^ Parser.show_position v.at ^ ", message=" ^ Fun.id v.message ^ ")"

      type _ Effect.t +=
        | Abandoning_abandon : diagnostic -> fk_nothing Effect.t

      type 'fk_answer abandoning_handler = { abandon : diagnostic -> (fk_nothing -> 'fk_answer) -> 'fk_answer }

      let handle_abandoning (h : 'fk_answer abandoning_handler) (f : unit -> 'fk_answer) : 'fk_answer =
        match f () with
        | v -> v
        | effect (Abandoning_abandon x0), k -> h.abandon x0 (fun v -> Effect.Deep.continue k v)

      type _ Effect.t +=
        | Reporting_report : diagnostic -> unit Effect.t

      type 'fk_answer reporting_handler = { report : diagnostic -> (unit -> 'fk_answer) -> 'fk_answer }

      let handle_reporting (h : 'fk_answer reporting_handler) (f : unit -> 'fk_answer) : 'fk_answer =
        match f () with
        | v -> v
        | effect (Reporting_report x0), k -> h.report x0 (fun v -> Effect.Deep.continue k v)

      module Diagnostics = struct
        let collecting (block : unit -> _) : _ * diagnostic list =
          let found = ref [] in
          let result = handle_reporting ({ report = (fun x0 k -> k ((fun diagnostic -> found := ! found @ [diagnostic];
                   ()) x0)) } : _ reporting_handler) (fun () -> block ()) in
          (result, ! found)

        let recovering (block : unit -> _) : _ option =
          handle_abandoning ({ abandon = (fun diagnostic _ -> Effect.perform (Reporting_report diagnostic);
             None) } : _ abandoning_handler) (fun () -> Some (block ()))

        let attempting (block : unit -> _) : (_, diagnostic) result =
          handle_abandoning ({ abandon = (fun diagnostic _ -> Error diagnostic) } : _ abandoning_handler) (fun () -> Ok (block ()))

        let ordered (diagnostics : diagnostic list) : diagnostic list =
          Lang.Lists.list_sorted_by (Lang.Lists.list_distinct diagnostics) (fun d -> (Option.value (d : diagnostic).file ~default:"", ((d : diagnostic).at : Parser.position).Parser.line, ((d : diagnostic).at : Parser.position).Parser.column))
      end

      module Written = struct
        let rec type_ref (t : Parser.type_ref) : string =
          match t with
          | Parser.NamedType { at = _; name = name; arguments = [] } -> name
          | Parser.NamedType { at = _; name = name; arguments = arguments } -> name ^ "<" ^ type_refs arguments ^ ">"
          | Parser.FunctionType { at = _; parameters = parameters; result = result; effects = _ } -> let fk_arg1 = type_refs parameters in
              let fk_arg2 = type_ref result in
              "(" ^ fk_arg1 ^ ") -> " ^ fk_arg2
          | Parser.TupleType { at = _; elements = elements } -> "(" ^ type_refs elements ^ ")"
          | Parser.EffectsType { at = _; effects = effects } -> String.concat " " (List.map Fun.id (List.map (fun it -> "@" ^ (it : Parser.annotation).Parser.name) effects))
          | Parser.GivenType { at = _; name = name; given = given } -> name ^ " = " ^ type_ref given
        and type_refs (ts : Parser.type_ref list) : string =
          String.concat ", " (List.map Fun.id (List.map (fun it -> type_ref it) ts))
      end
    end

    module Sources = struct
      type file_role =
        | EntryFile
        | ModuleFile of { name : string }
        | DeclarationsFile

      let rec show_file_role (v : file_role) =
        match v with
        | EntryFile -> "EntryFile"
        | ModuleFile r -> "ModuleFile(" ^ "name=" ^ Fun.id r.name ^ ")"
        | DeclarationsFile -> "DeclarationsFile"

      type project =
        | ProgramProject
        | CoreProject
        | OtherProject of { root : string }

      let rec show_project (v : project) =
        match v with
        | ProgramProject -> "ProgramProject"
        | CoreProject -> "CoreProject"
        | OtherProject r -> "OtherProject(" ^ "root=" ^ Fun.id r.root ^ ")"

      type source_text = { path : string option; project : project; text : string; compiled_in : string option; interface : bool; trusted : bool }

      let rec show_source_text (v : source_text) =
        "SourceText(" ^ "path=" ^ fk_show_option Fun.id v.path ^ ", project=" ^ show_project v.project ^ ", text=" ^ Fun.id v.text ^ ", compiledIn=" ^ fk_show_option Fun.id v.compiled_in ^ ", interface=" ^ string_of_bool v.interface ^ ", trusted=" ^ string_of_bool v.trusted ^ ")"

      type loaded_file = { source : source_text; package : string list; role : file_role; imports : Parser.import list; declarations : Parser.declaration list }

      let rec show_loaded_file (v : loaded_file) =
        "LoadedFile(" ^ "source=" ^ show_source_text v.source ^ ", package=" ^ fk_show_list Fun.id v.package ^ ", role=" ^ show_file_role v.role ^ ", imports=" ^ fk_show_list Parser.show_import v.imports ^ ", declarations=" ^ fk_show_list Parser.show_declaration v.declarations ^ ")"

      type source_tree = { packages : (string list, source_text list) Collections.Maps.map; imports : string list }

      let rec show_source_tree (v : source_tree) =
        "SourceTree(" ^ "packages=" ^ (fun v -> Collections.Maps.map_to_string v (fk_show_list Fun.id) (fk_show_list show_source_text)) v.packages ^ ", imports=" ^ fk_show_list Fun.id v.imports ^ ")"

      type workspace = { files : loaded_file list; apart : (string, string) Collections.Maps.map; borrowed : (string, loaded_file) Collections.Maps.map }

      let rec show_workspace (v : workspace) =
        "Workspace(" ^ "files=" ^ fk_show_list show_loaded_file v.files ^ ", apart=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Fun.id) v.apart ^ ", borrowed=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_loaded_file) v.borrowed ^ ")"

      let workspace_default_borrowed () : (string, loaded_file) Collections.Maps.map =
        Collections.Maps.empty_map ()

      module Loader = struct
        type loading = { tree : source_tree; entry : source_text; mutable packages : string list list; mutable files : loaded_file list; mutable apart : (string, string) Collections.Maps.map }

        let rec show_loading (v : loading) =
          "Loading(" ^ "tree=" ^ show_source_tree v.tree ^ ", entry=" ^ show_source_text v.entry ^ ", packages=" ^ fk_show_list (fk_show_list Fun.id) v.packages ^ ", files=" ^ fk_show_list show_loaded_file v.files ^ ", apart=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Fun.id) v.apart ^ ")"

        let rec trusting (d : Parser.declaration) : Parser.declaration =
          match (d : Parser.declaration).Parser.definition with
          | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _ :: _; application = _; type_parameters = _ } -> d
          | Parser.FunctionDefinition { type_parameters = type_parameters; receiver = receiver; parameters = parameters; result = Some result; body = _; external_ = None; operator = operator } -> { (d : Parser.declaration) with Parser.definition = (Parser.FunctionDefinition { type_parameters = type_parameters; receiver = receiver; parameters = parameters; result = Some result; body = (Parser.Compiled { at = (d : Parser.declaration).Parser.at } : Parser.expression); external_ = None; operator = operator } : Parser.definition) }
          | Parser.ModuleDefinition { declarations = inner; spec = spec; parameters = parameters; application = application; type_parameters = type_parameters } -> { (d : Parser.declaration) with Parser.definition = (Parser.ModuleDefinition { declarations = List.map (fun it -> trusting it) inner; spec = spec; parameters = parameters; application = application; type_parameters = type_parameters } : Parser.definition) }
          | _ -> d

        let parsed (source : source_text) : Parser.source_file option =
          match if (source : source_text).interface then Parser.Parser.parse_interface (source : source_text).text else Parser.Parser.parse (source : source_text).text with
          | Ok file -> Some (if (source : source_text).trusted then { (file : Parser.source_file) with Parser.declarations = List.map (fun it -> trusting it) (file : Parser.source_file).Parser.declarations } else file)
          | Error errors -> List.iter (fun it -> Effect.perform (Diagnostics.Reporting_report ({ Diagnostics.file = (source : source_text).path; at = (it : Parser.syntax_error).Parser.at; message = (it : Parser.syntax_error).Parser.message } : Diagnostics.diagnostic))) errors;
              None

        let as_import (written : string) : Parser.import =
          let fk_arg1 = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) (Lang.Strings.string_remove_suffix written ".*") "." in
          let fk_arg2 = String.ends_with ~suffix:".*" written in
          ({ Parser.at = ({ Parser.line = 1; column = 1 } : Parser.position); path = fk_arg1; wildcard = fk_arg2; alias = None } : Parser.import)

        let default_imports =
          List.map (fun written -> as_import written) ["fckt.lang.Effect"; "fckt.lang.HandledBy"; "fckt.lang.Pure"; "fckt.lang.Propagates"; "fckt.lang.Encapsulates"; "fckt.lang.Mutating"; "fckt.lang.Repeatable"; "fckt.lang.Meta"; "fckt.lang.Monad"; "fckt.lang.Applicative"; "fckt.lang.Functions.*"; "fckt.lang.Lists.*"; "fckt.lang.Strings.*"; "fckt.lang.Maths.*"; "fckt.lang.Options.*"; "fckt.lang.Results.*"; "fckt.lang.Lazies.*"]

        let imported_into (source : source_text) (tree : source_tree) : Parser.import list =
          default_imports @ (if (source : source_text).project = (ProgramProject : project) then List.map (fun written -> as_import written) (tree : source_tree).imports else [])

        let file_name (source : source_text) : string =
          Lang.Strings.string_remove_suffix (Lang.Strings.string_remove_suffix (Lang.Strings.string_substring_after_last (Option.value (source : source_text).path ~default:"") "/") ".fk") ".fki"

        let starts_capitalised (name : string) : bool =
          Option.value (Option.map (fun it -> Lang.Strings.char_is_upper_case it) ((fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in if n < 0 || i >= String.length s then None else Some (Uchar.to_int (Uchar.utf_decode_uchar (String.get_utf_8_uchar s i)))) name 0)) ~default:false

        let is_extension (d : Parser.declaration) : bool =
          match (d : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = Some _; parameters = _; result = _; body = _; external_ = _; operator = _ } -> true
          | _ -> false

        let check_declares_only (source : source_text) (name : string) (declarations : Parser.declaration list) : unit =
          let main = List.find_opt (fun d -> ((d : Parser.declaration).Parser.name = name && (d : Parser.declaration).Parser.visibility <> (Parser.Private : Parser.visibility)) && not (is_extension d)) declarations in
          (match main with
           | None -> Effect.perform (Diagnostics.Reporting_report ({ Diagnostics.file = (source : source_text).path; at = ({ Parser.line = 1; column = 1 } : Parser.position); message = name ^ ".fk must declare " ^ name ^ ", which it's named for: a module, type, spec or effect" } : Diagnostics.diagnostic))
           | Some _ -> ());
          List.iter (fun d -> Effect.perform (Diagnostics.Reporting_report ({ Diagnostics.file = (source : source_text).path; at = (d : Parser.declaration).Parser.at; message = (if starts_capitalised (d : Parser.declaration).Parser.name then (d : Parser.declaration).Parser.name ^ " belongs in its own file, " ^ (d : Parser.declaration).Parser.name ^ ".fk; or make it private to " ^ name ^ ".fk" else "'" ^ (d : Parser.declaration).Parser.name ^ "' is outside " ^ name ^ ": a capitalised file declares only what it's named for, so put it in a module, or make it private to " ^ name ^ ".fk") } : Diagnostics.diagnostic))) (List.filter (fun d -> Some d <> main && (d : Parser.declaration).Parser.visibility <> (Parser.Private : Parser.visibility)) declarations)

        let add (loading : loading) (file : loaded_file) : unit =
          loading.files <- (loading : loading).files @ [file]

        let is_main (d : Parser.declaration) : bool =
          (d : Parser.declaration).Parser.name = "main" && (match (d : Parser.declaration).Parser.definition with
           | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = _; operator = _ } -> true
           | _ -> false)

        let load_file (loading : loading) (pkg : string list) (source : source_text) : unit =
          match parsed source with
          | None -> ()
          | Some file -> let name = file_name source in
              if starts_capitalised name then (check_declares_only source name (file : Parser.source_file).Parser.declarations;
                 add loading ({ source = source; package = pkg; role = (ModuleFile { name = name } : file_role); imports = (file : Parser.source_file).Parser.imports @ imported_into source (loading : loading).tree; declarations = (file : Parser.source_file).Parser.declarations } : loaded_file)) else if List.exists (fun it -> is_main it) (file : Parser.source_file).Parser.declarations then if List.is_empty pkg then loading.apart <- List.fold_left (fun found d -> if Collections.Maps.map_contains_key found (d : Parser.declaration).Parser.name then found else Collections.Maps.map_put found (d : Parser.declaration).Parser.name (Option.value (source : source_text).path ~default:"a file")) (loading : loading).apart (file : Parser.source_file).Parser.declarations else () else add loading ({ source = source; package = pkg; role = (DeclarationsFile : file_role); imports = (file : Parser.source_file).Parser.imports @ imported_into source (loading : loading).tree; declarations = (file : Parser.source_file).Parser.declarations } : loaded_file)

        let load_package (loading : loading) (pkg : string list) : unit =
          if List.mem pkg (loading : loading).packages then () else (loading.packages <- (loading : loading).packages @ [pkg];
             List.iter (fun source -> load_file loading pkg source) (List.filter (fun it -> (it : source_text).path <> ((loading : loading).entry : source_text).path) (Collections.Maps.map_get_or_default ((loading : loading).tree : source_tree).packages pkg [])))

        let rec package_of (tree : source_tree) (path : string list) : string list option =
          if List.is_empty path then None else if Collections.Maps.map_contains_key (tree : source_tree).packages path then Some path else package_of tree (Lang.Lists.list_drop_last path 1)

        let shown (i : Parser.import) : string =
          String.concat "." (List.map Fun.id (i : Parser.import).Parser.path) ^ (if (i : Parser.import).Parser.wildcard then ".*" else "")

        let has_member (file : loaded_file) (name : string) (member : string) : bool =
          match List.find_opt (fun it -> (it : Parser.declaration).Parser.name = name) (file : loaded_file).declarations with
          | Some ({ Parser.at = _; name = _; definition = Parser.ModuleDefinition { declarations = declarations; spec = _; parameters = _; application = _; type_parameters = _ }; visibility = _; opaque = _; annotations = _ } : Parser.declaration) -> List.exists (fun it -> (it : Parser.declaration).Parser.name = member) declarations
          | _ -> false

        let check_imported (loading : loading) (importer : loaded_file) (i : Parser.import) (pkg : string list) (rest : string list) : unit =
          match rest with
          | [] -> ()
          | first :: members -> let in_package = List.filter (fun it -> (it : loaded_file).package = pkg) (loading : loading).files in
              match List.find_opt (fun it -> (it : loaded_file).role = (ModuleFile { name = first } : file_role)) in_package with
              | Some module_file -> (match members with
                   | member :: _ when ((module_file : loaded_file).source : source_text).project = (CoreProject : project) && not (has_member module_file first member) -> Effect.perform (Diagnostics.Reporting_report ({ Diagnostics.file = ((importer : loaded_file).source : source_text).path; at = (i : Parser.import).Parser.at; message = String.concat "." (List.map Fun.id (pkg @ [first])) ^ " has no '" ^ member ^ "'" } : Diagnostics.diagnostic))
                   | _ -> ())
              | None -> if Lang.Lists.list_none in_package (fun it -> (it : loaded_file).role = (DeclarationsFile : file_role) && List.exists (fun d -> (d : Parser.declaration).Parser.name = first) (it : loaded_file).declarations) then Effect.perform (Diagnostics.Reporting_report ({ Diagnostics.file = ((importer : loaded_file).source : source_text).path; at = (i : Parser.import).Parser.at; message = String.concat "." (List.map Fun.id pkg) ^ " has no '" ^ first ^ "'" } : Diagnostics.diagnostic)) else ()

        let follow_import (loading : loading) (file : loaded_file) (i : Parser.import) : unit =
          match package_of (loading : loading).tree (i : Parser.import).Parser.path with
          | None -> Effect.perform (Diagnostics.Reporting_report ({ Diagnostics.file = ((file : loaded_file).source : source_text).path; at = (i : Parser.import).Parser.at; message = "import " ^ shown i ^ " names no package: a package is a folder, as geometry is for geometry/Shapes.fk" } : Diagnostics.diagnostic))
          | Some pkg -> let rest = List.drop (List.length pkg) (i : Parser.import).Parser.path in
              if List.is_empty rest && not (i : Parser.import).Parser.wildcard then (let dotted = String.concat "." (List.map Fun.id (i : Parser.import).Parser.path) in
                 Effect.perform (Diagnostics.Reporting_report ({ Diagnostics.file = ((file : loaded_file).source : source_text).path; at = (i : Parser.import).Parser.at; message = dotted ^ " is a package; import what's in it, as in import " ^ dotted ^ ".*" } : Diagnostics.diagnostic))) else (load_package loading pkg;
                 check_imported loading file i pkg rest)

        let rec dotted (tokens : Parser.token list) (run : string list) : string list * Parser.token list =
          match tokens with
          | dot :: name :: rest when (dot : Parser.token).Parser.kind = (Parser.Dot : Parser.kind) && (name : Parser.token).Parser.kind = (Parser.Identifier : Parser.kind) -> dotted rest (run @ [(name : Parser.token).Parser.text])
          | _ -> (run, tokens)

        let rec dotted_runs (tokens : Parser.token list) (runs : string list list) : string list list =
          match tokens with
          | [] -> runs
          | t :: rest when (t : Parser.token).Parser.kind = (Parser.Identifier : Parser.kind) -> let (run, after) = dotted rest [(t : Parser.token).Parser.text] in
              dotted_runs after (if List.length run > 1 then runs @ [run] else runs)
          | _ :: rest -> dotted_runs rest runs

        let named_in_full (tree : source_tree) (text : string) : string list list =
          match Parser.Lexer.tokens text (Parser.Lexer.tokens_default_from ()) with
          | Error _ -> []
          | Ok tokens -> Lang.Lists.list_distinct (Lang.Lists.list_map_not_null (List.filter (fun run -> List.length run > 1 && Collections.Maps.map_contains_key (tree : source_tree).packages (List.take 1 run)) (dotted_runs tokens [])) (fun run -> package_of tree run))

        let rec follow (loading : loading) (files : loaded_file list) : unit =
          List.iter (fun file -> List.iter (fun i -> let before = List.length (loading : loading).files in
                follow_import loading file i;
                follow loading (List.drop before (loading : loading).files)) (file : loaded_file).imports;
             List.iter (fun pkg -> let before = List.length (loading : loading).files in
                load_package loading pkg;
                follow loading (List.drop before (loading : loading).files)) (named_in_full (loading : loading).tree ((file : loaded_file).source : source_text).text)) files

        let load (entry : source_text) (tree : source_tree) : workspace =
          let loading = ({ tree = tree; entry = entry; packages = []; files = []; apart = Collections.Maps.empty_map () } : loading) in
          (match parsed entry with
           | Some file -> let own = ({ source = entry; package = []; role = (EntryFile : file_role); imports = (file : Parser.source_file).Parser.imports @ imported_into entry tree; declarations = (file : Parser.source_file).Parser.declarations } : loaded_file) in
               loading.files <- [own];
               let before = List.length (loading : loading).files in
               load_package loading [];
               follow loading ([own] @ List.drop before (loading : loading).files)
           | None -> ());
          ({ files = (loading : loading).files; apart = (loading : loading).apart; borrowed = workspace_default_borrowed () } : workspace)
      end

      let source_text_default_compiled_in () : string option =
        None

      let source_text_default_interface () : bool =
        false

      let source_text_default_trusted () : bool =
        false

      let source_tree_default_imports () : string list =
        []
    end

    module Types = struct
      type type_variable = { id : int }

      let rec show_type_variable (v : type_variable) =
        "TypeVariable(" ^ "id=" ^ string_of_int v.id ^ ")"

      type effect_label = { name : string; arguments : type_ list }
      and row = { labels : effect_label list; rest : type_variable option }
      and type_ =
        | Variable of { variable : type_variable }
        | TypeParameter of { name : string }
        | Named of { name : string; arguments : type_ list; region : type_ option }
        | Abstract of { name : string; arguments : type_ list }
        | SpecOwnType of { name : string; arguments : type_ list }
        | ModuleValue of { spec : string; arguments : type_ list; own_types : string list }
        | Handler of { effect_ : string; arguments : type_ list }
        | TupleOf of { elements : type_ list }
        | FunctionOf of { parameters : type_ list; result : type_; effects : row }
        | Effects of { row : row }

      let rec show_effect_label (v : effect_label) =
        "EffectLabel(" ^ "name=" ^ Fun.id v.name ^ ", arguments=" ^ fk_show_list show_type v.arguments ^ ")"
      and show_row (v : row) =
        "Row(" ^ "labels=" ^ fk_show_list show_effect_label v.labels ^ ", rest=" ^ fk_show_option show_type_variable v.rest ^ ")"
      and show_type (v : type_) =
        match v with
        | Variable r -> "Variable(" ^ "variable=" ^ show_type_variable r.variable ^ ")"
        | TypeParameter r -> "TypeParameter(" ^ "name=" ^ Fun.id r.name ^ ")"
        | Named r -> "Named(" ^ "name=" ^ Fun.id r.name ^ ", arguments=" ^ fk_show_list show_type r.arguments ^ ", region=" ^ fk_show_option show_type r.region ^ ")"
        | Abstract r -> "Abstract(" ^ "name=" ^ Fun.id r.name ^ ", arguments=" ^ fk_show_list show_type r.arguments ^ ")"
        | SpecOwnType r -> "SpecOwnType(" ^ "name=" ^ Fun.id r.name ^ ", arguments=" ^ fk_show_list show_type r.arguments ^ ")"
        | ModuleValue r -> "ModuleValue(" ^ "spec=" ^ Fun.id r.spec ^ ", arguments=" ^ fk_show_list show_type r.arguments ^ ", ownTypes=" ^ fk_show_list Fun.id r.own_types ^ ")"
        | Handler r -> "Handler(" ^ "effect=" ^ Fun.id r.effect_ ^ ", arguments=" ^ fk_show_list show_type r.arguments ^ ")"
        | TupleOf r -> "TupleOf(" ^ "elements=" ^ fk_show_list show_type r.elements ^ ")"
        | FunctionOf r -> "FunctionOf(" ^ "parameters=" ^ fk_show_list show_type r.parameters ^ ", result=" ^ show_type r.result ^ ", effects=" ^ show_row r.effects ^ ")"
        | Effects r -> "Effects(" ^ "row=" ^ show_row r.row ^ ")"

      type scheme = { variables : type_variable list; template : type_ }

      let rec show_scheme (v : scheme) =
        "Scheme(" ^ "variables=" ^ fk_show_list show_type_variable v.variables ^ ", template=" ^ show_type v.template ^ ")"

      type _ Effect.t +=
        | Solving_fresh : unit -> type_variable Effect.t
        | Solving_solutionOf : type_variable -> type_ option Effect.t
        | Solving_solve : type_variable * type_ -> unit Effect.t

      type 'fk_answer solving_handler = { fresh : (type_variable -> 'fk_answer) -> 'fk_answer; solution_of : type_variable -> (type_ option -> 'fk_answer) -> 'fk_answer; solve : type_variable -> type_ -> (unit -> 'fk_answer) -> 'fk_answer }

      let handle_solving (h : 'fk_answer solving_handler) (f : unit -> 'fk_answer) : 'fk_answer =
        match f () with
        | v -> v
        | effect (Solving_fresh ()), k -> h.fresh (fun v -> Effect.Deep.continue k v)
        | effect (Solving_solutionOf x0), k -> h.solution_of x0 (fun v -> Effect.Deep.continue k v)
        | effect (Solving_solve (x0, x1)), k -> h.solve x0 x1 (fun v -> Effect.Deep.continue k v)

      module Types = struct
        let builtins =
          Collections.Maps.map_of [("Int", 0); ("Float", 0); ("Double", 0); ("String", 0); ("Boolean", 0); ("Unit", 0); ("Char", 0); ("Byte", 0); ("Nothing", 0); ("List", 1); ("Option", 1); ("Lazy", 1); ("Result", 2)]

        let pure =
          ({ labels = []; rest = None } : row)

        let rec resolved (t : type_) : type_ =
          match t with
          | Variable { variable = v } -> (match Effect.perform (Solving_solutionOf v) with
               | Some solution -> resolved solution
               | None -> t)
          | _ -> t

        let mutating =
          "fckt.lang.Mutating"

        let same_region (x : type_) (y : type_) : bool =
          match (x, y) with
          | (Variable { variable = v }, Variable { variable = w }) -> v = w
          | (Named { name = n; arguments = _; region = _ }, Named { name = m; arguments = _; region = _ }) -> n = m
          | _ -> false

        let same_effect (a : effect_label) (b : effect_label) : bool =
          if (a : effect_label).name <> (b : effect_label).name then false else if (a : effect_label).name <> mutating then true else (match ((a : effect_label).arguments, (b : effect_label).arguments) with
               | (x :: _, y :: _) -> let fk_arg1 = resolved x in
                   let fk_arg2 = resolved y in
                   same_region fk_arg1 fk_arg2
               | _ -> true)

        let rec flattened_into (labels : effect_label list) (done_ : effect_label list) (rest : type_variable option) : row =
          let found = List.fold_left (fun acc label -> if List.exists (fun it -> same_effect it label) acc then acc else acc @ [label]) done_ labels in
          match rest with
          | None -> ({ labels = found; rest = None } : row)
          | Some v -> match Effect.perform (Solving_solutionOf v) with
              | None -> ({ labels = found; rest = rest } : row)
              | Some (Effects { row = more }) -> flattened_into (more : row).labels found (more : row).rest
              | Some (Variable { variable = other }) -> flattened_into [] found (Some other)
              | Some _ -> ({ labels = found; rest = None } : row)

        let flattened (row : row) : row =
          flattened_into (row : row).labels [] (row : row).rest

        let effect_names (row : row) : string list =
          List.map (fun it -> (it : effect_label).name) (flattened row : row).labels

        let list_of (element : type_) : type_ =
          (Named { name = "List"; arguments = [element]; region = None } : type_)

        let row_of (names : string list) (rest : type_variable option) : row =
          ({ labels = List.map (fun it -> ({ name = it; arguments = [] } : effect_label)) (Lang.Lists.list_sorted names); rest = rest } : row)

        let rec variables_into (t : type_) (found : type_variable list) : type_variable list =
          match resolved t with
          | Variable { variable = v } -> if List.mem v found then found else found @ [v]
          | TypeParameter { name = _ } -> found
          | Named { name = _; arguments = arguments; region = region } -> (let in_arguments = List.fold_left (fun acc a -> variables_into a acc) found arguments in
               match region with
               | Some r -> variables_into r in_arguments
               | None -> in_arguments)
          | Abstract { name = _; arguments = arguments } -> List.fold_left (fun acc a -> variables_into a acc) found arguments
          | SpecOwnType { name = _; arguments = arguments } -> List.fold_left (fun acc a -> variables_into a acc) found arguments
          | ModuleValue { spec = _; arguments = arguments; own_types = _ } -> List.fold_left (fun acc a -> variables_into a acc) found arguments
          | Handler { effect_ = _; arguments = arguments } -> List.fold_left (fun acc a -> variables_into a acc) found arguments
          | TupleOf { elements = elements } -> List.fold_left (fun acc e -> variables_into e acc) found elements
          | FunctionOf { parameters = parameters; result = result; effects = effects } -> row_variables_into effects (variables_into result (List.fold_left (fun acc p -> variables_into p acc) found parameters))
          | Effects { row = row } -> row_variables_into row found
        and row_variables_into (row : row) (found : type_variable list) : type_variable list =
          let flat = flattened row in
          let in_labels = List.fold_left (fun acc label -> List.fold_left (fun inner a -> variables_into a inner) acc (label : effect_label).arguments) found (flat : row).labels in
          match (flat : row).rest with
          | Some v -> if List.mem v in_labels then in_labels else in_labels @ [v]
          | None -> in_labels

        let variables_in (t : type_) : type_variable list =
          variables_into t []

        let rec substitute (t : type_) (mapping : (type_variable, type_) Collections.Maps.map) : type_ =
          match resolved t with
          | Variable { variable = v } -> Collections.Maps.map_get_or_default mapping v (Variable { variable = v } : type_)
          | TypeParameter { name = name } -> (TypeParameter { name = name } : type_)
          | Named { name = name; arguments = arguments; region = region } -> let fk_arg1 = List.map (fun it -> substitute it mapping) arguments in
              let fk_arg2 = Option.map (fun it -> substitute it mapping) region in
              (Named { name = name; arguments = fk_arg1; region = fk_arg2 } : type_)
          | Abstract { name = name; arguments = arguments } -> (Abstract { name = name; arguments = List.map (fun it -> substitute it mapping) arguments } : type_)
          | SpecOwnType { name = name; arguments = arguments } -> (SpecOwnType { name = name; arguments = List.map (fun it -> substitute it mapping) arguments } : type_)
          | ModuleValue { spec = spec; arguments = arguments; own_types = own } -> (ModuleValue { spec = spec; arguments = List.map (fun it -> substitute it mapping) arguments; own_types = own } : type_)
          | Handler { effect_ = effect_; arguments = arguments } -> (Handler { effect_ = effect_; arguments = List.map (fun it -> substitute it mapping) arguments } : type_)
          | TupleOf { elements = elements } -> (TupleOf { elements = List.map (fun it -> substitute it mapping) elements } : type_)
          | FunctionOf { parameters = parameters; result = result; effects = effects } -> let fk_arg1 = List.map (fun it -> substitute it mapping) parameters in
              let fk_arg2 = substitute result mapping in
              let fk_arg3 = substitute_row effects mapping in
              (FunctionOf { parameters = fk_arg1; result = fk_arg2; effects = fk_arg3 } : type_)
          | Effects { row = row } -> (Effects { row = substitute_row row mapping } : type_)
        and substitute_row (row : row) (mapping : (type_variable, type_) Collections.Maps.map) : row =
          let flat = flattened row in
          let labels = List.map (fun it -> ({ name = (it : effect_label).name; arguments = List.map (fun a -> substitute a mapping) (it : effect_label).arguments } : effect_label)) (flat : row).labels in
          match (flat : row).rest with
          | None -> ({ labels = labels; rest = None } : row)
          | Some v -> match Collections.Maps.map_get mapping v with
              | None -> ({ labels = labels; rest = Some v } : row)
              | Some (Variable { variable = w }) -> ({ labels = labels; rest = Some w } : row)
              | Some (Effects { row = more }) -> flattened ({ labels = labels @ (more : row).labels; rest = (more : row).rest } : row)
              | Some _ -> ({ labels = labels; rest = None } : row)

        let instantiate (scheme : scheme) (given : (type_variable, type_) Collections.Maps.map) : type_ =
          if List.is_empty (scheme : scheme).variables then (scheme : scheme).template else substitute (scheme : scheme).template (Collections.Maps.list_tuple_to_map (List.map (fun v -> (v, Collections.Maps.map_get_or_else given v (fun () -> (Variable { variable = Effect.perform (Solving_fresh ()) } : type_)))) (scheme : scheme).variables))

        let instantiate_default_given () : (type_variable, type_) Collections.Maps.map =
          Collections.Maps.empty_map ()

        let unit =
          (Named { name = "Unit"; arguments = []; region = None } : type_)

        let rec resolved_fully (t : type_) : type_ =
          match resolved t with
          | Variable { variable = v } -> (Variable { variable = v } : type_)
          | TypeParameter { name = name } -> (TypeParameter { name = name } : type_)
          | Named { name = name; arguments = arguments; region = region } -> let fk_arg1 = List.map (fun it -> resolved_fully it) arguments in
              let fk_arg2 = Option.map (fun it -> resolved_fully it) region in
              (Named { name = name; arguments = fk_arg1; region = fk_arg2 } : type_)
          | Abstract { name = name; arguments = arguments } -> (Abstract { name = name; arguments = List.map (fun it -> resolved_fully it) arguments } : type_)
          | SpecOwnType { name = name; arguments = arguments } -> (SpecOwnType { name = name; arguments = List.map (fun it -> resolved_fully it) arguments } : type_)
          | ModuleValue { spec = spec; arguments = arguments; own_types = own } -> (ModuleValue { spec = spec; arguments = List.map (fun it -> resolved_fully it) arguments; own_types = own } : type_)
          | Handler { effect_ = effect_; arguments = arguments } -> (Handler { effect_ = effect_; arguments = List.map (fun it -> resolved_fully it) arguments } : type_)
          | TupleOf { elements = elements } -> (TupleOf { elements = List.map (fun it -> resolved_fully it) elements } : type_)
          | FunctionOf { parameters = parameters; result = result; effects = effects } -> let fk_arg1 = List.map (fun it -> resolved_fully it) parameters in
              let fk_arg2 = resolved_fully result in
              let fk_arg3 = resolved_row_fully effects in
              (FunctionOf { parameters = fk_arg1; result = fk_arg2; effects = fk_arg3 } : type_)
          | Effects { row = row } -> (Effects { row = resolved_row_fully row } : type_)
        and resolved_row_fully (row : row) : row =
          let flat = flattened row in
          ({ labels = List.map (fun it -> ({ name = (it : effect_label).name; arguments = List.map (fun a -> resolved_fully a) (it : effect_label).arguments } : effect_label)) (flat : row).labels; rest = (flat : row).rest } : row)

        let is_named (t : type_) (name : string) : bool =
          match t with
          | Named { name = n; arguments = _; region = _ } -> n = name
          | _ -> false

        let result_of (value : type_) (error : type_) : type_ =
          (Named { name = "Result"; arguments = [value; error]; region = None } : type_)

        let option_of (element : type_) : type_ =
          (Named { name = "Option"; arguments = [element]; region = None } : type_)

        let string =
          (Named { name = "String"; arguments = []; region = None } : type_)

        let boolean =
          (Named { name = "Boolean"; arguments = []; region = None } : type_)

        let as_row (t : type_) : row =
          match resolved t with
          | Effects { row = row } -> flattened row
          | Variable { variable = v } -> ({ labels = []; rest = Some v } : row)
          | _ -> pure

        let float =
          (Named { name = "Float"; arguments = []; region = None } : type_)

        let int =
          (Named { name = "Int"; arguments = []; region = None } : type_)

        let char =
          (Named { name = "Char"; arguments = []; region = None } : type_)

        let global_region =
          (Named { name = "global region"; arguments = []; region = None } : type_)

        let byte =
          (Named { name = "Byte"; arguments = []; region = None } : type_)

        let nothing =
          (Named { name = "Nothing"; arguments = []; region = None } : type_)

        let lazy_of (element : type_) : type_ =
          (Named { name = "Lazy"; arguments = [element]; region = None } : type_)
      end

      module Solutions = struct
        let solving (block : unit -> _) : _ =
          let made = ref 0 in
          let solutions = ref (Collections.Maps.empty_map ()) in
          handle_solving ({ fresh = (fun k -> k ((fun () -> made := ! made + 1;
                 ({ id = ! made } : type_variable)) ())); solution_of = (fun x0 k -> k ((fun variable -> Collections.Maps.map_get (! solutions) variable) x0)); solve = (fun x0 x1 k -> k ((fun variable t -> solutions := Collections.Maps.map_put (! solutions) variable t;
                 ()) x0 x1)) } : _ solving_handler) (fun () -> block ())
      end

      let type_module_value_default_own_types () : string list =
        []

      module TypeText = struct
        type naming = { mutable named : type_variable list }

        let rec show_naming (v : naming) =
          "Naming(" ^ "named=" ^ fk_show_list show_type_variable v.named ^ ")"

        let name_of (v : type_variable) (naming : naming) : string =
          match Lang.Lists.list_index_of (naming : naming).named v with
          | (-1) -> naming.named <- (naming : naming).named @ [v];
              "T" ^ string_of_int (List.length (naming : naming).named)
          | _ -> "T" ^ string_of_int (Lang.Lists.list_index_of (naming : naming).named v + 1)

        let last_part (name : string) : string =
          Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".")) ~default:name

        let rec render (t : type_) (naming : naming) : string =
          match Types.resolved t with
          | Variable { variable = v } -> name_of v naming
          | TypeParameter { name = name } -> name
          | Named { name = name; arguments = arguments; region = _ } -> applied name arguments naming
          | Abstract { name = name; arguments = arguments } -> applied name arguments naming
          | SpecOwnType { name = name; arguments = arguments } -> applied name arguments naming
          | ModuleValue { spec = spec; arguments = arguments; own_types = [] } -> applied spec arguments naming
          | ModuleValue { spec = spec; arguments = arguments; own_types = own } -> spec ^ "<" ^ String.concat ", " (List.map Fun.id (List.map (fun (name, a) -> name ^ " = " ^ render a naming) (Lang.Lists.list_zip own arguments))) ^ ">"
          | Handler { effect_ = effect_; arguments = _ } -> "a handler for @" ^ last_part effect_
          | TupleOf { elements = elements } -> "(" ^ render_all elements naming ^ ")"
          | FunctionOf { parameters = parameters; result = result; effects = effects } -> let does = String.concat "" (List.map Fun.id (List.map (fun it -> "@" ^ last_part it ^ " ") (Lang.Lists.list_sorted (Types.effect_names effects)))) in
              let fk_arg1 = render_all parameters naming in
              let fk_arg2 = render result naming in
              does ^ "(" ^ fk_arg1 ^ ") -> " ^ fk_arg2
          | Effects { row = row } -> let flat = Types.flattened row in
              let labels = List.map (fun it -> "@" ^ last_part (it : effect_label).name) (flat : row).labels in
              let rest = match (flat : row).rest with
                | Some v -> ["@" ^ name_of v naming]
                | None -> [] in
              match labels @ rest with
              | [] -> "@Pure"
              | all -> String.concat " " (List.map Fun.id all)
        and applied (name : string) (arguments : type_ list) (naming : naming) : string =
          if List.is_empty arguments then name else name ^ "<" ^ render_all arguments naming ^ ">"
        and render_all (types : type_ list) (naming : naming) : string =
          String.concat ", " (List.map Fun.id (List.map (fun it -> render it naming) types))

        let shown (t : type_) : string =
          render t ({ named = [] } : naming)

        let shown_together (types : type_ list) : string list =
          let naming = ({ named = [] } : naming) in
          List.map (fun it -> render it naming) types
      end

      module Unification = struct
        let bind (v : type_variable) (t : type_) : bool =
          if List.mem v (Types.variables_in t) then false else (Effect.perform (Solving_solve (v, t));
             true)

        let rec unify (a : type_) (b : type_) : bool =
          let fk_arg1 = Types.resolved a in
          let fk_arg2 = Types.resolved b in
          unify_resolved fk_arg1 fk_arg2
        and unify_resolved (x : type_) (y : type_) : bool =
          match (x, y) with
          | (Variable { variable = v }, Variable { variable = w }) -> v = w || bind v y
          | (Effects { row = r }, Effects { row = s }) -> unify_rows r s
          | (Variable { variable = v }, Effects { row = s }) -> unify_rows ({ labels = []; rest = Some v } : row) s
          | (Effects { row = r }, Variable { variable = w }) -> unify_rows r ({ labels = []; rest = Some w } : row)
          | (Variable { variable = v }, _) -> bind v y
          | (_, Variable { variable = w }) -> bind w x
          | (TypeParameter { name = n }, TypeParameter { name = m }) -> n = m
          | (Named { name = n; arguments = xs; region = x_region }, Named { name = m; arguments = ys; region = y_region }) -> (n = m && unify_all xs ys) && (match (x_region, y_region) with
               | (Some p, Some q) -> unify p q
               | _ -> true)
          | (Abstract { name = n; arguments = xs }, Abstract { name = m; arguments = ys }) -> n = m && unify_all xs ys
          | (SpecOwnType { name = n; arguments = xs }, SpecOwnType { name = m; arguments = ys }) -> n = m && unify_all xs ys
          | (ModuleValue { spec = n; arguments = xs; own_types = _ }, ModuleValue { spec = m; arguments = ys; own_types = _ }) -> n = m && unify_all xs ys
          | (Handler { effect_ = n; arguments = xs }, Handler { effect_ = m; arguments = ys }) -> n = m && unify_all xs ys
          | (TupleOf { elements = xs }, TupleOf { elements = ys }) -> unify_all xs ys
          | (FunctionOf { parameters = xs; result = x_result; effects = x_effects }, FunctionOf { parameters = ys; result = y_result; effects = y_effects }) -> (unify_all xs ys && unify x_result y_result) && unify_rows x_effects y_effects
          | _ -> false
        and unify_all (xs : type_ list) (ys : type_ list) : bool =
          match (xs, ys) with
          | ([], []) -> true
          | (x :: more_x, y :: more_y) -> unify x y && unify_all more_x more_y
          | _ -> false
        and unify_rows (a : row) (b : row) : bool =
          let x = Types.flattened a in
          let y = Types.flattened b in
          let only_x = List.filter (fun e -> Lang.Lists.list_none (y : row).labels (fun it -> Types.same_effect it e)) (x : row).labels in
          let only_y = List.filter (fun e -> Lang.Lists.list_none (x : row).labels (fun it -> Types.same_effect it e)) (y : row).labels in
          same_arguments (x : row).labels (y : row).labels && (match ((x : row).rest, (y : row).rest) with
           | (None, None) -> List.is_empty only_x && List.is_empty only_y
           | (Some v, Some w) -> if v = w then List.is_empty only_x && List.is_empty only_y else (let rest = Effect.perform (Solving_fresh ()) in
                  bind v (Effects { row = ({ labels = only_y; rest = Some rest } : row) } : type_) && bind w (Effects { row = ({ labels = only_x; rest = Some rest } : row) } : type_))
           | (None, Some w) -> List.is_empty only_y && bind w (Effects { row = ({ labels = only_x; rest = None } : row) } : type_)
           | (Some v, None) -> List.is_empty only_x && bind v (Effects { row = ({ labels = only_y; rest = None } : row) } : type_))
        and same_arguments (xs : effect_label list) (ys : effect_label list) : bool =
          match xs with
          | [] -> true
          | label :: more -> let generic = (label : effect_label).name <> Types.mutating && Lang.Lists.list_is_not_empty (label : effect_label).arguments in
              let counterpart = List.filter (fun it -> (it : effect_label).name = (label : effect_label).name && (let fk_arg1 = List.length (it : effect_label).arguments in
                    let fk_arg2 = List.length (label : effect_label).arguments in
                    fk_arg1 = fk_arg2)) ys in
              match counterpart with
              | other :: _ when generic -> unify_all (label : effect_label).arguments (other : effect_label).arguments && same_arguments more ys
              | _ -> same_arguments more ys
      end
    end

    module Symbols = struct
      type call_in = { at : Parser.position; callee : Parser.expression; arguments : Parser.argument list }

      let rec show_call_in (v : call_in) =
        "CallIn(" ^ "at=" ^ Parser.show_position v.at ^ ", callee=" ^ Parser.show_expression v.callee ^ ", arguments=" ^ fk_show_list Parser.show_argument v.arguments ^ ")"

      type symbol = { name : string; path : string list; declaration : Parser.declaration; file : Sources.loaded_file }

      let rec show_symbol (v : symbol) =
        "Symbol(" ^ "name=" ^ Fun.id v.name ^ ", path=" ^ fk_show_list Fun.id v.path ^ ", declaration=" ^ Parser.show_declaration v.declaration ^ ", file=" ^ Sources.show_loaded_file v.file ^ ")"

      type case_symbol = { name : string; owner : symbol; definition : Parser.case_definition }

      let rec show_case_symbol (v : case_symbol) =
        "CaseSymbol(" ^ "name=" ^ Fun.id v.name ^ ", owner=" ^ show_symbol v.owner ^ ", definition=" ^ Parser.show_case_definition v.definition ^ ")"

      type module_symbol =
        | PackageModule of { name : string }
        | DeclaredModule of { symbol : symbol }

      let rec show_module_symbol (v : module_symbol) =
        match v with
        | PackageModule r -> "PackageModule(" ^ "name=" ^ Fun.id r.name ^ ")"
        | DeclaredModule r -> "DeclaredModule(" ^ "symbol=" ^ show_symbol r.symbol ^ ")"

      type symbol_table = { modules : (string, module_symbol) Collections.Maps.map; records : (string, symbol) Collections.Maps.map; case_types : (string, symbol) Collections.Maps.map; aliases : (string, symbol) Collections.Maps.map; annotation_types : (string, symbol) Collections.Maps.map; specs : (string, symbol) Collections.Maps.map; functions : (string, symbol) Collections.Maps.map; cases : (string, case_symbol) Collections.Maps.map; declarations : symbol list; file_private : bool }

      let rec show_symbol_table (v : symbol_table) =
        "SymbolTable(" ^ "modules=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_module_symbol) v.modules ^ ", records=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_symbol) v.records ^ ", caseTypes=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_symbol) v.case_types ^ ", aliases=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_symbol) v.aliases ^ ", annotationTypes=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_symbol) v.annotation_types ^ ", specs=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_symbol) v.specs ^ ", functions=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_symbol) v.functions ^ ", cases=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_case_symbol) v.cases ^ ", declarations=" ^ fk_show_list show_symbol v.declarations ^ ", filePrivate=" ^ string_of_bool v.file_private ^ ")"

      module Symbols = struct
        type type_tables = { records : (string, symbol) Collections.Maps.map; case_types : (string, symbol) Collections.Maps.map; aliases : (string, symbol) Collections.Maps.map; annotation_types : (string, symbol) Collections.Maps.map }

        let rec show_type_tables (v : type_tables) =
          "TypeTables(" ^ "records=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_symbol) v.records ^ ", caseTypes=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_symbol) v.case_types ^ ", aliases=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_symbol) v.aliases ^ ", annotationTypes=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_symbol) v.annotation_types ^ ")"

        let last_part (name : string) : string =
          Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".")) ~default:name

        let rec mangled (t : Parser.type_ref) (type_parameters : string list) : string =
          match t with
          | Parser.NamedType { at = _; name = name; arguments = arguments } -> if List.mem name type_parameters then "" else (let fk_arg1 = last_part name in
                 let fk_arg2 = String.concat "" (List.map Fun.id (List.map (fun it -> mangled it type_parameters) arguments)) in
                 fk_arg1 ^ fk_arg2)
          | Parser.TupleType { at = _; elements = elements } -> "Tuple" ^ String.concat "" (List.map Fun.id (List.map (fun it -> mangled it type_parameters) elements))
          | Parser.FunctionType { at = _; parameters = _; result = _; effects = _ } -> "Function"
          | Parser.EffectsType { at = _; effects = _ } -> ""
          | Parser.GivenType { at = _; name = _; given = given } -> mangled given type_parameters

        let own_name (d : Parser.declaration) : string =
          match (d : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = type_parameters; receiver = Some receiver; parameters = _; result = _; body = _; external_ = _; operator = _ } -> mangled receiver type_parameters ^ "$" ^ (d : Parser.declaration).Parser.name
          | _ -> (d : Parser.declaration).Parser.name

        let path_of (name : string) : string list =
          Lang.Lists.list_drop_last ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".") 1

        let file_name (path : string) : string =
          Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) path "/")) ~default:path

        let is_file_own (s : symbol) (path : string) : bool =
          let lower_case_file = Option.value (Option.map (fun it -> Lang.Strings.char_is_lower_case it) (List.nth_opt ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) (file_name path)) 0)) ~default:false in
          let own_kind = match ((s : symbol).declaration : Parser.declaration).Parser.definition with
            | Parser.FunctionDefinition { type_parameters = _; receiver = None; parameters = _; result = _; body = _; external_ = _; operator = _ } -> true
            | Parser.RecordDefinition { type_parameters = _; fields = _; private_constructor = _; annotation = _; external_ = _ } -> true
            | Parser.CasesDefinition { type_parameters = _; cases = _; case_refs = _; includes = _ } -> true
            | Parser.AliasDefinition { type_parameters = _; target = _ } -> true
            | _ -> false in
          ((((s : symbol).declaration : Parser.declaration).Parser.visibility = (Parser.Private : Parser.visibility) && lower_case_file) && own_kind) && (s : symbol).path = ((s : symbol).file : Sources.loaded_file).Sources.package

        let file_private_name (name : string) (path : string) : string =
          let parts = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) (file_name path) "." in
          let stem = String.concat "." (List.map Fun.id (if List.length parts > 1 then Lang.Lists.list_drop_last parts 1 else parts)) in
          (name ^ "'") ^ String.concat "" (List.map Fun.id (List.map (fun c -> if Lang.Strings.char_is_letter_or_digit c || c = 95 then fk_show_char c else "_") ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) stem)))

        let file_private (symbols : symbol list) : symbol list =
          let counts = List.fold_left (fun m s -> Collections.Maps.map_put m (s : symbol).name (Collections.Maps.map_get_or_default m (s : symbol).name 0 + 1)) (Collections.Maps.empty_map ()) symbols in
          List.map (fun s -> match (((s : symbol).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path with
             | Some path when Collections.Maps.map_get_or_default counts (s : symbol).name 0 > 1 && is_file_own s path -> { (s : symbol) with name = file_private_name (s : symbol).name path }
             | _ -> s) symbols

        let ordered (workspace : Sources.workspace) : Sources.loaded_file list =
          match (workspace : Sources.workspace).Sources.files with
          | [] -> []
          | own :: others -> others @ [own]

        let rec symbols_in (declarations : Parser.declaration list) (prefix : string) (file : Sources.loaded_file) (borrowed : (string, Sources.loaded_file) Collections.Maps.map) : symbol list =
          List.concat_map (fun d -> let name = prefix ^ own_name d in
             let symbol = let fk_arg1 = path_of name in
               let fk_arg2 = Collections.Maps.map_get_or_default borrowed name file in
               ({ name = name; path = fk_arg1; declaration = d; file = fk_arg2 } : symbol) in
             match (d : Parser.declaration).Parser.definition with
             | Parser.ModuleDefinition { declarations = inside; spec = _; parameters = _; application = _; type_parameters = _ } -> symbol :: symbols_in inside (name ^ ".") file borrowed
             | _ -> [symbol]) declarations

        let prefix_of (pkg : string list) : string =
          if List.is_empty pkg then "" else String.concat "." (List.map Fun.id pkg) ^ "."

        let declarations (workspace : Sources.workspace) : symbol list =
          file_private (List.concat_map (fun file -> symbols_in (file : Sources.loaded_file).Sources.declarations (prefix_of (file : Sources.loaded_file).Sources.package) file (workspace : Sources.workspace).Sources.borrowed) (ordered workspace))

        let is_function (s : symbol) : bool =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = _; operator = _ } -> true
          | _ -> false

        let is_spec (s : symbol) : bool =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = _; values = _; type_parameters = _; copy_of = _; parents = _ } -> true
          | _ -> false

        let simple_name (symbol : symbol) : string =
          Option.value (List.nth_opt ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) (last_part (symbol : symbol).name) "'") 0) ~default:""

        let is_module (s : symbol) : bool =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _; application = _; type_parameters = _ } -> true
          | _ -> false

        let module_name (m : module_symbol) : string =
          match m with
          | PackageModule { name = name } -> name
          | DeclaredModule { symbol = symbol } -> (symbol : symbol).name

        let at (symbol : symbol) (message : string) : Diagnostics.diagnostic =
          ({ Diagnostics.file = (((symbol : symbol).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((symbol : symbol).declaration : Parser.declaration).Parser.at; message = message } : Diagnostics.diagnostic)

        let module_table (packages : module_symbol list) (declared : symbol list) : (string, module_symbol) Collections.Maps.map =
          let modules = List.map (fun it -> (DeclaredModule { symbol = it } : module_symbol)) (List.filter (fun it -> is_module it) declared) in
          List.fold_left (fun table m -> let name = module_name m in
             match m with
             | DeclaredModule { symbol = symbol } when Collections.Maps.map_contains_key table name -> (match Effect.perform (Diagnostics.Abandoning_abandon (at symbol ("module '" ^ simple_name symbol ^ "' is declared twice"))) with
                  | _ -> (assert false))
             | _ -> Collections.Maps.map_put table name m) (Collections.Maps.empty_map ()) (packages @ modules)

        let uniquely (symbols : symbol list) (duplicate : symbol -> string) : (string, symbol) Collections.Maps.map =
          List.fold_left (fun table symbol -> if Collections.Maps.map_contains_key table (symbol : symbol).name then (match Effect.perform (Diagnostics.Abandoning_abandon (at symbol (duplicate symbol))) with
                | _ -> (assert false)) else Collections.Maps.map_put table (symbol : symbol).name symbol) (Collections.Maps.empty_map ()) symbols

        let is_record (s : symbol) : bool =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.RecordDefinition { type_parameters = _; fields = _; private_constructor = _; annotation = _; external_ = _ } -> true
          | _ -> false

        let is_case_type (s : symbol) : bool =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.CasesDefinition { type_parameters = _; cases = _; case_refs = _; includes = _ } -> true
          | _ -> false

        let is_alias (s : symbol) : bool =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.AliasDefinition { type_parameters = _; target = _ } -> true
          | _ -> false

        let is_type (s : symbol) : bool =
          (is_record s || is_case_type s) || is_alias s

        let check_cases (symbol : symbol) : unit =
          match ((symbol : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.CasesDefinition { type_parameters = _; cases = []; case_refs = []; includes = [] } -> (match Effect.perform (Diagnostics.Abandoning_abandon (at symbol ("type '" ^ simple_name symbol ^ "' has no cases"))) with
               | _ -> (assert false))
          | Parser.CasesDefinition { type_parameters = _; cases = cases; case_refs = _; includes = _ } -> List.iter (fun c -> if (c : Parser.case_definition).Parser.name = "Some" || (c : Parser.case_definition).Parser.name = "None" then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((symbol : symbol).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (c : Parser.case_definition).Parser.at; message = "'" ^ (c : Parser.case_definition).Parser.name ^ "' is reserved for Option" } : Diagnostics.diagnostic)) with
                    | _ -> (assert false)) else ()) cases
          | _ -> ()

        let rec check_type_names (types : symbol list) (seen : string list) : unit =
          match types with
          | [] -> ()
          | symbol :: rest -> let own = simple_name symbol in
              if Collections.Maps.map_contains_key Types.Types.builtins own then (match Effect.perform (Diagnostics.Abandoning_abandon (at symbol ("'" ^ own ^ "' is a built-in type"))) with
                 | _ -> (assert false)) else if List.mem (symbol : symbol).name seen then (match Effect.perform (Diagnostics.Abandoning_abandon (at symbol ("type '" ^ own ^ "' is declared twice"))) with
                   | _ -> (assert false)) else (check_cases symbol;
                   check_type_names rest (seen @ [(symbol : symbol).name]))

        let by_name (symbols : symbol list) : (string, symbol) Collections.Maps.map =
          Collections.Maps.list_tuple_to_map (List.map (fun it -> ((it : symbol).name, it)) symbols)

        let is_annotation (s : symbol) : bool =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.RecordDefinition { type_parameters = _; fields = _; private_constructor = _; annotation = annotation; external_ = _ } -> annotation
          | _ -> false

        let cases_of (symbol : symbol) : Parser.case_definition list =
          match ((symbol : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.CasesDefinition { type_parameters = _; cases = cases; case_refs = _; includes = _ } -> cases
          | _ -> []

        let check_case_names (tables : type_tables) : unit =
          List.iter (fun entry -> let (_, owner) = entry in
             let cases = cases_of owner in
             List.iter (fun c -> if Collections.Maps.map_contains_key (tables : type_tables).records (String.concat "." (List.map Fun.id ((owner : symbol).path @ [(c : Parser.case_definition).Parser.name]))) then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((owner : symbol).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (c : Parser.case_definition).Parser.at; message = "'" ^ (c : Parser.case_definition).Parser.name ^ "' is both a type and a variant" } : Diagnostics.diagnostic)) with
                   | _ -> (assert false)) else ()) cases;
             List.iteri (fun i c -> if List.exists (fun it -> (it : Parser.case_definition).Parser.name = (c : Parser.case_definition).Parser.name) (List.take i cases) then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((owner : symbol).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (c : Parser.case_definition).Parser.at; message = "variant '" ^ (c : Parser.case_definition).Parser.name ^ "' is declared twice in " ^ (owner : symbol).name } : Diagnostics.diagnostic)) with
                   | _ -> (assert false)) else ()) cases) (Collections.Maps.map_to_list (tables : type_tables).case_types)

        let type_tables (declared : symbol list) : type_tables =
          let types = List.filter (fun it -> is_type it) declared in
          check_type_names types [];
          let tables = let fk_arg1 = by_name (List.filter (fun it -> is_record it && not (is_annotation it)) types) in
            let fk_arg2 = by_name (List.filter (fun it -> is_case_type it) types) in
            let fk_arg3 = by_name (List.filter (fun it -> is_alias it) types) in
            let fk_arg4 = by_name (List.filter (fun it -> is_annotation it) types) in
            ({ records = fk_arg1; case_types = fk_arg2; aliases = fk_arg3; annotation_types = fk_arg4 } : type_tables) in
          check_case_names tables;
          tables

        let function_table (declared : symbol list) : (string, symbol) Collections.Maps.map =
          let fk_arg1 = List.filter (fun it -> is_function it) declared in
          let fk_arg2 = Collections.Maps.empty_map () in
          List.fold_left (fun table symbol -> if not (Collections.Maps.map_contains_key table (symbol : symbol).name) then Collections.Maps.map_put table (symbol : symbol).name symbol else (match ((symbol : symbol).declaration : Parser.declaration).Parser.definition with
                | Parser.FunctionDefinition { type_parameters = _; receiver = Some receiver; parameters = _; result = _; body = _; external_ = _; operator = _ } -> (match Effect.perform (Diagnostics.Abandoning_abandon (at symbol ("'" ^ ((symbol : symbol).declaration : Parser.declaration).Parser.name ^ "' is declared twice for " ^ Diagnostics.Written.type_ref receiver))) with
                     | _ -> (assert false))
                | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (at symbol ("'" ^ simple_name symbol ^ "' is declared twice"))) with
                    | _ -> (assert false))) fk_arg2 fk_arg1

        let case_table (types : type_tables) : (string, case_symbol) Collections.Maps.map =
          Collections.Maps.list_tuple_to_map (List.concat_map (fun entry -> let (name, owner) = entry in
              List.map (fun c -> (name ^ "." ^ (c : Parser.case_definition).Parser.name, ({ name = name ^ "." ^ (c : Parser.case_definition).Parser.name; owner = owner; definition = c } : case_symbol))) (cases_of owner)) (Collections.Maps.map_to_list (types : type_tables).case_types))

        let table_of (declared : symbol list) (packages : module_symbol list) : symbol_table =
          let modules = module_table packages declared in
          let specs = uniquely (List.filter (fun it -> is_spec it) declared) (fun s -> "spec '" ^ simple_name s ^ "' is declared twice") in
          let types = type_tables declared in
          let functions = function_table declared in
          let fk_arg1 = case_table types in
          let fk_arg2 = List.exists (fun it -> Lang.Strings.string_contains (it : symbol).name "'") declared in
          ({ modules = modules; records = (types : type_tables).records; case_types = (types : type_tables).case_types; aliases = (types : type_tables).aliases; annotation_types = (types : type_tables).annotation_types; specs = specs; functions = functions; cases = fk_arg1; declarations = declared; file_private = fk_arg2 } : symbol_table)

        let rebuilt (table : symbol_table) (declarations : symbol list) : symbol_table =
          table_of declarations (Lang.Lists.list_map_not_null (Collections.Maps.map_to_list (table : symbol_table).modules) (fun (_, m) -> match m with
              | PackageModule { name = _ } -> Some m
              | DeclaredModule { symbol = _ } -> None))

        let prefixes (pkg : string list) : string list list =
          List.mapi (fun i _ -> List.take (i + 1) pkg) pkg

        let table (workspace : Sources.workspace) : symbol_table =
          let packages = List.map (fun pkg -> (PackageModule { name = String.concat "." (List.map Fun.id pkg) } : module_symbol)) (Lang.Lists.list_distinct (List.concat_map (fun pkg -> prefixes pkg) (List.filter (fun it -> Lang.Lists.list_is_not_empty it) (List.map (fun it -> (it : Sources.loaded_file).Sources.package) (workspace : Sources.workspace).Sources.files)))) in
          table_of (declarations workspace) packages
      end

      module Positions = struct
        let of_type (t : Parser.type_ref) : Parser.position =
          match t with
          | Parser.NamedType { at = at; name = _; arguments = _ } -> at
          | Parser.FunctionType { at = at; parameters = _; result = _; effects = _ } -> at
          | Parser.TupleType { at = at; elements = _ } -> at
          | Parser.EffectsType { at = at; effects = _ } -> at
          | Parser.GivenType { at = at; name = _; given = _ } -> at

        let of_ (e : Parser.expression) : Parser.position =
          match e with
          | Parser.Compiled { at = at } -> at
          | Parser.IntConstant { at = at; value = _ } -> at
          | Parser.FloatConstant { at = at; value = _ } -> at
          | Parser.BooleanConstant { at = at; value = _ } -> at
          | Parser.CharConstant { at = at; value = _ } -> at
          | Parser.StringTemplate { at = at; parts = _ } -> at
          | Parser.Name { at = at; name = _ } -> at
          | Parser.Tuple { at = at; elements = _ } -> at
          | Parser.ListOf { at = at; items = _ } -> at
          | Parser.Spread { at = at; list = _ } -> at
          | Parser.Call { at = at; callee = _; arguments = _; type_arguments = _ } -> at
          | Parser.Member { at = at; target = _; name = _ } -> at
          | Parser.Binary { at = at; operator = _; left = _; right = _ } -> at
          | Parser.Unary { at = at; operator = _; operand = _ } -> at
          | Parser.Assign { at = at; target = _; value = _ } -> at
          | Parser.Lambda { at = at; parameters = _; body = _; ignores_arguments = _ } -> at
          | Parser.Pipe { at = at; value = _; function_ = _ } -> at
          | Parser.If { at = at; condition = _; then_ = _; otherwise = _; has_else = _ } -> at
          | Parser.When { at = at; subject = _; branches = _ } -> at
          | Parser.Block { at = at; statements = _; result = _; ends_in_binding = _ } -> at
          | Parser.Monadic { at = at; monad = _; block = _ } -> at
          | Parser.Handle { at = at; handler = _; block = _; parameters = _ } -> at
      end

      let symbol_table_default_file_private () : bool =
        false

      module Signatures = struct
        let body_of (s : symbol) : Parser.expression option =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = body; external_ = _; operator = _ } -> Some body
          | _ -> None

        let written_parameters_of (s : symbol) : Parser.parameter list option =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = parameters; result = _; body = _; external_ = _; operator = _ } -> parameters
          | _ -> None

        let type_parameters_of (s : symbol) : string list =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = type_parameters; receiver = _; parameters = _; result = _; body = _; external_ = _; operator = _ } -> type_parameters
          | _ -> []

        let receiver_of (s : symbol) : Parser.type_ref option =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = receiver; parameters = _; result = _; body = _; external_ = _; operator = _ } -> receiver
          | _ -> None

        let is_extension (s : symbol) : bool =
          Option.is_some (receiver_of s)

        let method_name (s : symbol) : string =
          ((s : symbol).declaration : Parser.declaration).Parser.name

        let parameters_of (s : symbol) : Parser.parameter list option =
          match receiver_of s with
          | Some receiver -> Some (let fk_arg1 = let fk_arg1 = Parser.parameter_default_annotations () in
                 let fk_arg2 = Parser.parameter_default_default () in
                 ({ Parser.at = ((s : symbol).declaration : Parser.declaration).Parser.at; name = "this"; parameter_type = Some receiver; annotations = fk_arg1; default = fk_arg2 } : Parser.parameter) in
               let fk_arg2 = Option.value (written_parameters_of s) ~default:[] in
               fk_arg1 :: fk_arg2)
          | None -> written_parameters_of s

        let is_operator (s : symbol) : bool =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = _; operator = operator } -> operator
          | _ -> false

        let is_function (s : symbol) : bool =
          Option.is_some (parameters_of s)

        let result_of (s : symbol) : Parser.type_ref option =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = result; body = _; external_ = _; operator = _ } -> result
          | _ -> None

        let is_external (s : symbol) : bool =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = external_; operator = _ } -> Option.is_some external_
          | _ -> false

        let is_compiled (s : symbol) : bool =
          match ((s : symbol).declaration : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = Parser.Compiled { at = _ }; external_ = None; operator = _ } -> true
          | _ -> false

        let is_property (s : symbol) : bool =
          is_extension s && Option.is_none (written_parameters_of s)
      end

      module Calls = struct
        let rec of_ (e : Parser.expression) : call_in list =
          match e with
          | Parser.Call { at = at; callee = callee; arguments = arguments; type_arguments = _ } -> let fk_arg1 = of_ callee in
              let fk_arg2 = List.concat_map (fun it -> of_ (it : Parser.argument).Parser.value) arguments in
              ({ at = at; callee = callee; arguments = arguments } : call_in) :: (fk_arg1 @ fk_arg2)
          | Parser.Compiled { at = _ } -> []
          | Parser.IntConstant { at = _; value = _ } -> []
          | Parser.FloatConstant { at = _; value = _ } -> []
          | Parser.BooleanConstant { at = _; value = _ } -> []
          | Parser.CharConstant { at = _; value = _ } -> []
          | Parser.Name { at = _; name = _ } -> []
          | Parser.StringTemplate { at = _; parts = parts } -> List.concat_map (fun p -> match p with
                 | Parser.TemplateText { text = _ } -> []
                 | Parser.Interpolation { expression = inner } -> of_ inner) parts
          | Parser.Tuple { at = _; elements = elements } -> List.concat_map (fun it -> of_ it) elements
          | Parser.ListOf { at = _; items = items } -> List.concat_map (fun it -> of_ it) items
          | Parser.Spread { at = _; list = list } -> of_ list
          | Parser.Member { at = _; target = target; name = _ } -> of_ target
          | Parser.Binary { at = _; operator = _; left = left; right = right } -> let fk_arg1 = of_ left in
              let fk_arg2 = of_ right in
              fk_arg1 @ fk_arg2
          | Parser.Unary { at = _; operator = _; operand = operand } -> of_ operand
          | Parser.Assign { at = _; target = target; value = value } -> let fk_arg1 = of_ target in
              let fk_arg2 = of_ value in
              fk_arg1 @ fk_arg2
          | Parser.Lambda { at = _; parameters = _; body = body; ignores_arguments = _ } -> of_ body
          | Parser.Pipe { at = _; value = value; function_ = function_ } -> let fk_arg1 = of_ value in
              let fk_arg2 = of_ function_ in
              fk_arg1 @ fk_arg2
          | Parser.If { at = _; condition = condition; then_ = then_; otherwise = otherwise; has_else = _ } -> let fk_arg1 = let fk_arg1 = of_ condition in
                let fk_arg2 = of_ then_ in
                fk_arg1 @ fk_arg2 in
              let fk_arg2 = of_ otherwise in
              fk_arg1 @ fk_arg2
          | Parser.When { at = _; subject = subject; branches = branches } -> let fk_arg1 = List.concat_map (fun it -> of_ it) (Option.to_list subject) in
              let fk_arg2 = List.concat_map (fun b -> let fk_arg1 = let fk_arg1 = List.concat_map (fun it -> of_ it) (Option.to_list (b : Parser.branch).Parser.condition) in
                     let fk_arg2 = List.concat_map (fun it -> of_ it) (Option.to_list (b : Parser.branch).Parser.guard) in
                     fk_arg1 @ fk_arg2 in
                   let fk_arg2 = of_ (b : Parser.branch).Parser.body in
                   fk_arg1 @ fk_arg2) branches in
              fk_arg1 @ fk_arg2
          | Parser.Block { at = _; statements = statements; result = result; ends_in_binding = _ } -> let fk_arg1 = List.concat_map (fun s -> match s with
                   | Parser.Binding { at = _; name = _; parameters = _; value_type = _; value = value; variable = _ } -> of_ value
                   | Parser.Evaluation { at = _; expression = expression } -> of_ expression
                   | Parser.Destructuring { at = _; pattern = _; value = value } -> of_ value
                   | Parser.Bind { at = _; pattern = _; value = value } -> of_ value) statements in
              let fk_arg2 = of_ result in
              fk_arg1 @ fk_arg2
          | Parser.Monadic { at = _; monad = monad; block = block } -> let fk_arg1 = of_ monad in
              let fk_arg2 = of_ block in
              fk_arg1 @ fk_arg2
          | Parser.Handle { at = _; handler = handler; block = block; parameters = _ } -> let fk_arg1 = of_ handler in
              let fk_arg2 = of_ block in
              fk_arg1 @ fk_arg2
      end

      module References = struct
        let rec dotted (e : Parser.expression) : string option =
          match e with
          | Parser.Name { at = _; name = name } -> Some name
          | Parser.Member { at = _; target = target; name = name } -> Option.map (fun it -> it ^ "." ^ name) (dotted target)
          | _ -> None

        let operator_methods =
          [("+", "plus"); ("-", "minus"); ("*", "times"); ("/", "div"); ("%", "rem")]

        let range_methods =
          [("..", "rangeTo"); ("..<", "rangeUntil")]

        let unary_minus =
          "unaryMinus"

        let rec names_in (p : Parser.pattern) : string list =
          match p with
          | Parser.NamePattern { at = _; name = name } -> [name]
          | Parser.CasePattern { at = _; name = _; arguments = arguments; check = _; qualifier = _ } -> List.concat_map (fun it -> names_in it) (Option.value arguments ~default:[])
          | Parser.TuplePattern { at = _; elements = elements } -> List.concat_map (fun it -> names_in it) elements
          | Parser.ListPattern { at = _; elements = elements; rest = rest } -> let fk_arg1 = List.concat_map (fun it -> names_in it) elements in
              let fk_arg2 = Option.value (Option.map (fun it -> names_in it) rest) ~default:[] in
              fk_arg1 @ fk_arg2
          | Parser.Wildcard { at = _ } -> []
          | Parser.ConstantPattern { at = _; expression = _ } -> []

        let rec into (e : Parser.expression) (bound : string list) (found : string list) : string list =
          match e with
          | Parser.Name { at = _; name = name } -> if List.mem name bound then found else found @ [name]
          | Parser.Compiled { at = _ } -> found
          | Parser.IntConstant { at = _; value = _ } -> found
          | Parser.FloatConstant { at = _; value = _ } -> found
          | Parser.BooleanConstant { at = _; value = _ } -> found
          | Parser.CharConstant { at = _; value = _ } -> found
          | Parser.Tuple { at = _; elements = elements } -> into_all elements bound found
          | Parser.Spread { at = _; list = list } -> into list bound found
          | Parser.StringTemplate { at = _; parts = parts } -> List.fold_left (fun acc part -> match part with
                 | Parser.TemplateText { text = _ } -> acc
                 | Parser.Interpolation { expression = inner } -> into inner bound acc) found parts
          | Parser.ListOf { at = _; items = items } -> into_all items bound found
          | Parser.Call { at = _; callee = callee; arguments = arguments; type_arguments = _ } -> let fk_arg1 = List.map (fun it -> (it : Parser.argument).Parser.value) arguments in
              let fk_arg2 = into callee bound found in
              into_all fk_arg1 bound fk_arg2
          | Parser.Member { at = _; target = target; name = name } -> (let in_target = into target bound found @ ["." ^ name] in
               match dotted e with
               | Some d when not (List.mem (Option.value (List.nth_opt ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) d ".") 0) ~default:d) bound) -> in_target @ [d]
               | _ -> in_target)
          | Parser.Binary { at = _; operator = operator; left = left; right = right } -> (let operands = into right bound (into left bound found) in
               match List.assoc_opt operator (operator_methods @ range_methods) with
               | Some method_ -> operands @ ["operator " ^ method_]
               | None -> operands)
          | Parser.Unary { at = _; operator = operator; operand = operand } -> into operand bound found @ (if operator = "-" then ["operator " ^ unary_minus] else [])
          | Parser.Assign { at = _; target = target; value = value } -> into value bound (into target bound found)
          | Parser.Handle { at = _; handler = handler; block = block; parameters = parameters } -> let inner = bound @ Option.value (Option.map (fun ps -> List.map (fun it -> (it : Parser.parameter).Parser.name) ps) parameters) ~default:["it"] in
              into block inner (into handler bound found)
          | Parser.Lambda { at = _; parameters = parameters; body = body; ignores_arguments = _ } -> into body (bound @ List.map (fun it -> (it : Parser.parameter).Parser.name) parameters) found
          | Parser.Pipe { at = _; value = value; function_ = function_ } -> into function_ bound (into value bound found)
          | Parser.If { at = _; condition = condition; then_ = then_; otherwise = otherwise; has_else = _ } -> into_all [condition; then_; otherwise] bound found
          | Parser.When { at = _; subject = subject; branches = branches } -> List.fold_left (fun acc branch -> let names = bound @ List.concat_map (fun it -> names_in it) (branch : Parser.branch).Parser.patterns in
                 let with_condition = Option.value (Option.map (fun it -> into it bound acc) (branch : Parser.branch).Parser.condition) ~default:acc in
                 let with_guard = Option.value (Option.map (fun it -> into it names with_condition) (branch : Parser.branch).Parser.guard) ~default:with_condition in
                 into (branch : Parser.branch).Parser.body names with_guard) (Option.value (Option.map (fun it -> into it bound found) subject) ~default:found) branches
          | Parser.Block { at = _; statements = statements; result = result; ends_in_binding = _ } -> let (names, in_statements) = List.fold_left (fun acc statement -> let (b, f) = acc in
                   match statement with
                   | Parser.Binding { at = _; name = name; parameters = Some parameters; value_type = _; value = value; variable = _ } -> (b @ [name], into value ((b @ [name]) @ List.map (fun it -> (it : Parser.parameter).Parser.name) parameters) f)
                   | Parser.Binding { at = _; name = name; parameters = None; value_type = _; value = value; variable = _ } -> (b @ [name], into value b f)
                   | Parser.Evaluation { at = _; expression = expression } -> (b, into expression b f)
                   | Parser.Destructuring { at = _; pattern = pattern; value = value } -> let fk_arg1 = b @ names_in pattern in
                       let fk_arg2 = into value b f in
                       (fk_arg1, fk_arg2)
                   | Parser.Bind { at = _; pattern = pattern; value = value } -> let fk_arg1 = b @ names_in pattern in
                       let fk_arg2 = into value b f in
                       (fk_arg1, fk_arg2)) (bound, found) statements in
              into result names in_statements
          | Parser.Monadic { at = _; monad = monad; block = block } -> let with_monad = match dotted monad with
                | Some d when not (List.mem (Option.value (List.nth_opt ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) d ".") 0) ~default:d) bound) -> (found @ List.map (fun it -> d ^ "." ^ it) ["bind"; "pure"; "map"; "product"]) @ [d]
                | _ -> found in
              into block bound with_monad
        and into_all (es : Parser.expression list) (bound : string list) (found : string list) : string list =
          List.fold_left (fun acc e -> into e bound acc) found es

        let of_ (e : Parser.expression) (bound : string list) : string list =
          Lang.Lists.list_distinct (into e bound [])
      end
    end

    let checked_program_default_to_strings () : (string, Symbols.symbol) Collections.Maps.map =
      Collections.Maps.empty_map ()

    module Expansion = struct
      module Expansion = struct
        let rec map_in (declarations : Parser.declaration list) (prefix : string) (file : Sources.loaded_file) (f : Symbols.symbol -> Parser.declaration) : Parser.declaration list =
          List.map (fun d -> let name = prefix ^ Symbols.Symbols.own_name d in
             let inner = match (d : Parser.declaration).Parser.definition with
               | Parser.ModuleDefinition { declarations = inside; spec = spec; parameters = parameters; application = application; type_parameters = type_parameters } -> ({ Parser.at = (d : Parser.declaration).Parser.at; name = (d : Parser.declaration).Parser.name; definition = (Parser.ModuleDefinition { declarations = map_in inside (name ^ ".") file f; spec = spec; parameters = parameters; application = application; type_parameters = type_parameters } : Parser.definition); visibility = (d : Parser.declaration).Parser.visibility; opaque = (d : Parser.declaration).Parser.opaque; annotations = (d : Parser.declaration).Parser.annotations } : Parser.declaration)
               | _ -> d in
             f ({ Symbols.name = name; path = Symbols.Symbols.path_of name; declaration = inner; file = file } : Symbols.symbol)) declarations

        let map_declarations (workspace : Sources.workspace) (f : Symbols.symbol -> Parser.declaration) : Sources.workspace =
          ({ Sources.files = List.map (fun file -> let prefix = if List.is_empty (file : Sources.loaded_file).Sources.package then "" else String.concat "." (List.map Fun.id (file : Sources.loaded_file).Sources.package) ^ "." in
             ({ Sources.source = (file : Sources.loaded_file).Sources.source; package = (file : Sources.loaded_file).Sources.package; role = (file : Sources.loaded_file).Sources.role; imports = (file : Sources.loaded_file).Sources.imports; declarations = map_in (file : Sources.loaded_file).Sources.declarations prefix file f } : Sources.loaded_file)) (workspace : Sources.workspace).Sources.files; apart = (workspace : Sources.workspace).Sources.apart; borrowed = (workspace : Sources.workspace).Sources.borrowed } : Sources.workspace)

        let find (name : string) (from : Symbols.symbol) (outline : (string, Symbols.symbol) Collections.Maps.map) : Symbols.symbol option =
          let parts = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name "." in
          let around = List.mapi (fun i _ -> List.take (List.length (from : Symbols.symbol).Symbols.path - i) (from : Symbols.symbol).Symbols.path) (from : Symbols.symbol).Symbols.path @ [[]] in
          let in_scope = List.nth_opt (Lang.Lists.list_map_not_null around (fun prefix -> Collections.Maps.map_get outline (String.concat "." (List.map Fun.id (prefix @ parts))))) 0 in
          Lang.Options.option_or_else in_scope (fun () -> List.nth_opt (Lang.Lists.list_map_not_null ((from : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.imports (fun i -> if (i : Parser.import).Parser.wildcard then Collections.Maps.map_get outline (String.concat "." (List.map Fun.id ((i : Parser.import).Parser.path @ parts))) else if let fk_arg1 = Option.value (i : Parser.import).Parser.alias ~default:(Option.value (Lang.Lists.list_last_or_none (i : Parser.import).Parser.path) ~default:"") in
                   let fk_arg2 = Option.value (List.nth_opt parts 0) ~default:"" in
                   fk_arg1 = fk_arg2 then Collections.Maps.map_get outline (String.concat "." (List.map Fun.id ((i : Parser.import).Parser.path @ List.drop 1 parts))) else None)) 0)

        let rec copied_effect (s : Symbols.symbol) (outline : (string, Symbols.symbol) Collections.Maps.map) (seen : string list) : Parser.declaration =
          match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = _; values = _; type_parameters = _; copy_of = Some (Parser.NamedType { at = at; name = name; arguments = _ }); parents = _ } -> (let d = (s : Symbols.symbol).Symbols.declaration in
               if List.mem (s : Symbols.symbol).Symbols.name seen then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (d : Parser.declaration).Parser.at; message = "effect '" ^ (d : Parser.declaration).Parser.name ^ "' is a copy of itself" } : Diagnostics.diagnostic)) with
                  | _ -> (assert false)) else ();
               let target = match find name s outline with
                 | Some t -> t
                 | None -> match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = "unknown effect '" ^ name ^ "'" } : Diagnostics.diagnostic)) with
                     | _ -> (assert false) in
               let original = match ((target : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
                 | Parser.SpecDefinition { types = _; values = _; type_parameters = _; copy_of = Some _; parents = _ } -> copied_effect target outline (seen @ [(s : Symbols.symbol).Symbols.name])
                 | _ -> (target : Symbols.symbol).Symbols.declaration in
               let not_effect = ({ Diagnostics.file = (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = "'" ^ name ^ "' isn't an effect, so there's nothing to copy" } : Diagnostics.diagnostic) in
               if Lang.Lists.list_none (original : Parser.declaration).Parser.annotations (fun it -> (it : Parser.annotation).Parser.name = "Effect") then (match Effect.perform (Diagnostics.Abandoning_abandon not_effect) with
                  | _ -> (assert false)) else ();
               match (original : Parser.declaration).Parser.definition with
               | Parser.SpecDefinition { types = types; values = values; type_parameters = type_parameters; copy_of = _; parents = parents } -> ({ Parser.at = (d : Parser.declaration).Parser.at; name = (d : Parser.declaration).Parser.name; definition = (Parser.SpecDefinition { types = types; values = values; type_parameters = type_parameters; copy_of = None; parents = parents } : Parser.definition); visibility = (d : Parser.declaration).Parser.visibility; opaque = (d : Parser.declaration).Parser.opaque; annotations = (d : Parser.declaration).Parser.annotations } : Parser.declaration)
               | Parser.RecordDefinition { type_parameters = _; fields = _; private_constructor = _; annotation = _; external_ = _ } -> ({ Parser.at = (d : Parser.declaration).Parser.at; name = (d : Parser.declaration).Parser.name; definition = (Parser.RecordDefinition { type_parameters = []; fields = []; private_constructor = false; annotation = true; external_ = None } : Parser.definition); visibility = (d : Parser.declaration).Parser.visibility; opaque = (d : Parser.declaration).Parser.opaque; annotations = (d : Parser.declaration).Parser.annotations } : Parser.declaration)
               | _ -> match Effect.perform (Diagnostics.Abandoning_abandon not_effect) with
                   | _ -> (assert false))
          | _ -> (s : Symbols.symbol).Symbols.declaration

        let outline (workspace : Sources.workspace) : (string, Symbols.symbol) Collections.Maps.map =
          Collections.Maps.list_tuple_to_map (List.map (fun s -> ((s : Symbols.symbol).Symbols.name, s)) (List.filter (fun s -> not (Symbols.Symbols.is_function s)) (Symbols.Symbols.declarations workspace)))

        let spec_types (d : Parser.declaration) : Parser.spec_type list =
          match (d : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = types; values = _; type_parameters = _; copy_of = _; parents = _ } -> types
          | _ -> []

        let spec_values (d : Parser.declaration) : Parser.spec_value list =
          match (d : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = _; values = values; type_parameters = _; copy_of = _; parents = _ } -> values
          | _ -> []

        let rec flattened_spec (s : Symbols.symbol) (outline : (string, Symbols.symbol) Collections.Maps.map) (seen : string list) : Parser.declaration =
          match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = types; values = values; type_parameters = type_parameters; copy_of = copy_of; parents = parents } -> let d = (s : Symbols.symbol).Symbols.declaration in
              if List.mem (s : Symbols.symbol).Symbols.name seen then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (d : Parser.declaration).Parser.at; message = "spec '" ^ (d : Parser.declaration).Parser.name ^ "' builds on itself" } : Diagnostics.diagnostic)) with
                 | _ -> (assert false)) else ();
              let inherited = List.map (fun ref -> let (at, name, arguments) = match ref with
                     | Parser.NamedType { at = a; name = n; arguments = args } -> (a, n, args)
                     | _ -> ((d : Parser.declaration).Parser.at, "", []) in
                   let parent = Lang.Options.option_filter (find name s outline) (fun it -> Symbols.Symbols.is_spec it) in
                   match parent with
                   | None -> (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = "unknown spec '" ^ name ^ "'" } : Diagnostics.diagnostic)) with
                        | _ -> (assert false))
                   | Some p -> let parent_type_parameters = match ((p : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
                         | Parser.SpecDefinition { types = _; values = _; type_parameters = ps; copy_of = _; parents = _ } -> ps
                         | _ -> [] in
                       if Lang.Lists.list_is_not_empty arguments || Lang.Lists.list_is_not_empty parent_type_parameters then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = "a spec can't build on one with type arguments yet" } : Diagnostics.diagnostic)) with
                          | _ -> (assert false)) else ();
                       if List.exists (fun it -> (it : Parser.annotation).Parser.name = "Effect") ((p : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations || List.exists (fun it -> (it : Parser.annotation).Parser.name = "Effect") (d : Parser.declaration).Parser.annotations then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = "an effect can't build on another yet" } : Diagnostics.diagnostic)) with
                          | _ -> (assert false)) else ();
                       flattened_spec p outline (seen @ [(s : Symbols.symbol).Symbols.name])) parents in
              let inherited_types = List.concat_map (fun it -> spec_types it) inherited in
              let all_types = List.map (fun name -> Option.value (Lang.Lists.list_last_or_none (List.filter (fun it -> (it : Parser.spec_type).Parser.name = name) (inherited_types @ types))) ~default:({ Parser.at = (d : Parser.declaration).Parser.at; name = name; type_parameters = [] } : Parser.spec_type)) (Lang.Lists.list_distinct (List.map (fun it -> (it : Parser.spec_type).Parser.name) (inherited_types @ types))) in
              let own = List.map (fun it -> (it : Parser.spec_value).Parser.name) values in
              let all_values = Lang.Lists.list_distinct_by (List.filter (fun v -> not (List.mem (v : Parser.spec_value).Parser.name own)) (List.concat_map (fun it -> spec_values it) inherited)) (fun it -> (it : Parser.spec_value).Parser.name) @ values in
              ({ Parser.at = (d : Parser.declaration).Parser.at; name = (d : Parser.declaration).Parser.name; definition = (Parser.SpecDefinition { types = all_types; values = all_values; type_parameters = type_parameters; copy_of = copy_of; parents = parents } : Parser.definition); visibility = (d : Parser.declaration).Parser.visibility; opaque = (d : Parser.declaration).Parser.opaque; annotations = (d : Parser.declaration).Parser.annotations } : Parser.declaration)
          | _ -> (s : Symbols.symbol).Symbols.declaration

        let is_function_declaration (d : Parser.declaration) : bool =
          match (d : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = _; operator = _ } -> true
          | _ -> false

        let is_blank (t : Parser.type_ref) : bool =
          match t with
          | Parser.NamedType { at = _; name = "_"; arguments = [] } -> true
          | _ -> false

        let rec filled_blanks (arguments : Parser.type_ref list) (given : Parser.type_ref list) : Parser.type_ref list =
          match arguments with
          | [] -> []
          | first :: rest -> match given with
              | g :: more when is_blank first -> g :: filled_blanks rest more
              | _ -> first :: filled_blanks rest given

        let rec fixed_type (t : Parser.type_ref) (fixed : (Parser.spec_type * Parser.type_ref) list) : Parser.type_ref =
          match t with
          | Parser.NamedType { at = at; name = name; arguments = arguments } -> (let given = List.map (fun it -> fixed_type it fixed) arguments in
               match List.find_opt (fun (spec_type, _) -> (spec_type : Parser.spec_type).Parser.name = name) fixed with
               | Some (spec_type, Parser.NamedType { at = arg_at; name = arg_name; arguments = arg_arguments }) when Lang.Lists.list_is_not_empty (spec_type : Parser.spec_type).Parser.type_parameters -> if Lang.Lists.list_none arg_arguments (fun it -> is_blank it) then (Parser.NamedType { at = arg_at; name = arg_name; arguments = arg_arguments @ given } : Parser.type_ref) else (Parser.NamedType { at = arg_at; name = arg_name; arguments = filled_blanks arg_arguments given } : Parser.type_ref)
               | Some (_, written) -> written
               | None -> (Parser.NamedType { at = at; name = name; arguments = given } : Parser.type_ref))
          | Parser.FunctionType { at = at; parameters = parameters; result = result; effects = effects } -> let fk_arg1 = List.map (fun it -> fixed_type it fixed) parameters in
              let fk_arg2 = fixed_type result fixed in
              (Parser.FunctionType { at = at; parameters = fk_arg1; result = fk_arg2; effects = effects } : Parser.type_ref)
          | Parser.TupleType { at = at; elements = elements } -> (Parser.TupleType { at = at; elements = List.map (fun it -> fixed_type it fixed) elements } : Parser.type_ref)
          | Parser.EffectsType { at = _; effects = _ } -> t
          | Parser.GivenType { at = at; name = name; given = given } -> (Parser.GivenType { at = at; name = name; given = fixed_type given fixed } : Parser.type_ref)

        let default_of (v : Parser.spec_value) (fixed : (Parser.spec_type * Parser.type_ref) list) : Parser.declaration =
          let fix = fun t -> fixed_type t fixed in
          ({ Parser.at = (v : Parser.spec_value).Parser.at; name = (v : Parser.spec_value).Parser.name; definition = (let fk_arg1 = Option.map (fun ps -> List.map (fun p -> ({ Parser.at = (p : Parser.parameter).Parser.at; name = (p : Parser.parameter).Parser.name; parameter_type = Option.map fix (p : Parser.parameter).Parser.parameter_type; annotations = (p : Parser.parameter).Parser.annotations; default = (p : Parser.parameter).Parser.default } : Parser.parameter)) ps) (v : Parser.spec_value).Parser.parameters in
           let fk_arg2 = Some (fix (v : Parser.spec_value).Parser.value_type) in
           let fk_arg3 = Option.value (v : Parser.spec_value).Parser.default ~default:(Parser.Name { at = (v : Parser.spec_value).Parser.at; name = "Unit" } : Parser.expression) in
           (Parser.FunctionDefinition { type_parameters = (v : Parser.spec_value).Parser.type_parameters; receiver = None; parameters = fk_arg1; result = fk_arg2; body = fk_arg3; external_ = None; operator = false } : Parser.definition)); visibility = (Parser.Public : Parser.visibility); opaque = false; annotations = (v : Parser.spec_value).Parser.annotations } : Parser.declaration)

        let filled_module (s : Symbols.symbol) (outline : (string, Symbols.symbol) Collections.Maps.map) : Parser.declaration =
          match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.ModuleDefinition { declarations = declarations; spec = spec; parameters = parameters; application = application; type_parameters = type_parameters } -> let d = (s : Symbols.symbol).Symbols.declaration in
              let from_spec = match spec with
                | Some (Parser.NamedType { at = _; name = name; arguments = arguments }) -> (match Lang.Options.option_filter (find name s outline) (fun it -> Symbols.Symbols.is_spec it) with
                     | Some followed -> let defined = List.map (fun it -> (it : Parser.declaration).Parser.name) (List.filter (fun inner -> is_function_declaration inner) declarations) in
                         let fixed = Lang.Lists.list_zip (spec_types (followed : Symbols.symbol).Symbols.declaration) arguments in
                         List.map (fun v -> default_of v fixed) (List.filter (fun v -> Option.is_some (v : Parser.spec_value).Parser.default && not (List.mem (v : Parser.spec_value).Parser.name defined)) (spec_values (followed : Symbols.symbol).Symbols.declaration))
                     | None -> [])
                | _ -> [] in
              let all = List.map (fun inner -> match (inner : Parser.declaration).Parser.definition with
                   | Parser.FunctionDefinition { type_parameters = own_parameters; receiver = receiver; parameters = ps; result = result; body = body; external_ = external_; operator = operator } when Lang.Lists.list_is_not_empty type_parameters -> Option.iter (fun clash -> match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (inner : Parser.declaration).Parser.at; message = "'" ^ (inner : Parser.declaration).Parser.name ^ "' is in " ^ (d : Parser.declaration).Parser.name ^ "<" ^ String.concat ", " (List.map Fun.id type_parameters) ^ ">, so its own type parameters can't be named " ^ clash ^ " too" } : Diagnostics.diagnostic)) with
                          | _ -> (assert false)) (List.find_opt (fun it -> List.mem it type_parameters) own_parameters);
                       ({ Parser.at = (inner : Parser.declaration).Parser.at; name = (inner : Parser.declaration).Parser.name; definition = (Parser.FunctionDefinition { type_parameters = own_parameters @ type_parameters; receiver = receiver; parameters = ps; result = result; body = body; external_ = external_; operator = operator } : Parser.definition); visibility = (inner : Parser.declaration).Parser.visibility; opaque = (inner : Parser.declaration).Parser.opaque; annotations = (inner : Parser.declaration).Parser.annotations } : Parser.declaration)
                   | _ -> inner) (declarations @ from_spec) in
              ({ Parser.at = (d : Parser.declaration).Parser.at; name = (d : Parser.declaration).Parser.name; definition = (Parser.ModuleDefinition { declarations = all; spec = spec; parameters = parameters; application = application; type_parameters = type_parameters } : Parser.definition); visibility = (d : Parser.declaration).Parser.visibility; opaque = (d : Parser.declaration).Parser.opaque; annotations = (d : Parser.declaration).Parser.annotations } : Parser.declaration)
          | _ -> (s : Symbols.symbol).Symbols.declaration

        let borrowed_defaults (workspace : Sources.workspace) : (string, Sources.loaded_file) Collections.Maps.map =
          let outline = outline workspace in
          Collections.Maps.list_tuple_to_map (List.concat_map (fun m -> match ((m : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
              | Parser.ModuleDefinition { declarations = declarations; spec = Some (Parser.NamedType { at = _; name = name; arguments = _ }); parameters = _; application = _; type_parameters = _ } -> (match Lang.Options.option_filter (find name m outline) (fun it -> Symbols.Symbols.is_spec it) with
                   | Some followed -> let defined = List.map (fun it -> (it : Parser.declaration).Parser.name) (List.filter (fun inner -> is_function_declaration inner) declarations) in
                       List.map (fun v -> ((m : Symbols.symbol).Symbols.name ^ "." ^ (v : Parser.spec_value).Parser.name, (followed : Symbols.symbol).Symbols.file)) (List.filter (fun v -> Option.is_some (v : Parser.spec_value).Parser.default && not (List.mem (v : Parser.spec_value).Parser.name defined)) (spec_values (followed : Symbols.symbol).Symbols.declaration))
                   | None -> [])
              | _ -> []) (Symbols.Symbols.declarations workspace))

        let expanded (workspace : Sources.workspace) : Sources.workspace =
          let copied = map_declarations workspace (fun s -> match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
               | Parser.SpecDefinition { types = _; values = _; type_parameters = _; copy_of = Some _; parents = _ } -> copied_effect s (outline workspace) []
               | _ -> (s : Symbols.symbol).Symbols.declaration) in
          let flattened = map_declarations copied (fun s -> match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
               | Parser.SpecDefinition { types = _; values = _; type_parameters = _; copy_of = _; parents = _ :: _ } -> flattened_spec s (outline copied) []
               | _ -> (s : Symbols.symbol).Symbols.declaration) in
          let filled = map_declarations flattened (fun s -> match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
               | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _; application = _; type_parameters = _ } -> filled_module s (outline flattened)
               | _ -> (s : Symbols.symbol).Symbols.declaration) in
          ({ Sources.files = (filled : Sources.workspace).Sources.files; apart = (filled : Sources.workspace).Sources.apart; borrowed = borrowed_defaults flattened } : Sources.workspace)
      end
    end

    module Resolution = struct
      type call_site = { file : string option; at : Parser.position }

      let rec show_call_site (v : call_site) =
        "CallSite(" ^ "file=" ^ fk_show_option Fun.id v.file ^ ", at=" ^ Parser.show_position v.at ^ ")"

      type file_imports = { named : (string, string) Collections.Maps.map; ambiguous : (string, string list) Collections.Maps.map }

      let rec show_file_imports (v : file_imports) =
        "FileImports(" ^ "named=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Fun.id) v.named ^ ", ambiguous=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id (fk_show_list Fun.id)) v.ambiguous ^ ")"

      type hints = { tree : Sources.source_tree; apart : (string, string) Collections.Maps.map }

      let rec show_hints (v : hints) =
        "Hints(" ^ "tree=" ^ Sources.show_source_tree v.tree ^ ", apart=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Fun.id) v.apart ^ ")"

      type 'a lookup =
        | Found of { value : 'a }
        | NotFound
        | Refused of { message : string }

      let rec show_lookup show_a (v : 'a lookup) =
        match v with
        | Found r -> "Found(" ^ "value=" ^ show_a r.value ^ ")"
        | NotFound -> "NotFound"
        | Refused r -> "Refused(" ^ "message=" ^ Fun.id r.message ^ ")"

      type made = { functor_ : Symbols.symbol; arguments : Symbols.symbol list }

      let rec show_made (v : made) =
        "Made(" ^ "functor=" ^ Symbols.show_symbol v.functor_ ^ ", arguments=" ^ fk_show_list Symbols.show_symbol v.arguments ^ ")"

      type modules = { specs : (string, Symbols.symbol) Collections.Maps.map; parameter_modules : string list; parameter_members : string list; applications : (string, made) Collections.Maps.map; aliases : (string, string) Collections.Maps.map; copy_origins : (string, string) Collections.Maps.map; fixed_types : (string, Symbols.symbol) Collections.Maps.map; lifted : (call_site, string) Collections.Maps.map }

      let rec show_modules (v : modules) =
        "Modules(" ^ "specs=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Symbols.show_symbol) v.specs ^ ", parameterModules=" ^ fk_show_list Fun.id v.parameter_modules ^ ", parameterMembers=" ^ fk_show_list Fun.id v.parameter_members ^ ", applications=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_made) v.applications ^ ", aliases=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Fun.id) v.aliases ^ ", copyOrigins=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Fun.id) v.copy_origins ^ ", fixedTypes=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Symbols.show_symbol) v.fixed_types ^ ", lifted=" ^ (fun v -> Collections.Maps.map_to_string v show_call_site Fun.id) v.lifted ^ ")"

      type namespace = { table : Symbols.symbol_table; imports : (string option, file_imports) Collections.Maps.map; modules : modules; hints : hints }

      let rec show_namespace (v : namespace) =
        "Namespace(" ^ "table=" ^ Symbols.show_symbol_table v.table ^ ", imports=" ^ (fun v -> Collections.Maps.map_to_string v (fk_show_option Fun.id) show_file_imports) v.imports ^ ", modules=" ^ show_modules v.modules ^ ", hints=" ^ show_hints v.hints ^ ")"

      type place = { file : Sources.loaded_file; path : string list }

      let rec show_place (v : place) =
        "Place(" ^ "file=" ^ Sources.show_loaded_file v.file ^ ", path=" ^ fk_show_list Fun.id v.path ^ ")"

      type strictness =
        | Skipping
        | Refusing

      let rec show_strictness (v : strictness) =
        match v with
        | Skipping -> "Skipping"
        | Refusing -> "Refusing"

      type type_meaning =
        | TypeParameterType of { name : string }
        | SpecOwnType of { name : string }
        | BuiltinType of { name : string }
        | DeclaredType of { symbol : Symbols.symbol }
        | SpecModuleType of { spec : Symbols.symbol }

      let rec show_type_meaning (v : type_meaning) =
        match v with
        | TypeParameterType r -> "TypeParameterType(" ^ "name=" ^ Fun.id r.name ^ ")"
        | SpecOwnType r -> "SpecOwnType(" ^ "name=" ^ Fun.id r.name ^ ")"
        | BuiltinType r -> "BuiltinType(" ^ "name=" ^ Fun.id r.name ^ ")"
        | DeclaredType r -> "DeclaredType(" ^ "symbol=" ^ Symbols.show_symbol r.symbol ^ ")"
        | SpecModuleType r -> "SpecModuleType(" ^ "spec=" ^ Symbols.show_symbol r.spec ^ ")"

      type type_scope = { place : place; type_parameters : string list; spec_types : string list; parameters : string list }

      let rec show_type_scope (v : type_scope) =
        "TypeScope(" ^ "place=" ^ show_place v.place ^ ", typeParameters=" ^ fk_show_list Fun.id v.type_parameters ^ ", specTypes=" ^ fk_show_list Fun.id v.spec_types ^ ", parameters=" ^ fk_show_list Fun.id v.parameters ^ ")"

      type written_type = { at : Parser.position; name : string; scope : type_scope }

      let rec show_written_type (v : written_type) =
        "WrittenType(" ^ "at=" ^ Parser.show_position v.at ^ ", name=" ^ Fun.id v.name ^ ", scope=" ^ show_type_scope v.scope ^ ")"

      type resolved_type = { written : written_type; meaning : type_meaning }

      let rec show_resolved_type (v : resolved_type) =
        "ResolvedType(" ^ "written=" ^ show_written_type v.written ^ ", meaning=" ^ show_type_meaning v.meaning ^ ")"

      type resolved_file = { file : Sources.loaded_file; types : resolved_type list }

      let rec show_resolved_file (v : resolved_file) =
        "ResolvedFile(" ^ "file=" ^ Sources.show_loaded_file v.file ^ ", types=" ^ fk_show_list show_resolved_type v.types ^ ")"

      module Visibility = struct
        let is_foreign (symbol : Symbols.symbol) (place : place) : bool =
          ((List.is_empty (symbol : Symbols.symbol).Symbols.path && not (Symbols.Symbols.is_module symbol)) && (((symbol : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.project = (Sources.ProgramProject : Sources.project)) && (((place : place).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.project <> (Sources.ProgramProject : Sources.project)

        let project_name (project : Sources.project) : string =
          match project with
          | Sources.ProgramProject -> "program"
          | Sources.CoreProject -> "core"
          | Sources.OtherProject { root = root } -> root

        let is_inside (place : place) (path : string list) : bool =
          List.take (List.length path) (place : place).path = path

        let is_in_package (symbol : Symbols.symbol) (table : Symbols.symbol_table) : bool =
          List.is_empty (symbol : Symbols.symbol).Symbols.path || (match Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.modules (String.concat "." (List.map Fun.id (symbol : Symbols.symbol).Symbols.path)) with
           | Some (Symbols.PackageModule { name = _ }) -> true
           | _ -> false)

        let is_functor (m : Symbols.symbol) : bool =
          match ((m : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _ :: _; application = _; type_parameters = _ } -> true
          | _ -> false

        let enclosing_functor (path : string list) (table : Symbols.symbol_table) : Symbols.symbol option =
          List.nth_opt (Lang.Lists.list_map_not_null (List.mapi (fun i _ -> Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.modules (String.concat "." (List.map Fun.id (List.take (i + 1) path)))) path) (fun found -> match found with
              | Some (Symbols.DeclaredModule { symbol = m }) when is_functor m -> Some m
              | _ -> None)) 0

        let rec why_hidden (symbol : Symbols.symbol) (place : place) (table : Symbols.symbol_table) : string option =
          let own = Symbols.Symbols.simple_name symbol in
          if is_foreign symbol place then Some ("'" ^ own ^ "' is the program's own, which other projects' code can't see") else if ((symbol : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.visibility = (Parser.Internal : Parser.visibility) && (((symbol : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.project <> (((place : place).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.project then Some ("'" ^ own ^ "' is internal to its project, " ^ project_name (((symbol : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.project) else if ((symbol : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.visibility = (Parser.Private : Parser.visibility) && not (is_inside place (symbol : Symbols.symbol).Symbols.path) then Some ("'" ^ own ^ "' is private to " ^ (if List.is_empty (symbol : Symbols.symbol).Symbols.path then "this file" else String.concat "." (List.map Fun.id (symbol : Symbols.symbol).Symbols.path))) else if ((((symbol : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.visibility = (Parser.Private : Parser.visibility) && not (Symbols.Symbols.is_module symbol)) && is_in_package symbol table) && (((symbol : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path <> (((place : place).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path then Some ("'" ^ own ^ "' is private to " ^ Option.value (((symbol : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path ~default:"the program's file") else (match enclosing_functor (symbol : Symbols.symbol).Symbols.path table with
                   | Some functor_ when not (is_inside place (let fk_arg1 = Symbols.Symbols.path_of (functor_ : Symbols.symbol).Symbols.name in
                         let fk_arg2 = [Symbols.Symbols.simple_name functor_] in
                         fk_arg1 @ fk_arg2)) -> let name = Symbols.Symbols.simple_name functor_ in
                       Some ("'" ^ own ^ "' is in the functor " ^ name ^ ", which makes modules: use it through one, made with module Name = " ^ name ^ "(...)")
                   | _ -> hidden_module_around (symbol : Symbols.symbol).Symbols.path 1 place table)
        and hidden_module_around (path : string list) (length : int) (place : place) (table : Symbols.symbol_table) : string option =
          if length > List.length path then None else (match Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.modules (String.concat "." (List.map Fun.id (List.take length path))) with
             | Some (Symbols.DeclaredModule { symbol = m }) -> Lang.Options.option_or_else (why_hidden m place table) (fun () -> hidden_module_around path (length + 1) place table)
             | _ -> hidden_module_around path (length + 1) place table)
      end

      module Names = struct
        let enclosing_application (path : string list) (namespace : namespace) : string option =
          List.find_opt (fun it -> Collections.Maps.map_contains_key ((namespace : namespace).modules : modules).applications it) (List.mapi (fun i _ -> String.concat "." (List.map Fun.id (List.take (i + 1) path))) path)

        let spec_place (place : place) (namespace : namespace) : place option =
          match Collections.Maps.map_get ((namespace : namespace).table : Symbols.symbol_table).Symbols.modules (String.concat "." (List.map Fun.id (place : place).path)) with
          | Some (Symbols.DeclaredModule { symbol = m }) when (((m : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path <> (((place : place).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path && Option.is_none (enclosing_application (place : place).path namespace) -> Option.bind (Collections.Maps.map_get ((namespace : namespace).modules : modules).specs (m : Symbols.symbol).Symbols.name) (fun followed -> let spec = if (((followed : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path = (((place : place).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path then Some followed else List.find_opt (fun s -> (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path = (((place : place).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path) (List.map (fun (_, s) -> s) (Collections.Maps.map_to_list ((namespace : namespace).table : Symbols.symbol_table).Symbols.specs)) in
                 Option.map (fun s -> ({ file = (place : place).file; path = (s : Symbols.symbol).Symbols.path } : place)) spec)
          | _ -> None

        let rec canonical (name : string) (namespace : namespace) : string =
          let parts = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name "." in
          let found = List.nth_opt (Lang.Lists.list_map_not_null (List.mapi (fun i _ -> List.length parts - i) parts) (fun n -> Option.map (fun given -> String.concat "." (List.map Fun.id ([given] @ List.drop n parts))) (Collections.Maps.map_get ((namespace : namespace).modules : modules).aliases (String.concat "." (List.map Fun.id (List.take n parts)))))) 0 in
          match found with
          | Some replaced -> canonical replaced namespace
          | None -> name

        let rec around (name : string) (depths : int list) (entries : (string, _) Collections.Maps.map) (symbol_of : _ -> Symbols.symbol option) (place : place) (namespace : namespace) (strictness : strictness) : _ lookup =
          match depths with
          | [] -> (NotFound : _ lookup)
          | depth :: further -> let table = (namespace : namespace).table in
              let next = fun () -> around name further entries symbol_of place namespace strictness in
              let full = canonical (String.concat "." (List.map Fun.id (List.take depth (place : place).path @ [name]))) namespace in
              let own = if not ((namespace : namespace).table : Symbols.symbol_table).Symbols.file_private then None else Option.bind (((place : place).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path (fun path -> Collections.Maps.map_get entries (Symbols.Symbols.file_private_name full path)) in
              match Lang.Options.option_or_else own (fun () -> Collections.Maps.map_get entries full) with
              | None -> next ()
              | Some entry -> match symbol_of entry with
                  | Some symbol when Visibility.is_foreign symbol place -> next ()
                  | Some symbol -> (match Visibility.why_hidden symbol place table with
                       | None -> (Found { value = entry } : _ lookup)
                       | Some why -> match strictness with
                           | Skipping -> next ()
                           | Refusing -> (Refused { message = why } : _ lookup))
                  | None -> (Found { value = entry } : _ lookup)

        let is_package (name : string) (table : Symbols.symbol_table) : bool =
          match Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.modules name with
          | Some (Symbols.PackageModule { name = _ }) -> true
          | _ -> false

        let rec package_depth (path : string list) (depth : int) (table : Symbols.symbol_table) : int =
          if depth < List.length path && is_package (String.concat "." (List.map Fun.id (List.take (depth + 1) path))) table then package_depth path (depth + 1) table else depth

        let rec descending (from : int) (to_ : int) : int list =
          if from < to_ then [] else from :: descending (from - 1) to_

        let reach (name : string) (place : place) (table : Symbols.symbol_table) : int list =
          let depth = package_depth (place : place).path 0 table in
          let first = Option.value (List.nth_opt ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".") 0) ~default:name in
          let full = depth > 0 && is_package first table in
          descending (List.length (place : place).path) depth @ (if full then [0] else [])

        let imported_names (name : string) (place : place) (namespace : namespace) : string list =
          let first = Option.value (List.nth_opt ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".") 0) ~default:name in
          let rest = Lang.Strings.string_remove_prefix name first in
          let imports = Collections.Maps.map_get_or_default (namespace : namespace).imports (((place : place).file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path (let fk_arg1 = Collections.Maps.empty_map () in
             let fk_arg2 = Collections.Maps.empty_map () in
             ({ named = fk_arg1; ambiguous = fk_arg2 } : file_imports)) in
          let targets = match Collections.Maps.map_get (imports : file_imports).named first with
            | Some target -> [target]
            | None -> Collections.Maps.map_get_or_default (imports : file_imports).ambiguous first [] in
          List.map (fun it -> it ^ rest) targets

        let imported (name : string) (entries : (string, _) Collections.Maps.map) (symbol_of : _ -> Symbols.symbol option) (alike : string -> bool) (place : place) (namespace : namespace) (strictness : strictness) : _ lookup =
          let names = imported_names name place namespace in
          let found = Lang.Lists.list_distinct (List.filter (fun it -> Collections.Maps.map_contains_key entries it) (List.map (fun it -> canonical it namespace) names)) in
          let similar = Lang.Lists.list_distinct (List.filter (fun it -> alike it) names) in
          let first = Option.value (List.nth_opt ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".") 0) ~default:name in
          if List.length similar > 1 || List.length found > 1 then (let clashing = if List.length similar > 1 then similar else found in
             match strictness with
             | Skipping -> (NotFound : _ lookup)
             | Refusing -> (Refused { message = "'" ^ first ^ "' is imported from " ^ String.concat " and " (List.map Fun.id clashing) ^ "; import the one you mean by name" } : _ lookup)) else (match found with
             | [full] -> (match Collections.Maps.map_get entries full with
                  | None -> (NotFound : _ lookup)
                  | Some entry -> match Option.bind (symbol_of entry) (fun it -> Visibility.why_hidden it place (namespace : namespace).table) with
                      | None -> (Found { value = entry } : _ lookup)
                      | Some why -> match strictness with
                          | Skipping -> (NotFound : _ lookup)
                          | Refusing -> (Refused { message = why } : _ lookup))
             | _ -> (NotFound : _ lookup))

        let rec find (name : string) (entries : (string, _) Collections.Maps.map) (symbol_of : _ -> Symbols.symbol option) (alike : string -> bool) (place : place) (namespace : namespace) (strictness : strictness) : _ lookup =
          match spec_place place namespace with
          | Some at -> (match around name [List.length (place : place).path] entries symbol_of place namespace strictness with
               | NotFound -> (match find name entries symbol_of alike at namespace strictness with
                    | NotFound -> anywhere name entries symbol_of alike place namespace strictness
                    | other -> other)
               | other -> other)
          | None -> anywhere name entries symbol_of alike place namespace strictness
        and anywhere (name : string) (entries : (string, _) Collections.Maps.map) (symbol_of : _ -> Symbols.symbol option) (alike : string -> bool) (place : place) (namespace : namespace) (strictness : strictness) : _ lookup =
          match around name (reach name place (namespace : namespace).table) entries symbol_of place namespace strictness with
          | NotFound -> (match where_functor_is name entries symbol_of alike place namespace strictness with
               | NotFound -> (match where_spec_is name entries symbol_of alike place namespace strictness with
                    | NotFound -> imported name entries symbol_of alike place namespace strictness
                    | other -> other)
               | other -> other)
          | other -> other
        and where_functor_is (name : string) (entries : (string, _) Collections.Maps.map) (symbol_of : _ -> Symbols.symbol option) (alike : string -> bool) (place : place) (namespace : namespace) (strictness : strictness) : _ lookup =
          match Option.bind (enclosing_application (place : place).path namespace) (fun app -> Option.map (fun made -> (app, made)) (Collections.Maps.map_get ((namespace : namespace).modules : modules).applications app)) with
          | None -> (NotFound : _ lookup)
          | Some (app, made) -> let in_functor = ({ file = (place : place).file; path = (let fk_arg1 = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) ((made : made).functor_ : Symbols.symbol).Symbols.name "." in
                 let fk_arg2 = List.drop (List.length ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) app ".")) (place : place).path in
                 fk_arg1 @ fk_arg2) } : place) in
              let is_parameters = fun full -> List.exists (fun p -> full = p || String.starts_with ~prefix:(p ^ ".") full) ((namespace : namespace).modules : modules).parameter_modules in
              match find name entries symbol_of alike in_functor namespace strictness with
              | Found { value = entry } when Option.value (Option.map (fun s -> not (is_parameters (s : Symbols.symbol).Symbols.name)) (symbol_of entry)) ~default:true -> (Found { value = entry } : _ lookup)
              | Refused { message = why } -> (Refused { message = why } : _ lookup)
              | _ -> (NotFound : _ lookup)
        and where_spec_is (name : string) (entries : (string, _) Collections.Maps.map) (symbol_of : _ -> Symbols.symbol option) (alike : string -> bool) (place : place) (namespace : namespace) (strictness : strictness) : _ lookup =
          match spec_place place namespace with
          | Some at -> find name entries symbol_of alike at namespace strictness
          | None -> (NotFound : _ lookup)
      end

      module Lookups = struct
        let of_kind (name : string) (entries : (string, Symbols.symbol) Collections.Maps.map) (place : place) (namespace : namespace) (strictness : strictness) : Symbols.symbol lookup =
          Names.find name entries (fun s -> Some s) (fun full -> Collections.Maps.map_contains_key entries full) place namespace strictness

        let spec (name : string) (place : place) (namespace : namespace) (strictness : strictness) : Symbols.symbol lookup =
          of_kind name ((namespace : namespace).table : Symbols.symbol_table).Symbols.specs place namespace strictness

        let module_named (name : string) (place : place) (namespace : namespace) (strictness : strictness) : Symbols.module_symbol lookup =
          let modules = ((namespace : namespace).table : Symbols.symbol_table).Symbols.modules in
          Names.find name modules (fun m -> match m with
             | Symbols.DeclaredModule { symbol = s } -> Some s
             | Symbols.PackageModule { name = _ } -> None) (fun full -> Collections.Maps.map_contains_key modules full) place namespace strictness

        let found (lookup : _ lookup) : _ option =
          match lookup with
          | Found { value = a } -> Some a
          | _ -> None

        let annotation_type (name : string) (place : place) (namespace : namespace) (strictness : strictness) : Symbols.symbol lookup =
          of_kind name ((namespace : namespace).table : Symbols.symbol_table).Symbols.annotation_types place namespace strictness

        let of_type (name : string) (entries : (string, Symbols.symbol) Collections.Maps.map) (place : place) (namespace : namespace) (strictness : strictness) : Symbols.symbol lookup =
          let table = (namespace : namespace).table in
          Names.find name entries (fun s -> Some s) (fun full -> (Collections.Maps.map_contains_key (table : Symbols.symbol_table).Symbols.records full || Collections.Maps.map_contains_key (table : Symbols.symbol_table).Symbols.case_types full) || Collections.Maps.map_contains_key (table : Symbols.symbol_table).Symbols.aliases full) place namespace strictness

        let record (name : string) (place : place) (namespace : namespace) (strictness : strictness) : Symbols.symbol lookup =
          of_type name ((namespace : namespace).table : Symbols.symbol_table).Symbols.records place namespace strictness

        let case_type (name : string) (place : place) (namespace : namespace) (strictness : strictness) : Symbols.symbol lookup =
          of_type name ((namespace : namespace).table : Symbols.symbol_table).Symbols.case_types place namespace strictness

        let alias (name : string) (place : place) (namespace : namespace) (strictness : strictness) : Symbols.symbol lookup =
          of_type name ((namespace : namespace).table : Symbols.symbol_table).Symbols.aliases place namespace strictness

        let any_type (name : string) (place : place) (namespace : namespace) (strictness : strictness) : Symbols.symbol lookup =
          match record name place namespace strictness with
          | NotFound -> (match case_type name place namespace strictness with
               | NotFound -> alias name place namespace strictness
               | other -> other)
          | other -> other

        let function_ (name : string) (place : place) (namespace : namespace) (strictness : strictness) : Symbols.symbol lookup =
          of_kind name ((namespace : namespace).table : Symbols.symbol_table).Symbols.functions place namespace strictness
      end

      module ImportHints = struct
        let is_module_file (f : Sources.source_text) : bool =
          Option.value (Option.map (fun it -> Lang.Strings.char_is_upper_case it) ((fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in if n < 0 || i >= String.length s then None else Some (Uchar.to_int (Uchar.utf_decode_uchar (String.get_utf_8_uchar s i)))) (Sources.Loader.file_name f) 0)) ~default:false

        let is_function (d : Parser.declaration) : bool =
          match (d : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = _; operator = _ } -> true
          | _ -> false

        let declares_inside (main : Parser.declaration) (name : string) (at_top : Parser.position -> bool) : bool =
          match (main : Parser.declaration).Parser.definition with
          | Parser.ModuleDefinition { declarations = inside; spec = _; parameters = _; application = _; type_parameters = _ } -> List.exists (fun d -> ((d : Parser.declaration).Parser.name = name && at_top (d : Parser.declaration).Parser.at) && not (is_function d)) inside
          | Parser.SpecDefinition { types = types; values = _; type_parameters = _; copy_of = _; parents = _ } -> List.exists (fun t -> (t : Parser.spec_type).Parser.name = name && at_top (t : Parser.spec_type).Parser.at) types
          | _ -> false

        let is_handler (d : Parser.declaration) : bool =
          match (d : Parser.declaration).Parser.definition with
          | Parser.ModuleDefinition { declarations = _; spec = Some _; parameters = _; application = _; type_parameters = _ } -> true
          | _ -> false

        let is_operator (d : Parser.declaration) : bool =
          match (d : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = _; operator = operator } -> operator
          | _ -> false

        let has_member (main : Parser.declaration) (name : string) (at_top : Parser.position -> bool) : bool =
          match (main : Parser.declaration).Parser.definition with
          | Parser.ModuleDefinition { declarations = inside; spec = _; parameters = _; application = _; type_parameters = _ } -> List.exists (fun d -> ((((d : Parser.declaration).Parser.name = name && at_top (d : Parser.declaration).Parser.at) && is_function d) && (d : Parser.declaration).Parser.visibility = (Parser.Public : Parser.visibility)) && not (is_operator d)) inside
          | Parser.SpecDefinition { types = _; values = values; type_parameters = _; copy_of = _; parents = _ } -> List.exists (fun v -> (v : Parser.spec_value).Parser.name = name && at_top (v : Parser.spec_value).Parser.at) values
          | Parser.RecordDefinition { type_parameters = _; fields = fields; private_constructor = _; annotation = _; external_ = _ } -> List.exists (fun field -> (field : Parser.field).Parser.name = name && at_top (field : Parser.field).Parser.at) fields
          | _ -> false

        let is_effect (d : Parser.declaration) : bool =
          match (d : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = _; values = _; type_parameters = _; copy_of = _; parents = _ } -> List.exists (fun it -> (it : Parser.annotation).Parser.name = "Effect") (d : Parser.declaration).Parser.annotations
          | _ -> false

        let found_in (name : string) (pkg : string list) (f : Sources.source_text) : string list =
          let own = Sources.Loader.file_name f in
          let imported = String.concat "." (List.map Fun.id (pkg @ [own])) in
          if own = name then [imported] else (match Parser.Parser.parse (f : Sources.source_text).Sources.text with
             | Error _ -> []
             | Ok file -> List.concat_map (fun main -> let lines = Lang.Strings.string_lines (f : Sources.source_text).Sources.text in
                    let at_top = fun at -> Option.value (Option.map (fun line -> String.starts_with ~prefix:"  " line && not (String.starts_with ~prefix:"   " line)) (Lang.Lists.list_get_or_none lines ((at : Parser.position).Parser.line - 1))) ~default:false in
                    if Option.value (Option.map (fun it -> Lang.Strings.char_is_upper_case it) ((fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in if n < 0 || i >= String.length s then None else Some (Uchar.to_int (Uchar.utf_decode_uchar (String.get_utf_8_uchar s i)))) name 0)) ~default:false then if declares_inside main name at_top then [imported ^ "." ^ name] else [] else if is_handler main || not (has_member main name at_top) then [] else if is_effect main then [imported] else [imported ^ "." ^ name]) (List.filter (fun it -> (it : Parser.declaration).Parser.name = own) (file : Parser.source_file).Parser.declarations))

        let imports_for (name : string) (hints : hints) : string list =
          if String.equal "" name then [] else Lang.Lists.list_distinct (List.concat_map (fun (pkg, files) -> List.concat_map (fun f -> found_in name pkg f) (List.filter (fun f -> (f : Sources.source_text).Sources.project <> (Sources.CoreProject : Sources.project) && is_module_file f) files)) (List.filter (fun (pkg, _) -> Lang.Lists.list_is_not_empty pkg) (Collections.Maps.map_to_list ((hints : hints).tree : Sources.source_tree).Sources.packages)))

        let for_name (name : string) (namespace : namespace) : string =
          match Collections.Maps.map_get ((namespace : namespace).hints : hints).apart name with
          | Some file -> "; " ^ file ^ " declares it, but it has a main of its own, so it's a program apart from this one"
          | None -> match imports_for name (namespace : namespace).hints with
              | [] -> ""
              | imports -> ("; " ^ String.concat ", or " (List.map Fun.id (List.map (fun it -> "import " ^ it) imports))) ^ " has one"
      end

      module Imports = struct
        type known =
          | KnownModule
          | KnownType of { symbol : Symbols.symbol }
          | KnownSpec of { symbol : Symbols.symbol }
          | KnownFunction of { symbol : Symbols.symbol }

        let rec show_known (v : known) =
          match v with
          | KnownModule -> "KnownModule"
          | KnownType r -> "KnownType(" ^ "symbol=" ^ Symbols.show_symbol r.symbol ^ ")"
          | KnownSpec r -> "KnownSpec(" ^ "symbol=" ^ Symbols.show_symbol r.symbol ^ ")"
          | KnownFunction r -> "KnownFunction(" ^ "symbol=" ^ Symbols.show_symbol r.symbol ^ ")"

        type importable = { known : (string, known) Collections.Maps.map; members : (string, (string * string) list) Collections.Maps.map }

        let rec show_importable (v : importable) =
          "Importable(" ^ "known=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_known) v.known ^ ", members=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id (fk_show_list (fun (x0, x1) -> "(" ^ Fun.id x0 ^ ", " ^ Fun.id x1 ^ ")"))) v.members ^ ")"

        let known_names (table : Symbols.symbol_table) : (string, known) Collections.Maps.map =
          let declared = List.map (fun (name, symbol) -> (name, (KnownType { symbol = symbol } : known))) (List.concat_map (fun it -> Collections.Maps.map_to_list it) [(table : Symbols.symbol_table).Symbols.records; (table : Symbols.symbol_table).Symbols.case_types; (table : Symbols.symbol_table).Symbols.aliases; (table : Symbols.symbol_table).Symbols.annotation_types]) in
          let specs = List.map (fun (name, symbol) -> (name, (KnownSpec { symbol = symbol } : known))) (Collections.Maps.map_to_list (table : Symbols.symbol_table).Symbols.specs) in
          let functions = List.map (fun (name, symbol) -> (name, (KnownFunction { symbol = symbol } : known))) (Collections.Maps.map_to_list (table : Symbols.symbol_table).Symbols.functions) in
          let modules = List.map (fun (name, _) -> (name, (KnownModule : known))) (Collections.Maps.map_to_list (table : Symbols.symbol_table).Symbols.modules) in
          Collections.Maps.list_tuple_to_map (((declared @ specs) @ functions) @ modules)

        let parent_of (full : string) : string =
          String.concat "." (List.map Fun.id (Lang.Lists.list_drop_last ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) full ".") 1))

        let last_part (full : string) : string =
          Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) full ".")) ~default:full

        let operations_of (full : string) (known : (string, known) Collections.Maps.map) : (string * string) list =
          match Collections.Maps.map_get known full with
          | Some (KnownSpec { symbol = ({ Symbols.name = _; path = _; declaration = ({ Parser.at = _; name = _; definition = Parser.SpecDefinition { types = _; values = values; type_parameters = _; copy_of = _; parents = _ }; visibility = _; opaque = _; annotations = annotations } : Parser.declaration); file = _ } : Symbols.symbol) }) when List.exists (fun it -> (it : Parser.annotation).Parser.name = "Effect") annotations -> let prefix = if String.equal "" (parent_of full) then "" else parent_of full ^ "." in
              List.map (fun v -> ((v : Parser.spec_value).Parser.name, prefix ^ (v : Parser.spec_value).Parser.name)) values
          | _ -> []

        let importable_in (table : Symbols.symbol_table) : importable =
          let known = known_names table in
          let inside = let fk_arg1 = List.filter (fun (name, _) -> not (Lang.Strings.string_contains name "'")) (Collections.Maps.map_to_list known) in
            let fk_arg2 = Collections.Maps.empty_map () in
            List.fold_left (fun m entry -> let (name, _) = entry in
               let parent = parent_of name in
               Collections.Maps.map_put m parent (let fk_arg1 = Collections.Maps.map_get_or_default m parent [] in
                let fk_arg2 = [(last_part name, name)] in
                fk_arg1 @ fk_arg2)) fk_arg2 fk_arg1 in
          let cases = let fk_arg1 = Collections.Maps.map_to_list (table : Symbols.symbol_table).Symbols.case_types in
            let fk_arg2 = Collections.Maps.empty_map () in
            List.fold_left (fun m entry -> let (name, owner) = entry in
               let parent = parent_of name in
               Collections.Maps.map_put m parent (let fk_arg1 = Collections.Maps.map_get_or_default m parent [] in
                let fk_arg2 = List.map (fun c -> ((c : Parser.case_definition).Parser.name, name ^ "." ^ (c : Parser.case_definition).Parser.name)) (Symbols.Symbols.cases_of owner) in
                fk_arg1 @ fk_arg2)) fk_arg2 fk_arg1 in
          let parents = Lang.Lists.list_distinct (let fk_arg1 = List.map (fun (p, _) -> p) (Collections.Maps.map_to_list inside) in
             let fk_arg2 = List.map (fun (p, _) -> p) (Collections.Maps.map_to_list cases) in
             fk_arg1 @ fk_arg2) in
          let members = Collections.Maps.list_tuple_to_map (List.map (fun p -> let own = Collections.Maps.map_get_or_default inside p [] in
                (p, (let fk_arg1 = own @ Collections.Maps.map_get_or_default cases p [] in
                 let fk_arg2 = List.concat_map (fun (_, full) -> operations_of full known) own in
                 fk_arg1 @ fk_arg2))) parents) in
          ({ known = known; members = members } : importable)

        let implying (implied : (string, string list) Collections.Maps.map) (more : (string * string) list) : (string, string list) Collections.Maps.map =
          List.fold_left (fun acc entry -> let (name, target) = entry in
             let existing = Collections.Maps.map_get_or_default acc name [] in
             if List.mem target existing then acc else Collections.Maps.map_put acc name (existing @ [target])) implied more

        let is_extension (s : Symbols.symbol) : bool =
          match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.FunctionDefinition { type_parameters = _; receiver = Some _; parameters = _; result = _; body = _; external_ = _; operator = _ } -> true
          | _ -> false

        let is_method_of (path : string list) (table : Symbols.symbol_table) : bool =
          let parent = Lang.Lists.list_drop_last path 1 in
          let method_ = Option.value (Lang.Lists.list_last_or_none path) ~default:"" in
          Collections.Maps.map_any (table : Symbols.symbol_table).Symbols.functions (fun _ s -> ((s : Symbols.symbol).Symbols.path = parent && ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.name = method_) && is_extension s)

        let types_in (of_ : string) (importable : importable) : (string * string) list =
          List.filter (fun (_, full) -> match Collections.Maps.map_get (importable : importable).known full with
             | None -> true
             | Some (KnownType { symbol = _ }) -> true
             | Some (KnownSpec { symbol = _ }) -> true
             | _ -> false) (Collections.Maps.map_get_or_default (importable : importable).members of_ [])

        let alongside (full : string) (importable : importable) (table : Symbols.symbol_table) : (string * string) list =
          let known = (importable : importable).known in
          let types = match Collections.Maps.map_get known full with
            | Some KnownModule -> types_in full importable
            | _ -> [] in
          let cases = match Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.case_types full with
            | Some owner -> List.map (fun c -> ((c : Parser.case_definition).Parser.name, full ^ "." ^ (c : Parser.case_definition).Parser.name)) (Symbols.Symbols.cases_of owner)
            | None -> [] in
          (types @ operations_of full known) @ cases

        let bring (i : Parser.import) (file : Sources.loaded_file) (named : (string, string) Collections.Maps.map) (implied : (string, string list) Collections.Maps.map) (importable : importable) (table : Symbols.symbol_table) : (string, string) Collections.Maps.map * (string, string list) Collections.Maps.map =
          let known = (importable : importable).known in
          let full = String.concat "." (List.map Fun.id (i : Parser.import).Parser.path) in
          if (i : Parser.import).Parser.wildcard then if not (Collections.Maps.map_contains_key (table : Symbols.symbol_table).Symbols.modules full) then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = ((file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (i : Parser.import).Parser.at; message = "import " ^ full ^ ".* names no package or module" } : Diagnostics.diagnostic)) with
               | _ -> (assert false)) else (named, implying implied (Collections.Maps.map_get_or_default (importable : importable).members full [])) else if (not (Collections.Maps.map_contains_key known full) && not (Collections.Maps.map_contains_key (table : Symbols.symbol_table).Symbols.cases full)) && is_method_of (i : Parser.import).Parser.path table then (named, implied) else if not (Collections.Maps.map_contains_key known full) && not (Collections.Maps.map_contains_key (table : Symbols.symbol_table).Symbols.cases full) then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = ((file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (i : Parser.import).Parser.at; message = "import " ^ full ^ " names nothing" } : Diagnostics.diagnostic)) with
                 | _ -> (assert false)) else (let name = Option.value (i : Parser.import).Parser.alias ~default:(Option.value (Lang.Lists.list_last_or_none (i : Parser.import).Parser.path) ~default:full) in
                 match Collections.Maps.map_get named name with
                 | Some other when other <> full -> (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = ((file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (i : Parser.import).Parser.at; message = "'" ^ name ^ "' is imported already, as " ^ other ^ "; import this one as another name, with as" } : Diagnostics.diagnostic)) with
                      | _ -> (assert false))
                 | _ -> let fk_arg1 = Collections.Maps.map_put named name full in
                     let fk_arg2 = implying implied (alongside full importable table) in
                     (fk_arg1, fk_arg2))

        let of_ (file : Sources.loaded_file) (importable : importable) (table : Symbols.symbol_table) : file_imports =
          let (named, implied) = List.fold_left (fun acc i -> let (n, imp) = acc in
               bring i file n imp importable table) (let fk_arg1 = Collections.Maps.empty_map () in
             let fk_arg2 = Collections.Maps.empty_map () in
             (fk_arg1, fk_arg2)) (file : Sources.loaded_file).Sources.imports in
          let fk_arg1 = Collections.Maps.map_put_all (Collections.Maps.list_tuple_to_map (List.map (fun (name, targets) -> (name, Option.value (List.nth_opt targets 0) ~default:"")) (Collections.Maps.map_to_list (Collections.Maps.map_filter implied (fun _ targets -> List.length targets = 1))))) named in
          let fk_arg2 = Collections.Maps.map_filter implied (fun name targets -> List.length targets > 1 && not (Collections.Maps.map_contains_key named name)) in
          ({ named = fk_arg1; ambiguous = fk_arg2 } : file_imports)

        let all_of (files : Sources.loaded_file list) (table : Symbols.symbol_table) : (Sources.loaded_file * file_imports) list =
          let importable = importable_in table in
          List.map (fun file -> (file, of_ file importable table)) files
      end

      let type_scope_default_parameters () : string list =
        []

      module Specs = struct
        let rec own_types_seen (spec : Parser.declaration) (place : place) (namespace : namespace) (seen : string list) : string list =
          match (spec : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = types; values = _; type_parameters = _; copy_of = _; parents = parents } -> let fk_arg1 = List.map (fun it -> (it : Parser.spec_type).Parser.name) types in
              let fk_arg2 = List.concat_map (fun parent -> match parent with
                   | Parser.NamedType { at = _; name = name; arguments = _ } -> (match Names.find name ((namespace : namespace).table : Symbols.symbol_table).Symbols.specs (fun s -> Some s) (fun full -> Collections.Maps.map_contains_key ((namespace : namespace).table : Symbols.symbol_table).Symbols.specs full) place namespace (Skipping : strictness) with
                        | Found { value = found } when not (List.mem (found : Symbols.symbol).Symbols.name seen) -> own_types_seen (found : Symbols.symbol).Symbols.declaration ({ file = (found : Symbols.symbol).Symbols.file; path = (found : Symbols.symbol).Symbols.path } : place) namespace (seen @ [(found : Symbols.symbol).Symbols.name])
                        | _ -> [])
                   | _ -> []) parents in
              fk_arg1 @ fk_arg2
          | _ -> []

        let own_types (spec : Parser.declaration) (place : place) (namespace : namespace) : string list =
          own_types_seen spec place namespace []
      end

      module WrittenTypes = struct
        let rec type_ref_of (v : Parser.annotation_value) : Parser.type_ref option =
          match v with
          | Parser.Reference { at = at; name = name; type_arguments = type_arguments; arguments = None } -> Some (Parser.NamedType { at = at; name = name; arguments = Option.value type_arguments ~default:[] } : Parser.type_ref)
          | Parser.ValueTuple { at = at; items = items } -> let refs = Lang.Lists.list_map_not_null items (fun it -> type_ref_of it) in
              if let fk_arg1 = List.length refs in
              let fk_arg2 = List.length items in
              fk_arg1 = fk_arg2 then Some (Parser.TupleType { at = at; elements = refs } : Parser.type_ref) else None
          | _ -> None

        let rec in_type_ref (t : Parser.type_ref) (scope : type_scope) : written_type list =
          match t with
          | Parser.NamedType { at = at; name = name; arguments = arguments } -> ({ at = at; name = name; scope = scope } : written_type) :: List.concat_map (fun it -> in_type_ref it scope) arguments
          | Parser.FunctionType { at = _; parameters = parameters; result = result; effects = _ } -> let fk_arg1 = List.concat_map (fun it -> in_type_ref it scope) parameters in
              let fk_arg2 = in_type_ref result scope in
              fk_arg1 @ fk_arg2
          | Parser.TupleType { at = _; elements = elements } -> List.concat_map (fun it -> in_type_ref it scope) elements
          | Parser.EffectsType { at = _; effects = _ } -> []
          | Parser.GivenType { at = _; name = _; given = given } -> in_type_ref given scope

        let rec in_arguments (arguments : Parser.annotation_argument list) (annotation : Symbols.symbol) (place : place) (namespace : namespace) : written_type list =
          let fields = match ((annotation : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
            | Parser.RecordDefinition { type_parameters = _; fields = fs; private_constructor = _; annotation = _; external_ = _ } -> fs
            | _ -> [] in
          let scope = ({ place = place; type_parameters = []; spec_types = []; parameters = type_scope_default_parameters () } : type_scope) in
          List.concat_map (fun (i, argument) -> let field = match (argument : Parser.annotation_argument).Parser.name with
               | Some n -> List.find_opt (fun it -> (it : Parser.field).Parser.name = n) fields
               | None -> Lang.Options.option_or_else (Lang.Lists.list_get_or_none fields i) (fun () -> Lang.Options.option_filter (Lang.Lists.list_last_or_none fields) (fun it -> (it : Parser.field).Parser.vararg)) in
             Option.value (Option.map (fun f -> in_argument (argument : Parser.annotation_argument).Parser.value (f : Parser.field).Parser.field_type ((f : Parser.field).Parser.vararg && Option.is_none (argument : Parser.annotation_argument).Parser.name) scope namespace) field) ~default:[]) (Lang.Lists.list_with_index arguments)
        and in_argument (v : Parser.annotation_value) (field_type : Parser.type_ref) (item : bool) (scope : type_scope) (namespace : namespace) : written_type list =
          match (field_type, v) with
          | (Parser.NamedType { at = _; name = "List"; arguments = [item_type] }, Parser.ValueList { at = _; items = items }) when not item -> List.concat_map (fun it -> in_argument it item_type false scope namespace) items
          | (Parser.NamedType { at = _; name = "List"; arguments = [item_type] }, _) when item -> in_argument v item_type false scope namespace
          | (Parser.TupleType { at = _; elements = elements }, Parser.ValueTuple { at = _; items = items }) -> List.concat_map (fun (value, t) -> in_argument value t false scope namespace) (Lang.Lists.list_zip items elements)
          | (Parser.NamedType { at = _; name = "Type"; arguments = [] }, _) -> Option.value (Option.map (fun it -> in_type_ref it scope) (type_ref_of v)) ~default:[]
          | (Parser.NamedType { at = _; name = name; arguments = [] }, Parser.Reference { at = _; name = n; type_arguments = None; arguments = Some nested }) -> (match Lookups.annotation_type name (scope : type_scope).place namespace (Skipping : strictness) with
               | Found { value = annotation } -> in_arguments nested annotation (scope : type_scope).place namespace
               | _ -> [])
          | _ -> []

        let in_annotations (annotations : Parser.annotation list) (place : place) (namespace : namespace) : written_type list =
          List.concat_map (fun a -> match Lookups.annotation_type (a : Parser.annotation).Parser.name place namespace (Skipping : strictness) with
             | Found { value = declared } -> in_arguments (a : Parser.annotation).Parser.arguments declared place namespace
             | _ -> []) annotations

        let in_annotated (d : Parser.declaration) (place : place) (namespace : namespace) : written_type list =
          match (d : Parser.declaration).Parser.definition with
          | Parser.RecordDefinition { type_parameters = _; fields = fields; private_constructor = _; annotation = _; external_ = _ } -> List.concat_map (fun it -> in_annotations (it : Parser.field).Parser.annotations place namespace) fields
          | Parser.CasesDefinition { type_parameters = _; cases = cases; case_refs = _; includes = _ } -> List.concat_map (fun c -> let fk_arg1 = in_annotations (c : Parser.case_definition).Parser.annotations place namespace in
                 let fk_arg2 = List.concat_map (fun it -> in_annotations (it : Parser.field).Parser.annotations place namespace) (c : Parser.case_definition).Parser.fields in
                 fk_arg1 @ fk_arg2) cases
          | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = parameters; result = _; body = _; external_ = _; operator = _ } -> List.concat_map (fun it -> in_annotations (it : Parser.parameter).Parser.annotations place namespace) (Option.value parameters ~default:[])
          | Parser.SpecDefinition { types = _; values = values; type_parameters = _; copy_of = _; parents = _ } -> List.concat_map (fun it -> in_annotations (it : Parser.spec_value).Parser.annotations place namespace) values
          | _ -> []

        let is_annotation (name : string) (place : place) (namespace : namespace) : bool =
          let annotations = ((namespace : namespace).table : Symbols.symbol_table).Symbols.annotation_types in
          match Names.find name annotations (fun s -> Some s) (fun full -> Collections.Maps.map_contains_key annotations full) place namespace (Skipping : strictness) with
          | Found { value = _ } -> true
          | _ -> false

        let rec in_meta_type_ref (t : Parser.type_ref) (scope : type_scope) (namespace : namespace) : written_type list =
          match t with
          | Parser.TupleType { at = _; elements = elements } -> List.concat_map (fun it -> in_meta_type_ref it scope namespace) elements
          | Parser.NamedType { at = _; name = "Type"; arguments = _ } -> []
          | Parser.NamedType { at = _; name = "Spec"; arguments = _ } -> []
          | Parser.NamedType { at = _; name = "Function"; arguments = _ } -> []
          | Parser.NamedType { at = _; name = "Module"; arguments = _ } -> []
          | Parser.NamedType { at = _; name = "Case"; arguments = arguments } -> List.concat_map (fun it -> in_type_ref it scope) (List.take 1 arguments)
          | Parser.NamedType { at = _; name = "Field"; arguments = [record; Parser.NamedType { at = _; name = "_"; arguments = [] }] } -> in_type_ref record scope
          | Parser.NamedType { at = _; name = "Field"; arguments = arguments } -> List.concat_map (fun it -> in_type_ref it scope) arguments
          | Parser.NamedType { at = _; name = "List"; arguments = [item] } -> in_meta_type_ref item scope namespace
          | Parser.NamedType { at = _; name = name; arguments = _ } when is_annotation name (scope : type_scope).place namespace -> []
          | _ -> in_type_ref t scope

        let rec in_parameter (p : Parser.parameter) (scope : type_scope) : written_type list =
          let fk_arg1 = List.concat_map (fun it -> in_type_ref it scope) (Option.to_list (p : Parser.parameter).Parser.parameter_type) in
          let fk_arg2 = List.concat_map (fun it -> in_expression it scope) (Option.to_list (p : Parser.parameter).Parser.default) in
          fk_arg1 @ fk_arg2
        and in_expressions (es : Parser.expression list) (scope : type_scope) : written_type list =
          List.concat_map (fun it -> in_expression it scope) es
        and in_expression (e : Parser.expression) (scope : type_scope) : written_type list =
          match e with
          | Parser.Compiled { at = _ } -> []
          | Parser.IntConstant { at = _; value = _ } -> []
          | Parser.FloatConstant { at = _; value = _ } -> []
          | Parser.BooleanConstant { at = _; value = _ } -> []
          | Parser.CharConstant { at = _; value = _ } -> []
          | Parser.Name { at = _; name = _ } -> []
          | Parser.StringTemplate { at = _; parts = parts } -> List.concat_map (fun part -> match part with
                 | Parser.TemplateText { text = _ } -> []
                 | Parser.Interpolation { expression = inner } -> in_expression inner scope) parts
          | Parser.Tuple { at = _; elements = elements } -> in_expressions elements scope
          | Parser.ListOf { at = _; items = items } -> in_expressions items scope
          | Parser.Spread { at = _; list = list } -> in_expression list scope
          | Parser.Call { at = _; callee = callee; arguments = arguments; type_arguments = type_arguments } -> let fk_arg1 = let fk_arg1 = in_expression callee scope in
                let fk_arg2 = List.concat_map (fun it -> in_type_ref it scope) type_arguments in
                fk_arg1 @ fk_arg2 in
              let fk_arg2 = in_expressions (List.map (fun it -> (it : Parser.argument).Parser.value) arguments) scope in
              fk_arg1 @ fk_arg2
          | Parser.Member { at = _; target = target; name = _ } -> in_expression target scope
          | Parser.Binary { at = _; operator = _; left = left; right = right } -> let fk_arg1 = in_expression left scope in
              let fk_arg2 = in_expression right scope in
              fk_arg1 @ fk_arg2
          | Parser.Unary { at = _; operator = _; operand = operand } -> in_expression operand scope
          | Parser.Assign { at = _; target = target; value = value } -> let fk_arg1 = in_expression target scope in
              let fk_arg2 = in_expression value scope in
              fk_arg1 @ fk_arg2
          | Parser.Lambda { at = _; parameters = parameters; body = body; ignores_arguments = _ } -> let fk_arg1 = List.concat_map (fun it -> in_parameter it scope) parameters in
              let fk_arg2 = in_expression body scope in
              fk_arg1 @ fk_arg2
          | Parser.Pipe { at = _; value = value; function_ = function_ } -> let fk_arg1 = in_expression value scope in
              let fk_arg2 = in_expression function_ scope in
              fk_arg1 @ fk_arg2
          | Parser.If { at = _; condition = condition; then_ = then_; otherwise = otherwise; has_else = _ } -> in_expressions [condition; then_; otherwise] scope
          | Parser.When { at = _; subject = subject; branches = branches } -> let fk_arg1 = List.concat_map (fun it -> in_expression it scope) (Option.to_list subject) in
              let fk_arg2 = List.concat_map (fun b -> let fk_arg1 = let fk_arg1 = let fk_arg1 = List.concat_map (fun it -> in_pattern it scope) (b : Parser.branch).Parser.patterns in
                       let fk_arg2 = List.concat_map (fun it -> in_expression it scope) (Option.to_list (b : Parser.branch).Parser.condition) in
                       fk_arg1 @ fk_arg2 in
                     let fk_arg2 = List.concat_map (fun it -> in_expression it scope) (Option.to_list (b : Parser.branch).Parser.guard) in
                     fk_arg1 @ fk_arg2 in
                   let fk_arg2 = in_expression (b : Parser.branch).Parser.body scope in
                   fk_arg1 @ fk_arg2) branches in
              fk_arg1 @ fk_arg2
          | Parser.Block { at = _; statements = statements; result = result; ends_in_binding = _ } -> let fk_arg1 = List.concat_map (fun it -> in_statement it scope) statements in
              let fk_arg2 = in_expression result scope in
              fk_arg1 @ fk_arg2
          | Parser.Monadic { at = _; monad = monad; block = block } -> let fk_arg1 = in_expression monad scope in
              let fk_arg2 = in_expression block scope in
              fk_arg1 @ fk_arg2
          | Parser.Handle { at = _; handler = handler; block = block; parameters = parameters } -> let fk_arg1 = let fk_arg1 = in_expression handler scope in
                let fk_arg2 = List.concat_map (fun it -> in_parameter it scope) (Option.value parameters ~default:[]) in
                fk_arg1 @ fk_arg2 in
              let fk_arg2 = in_expression block scope in
              fk_arg1 @ fk_arg2
        and in_pattern (p : Parser.pattern) (scope : type_scope) : written_type list =
          match p with
          | Parser.ConstantPattern { at = _; expression = e } -> in_expression e scope
          | Parser.TuplePattern { at = _; elements = elements } -> List.concat_map (fun it -> in_pattern it scope) elements
          | Parser.ListPattern { at = _; elements = elements; rest = rest } -> let fk_arg1 = List.concat_map (fun it -> in_pattern it scope) elements in
              let fk_arg2 = List.concat_map (fun it -> in_pattern it scope) (Option.to_list rest) in
              fk_arg1 @ fk_arg2
          | Parser.CasePattern { at = _; name = _; arguments = arguments; check = _; qualifier = _ } -> List.concat_map (fun it -> in_pattern it scope) (Option.value arguments ~default:[])
          | _ -> []
        and in_statement (s : Parser.statement) (scope : type_scope) : written_type list =
          match s with
          | Parser.Binding { at = _; name = _; parameters = parameters; value_type = value_type; value = value; variable = _ } -> let fk_arg1 = let fk_arg1 = List.concat_map (fun it -> in_parameter it scope) (Option.value parameters ~default:[]) in
                let fk_arg2 = List.concat_map (fun it -> in_type_ref it scope) (Option.to_list value_type) in
                fk_arg1 @ fk_arg2 in
              let fk_arg2 = in_expression value scope in
              fk_arg1 @ fk_arg2
          | Parser.Evaluation { at = _; expression = e } -> in_expression e scope
          | Parser.Destructuring { at = _; pattern = pattern; value = value } -> let fk_arg1 = in_pattern pattern scope in
              let fk_arg2 = in_expression value scope in
              fk_arg1 @ fk_arg2
          | Parser.Bind { at = _; pattern = pattern; value = value } -> let fk_arg1 = in_pattern pattern scope in
              let fk_arg2 = in_expression value scope in
              fk_arg1 @ fk_arg2

        let in_fields (fields : Parser.field list) (scope : type_scope) : written_type list =
          List.concat_map (fun f -> let fk_arg1 = in_type_ref (f : Parser.field).Parser.field_type scope in
             let fk_arg2 = List.concat_map (fun it -> in_expression it scope) (Option.to_list (f : Parser.field).Parser.default) in
             fk_arg1 @ fk_arg2) fields

        let rec in_declarations (declarations : Parser.declaration list) (place : place) (module_type_parameters : string list) (namespace : namespace) (borrowed : (string, Sources.loaded_file) Collections.Maps.map) : written_type list =
          List.concat_map (fun it -> in_declaration it place module_type_parameters namespace borrowed) (List.filter (fun d -> not (Collections.Maps.map_contains_key borrowed (String.concat "." (List.map Fun.id ((place : place).path @ [(d : Parser.declaration).Parser.name]))))) declarations)
        and in_declaration (d : Parser.declaration) (place : place) (module_type_parameters : string list) (namespace : namespace) (borrowed : (string, Sources.loaded_file) Collections.Maps.map) : written_type list =
          let fk_arg1 = let fk_arg1 = in_annotations (d : Parser.declaration).Parser.annotations place namespace in
            let fk_arg2 = in_annotated d place namespace in
            fk_arg1 @ fk_arg2 in
          let fk_arg2 = in_definition d place module_type_parameters namespace borrowed in
          fk_arg1 @ fk_arg2
        and in_definition (d : Parser.declaration) (place : place) (module_type_parameters : string list) (namespace : namespace) (borrowed : (string, Sources.loaded_file) Collections.Maps.map) : written_type list =
          match (d : Parser.declaration).Parser.definition with
          | Parser.RecordDefinition { type_parameters = type_parameters; fields = fields; private_constructor = _; annotation = true; external_ = _ } -> List.concat_map (fun it -> in_meta_type_ref (it : Parser.field).Parser.field_type ({ place = place; type_parameters = type_parameters; spec_types = []; parameters = type_scope_default_parameters () } : type_scope) namespace) fields
          | Parser.RecordDefinition { type_parameters = type_parameters; fields = fields; private_constructor = _; annotation = _; external_ = _ } -> in_fields fields ({ place = place; type_parameters = type_parameters; spec_types = []; parameters = type_scope_default_parameters () } : type_scope)
          | Parser.CasesDefinition { type_parameters = type_parameters; cases = cases; case_refs = _; includes = includes } -> let scope = ({ place = place; type_parameters = type_parameters; spec_types = []; parameters = type_scope_default_parameters () } : type_scope) in
              let fk_arg1 = List.concat_map (fun it -> in_fields (it : Parser.case_definition).Parser.fields scope) cases in
              let fk_arg2 = List.concat_map (fun it -> in_type_ref it scope) includes in
              fk_arg1 @ fk_arg2
          | Parser.AliasDefinition { type_parameters = type_parameters; target = target } -> in_type_ref target ({ place = place; type_parameters = module_type_parameters @ type_parameters; spec_types = []; parameters = type_scope_default_parameters () } : type_scope)
          | Parser.FunctionDefinition { type_parameters = type_parameters; receiver = receiver; parameters = parameters; result = result; body = body; external_ = _; operator = _ } -> let scope = ({ place = place; type_parameters = type_parameters; spec_types = []; parameters = List.map (fun it -> (it : Parser.parameter).Parser.name) (Option.value parameters ~default:[]) } : type_scope) in
              let fk_arg1 = let fk_arg1 = let fk_arg1 = List.concat_map (fun it -> in_type_ref it scope) (Option.to_list receiver) in
                  let fk_arg2 = List.concat_map (fun it -> in_parameter it scope) (Option.value parameters ~default:[]) in
                  fk_arg1 @ fk_arg2 in
                let fk_arg2 = List.concat_map (fun it -> in_type_ref it scope) (Option.to_list result) in
                fk_arg1 @ fk_arg2 in
              let fk_arg2 = in_expression body scope in
              fk_arg1 @ fk_arg2
          | Parser.ModuleDefinition { declarations = declarations; spec = _; parameters = _; application = _; type_parameters = type_parameters } -> let full = String.concat "." (List.map Fun.id ((place : place).path @ [(d : Parser.declaration).Parser.name])) in
              let made = List.map (fun (name, _) -> name) (List.filter (fun (_, application) -> ((application : made).functor_ : Symbols.symbol).Symbols.name = full) (Collections.Maps.map_to_list ((namespace : namespace).modules : modules).applications)) in
              List.concat_map (fun reading -> in_declarations declarations ({ file = (place : place).file; path = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) reading "." } : place) (module_type_parameters @ type_parameters) namespace borrowed) ([full] @ made)
          | Parser.SpecDefinition { types = _; values = values; type_parameters = type_parameters; copy_of = _; parents = _ } -> let scope = let fk_arg1 = Specs.own_types d place namespace in
                let fk_arg2 = type_scope_default_parameters () in
                ({ place = place; type_parameters = type_parameters; spec_types = fk_arg1; parameters = fk_arg2 } : type_scope) in
              List.concat_map (fun v -> let inner = ({ place = place; type_parameters = (scope : type_scope).type_parameters @ (v : Parser.spec_value).Parser.type_parameters; spec_types = (scope : type_scope).spec_types; parameters = type_scope_default_parameters () } : type_scope) in
                 let fk_arg1 = let fk_arg1 = List.concat_map (fun it -> in_parameter it inner) (Option.value (v : Parser.spec_value).Parser.parameters ~default:[]) in
                   let fk_arg2 = in_type_ref (v : Parser.spec_value).Parser.value_type inner in
                   fk_arg1 @ fk_arg2 in
                 let fk_arg2 = List.concat_map (fun it -> in_expression it inner) (Option.to_list (v : Parser.spec_value).Parser.default) in
                 fk_arg1 @ fk_arg2) values

        let in_file (file : Sources.loaded_file) (namespace : namespace) (borrowed : (string, Sources.loaded_file) Collections.Maps.map) : written_type list =
          let fk_arg1 = in_declarations (file : Sources.loaded_file).Sources.declarations ({ file = file; path = (file : Sources.loaded_file).Sources.package } : place) [] namespace borrowed in
          let fk_arg2 = List.concat_map (fun (name, _) -> Option.value (Option.map (fun f -> in_declaration (f : Symbols.symbol).Symbols.declaration ({ file = file; path = (f : Symbols.symbol).Symbols.path } : place) [] namespace (Collections.Maps.empty_map ())) (Collections.Maps.map_get ((namespace : namespace).table : Symbols.symbol_table).Symbols.functions name)) ~default:[]) (List.filter (fun (_, from) -> ((from : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path = ((file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path) (Collections.Maps.map_to_list borrowed)) in
          fk_arg1 @ fk_arg2
      end

      module TypeNames = struct
        let not_declared (name : string) (scope : type_scope) (namespace : namespace) : type_meaning lookup =
          match Lookups.spec name (scope : type_scope).place namespace (Skipping : strictness) with
          | Found { value = spec } -> (Found { value = (SpecModuleType { spec = spec } : type_meaning) } : type_meaning lookup)
          | _ -> match Lookups.annotation_type name (scope : type_scope).place namespace (Skipping : strictness) with
              | Found { value = _ } -> (Refused { message = "'" ^ name ^ "' is an annotation, written @" ^ name ^ "(...) before a declaration; no value has its type" } : type_meaning lookup)
              | _ -> if List.mem ("@" ^ name) (scope : type_scope).type_parameters then (Refused { message = "'" ^ name ^ "' is an effect parameter, written @" ^ name ^ ", as in @" ^ name ^ " () -> Unit" } : type_meaning lookup) else if name = "_" then (Refused { message = "'_' only marks a spec type's parameters, as in Monad<Result<_, String>>" } : type_meaning lookup) else (Refused { message = "unknown type '" ^ name ^ "'" ^ ImportHints.for_name name namespace } : type_meaning lookup)

        let meaning (name : string) (scope : type_scope) (namespace : namespace) : type_meaning lookup =
          if Lang.Strings.string_contains name "." && List.mem (Option.value (List.nth_opt ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".") 0) ~default:"") (scope : type_scope).parameters then (NotFound : type_meaning lookup) else if List.mem name (scope : type_scope).type_parameters then (Found { value = (TypeParameterType { name = name } : type_meaning) } : type_meaning lookup) else if List.mem name (scope : type_scope).spec_types then (Found { value = (SpecOwnType { name = name } : type_meaning) } : type_meaning lookup) else if Collections.Maps.map_contains_key Types.Types.builtins name then (Found { value = (BuiltinType { name = name } : type_meaning) } : type_meaning lookup) else (match Lookups.any_type name (scope : type_scope).place namespace (Refusing : strictness) with
                   | Found { value = symbol } -> (Found { value = (DeclaredType { symbol = symbol } : type_meaning) } : type_meaning lookup)
                   | Refused { message = why } -> (Refused { message = why } : type_meaning lookup)
                   | NotFound -> not_declared name scope namespace)
      end

      module Resolution = struct
        let no_modules =
          let fk_arg1 = Collections.Maps.empty_map () in
          let fk_arg2 = Collections.Maps.empty_map () in
          let fk_arg3 = Collections.Maps.empty_map () in
          let fk_arg4 = Collections.Maps.empty_map () in
          let fk_arg5 = Collections.Maps.empty_map () in
          let fk_arg6 = Collections.Maps.empty_map () in
          ({ specs = fk_arg1; parameter_modules = []; parameter_members = []; applications = fk_arg2; aliases = fk_arg3; copy_origins = fk_arg4; fixed_types = fk_arg5; lifted = fk_arg6 } : modules)

        let namespace (workspace : Sources.workspace) (tree : Sources.source_tree) : namespace =
          let table = Symbols.Symbols.table workspace in
          ({ table = table; imports = Collections.Maps.list_tuple_to_map (List.map (fun (file, imports) -> (((file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path, imports)) (Imports.all_of (workspace : Sources.workspace).Sources.files table)); modules = no_modules; hints = ({ tree = tree; apart = (workspace : Sources.workspace).Sources.apart } : hints) } : namespace)

        let resolved_types (file : Sources.loaded_file) (namespace : namespace) (borrowed : (string, Sources.loaded_file) Collections.Maps.map) : resolved_type list =
          Lang.Lists.list_map_not_null (WrittenTypes.in_file file namespace borrowed) (fun written -> match TypeNames.meaning (written : written_type).name (written : written_type).scope namespace with
             | Found { value = meaning } -> Some ({ written = written; meaning = meaning } : resolved_type)
             | Refused { message = why } -> Effect.perform (Diagnostics.Reporting_report ({ Diagnostics.file = ((file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (written : written_type).at; message = why } : Diagnostics.diagnostic));
                 None
             | NotFound -> None)
      end
    end

    module Functors = struct
      module Functors = struct
        type building = { namespace : Resolution.namespace; mutable declarations : Symbols.symbol list; mutable parameters : (string, (string * Symbols.symbol) list) Collections.Maps.map; mutable parameter_modules : string list; mutable parameter_members : string list; mutable parameter_specs : (string, Symbols.symbol) Collections.Maps.map; mutable applications : (string, Resolution.made) Collections.Maps.map; mutable aliases : (string, string) Collections.Maps.map; mutable copy_origins : (string, string) Collections.Maps.map; mutable fixed_types : (string, Symbols.symbol) Collections.Maps.map; mutable lifted : (Resolution.call_site, string) Collections.Maps.map; mutable lifted_count : int }

        let rec show_building (v : building) =
          "Building(" ^ "namespace=" ^ Resolution.show_namespace v.namespace ^ ", declarations=" ^ fk_show_list Symbols.show_symbol v.declarations ^ ", parameters=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id (fk_show_list (fun (x0, x1) -> "(" ^ Fun.id x0 ^ ", " ^ Symbols.show_symbol x1 ^ ")"))) v.parameters ^ ", parameterModules=" ^ fk_show_list Fun.id v.parameter_modules ^ ", parameterMembers=" ^ fk_show_list Fun.id v.parameter_members ^ ", parameterSpecs=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Symbols.show_symbol) v.parameter_specs ^ ", applications=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Resolution.show_made) v.applications ^ ", aliases=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Fun.id) v.aliases ^ ", copyOrigins=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Fun.id) v.copy_origins ^ ", fixedTypes=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Symbols.show_symbol) v.fixed_types ^ ", lifted=" ^ (fun v -> Collections.Maps.map_to_string v Resolution.show_call_site Fun.id) v.lifted ^ ", liftedCount=" ^ string_of_int v.lifted_count ^ ")"

        let is_functor (s : Symbols.symbol) : bool =
          match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _ :: _; application = _; type_parameters = _ } -> true
          | _ -> false

        let enclosing_functor (building : building) (path : string list) : Symbols.symbol option =
          List.nth_opt (Lang.Lists.list_map_not_null (List.mapi (fun i _ -> String.concat "." (List.map Fun.id (List.take (i + 1) path))) path) (fun name -> List.find_opt (fun d -> (d : Symbols.symbol).Symbols.name = name && is_functor d) (building : building).declarations)) 0

        let problem (s : Symbols.symbol) (at : Parser.position) (message : string) : Diagnostics.diagnostic =
          ({ Diagnostics.file = (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = message } : Diagnostics.diagnostic)

        let is_blank (t : Parser.type_ref) : bool =
          match t with
          | Parser.NamedType { at = _; name = "_"; arguments = [] } -> true
          | _ -> false

        let rec filled (arguments : Parser.type_ref list) (given : Parser.type_ref list) : Parser.type_ref list =
          match arguments with
          | [] -> []
          | first :: rest -> match given with
              | g :: more when is_blank first -> g :: filled rest more
              | _ -> first :: filled rest given

        let fix_types (building : building) (parameter_module : string) (f : Symbols.symbol) (spec : Symbols.symbol) (ref : Parser.type_ref) : unit =
          match ref with
          | Parser.NamedType { at = at; name = _; arguments = arguments } -> let types = match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
                | Parser.SpecDefinition { types = ts; values = _; type_parameters = _; copy_of = _; parents = _ } -> ts
                | _ -> [] in
              let spec_name = Symbols.Symbols.simple_name spec in
              if let fk_arg1 = List.length arguments in
              let fk_arg2 = List.length types in
              fk_arg1 > fk_arg2 then (match Effect.perform (Diagnostics.Abandoning_abandon (problem f at (let fk_arg1 = string_of_int (List.length types) in
                    let fk_arg2 = if List.length types = 1 then "" else "s" in
                    let fk_arg3 = string_of_int (List.length arguments) in
                    spec_name ^ " has " ^ fk_arg1 ^ " type" ^ fk_arg2 ^ ", so it takes at most that many type arguments, not " ^ fk_arg3))) with
                 | _ -> (assert false)) else ();
              List.iter (fun (t, argument) -> let parameters = List.map (fun p -> (Parser.NamedType { at = Symbols.Positions.of_type argument; name = p; arguments = [] } : Parser.type_ref)) (t : Parser.spec_type).Parser.type_parameters in
                 let target = if List.is_empty parameters then argument else (match argument with
                      | Parser.NamedType { at = arg_at; name = arg_name; arguments = arg_arguments } -> let holes = Lang.Lists.list_count arg_arguments (fun it -> is_blank it) in
                          if holes = 0 then (Parser.NamedType { at = arg_at; name = arg_name; arguments = arg_arguments @ parameters } : Parser.type_ref) else if holes <> List.length parameters then (match Effect.perform (Diagnostics.Abandoning_abandon (problem f arg_at (let fk_arg1 = string_of_int (List.length parameters) in
                                  let fk_arg2 = if List.length parameters = 1 then "" else "s" in
                                  let fk_arg3 = string_of_int (List.length parameters) in
                                  spec_name ^ "'s " ^ (t : Parser.spec_type).Parser.name ^ " takes " ^ fk_arg1 ^ " type parameter" ^ fk_arg2 ^ ", so " ^ arg_name ^ " needs " ^ fk_arg3 ^ " '_', not " ^ string_of_int holes))) with
                               | _ -> (assert false)) else (Parser.NamedType { at = arg_at; name = arg_name; arguments = filled arg_arguments parameters } : Parser.type_ref)
                      | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (problem f (Symbols.Positions.of_type argument) (spec_name ^ "'s " ^ (t : Parser.spec_type).Parser.name ^ " takes type parameters, so it needs a named type, like Option"))) with
                          | _ -> (assert false)) in
                 let alias_name = String.concat "." (List.map Fun.id ((f : Symbols.symbol).Symbols.path @ [Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) parameter_module ".")) ~default:parameter_module ^ "#" ^ (t : Parser.spec_type).Parser.name])) in
                 let alias = ({ Symbols.name = alias_name; path = (f : Symbols.symbol).Symbols.path; declaration = (let fk_arg1 = Symbols.Positions.of_type argument in
                    let fk_arg2 = Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) alias_name ".")) ~default:alias_name in
                    let fk_arg3 = Parser.declaration_default_visibility () in
                    let fk_arg4 = Parser.declaration_default_opaque () in
                    let fk_arg5 = Parser.declaration_default_annotations () in
                    ({ Parser.at = fk_arg1; name = fk_arg2; definition = (Parser.AliasDefinition { type_parameters = (t : Parser.spec_type).Parser.type_parameters; target = target } : Parser.definition); visibility = fk_arg3; opaque = fk_arg4; annotations = fk_arg5 } : Parser.declaration)); file = (f : Symbols.symbol).Symbols.file } : Symbols.symbol) in
                 building.declarations <- (building : building).declarations @ [alias];
                 building.fixed_types <- Collections.Maps.map_put (building : building).fixed_types (parameter_module ^ "." ^ (t : Parser.spec_type).Parser.name) alias) (Lang.Lists.list_zip types arguments)
          | _ -> ()

        let add_parameters (building : building) (f : Symbols.symbol) : unit =
          match ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.ModuleDefinition { declarations = _; spec = _; parameters = parameters; application = _; type_parameters = _ } -> Option.iter (fun outer -> match Effect.perform (Diagnostics.Abandoning_abandon (problem f ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at ("a functor can't be inside another functor (" ^ Symbols.Symbols.simple_name outer ^ ") yet"))) with
                 | _ -> (assert false)) (enclosing_functor building (f : Symbols.symbol).Symbols.path);
              let place = ({ Resolution.file = (f : Symbols.symbol).Symbols.file; path = (f : Symbols.symbol).Symbols.path } : Resolution.place) in
              List.iteri (fun i p -> if List.exists (fun it -> (it : Parser.module_parameter).Parser.name = (p : Parser.module_parameter).Parser.name) (List.take i parameters) then (match Effect.perform (Diagnostics.Abandoning_abandon (problem f (p : Parser.module_parameter).Parser.at ("'" ^ (p : Parser.module_parameter).Parser.name ^ "' is declared twice"))) with
                    | _ -> (assert false)) else ()) parameters;
              let found = List.map (fun p -> let spec_name = match (p : Parser.module_parameter).Parser.spec with
                     | Parser.NamedType { at = _; name = n; arguments = _ } -> n
                     | _ -> "" in
                   let spec = match Resolution.Lookups.spec spec_name place (building : building).namespace (Resolution.Refusing : Resolution.strictness) with
                     | Resolution.Found { value = s } -> s
                     | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem f (Symbols.Positions.of_type (p : Parser.module_parameter).Parser.spec) why)) with
                          | _ -> (assert false))
                     | Resolution.NotFound -> match Effect.perform (Diagnostics.Abandoning_abandon (let fk_arg1 = Symbols.Positions.of_type (p : Parser.module_parameter).Parser.spec in
                           let fk_arg2 = "unknown spec '" ^ spec_name ^ "'" ^ Resolution.ImportHints.for_name spec_name (building : building).namespace in
                           problem f fk_arg1 fk_arg2)) with
                         | _ -> (assert false) in
                   let name = (f : Symbols.symbol).Symbols.name ^ "." ^ (p : Parser.module_parameter).Parser.name in
                   if List.exists (fun it -> (it : Symbols.symbol).Symbols.name = name && Symbols.Symbols.is_module it) (building : building).declarations then (match Effect.perform (Diagnostics.Abandoning_abandon (problem f (p : Parser.module_parameter).Parser.at (Symbols.Symbols.simple_name f ^ " has a module named " ^ (p : Parser.module_parameter).Parser.name ^ " already"))) with
                      | _ -> (assert false)) else ();
                   let (types, values) = match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
                     | Parser.SpecDefinition { types = ts; values = vs; type_parameters = _; copy_of = _; parents = _ } -> (ts, vs)
                     | _ -> ([], []) in
                   fix_types building name f spec (p : Parser.module_parameter).Parser.spec;
                   let type_declarations = List.map (fun t -> let fk_arg1 = Parser.declaration_default_visibility () in
                        let fk_arg2 = Parser.declaration_default_opaque () in
                        let fk_arg3 = Parser.declaration_default_annotations () in
                        ({ Parser.at = (p : Parser.module_parameter).Parser.at; name = (t : Parser.spec_type).Parser.name; definition = (Parser.RecordDefinition { type_parameters = (t : Parser.spec_type).Parser.type_parameters; fields = []; private_constructor = false; annotation = false; external_ = None } : Parser.definition); visibility = fk_arg1; opaque = fk_arg2; annotations = fk_arg3 } : Parser.declaration)) types in
                   let value_declarations = List.map (fun v -> let fk_arg1 = Parser.declaration_default_visibility () in
                        let fk_arg2 = Parser.declaration_default_opaque () in
                        let fk_arg3 = Parser.declaration_default_annotations () in
                        ({ Parser.at = (p : Parser.module_parameter).Parser.at; name = (v : Parser.spec_value).Parser.name; definition = (Parser.FunctionDefinition { type_parameters = (v : Parser.spec_value).Parser.type_parameters; receiver = None; parameters = (v : Parser.spec_value).Parser.parameters; result = None; body = (Parser.BooleanConstant { at = (p : Parser.module_parameter).Parser.at; value = true } : Parser.expression); external_ = None; operator = false } : Parser.definition); visibility = fk_arg1; opaque = fk_arg2; annotations = fk_arg3 } : Parser.declaration)) values in
                   let module_declaration = let fk_arg1 = Parser.declaration_default_visibility () in
                     let fk_arg2 = Parser.declaration_default_opaque () in
                     let fk_arg3 = Parser.declaration_default_annotations () in
                     ({ Parser.at = (p : Parser.module_parameter).Parser.at; name = (p : Parser.module_parameter).Parser.name; definition = (Parser.ModuleDefinition { declarations = type_declarations @ value_declarations; spec = Some (p : Parser.module_parameter).Parser.spec; parameters = []; application = None; type_parameters = [] } : Parser.definition); visibility = fk_arg1; opaque = fk_arg2; annotations = fk_arg3 } : Parser.declaration) in
                   let inside = List.map (fun d -> ({ Symbols.name = name ^ "." ^ (d : Parser.declaration).Parser.name; path = Symbols.Symbols.path_of (name ^ "." ^ (d : Parser.declaration).Parser.name); declaration = d; file = (f : Symbols.symbol).Symbols.file } : Symbols.symbol)) (type_declarations @ value_declarations) in
                   building.declarations <- ((building : building).declarations @ [({ Symbols.name = name; path = Symbols.Symbols.path_of name; declaration = module_declaration; file = (f : Symbols.symbol).Symbols.file } : Symbols.symbol)]) @ inside;
                   building.parameter_modules <- (building : building).parameter_modules @ [name];
                   building.parameter_members <- (building : building).parameter_members @ List.map (fun it -> name ^ "." ^ (it : Parser.declaration).Parser.name) value_declarations;
                   building.parameter_specs <- Collections.Maps.map_put (building : building).parameter_specs name spec;
                   ((p : Parser.module_parameter).Parser.name, spec)) parameters in
              building.parameters <- Collections.Maps.map_put (building : building).parameters (f : Symbols.symbol).Symbols.name found
          | _ -> ()

        let is_application (s : Symbols.symbol) : bool =
          match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _; application = Some _; type_parameters = _ } -> true
          | _ -> false

        let module_at (building : building) (name : string) (at : Parser.position) (place : Resolution.place) (at_ : Symbols.symbol) : Symbols.symbol =
          match Resolution.Lookups.module_named name place { ((building : building).namespace : Resolution.namespace) with Resolution.table = Symbols.Symbols.rebuilt ((building : building).namespace : Resolution.namespace).Resolution.table (building : building).declarations } (Resolution.Refusing : Resolution.strictness) with
          | Resolution.Found { value = Symbols.DeclaredModule { symbol = m } } -> m
          | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem at_ at why)) with
               | _ -> (assert false))
          | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (problem at_ at ("unknown module '" ^ name ^ "'"))) with
              | _ -> (assert false)

        let argument_module (building : building) (ref : Parser.type_ref) (place : Resolution.place) (from : Symbols.symbol) : Symbols.symbol =
          match ref with
          | Parser.NamedType { at = at; name = name; arguments = _ } -> (let m = module_at building name at place from in
               let own = Symbols.Symbols.simple_name m in
               match ((m : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
               | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _ :: _; application = _; type_parameters = _ } -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem from at (own ^ " is a functor; give it modules first"))) with
                    | _ -> (assert false))
               | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _; application = _; type_parameters = _ :: _ } -> (let type_parameters = match ((m : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
                      | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _; application = _; type_parameters = ts } -> ts
                      | _ -> [] in
                    match Effect.perform (Diagnostics.Abandoning_abandon (problem from at (own ^ " takes type parameters, " ^ String.concat ", " (List.map Fun.id type_parameters) ^ ", so it can't be given to a functor yet"))) with
                    | _ -> (assert false))
               | _ -> m)
          | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (let fk_arg1 = Symbols.Positions.of_type ref in
                let fk_arg2 = "a functor takes its modules in parentheses: " ^ Symbols.Symbols.simple_name from ^ "(Module)" in
                problem from fk_arg1 fk_arg2)) with
              | _ -> (assert false)

        let copies_of (functor_ : Symbols.symbol) (made : string) (building : building) : Symbols.symbol list =
          let in_functor = List.filter (fun d -> String.starts_with ~prefix:((functor_ : Symbols.symbol).Symbols.name ^ ".") (d : Symbols.symbol).Symbols.name && not (List.exists (fun p -> (d : Symbols.symbol).Symbols.name = p || String.starts_with ~prefix:(p ^ ".") (d : Symbols.symbol).Symbols.name) (building : building).parameter_modules)) (building : building).declarations in
          let copies = List.map (fun d -> let name = made ^ (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in String.sub s i (String.length s - i)) (d : Symbols.symbol).Symbols.name ((fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) (functor_ : Symbols.symbol).Symbols.name) in
               ({ Symbols.name = name; path = Symbols.Symbols.path_of name; declaration = (d : Symbols.symbol).Symbols.declaration; file = (d : Symbols.symbol).Symbols.file } : Symbols.symbol)) in_functor in
          building.copy_origins <- List.fold_left (fun m entry -> let (original, copy) = entry in
             Collections.Maps.map_put m (copy : Symbols.symbol).Symbols.name (original : Symbols.symbol).Symbols.name) (building : building).copy_origins (List.filter (fun (original, _) -> Symbols.Symbols.is_type original || Symbols.Symbols.is_annotation original) (Lang.Lists.list_zip in_functor copies));
          copies

        let apply (building : building) (app : Symbols.symbol) : unit =
          match ((app : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.ModuleDefinition { declarations = _; spec = spec; parameters = _; application = Some ({ Parser.functor_ = functor_ref; arguments = arguments } : Parser.application); type_parameters = type_parameters } -> Option.iter (fun outer -> match Effect.perform (Diagnostics.Abandoning_abandon (problem app ((app : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at ("a functor can't be applied inside another functor (" ^ Symbols.Symbols.simple_name outer ^ ") yet"))) with
                 | _ -> (assert false)) (enclosing_functor building (app : Symbols.symbol).Symbols.path);
              let place = ({ Resolution.file = (app : Symbols.symbol).Symbols.file; path = (app : Symbols.symbol).Symbols.path } : Resolution.place) in
              let (functor_at, functor_name) = match functor_ref with
                | Parser.NamedType { at = at; name = n; arguments = _ } -> (at, n)
                | _ -> (Symbols.Positions.of_type functor_ref, "") in
              let functor_ = module_at building functor_name functor_at place app in
              let own = Symbols.Symbols.simple_name functor_ in
              let parameters = match ((functor_ : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
                | Parser.ModuleDefinition { declarations = _; spec = _; parameters = ps; application = _; type_parameters = _ } -> ps
                | _ -> [] in
              if List.is_empty parameters then (match Effect.perform (Diagnostics.Abandoning_abandon (problem app functor_at (own ^ " isn't a functor: it takes no modules"))) with
                 | _ -> (assert false)) else ();
              let positional = Lang.Lists.list_take_while arguments (fun it -> Option.is_none (it : Parser.module_argument).Parser.name) in
              if let fk_arg1 = List.length positional in
              let fk_arg2 = List.length parameters in
              fk_arg1 > fk_arg2 then (match Effect.perform (Diagnostics.Abandoning_abandon (problem app functor_at (let fk_arg1 = string_of_int (List.length parameters) in
                    let fk_arg2 = if List.length parameters = 1 then "" else "s" in
                    let fk_arg3 = string_of_int (List.length positional) in
                    own ^ " takes " ^ fk_arg1 ^ " module" ^ fk_arg2 ^ ", not " ^ fk_arg3))) with
                 | _ -> (assert false)) else ();
              let named = List.drop (List.length positional) arguments in
              List.iter (fun a -> let argument_name = Option.value (a : Parser.module_argument).Parser.name ~default:"" in
                 let at = Symbols.Positions.of_type (a : Parser.module_argument).Parser.value in
                 let index = Lang.Lists.list_index_of_first parameters (fun it -> (it : Parser.module_parameter).Parser.name = argument_name) in
                 if Option.is_none (a : Parser.module_argument).Parser.name then (match Effect.perform (Diagnostics.Abandoning_abandon (problem app at "a module given by position goes before those given by name")) with
                    | _ -> (assert false)) else if index < 0 then (match Effect.perform (Diagnostics.Abandoning_abandon (problem app at (own ^ " has no module " ^ argument_name ^ ": it takes " ^ String.concat ", " (List.map Fun.id (List.map (fun it -> (it : Parser.module_parameter).Parser.name) parameters))))) with
                      | _ -> (assert false)) else if index < List.length positional || Lang.Lists.list_count named (fun it -> (it : Parser.module_argument).Parser.name = (a : Parser.module_argument).Parser.name) > 1 then (match Effect.perform (Diagnostics.Abandoning_abandon (problem app at (own ^ "'s " ^ argument_name ^ " is given twice"))) with
                        | _ -> (assert false)) else ()) named;
              let given = List.mapi (fun i p -> let written = Lang.Options.option_or_else (Option.map (fun it -> (it : Parser.module_argument).Parser.value) (Lang.Lists.list_get_or_none positional i)) (fun () -> Option.map (fun it -> (it : Parser.module_argument).Parser.value) (List.find_opt (fun it -> (it : Parser.module_argument).Parser.name = Some (p : Parser.module_parameter).Parser.name) named)) in
                   match written with
                   | Some ref -> argument_module building ref place app
                   | None -> match (p : Parser.module_parameter).Parser.default with
                       | Some ref -> let m = argument_module building ref ({ Resolution.file = (functor_ : Symbols.symbol).Symbols.file; path = (functor_ : Symbols.symbol).Symbols.path } : Resolution.place) functor_ in
                           if List.mem (m : Symbols.symbol).Symbols.name (building : building).parameter_modules then (match Effect.perform (Diagnostics.Abandoning_abandon (problem functor_ (Symbols.Positions.of_type ref) (own ^ "'s " ^ (p : Parser.module_parameter).Parser.name ^ " can't default to another of its modules"))) with
                              | _ -> (assert false)) else m
                       | None -> let spec_name = match (p : Parser.module_parameter).Parser.spec with
                             | Parser.NamedType { at = _; name = n; arguments = _ } -> n
                             | _ -> "" in
                           match Effect.perform (Diagnostics.Abandoning_abandon (problem app functor_at (own ^ " needs a module for " ^ (p : Parser.module_parameter).Parser.name ^ ", which follows " ^ spec_name))) with
                           | _ -> (assert false)) parameters in
              let copies = copies_of functor_ (app : Symbols.symbol).Symbols.name building in
              let made_module = ({ Symbols.name = (app : Symbols.symbol).Symbols.name; path = (app : Symbols.symbol).Symbols.path; declaration = ({ Parser.at = ((app : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; name = ((app : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.name; definition = (Parser.ModuleDefinition { declarations = List.map (fun it -> (it : Symbols.symbol).Symbols.declaration) (List.filter (fun c -> (c : Symbols.symbol).Symbols.path = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) (app : Symbols.symbol).Symbols.name ".") copies); spec = spec; parameters = []; application = Some ({ Parser.functor_ = functor_ref; arguments = arguments } : Parser.application); type_parameters = type_parameters } : Parser.definition); visibility = ((app : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.visibility; opaque = ((app : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.opaque; annotations = ((app : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations } : Parser.declaration); file = (app : Symbols.symbol).Symbols.file } : Symbols.symbol) in
              building.declarations <- List.map (fun d -> if (d : Symbols.symbol).Symbols.name = (app : Symbols.symbol).Symbols.name then made_module else d) (building : building).declarations @ copies;
              building.aliases <- List.fold_left (fun m entry -> let (p, given_module) = entry in
                 Collections.Maps.map_put m ((app : Symbols.symbol).Symbols.name ^ "." ^ (p : Parser.module_parameter).Parser.name) (given_module : Symbols.symbol).Symbols.name) (building : building).aliases (Lang.Lists.list_zip parameters given);
              building.applications <- Collections.Maps.map_put (building : building).applications (app : Symbols.symbol).Symbols.name ({ Resolution.functor_ = functor_; arguments = given } : Resolution.made)
          | _ -> ()

        let enclosing_application (building : building) (path : string list) : string option =
          List.find_opt (fun it -> Collections.Maps.map_contains_key (building : building).applications it) (List.mapi (fun i _ -> String.concat "." (List.map Fun.id (List.take (i + 1) path))) path)

        let lift_applications (building : building) (d : Symbols.symbol) : unit =
          let place = ({ Resolution.file = (d : Symbols.symbol).Symbols.file; path = (d : Symbols.symbol).Symbols.path } : Resolution.place) in
          let bodies = let fk_arg1 = Option.to_list (Symbols.Signatures.body_of d) in
            let fk_arg2 = Lang.Lists.list_map_not_null (Option.value (Symbols.Signatures.written_parameters_of d) ~default:[]) (fun it -> (it : Parser.parameter).Parser.default) in
            fk_arg1 @ fk_arg2 in
          List.iter (fun call -> let functor_ = Option.bind (Symbols.References.dotted (call : Symbols.call_in).Symbols.callee) (fun name -> match Resolution.Lookups.module_named name place (building : building).namespace (Resolution.Skipping : Resolution.strictness) with
                  | Resolution.Found { value = Symbols.DeclaredModule { symbol = m } } when is_functor m -> Some (name, m)
                  | _ -> None) in
             Option.iter (fun entry -> let (name, m) = entry in
                if Option.is_some (enclosing_functor building (d : Symbols.symbol).Symbols.path) then (match Effect.perform (Diagnostics.Abandoning_abandon (problem d (call : Symbols.call_in).Symbols.at "a functor can't be applied inside another functor yet")) with
                   | _ -> (assert false)) else ();
                if Option.is_none (enclosing_application building (d : Symbols.symbol).Symbols.path) then (let arguments = List.map (fun a -> let module_name = Lang.Options.option_filter (Symbols.References.dotted (a : Parser.argument).Parser.value) (fun n -> Option.is_some (Resolution.Lookups.found (Resolution.Lookups.module_named n place (building : building).namespace (Resolution.Skipping : Resolution.strictness)))) in
                        match module_name with
                        | Some n -> ({ Parser.name = (a : Parser.argument).Parser.name; value = (Parser.NamedType { at = Symbols.Positions.of_ (a : Parser.argument).Parser.value; name = n; arguments = [] } : Parser.type_ref) } : Parser.module_argument)
                        | None -> match Effect.perform (Diagnostics.Abandoning_abandon (let fk_arg1 = Symbols.Positions.of_ (a : Parser.argument).Parser.value in
                              let fk_arg2 = Symbols.Symbols.simple_name m ^ " takes modules, by name" in
                              problem d fk_arg1 fk_arg2)) with
                            | _ -> (assert false)) (call : Symbols.call_in).Symbols.arguments in
                   building.lifted_count <- (building : building).lifted_count + 1;
                   let made = String.concat "." (List.map Fun.id ((d : Symbols.symbol).Symbols.path @ [Symbols.Symbols.simple_name m ^ "__" ^ string_of_int (building : building).lifted_count])) in
                   let app = ({ Symbols.name = made; path = (d : Symbols.symbol).Symbols.path; declaration = (let fk_arg1 = Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) made ".")) ~default:made in
                      let fk_arg2 = (Parser.ModuleDefinition { declarations = []; spec = None; parameters = []; application = Some ({ Parser.functor_ = (Parser.NamedType { at = Symbols.Positions.of_ (call : Symbols.call_in).Symbols.callee; name = name; arguments = [] } : Parser.type_ref); arguments = arguments } : Parser.application); type_parameters = [] } : Parser.definition) in
                      let fk_arg3 = Parser.declaration_default_opaque () in
                      let fk_arg4 = Parser.declaration_default_annotations () in
                      ({ Parser.at = (call : Symbols.call_in).Symbols.at; name = fk_arg1; definition = fk_arg2; visibility = (Parser.Private : Parser.visibility); opaque = fk_arg3; annotations = fk_arg4 } : Parser.declaration)); file = (d : Symbols.symbol).Symbols.file } : Symbols.symbol) in
                   building.declarations <- (building : building).declarations @ [app];
                   apply building app;
                   building.lifted <- Collections.Maps.map_put (building : building).lifted ({ Resolution.file = (((d : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (call : Symbols.call_in).Symbols.at } : Resolution.call_site) made) else ()) functor_) (List.concat_map (fun it -> Symbols.Calls.of_ it) bodies)

        let specs_followed (declarations : Symbols.symbol list) (namespace : Resolution.namespace) (parameter_modules : string list) (applications : (string, Resolution.made) Collections.Maps.map) : (string, Symbols.symbol) Collections.Maps.map =
          let followed = let fk_arg1 = List.filter (fun it -> Symbols.Symbols.is_module it) declarations in
            let fk_arg2 = Collections.Maps.empty_map () in
            List.fold_left (fun followed declared -> match ((declared : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
               | Parser.ModuleDefinition { declarations = _; spec = Some (Parser.NamedType { at = at; name = name; arguments = arguments }); parameters = parameters; application = _; type_parameters = _ } -> (let place = ({ Resolution.file = (declared : Symbols.symbol).Symbols.file; path = (declared : Symbols.symbol).Symbols.path } : Resolution.place) in
                    let problem = fun message -> ({ Diagnostics.file = (((declared : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = message } : Diagnostics.diagnostic) in
                    match Resolution.Lookups.spec name place namespace (Resolution.Refusing : Resolution.strictness) with
                    | Resolution.Found { value = spec } -> let own = Symbols.Symbols.simple_name declared in
                        let spec_name = Symbols.Symbols.simple_name spec in
                        (match arguments with
                         | first :: _ when not (List.mem (declared : Symbols.symbol).Symbols.name parameter_modules) -> (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((declared : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = Symbols.Positions.of_type first; message = own ^ " says what its types are in its body, so write just : " ^ spec_name ^ "; type arguments are for a functor's parameters, like F(M: " ^ spec_name ^ "<...>)" } : Diagnostics.diagnostic)) with
                              | _ -> (assert false))
                         | _ -> ());
                        (match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
                         | Parser.SpecDefinition { types = _; values = _; type_parameters = _ :: _; copy_of = _; parents = _ } -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem (own ^ " can't follow " ^ spec_name ^ ", which takes type parameters; handle it with a value instead: " ^ spec_name ^ "(...) { ... }"))) with
                              | _ -> (assert false))
                         | _ -> ());
                        Collections.Maps.map_put followed (declared : Symbols.symbol).Symbols.name spec
                    | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem why)) with
                         | _ -> (assert false))
                    | Resolution.NotFound -> match Effect.perform (Diagnostics.Abandoning_abandon (problem ("unknown spec '" ^ name ^ "'" ^ Resolution.ImportHints.for_name name namespace))) with
                        | _ -> (assert false))
               | _ -> followed) fk_arg2 fk_arg1 in
          List.fold_left (fun m entry -> let (made, application) = entry in
             match Collections.Maps.map_get m ((application : Resolution.made).Resolution.functor_ : Symbols.symbol).Symbols.name with
             | Some spec -> Collections.Maps.map_put m made spec
             | None -> m) followed (Collections.Maps.map_to_list applications)

        let applied (namespace : Resolution.namespace) : Resolution.namespace =
          let building = let fk_arg1 = Collections.Maps.empty_map () in
            let fk_arg2 = Collections.Maps.empty_map () in
            let fk_arg3 = Collections.Maps.empty_map () in
            let fk_arg4 = Collections.Maps.empty_map () in
            let fk_arg5 = Collections.Maps.empty_map () in
            let fk_arg6 = Collections.Maps.empty_map () in
            let fk_arg7 = Collections.Maps.empty_map () in
            ({ namespace = namespace; declarations = ((namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.declarations; parameters = fk_arg1; parameter_modules = []; parameter_members = []; parameter_specs = fk_arg2; applications = fk_arg3; aliases = fk_arg4; copy_origins = fk_arg5; fixed_types = fk_arg6; lifted = fk_arg7; lifted_count = 0 } : building) in
          List.iter (fun f -> add_parameters building f) (List.filter (fun it -> is_functor it) ((namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.declarations);
          List.iter (fun app -> apply building app) (List.filter (fun it -> is_application it) ((namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.declarations);
          List.iter (fun d -> lift_applications building d) (List.filter (fun it -> Symbols.Symbols.is_function it) ((namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.declarations);
          let table = Symbols.Symbols.rebuilt (namespace : Resolution.namespace).Resolution.table (building : building).declarations in
          let with_table = { (namespace : Resolution.namespace) with Resolution.table = table } in
          { (namespace : Resolution.namespace) with Resolution.table = table; modules = ({ Resolution.specs = specs_followed (table : Symbols.symbol_table).Symbols.declarations with_table (building : building).parameter_modules (building : building).applications; parameter_modules = (building : building).parameter_modules; parameter_members = (building : building).parameter_members; applications = (building : building).applications; aliases = (building : building).aliases; copy_origins = (building : building).copy_origins; fixed_types = (building : building).fixed_types; lifted = (building : building).lifted } : Resolution.modules) }
      end
    end

    module Annotations = struct
      type reached = { declaration : Symbols.symbol; annotation : Parser.annotation; via : Symbols.symbol list }

      let rec show_reached (v : reached) =
        "Reached(" ^ "declaration=" ^ Symbols.show_symbol v.declaration ^ ", annotation=" ^ Parser.show_annotation v.annotation ^ ", via=" ^ fk_show_list Symbols.show_symbol v.via ^ ")"

      module Annotations = struct
        let place_of (symbol : Symbols.symbol) : Resolution.place =
          ({ Resolution.file = (symbol : Symbols.symbol).Symbols.file; path = (symbol : Symbols.symbol).Symbols.path } : Resolution.place)

        let effect_ =
          "fckt.lang.Effect"

        let rec declaration_of (a : Parser.annotation) (place : Resolution.place) (namespace : Resolution.namespace) : Symbols.symbol option =
          let table = (namespace : Resolution.namespace).Resolution.table in
          let quietly = fun entries -> Resolution.Names.find (a : Parser.annotation).Parser.name entries (fun s -> Some s) (fun full -> Collections.Maps.map_contains_key entries full) place namespace (Resolution.Skipping : Resolution.strictness) in
          match quietly (table : Symbols.symbol_table).Symbols.annotation_types with
          | Resolution.Found { value = s } -> Some s
          | _ -> match quietly (table : Symbols.symbol_table).Symbols.specs with
              | Resolution.Found { value = spec } when is_effect spec namespace -> Some spec
              | _ -> None
        and is_marked (symbol : Symbols.symbol) (name : string) (namespace : Resolution.namespace) : bool =
          List.exists (fun a -> Option.map (fun it -> (it : Symbols.symbol).Symbols.name) (declaration_of a (place_of symbol) namespace) = Some name) ((symbol : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations
        and is_effect (symbol : Symbols.symbol) (namespace : Resolution.namespace) : bool =
          is_marked symbol effect_ namespace

        let meta =
          "fckt.lang.Meta"

        let rec walk (annotations : Parser.annotation list) (place : Resolution.place) (via : Symbols.symbol list) (namespace : Resolution.namespace) : reached list =
          List.concat_map (fun a -> match declaration_of a place namespace with
             | None -> []
             | Some declaration -> if List.exists (fun it -> (it : Symbols.symbol).Symbols.name = (declaration : Symbols.symbol).Symbols.name) via then (let loop = Lang.Lists.list_drop_while via (fun it -> (it : Symbols.symbol).Symbols.name <> (declaration : Symbols.symbol).Symbols.name) @ [declaration] in
                    match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((declaration : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((declaration : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = "annotations can't be annotated in a circle: " ^ String.concat " -> " (List.map Fun.id (List.map (fun it -> "@" ^ Symbols.Symbols.simple_name it) loop)) } : Diagnostics.diagnostic)) with
                    | _ -> (assert false)) else (let passed_on = List.filter (fun inner -> not (Option.value (Option.map (fun t -> is_marked t meta namespace) (declaration_of inner (place_of declaration) namespace)) ~default:false)) ((declaration : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations in
                    ({ declaration = declaration; annotation = a; via = via } : reached) :: walk passed_on (place_of declaration) (via @ [declaration]) namespace)) annotations

        let repeatable =
          "fckt.lang.Repeatable"

        let last_part (name : string) : string =
          Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".")) ~default:name

        let rec constant_text (e : Parser.expression) : string =
          match e with
          | Parser.StringTemplate { at = _; parts = parts } -> ("\"" ^ String.concat "" (List.map Fun.id (List.map (fun p -> match p with
                    | Parser.TemplateText { text = text } -> text
                    | Parser.Interpolation { expression = _ } -> "") parts))) ^ "\""
          | Parser.IntConstant { at = _; value = value } -> string_of_int value
          | Parser.FloatConstant { at = _; value = value } -> fk_show_float value
          | Parser.BooleanConstant { at = _; value = value } -> string_of_bool value
          | Parser.CharConstant { at = _; value = value } -> "'" ^ fk_show_char value ^ "'"
          | Parser.Unary { at = _; operator = _; operand = operand } -> "-" ^ constant_text operand
          | _ -> "?"

        let rec value_text (v : Parser.annotation_value) : string =
          match v with
          | Parser.Constant { expression = e } -> constant_text e
          | Parser.Reference { at = _; name = name; type_arguments = type_arguments; arguments = arguments } -> let fk_arg1 = name ^ Option.value (Option.map (fun ts -> ("<" ^ String.concat ", " (List.map Fun.id (List.map (fun it -> Diagnostics.Written.type_ref it) ts))) ^ ">") type_arguments) ~default:"" in
              let fk_arg2 = Option.value (Option.map (fun args -> ("(" ^ String.concat ", " (List.map Fun.id (List.map (fun it -> value_text (it : Parser.annotation_argument).Parser.value) args))) ^ ")") arguments) ~default:"" in
              fk_arg1 ^ fk_arg2
          | Parser.ValueList { at = _; items = items } -> ("[" ^ String.concat ", " (List.map Fun.id (List.map (fun it -> value_text it) items))) ^ "]"
          | Parser.ValueTuple { at = _; items = items } -> ("(" ^ String.concat ", " (List.map Fun.id (List.map (fun it -> value_text it) items))) ^ ")"

        let text (a : Parser.annotation) : string =
          let fk_arg1 = last_part (a : Parser.annotation).Parser.name in
          let fk_arg2 = match (a : Parser.annotation).Parser.arguments with
            | [] -> ""
            | arguments -> ("(" ^ String.concat ", " (List.map Fun.id (List.map (fun argument -> let fk_arg1 = Option.value (Option.map (fun it -> it ^ " = ") (argument : Parser.annotation_argument).Parser.name) ~default:"" in
                      let fk_arg2 = value_text (argument : Parser.annotation_argument).Parser.value in
                      fk_arg1 ^ fk_arg2) arguments))) ^ ")" in
          fk_arg1 ^ fk_arg2

        let reached (annotations : Parser.annotation list) (place : Resolution.place) (at : Parser.position) (namespace : Resolution.namespace) : reached list =
          let all = walk annotations place [] namespace in
          let direct = List.map (fun it -> ((it : reached).declaration : Symbols.symbol).Symbols.name) (List.filter (fun it -> List.is_empty (it : reached).via) all) in
          let kept = List.filter (fun r -> List.is_empty (r : reached).via || not (List.mem ((r : reached).declaration : Symbols.symbol).Symbols.name direct)) all in
          List.iter (fun declaration -> if not (is_marked declaration repeatable namespace) then (let values = Lang.Lists.list_distinct_by (List.filter (fun it -> ((it : reached).declaration : Symbols.symbol).Symbols.name = (declaration : Symbols.symbol).Symbols.name) kept) (fun it -> text (it : reached).annotation) in
                if List.length values > 1 then (let own = Symbols.Symbols.simple_name declaration in
                   let ways = List.map (fun r -> let fk_arg1 = "@" ^ text (r : reached).annotation in
                        let fk_arg2 = Option.value (Option.map (fun it -> " through " ^ Symbols.Symbols.simple_name it) (Lang.Lists.list_last_or_none (r : reached).via)) ~default:"" in
                        fk_arg1 ^ fk_arg2) values in
                   match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = "this gets @" ^ own ^ " more than once, with different values: " ^ String.concat ", and " (List.map Fun.id ways) ^ "; choose one by declaring @" ^ own ^ " here" } : Diagnostics.diagnostic)) with
                   | _ -> (assert false)) else ()) else ()) (Lang.Lists.list_distinct_by (List.map (fun it -> (it : reached).declaration) kept) (fun it -> (it : Symbols.symbol).Symbols.name));
          kept

        let effects_of (annotations : Parser.annotation list) (place : Resolution.place) (at : Parser.position) (namespace : Resolution.namespace) : string list =
          Lang.Lists.list_distinct (List.map (fun it -> ((it : reached).declaration : Symbols.symbol).Symbols.name) (List.filter (fun it -> is_effect (it : reached).declaration namespace) (reached annotations place at namespace)))
      end
    end

    module Core = struct
      type constructor =
        | RecordConstructor of { record : Symbols.symbol }
        | CaseConstructor of { c : Symbols.case_symbol }
        | BuiltinCase of { name : string }

      let rec show_constructor (v : constructor) =
        match v with
        | RecordConstructor r -> "RecordConstructor(" ^ "record=" ^ Symbols.show_symbol r.record ^ ")"
        | CaseConstructor r -> "CaseConstructor(" ^ "c=" ^ Symbols.show_case_symbol r.c ^ ")"
        | BuiltinCase r -> "BuiltinCase(" ^ "name=" ^ Fun.id r.name ^ ")"

      type declared_field = { name : string; t : Types.type_; variable : bool }

      let rec show_declared_field (v : declared_field) =
        "DeclaredField(" ^ "name=" ^ Fun.id v.name ^ ", t=" ^ Types.show_type v.t ^ ", variable=" ^ string_of_bool v.variable ^ ")"

      type declared_case = { case : Symbols.case_symbol; fields : declared_field list }

      let rec show_declared_case (v : declared_case) =
        "DeclaredCase(" ^ "case=" ^ Symbols.show_case_symbol v.case ^ ", fields=" ^ fk_show_list show_declared_field v.fields ^ ")"

      type declared_operation = { name : string; type_parameters : string list; parameters : Types.type_ list option; result : Types.type_; fails_at_call : bool }

      let rec show_declared_operation (v : declared_operation) =
        "DeclaredOperation(" ^ "name=" ^ Fun.id v.name ^ ", typeParameters=" ^ fk_show_list Fun.id v.type_parameters ^ ", parameters=" ^ fk_show_option (fk_show_list Types.show_type) v.parameters ^ ", result=" ^ Types.show_type v.result ^ ", failsAtCall=" ^ string_of_bool v.fails_at_call ^ ")"

      type declared_effect = { effect_ : Symbols.symbol; type_parameters : string list; operations : declared_operation list }

      let rec show_declared_effect (v : declared_effect) =
        "DeclaredEffect(" ^ "effect=" ^ Symbols.show_symbol v.effect_ ^ ", typeParameters=" ^ fk_show_list Fun.id v.type_parameters ^ ", operations=" ^ fk_show_list show_declared_operation v.operations ^ ")"

      type declared_spec = { spec : Symbols.symbol; types : (string * string list) list; values : (string * Types.type_) list }

      let rec show_declared_spec (v : declared_spec) =
        "DeclaredSpec(" ^ "spec=" ^ Symbols.show_symbol v.spec ^ ", types=" ^ fk_show_list (fun (x0, x1) -> "(" ^ Fun.id x0 ^ ", " ^ fk_show_list Fun.id x1 ^ ")") v.types ^ ", values=" ^ fk_show_list (fun (x0, x1) -> "(" ^ Fun.id x0 ^ ", " ^ Types.show_type x1 ^ ")") v.values ^ ")"

      type literal =
        | IntLiteral of { value : int }
        | FloatLiteral of { value : float }
        | BooleanLiteral of { value : bool }
        | CharLiteral of { code : int }
        | StringLiteral of { value : string }
        | UnitLiteral

      let rec show_literal (v : literal) =
        match v with
        | IntLiteral r -> "IntLiteral(" ^ "value=" ^ string_of_int r.value ^ ")"
        | FloatLiteral r -> "FloatLiteral(" ^ "value=" ^ fk_show_float r.value ^ ")"
        | BooleanLiteral r -> "BooleanLiteral(" ^ "value=" ^ string_of_bool r.value ^ ")"
        | CharLiteral r -> "CharLiteral(" ^ "code=" ^ string_of_int r.code ^ ")"
        | StringLiteral r -> "StringLiteral(" ^ "value=" ^ Fun.id r.value ^ ")"
        | UnitLiteral -> "UnitLiteral"

      type matcher =
        | AnyMatcher
        | NameMatcher of { name : string }
        | TupleMatcher of { parts : matcher list }
        | ConstantMatcher of { literal : literal }
        | CaseMatcher of { constructor : constructor; fields : matcher list option; narrowed : string option }
        | CaseTypeMatcher of { case_type : Symbols.symbol; narrowed : string option }
        | ListMatcher of { items : matcher list; rest : matcher option }

      let rec show_matcher (v : matcher) =
        match v with
        | AnyMatcher -> "AnyMatcher"
        | NameMatcher r -> "NameMatcher(" ^ "name=" ^ Fun.id r.name ^ ")"
        | TupleMatcher r -> "TupleMatcher(" ^ "parts=" ^ fk_show_list show_matcher r.parts ^ ")"
        | ConstantMatcher r -> "ConstantMatcher(" ^ "literal=" ^ show_literal r.literal ^ ")"
        | CaseMatcher r -> "CaseMatcher(" ^ "constructor=" ^ show_constructor r.constructor ^ ", fields=" ^ fk_show_option (fk_show_list show_matcher) r.fields ^ ", narrowed=" ^ fk_show_option Fun.id r.narrowed ^ ")"
        | CaseTypeMatcher r -> "CaseTypeMatcher(" ^ "caseType=" ^ Symbols.show_symbol r.case_type ^ ", narrowed=" ^ fk_show_option Fun.id r.narrowed ^ ")"
        | ListMatcher r -> "ListMatcher(" ^ "items=" ^ fk_show_list show_matcher r.items ^ ", rest=" ^ fk_show_option show_matcher r.rest ^ ")"

      type primitive =
        | IntPlus
        | IntMinus
        | IntTimes
        | IntDivide
        | IntRemainder
        | IntNegate
        | FloatPlus
        | FloatMinus
        | FloatTimes
        | FloatDivide
        | FloatRemainder
        | FloatNegate
        | Promoted
        | Concatenated
        | Appended
        | Equal
        | NotEqual
        | Less
        | LessOrEqual
        | Greater
        | GreaterOrEqual
        | And
        | Or
        | Not

      let rec show_primitive (v : primitive) =
        match v with
        | IntPlus -> "IntPlus"
        | IntMinus -> "IntMinus"
        | IntTimes -> "IntTimes"
        | IntDivide -> "IntDivide"
        | IntRemainder -> "IntRemainder"
        | IntNegate -> "IntNegate"
        | FloatPlus -> "FloatPlus"
        | FloatMinus -> "FloatMinus"
        | FloatTimes -> "FloatTimes"
        | FloatDivide -> "FloatDivide"
        | FloatRemainder -> "FloatRemainder"
        | FloatNegate -> "FloatNegate"
        | Promoted -> "Promoted"
        | Concatenated -> "Concatenated"
        | Appended -> "Appended"
        | Equal -> "Equal"
        | NotEqual -> "NotEqual"
        | Less -> "Less"
        | LessOrEqual -> "LessOrEqual"
        | Greater -> "Greater"
        | GreaterOrEqual -> "GreaterOrEqual"
        | And -> "And"
        | Or -> "Or"
        | Not -> "Not"

      type answer = { operation : string; answer : core; resumes : bool }
      and core =
        | Value of { literal : literal }
        | LocalRead of { name : string; is_var : bool }
        | GlobalRead of { function_ : Symbols.symbol }
        | ExternalRead of { function_ : Symbols.symbol }
        | Applied of { function_ : core; arguments : core list }
        | ExternalApplied of { function_ : Symbols.symbol; arguments : core list }
        | Performed of { effect_ : Symbols.symbol; operation : string; arguments : core list }
        | Operated of { primitive : primitive; operands : core list }
        | Shown of { value : core; t : Types.type_ }
        | Constructed of { constructor : constructor; fields : core list; t : Types.type_ }
        | Copied of { record : core; owner : Symbols.symbol; changes : (string * core) list }
        | FieldRead of { record : core; owner : Symbols.symbol; field : string }
        | CaseName of { value : core; cases : Symbols.case_symbol list }
        | FieldWritten of { record : core; owner : Symbols.symbol; field : string; value : core }
        | NarrowedWritten of { local : string; case_name : string; case_type : string; field : string; value : core }
        | ListMade of { items : list_item list }
        | TupleMade of { parts : core list }
        | Joined of { list : core; separator : core; element : Types.type_ }
        | Assertion of { condition : core; summary : string; facts : (string * core) list }
        | EqualityAssertion of { expected : core; actual : core; t : Types.type_; where : string; source : string }
        | Matched of { subject : core; branches : match_branch list }
        | NarrowedRead of { local : string; case_name : string; case_type : string; field : string }
        | Conditional of { condition : core; then_ : core; otherwise : core }
        | Bound of { pattern : matcher; value : core; body : core }
        | VarBound of { name : string; value : core; body : core }
        | VarWritten of { name : string; value : core }
        | FunctionBound of { name : string; parameters : matcher list; body : core; rest : core }
        | Sequenced of { first : core; then_ : core }
        | FunctionValue of { parameters : matcher list; body : core; drops_result : bool }
        | HandlerMade of { effect_ : Symbols.symbol; answers : answer list }
        | ModuleHandler of { module_ : Symbols.symbol; effect_ : Symbols.symbol }
        | Handled of { effect_ : Symbols.symbol; handler : core; block : core }
        | Widened of { value : core; t : Types.type_ }
        | ModulePacked of { module_ : Symbols.symbol; spec : Symbols.symbol }
        | ModuleMemberRead of { value : core; spec : Symbols.symbol; member : string }
        | Absurd of { call : core }
        | Pending of { what : string }
      and list_item =
        | OneItem of { value : core }
        | SpreadItems of { list : core }
      and match_branch = { patterns : matcher list; guard : core option; body : core }

      let rec show_answer (v : answer) =
        "Answer(" ^ "operation=" ^ Fun.id v.operation ^ ", answer=" ^ show_core v.answer ^ ", resumes=" ^ string_of_bool v.resumes ^ ")"
      and show_core (v : core) =
        match v with
        | Value r -> "Value(" ^ "literal=" ^ show_literal r.literal ^ ")"
        | LocalRead r -> "LocalRead(" ^ "name=" ^ Fun.id r.name ^ ", isVar=" ^ string_of_bool r.is_var ^ ")"
        | GlobalRead r -> "GlobalRead(" ^ "function=" ^ Symbols.show_symbol r.function_ ^ ")"
        | ExternalRead r -> "ExternalRead(" ^ "function=" ^ Symbols.show_symbol r.function_ ^ ")"
        | Applied r -> "Applied(" ^ "function=" ^ show_core r.function_ ^ ", arguments=" ^ fk_show_list show_core r.arguments ^ ")"
        | ExternalApplied r -> "ExternalApplied(" ^ "function=" ^ Symbols.show_symbol r.function_ ^ ", arguments=" ^ fk_show_list show_core r.arguments ^ ")"
        | Performed r -> "Performed(" ^ "effect=" ^ Symbols.show_symbol r.effect_ ^ ", operation=" ^ Fun.id r.operation ^ ", arguments=" ^ fk_show_list show_core r.arguments ^ ")"
        | Operated r -> "Operated(" ^ "primitive=" ^ show_primitive r.primitive ^ ", operands=" ^ fk_show_list show_core r.operands ^ ")"
        | Shown r -> "Shown(" ^ "value=" ^ show_core r.value ^ ", t=" ^ Types.show_type r.t ^ ")"
        | Constructed r -> "Constructed(" ^ "constructor=" ^ show_constructor r.constructor ^ ", fields=" ^ fk_show_list show_core r.fields ^ ", t=" ^ Types.show_type r.t ^ ")"
        | Copied r -> "Copied(" ^ "record=" ^ show_core r.record ^ ", owner=" ^ Symbols.show_symbol r.owner ^ ", changes=" ^ fk_show_list (fun (x0, x1) -> "(" ^ Fun.id x0 ^ ", " ^ show_core x1 ^ ")") r.changes ^ ")"
        | FieldRead r -> "FieldRead(" ^ "record=" ^ show_core r.record ^ ", owner=" ^ Symbols.show_symbol r.owner ^ ", field=" ^ Fun.id r.field ^ ")"
        | CaseName r -> "CaseName(" ^ "value=" ^ show_core r.value ^ ", cases=" ^ fk_show_list Symbols.show_case_symbol r.cases ^ ")"
        | FieldWritten r -> "FieldWritten(" ^ "record=" ^ show_core r.record ^ ", owner=" ^ Symbols.show_symbol r.owner ^ ", field=" ^ Fun.id r.field ^ ", value=" ^ show_core r.value ^ ")"
        | NarrowedWritten r -> "NarrowedWritten(" ^ "local=" ^ Fun.id r.local ^ ", caseName=" ^ Fun.id r.case_name ^ ", caseType=" ^ Fun.id r.case_type ^ ", field=" ^ Fun.id r.field ^ ", value=" ^ show_core r.value ^ ")"
        | ListMade r -> "ListMade(" ^ "items=" ^ fk_show_list show_list_item r.items ^ ")"
        | TupleMade r -> "TupleMade(" ^ "parts=" ^ fk_show_list show_core r.parts ^ ")"
        | Joined r -> "Joined(" ^ "list=" ^ show_core r.list ^ ", separator=" ^ show_core r.separator ^ ", element=" ^ Types.show_type r.element ^ ")"
        | Assertion r -> "Assertion(" ^ "condition=" ^ show_core r.condition ^ ", summary=" ^ Fun.id r.summary ^ ", facts=" ^ fk_show_list (fun (x0, x1) -> "(" ^ Fun.id x0 ^ ", " ^ show_core x1 ^ ")") r.facts ^ ")"
        | EqualityAssertion r -> "EqualityAssertion(" ^ "expected=" ^ show_core r.expected ^ ", actual=" ^ show_core r.actual ^ ", t=" ^ Types.show_type r.t ^ ", where=" ^ Fun.id r.where ^ ", source=" ^ Fun.id r.source ^ ")"
        | Matched r -> "Matched(" ^ "subject=" ^ show_core r.subject ^ ", branches=" ^ fk_show_list show_match_branch r.branches ^ ")"
        | NarrowedRead r -> "NarrowedRead(" ^ "local=" ^ Fun.id r.local ^ ", caseName=" ^ Fun.id r.case_name ^ ", caseType=" ^ Fun.id r.case_type ^ ", field=" ^ Fun.id r.field ^ ")"
        | Conditional r -> "Conditional(" ^ "condition=" ^ show_core r.condition ^ ", then=" ^ show_core r.then_ ^ ", otherwise=" ^ show_core r.otherwise ^ ")"
        | Bound r -> "Bound(" ^ "pattern=" ^ show_matcher r.pattern ^ ", value=" ^ show_core r.value ^ ", body=" ^ show_core r.body ^ ")"
        | VarBound r -> "VarBound(" ^ "name=" ^ Fun.id r.name ^ ", value=" ^ show_core r.value ^ ", body=" ^ show_core r.body ^ ")"
        | VarWritten r -> "VarWritten(" ^ "name=" ^ Fun.id r.name ^ ", value=" ^ show_core r.value ^ ")"
        | FunctionBound r -> "FunctionBound(" ^ "name=" ^ Fun.id r.name ^ ", parameters=" ^ fk_show_list show_matcher r.parameters ^ ", body=" ^ show_core r.body ^ ", rest=" ^ show_core r.rest ^ ")"
        | Sequenced r -> "Sequenced(" ^ "first=" ^ show_core r.first ^ ", then=" ^ show_core r.then_ ^ ")"
        | FunctionValue r -> "FunctionValue(" ^ "parameters=" ^ fk_show_list show_matcher r.parameters ^ ", body=" ^ show_core r.body ^ ", dropsResult=" ^ string_of_bool r.drops_result ^ ")"
        | HandlerMade r -> "HandlerMade(" ^ "effect=" ^ Symbols.show_symbol r.effect_ ^ ", answers=" ^ fk_show_list show_answer r.answers ^ ")"
        | ModuleHandler r -> "ModuleHandler(" ^ "module=" ^ Symbols.show_symbol r.module_ ^ ", effect=" ^ Symbols.show_symbol r.effect_ ^ ")"
        | Handled r -> "Handled(" ^ "effect=" ^ Symbols.show_symbol r.effect_ ^ ", handler=" ^ show_core r.handler ^ ", block=" ^ show_core r.block ^ ")"
        | Widened r -> "Widened(" ^ "value=" ^ show_core r.value ^ ", t=" ^ Types.show_type r.t ^ ")"
        | ModulePacked r -> "ModulePacked(" ^ "module=" ^ Symbols.show_symbol r.module_ ^ ", spec=" ^ Symbols.show_symbol r.spec ^ ")"
        | ModuleMemberRead r -> "ModuleMemberRead(" ^ "value=" ^ show_core r.value ^ ", spec=" ^ Symbols.show_symbol r.spec ^ ", member=" ^ Fun.id r.member ^ ")"
        | Absurd r -> "Absurd(" ^ "call=" ^ show_core r.call ^ ")"
        | Pending r -> "Pending(" ^ "what=" ^ Fun.id r.what ^ ")"
      and show_list_item (v : list_item) =
        match v with
        | OneItem r -> "OneItem(" ^ "value=" ^ show_core r.value ^ ")"
        | SpreadItems r -> "SpreadItems(" ^ "list=" ^ show_core r.list ^ ")"
      and show_match_branch (v : match_branch) =
        "MatchBranch(" ^ "patterns=" ^ fk_show_list show_matcher v.patterns ^ ", guard=" ^ fk_show_option show_core v.guard ^ ", body=" ^ show_core v.body ^ ")"

      type core_function = { parameters : string list; body : core }

      let rec show_core_function (v : core_function) =
        "CoreFunction(" ^ "parameters=" ^ fk_show_list Fun.id v.parameters ^ ", body=" ^ show_core v.body ^ ")"

      type type_declaration =
        | DeclaredRecord of { record : Symbols.symbol; type_parameters : string list; fields : declared_field list }
        | DeclaredCases of { case_type : Symbols.symbol; type_parameters : string list; cases : declared_case list }
        | DeclaredAlias of { alias : Symbols.symbol; type_parameters : string list; target : Types.type_ }
        | DeclaredExternal of { external_ : Symbols.symbol; type_parameters : string list; ocaml : string }

      let rec show_type_declaration (v : type_declaration) =
        match v with
        | DeclaredRecord r -> "DeclaredRecord(" ^ "record=" ^ Symbols.show_symbol r.record ^ ", typeParameters=" ^ fk_show_list Fun.id r.type_parameters ^ ", fields=" ^ fk_show_list show_declared_field r.fields ^ ")"
        | DeclaredCases r -> "DeclaredCases(" ^ "caseType=" ^ Symbols.show_symbol r.case_type ^ ", typeParameters=" ^ fk_show_list Fun.id r.type_parameters ^ ", cases=" ^ fk_show_list show_declared_case r.cases ^ ")"
        | DeclaredAlias r -> "DeclaredAlias(" ^ "alias=" ^ Symbols.show_symbol r.alias ^ ", typeParameters=" ^ fk_show_list Fun.id r.type_parameters ^ ", target=" ^ Types.show_type r.target ^ ")"
        | DeclaredExternal r -> "DeclaredExternal(" ^ "external=" ^ Symbols.show_symbol r.external_ ^ ", typeParameters=" ^ fk_show_list Fun.id r.type_parameters ^ ", ocaml=" ^ Fun.id r.ocaml ^ ")"

      module Cores = struct
        let rec runs (c : core) : bool =
          match c with
          | Value { literal = _ } -> false
          | LocalRead { name = _; is_var = is_var } -> is_var
          | GlobalRead { function_ = _ } -> false
          | ExternalRead { function_ = _ } -> false
          | FunctionValue { parameters = _; body = _; drops_result = _ } -> false
          | Operated { primitive = _; operands = operands } -> List.exists (fun it -> runs it) operands
          | Shown { value = value; t = _ } -> runs value
          | TupleMade { parts = parts } -> List.exists (fun it -> runs it) parts
          | ListMade { items = items } -> List.exists (fun item -> match item with
                 | OneItem { value = value } -> runs value
                 | SpreadItems { list = list } -> runs list) items
          | Conditional { condition = condition; then_ = then_; otherwise = otherwise } -> (runs condition || runs then_) || runs otherwise
          | Constructed { constructor = _; fields = fields; t = _ } -> List.exists (fun it -> runs it) fields
          | FieldRead { record = record; owner = _; field = _ } -> runs record
          | Copied { record = record; owner = _; changes = changes } -> runs record || List.exists (fun (_, c) -> runs c) changes
          | NarrowedRead { local = _; case_name = _; case_type = _; field = _ } -> false
          | Widened { value = value; t = _ } -> runs value
          | ModulePacked { module_ = _; spec = _ } -> false
          | _ -> true

        let in_written_order (arguments : core list) (order : int list) (call : core list -> core) : core =
          if order = Lang.Lists.list_sorted order || Lang.Lists.list_count arguments (fun it -> runs it) < 2 then call arguments else (let named = List.mapi (fun i a -> (a, (if runs a then Some ("fk_named" ^ string_of_int (i + 1)) else None))) arguments in
             let written = List.map (fun (entry, _) -> entry) (Lang.Lists.list_sorted_by (Lang.Lists.list_zip named order) (fun (_, at) -> at)) in
             let given = List.map (fun (a, name) -> Option.value (Option.map (fun it -> (LocalRead { name = it; is_var = false } : core)) name) ~default:a) named in
             let fk_arg1 = List.rev written in
             let fk_arg2 = call given in
             List.fold_left (fun body entry -> let (a, name) = entry in
                match name with
                | Some n -> (Bound { pattern = (NameMatcher { name = n } : matcher); value = a; body = body } : core)
                | None -> body) fk_arg2 fk_arg1)

        let rec references (c : core) : Symbols.symbol list =
          match c with
          | Value { literal = _ } -> []
          | LocalRead { name = _; is_var = _ } -> []
          | GlobalRead { function_ = f } -> [f]
          | ExternalRead { function_ = f } -> [f]
          | Applied { function_ = function_; arguments = arguments } -> let fk_arg1 = references function_ in
              let fk_arg2 = all arguments in
              fk_arg1 @ fk_arg2
          | ExternalApplied { function_ = f; arguments = arguments } -> [f] @ all arguments
          | Performed { effect_ = effect_; operation = _; arguments = arguments } -> [effect_] @ all arguments
          | Operated { primitive = _; operands = operands } -> all operands
          | Shown { value = value; t = _ } -> references value
          | Constructed { constructor = constructor; fields = fields; t = _ } -> let fk_arg1 = match constructor with
                | RecordConstructor { record = record } -> [record]
                | CaseConstructor { c = case } -> [(case : Symbols.case_symbol).Symbols.owner]
                | BuiltinCase { name = _ } -> [] in
              let fk_arg2 = all fields in
              fk_arg1 @ fk_arg2
          | FieldRead { record = record; owner = owner; field = _ } -> [owner] @ references record
          | Copied { record = record; owner = owner; changes = changes } -> let fk_arg1 = [owner] @ references record in
              let fk_arg2 = all (List.map (fun (_, c) -> c) changes) in
              fk_arg1 @ fk_arg2
          | FieldWritten { record = record; owner = owner; field = _; value = value } -> let fk_arg1 = [owner] @ references record in
              let fk_arg2 = references value in
              fk_arg1 @ fk_arg2
          | NarrowedWritten { local = _; case_name = _; case_type = _; field = _; value = value } -> references value
          | CaseName { value = value; cases = cases } -> let fk_arg1 = List.map (fun it -> (it : Symbols.case_symbol).Symbols.owner) cases in
              let fk_arg2 = references value in
              fk_arg1 @ fk_arg2
          | ListMade { items = items } -> List.concat_map (fun item -> match item with
                 | OneItem { value = value } -> references value
                 | SpreadItems { list = list } -> references list) items
          | TupleMade { parts = parts } -> all parts
          | Joined { list = list; separator = separator; element = _ } -> let fk_arg1 = references list in
              let fk_arg2 = references separator in
              fk_arg1 @ fk_arg2
          | Assertion { condition = condition; summary = _; facts = facts } -> let fk_arg1 = references condition in
              let fk_arg2 = List.concat_map (fun (_, fact) -> references fact) facts in
              fk_arg1 @ fk_arg2
          | EqualityAssertion { expected = expected; actual = actual; t = _; where = _; source = _ } -> let fk_arg1 = references expected in
              let fk_arg2 = references actual in
              fk_arg1 @ fk_arg2
          | Matched { subject = subject; branches = branches } -> let fk_arg1 = references subject in
              let fk_arg2 = List.concat_map (fun b -> let fk_arg1 = Option.value (Option.map (fun it -> references it) (b : match_branch).guard) ~default:[] in
                   let fk_arg2 = references (b : match_branch).body in
                   fk_arg1 @ fk_arg2) branches in
              fk_arg1 @ fk_arg2
          | NarrowedRead { local = _; case_name = _; case_type = _; field = _ } -> []
          | Conditional { condition = condition; then_ = then_; otherwise = otherwise } -> let fk_arg1 = let fk_arg1 = references condition in
                let fk_arg2 = references then_ in
                fk_arg1 @ fk_arg2 in
              let fk_arg2 = references otherwise in
              fk_arg1 @ fk_arg2
          | Bound { pattern = _; value = value; body = body } -> let fk_arg1 = references value in
              let fk_arg2 = references body in
              fk_arg1 @ fk_arg2
          | VarBound { name = _; value = value; body = body } -> let fk_arg1 = references value in
              let fk_arg2 = references body in
              fk_arg1 @ fk_arg2
          | VarWritten { name = _; value = value } -> references value
          | FunctionBound { name = _; parameters = _; body = body; rest = rest } -> let fk_arg1 = references body in
              let fk_arg2 = references rest in
              fk_arg1 @ fk_arg2
          | Sequenced { first = first; then_ = then_ } -> let fk_arg1 = references first in
              let fk_arg2 = references then_ in
              fk_arg1 @ fk_arg2
          | FunctionValue { parameters = _; body = body; drops_result = _ } -> references body
          | Absurd { call = call } -> references call
          | Widened { value = value; t = _ } -> references value
          | ModulePacked { module_ = module_; spec = spec } -> [module_; spec]
          | ModuleMemberRead { value = value; spec = spec; member = _ } -> [spec] @ references value
          | HandlerMade { effect_ = effect_; answers = answers } -> [effect_] @ all (List.map (fun it -> (it : answer).answer) answers)
          | ModuleHandler { module_ = module_; effect_ = effect_ } -> [module_; effect_]
          | Handled { effect_ = effect_; handler = handler; block = block } -> let fk_arg1 = [effect_] @ references handler in
              let fk_arg2 = references block in
              fk_arg1 @ fk_arg2
          | Pending { what = _ } -> []
        and all (cores : core list) : Symbols.symbol list =
          List.concat_map (fun it -> references it) cores
      end
    end

    let checked_program_default_types () : Core.type_declaration list =
      []

    let checked_program_default_effects () : Core.declared_effect list =
      []

    let checked_program_default_specs () : Core.declared_spec list =
      []

    module Definitions = struct
      type case_info = { origin : Symbols.symbol; definition : Parser.case_definition; source : case_source }
      and case_source =
        | OwnCase
        | NamedCase of { from : case_info }
        | IncludedCase of { included : Symbols.symbol; arguments : Parser.type_ref list; written_at : Resolution.place; from : case_info }

      let rec show_case_info (v : case_info) =
        "CaseInfo(" ^ "origin=" ^ Symbols.show_symbol v.origin ^ ", definition=" ^ Parser.show_case_definition v.definition ^ ", source=" ^ show_case_source v.source ^ ")"
      and show_case_source (v : case_source) =
        match v with
        | OwnCase -> "OwnCase"
        | NamedCase r -> "NamedCase(" ^ "from=" ^ show_case_info r.from ^ ")"
        | IncludedCase r -> "IncludedCase(" ^ "included=" ^ Symbols.show_symbol r.included ^ ", arguments=" ^ fk_show_list Parser.show_type_ref r.arguments ^ ", writtenAt=" ^ Resolution.show_place r.written_at ^ ", from=" ^ show_case_info r.from ^ ")"

      type definitions = { namespace : Resolution.namespace; cases : (string, case_info list) Collections.Maps.map; regioned : string list }

      let rec show_definitions (v : definitions) =
        "Definitions(" ^ "namespace=" ^ Resolution.show_namespace v.namespace ^ ", cases=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id (fk_show_list show_case_info)) v.cases ^ ", regioned=" ^ fk_show_list Fun.id v.regioned ^ ")"

      type meta_type =
        | MetaValue of { t : Types.type_ }
        | MetaTypeReference
        | MetaSpec
        | MetaFunction
        | MetaModule of { spec : Symbols.symbol option }
        | MetaCase of { case_type : Types.type_ }
        | MetaField of { record : Types.type_; field_type : Types.type_ option }
        | MetaAnnotation of { annotation : Symbols.symbol }
        | MetaList of { item : meta_type }
        | MetaTuple of { items : meta_type list }

      let rec show_meta_type (v : meta_type) =
        match v with
        | MetaValue r -> "MetaValue(" ^ "t=" ^ Types.show_type r.t ^ ")"
        | MetaTypeReference -> "MetaTypeReference"
        | MetaSpec -> "MetaSpec"
        | MetaFunction -> "MetaFunction"
        | MetaModule r -> "MetaModule(" ^ "spec=" ^ fk_show_option Symbols.show_symbol r.spec ^ ")"
        | MetaCase r -> "MetaCase(" ^ "caseType=" ^ Types.show_type r.case_type ^ ")"
        | MetaField r -> "MetaField(" ^ "record=" ^ Types.show_type r.record ^ ", fieldType=" ^ fk_show_option Types.show_type r.field_type ^ ")"
        | MetaAnnotation r -> "MetaAnnotation(" ^ "annotation=" ^ Symbols.show_symbol r.annotation ^ ")"
        | MetaList r -> "MetaList(" ^ "item=" ^ show_meta_type r.item ^ ")"
        | MetaTuple r -> "MetaTuple(" ^ "items=" ^ fk_show_list show_meta_type r.items ^ ")"

      type type_context = { place : Resolution.place; type_parameters : (string, Types.type_) Collections.Maps.map; region : Types.type_ option; arrow_effects : Types.row option; expanding : string list; spec_types : (string, int) Collections.Maps.map; outside_view : bool; seen_from : Resolution.place option; value_parameters : (string, Types.type_) Collections.Maps.map; later_parameters : string list }

      let rec show_type_context (v : type_context) =
        "TypeContext(" ^ "place=" ^ Resolution.show_place v.place ^ ", typeParameters=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Types.show_type) v.type_parameters ^ ", region=" ^ fk_show_option Types.show_type v.region ^ ", arrowEffects=" ^ fk_show_option Types.show_row v.arrow_effects ^ ", expanding=" ^ fk_show_list Fun.id v.expanding ^ ", specTypes=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id string_of_int) v.spec_types ^ ", outsideView=" ^ string_of_bool v.outside_view ^ ", seenFrom=" ^ fk_show_option Resolution.show_place v.seen_from ^ ", valueParameters=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Types.show_type) v.value_parameters ^ ", laterParameters=" ^ fk_show_list Fun.id v.later_parameters ^ ")"

      module Cases = struct
        type computing = { namespace : Resolution.namespace; mutable done_ : (string, case_info list) Collections.Maps.map }

        let rec show_computing (v : computing) =
          "Computing(" ^ "namespace=" ^ Resolution.show_namespace v.namespace ^ ", done=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id (fk_show_list show_case_info)) v.done_ ^ ")"

        let problem (symbol : Symbols.symbol) (position : Parser.position) (message : string) : Diagnostics.diagnostic =
          ({ Diagnostics.file = (((symbol : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = position; message = message } : Diagnostics.diagnostic)

        let type_parameters_of (symbol : Symbols.symbol) : string list =
          match ((symbol : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.CasesDefinition { type_parameters = type_parameters; cases = _; case_refs = _; includes = _ } -> type_parameters
          | _ -> []

        let same (a : case_info) (b : case_info) : bool =
          ((a : case_info).origin : Symbols.symbol).Symbols.name = ((b : case_info).origin : Symbols.symbol).Symbols.name && ((a : case_info).definition : Parser.case_definition).Parser.name = ((b : case_info).definition : Parser.case_definition).Parser.name

        let rec substituted (t : Parser.type_ref) (substitution : (string, Parser.type_ref) Collections.Maps.map) : Parser.type_ref =
          match t with
          | Parser.NamedType { at = at; name = name; arguments = [] } when Collections.Maps.map_contains_key substitution name -> Collections.Maps.map_get_or_default substitution name t
          | Parser.NamedType { at = at; name = name; arguments = arguments } -> (Parser.NamedType { at = at; name = name; arguments = List.map (fun it -> substituted it substitution) arguments } : Parser.type_ref)
          | Parser.FunctionType { at = at; parameters = parameters; result = result; effects = effects } -> let fk_arg1 = List.map (fun it -> substituted it substitution) parameters in
              let fk_arg2 = substituted result substitution in
              (Parser.FunctionType { at = at; parameters = fk_arg1; result = fk_arg2; effects = effects } : Parser.type_ref)
          | Parser.TupleType { at = at; elements = elements } -> (Parser.TupleType { at = at; elements = List.map (fun it -> substituted it substitution) elements } : Parser.type_ref)
          | Parser.EffectsType { at = _; effects = _ } -> t
          | Parser.GivenType { at = at; name = name; given = given } -> (Parser.GivenType { at = at; name = name; given = substituted given substitution } : Parser.type_ref)

        let rec written_fields (c : case_info) : Parser.type_ref list =
          match (c : case_info).source with
          | OwnCase -> List.map (fun it -> (it : Parser.field).Parser.field_type) ((c : case_info).definition : Parser.case_definition).Parser.fields
          | NamedCase { from = from } -> written_fields from
          | IncludedCase { included = included; arguments = arguments; written_at = _; from = from } -> let substitution = Collections.Maps.list_tuple_to_map (Lang.Lists.list_zip (type_parameters_of included) arguments) in
              List.map (fun it -> substituted it substitution) (written_fields from)

        let added (symbol : Symbols.symbol) (cases : case_info list) (c : case_info) (at : Parser.position) : case_info list =
          match List.find_opt (fun it -> same it c) cases with
          | None -> cases @ [c]
          | Some existing -> if let fk_arg1 = List.map (fun it -> Diagnostics.Written.type_ref it) (written_fields existing) in
              let fk_arg2 = List.map (fun it -> Diagnostics.Written.type_ref it) (written_fields c) in
              fk_arg1 = fk_arg2 then cases else (match Effect.perform (Diagnostics.Abandoning_abandon (problem symbol at ("'" ^ (symbol : Symbols.symbol).Symbols.name ^ "' takes " ^ ((c : case_info).origin : Symbols.symbol).Symbols.name ^ "." ^ ((c : case_info).definition : Parser.case_definition).Parser.name ^ " twice, with different types"))) with
                 | _ -> (assert false))

        let rec cases_of (computing : computing) (symbol : Symbols.symbol) (visiting : string list) : case_info list =
          match Collections.Maps.map_get (computing : computing).done_ (symbol : Symbols.symbol).Symbols.name with
          | Some cases -> cases
          | None -> if List.mem (symbol : Symbols.symbol).Symbols.name visiting then (match Effect.perform (Diagnostics.Abandoning_abandon (problem symbol ((symbol : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at ("type '" ^ Symbols.Symbols.simple_name symbol ^ "' includes itself"))) with
                 | _ -> (assert false)) else ();
              let place = ({ Resolution.file = (symbol : Symbols.symbol).Symbols.file; path = (symbol : Symbols.symbol).Symbols.path } : Resolution.place) in
              let inner = visiting @ [(symbol : Symbols.symbol).Symbols.name] in
              let found = match ((symbol : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
                | Parser.CasesDefinition { type_parameters = _; cases = cases; case_refs = case_refs; includes = includes } -> let own = List.map (fun c -> (({ origin = symbol; definition = c; source = (OwnCase : case_source) } : case_info), (c : Parser.case_definition).Parser.at)) cases in
                    let named = List.map (fun ref -> (named_case computing symbol ref place inner, (ref : Parser.case_ref).Parser.at)) case_refs in
                    let included = List.concat_map (fun include_ -> included_cases computing symbol include_ place inner) includes in
                    List.fold_left (fun result entry -> let (c, at) = entry in
                       added symbol result c at) [] ((own @ named) @ included)
                | _ -> [] in
              computing.done_ <- Collections.Maps.map_put (computing : computing).done_ (symbol : Symbols.symbol).Symbols.name found;
              found
        and named_case (computing : computing) (symbol : Symbols.symbol) (ref : Parser.case_ref) (place : Resolution.place) (visiting : string list) : case_info =
          match Resolution.Lookups.case_type (ref : Parser.case_ref).Parser.owner place (computing : computing).namespace (Resolution.Refusing : Resolution.strictness) with
          | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem symbol (ref : Parser.case_ref).Parser.at why)) with
               | _ -> (assert false))
          | Resolution.NotFound -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem symbol (ref : Parser.case_ref).Parser.at ("unknown type '" ^ (ref : Parser.case_ref).Parser.owner ^ "'"))) with
               | _ -> (assert false))
          | Resolution.Found { value = owner } -> let own = Symbols.Symbols.simple_name owner in
              if Lang.Lists.list_is_not_empty (type_parameters_of owner) then (match Effect.perform (Diagnostics.Abandoning_abandon (problem symbol (ref : Parser.case_ref).Parser.at ("can't take single cases from the generic type " ^ own ^ "; include it whole with *" ^ own ^ "<...>"))) with
                 | _ -> (assert false)) else ();
              match List.filter (fun it -> ((it : case_info).definition : Parser.case_definition).Parser.name = (ref : Parser.case_ref).Parser.case_name) (cases_of computing owner visiting) with
              | [c] -> ({ origin = (c : case_info).origin; definition = (c : case_info).definition; source = (NamedCase { from = c } : case_source) } : case_info)
              | [] -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem symbol (ref : Parser.case_ref).Parser.at (own ^ " has no case '" ^ (ref : Parser.case_ref).Parser.case_name ^ "'"))) with
                   | _ -> (assert false))
              | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (problem symbol (ref : Parser.case_ref).Parser.at (own ^ " has several cases named '" ^ (ref : Parser.case_ref).Parser.case_name ^ "'"))) with
                  | _ -> (assert false)
        and included_cases (computing : computing) (symbol : Symbols.symbol) (include_ : Parser.type_ref) (place : Resolution.place) (visiting : string list) : (case_info * Parser.position) list =
          match include_ with
          | Parser.NamedType { at = at; name = name; arguments = arguments } -> (match Resolution.Lookups.case_type name place (computing : computing).namespace (Resolution.Refusing : Resolution.strictness) with
               | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem symbol at why)) with
                    | _ -> (assert false))
               | Resolution.NotFound -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem symbol at ("'*' takes a type with cases, and '" ^ name ^ "' isn't one"))) with
                    | _ -> (assert false))
               | Resolution.Found { value = other } -> List.map (fun c -> (({ origin = (c : case_info).origin; definition = (c : case_info).definition; source = (IncludedCase { included = other; arguments = arguments; written_at = place; from = c } : case_source) } : case_info), at)) (cases_of computing other visiting))
          | _ -> []

        let all (namespace : Resolution.namespace) : (string, case_info list) Collections.Maps.map =
          let computing = ({ namespace = namespace; done_ = Collections.Maps.empty_map () } : computing) in
          List.iter (fun (_, symbol) -> cases_of computing symbol [];
             ()) (Collections.Maps.map_to_list ((namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.case_types);
          (computing : computing).done_
      end

      module Regions = struct
        let fields_of (s : Symbols.symbol) : Parser.field list =
          match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.RecordDefinition { type_parameters = _; fields = fields; private_constructor = _; annotation = _; external_ = _ } -> fields
          | Parser.CasesDefinition { type_parameters = _; cases = cases; case_refs = _; includes = _ } -> List.concat_map (fun it -> (it : Parser.case_definition).Parser.fields) cases
          | _ -> []

        let rec holds (t : Parser.type_ref) (place : Resolution.place) (found : string list) (namespace : Resolution.namespace) : bool =
          match t with
          | Parser.FunctionType { at = _; parameters = _; result = _; effects = _ } -> false
          | Parser.EffectsType { at = _; effects = _ } -> false
          | Parser.TupleType { at = _; elements = elements } -> List.exists (fun it -> holds it place found namespace) elements
          | Parser.NamedType { at = _; name = name; arguments = arguments } -> List.exists (fun it -> holds it place found namespace) arguments || is_holding name place found namespace
          | Parser.GivenType { at = _; name = _; given = given } -> holds given place found namespace
        and is_holding (name : string) (place : Resolution.place) (found : string list) (namespace : Resolution.namespace) : bool =
          let declared = Lang.Options.option_or_else (Resolution.Lookups.found (Resolution.Lookups.record name place namespace (Resolution.Skipping : Resolution.strictness))) (fun () -> Resolution.Lookups.found (Resolution.Lookups.case_type name place namespace (Resolution.Skipping : Resolution.strictness))) in
          match declared with
          | Some d -> List.mem (d : Symbols.symbol).Symbols.name found
          | None -> match Option.map (fun it -> ((it : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition) (Resolution.Lookups.found (Resolution.Lookups.alias name place namespace (Resolution.Skipping : Resolution.strictness))) with
              | Some (Parser.AliasDefinition { type_parameters = _; target = target }) -> holds target place found namespace
              | _ -> false

        let rec holding (types : Symbols.symbol list) (found : string list) (namespace : Resolution.namespace) : string list =
          let more = List.filter (fun t -> not (List.mem (t : Symbols.symbol).Symbols.name found) && List.exists (fun it -> holds (it : Parser.field).Parser.field_type ({ Resolution.file = (t : Symbols.symbol).Symbols.file; path = (t : Symbols.symbol).Symbols.path } : Resolution.place) found namespace) (fields_of t)) types in
          if List.is_empty more then found else holding types (found @ List.map (fun it -> (it : Symbols.symbol).Symbols.name) more) namespace

        let regioned (namespace : Resolution.namespace) : string list =
          let table = (namespace : Resolution.namespace).Resolution.table in
          let records = List.map (fun (_, s) -> s) (Collections.Maps.map_to_list (table : Symbols.symbol_table).Symbols.records) in
          let case_types = List.map (fun (_, s) -> s) (Collections.Maps.map_to_list (table : Symbols.symbol_table).Symbols.case_types) in
          let changing = let fk_arg1 = List.filter (fun r -> match ((r : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
                 | Parser.RecordDefinition { type_parameters = _; fields = fields; private_constructor = _; annotation = _; external_ = external_ } -> Option.is_some external_ || List.exists (fun it -> (it : Parser.field).Parser.variable) fields
                 | _ -> false) records in
            let fk_arg2 = List.filter (fun s -> List.exists (fun it -> (it : Parser.field).Parser.variable) (fields_of s)) case_types in
            fk_arg1 @ fk_arg2 in
          holding (records @ case_types) (List.map (fun it -> (it : Symbols.symbol).Symbols.name) changing) namespace
      end

      let type_context_default_region () : Types.type_ option =
        None

      let type_context_default_arrow_effects () : Types.row option =
        None

      let type_context_default_expanding () : string list =
        []

      let type_context_default_spec_types () : (string, int) Collections.Maps.map =
        Collections.Maps.empty_map ()

      let type_context_default_outside_view () : bool =
        false

      let type_context_default_seen_from () : Resolution.place option =
        None

      let type_context_default_value_parameters () : (string, Types.type_) Collections.Maps.map =
        Collections.Maps.empty_map ()

      let type_context_default_later_parameters () : string list =
        []

      module Conversion = struct
        let module_type_parameters (path : string list) (definitions : definitions) : string list =
          match Collections.Maps.map_get (((definitions : definitions).namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.modules (String.concat "." (List.map Fun.id path)) with
          | Some (Symbols.DeclaredModule { symbol = ({ Symbols.name = _; path = _; declaration = ({ Parser.at = _; name = _; definition = Parser.ModuleDefinition { declarations = _; spec = _; parameters = _; application = _; type_parameters = type_parameters }; visibility = _; opaque = _; annotations = _ } : Parser.declaration); file = _ } : Symbols.symbol) }) -> type_parameters
          | _ -> []

        let problem (context : type_context) (at : Parser.position) (message : string) : Diagnostics.diagnostic =
          ({ Diagnostics.file = ((((context : type_context).place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = message } : Diagnostics.diagnostic)

        let row_of_type (t : Types.type_) : Types.row =
          match Types.Types.resolved t with
          | Types.Effects { row = row } -> Types.Types.flattened row
          | Types.Variable { variable = v } -> ({ Types.labels = []; rest = Some v } : Types.row)
          | _ -> Types.Types.pure

        let starts_lower_case (name : string) : bool =
          Option.value (Option.map (fun it -> Lang.Strings.char_is_lower_case it) (List.nth_opt ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) name) 0)) ~default:false

        let own_types_of (spec : Symbols.symbol) : Parser.spec_type list =
          match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = ts; values = _; type_parameters = _; copy_of = _; parents = _ } -> ts
          | _ -> []

        let own_type_names (spec : Symbols.symbol) : string list =
          List.map (fun it -> (it : Parser.spec_type).Parser.name) (own_types_of spec)

        let parameter_own_type (at : Parser.position) (name : string) (arguments : Parser.type_ref list) (context : type_context) (definitions : definitions) : Types.type_ option =
          let parameter = Option.value (List.nth_opt ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".") 0) ~default:name in
          let own = (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in String.sub s i (String.length s - i)) name ((fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) parameter + 1) in
          if parameter = name || not (starts_lower_case parameter) then None else if List.mem parameter (context : type_context).later_parameters then (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("'" ^ name ^ "' names " ^ parameter ^ ", which comes after it: a parameter's type can name only those before it"))) with
               | _ -> (assert false)) else Option.map (fun given -> match Types.Types.resolved given with
                 | Types.ModuleValue { spec = spec_name; arguments = own_arguments; own_types = _ } -> (match Collections.Maps.map_get (((definitions : definitions).namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.specs spec_name with
                      | Some spec -> if Lang.Lists.list_is_not_empty arguments then (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at (Symbols.Symbols.simple_name spec ^ "'s " ^ own ^ " takes no type arguments"))) with
                             | _ -> (assert false)) else ();
                          let names = own_type_names spec in
                          if not (List.mem own names) then (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at (Symbols.Symbols.simple_name spec ^ " has no type '" ^ own ^ "'"))) with
                             | _ -> (assert false)) else Option.value (Lang.Lists.list_get_or_none own_arguments (Lang.Lists.list_index_of names own)) ~default:given
                      | None -> match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("'" ^ parameter ^ "' isn't a value of a spec with types of its own, so it has no " ^ own))) with
                          | _ -> (assert false))
                 | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("'" ^ parameter ^ "' isn't a value of a spec with types of its own, so it has no " ^ own))) with
                     | _ -> (assert false)) (Collections.Maps.map_get (context : type_context).value_parameters parameter)

        let scope_of (context : type_context) : Resolution.type_scope =
          let fk_arg1 = List.map (fun (name, _) -> name) (Collections.Maps.map_to_list (context : type_context).type_parameters) in
          let fk_arg2 = Resolution.type_scope_default_parameters () in
          ({ Resolution.place = (context : type_context).place; type_parameters = fk_arg1; spec_types = []; parameters = fk_arg2 } : Resolution.type_scope)

        let spec_named (name : string) (context : type_context) (definitions : definitions) : Symbols.symbol option =
          if (Collections.Maps.map_contains_key (context : type_context).type_parameters name || Collections.Maps.map_contains_key (context : type_context).spec_types name) || Collections.Maps.map_contains_key Types.Types.builtins name then None else (match Resolution.TypeNames.meaning name (scope_of context) (definitions : definitions).namespace with
             | Resolution.Found { value = Resolution.SpecModuleType { spec = spec } } -> Some spec
             | _ -> None)

        let is_given (t : Parser.type_ref) : bool =
          match t with
          | Parser.GivenType { at = _; name = _; given = _ } -> true
          | _ -> false

        let module_type (spec : Symbols.symbol) (at : Parser.position) (arguments : Types.type_ list) (context : type_context) (definitions : definitions) : Types.type_ =
          let own = Symbols.Symbols.simple_name spec in
          let (types, type_parameters) = match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
            | Parser.SpecDefinition { types = ts; values = _; type_parameters = ps; copy_of = _; parents = _ } -> (ts, ps)
            | _ -> ([], []) in
          if Annotations.Annotations.is_effect spec (definitions : definitions).namespace then (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("'" ^ own ^ "' is an effect: a function does it, written @" ^ own ^ ", and a handler answers it; no value has its type"))) with
             | _ -> (assert false)) else ();
          Option.iter (fun t -> match Effect.perform (Diagnostics.Abandoning_abandon (problem context at (own ^ "'s " ^ (t : Parser.spec_type).Parser.name ^ " takes type parameters, so a value of " ^ own ^ " can't say what it is yet"))) with
             | _ -> (assert false)) (List.find_opt (fun it -> Lang.Lists.list_is_not_empty (it : Parser.spec_type).Parser.type_parameters) types);
          if Lang.Lists.list_is_not_empty type_parameters then (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at (own ^ " takes type parameters, so it can't be a value's type yet"))) with
             | _ -> (assert false)) else ();
          (Types.ModuleValue { spec = (spec : Symbols.symbol).Symbols.name; arguments = arguments; own_types = List.map (fun it -> (it : Parser.spec_type).Parser.name) types } : Types.type_)

        let unnamed (t : Parser.type_ref) : Parser.type_ref =
          match t with
          | Parser.GivenType { at = _; name = _; given = written } -> written
          | _ -> t

        let check_arity (name : string) (arity : int) (arguments : Types.type_ list) (at : Parser.position) (context : type_context) : unit =
          if List.length arguments = arity then () else (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("'" ^ name ^ "' takes " ^ string_of_int arity ^ " type argument" ^ (if arity = 1 then "" else "s") ^ ", not " ^ string_of_int (List.length arguments)))) with
             | _ -> (assert false))

        let type_parameters_of (symbol : Symbols.symbol) : string list =
          match ((symbol : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.RecordDefinition { type_parameters = type_parameters; fields = _; private_constructor = _; annotation = _; external_ = _ } -> type_parameters
          | Parser.CasesDefinition { type_parameters = type_parameters; cases = _; case_refs = _; includes = _ } -> type_parameters
          | Parser.AliasDefinition { type_parameters = type_parameters; target = _ } -> type_parameters
          | _ -> []

        let is_effects_ref (t : Parser.type_ref) : bool =
          match t with
          | Parser.EffectsType { at = _; effects = _ } -> true
          | _ -> false

        let rec interleaved (parameters : string list) (arguments : Types.type_ list) : Types.type_ list =
          match parameters with
          | [] -> []
          | p :: rest -> if String.starts_with ~prefix:"@" p then (let fk_arg1 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
                 let fk_arg2 = interleaved rest arguments in
                 fk_arg1 :: fk_arg2) else (match arguments with
                 | a :: more -> a :: interleaved rest more
                 | [] -> [])

        let with_effect_arguments (name : string) (written : Parser.type_ref list) (parameters : string list) (arguments : Types.type_ list) (context : type_context) : Types.type_ list =
          let effect_parameters = Lang.Lists.list_count parameters (fun it -> String.starts_with ~prefix:"@" it) in
          let written_effects = List.exists (fun it -> is_effects_ref it) written in
          if effect_parameters = 0 && not written_effects then arguments else if let fk_arg1 = List.length arguments in
            let fk_arg2 = List.length parameters in
            fk_arg1 = fk_arg2 then (List.iter (fun (parameter, given) -> if String.starts_with ~prefix:"@" parameter && not (is_effects_ref given) then (match Effect.perform (Diagnostics.Abandoning_abandon (let fk_arg1 = Symbols.Positions.of_type given in
                       let fk_arg2 = name ^ "'s " ^ Lang.Strings.string_remove_prefix parameter "@" ^ " is effects, like " ^ name ^ "<@Console>, not a type" in
                       problem context fk_arg1 fk_arg2)) with
                     | _ -> (assert false)) else if not (String.starts_with ~prefix:"@" parameter) && is_effects_ref given then (match Effect.perform (Diagnostics.Abandoning_abandon (problem context (Symbols.Positions.of_type given) (name ^ "'s " ^ parameter ^ " is a type, not effects"))) with
                       | _ -> (assert false)) else ()) (Lang.Lists.list_zip parameters written);
               arguments) else if (let fk_arg1 = List.length arguments in
               let fk_arg2 = List.length parameters - effect_parameters in
               fk_arg1 <> fk_arg2) || written_effects then arguments else interleaved parameters arguments

        let with_region (symbol : Symbols.symbol) (t : Types.type_) (context : type_context) (definitions : definitions) : Types.type_ =
          match t with
          | Types.Named { name = name; arguments = arguments; region = None } when List.mem (symbol : Symbols.symbol).Symbols.name (definitions : definitions).regioned -> (Types.Named { name = name; arguments = arguments; region = Some (Option.value (context : type_context).region ~default:(Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_)) } : Types.type_)
          | _ -> t

        let is_abstract (symbol : Symbols.symbol) (definitions : definitions) : bool =
          ((symbol : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.opaque || List.mem (String.concat "." (List.map Fun.id (symbol : Symbols.symbol).Symbols.path)) (((definitions : definitions).namespace : Resolution.namespace).Resolution.modules : Resolution.modules).Resolution.parameter_modules

        let is_abstract_here (symbol : Symbols.symbol) (place : Resolution.place) (definitions : definitions) : bool =
          is_abstract symbol definitions && not (Resolution.Visibility.is_inside place (symbol : Symbols.symbol).Symbols.path)

        let rec type_of (t : Parser.type_ref) (context : type_context) (definitions : definitions) : Types.type_ =
          match t with
          | Parser.FunctionType { at = _; parameters = parameters; result = result; effects = effects } -> let fk_arg1 = List.map (fun it -> type_of it context definitions) parameters in
              let fk_arg2 = type_of result context definitions in
              let fk_arg3 = if List.is_empty effects then Option.value (context : type_context).arrow_effects ~default:Types.Types.pure else row_of effects (Option.is_some (context : type_context).arrow_effects) false context definitions in
              (Types.FunctionOf { parameters = fk_arg1; result = fk_arg2; effects = fk_arg3 } : Types.type_)
          | Parser.EffectsType { at = _; effects = effects } -> (Types.Effects { row = row_of effects false true context definitions } : Types.type_)
          | Parser.TupleType { at = _; elements = elements } -> (Types.TupleOf { elements = List.map (fun it -> type_of it context definitions) elements } : Types.type_)
          | Parser.GivenType { at = at; name = name; given = _ } -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("'" ^ name ^ " = ...' gives a spec value's own type, as in Format<T = Int>"))) with
               | _ -> (assert false))
          | Parser.NamedType { at = at; name = name; arguments = arguments } -> match parameter_own_type at name arguments context definitions with
              | Some own -> own
              | None -> match spec_named name context definitions with
                  | Some spec -> spec_value_type spec at name arguments context definitions
                  | None -> if List.exists (fun it -> is_given it) arguments then (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("'" ^ name ^ "' isn't a spec, so its type arguments aren't named: " ^ Diagnostics.Written.type_ref (Parser.NamedType { at = at; name = name; arguments = List.map (fun it -> unnamed it) arguments } : Parser.type_ref)))) with
                         | _ -> (assert false)) else named_type at name arguments (List.map (fun it -> type_of it context definitions) arguments) context definitions
        and spec_value_type (spec : Symbols.symbol) (at : Parser.position) (name : string) (arguments : Parser.type_ref list) (context : type_context) (definitions : definitions) : Types.type_ =
          let own = Symbols.Symbols.simple_name spec in
          let types = own_types_of spec in
          Option.iter (fun t -> match Effect.perform (Diagnostics.Abandoning_abandon (problem context at (own ^ "'s " ^ (t : Parser.spec_type).Parser.name ^ " takes type parameters, so a value of " ^ own ^ " can't say what it is yet"))) with
             | _ -> (assert false)) (List.find_opt (fun it -> Lang.Lists.list_is_not_empty (it : Parser.spec_type).Parser.type_parameters) types);
          let positional = List.filter (fun it -> not (is_given it)) arguments in
          if List.is_empty types && Lang.Lists.list_is_not_empty arguments then (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("'" ^ name ^ "' takes 0 type arguments, not " ^ string_of_int (List.length arguments)))) with
             | _ -> (assert false)) else ();
          if Lang.Lists.list_is_not_empty positional then (let named = String.concat ", " (List.map Fun.id (List.map (fun (t, written) -> (t : Parser.spec_type).Parser.name ^ " = " ^ Diagnostics.Written.type_ref written) (Lang.Lists.list_zip types positional))) in
             match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("a " ^ own ^ " value names its own types: " ^ own ^ "<" ^ named ^ ">"))) with
             | _ -> (assert false)) else ();
          let given = Lang.Lists.list_map_not_null arguments (fun a -> match a with
               | Parser.GivenType { at = given_at; name = given_name; given = written } -> Some (given_at, given_name, written)
               | _ -> None) in
          List.iteri (fun i entry -> let (given_at, given_name, _) = entry in
             if Lang.Lists.list_none types (fun it -> (it : Parser.spec_type).Parser.name = given_name) then (match Effect.perform (Diagnostics.Abandoning_abandon (problem context given_at (own ^ " has no type '" ^ given_name ^ "'"))) with
                | _ -> (assert false)) else if List.exists (fun (_, earlier, _) -> earlier = given_name) (List.take i given) then (match Effect.perform (Diagnostics.Abandoning_abandon (problem context given_at (own ^ "'s " ^ given_name ^ " is given twice"))) with
                  | _ -> (assert false)) else ()) given;
          let own_arguments = List.map (fun t -> match List.find_opt (fun (_, given_name, _) -> given_name = (t : Parser.spec_type).Parser.name) given with
               | Some (_, _, written) -> type_of written context definitions
               | None -> (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_)) types in
          module_type spec at own_arguments context definitions
        and named_type (at : Parser.position) (name : string) (written : Parser.type_ref list) (arguments : Types.type_ list) (context : type_context) (definitions : definitions) : Types.type_ =
          match Collections.Maps.map_get (context : type_context).type_parameters name with
          | Some parameter -> check_arity name 0 arguments at context;
              parameter
          | None -> match Collections.Maps.map_get (context : type_context).spec_types name with
              | Some arity -> check_arity name arity arguments at context;
                  (Types.SpecOwnType { name = name; arguments = arguments } : Types.type_)
              | None -> builtin_or_declared at name written arguments context definitions
        and builtin_or_declared (at : Parser.position) (name : string) (written : Parser.type_ref list) (arguments : Types.type_ list) (context : type_context) (definitions : definitions) : Types.type_ =
          match Collections.Maps.map_get Types.Types.builtins name with
          | Some arity -> check_arity name arity arguments at context;
              (Types.Named { name = (if name = "Double" then "Float" else name); arguments = arguments; region = None } : Types.type_)
          | None -> match Resolution.TypeNames.meaning name (scope_of context) (definitions : definitions).namespace with
              | Resolution.Found { value = Resolution.DeclaredType { symbol = symbol } } -> let parameters = type_parameters_of symbol in
                  let given = with_effect_arguments name written parameters arguments context in
                  check_arity name (List.length parameters) given at context;
                  declared symbol given context definitions
              | Resolution.Found { value = Resolution.SpecModuleType { spec = spec } } -> spec_value_type spec at name written context definitions
              | Resolution.Found { value = _ } -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("unknown type '" ^ name ^ "'"))) with
                   | _ -> (assert false))
              | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at why)) with
                   | _ -> (assert false))
              | Resolution.NotFound -> match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("unknown type '" ^ name ^ "'"))) with
                  | _ -> (assert false)
        and declared (symbol : Symbols.symbol) (arguments : Types.type_ list) (context : type_context) (definitions : definitions) : Types.type_ =
          with_region symbol (seen_from symbol arguments context definitions) context definitions
        and seen_from (symbol : Symbols.symbol) (arguments : Types.type_ list) (context : type_context) (definitions : definitions) : Types.type_ =
          if is_abstract_here symbol (Option.value (context : type_context).seen_from ~default:(context : type_context).place) definitions || (context : type_context).outside_view && is_abstract symbol definitions then (let fk_arg1 = String.concat "." (List.map Fun.id (symbol : Symbols.symbol).Symbols.path) in
             let fk_arg2 = Symbols.Symbols.simple_name symbol in
             outside_type fk_arg1 fk_arg2 arguments context definitions) else (match ((symbol : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
             | Parser.AliasDefinition { type_parameters = _; target = _ } -> expand symbol arguments context definitions
             | _ -> (Types.Named { name = (symbol : Symbols.symbol).Symbols.name; arguments = arguments; region = None } : Types.type_))
        and outside_type (owner : string) (name : string) (arguments : Types.type_ list) (context : type_context) (definitions : definitions) : Types.type_ =
          let modules = ((definitions : definitions).namespace : Resolution.namespace).Resolution.modules in
          let table = ((definitions : definitions).namespace : Resolution.namespace).Resolution.table in
          let full = owner ^ "." ^ name in
          match Collections.Maps.map_get (modules : Resolution.modules).Resolution.fixed_types full with
          | Some fixed -> fixed_type fixed name arguments context definitions
          | None -> let declared = Lang.Options.option_filter (Lang.Options.option_or_else (Lang.Options.option_or_else (Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.records full) (fun () -> Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.case_types full)) (fun () -> Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.aliases full)) (fun _ -> not (List.mem owner (modules : Resolution.modules).Resolution.parameter_modules)) in
              match Option.map (fun d -> (d, ((d : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition)) declared with
              | Some (d, Parser.AliasDefinition { type_parameters = _; target = _ }) -> if ((d : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.opaque then (Types.Abstract { name = full; arguments = arguments } : Types.type_) else expand d arguments context definitions
              | Some (d, _) -> (Types.Named { name = (d : Symbols.symbol).Symbols.name; arguments = arguments; region = None } : Types.type_)
              | None -> (Types.Abstract { name = full; arguments = arguments } : Types.type_)
        and fixed_type (fixed : Symbols.symbol) (name : string) (arguments : Types.type_ list) (context : type_context) (definitions : definitions) : Types.type_ =
          let n = List.length (type_parameters_of fixed) in
          match Diagnostics.Diagnostics.attempting (fun () -> expand fixed arguments context definitions) with
          | Ok t -> t
          | Error d -> if n = 0 then (match Effect.perform (Diagnostics.Abandoning_abandon d) with
                 | _ -> (assert false)) else (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (d : Diagnostics.diagnostic).Diagnostics.file; at = (d : Diagnostics.diagnostic).Diagnostics.at; message = name ^ " takes " ^ string_of_int n ^ " type parameter" ^ (if n = 1 then "" else "s") ^ ", so its type argument must take " ^ string_of_int n ^ " more: " ^ (d : Diagnostics.diagnostic).Diagnostics.message } : Diagnostics.diagnostic)) with
                 | _ -> (assert false))
        and expand (alias : Symbols.symbol) (arguments : Types.type_ list) (context : type_context) (definitions : definitions) : Types.type_ =
          match ((alias : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.AliasDefinition { type_parameters = type_parameters; target = target } -> if List.mem (alias : Symbols.symbol).Symbols.name (context : type_context).expanding then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((alias : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((alias : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = "type '" ^ Symbols.Symbols.simple_name alias ^ "' is defined in terms of itself" } : Diagnostics.diagnostic)) with
                 | _ -> (assert false)) else (let in_module = Resolution.Visibility.is_inside (context : type_context).place (alias : Symbols.symbol).Symbols.path in
                 let module_parameters = List.map (fun p -> (p, (if in_module then Collections.Maps.map_get_or_else (context : type_context).type_parameters p (fun () -> (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_)) else (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_)))) (module_type_parameters (alias : Symbols.symbol).Symbols.path definitions) in
                 let inner = let fk_arg1 = Collections.Maps.list_tuple_to_map (module_parameters @ Lang.Lists.list_zip type_parameters arguments) in
                   let fk_arg2 = type_context_default_value_parameters () in
                   let fk_arg3 = type_context_default_later_parameters () in
                   ({ place = ({ Resolution.file = (alias : Symbols.symbol).Symbols.file; path = (alias : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; region = (context : type_context).region; arrow_effects = (context : type_context).arrow_effects; expanding = (context : type_context).expanding @ [(alias : Symbols.symbol).Symbols.name]; spec_types = (context : type_context).spec_types; outside_view = (context : type_context).outside_view; seen_from = (context : type_context).seen_from; value_parameters = fk_arg2; later_parameters = fk_arg3 } : type_context) in
                 type_of target inner definitions)
          | _ -> (Types.Named { name = (alias : Symbols.symbol).Symbols.name; arguments = arguments; region = None } : Types.type_)
        and row_of (annotations : Parser.annotation list) (open_ : bool) (pure : bool) (context : type_context) (definitions : definitions) : Types.row =
          let (parameters, named) = Lang.Lists.list_partition annotations (fun it -> Collections.Maps.map_contains_key (context : type_context).type_parameters ("@" ^ (it : Parser.annotation).Parser.name)) in
          (match parameters with
           | _ :: second :: _ -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem context (second : Parser.annotation).Parser.at "effects can name only one effect parameter")) with
                | _ -> (assert false))
           | _ -> ());
          let labels = List.filter (fun it -> not pure || (it : Types.effect_label).Types.name <> "fckt.lang.Pure") (labels_of named context definitions) in
          match parameters with
          | parameter :: _ -> let own = row_of_type (Collections.Maps.map_get_or_else (context : type_context).type_parameters ("@" ^ (parameter : Parser.annotation).Parser.name) (fun () -> (Types.Effects { row = Types.Types.pure } : Types.type_))) in
              ({ Types.labels = Lang.Lists.list_distinct (labels @ (own : Types.row).Types.labels); rest = (own : Types.row).Types.rest } : Types.row)
          | [] -> ({ Types.labels = labels; rest = (if open_ then Some (Effect.perform (Types.Solving_fresh ())) else None) } : Types.row)
        and labels_of (annotations : Parser.annotation list) (context : type_context) (definitions : definitions) : Types.effect_label list =
          List.concat_map (fun a -> let namespace = (definitions : definitions).namespace in
             match Annotations.Annotations.declaration_of a (context : type_context).place namespace with
             | None -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem context (a : Parser.annotation).Parser.at ("unknown effect '" ^ (a : Parser.annotation).Parser.name ^ "'" ^ Resolution.ImportHints.for_name (a : Parser.annotation).Parser.name namespace))) with
                  | _ -> (assert false))
             | Some declaration when Symbols.Symbols.is_spec declaration && Lang.Lists.list_is_not_empty (a : Parser.annotation).Parser.type_arguments -> [({ Types.name = (declaration : Symbols.symbol).Symbols.name; arguments = List.map (fun it -> type_of it context definitions) (a : Parser.annotation).Parser.type_arguments } : Types.effect_label)]
             | Some _ -> match Annotations.Annotations.effects_of [a] (context : type_context).place (a : Parser.annotation).Parser.at namespace with
                 | [] -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem context (a : Parser.annotation).Parser.at ("'" ^ (a : Parser.annotation).Parser.name ^ "' isn't an effect; declare one with effect " ^ Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) (a : Parser.annotation).Parser.name ".")) ~default:(a : Parser.annotation).Parser.name))) with
                      | _ -> (assert false))
                 | effects -> List.map (fun it -> ({ Types.name = it; arguments = [] } : Types.effect_label)) effects) annotations

        let record_fields (record : Symbols.symbol) (arguments : Types.type_ list) (region : Types.type_ option) (definitions : definitions) (seen_from : Resolution.place option) : Types.type_ list =
          match ((record : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.RecordDefinition { type_parameters = type_parameters; fields = fields; private_constructor = _; annotation = _; external_ = _ } -> let context = let fk_arg1 = Collections.Maps.list_tuple_to_map (Lang.Lists.list_zip type_parameters arguments) in
                let fk_arg2 = Collections.Maps.empty_map () in
                let fk_arg3 = type_context_default_value_parameters () in
                let fk_arg4 = type_context_default_later_parameters () in
                ({ place = ({ Resolution.file = (record : Symbols.symbol).Symbols.file; path = (record : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; region = region; arrow_effects = None; expanding = []; spec_types = fk_arg2; outside_view = false; seen_from = seen_from; value_parameters = fk_arg3; later_parameters = fk_arg4 } : type_context) in
              List.map (fun it -> type_of (it : Parser.field).Parser.field_type context definitions) fields
          | _ -> []

        let record_fields_default_seen_from () : Resolution.place option =
          None

        let is_opaque_around (path : string list) (definitions : definitions) : bool =
          List.exists (fun (_, a) -> (((a : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.opaque && Lang.Lists.list_is_not_empty (a : Symbols.symbol).Symbols.path) && List.take (List.length (a : Symbols.symbol).Symbols.path) path = (a : Symbols.symbol).Symbols.path) (Collections.Maps.map_to_list (((definitions : definitions).namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.aliases)

        let case_fields_default_seen_from () : Resolution.place option =
          None

        let rec case_fields (c : case_info) (parameters : string list) (arguments : Types.type_ list) (region : Types.type_ option) (definitions : definitions) (seen_from : Resolution.place option) : Types.type_ list =
          match (c : case_info).source with
          | OwnCase -> let context = let fk_arg1 = Collections.Maps.list_tuple_to_map (Lang.Lists.list_zip parameters arguments) in
                let fk_arg2 = Collections.Maps.empty_map () in
                let fk_arg3 = type_context_default_value_parameters () in
                let fk_arg4 = type_context_default_later_parameters () in
                ({ place = ({ Resolution.file = ((c : case_info).origin : Symbols.symbol).Symbols.file; path = ((c : case_info).origin : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; region = region; arrow_effects = None; expanding = []; spec_types = fk_arg2; outside_view = false; seen_from = seen_from; value_parameters = fk_arg3; later_parameters = fk_arg4 } : type_context) in
              List.map (fun it -> type_of (it : Parser.field).Parser.field_type context definitions) ((c : case_info).definition : Parser.case_definition).Parser.fields
          | NamedCase { from = from } -> case_fields from [] [] region definitions seen_from
          | IncludedCase { included = included; arguments = written; written_at = place; from = from } -> let context = let fk_arg1 = Collections.Maps.list_tuple_to_map (Lang.Lists.list_zip parameters arguments) in
                let fk_arg2 = Collections.Maps.empty_map () in
                let fk_arg3 = type_context_default_value_parameters () in
                let fk_arg4 = type_context_default_later_parameters () in
                ({ place = place; type_parameters = fk_arg1; region = region; arrow_effects = None; expanding = []; spec_types = fk_arg2; outside_view = false; seen_from = seen_from; value_parameters = fk_arg3; later_parameters = fk_arg4 } : type_context) in
              let fk_arg1 = Cases.type_parameters_of included in
              let fk_arg2 = List.map (fun it -> type_of it context definitions) written in
              case_fields from fk_arg1 fk_arg2 region definitions seen_from

        let cases_with_fields (case_type : Symbols.symbol) (arguments : Types.type_ list) (region : Types.type_ option) (definitions : definitions) (seen_from : Resolution.place option) : (case_info * Types.type_ list) list =
          List.map (fun c -> (c, case_fields c (Cases.type_parameters_of case_type) arguments region definitions seen_from)) (Collections.Maps.map_get_or_default (definitions : definitions).cases (case_type : Symbols.symbol).Symbols.name [])

        let cases_with_fields_default_seen_from () : Resolution.place option =
          None

        let new_region (symbol : Symbols.symbol) (definitions : definitions) : Types.type_ option =
          if List.mem (symbol : Symbols.symbol).Symbols.name (definitions : definitions).regioned then Some (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) else None
      end

      module MetaTypes = struct
        let tuple_of (items : meta_type list) : meta_type =
          let values = Lang.Lists.list_map_not_null items (fun item -> match item with
               | MetaValue { t = t } -> Some t
               | _ -> None) in
          if let fk_arg1 = List.length values in
          let fk_arg2 = List.length items in
          fk_arg1 = fk_arg2 then (MetaValue { t = (Types.TupleOf { elements = values } : Types.type_) } : meta_type) else (MetaTuple { items = items } : meta_type)

        let is_case_type (t : Types.type_) (definitions : definitions) : bool =
          match Types.Types.resolved t with
          | Types.Named { name = n; arguments = _; region = _ } -> Collections.Maps.map_contains_key (((definitions : definitions).namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.case_types n
          | _ -> false

        let rec meta_type_of (t : Parser.type_ref) (context : type_context) (definitions : definitions) : meta_type =
          match t with
          | Parser.TupleType { at = _; elements = elements } -> tuple_of (List.map (fun it -> meta_type_of it context definitions) elements)
          | Parser.NamedType { at = at; name = name; arguments = arguments } -> (let problem = fun message -> match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = ((((context : type_context).place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = message } : Diagnostics.diagnostic)) with
                   | _ -> (assert false) in
               let arity = fun n -> if List.length arguments <> n then problem ("'" ^ name ^ "' takes " ^ string_of_int n ^ " type argument" ^ (if n = 1 then "" else "s") ^ ", not " ^ string_of_int (List.length arguments)) else () in
               match name with
               | "Type" -> arity 0;
                   (MetaTypeReference : meta_type)
               | "Spec" -> arity 0;
                   (MetaSpec : meta_type)
               | "Function" -> arity 0;
                   (MetaFunction : meta_type)
               | "Module" -> if List.length arguments > 1 then arity 1 else ();
                   (MetaModule { spec = Option.map (fun argument -> match argument with
                      | Parser.NamedType { at = argument_at; name = spec_name; arguments = [] } -> (match Resolution.Lookups.spec spec_name (context : type_context).place (definitions : definitions).namespace (Resolution.Refusing : Resolution.strictness) with
                           | Resolution.Found { value = spec } -> spec
                           | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = ((((context : type_context).place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = argument_at; message = why } : Diagnostics.diagnostic)) with
                                | _ -> (assert false))
                           | Resolution.NotFound -> match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = ((((context : type_context).place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = Symbols.Positions.of_type argument; message = "Module<...> takes a spec, like Module<Ordered>" } : Diagnostics.diagnostic)) with
                               | _ -> (assert false))
                      | _ -> match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = ((((context : type_context).place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = Symbols.Positions.of_type argument; message = "Module<...> takes a spec, like Module<Ordered>" } : Diagnostics.diagnostic)) with
                          | _ -> (assert false)) (List.nth_opt arguments 0) } : meta_type)
               | "Case" -> arity 1;
                   let argument = Option.value (List.nth_opt arguments 0) ~default:t in
                   let case_type = Conversion.type_of argument context definitions in
                   if not (is_case_type case_type definitions) then (match Effect.perform (Diagnostics.Abandoning_abandon (let fk_arg1 = Symbols.Positions.of_type argument in
                        let fk_arg2 = "Case<...> takes a type with cases, not " ^ Types.TypeText.shown case_type in
                        ({ Diagnostics.file = ((((context : type_context).place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = fk_arg1; message = fk_arg2 } : Diagnostics.diagnostic))) with
                      | _ -> (assert false)) else (MetaCase { case_type = case_type } : meta_type)
               | "Field" -> arity 2;
                   let (record_ref, value_ref) = match arguments with
                     | [r; v] -> (r, v)
                     | _ -> (t, t) in
                   let record = Conversion.type_of record_ref context definitions in
                   let is_record = match Types.Types.resolved record with
                     | Types.Named { name = n; arguments = _; region = _ } -> Collections.Maps.map_contains_key (((definitions : definitions).namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.records n
                     | _ -> false in
                   if not is_record then (match Effect.perform (Diagnostics.Abandoning_abandon (let fk_arg1 = Symbols.Positions.of_type record_ref in
                        let fk_arg2 = "Field<R, T> takes a record type as R, not " ^ Types.TypeText.shown record in
                        ({ Diagnostics.file = ((((context : type_context).place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = fk_arg1; message = fk_arg2 } : Diagnostics.diagnostic))) with
                      | _ -> (assert false)) else ();
                   (MetaField { record = record; field_type = (match value_ref with
                    | Parser.NamedType { at = _; name = "_"; arguments = [] } -> None
                    | _ -> Some (Conversion.type_of value_ref context definitions)) } : meta_type)
               | "List" -> (match arguments with
                    | [item] -> (match meta_type_of item context definitions with
                         | MetaValue { t = item_type } -> (MetaValue { t = Types.Types.list_of item_type } : meta_type)
                         | meta -> (MetaList { item = meta } : meta_type))
                    | _ -> (MetaValue { t = Conversion.type_of t context definitions } : meta_type))
               | _ -> match Resolution.Lookups.annotation_type name (context : type_context).place (definitions : definitions).namespace (Resolution.Refusing : Resolution.strictness) with
                   | Resolution.Found { value = annotation } -> arity 0;
                       (MetaAnnotation { annotation = annotation } : meta_type)
                   | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = ((((context : type_context).place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = why } : Diagnostics.diagnostic)) with
                        | _ -> (assert false))
                   | Resolution.NotFound -> (MetaValue { t = Conversion.type_of t context definitions } : meta_type))
          | _ -> (MetaValue { t = Conversion.type_of t context definitions } : meta_type)

        let all (definitions : definitions) : (string, meta_type list) Collections.Maps.map =
          Collections.Maps.list_tuple_to_map (List.map (fun a -> let context = let fk_arg1 = Collections.Maps.empty_map () in
                let fk_arg2 = type_context_default_region () in
                let fk_arg3 = type_context_default_arrow_effects () in
                let fk_arg4 = type_context_default_expanding () in
                let fk_arg5 = type_context_default_spec_types () in
                let fk_arg6 = type_context_default_outside_view () in
                let fk_arg7 = type_context_default_seen_from () in
                let fk_arg8 = type_context_default_value_parameters () in
                let fk_arg9 = type_context_default_later_parameters () in
                ({ place = ({ Resolution.file = (a : Symbols.symbol).Symbols.file; path = (a : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; region = fk_arg2; arrow_effects = fk_arg3; expanding = fk_arg4; spec_types = fk_arg5; outside_view = fk_arg6; seen_from = fk_arg7; value_parameters = fk_arg8; later_parameters = fk_arg9 } : type_context) in
              let fields = match ((a : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
                | Parser.RecordDefinition { type_parameters = _; fields = fs; private_constructor = _; annotation = _; external_ = _ } -> fs
                | _ -> [] in
              List.iteri (fun i f -> if List.exists (fun it -> (it : Parser.field).Parser.name = (f : Parser.field).Parser.name) (List.take i fields) then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((a : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (f : Parser.field).Parser.at; message = "field '" ^ (f : Parser.field).Parser.name ^ "' is declared twice" } : Diagnostics.diagnostic)) with
                    | _ -> (assert false)) else ()) fields;
              ((a : Symbols.symbol).Symbols.name, List.map (fun f -> let t = meta_type_of (f : Parser.field).Parser.field_type context definitions in
                 if (f : Parser.field).Parser.vararg then (MetaList { item = t } : meta_type) else t) fields)) (List.filter (fun it -> Symbols.Symbols.is_annotation it) (((definitions : definitions).namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.declarations))

        let rec described (meta : meta_type) : string =
          match meta with
          | MetaValue { t = t } -> "a value of type " ^ Types.TypeText.shown t
          | MetaTypeReference -> "a type, like List<User>"
          | MetaSpec -> "a spec, by name"
          | MetaFunction -> "a function, by name"
          | MetaModule { spec = Some spec } -> "a module that follows " ^ (spec : Symbols.symbol).Symbols.name
          | MetaModule { spec = None } -> "a module, by name"
          | MetaCase { case_type = t } -> "a case of " ^ Types.TypeText.shown t
          | MetaField { record = record; field_type = _ } -> let fk_arg1 = Types.TypeText.shown record in
              let fk_arg2 = Types.TypeText.shown record in
              "a field of " ^ fk_arg1 ^ ", like " ^ fk_arg2 ^ ".name"
          | MetaAnnotation { annotation = a } -> "an annotation, @" ^ Symbols.Symbols.simple_name a ^ "(...)"
          | MetaList { item = item } -> "a list of " ^ described item ^ "s"
          | MetaTuple { items = items } -> "a tuple of " ^ String.concat ", " (List.map Fun.id (List.map (fun it -> described it) items))
      end

      module TypeDeclarations = struct
        let declared (d : Symbols.symbol) (definitions : definitions) : Core.type_declaration option =
          match ((d : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.RecordDefinition { type_parameters = type_parameters; fields = _; private_constructor = _; annotation = true; external_ = _ } -> None
          | Parser.RecordDefinition { type_parameters = type_parameters; fields = _; private_constructor = _; annotation = _; external_ = Some ocaml } -> Some (Core.DeclaredExternal { external_ = d; type_parameters = type_parameters; ocaml = ocaml } : Core.type_declaration)
          | Parser.RecordDefinition { type_parameters = type_parameters; fields = fields; private_constructor = _; annotation = _; external_ = None } -> let types = let fk_arg1 = List.map (fun it -> (Types.TypeParameter { name = it } : Types.type_)) type_parameters in
                let fk_arg2 = Conversion.record_fields_default_seen_from () in
                Conversion.record_fields d fk_arg1 None definitions fk_arg2 in
              Some (Core.DeclaredRecord { record = d; type_parameters = type_parameters; fields = List.map (fun (f, t) -> ({ Core.name = (f : Parser.field).Parser.name; t = t; variable = (f : Parser.field).Parser.variable } : Core.declared_field)) (Lang.Lists.list_zip fields types) } : Core.type_declaration)
          | Parser.CasesDefinition { type_parameters = type_parameters; cases = _; case_refs = _; includes = _ } -> let cases = List.map (fun (c, types) -> ({ Core.case = ({ Symbols.name = ((c : case_info).origin : Symbols.symbol).Symbols.name ^ "." ^ ((c : case_info).definition : Parser.case_definition).Parser.name; owner = (c : case_info).origin; definition = (c : case_info).definition } : Symbols.case_symbol); fields = List.map (fun (f, t) -> ({ Core.name = (f : Parser.field).Parser.name; t = t; variable = (f : Parser.field).Parser.variable } : Core.declared_field)) (Lang.Lists.list_zip ((c : case_info).definition : Parser.case_definition).Parser.fields types) } : Core.declared_case)) (let fk_arg1 = List.map (fun it -> (Types.TypeParameter { name = it } : Types.type_)) type_parameters in
                 let fk_arg2 = Conversion.cases_with_fields_default_seen_from () in
                 Conversion.cases_with_fields d fk_arg1 None definitions fk_arg2) in
              Some (Core.DeclaredCases { case_type = d; type_parameters = type_parameters; cases = cases } : Core.type_declaration)
          | Parser.AliasDefinition { type_parameters = type_parameters; target = target } -> Some (Core.DeclaredAlias { alias = d; type_parameters = type_parameters; target = Conversion.type_of target (let fk_arg1 = Collections.Maps.list_tuple_to_map (List.map (fun it -> (it, (Types.TypeParameter { name = it } : Types.type_))) type_parameters) in
               let fk_arg2 = type_context_default_region () in
               let fk_arg3 = type_context_default_arrow_effects () in
               let fk_arg4 = type_context_default_expanding () in
               let fk_arg5 = type_context_default_spec_types () in
               let fk_arg6 = type_context_default_outside_view () in
               let fk_arg7 = type_context_default_seen_from () in
               let fk_arg8 = type_context_default_value_parameters () in
               let fk_arg9 = type_context_default_later_parameters () in
               ({ place = ({ Resolution.file = (d : Symbols.symbol).Symbols.file; path = (d : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; region = fk_arg2; arrow_effects = fk_arg3; expanding = fk_arg4; spec_types = fk_arg5; outside_view = fk_arg6; seen_from = fk_arg7; value_parameters = fk_arg8; later_parameters = fk_arg9 } : type_context)) definitions } : Core.type_declaration)
          | _ -> None

        let all (definitions : definitions) : Core.type_declaration list =
          Lang.Lists.list_map_not_null (((definitions : definitions).namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.declarations (fun d -> match Diagnostics.Diagnostics.attempting (fun () -> declared d definitions) with
             | Ok declaration -> declaration
             | Error _ -> None)

        let to_strings (definitions : definitions) : (string, Symbols.symbol) Collections.Maps.map =
          Collections.Maps.list_tuple_to_map (Lang.Lists.list_map_not_null (Collections.Maps.map_to_list (((definitions : definitions).namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.functions) (fun (_, s) -> match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
              | Parser.FunctionDefinition { type_parameters = type_parameters; receiver = Some receiver; parameters = Some parameters; result = _; body = _; external_ = _; operator = _ } when ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.name = "toString" -> (match Diagnostics.Diagnostics.attempting (fun () -> Conversion.type_of receiver (let fk_arg1 = Collections.Maps.list_tuple_to_map (List.map (fun it -> (it, (Types.TypeParameter { name = it } : Types.type_))) type_parameters) in
                       let fk_arg2 = type_context_default_region () in
                       let fk_arg3 = type_context_default_arrow_effects () in
                       let fk_arg4 = type_context_default_expanding () in
                       let fk_arg5 = type_context_default_spec_types () in
                       let fk_arg6 = type_context_default_outside_view () in
                       let fk_arg7 = type_context_default_seen_from () in
                       let fk_arg8 = type_context_default_value_parameters () in
                       let fk_arg9 = type_context_default_later_parameters () in
                       ({ place = ({ Resolution.file = (s : Symbols.symbol).Symbols.file; path = (s : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; region = fk_arg2; arrow_effects = fk_arg3; expanding = fk_arg4; spec_types = fk_arg5; outside_view = fk_arg6; seen_from = fk_arg7; value_parameters = fk_arg8; later_parameters = fk_arg9 } : type_context)) definitions) with
                   | Ok (Types.Named { name = name; arguments = arguments; region = _ }) when let fk_arg1 = List.length (List.filter (fun it -> match it with
                             | Types.Effects it_as_effects -> false
                             | _ -> true) arguments) in
                       let fk_arg2 = List.length parameters in
                       fk_arg1 = fk_arg2 -> Some (name, s)
                   | _ -> None)
              | _ -> None))
      end
    end

    module Coverage = struct
      type shape =
        | CaseShape of { owner : string; name : string }
        | BooleanShape of { value : bool }
        | EmptyList
        | NonEmptyList
        | TupleShape of { size : int }
        | RecordShape of { name : string }
        | LiteralShape of { text : string }

      let rec show_shape (v : shape) =
        match v with
        | CaseShape r -> "CaseShape(" ^ "owner=" ^ Fun.id r.owner ^ ", name=" ^ Fun.id r.name ^ ")"
        | BooleanShape r -> "BooleanShape(" ^ "value=" ^ string_of_bool r.value ^ ")"
        | EmptyList -> "EmptyList"
        | NonEmptyList -> "NonEmptyList"
        | TupleShape r -> "TupleShape(" ^ "size=" ^ string_of_int r.size ^ ")"
        | RecordShape r -> "RecordShape(" ^ "name=" ^ Fun.id r.name ^ ")"
        | LiteralShape r -> "LiteralShape(" ^ "text=" ^ Fun.id r.text ^ ")"

      type 't alternative = { shape : shape; fields : 't list }

      let rec show_alternative show_t (v : 't alternative) =
        "Alternative(" ^ "shape=" ^ show_shape v.shape ^ ", fields=" ^ fk_show_list show_t v.fields ^ ")"

      type matches = { shape : shape option; fields : matches list }

      let rec show_matches (v : matches) =
        "Matches(" ^ "shape=" ^ fk_show_option show_shape v.shape ^ ", fields=" ^ fk_show_list show_matches v.fields ^ ")"

      module Coverage = struct
        let anything =
          ({ shape = None; fields = [] } : matches)

        let first_of (row : matches list) : matches =
          Option.value (List.nth_opt row 0) ~default:anything

        let rec anythings (count : int) : matches list =
          if count <= 0 then [] else anything :: anythings (count - 1)

        let specialized (rows : matches list list) (shape : shape) (arity : int) : matches list list =
          Lang.Lists.list_map_not_null rows (fun row -> let head = first_of row in
             match (head : matches).shape with
             | None -> Some (let fk_arg1 = anythings arity in
                  let fk_arg2 = List.drop 1 row in
                  fk_arg1 @ fk_arg2)
             | Some s when s = shape -> Some ((head : matches).fields @ List.drop 1 row)
             | _ -> None)

        let rec unmatched (rows : matches list list) (types : _ list) (alternatives : _ -> _ alternative list option) : matches list option =
          match types with
          | [] -> if List.is_empty rows then Some [] else None
          | t :: rest -> let heads = Lang.Lists.list_distinct (Lang.Lists.list_map_not_null rows (fun row -> (first_of row : matches).shape)) in
              match alternatives t with
              | Some shapes when Lang.Lists.list_is_not_empty heads && List.for_all (fun it -> List.mem (it : _ alternative).shape heads) shapes -> inside_one rows shapes rest alternatives
              | shapes -> unmatched_by_any rows heads shapes rest alternatives
        and inside_one (rows : matches list list) (shapes : _ alternative list) (rest : _ list) (alternatives : _ -> _ alternative list option) : matches list option =
          match shapes with
          | [] -> None
          | a :: others -> match unmatched (specialized rows (a : _ alternative).shape (List.length (a : _ alternative).fields)) ((a : _ alternative).fields @ rest) alternatives with
              | Some found -> Some (let fk_arg1 = ({ shape = Some (a : _ alternative).shape; fields = List.take (List.length (a : _ alternative).fields) found } : matches) in
                   let fk_arg2 = List.drop (List.length (a : _ alternative).fields) found in
                   fk_arg1 :: fk_arg2)
              | None -> inside_one rows others rest alternatives
        and unmatched_by_any (rows : matches list list) (heads : shape list) (shapes : _ alternative list option) (rest : _ list) (alternatives : _ -> _ alternative list option) : matches list option =
          let open_ = List.map (fun it -> List.drop 1 it) (List.filter (fun row -> Option.is_none (first_of row : matches).shape) rows) in
          Option.map (fun found -> let example = if List.is_empty heads then anything else (match Option.bind shapes (fun s -> List.find_opt (fun it -> not (List.mem (it : _ alternative).shape heads)) s) with
                  | Some a -> ({ shape = Some (a : _ alternative).shape; fields = anythings (List.length (a : _ alternative).fields) } : matches)
                  | None -> anything) in
             example :: found) (unmatched open_ rest alternatives)

        let missing (patterns : matches list) (t : _) (alternatives : _ -> _ alternative list option) : matches list =
          let rows = List.map (fun it -> [it]) patterns in
          match alternatives t with
          | None -> Option.value (Option.map (fun found -> Option.to_list (List.nth_opt found 0)) (unmatched rows [t] alternatives)) ~default:[]
          | Some shapes -> Lang.Lists.list_map_not_null shapes (fun a -> Option.map (fun found -> ({ shape = Some (a : _ alternative).shape; fields = found } : matches)) (unmatched (specialized rows (a : _ alternative).shape (List.length (a : _ alternative).fields)) (a : _ alternative).fields alternatives))

        let rec shown (m : matches) : string =
          match (m : matches).shape with
          | None -> "_"
          | Some (CaseShape { owner = _; name = name }) -> if List.is_empty (m : matches).fields then name else name ^ "(" ^ shown_all (m : matches).fields ^ ")"
          | Some (BooleanShape { value = value }) -> string_of_bool value
          | Some (TupleShape { size = _ }) -> "(" ^ shown_all (m : matches).fields ^ ")"
          | Some (RecordShape { name = name }) -> let fk_arg1 = Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".")) ~default:name in
              let fk_arg2 = shown_all (m : matches).fields in
              fk_arg1 ^ "(" ^ fk_arg2 ^ ")"
          | Some (LiteralShape { text = text }) -> text
          | Some EmptyList -> "[]"
          | Some NonEmptyList -> let (items, end_) = list_items m [] in
              match (end_ : matches).shape with
              | Some EmptyList -> "[" ^ String.concat ", " (List.map Fun.id items) ^ "]"
              | _ -> "[" ^ String.concat ", " (List.map Fun.id (items @ ["*" ^ shown end_])) ^ "]"
        and shown_all (ms : matches list) : string =
          String.concat ", " (List.map Fun.id (List.map (fun it -> shown it) ms))
        and list_items (m : matches) (items : string list) : string list * matches =
          match ((m : matches).shape, (m : matches).fields) with
          | (Some NonEmptyList, [item; rest]) -> list_items rest (items @ [shown item])
          | _ -> (items, m)
      end
    end

    module Inference = struct
      type argument_value =
        | WrittenValue of { expression : Parser.expression }
        | TrailingBlock of { at : Parser.position; parameters : Parser.parameter list option; block : Parser.expression }
        | DefaultValue of { at : Parser.position; function_ : string }

      let rec show_argument_value (v : argument_value) =
        match v with
        | WrittenValue r -> "WrittenValue(" ^ "expression=" ^ Parser.show_expression r.expression ^ ")"
        | TrailingBlock r -> "TrailingBlock(" ^ "at=" ^ Parser.show_position r.at ^ ", parameters=" ^ fk_show_option (fk_show_list Parser.show_parameter) r.parameters ^ ", block=" ^ Parser.show_expression r.block ^ ")"
        | DefaultValue r -> "DefaultValue(" ^ "at=" ^ Parser.show_position r.at ^ ", function=" ^ Fun.id r.function_ ^ ")"

      type block_step =
        | RunStep of { core : Core.core }
        | BindStep of { pattern : Core.matcher; value : Core.core }
        | VarStep of { name : string; value : Core.core }
        | ByStep of { pattern : Core.matcher; value : Core.core }
        | FunctionStep of { name : string; parameters : Core.matcher list; body : Core.core }

      let rec show_block_step (v : block_step) =
        match v with
        | RunStep r -> "RunStep(" ^ "core=" ^ Core.show_core r.core ^ ")"
        | BindStep r -> "BindStep(" ^ "pattern=" ^ Core.show_matcher r.pattern ^ ", value=" ^ Core.show_core r.value ^ ")"
        | VarStep r -> "VarStep(" ^ "name=" ^ Fun.id r.name ^ ", value=" ^ Core.show_core r.value ^ ")"
        | ByStep r -> "ByStep(" ^ "pattern=" ^ Core.show_matcher r.pattern ^ ", value=" ^ Core.show_core r.value ^ ")"
        | FunctionStep r -> "FunctionStep(" ^ "name=" ^ Fun.id r.name ^ ", parameters=" ^ fk_show_list Core.show_matcher r.parameters ^ ", body=" ^ Core.show_core r.body ^ ")"

      type call_argument = { name : string option; value : argument_value; text : string option; operands : (string * string) option }

      let rec show_call_argument (v : call_argument) =
        "CallArgument(" ^ "name=" ^ fk_show_option Fun.id v.name ^ ", value=" ^ show_argument_value v.value ^ ", text=" ^ fk_show_option Fun.id v.text ^ ", operands=" ^ fk_show_option (fun (x0, x1) -> "(" ^ Fun.id x0 ^ ", " ^ Fun.id x1 ^ ")") v.operands ^ ")"

      type checked_function = { function_ : Symbols.symbol; scheme : Types.scheme; body : Core.core_function option }

      let rec show_checked_function (v : checked_function) =
        "CheckedFunction(" ^ "function=" ^ Symbols.show_symbol v.function_ ^ ", scheme=" ^ Types.show_scheme v.scheme ^ ", body=" ^ fk_show_option Core.show_core_function v.body ^ ")"

      type constructor_shape = { constructor : Core.constructor; field_names : string list; field_types : Types.type_ list; result : Types.type_ }

      let rec show_constructor_shape (v : constructor_shape) =
        "ConstructorShape(" ^ "constructor=" ^ Core.show_constructor v.constructor ^ ", fieldNames=" ^ fk_show_list Fun.id v.field_names ^ ", fieldTypes=" ^ fk_show_list Types.show_type v.field_types ^ ", result=" ^ Types.show_type v.result ^ ")"

      type default_handler = { effect_ : Symbols.symbol; handler : Symbols.symbol }

      let rec show_default_handler (v : default_handler) =
        "DefaultHandler(" ^ "effect=" ^ Symbols.show_symbol v.effect_ ^ ", handler=" ^ Symbols.show_symbol v.handler ^ ")"

      type function_group = { functions : Symbols.symbol list; recursive : bool }

      let rec show_function_group (v : function_group) =
        "FunctionGroup(" ^ "functions=" ^ fk_show_list Symbols.show_symbol v.functions ^ ", recursive=" ^ string_of_bool v.recursive ^ ")"

      type known = { schemes : (string, Types.scheme) Collections.Maps.map; type_parameter_variables : (string, (string, Types.type_variable) Collections.Maps.map) Collections.Maps.map; provisional : (string, Types.type_) Collections.Maps.map; viewed : (string, Types.type_) Collections.Maps.map; outside : (string, Types.scheme) Collections.Maps.map; bodies : (string, Core.core_function) Collections.Maps.map }

      let rec show_known (v : known) =
        "Known(" ^ "schemes=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Types.show_scheme) v.schemes ^ ", typeParameterVariables=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id (fun v -> Collections.Maps.map_to_string v Fun.id Types.show_type_variable)) v.type_parameter_variables ^ ", provisional=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Types.show_type) v.provisional ^ ", viewed=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Types.show_type) v.viewed ^ ", outside=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Types.show_scheme) v.outside ^ ", bodies=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Core.show_core_function) v.bodies ^ ")"

      type monad_functions =
        | Binding of { name : string; at : Parser.position; bind : Symbols.symbol; pure : Symbols.symbol }
        | Mapping of { name : string; at : Parser.position; map : Symbols.symbol; product : Symbols.symbol; pure : Symbols.symbol option }

      let rec show_monad_functions (v : monad_functions) =
        match v with
        | Binding r -> "Binding(" ^ "name=" ^ Fun.id r.name ^ ", at=" ^ Parser.show_position r.at ^ ", bind=" ^ Symbols.show_symbol r.bind ^ ", pure=" ^ Symbols.show_symbol r.pure ^ ")"
        | Mapping r -> "Mapping(" ^ "name=" ^ Fun.id r.name ^ ", at=" ^ Parser.show_position r.at ^ ", map=" ^ Symbols.show_symbol r.map ^ ", product=" ^ Symbols.show_symbol r.product ^ ", pure=" ^ fk_show_option Symbols.show_symbol r.pure ^ ")"

      type narrowing = { case_name : string; case_type : string; fields : Parser.field list; types : (string, Types.type_) Collections.Maps.map; shared : bool }

      let rec show_narrowing (v : narrowing) =
        "Narrowing(" ^ "caseName=" ^ Fun.id v.case_name ^ ", caseType=" ^ Fun.id v.case_type ^ ", fields=" ^ fk_show_list Parser.show_field v.fields ^ ", types=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Types.show_type) v.types ^ ", shared=" ^ string_of_bool v.shared ^ ")"

      type field_reference =
        | RecordField of { record : Symbols.symbol; t : Types.type_ }
        | NarrowedField of { narrowing : narrowing; t : Types.type_ }
        | ModuleMember of { spec : Symbols.symbol; value : Parser.spec_value; t : Types.type_ }

      let rec show_field_reference (v : field_reference) =
        match v with
        | RecordField r -> "RecordField(" ^ "record=" ^ Symbols.show_symbol r.record ^ ", t=" ^ Types.show_type r.t ^ ")"
        | NarrowedField r -> "NarrowedField(" ^ "narrowing=" ^ show_narrowing r.narrowing ^ ", t=" ^ Types.show_type r.t ^ ")"
        | ModuleMember r -> "ModuleMember(" ^ "spec=" ^ Symbols.show_symbol r.spec ^ ", value=" ^ Parser.show_spec_value r.value ^ ", t=" ^ Types.show_type r.t ^ ")"

      type local = { t : Types.type_; region : Types.type_ option; narrowed : narrowing option; hides : bool }

      let rec show_local (v : local) =
        "Local(" ^ "t=" ^ Types.show_type v.t ^ ", region=" ^ fk_show_option Types.show_type v.region ^ ", narrowed=" ^ fk_show_option show_narrowing v.narrowed ^ ", hides=" ^ string_of_bool v.hides ^ ")"

      type operation = { effect_ : Symbols.symbol; value : Parser.spec_value }

      let rec show_operation (v : operation) =
        "Operation(" ^ "effect=" ^ Symbols.show_symbol v.effect_ ^ ", value=" ^ Parser.show_spec_value v.value ^ ")"

      type pending_when = { file : string option; at : Parser.position; patterns : Coverage.matches list; subject : Types.type_ }

      let rec show_pending_when (v : pending_when) =
        "PendingWhen(" ^ "file=" ^ fk_show_option Fun.id v.file ^ ", at=" ^ Parser.show_position v.at ^ ", patterns=" ^ fk_show_list Coverage.show_matches v.patterns ^ ", subject=" ^ Types.show_type v.subject ^ ")"

      type scope = { own : (string, local) Collections.Maps.map; outer : scope option }

      let rec show_scope (v : scope) =
        "Scope(" ^ "own=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_local) v.own ^ ", outer=" ^ fk_show_option show_scope v.outer ^ ")"

      type block_so_far = { scope : scope; rest : Types.type_; steps : (Types.type_ * Types.type_) list; pending : (Parser.position * Parser.pattern * Types.type_) list; after : Parser.position option; assigned : bool; lines : block_step list }

      let rec show_block_so_far (v : block_so_far) =
        "BlockSoFar(" ^ "scope=" ^ show_scope v.scope ^ ", rest=" ^ Types.show_type v.rest ^ ", steps=" ^ fk_show_list (fun (x0, x1) -> "(" ^ Types.show_type x0 ^ ", " ^ Types.show_type x1 ^ ")") v.steps ^ ", pending=" ^ fk_show_list (fun (x0, x1, x2) -> "(" ^ Parser.show_position x0 ^ ", " ^ Parser.show_pattern x1 ^ ", " ^ Types.show_type x2 ^ ")") v.pending ^ ", after=" ^ fk_show_option Parser.show_position v.after ^ ", assigned=" ^ string_of_bool v.assigned ^ ", lines=" ^ fk_show_list show_block_step v.lines ^ ")"

      type checked_pattern = { scope : scope; matches : Coverage.matches list; matcher : Core.matcher }

      let rec show_checked_pattern (v : checked_pattern) =
        "CheckedPattern(" ^ "scope=" ^ show_scope v.scope ^ ", matches=" ^ fk_show_list Coverage.show_matches v.matches ^ ", matcher=" ^ Core.show_matcher v.matcher ^ ")"

      type signature = { function_ : Symbols.symbol; type_variables : (string * Types.type_variable) list; row : Types.row; t : Types.type_; outside : Types.type_ option }

      let rec show_signature (v : signature) =
        "Signature(" ^ "function=" ^ Symbols.show_symbol v.function_ ^ ", typeVariables=" ^ fk_show_list (fun (x0, x1) -> "(" ^ Fun.id x0 ^ ", " ^ Types.show_type_variable x1 ^ ")") v.type_variables ^ ", row=" ^ Types.show_row v.row ^ ", t=" ^ Types.show_type v.t ^ ", outside=" ^ fk_show_option Types.show_type v.outside ^ ")"

      type spec_types = { values : (string, Types.scheme) Collections.Maps.map; parameters : Types.type_variable list }

      let rec show_spec_types (v : spec_types) =
        "SpecTypes(" ^ "values=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Types.show_scheme) v.values ^ ", parameters=" ^ fk_show_list Types.show_type_variable v.parameters ^ ")"

      type environment = { definitions : Definitions.definitions; functions : (string, Symbols.symbol) Collections.Maps.map; ordered_functions : Symbols.symbol list; extensions : (string, Symbols.symbol list) Collections.Maps.map; cases_by_name : (string, Symbols.case_symbol list) Collections.Maps.map; module_specs : (string, Symbols.symbol) Collections.Maps.map; spec_types : (string, spec_types) Collections.Maps.map; operations : (string, operation list) Collections.Maps.map; known : known }

      let rec show_environment (v : environment) =
        "Environment(" ^ "definitions=" ^ Definitions.show_definitions v.definitions ^ ", functions=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Symbols.show_symbol) v.functions ^ ", orderedFunctions=" ^ fk_show_list Symbols.show_symbol v.ordered_functions ^ ", extensions=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id (fk_show_list Symbols.show_symbol)) v.extensions ^ ", casesByName=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id (fk_show_list Symbols.show_case_symbol)) v.cases_by_name ^ ", moduleSpecs=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Symbols.show_symbol) v.module_specs ^ ", specTypes=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id show_spec_types) v.spec_types ^ ", operations=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id (fk_show_list show_operation)) v.operations ^ ", known=" ^ show_known v.known ^ ")"

      type context = { environment : environment; place : Resolution.place; type_parameters : (string, Types.type_) Collections.Maps.map; value_parameters : (string, Types.type_) Collections.Maps.map }

      let rec show_context (v : context) =
        "Context(" ^ "environment=" ^ show_environment v.environment ^ ", place=" ^ Resolution.show_place v.place ^ ", typeParameters=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Types.show_type) v.type_parameters ^ ", valueParameters=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Types.show_type) v.value_parameters ^ ")"

      type inferred = { environment : environment; known : known; functions : checked_function list; meta_types : (string, Definitions.meta_type list) Collections.Maps.map; groups : function_group list }

      let rec show_inferred (v : inferred) =
        "Inferred(" ^ "environment=" ^ show_environment v.environment ^ ", known=" ^ show_known v.known ^ ", functions=" ^ fk_show_list show_checked_function v.functions ^ ", metaTypes=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id (fk_show_list Definitions.show_meta_type)) v.meta_types ^ ", groups=" ^ fk_show_list show_function_group v.groups ^ ")"

      type typed = { t : Types.type_; spelled : Symbols.case_symbol option; core : Core.core }

      let rec show_typed (v : typed) =
        "Typed(" ^ "t=" ^ Types.show_type v.t ^ ", spelled=" ^ fk_show_option Symbols.show_case_symbol v.spelled ^ ", core=" ^ Core.show_core v.core ^ ")"

      type checked_branch = { body : (Parser.expression * typed) option; matches : Coverage.matches list; core : Core.match_branch }

      let rec show_checked_branch (v : checked_branch) =
        "CheckedBranch(" ^ "body=" ^ fk_show_option (fun (x0, x1) -> "(" ^ Parser.show_expression x0 ^ ", " ^ show_typed x1 ^ ")") v.body ^ ", matches=" ^ fk_show_list Coverage.show_matches v.matches ^ ", core=" ^ Core.show_match_branch v.core ^ ")"

      type method_call =
        | CalledMethod of { typed : typed }
        | CalledField of { arguments : call_argument list }

      let rec show_method_call (v : method_call) =
        match v with
        | CalledMethod r -> "CalledMethod(" ^ "typed=" ^ show_typed r.typed ^ ")"
        | CalledField r -> "CalledField(" ^ "arguments=" ^ fk_show_list show_call_argument r.arguments ^ ")"

      type uses = { functions : Symbols.symbol list; guessed : string list }

      let rec show_uses (v : uses) =
        "Uses(" ^ "functions=" ^ fk_show_list Symbols.show_symbol v.functions ^ ", guessed=" ^ fk_show_list Fun.id v.guessed ^ ")"

      type _ Effect.t +=
        | Covering_cover : pending_when -> unit Effect.t

      type 'fk_answer covering_handler = { cover : pending_when -> (unit -> 'fk_answer) -> 'fk_answer }

      let handle_covering (h : 'fk_answer covering_handler) (f : unit -> 'fk_answer) : 'fk_answer =
        match f () with
        | v -> v
        | effect (Covering_cover x0), k -> h.cover x0 (fun v -> Effect.Deep.continue k v)

      type _ Effect.t +=
        | Doing_perform : Types.row * Parser.position -> unit Effect.t

      type 'fk_answer doing_handler = { perform : Types.row -> Parser.position -> (unit -> 'fk_answer) -> 'fk_answer }

      let handle_doing (h : 'fk_answer doing_handler) (f : unit -> 'fk_answer) : 'fk_answer =
        match f () with
        | v -> v
        | effect (Doing_perform (x0, x1)), k -> h.perform x0 x1 (fun v -> Effect.Deep.continue k v)

      module Defaults = struct
        let marker =
          "$default$"

        let name_of (owner : string) (name : string) : string =
          (owner ^ marker) ^ name

        let made (owner : Symbols.symbol) (owner_name : string) (name : string) (at : Parser.position) (value_type : Parser.type_ref option) (value : Parser.expression) (type_parameters : string list) : Symbols.symbol =
          let full = name_of owner_name name in
          let definition = (Parser.FunctionDefinition { type_parameters = type_parameters; receiver = None; parameters = Some []; result = value_type; body = value; external_ = None; operator = false } : Parser.definition) in
          let visibility = if ((owner : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.visibility = (Parser.Private : Parser.visibility) then (Parser.Private : Parser.visibility) else (Parser.Public : Parser.visibility) in
          ({ Symbols.name = full; path = (owner : Symbols.symbol).Symbols.path; declaration = (let fk_arg1 = Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) full ".")) ~default:full in
           let fk_arg2 = Parser.declaration_default_opaque () in
           let fk_arg3 = Parser.declaration_default_annotations () in
           ({ Parser.at = at; name = fk_arg1; definition = definition; visibility = visibility; opaque = fk_arg2; annotations = fk_arg3 } : Parser.declaration)); file = (owner : Symbols.symbol).Symbols.file } : Symbols.symbol)

        let of_function (s : Symbols.symbol) : Symbols.symbol list =
          let parameters = Option.value (Symbols.Signatures.written_parameters_of s) ~default:[] in
          List.concat_map (fun p -> match (p : Parser.parameter).Parser.default with
             | None -> []
             | Some value -> let refs = Symbols.References.of_ value [] in
                 match List.find_opt (fun other -> List.mem (other : Parser.parameter).Parser.name refs) parameters with
                 | Some other -> (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = Symbols.Positions.of_ value; message = "a default can't use the other parameters, as '" ^ (other : Parser.parameter).Parser.name ^ "' here: it's worked out on its own" } : Diagnostics.diagnostic)) with
                      | _ -> (assert false))
                 | None -> [made s (s : Symbols.symbol).Symbols.name (p : Parser.parameter).Parser.name (p : Parser.parameter).Parser.at (p : Parser.parameter).Parser.parameter_type value (Symbols.Signatures.type_parameters_of s)]) parameters

        let of_annotation (s : Symbols.symbol) : Symbols.symbol list =
          match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.RecordDefinition { type_parameters = _; fields = fields; private_constructor = _; annotation = _; external_ = _ } -> (match List.find_opt (fun it -> Option.is_some (it : Parser.field).Parser.default) fields with
               | Some f -> (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (f : Parser.field).Parser.at; message = "an annotation's fields can't have defaults" } : Diagnostics.diagnostic)) with
                    | _ -> (assert false))
               | None -> [])
          | _ -> []

        let of_record (s : Symbols.symbol) : Symbols.symbol list =
          match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.RecordDefinition { type_parameters = type_parameters; fields = fields; private_constructor = _; annotation = _; external_ = _ } -> List.concat_map (fun f -> Option.to_list (Option.map (fun value -> made s (s : Symbols.symbol).Symbols.name (f : Parser.field).Parser.name (f : Parser.field).Parser.at (Some (f : Parser.field).Parser.field_type) value type_parameters) (f : Parser.field).Parser.default)) fields
          | _ -> []

        let of_cases (s : Symbols.symbol) : Symbols.symbol list =
          match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.CasesDefinition { type_parameters = type_parameters; cases = cases; case_refs = _; includes = _ } -> List.concat_map (fun c -> List.concat_map (fun f -> Option.to_list (Option.map (fun value -> made s ((s : Symbols.symbol).Symbols.name ^ "$" ^ (c : Parser.case_definition).Parser.name) (f : Parser.field).Parser.name (f : Parser.field).Parser.at (Some (f : Parser.field).Parser.field_type) value type_parameters) (f : Parser.field).Parser.default)) (c : Parser.case_definition).Parser.fields) cases
          | _ -> []

        let rec names_in (t : Parser.type_ref) : string list =
          match t with
          | Parser.NamedType { at = _; name = name; arguments = arguments } -> name :: List.concat_map (fun it -> names_in it) arguments
          | Parser.FunctionType { at = _; parameters = parameters; result = result; effects = _ } -> let fk_arg1 = List.concat_map (fun it -> names_in it) parameters in
              let fk_arg2 = names_in result in
              fk_arg1 @ fk_arg2
          | Parser.TupleType { at = _; elements = elements } -> List.concat_map (fun it -> names_in it) elements
          | Parser.EffectsType { at = _; effects = _ } -> []
          | Parser.GivenType { at = _; name = _; given = given } -> names_in given

        let of_spec (s : Symbols.symbol) : Symbols.symbol list =
          match ((s : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = types; values = values; type_parameters = _; copy_of = _; parents = _ } -> List.concat_map (fun v -> List.concat_map (fun p -> match (p : Parser.parameter).Parser.default with
                    | None -> []
                    | Some value -> let own = List.find_opt (fun name -> List.exists (fun it -> (it : Parser.spec_type).Parser.name = name) types) (Option.value (Option.map (fun it -> names_in it) (p : Parser.parameter).Parser.parameter_type) ~default:[]) in
                        match own with
                        | Some name -> (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = Symbols.Positions.of_ value; message = "a default is worked out on its own, so it can't be a " ^ name ^ ", which each module says what it is" } : Diagnostics.diagnostic)) with
                             | _ -> (assert false))
                        | None -> [made s ((s : Symbols.symbol).Symbols.name ^ "$" ^ (v : Parser.spec_value).Parser.name) (p : Parser.parameter).Parser.name (p : Parser.parameter).Parser.at (p : Parser.parameter).Parser.parameter_type value (v : Parser.spec_value).Parser.type_parameters]) (Option.value (v : Parser.spec_value).Parser.parameters ~default:[])) values
          | _ -> []

        let of_ (d : Symbols.symbol) : Symbols.symbol list =
          if Symbols.Symbols.is_function d then of_function d else if Symbols.Symbols.is_annotation d then of_annotation d else if Symbols.Symbols.is_record d then of_record d else if Symbols.Symbols.is_case_type d then of_cases d else if Symbols.Symbols.is_spec d then of_spec d else []

        let is_default (s : Symbols.symbol) : bool =
          Lang.Strings.string_contains (s : Symbols.symbol).Symbols.name marker
      end

      let context_default_value_parameters () : (string, Types.type_) Collections.Maps.map =
        Collections.Maps.empty_map ()

      let known_default_outside () : (string, Types.scheme) Collections.Maps.map =
        Collections.Maps.empty_map ()

      let known_default_bodies () : (string, Core.core_function) Collections.Maps.map =
        Collections.Maps.empty_map ()

      module Globals = struct
        let problem (context : context) (at : Parser.position) (message : string) : Diagnostics.diagnostic =
          ({ Diagnostics.file = ((((context : context).place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = message } : Diagnostics.diagnostic)

        let visible (s : Symbols.symbol) (context : context) : bool =
          Option.is_none (Resolution.Visibility.why_hidden s (context : context).place ((((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table)

        let only_as_package_mate (s : Symbols.symbol) (context : context) : bool option =
          let file = ((context : context).place : Resolution.place).Resolution.file in
          let owner = String.concat "." (List.map Fun.id (s : Symbols.symbol).Symbols.path) in
          let here = String.concat "." (List.map Fun.id ((context : context).place : Resolution.place).Resolution.path) in
          let imported = fun i -> let p = String.concat "." (List.map Fun.id (i : Parser.import).Parser.path) in
              p = owner || String.starts_with ~prefix:(owner ^ ".") p in
          if (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path = ((file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path || (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.project = (Sources.CoreProject : Sources.project) then Some false else if (String.equal "" owner || here = owner) || String.starts_with ~prefix:(owner ^ ".") here then Some false else if List.exists imported (file : Sources.loaded_file).Sources.imports then Some false else (let is_package = match Collections.Maps.map_get (((((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.modules owner with
                   | Some (Symbols.PackageModule { name = _ }) -> true
                   | _ -> false in
                 let pkg = String.concat "." (List.map Fun.id (if is_package then (s : Symbols.symbol).Symbols.path else Lang.Lists.list_drop_last (s : Symbols.symbol).Symbols.path 1)) in
                 if here = pkg || String.starts_with ~prefix:(pkg ^ ".") here then Some true else None)

        let in_scope (s : Symbols.symbol) (context : context) : bool =
          Option.is_some (only_as_package_mate s context)

        let extensions_named (name : string) (context : context) : Symbols.symbol list =
          List.filter (fun it -> visible it context && in_scope it context) (Collections.Maps.map_get_or_default ((context : context).environment : environment).extensions name [])

        let find (name : string) (context : context) (strictness : Resolution.strictness) : Symbols.symbol Resolution.lookup =
          let functions = ((context : context).environment : environment).functions in
          Resolution.Names.find name functions (fun s -> Some s) (fun full -> Collections.Maps.map_contains_key functions full) (context : context).place (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace strictness

        let type_context (context : context) : Definitions.type_context =
          let fk_named3 = Definitions.type_context_default_region () in
          let fk_named4 = Definitions.type_context_default_arrow_effects () in
          let fk_named5 = Definitions.type_context_default_expanding () in
          let fk_named6 = Definitions.type_context_default_spec_types () in
          let fk_named7 = Definitions.type_context_default_outside_view () in
          let fk_named8 = Definitions.type_context_default_seen_from () in
          let fk_named10 = Definitions.type_context_default_later_parameters () in
          ({ Definitions.place = (context : context).place; type_parameters = (context : context).type_parameters; region = fk_named3; arrow_effects = fk_named4; expanding = fk_named5; spec_types = fk_named6; outside_view = fk_named7; seen_from = fk_named8; value_parameters = (context : context).value_parameters; later_parameters = fk_named10 } : Definitions.type_context)

        let rec fit (wanted : Types.type_) (actual : Types.type_) : int option =
          match let fk_arg1 = Types.Types.resolved wanted in
          let fk_arg2 = Types.Types.resolved actual in
          (fk_arg1, fk_arg2) with
          | (Types.Variable { variable = _ }, _) -> Some 0
          | (_, Types.Variable { variable = _ }) -> Some 0
          | (Types.Named { name = n; arguments = xs; region = _ }, Types.Named { name = m; arguments = ys; region = _ }) -> if n <> m || (let fk_arg1 = List.length xs in
               let fk_arg2 = List.length ys in
               fk_arg1 <> fk_arg2) then None else fit_all xs ys 1
          | (Types.FunctionOf { parameters = xs; result = x; effects = _ }, Types.FunctionOf { parameters = ys; result = y; effects = _ }) -> if let fk_arg1 = List.length xs in
              let fk_arg2 = List.length ys in
              fk_arg1 <> fk_arg2 then None else fit_all (xs @ [x]) (ys @ [y]) 0
          | (Types.TupleOf { elements = xs }, Types.TupleOf { elements = ys }) -> if let fk_arg1 = List.length xs in
              let fk_arg2 = List.length ys in
              fk_arg1 <> fk_arg2 then None else fit_all xs ys 1
          | (Types.Effects { row = _ }, Types.Effects { row = _ }) -> Some 0
          | (Types.Abstract { name = n; arguments = xs }, Types.Abstract { name = m; arguments = ys }) -> if n <> m || (let fk_arg1 = List.length xs in
               let fk_arg2 = List.length ys in
               fk_arg1 <> fk_arg2) then None else fit_all xs ys 1
          | _ -> None
        and fit_all (xs : Types.type_ list) (ys : Types.type_ list) (start : int) : int option =
          List.fold_left (fun acc pair -> let (x, y) = pair in
             Option.bind acc (fun n -> Option.map (fun it -> n + it) (fit x y))) (Some start) (Lang.Lists.list_zip xs ys)

        let receiver_type (s : Symbols.symbol) (context : context) : Types.type_ =
          match Symbols.Signatures.receiver_of s with
          | Some receiver -> let parameters = Collections.Maps.list_tuple_to_map (List.map (fun p -> (p, (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_))) (Symbols.Signatures.type_parameters_of s)) in
              Definitions.Conversion.type_of receiver (let fk_arg1 = Definitions.type_context_default_region () in
               let fk_arg2 = Definitions.type_context_default_arrow_effects () in
               let fk_arg3 = Definitions.type_context_default_expanding () in
               let fk_arg4 = Definitions.type_context_default_spec_types () in
               let fk_arg5 = Definitions.type_context_default_outside_view () in
               let fk_arg6 = Definitions.type_context_default_seen_from () in
               let fk_arg7 = Definitions.type_context_default_value_parameters () in
               let fk_arg8 = Definitions.type_context_default_later_parameters () in
               ({ Definitions.place = ({ Resolution.file = (s : Symbols.symbol).Symbols.file; path = (s : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = parameters; region = fk_arg1; arrow_effects = fk_arg2; expanding = fk_arg3; spec_types = fk_arg4; outside_view = fk_arg5; seen_from = fk_arg6; value_parameters = fk_arg7; later_parameters = fk_arg8 } : Definitions.type_context)) ((context : context).environment : environment).definitions
          | None -> (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_)

        let outside_scheme (s : Symbols.symbol) (context : context) : Types.scheme option =
          if Resolution.Visibility.is_inside (context : context).place (s : Symbols.symbol).Symbols.path then None else Collections.Maps.map_get (((context : context).environment : environment).known : known).outside (s : Symbols.symbol).Symbols.name

        let inside_type (s : Symbols.symbol) (at : Parser.position) (context : context) : Types.type_ =
          let known = ((context : context).environment : environment).known in
          match Collections.Maps.map_get (known : known).viewed (s : Symbols.symbol).Symbols.name with
          | Some t -> t
          | None -> match Collections.Maps.map_get (known : known).provisional (s : Symbols.symbol).Symbols.name with
              | Some t -> t
              | None -> match Collections.Maps.map_get (known : known).schemes (s : Symbols.symbol).Symbols.name with
                  | Some scheme -> Types.Types.instantiate scheme (Types.Types.instantiate_default_given ())
                  | None -> match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("'" ^ Symbols.Symbols.simple_name s ^ "' is used before it's checked"))) with
                      | _ -> (assert false)

        let type_of (s : Symbols.symbol) (at : Parser.position) (context : context) : Types.type_ =
          match outside_scheme s context with
          | Some scheme -> Types.Types.instantiate scheme (Types.Types.instantiate_default_given ())
          | None -> inside_type s at context

        let find_or_refuse (name : string) (at : Parser.position) (context : context) : Symbols.symbol option =
          match find name context (Resolution.Refusing : Resolution.strictness) with
          | Resolution.Found { value = s } -> Some s
          | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at why)) with
               | _ -> (assert false))
          | Resolution.NotFound -> None

        let rec names_in (t : Parser.type_ref) : string list =
          match t with
          | Parser.NamedType { at = _; name = name; arguments = [] } -> if Lang.Strings.string_contains name "." then [] else [name]
          | Parser.NamedType { at = _; name = _; arguments = arguments } -> List.concat_map (fun it -> names_in it) arguments
          | Parser.TupleType { at = _; elements = elements } -> List.concat_map (fun it -> names_in it) elements
          | Parser.FunctionType { at = _; parameters = parameters; result = result; effects = _ } -> let fk_arg1 = List.concat_map (fun it -> names_in it) parameters in
              let fk_arg2 = names_in result in
              fk_arg1 @ fk_arg2
          | Parser.EffectsType { at = _; effects = _ } -> []
          | Parser.GivenType { at = _; name = _; given = given } -> names_in given

        let type_for_call (s : Symbols.symbol) (type_arguments : Parser.type_ref list) (at : Parser.position) (context : context) : Types.type_ =
          if List.is_empty type_arguments then type_of s at context else (let receiver_names = Option.value (Option.map (fun it -> names_in it) (Symbols.Signatures.receiver_of s)) ~default:[] in
             let declared = Lang.Lists.list_drop_while (List.filter (fun it -> not (String.starts_with ~prefix:"@" it)) (Symbols.Signatures.type_parameters_of s)) (fun it -> List.mem it receiver_names) in
             let method_ = Symbols.Signatures.method_name s in
             if let fk_arg1 = List.length declared in
             let fk_arg2 = List.length type_arguments in
             fk_arg1 <> fk_arg2 then (match Effect.perform (Diagnostics.Abandoning_abandon (problem context at (let fk_arg1 = string_of_int (List.length declared) in
                   let fk_arg2 = if List.length declared = 1 then "" else "s" in
                   let fk_arg3 = string_of_int (List.length type_arguments) in
                   "'" ^ method_ ^ "' takes " ^ fk_arg1 ^ " type argument" ^ fk_arg2 ^ ", not " ^ fk_arg3))) with
                | _ -> (assert false)) else ();
             let given = List.map (fun it -> Definitions.Conversion.type_of it (type_context context) ((context : context).environment : environment).definitions) type_arguments in
             let known = ((context : context).environment : environment).known in
             match let fk_arg1 = Collections.Maps.map_get (known : known).type_parameter_variables (s : Symbols.symbol).Symbols.name in
             let fk_arg2 = Lang.Options.option_or_else (outside_scheme s context) (fun () -> Collections.Maps.map_get (known : known).schemes (s : Symbols.symbol).Symbols.name) in
