             | (Some variables, Some scheme) -> Types.Types.instantiate scheme (Collections.Maps.list_tuple_to_map (Lang.Lists.list_map_not_null (Lang.Lists.list_zip declared given) (fun (name, t) -> Option.map (fun v -> (v, t)) (Collections.Maps.map_get variables name))))
             | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (problem context at ("'" ^ method_ ^ "' can't be given type arguments here"))) with
                 | _ -> (assert false))
      end

      let check_distinct (names : (string * Parser.position) list) (context : context) : unit =
        let named = List.filter (fun (name, _) -> name <> "_") names in
        let first_repeated = List.find_opt (fun name -> Lang.Lists.list_count named (fun (n, _) -> n = name) > 1) (Lang.Lists.list_distinct (List.map (fun (name, _) -> name) named)) in
        match first_repeated with
        | Some name -> (match List.filter (fun (n, _) -> n = name) named with
             | _ :: (_, second) :: _ -> (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context second ("'" ^ name ^ "' is declared twice"))) with
                  | _ -> (assert false))
             | _ -> ())
        | None -> ()

      module Environments = struct
        let spec_types_of (spec : Symbols.symbol) (definitions : Definitions.definitions) : spec_types =
          match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = types; values = values; type_parameters = type_parameters; copy_of = _; parents = _ } -> let place = ({ Resolution.file = (spec : Symbols.symbol).Symbols.file; path = (spec : Symbols.symbol).Symbols.path } : Resolution.place) in
              let context = let fk_arg1 = let fk_arg1 = Collections.Maps.empty_map () in
                  let fk_arg2 = Collections.Maps.empty_map () in
                  let fk_arg3 = Collections.Maps.empty_map () in
                  let fk_arg4 = Collections.Maps.empty_map () in
                  let fk_arg5 = Collections.Maps.empty_map () in
                  let fk_arg6 = Collections.Maps.empty_map () in
                  let fk_arg7 = let fk_arg1 = Collections.Maps.empty_map () in
                    let fk_arg2 = Collections.Maps.empty_map () in
                    let fk_arg3 = Collections.Maps.empty_map () in
                    let fk_arg4 = Collections.Maps.empty_map () in
                    let fk_arg5 = known_default_outside () in
                    let fk_arg6 = known_default_bodies () in
                    ({ schemes = fk_arg1; type_parameter_variables = fk_arg2; provisional = fk_arg3; viewed = fk_arg4; outside = fk_arg5; bodies = fk_arg6 } : known) in
                  ({ definitions = definitions; functions = fk_arg1; ordered_functions = []; extensions = fk_arg2; cases_by_name = fk_arg3; module_specs = fk_arg4; spec_types = fk_arg5; operations = fk_arg6; known = fk_arg7 } : environment) in
                let fk_arg2 = Collections.Maps.empty_map () in
                let fk_arg3 = context_default_value_parameters () in
                ({ environment = fk_arg1; place = place; type_parameters = fk_arg2; value_parameters = fk_arg3 } : context) in
              check_distinct (List.map (fun t -> ((t : Parser.spec_type).Parser.name, (t : Parser.spec_type).Parser.at)) types) context;
              check_distinct (List.map (fun v -> ((v : Parser.spec_value).Parser.name, (v : Parser.spec_value).Parser.at)) values) context;
              Option.iter (fun t -> match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((spec : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (t : Parser.spec_type).Parser.at; message = "'" ^ (t : Parser.spec_type).Parser.name ^ "' is a built-in type" } : Diagnostics.diagnostic)) with
                 | _ -> (assert false)) (List.find_opt (fun t -> Collections.Maps.map_contains_key Types.Types.builtins (t : Parser.spec_type).Parser.name) types);
              let parameter_variables = List.map (fun p -> (p, Effect.perform (Types.Solving_fresh ()))) type_parameters in
              let fk_arg1 = Collections.Maps.list_tuple_to_map (List.map (fun v -> let own = List.map (fun p -> (p, Effect.perform (Types.Solving_fresh ()))) (v : Parser.spec_value).Parser.type_parameters in
                    let rest = Effect.perform (Types.Solving_fresh ()) in
                    let effects = Annotations.Annotations.effects_of (v : Parser.spec_value).Parser.annotations place (v : Parser.spec_value).Parser.at (definitions : Definitions.definitions).Definitions.namespace in
                    let declared = if List.is_empty effects then Annotations.Annotations.effects_of ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations place ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at (definitions : Definitions.definitions).Definitions.namespace else effects in
                    let row = Types.Types.row_of declared (Some rest) in
                    let type_context = let fk_arg1 = Collections.Maps.list_tuple_to_map (List.map (fun (name, variable) -> (name, (Types.Variable { variable = variable } : Types.type_))) (parameter_variables @ own)) in
                      let fk_arg2 = Collections.Maps.list_tuple_to_map (List.map (fun t -> ((t : Parser.spec_type).Parser.name, List.length (t : Parser.spec_type).Parser.type_parameters)) types) in
                      let fk_arg3 = Definitions.type_context_default_outside_view () in
                      let fk_arg4 = Definitions.type_context_default_seen_from () in
                      let fk_arg5 = Definitions.type_context_default_value_parameters () in
                      let fk_arg6 = Definitions.type_context_default_later_parameters () in
                      ({ Definitions.place = place; type_parameters = fk_arg1; region = None; arrow_effects = None; expanding = []; spec_types = fk_arg2; outside_view = fk_arg3; seen_from = fk_arg4; value_parameters = fk_arg5; later_parameters = fk_arg6 } : Definitions.type_context) in
                    let result = Definitions.Conversion.type_of (v : Parser.spec_value).Parser.value_type type_context definitions in
                    let t = match (v : Parser.spec_value).Parser.parameters with
                      | Some ps -> check_distinct (List.map (fun p -> ((p : Parser.parameter).Parser.name, (p : Parser.parameter).Parser.at)) ps) context;
                          let with_row = let fk_arg1 = Definitions.type_context_default_outside_view () in
                            let fk_arg2 = Definitions.type_context_default_seen_from () in
                            let fk_arg3 = Definitions.type_context_default_value_parameters () in
                            let fk_arg4 = Definitions.type_context_default_later_parameters () in
                            ({ Definitions.place = (type_context : Definitions.type_context).Definitions.place; type_parameters = (type_context : Definitions.type_context).Definitions.type_parameters; region = None; arrow_effects = Some row; expanding = []; spec_types = (type_context : Definitions.type_context).Definitions.spec_types; outside_view = fk_arg1; seen_from = fk_arg2; value_parameters = fk_arg3; later_parameters = fk_arg4 } : Definitions.type_context) in
                          (Types.FunctionOf { parameters = List.map (fun p -> let fk_arg1 = Option.map (fun it -> Definitions.Conversion.type_of it with_row definitions) (p : Parser.parameter).Parser.parameter_type in
                             let fk_arg2 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
                             Option.value fk_arg1 ~default:fk_arg2) ps; result = result; effects = row } : Types.type_)
                      | None -> result in
                    ((v : Parser.spec_value).Parser.name, ({ Types.variables = (let fk_arg1 = List.map (fun (_, variable) -> variable) parameter_variables in
