              ({ values = fk_arg1; parameters = fk_arg2 } : spec_types)
          | _ -> ({ values = Collections.Maps.empty_map (); parameters = [] } : spec_types)

        let spec_values_of (spec : Symbols.symbol) : Parser.spec_value list =
          match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = _; values = values; type_parameters = _; copy_of = _; parents = _ } -> values
          | _ -> []

        let rec with_own_types_outside (t : Types.type_) (owner : string) (context : Definitions.type_context) (definitions : Definitions.definitions) : Types.type_ =
          match Types.Types.resolved t with
          | Types.SpecOwnType { name = name; arguments = arguments } -> Definitions.Conversion.outside_type owner name (List.map (fun it -> with_own_types_outside it owner context definitions) arguments) context definitions
          | Types.Named { name = n; arguments = arguments; region = region } -> (Types.Named { name = n; arguments = List.map (fun it -> with_own_types_outside it owner context definitions) arguments; region = region } : Types.type_)
          | Types.Abstract { name = n; arguments = arguments } -> (Types.Abstract { name = n; arguments = List.map (fun it -> with_own_types_outside it owner context definitions) arguments } : Types.type_)
          | Types.ModuleValue { spec = n; arguments = arguments; own_types = own } -> (Types.ModuleValue { spec = n; arguments = List.map (fun it -> with_own_types_outside it owner context definitions) arguments; own_types = own } : Types.type_)
          | Types.Handler { effect_ = n; arguments = arguments } -> (Types.Handler { effect_ = n; arguments = List.map (fun it -> with_own_types_outside it owner context definitions) arguments } : Types.type_)
          | Types.TupleOf { elements = elements } -> (Types.TupleOf { elements = List.map (fun it -> with_own_types_outside it owner context definitions) elements } : Types.type_)
          | Types.FunctionOf { parameters = parameters; result = result; effects = effects } -> let fk_arg1 = List.map (fun it -> with_own_types_outside it owner context definitions) parameters in
              let fk_arg2 = with_own_types_outside result owner context definitions in
              (Types.FunctionOf { parameters = fk_arg1; result = fk_arg2; effects = effects } : Types.type_)
          | other -> other

        let parameter_members_seen (definitions : Definitions.definitions) (spec_types : (string, spec_types) Collections.Maps.map) : (string, Types.scheme) Collections.Maps.map =
          let modules = ((definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.modules in
          Collections.Maps.list_tuple_to_map (Lang.Lists.list_map_not_null (modules : Resolution.modules).Resolution.parameter_members (fun member -> let owner = String.concat "." (List.map Fun.id (Symbols.Symbols.path_of member)) in
              Option.bind (Collections.Maps.map_get (((definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.functions member) (fun f -> let wanted = Option.bind (Option.bind (Collections.Maps.map_get (modules : Resolution.modules).Resolution.specs owner) (fun spec -> Collections.Maps.map_get spec_types (spec : Symbols.symbol).Symbols.name)) (fun types -> Collections.Maps.map_get (types : spec_types).values ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.name) in
                 Option.map (fun scheme -> let context = let fk_arg1 = Collections.Maps.empty_map () in
                      let fk_arg2 = Definitions.type_context_default_region () in
                      let fk_arg3 = Definitions.type_context_default_arrow_effects () in
                      let fk_arg4 = Definitions.type_context_default_expanding () in
                      let fk_arg5 = Definitions.type_context_default_spec_types () in
                      let fk_arg6 = Definitions.type_context_default_outside_view () in
                      let fk_arg7 = Definitions.type_context_default_seen_from () in
                      let fk_arg8 = Definitions.type_context_default_value_parameters () in
                      let fk_arg9 = Definitions.type_context_default_later_parameters () in
                      ({ Definitions.place = ({ Resolution.file = (f : Symbols.symbol).Symbols.file; path = (f : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; region = fk_arg2; arrow_effects = fk_arg3; expanding = fk_arg4; spec_types = fk_arg5; outside_view = fk_arg6; seen_from = fk_arg7; value_parameters = fk_arg8; later_parameters = fk_arg9 } : Definitions.type_context) in
                    (member, ({ Types.variables = (scheme : Types.scheme).Types.variables; template = with_own_types_outside (scheme : Types.scheme).Types.template owner context definitions } : Types.scheme))) wanted)))

        let of_ (definitions : Definitions.definitions) : environment =
          let table = ((definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table in
          let ordered = List.concat_map (fun d -> let fk_arg1 = if Symbols.Symbols.is_function d then [d] else [] in
