            List.fold_left (fun m f -> let method_ = Symbols.Signatures.method_name f in
               Collections.Maps.map_put m method_ (Collections.Maps.map_get_or_default m method_ [] @ [f])) fk_arg2 fk_arg1 in
          let cases_by_name = let fk_arg1 = List.concat_map (fun owner -> List.map (fun c -> ({ Symbols.name = (owner : Symbols.symbol).Symbols.name ^ "." ^ (c : Parser.case_definition).Parser.name; owner = owner; definition = c } : Symbols.case_symbol)) (Symbols.Symbols.cases_of owner)) (List.filter (fun it -> Symbols.Symbols.is_case_type it) (table : Symbols.symbol_table).Symbols.declarations) in
            let fk_arg2 = Collections.Maps.empty_map () in
            List.fold_left (fun m c -> Collections.Maps.map_put m ((c : Symbols.case_symbol).Symbols.definition : Parser.case_definition).Parser.name (Collections.Maps.map_get_or_default m ((c : Symbols.case_symbol).Symbols.definition : Parser.case_definition).Parser.name [] @ [c])) fk_arg2 fk_arg1 in
          let module_specs = (((definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.modules : Resolution.modules).Resolution.specs in
          let specs = List.filter (fun it -> Symbols.Symbols.is_spec it) (table : Symbols.symbol_table).Symbols.declarations in
          let spec_types = Collections.Maps.list_tuple_to_map (List.map (fun s -> ((s : Symbols.symbol).Symbols.name, spec_types_of s definitions)) specs) in
          let operations = let fk_arg1 = List.concat_map (fun s -> List.map (fun v -> (String.concat "." (List.map Fun.id ((s : Symbols.symbol).Symbols.path @ [(v : Parser.spec_value).Parser.name])), ({ effect_ = s; value = v } : operation))) (spec_values_of s)) (List.filter (fun s -> Annotations.Annotations.is_effect s (definitions : Definitions.definitions).Definitions.namespace) specs) in
