          let outside = parameter_members_seen definitions spec_types in
          ({ definitions = definitions; functions = functions; ordered_functions = ordered; extensions = extensions; cases_by_name = cases_by_name; module_specs = module_specs; spec_types = spec_types; operations = operations; known = (let fk_arg1 = Collections.Maps.empty_map () in
           let fk_arg2 = Collections.Maps.empty_map () in
           let fk_arg3 = Collections.Maps.empty_map () in
           let fk_arg4 = Collections.Maps.empty_map () in
           let fk_arg5 = known_default_bodies () in
           ({ schemes = fk_arg1; type_parameter_variables = fk_arg2; provisional = fk_arg3; viewed = fk_arg4; outside = outside; bodies = fk_arg5 } : known)) } : environment)
      end

      let spec_type_names (spec : Symbols.symbol) : string list =
        match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.SpecDefinition { types = types; values = _; type_parameters = _; copy_of = _; parents = _ } -> List.map (fun it -> (it : Parser.spec_type).Parser.name) types
        | _ -> []

      let spec_own_types (spec : Symbols.symbol) : Parser.spec_type list =
        match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.SpecDefinition { types = types; values = _; type_parameters = _; copy_of = _; parents = _ } -> types
        | _ -> []

      let type_named (full : string) (table : Symbols.symbol_table) : Symbols.symbol option =
        Lang.Options.option_or_else (Lang.Options.option_or_else (Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.records full) (fun () -> Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.case_types full)) (fun () -> Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.aliases full)

      let spec_values (spec : Symbols.symbol) : Parser.spec_value list =
        match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.SpecDefinition { types = _; values = values; type_parameters = _; copy_of = _; parents = _ } -> values
        | _ -> []

      let check_defines (declared : Symbols.symbol) (spec : Symbols.symbol) (environment : environment) : unit =
        let table = (((environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table in
        let own = Symbols.Symbols.simple_name declared in
        let spec_name = Symbols.Symbols.simple_name spec in
        List.iter (fun type_name -> let t = List.find_opt (fun it -> (it : Parser.spec_type).Parser.name = type_name) (spec_own_types spec) in
           let wanted_parameters = Option.value (Option.map (fun it -> List.length (it : Parser.spec_type).Parser.type_parameters) t) ~default:0 in
           match type_named ((declared : Symbols.symbol).Symbols.name ^ "." ^ type_name) table with
           | None -> (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((declared : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((declared : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = own ^ " doesn't define type " ^ type_name ^ ", which its spec " ^ spec_name ^ " needs" } : Diagnostics.diagnostic)) with
                | _ -> (assert false))
           | Some d -> if ((d : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.visibility = (Parser.Private : Parser.visibility) then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((d : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((d : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = type_name ^ " is in " ^ own ^ "'s spec " ^ spec_name ^ ", so it can't be private" } : Diagnostics.diagnostic)) with
                  | _ -> (assert false)) else ();
               let n = List.length (Definitions.Conversion.type_parameters_of d) in
               if n <> wanted_parameters then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((d : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((d : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = spec_name ^ " says " ^ type_name ^ " takes " ^ string_of_int wanted_parameters ^ " type parameter" ^ (if wanted_parameters = 1 then "" else "s") ^ ", not " ^ string_of_int n } : Diagnostics.diagnostic)) with
                  | _ -> (assert false)) else ()) (spec_type_names spec);
        List.iter (fun v -> match Collections.Maps.map_get (environment : environment).functions ((declared : Symbols.symbol).Symbols.name ^ "." ^ (v : Parser.spec_value).Parser.name) with
           | None -> (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((declared : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((declared : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = own ^ " doesn't define '" ^ (v : Parser.spec_value).Parser.name ^ "', which its spec " ^ spec_name ^ " needs" } : Diagnostics.diagnostic)) with
                | _ -> (assert false))
           | Some f -> if ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.visibility = (Parser.Private : Parser.visibility) then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((f : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = "'" ^ (v : Parser.spec_value).Parser.name ^ "' is in " ^ own ^ "'s spec " ^ spec_name ^ ", so it can't be private" } : Diagnostics.diagnostic)) with
                  | _ -> (assert false)) else ()) (spec_values spec)

      let check_modules_define (environment : environment) : unit =
        let table = (((environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table in
        List.iter (fun (name, spec) -> match Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.modules name with
           | Some (Symbols.DeclaredModule { symbol = declared }) -> check_defines declared spec environment
           | _ -> ()) (Collections.Maps.map_to_list (environment : environment).module_specs)

      let functor_parameters (functor_ : Symbols.symbol) : Parser.module_parameter list =
        match ((functor_ : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.ModuleDefinition { declarations = _; spec = _; parameters = parameters; application = _; type_parameters = _ } -> parameters
        | _ -> []

      let rec builds_on (spec : Symbols.symbol) (other : Symbols.symbol) (namespace : Resolution.namespace) (seen : string list) : bool =
        match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.SpecDefinition { types = _; values = _; type_parameters = _; copy_of = _; parents = parents } when not (List.mem (spec : Symbols.symbol).Symbols.name seen) -> List.exists (fun ref -> match ref with
               | Parser.NamedType { at = _; name = name; arguments = _ } -> (match Resolution.Lookups.found (Resolution.Lookups.spec name ({ Resolution.file = (spec : Symbols.symbol).Symbols.file; path = (spec : Symbols.symbol).Symbols.path } : Resolution.place) namespace (Resolution.Skipping : Resolution.strictness)) with
                    | Some parent -> (parent : Symbols.symbol).Symbols.name = (other : Symbols.symbol).Symbols.name || builds_on parent other namespace (seen @ [(spec : Symbols.symbol).Symbols.name])
                    | None -> false)
               | _ -> false) parents
        | _ -> false

      let check_arguments_of (app : Symbols.symbol) (application : Resolution.made) (environment : environment) : unit =
        let definitions = (environment : environment).definitions in
        let namespace = (definitions : Definitions.definitions).Definitions.namespace in
        let functor_name = Symbols.Symbols.simple_name (application : Resolution.made).Resolution.functor_ in
        let context = let fk_arg1 = Collections.Maps.empty_map () in
          let fk_arg2 = Definitions.type_context_default_region () in
          let fk_arg3 = Definitions.type_context_default_arrow_effects () in
          let fk_arg4 = Definitions.type_context_default_expanding () in
          let fk_arg5 = Definitions.type_context_default_spec_types () in
          let fk_arg6 = Definitions.type_context_default_outside_view () in
          let fk_arg7 = Definitions.type_context_default_seen_from () in
          let fk_arg8 = Definitions.type_context_default_value_parameters () in
          let fk_arg9 = Definitions.type_context_default_later_parameters () in
          ({ Definitions.place = ({ Resolution.file = (app : Symbols.symbol).Symbols.file; path = (app : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; region = fk_arg2; arrow_effects = fk_arg3; expanding = fk_arg4; spec_types = fk_arg5; outside_view = fk_arg6; seen_from = fk_arg7; value_parameters = fk_arg8; later_parameters = fk_arg9 } : Definitions.type_context) in
