             if not (Collections.Maps.map_contains_key (search : _ search).indices kw) then (visit search w places key edges;
                lower search k (lowest_of search kw)) else if Collections.Maps.map_contains_key (search : _ search).stacked kw then lower search k (index_of search kw) else ()) (edges v);
