        None

      let signature_of (f : Symbols.symbol) (environment : environment) : signature =
        let declared = List.map (fun p -> (p, Effect.perform (Types.Solving_fresh ()))) (Symbols.Signatures.type_parameters_of f) in
        let context = context_of f declared environment (context_of_default_value_parameters ()) in
        let row = ({ Types.labels = []; rest = Some (Effect.perform (Types.Solving_fresh ())) } : Types.row) in
        let parameters = Option.value (Symbols.Signatures.parameters_of f) ~default:[] in
        Option.iter (fun ps -> check_distinct (List.map (fun p -> ((p : Parser.parameter).Parser.name, (p : Parser.parameter).Parser.at)) ps) context) (Symbols.Signatures.parameters_of f);
        let parameter_types = types_of parameters [] row context environment in
        let value_parameters = named parameters parameter_types in
        let result = let fk_arg1 = Option.map (fun t -> Definitions.Conversion.type_of t (let fk_named3 = Definitions.type_context_default_region () in
                let fk_named4 = Definitions.type_context_default_arrow_effects () in
                let fk_named5 = Definitions.type_context_default_expanding () in
                let fk_named6 = Definitions.type_context_default_spec_types () in
                let fk_named7 = Definitions.type_context_default_outside_view () in
                let fk_named8 = Definitions.type_context_default_seen_from () in
                let fk_named10 = Definitions.type_context_default_later_parameters () in
                ({ Definitions.place = (context : context).place; type_parameters = (context : context).type_parameters; region = fk_named3; arrow_effects = fk_named4; expanding = fk_named5; spec_types = fk_named6; outside_view = fk_named7; seen_from = fk_named8; value_parameters = value_parameters; later_parameters = fk_named10 } : Definitions.type_context)) (environment : environment).definitions) (Symbols.Signatures.result_of f) in
          let fk_arg2 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
          Option.value fk_arg1 ~default:fk_arg2 in
        let type_variables = declared @ List.concat_map (fun (p, t) -> open_types_of p t context environment) (Lang.Lists.list_zip parameters parameter_types) in
        let t = match Symbols.Signatures.parameters_of f with
          | Some _ -> (Types.FunctionOf { parameters = parameter_types; result = result; effects = row } : Types.type_)
          | None -> result in
        let outside = if not (Definitions.Conversion.is_opaque_around (f : Symbols.symbol).Symbols.path (environment : environment).definitions) then None else (let outside_context = let fk_named6 = Collections.Maps.empty_map () in
               let fk_named8 = Definitions.type_context_default_seen_from () in
               let fk_named10 = Definitions.type_context_default_later_parameters () in
               ({ Definitions.place = (context : context).place; type_parameters = (context : context).type_parameters; region = None; arrow_effects = None; expanding = []; spec_types = fk_named6; outside_view = true; seen_from = fk_named8; value_parameters = value_parameters; later_parameters = fk_named10 } : Definitions.type_context) in
             let shown_result = Option.value (Option.map (fun r -> Definitions.Conversion.type_of r outside_context (environment : environment).definitions) (Symbols.Signatures.result_of f)) ~default:result in
             Some (match (t, Symbols.Signatures.parameters_of f) with
              | (Types.FunctionOf { parameters = insides; result = _; effects = _ }, Some ps) -> (Types.FunctionOf { parameters = List.mapi (fun i entry -> let (p, inside) = entry in
                     match (p : Parser.parameter).Parser.parameter_type with
                     | Some written when not (is_spec_value written context environment) -> Definitions.Conversion.type_of written (let fk_named6 = Collections.Maps.empty_map () in
                          let fk_named9 = named (List.take i ps) insides in
                          let fk_named8 = Definitions.type_context_default_seen_from () in
                          let fk_named10 = Definitions.type_context_default_later_parameters () in
                          ({ Definitions.place = (context : context).place; type_parameters = (context : context).type_parameters; region = None; arrow_effects = Some row; expanding = []; spec_types = fk_named6; outside_view = true; seen_from = fk_named8; value_parameters = fk_named9; later_parameters = fk_named10 } : Definitions.type_context)) (environment : environment).definitions
                     | _ -> inside) (Lang.Lists.list_zip ps insides); result = shown_result; effects = row } : Types.type_)
              | _ -> shown_result)) in
        ({ function_ = f; type_variables = type_variables; row = row; t = t; outside = outside } : signature)

      let spec_effects (spec : Symbols.symbol) (value : Parser.spec_value) (context : context) : string list =
        let namespace = (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace in
        let place = Annotations.Annotations.place_of spec in
        let own = Annotations.Annotations.effects_of (value : Parser.spec_value).Parser.annotations place (value : Parser.spec_value).Parser.at namespace in
        if List.is_empty own then Annotations.Annotations.effects_of ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations place ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at namespace else own

      let parameter_effects (path : string list) (environment : environment) : string list =
        let namespace = ((environment : environment).definitions : Definitions.definitions).Definitions.namespace in
        let functor_ = List.nth_opt (Lang.Lists.list_map_not_null (List.mapi (fun i _ -> String.concat "." (List.map Fun.id (List.take (i + 1) path))) path) (fun name -> match Collections.Maps.map_get ((namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.modules name with
              | Some (Symbols.DeclaredModule { symbol = m }) when Lang.Lists.list_is_not_empty (functor_parameters m) -> Some m
              | _ -> None)) 0 in
        Option.value (Option.map (fun m -> let context = let fk_arg1 = Collections.Maps.empty_map () in
              let fk_arg2 = context_default_value_parameters () in
              ({ environment = environment; place = ({ Resolution.file = (m : Symbols.symbol).Symbols.file; path = (m : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; value_parameters = fk_arg2 } : context) in
            Lang.Lists.list_distinct (List.concat_map (fun p -> Option.value (Option.map (fun spec -> List.concat_map (fun v -> spec_effects spec v context) (spec_values spec)) (Collections.Maps.map_get ((namespace : Resolution.namespace).Resolution.modules : Resolution.modules).Resolution.specs ((m : Symbols.symbol).Symbols.name ^ "." ^ (p : Parser.module_parameter).Parser.name))) ~default:[]) (functor_parameters m))) functor_) ~default:[]

      let is_seen_as_declared (f : Symbols.symbol) (environment : environment) : bool =
        let namespace = ((environment : environment).definitions : Definitions.definitions).Definitions.namespace in
        let generic = List.exists (fun a -> Lang.Lists.list_is_not_empty (a : Parser.annotation).Parser.type_arguments && Option.value (Option.map (fun it -> Symbols.Symbols.is_spec it) (Annotations.Annotations.declaration_of a ({ Resolution.file = (f : Symbols.symbol).Symbols.file; path = (f : Symbols.symbol).Symbols.path } : Resolution.place) namespace)) ~default:false) ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations in
        (((((((f : Symbols.symbol).Symbols.name <> "main" && not (Defaults.is_default f)) && not (Symbols.Signatures.is_external f)) && not (Symbols.Signatures.is_compiled f)) && Option.is_none (Resolution.Names.enclosing_application (f : Symbols.symbol).Symbols.path namespace)) && List.is_empty (parameter_effects (f : Symbols.symbol).Symbols.path environment)) && Lang.Lists.list_none (Symbols.Signatures.type_parameters_of f) (fun it -> String.starts_with ~prefix:"@" it)) && not generic

      let ceiling (path : string list) (environment : environment) : (Symbols.symbol * string list) option =
        let namespace = ((environment : environment).definitions : Definitions.definitions).Definitions.namespace in
        List.nth_opt (Lang.Lists.list_map_not_null (List.mapi (fun i _ -> List.take (List.length path - i) path) path) (fun p -> let name = String.concat "." (List.map Fun.id p) in
            let around = Lang.Options.option_or_else (Option.map (fun made -> (Symbols.DeclaredModule { symbol = (made : Resolution.made).Resolution.functor_ } : Symbols.module_symbol)) (Collections.Maps.map_get ((namespace : Resolution.namespace).Resolution.modules : Resolution.modules).Resolution.applications name)) (fun () -> Collections.Maps.map_get ((namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.modules name) in
            match around with
            | Some (Symbols.DeclaredModule { symbol = m }) -> let effects = Annotations.Annotations.effects_of ((m : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations ({ Resolution.file = (m : Symbols.symbol).Symbols.file; path = (m : Symbols.symbol).Symbols.path } : Resolution.place) ((m : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at namespace in
                if List.is_empty effects then None else Some (m, effects)
            | _ -> None)) 0

      module Doings = struct
        let shown (names : string list) : string =
          String.concat " " (List.map Fun.id (List.map (fun it -> "@" ^ Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) it ".")) ~default:it) (Lang.Lists.list_sorted (Lang.Lists.list_distinct names))))

        let perform_in (performed : Types.row) (effects : Types.row) (at : Parser.position) (file : string option) : unit =
          let flat = Types.Types.flattened performed in
          let own = (Types.Types.flattened effects : Types.row).Types.rest in
          let open_ = if Option.is_none (flat : Types.row).Types.rest || (flat : Types.row).Types.rest = own then ({ Types.labels = (flat : Types.row).Types.labels; rest = Some (Effect.perform (Types.Solving_fresh ())) } : Types.row) else performed in
          if not (Types.Unification.unify_rows open_ effects) then (let allowed = Types.Types.effect_names effects in
             let extra = Lang.Lists.list_distinct (List.filter (fun it -> not (List.mem it allowed)) (List.map (fun it -> (it : Types.effect_label).Types.name) (flat : Types.row).Types.labels)) in
             let can = if List.is_empty allowed then "says it's pure" else "says it can only do " ^ shown allowed in
             match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = file; at = at; message = "this does " ^ shown extra ^ ", but the type of the function it's in " ^ can } : Diagnostics.diagnostic)) with
             | _ -> (assert false)) else ()

        let include_ (row : Types.row) (rests : (Types.type_variable * Parser.position) list) (file : string option) : unit =
          List.iter (fun entry -> let (v, at) = entry in
             let theirs = Types.Types.flattened ({ Types.labels = []; rest = Some v } : Types.row) in
             if Lang.Lists.list_is_not_empty (theirs : Types.row).Types.labels then perform_in ({ Types.labels = (theirs : Types.row).Types.labels; rest = None } : Types.row) row at file else ();
             let own = (Types.Types.flattened row : Types.row).Types.rest in
             match ((theirs : Types.row).Types.rest, own) with
             | (None, _) -> ()
             | (Some rest, Some mine) when rest = mine -> ()
             | (Some rest, None) -> if not (Types.Unification.unify_rows ({ Types.labels = []; rest = Some rest } : Types.row) row) then perform_in ({ Types.labels = []; rest = Some rest } : Types.row) row at file else ()
             | (Some rest, Some mine) -> Types.Unification.unify (Types.Variable { variable = mine } : Types.type_) (Types.Variable { variable = rest } : Types.type_);
                 ()) rests

        let doing (row : Types.row) (file : string option) (block : unit -> _) : _ =
          let included = ref [] in
          let result = handle_doing ({ perform = (fun x0 x1 k -> k ((fun performed at -> let flat = Types.Types.flattened performed in
                   let own = (Types.Types.flattened row : Types.row).Types.rest in
                   match (flat : Types.row).Types.rest with
                   | Some rest when Some rest <> own -> included := ! included @ [(rest, at)];
                       perform_in ({ Types.labels = (flat : Types.row).Types.labels; rest = None } : Types.row) row at file
                   | _ -> perform_in performed row at file) x0 x1)) } : _ doing_handler) (fun () -> block ()) in
          include_ row (! included) file;
          result
      end

      let allows (effects : string list) : string =
        let doing = List.filter (fun it -> it <> "fckt.lang.Pure") effects in
        if List.is_empty doing then "be pure" else "do " ^ Doings.shown doing

      let allowed (f : Symbols.symbol) (environment : environment) : string list =
        let namespace = ((environment : environment).definitions : Definitions.definitions).Definitions.namespace in
        let own = Annotations.Annotations.effects_of ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations ({ Resolution.file = (f : Symbols.symbol).Symbols.file; path = (f : Symbols.symbol).Symbols.path } : Resolution.place) ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at namespace in
        match ceiling (f : Symbols.symbol).Symbols.path environment with
        | None -> own
        | Some (m, effects) -> let beyond = List.filter (fun it -> not (List.mem it effects)) own in
            if Lang.Lists.list_is_not_empty beyond then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((f : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = (let fk_arg1 = Symbols.Symbols.simple_name f in
                 let fk_arg2 = Symbols.Symbols.simple_name m in
                 let fk_arg3 = allows effects in
                 let fk_arg4 = Doings.shown beyond in
                 "'" ^ fk_arg1 ^ "' is in " ^ fk_arg2 ^ ", which may only " ^ fk_arg3 ^ ", so it can't be " ^ fk_arg4) } : Diagnostics.diagnostic)) with
               | _ -> (assert false)) else effects

      let row_regions (row : Types.row) (skip : Types.row option) : Types.type_ list =
        let own = Option.value (Option.map (fun s -> (Types.Types.flattened s : Types.row).Types.labels) skip) ~default:[] in
        Lang.Lists.list_map_not_null (List.filter (fun label -> Lang.Lists.list_none own (fun it -> Types.Types.same_effect it label)) (Types.Types.flattened row : Types.row).Types.labels) (fun label -> Option.map (fun it -> Types.Types.resolved it) (List.nth_opt (label : Types.effect_label).Types.arguments 0))

      let rec regions_into (t : Types.type_) (skip : Types.row option) (found : Types.type_ list) : Types.type_ list =
        match Types.Types.resolved t with
        | Types.Named { name = _; arguments = arguments; region = region } -> List.fold_left (fun acc a -> regions_into a skip acc) (found @ Option.value (Option.map (fun r -> [Types.Types.resolved r]) region) ~default:[]) arguments
        | Types.Effects { row = row } -> found @ row_regions row skip
        | Types.FunctionOf { parameters = parameters; result = result; effects = effects } -> let inside = regions_into result skip (List.fold_left (fun acc p -> regions_into p skip acc) found parameters) in
            if Option.value (Option.map (fun own -> let fk_arg1 = Types.Types.flattened own in
                let fk_arg2 = Types.Types.flattened effects in
                fk_arg1 = fk_arg2) skip) ~default:false then inside else inside @ row_regions effects skip
        | Types.Abstract { name = _; arguments = arguments } -> List.fold_left (fun acc a -> regions_into a skip acc) found arguments
        | Types.SpecOwnType { name = _; arguments = arguments } -> List.fold_left (fun acc a -> regions_into a skip acc) found arguments
        | Types.ModuleValue { spec = _; arguments = arguments; own_types = _ } -> List.fold_left (fun acc a -> regions_into a skip acc) found arguments
        | Types.Handler { effect_ = _; arguments = arguments } -> List.fold_left (fun acc a -> regions_into a skip acc) found arguments
        | Types.TupleOf { elements = elements } -> List.fold_left (fun acc e -> regions_into e skip acc) found elements
        | _ -> found

      let regions_in (t : Types.type_) (skip : Types.row option) : Types.type_ list =
        Lang.Lists.list_distinct (regions_into t skip [])

      let declared_row (f : Symbols.symbol) (parameters : Types.type_ list) (environment : environment) : Types.row =
        let declared = allowed f environment in
        let regions = Lang.Lists.list_distinct (List.filter (fun r -> match r with
              | Types.Variable { variable = _ } -> true
              | _ -> false) (List.concat_map (fun p -> regions_in p None) parameters)) in
        let changes = if List.mem Types.Types.mutating declared && Lang.Lists.list_is_not_empty regions then List.map (fun r -> ({ Types.name = Types.Types.mutating; arguments = [r] } : Types.effect_label)) regions else [] in
        let labels = List.map (fun d -> ({ Types.name = d; arguments = [] } : Types.effect_label)) (List.filter (fun d -> d <> Types.Types.mutating || List.is_empty changes) declared) @ changes in
        ({ Types.labels = labels; rest = Some (Effect.perform (Types.Solving_fresh ())) } : Types.row)

      let viewed_as (s : signature) (environment : environment) : Types.type_ option =
        match (s : signature).t with
        | Types.FunctionOf { parameters = parameters; result = result; effects = _ } when is_seen_as_declared (s : signature).function_ environment -> let row = ({ Types.labels = []; rest = Some (Effect.perform (Types.Solving_fresh ())) } : Types.row) in
            Types.Unification.unify_rows row (declared_row (s : signature).function_ parameters environment);
            Some (Types.FunctionOf { parameters = parameters; result = result; effects = row } : Types.type_)
        | _ -> None

      let doing_in (row : Types.row) (context : context) (block : unit -> _) : _ =
        Doings.doing row ((((context : context).place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path block

      module Scopes = struct
        let empty =
          ({ own = Collections.Maps.empty_map (); outer = None } : scope)

        let bind (scope : scope) (name : string) (local : local) : scope =
          ({ own = Collections.Maps.map_put (scope : scope).own name local; outer = (scope : scope).outer } : scope)

        let rec lookup (scope : scope) (name : string) : local option =
          match Collections.Maps.map_get (scope : scope).own name with
          | Some local -> Some local
          | None -> Option.bind (scope : scope).outer (fun it -> lookup it name)

        let inside (outer : scope) : scope =
          ({ own = Collections.Maps.empty_map (); outer = Some outer } : scope)

        let binds_here (scope : scope) (name : string) : bool =
          Collections.Maps.map_contains_key (scope : scope).own name

        let bind_all (scope : scope) (bindings : (string * local) list) : scope =
          List.fold_left (fun s binding -> let (name, local) = binding in
             bind s name local) scope bindings
      end

      let local_default_region () : Types.type_ option =
        None

      let local_default_narrowed () : narrowing option =
        None

      let local_default_hides () : bool =
        false

      let typed_default_spelled () : Symbols.case_symbol option =
        None

      let typed_default_core () : Core.core =
        (Core.Pending { what = "an expression" } : Core.core)

      let rec with_own_types (t : Types.type_) (names : string list) (given : Types.type_ list) : Types.type_ =
        match Types.Types.resolved t with
        | Types.SpecOwnType { name = name; arguments = _ } -> Option.value (Lang.Lists.list_get_or_none given (Lang.Lists.list_index_of names name)) ~default:t
        | Types.Named { name = n; arguments = arguments; region = region } -> (Types.Named { name = n; arguments = List.map (fun it -> with_own_types it names given) arguments; region = region } : Types.type_)
        | Types.Abstract { name = n; arguments = arguments } -> (Types.Abstract { name = n; arguments = List.map (fun it -> with_own_types it names given) arguments } : Types.type_)
        | Types.ModuleValue { spec = n; arguments = arguments; own_types = own } -> (Types.ModuleValue { spec = n; arguments = List.map (fun it -> with_own_types it names given) arguments; own_types = own } : Types.type_)
        | Types.Handler { effect_ = n; arguments = arguments } -> (Types.Handler { effect_ = n; arguments = List.map (fun it -> with_own_types it names given) arguments } : Types.type_)
        | Types.TupleOf { elements = elements } -> (Types.TupleOf { elements = List.map (fun it -> with_own_types it names given) elements } : Types.type_)
        | Types.FunctionOf { parameters = parameters; result = result; effects = effects } -> let fk_arg1 = List.map (fun it -> with_own_types it names given) parameters in
            let fk_arg2 = with_own_types result names given in
            (Types.FunctionOf { parameters = fk_arg1; result = fk_arg2; effects = effects } : Types.type_)
        | other -> other

      let module_value_member (spec_name : string) (arguments : Types.type_ list) (name : string) (context : context) : field_reference option =
        Option.bind (Collections.Maps.map_get (((((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.specs spec_name) (fun spec -> Option.bind (List.find_opt (fun it -> (it : Parser.spec_value).Parser.name = name) (spec_values spec)) (fun value -> Option.map (fun scheme -> let names = spec_type_names spec in
                 (ModuleMember { spec = spec; value = value; t = with_own_types (Types.Types.instantiate scheme (Types.Types.instantiate_default_given ())) names arguments } : field_reference)) (Option.bind (Collections.Maps.map_get ((context : context).environment : environment).spec_types (spec : Symbols.symbol).Symbols.name) (fun types -> Collections.Maps.map_get (types : spec_types).values (value : Parser.spec_value).Parser.name))))

      let record_fields_of (record : Symbols.symbol) : Parser.field list =
        match ((record : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.RecordDefinition { type_parameters = _; fields = fields; private_constructor = _; annotation = _; external_ = _ } -> fields
        | _ -> []

      let rec shown_variables (t : Types.type_) (found : Types.type_variable list) : Types.type_variable list =
        match Types.Types.resolved t with
        | Types.Variable { variable = v } -> if List.mem v found then found else found @ [v]
        | Types.Named { name = _; arguments = arguments; region = _ } -> List.fold_left (fun acc a -> shown_variables a acc) found arguments
        | Types.Abstract { name = _; arguments = arguments } -> List.fold_left (fun acc a -> shown_variables a acc) found arguments
        | Types.SpecOwnType { name = _; arguments = arguments } -> List.fold_left (fun acc a -> shown_variables a acc) found arguments
        | Types.ModuleValue { spec = _; arguments = arguments; own_types = _ } -> List.fold_left (fun acc a -> shown_variables a acc) found arguments
        | Types.Handler { effect_ = _; arguments = arguments } -> List.fold_left (fun acc a -> shown_variables a acc) found arguments
        | Types.TupleOf { elements = elements } -> List.fold_left (fun acc e -> shown_variables e acc) found elements
        | Types.FunctionOf { parameters = parameters; result = result; effects = _ } -> shown_variables result (List.fold_left (fun acc p -> shown_variables p acc) found parameters)
        | _ -> found

      let generic_text (t : Types.type_) : string =
        let letters = Collections.Maps.list_tuple_to_map (List.mapi (fun i v -> (v, (Types.TypeParameter { name = fk_show_char ((fun n -> Uchar.to_int (Uchar.of_int n)) (65 + i)) } : Types.type_))) (shown_variables t [])) in
        Types.TypeText.shown (Types.Types.substitute t letters)

      let extension_for (at : Parser.position) (name : string) (receiver : Types.type_) (context : context) : Symbols.symbol option =
        let candidates = Globals.extensions_named name context in
        if List.is_empty candidates then None else (match Types.Types.resolved receiver with
           | Types.Variable { variable = _ } -> None
           | _ -> let fitting = Lang.Lists.list_map_not_null candidates (fun s -> Option.map (fun n -> (s, n)) (Globals.fit (Globals.receiver_type s context) receiver)) in
               match Lang.Lists.list_max_or_none (List.map (fun (_, n) -> n) fitting) with
               | None -> None
               | Some best -> let tied = List.filter (fun (_, n) -> n = best) fitting in
                   let own = List.filter (fun (s, _) -> (((s : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.project <> (Sources.CoreProject : Sources.project)) tied in
                   let chosen = if List.is_empty own then tied else own in
                   match chosen with
                   | [(s, _)] -> Some s
                   | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ((let fk_arg1 = "can't tell which '" ^ name ^ "' this is: " ^ generic_text receiver ^ " fits " in
                           let fk_arg2 = String.concat " and " (List.map Fun.id (List.map (fun (s, _) -> generic_text (Globals.receiver_type s context) ^ "." ^ name) chosen)) in
                           fk_arg1 ^ fk_arg2) ^ "; annotate its type"))) with
                       | _ -> (assert false))

      let opaque (s : Symbols.symbol) (at : Parser.position) (context : context) : Diagnostics.diagnostic =
        let owner = String.concat "." (List.map Fun.id (s : Symbols.symbol).Symbols.path) in
        Globals.problem context at (Symbols.Symbols.simple_name s ^ " is opaque outside " ^ owner ^ ": only " ^ owner ^ " can build one or look into it")

      let field_of (at : Parser.position) (target : Parser.expression) (name : string) (receiver : Types.type_) (scope : scope) (context : context) : field_reference option =
        let narrowed = match target with
          | Parser.Name { at = _; name = local } -> Option.bind (Option.bind (Scopes.lookup scope local) (fun it -> (it : local).narrowed)) (fun n -> Option.map (fun t -> (NarrowedField { narrowing = n; t = t } : field_reference)) (Collections.Maps.map_get (n : narrowing).types name))
          | _ -> None in
        match narrowed with
        | Some field -> Some field
        | None -> match Types.Types.resolved receiver with
            | Types.ModuleValue { spec = spec; arguments = arguments; own_types = _ } -> module_value_member spec arguments name context
