      let is_case (info : Definitions.case_info) (c : Symbols.case_symbol) : bool =
        ((info : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name = ((c : Symbols.case_symbol).Symbols.owner : Symbols.symbol).Symbols.name && ((info : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name = ((c : Symbols.case_symbol).Symbols.definition : Parser.case_definition).Parser.name

      let takes_on_case (typed : typed) (expected : Types.type_) (context : context) : bool =
        match ((typed : typed).spelled, Types.Types.resolved expected) with
        | (Some c, Types.Named { name = name; arguments = arguments; region = region }) -> (match case_type_named name context with
             | Some target when case_type_of (typed : typed).t context <> Some name -> List.exists (fun (info, _) -> is_case info c) (Definitions.Conversion.cases_with_fields target arguments region ((context : context).environment : environment).definitions (Some (context : context).place))
             | _ -> false)
        | _ -> false

      let covariant =
        ["List"; "Option"; "Lazy"; "Result"]

      let is_case_subset (x : Types.type_) (y : Types.type_) (context : context) : bool =
        match (x, y) with
        | (Types.Named { name = n; arguments = xs; region = x_region }, Types.Named { name = m; arguments = ys; region = y_region }) -> (let same_region = match (x_region, y_region) with
               | (Some p, Some q) -> Types.Unification.unify p q
               | _ -> true in
             let definitions = ((context : context).environment : environment).definitions in
             match let fk_arg1 = case_type_named n context in
             let fk_arg2 = case_type_named m context in
             (fk_arg1, fk_arg2) with
             | (Some x_type, Some y_type) when same_region -> let theirs = Definitions.Conversion.cases_with_fields y_type ys y_region definitions (Some (context : context).place) in
                 List.for_all (fun entry -> let (c, types) = entry in
                    match List.find_opt (fun (other, _) -> Definitions.Cases.same other c) theirs with
                    | Some (_, their_types) -> List.for_all (fun (a, b) -> Types.Unification.unify a b) (Lang.Lists.list_zip types their_types)
                    | None -> false) (Definitions.Conversion.cases_with_fields x_type xs x_region definitions (Some (context : context).place))
             | _ -> false)
        | _ -> false

      let rec is_subtype (sub : Types.type_) (sup : Types.type_) (context : context) : bool =
        match let fk_arg1 = Types.Types.resolved sub in
        let fk_arg2 = Types.Types.resolved sup in
        (fk_arg1, fk_arg2) with
        | (Types.Variable { variable = _ }, y) -> Types.Unification.unify sub y
        | (x, Types.Variable { variable = _ }) -> Types.Unification.unify x sup
        | (Types.Named { name = n; arguments = xs; region = _ }, Types.Named { name = m; arguments = ys; region = _ }) when n = m && List.mem n covariant -> (let fk_arg1 = List.length xs in
             let fk_arg2 = List.length ys in
             fk_arg1 = fk_arg2) && all_subtypes xs ys context
        | (Types.TupleOf { elements = xs }, Types.TupleOf { elements = ys }) -> (let fk_arg1 = List.length xs in
             let fk_arg2 = List.length ys in
             fk_arg1 = fk_arg2) && all_subtypes xs ys context
        | (Types.Named { name = n; arguments = _; region = _ }, Types.Named { name = m; arguments = _; region = _ }) when n = m -> Types.Unification.unify sub sup
        | (Types.Named { name = n; arguments = xs; region = x_region }, Types.Named { name = m; arguments = ys; region = y_region }) when Option.is_some (case_type_named n context) && Option.is_some (case_type_named m context) -> is_case_subset (Types.Named { name = n; arguments = xs; region = x_region } : Types.type_) (Types.Named { name = m; arguments = ys; region = y_region } : Types.type_) context
        | (Types.FunctionOf { parameters = xs; result = x; effects = x_effects }, Types.FunctionOf { parameters = ys; result = y; effects = y_effects }) -> (((let fk_arg1 = List.length xs in
               let fk_arg2 = List.length ys in
               fk_arg1 = fk_arg2) && all_subtypes ys xs context) && is_subtype x y context) && is_sub_effects x_effects y_effects
        | (Types.Named { name = _; arguments = _; region = _ }, _) -> false
        | (_, Types.Named { name = _; arguments = _; region = _ }) -> false
        | (x, y) -> Types.Unification.unify x y
      and all_subtypes (xs : Types.type_ list) (ys : Types.type_ list) (context : context) : bool =
        match (xs, ys) with
        | (x :: more_x, y :: more_y) -> is_subtype x y context && all_subtypes more_x more_y context
        | _ -> true

      let differs (pair : Types.type_ * Types.type_) : bool =
        let (a, b) = pair in
        a <> b

      let own_type_mismatch (typed : typed) (wanted : Types.type_) (found : Types.type_) : string option =
        match (wanted, found) with
        | (Types.ModuleValue { spec = w; arguments = ws; own_types = own }, Types.ModuleValue { spec = f; arguments = fs; own_types = _ }) when w = f && Lang.Lists.list_is_not_empty own -> Option.map (fun (name, pair) -> let module_ = match (typed : typed).core with
                 | Core.ModulePacked { module_ = m; spec = _ } -> Symbols.Symbols.simple_name m
                 | _ -> "this " ^ Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) w ".")) ~default:w in
               let (expected_own, found_own) = pair in
               let fk_arg1 = Types.TypeText.shown found_own in
               let fk_arg2 = Types.TypeText.shown expected_own in
               module_ ^ "'s " ^ name ^ " is " ^ fk_arg1 ^ ", but here it must be " ^ fk_arg2) (List.find_opt (fun (_, pair) -> differs pair) (Lang.Lists.list_zip own (Lang.Lists.list_zip ws fs)))
        | _ -> None

      let assign (e : Parser.expression) (typed : typed) (expected : Types.type_) (context : context) : unit =
        if takes_on_case typed expected context then () else (let before = Types.TypeText.shown (typed : typed).t in
           let wanted = Types.TypeText.shown expected in
           let found = Types.Types.resolved_fully (typed : typed).t in
           let sought = Types.Types.resolved_fully expected in
           if not (is_subtype (typed : typed).t expected context) then (match own_type_mismatch typed sought found with
              | Some why -> (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context (Symbols.Positions.of_ e) why)) with
                   | _ -> (assert false))
              | None -> match mismatch (Symbols.Positions.of_ e) wanted before context with
                  | _ -> (assert false)) else ())

      let default_value (at : Parser.position) (function_ : string) (context : context) : typed =
        match Collections.Maps.map_get ((context : context).environment : environment).functions function_ with
        | None -> (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ("unknown name '" ^ function_ ^ "'"))) with
             | _ -> (assert false))
        | Some s -> match Types.Types.resolved (Globals.type_of s at context) with
            | Types.FunctionOf { parameters = _; result = result; effects = effects } -> Effect.perform (Doing_perform (effects, at));
                let call = (Core.Applied { function_ = (Core.GlobalRead { function_ = s } : Core.core); arguments = [] } : Core.core) in
                if Types.Types.is_named (Types.Types.resolved result) "Nothing" then ({ t = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_); spelled = None; core = (Core.Absurd { call = call } : Core.core) } : typed) else ({ t = result; spelled = None; core = call } : typed)
            | other -> ({ t = other; spelled = None; core = (Core.GlobalRead { function_ = s } : Core.core) } : typed)

      let operation_named (name : string) (at : Parser.position) (context : context) : operation option =
        let operations = ((context : context).environment : environment).operations in
        let namespace = (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace in
        let around_here = List.find_opt (fun it -> Lang.Lists.list_is_not_empty it) (List.map (fun n -> List.filter (fun it -> Globals.visible (it : operation).effect_ context) (Collections.Maps.map_get_or_default operations (String.concat "." (List.map Fun.id (List.take n ((context : context).place : Resolution.place).Resolution.path @ [name]))) [])) (Resolution.Names.reach name (context : context).place (namespace : Resolution.namespace).Resolution.table)) in
        let found = Option.value around_here ~default:(Lang.Lists.list_distinct_by (List.filter (fun it -> Globals.visible (it : operation).effect_ context) (List.concat_map (fun it -> Collections.Maps.map_get_or_default operations it []) (Resolution.Names.imported_names name (context : context).place namespace))) (fun it -> ((it : operation).effect_ : Symbols.symbol).Symbols.name)) in
        match found with
        | [] -> None
        | [operation] -> Some operation
        | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (let fk_arg1 = String.concat " and " (List.map Fun.id (List.map (fun it -> Symbols.Symbols.simple_name (it : operation).effect_) found)) in
               let fk_arg2 = String.concat " or " (List.map Fun.id (List.map (fun it -> Symbols.Symbols.simple_name (it : operation).effect_ ^ "." ^ name) found)) in
               "'" ^ name ^ "' is an operation of " ^ fk_arg1 ^ "; write " ^ fk_arg2))) with
            | _ -> (assert false)

      let qualified_operation (at : Parser.position) (target : Parser.expression) (name : string) (scope : scope) (context : context) : operation option =
        Option.map (fun spec -> match List.find_opt (fun it -> (it : Parser.spec_value).Parser.name = name) (spec_values spec) with
           | Some value -> ({ effect_ = spec; value = value } : operation)
           | None -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (Symbols.Symbols.simple_name spec ^ " has no operation '" ^ name ^ "'"))) with
               | _ -> (assert false)) (Option.bind (dotted_unbound target scope) (fun d -> effect_spec_named d context))

      let operation_called (callee : Parser.expression) (scope : scope) (context : context) : operation option =
        match callee with
        | Parser.Name { at = at; name = name } -> if Option.is_some (Scopes.lookup scope name) then None else operation_named name at context
        | Parser.Member { at = at; target = target; name = name } -> qualified_operation at target name scope context
        | _ -> None

      let without_type_arguments (type_arguments : Parser.type_ref list) (at : Parser.position) (context : context) (typed : typed) : typed =
        if List.is_empty type_arguments then typed else (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at "only a declared function is given type arguments, as in emptyMap<String, Int>()")) with
           | _ -> (assert false))

      let operation_type (operation : operation) (at : Parser.position) (context : context) : Types.type_ * Types.effect_label =
        match Option.bind (Collections.Maps.map_get ((context : context).environment : environment).spec_types ((operation : operation).effect_ : Symbols.symbol).Symbols.name) (fun types -> Option.map (fun s -> (types, s)) (Collections.Maps.map_get (types : spec_types).values ((operation : operation).value : Parser.spec_value).Parser.name)) with
        | Some (types, scheme) -> let mapping = Collections.Maps.list_tuple_to_map (List.map (fun v -> (v, (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_))) (scheme : Types.scheme).Types.variables) in
            let fk_arg1 = Types.Types.substitute (scheme : Types.scheme).Types.template mapping in
            let fk_arg2 = ({ Types.name = ((operation : operation).effect_ : Symbols.symbol).Symbols.name; arguments = List.map (fun v -> Collections.Maps.map_get_or_default mapping v (Types.Variable { variable = v } : Types.type_)) (types : spec_types).parameters } : Types.effect_label) in
            (fk_arg1, fk_arg2)
        | None -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ("'" ^ ((operation : operation).value : Parser.spec_value).Parser.name ^ "' is used before " ^ Symbols.Symbols.simple_name (operation : operation).effect_ ^ " is checked"))) with
            | _ -> (assert false)

      let performed (operation : operation) (label : Types.effect_label) (context : context) : Types.effect_label list =
        [label] @ (if fails_at_call (operation : operation).effect_ (operation : operation).value context then [({ Types.name = fail_effect; arguments = [] } : Types.effect_label)] else [])

      let record_shape (r : Symbols.symbol) (at : Parser.position) (building : bool) (context : context) : constructor_shape =
        let own = Symbols.Symbols.simple_name r in
        if Definitions.Conversion.is_abstract_here r (context : context).place ((context : context).environment : environment).definitions then (match Effect.perform (Diagnostics.Abandoning_abandon (opaque r at context)) with
           | _ -> (assert false)) else ();
        match ((r : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.RecordDefinition { type_parameters = type_parameters; fields = fields; private_constructor = private_constructor; annotation = _; external_ = external_ } -> if Option.is_some external_ then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (own ^ " is an OCaml type, made by its functions, not by " ^ own ^ "(...)"))) with
               | _ -> (assert false)) else ();
            if (building && private_constructor) && not (Resolution.Visibility.is_inside (context : context).place (r : Symbols.symbol).Symbols.path) then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (own ^ "'s constructor is private to " ^ String.concat "." (List.map Fun.id (r : Symbols.symbol).Symbols.path)))) with
               | _ -> (assert false)) else ();
            let arguments = List.map (fun it -> (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_)) type_parameters in
            let definitions = ((context : context).environment : environment).definitions in
            let region = Definitions.Conversion.new_region r definitions in
            let fk_arg1 = List.map (fun it -> (it : Parser.field).Parser.name) fields in
            let fk_arg2 = Definitions.Conversion.record_fields r arguments region definitions (Some (context : context).place) in
            ({ constructor = (Core.RecordConstructor { record = r } : Core.constructor); field_names = fk_arg1; field_types = fk_arg2; result = (Types.Named { name = (r : Symbols.symbol).Symbols.name; arguments = arguments; region = region } : Types.type_) } : constructor_shape)
        | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (own ^ " isn't a record"))) with
            | _ -> (assert false)

      let result_case (name : string) : constructor_shape option =
        let value = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
        let error = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
        match name with
        | "Ok" -> Some ({ constructor = (Core.BuiltinCase { name = "Ok" } : Core.constructor); field_names = ["value"]; field_types = [value]; result = Types.Types.result_of value error } : constructor_shape)
        | "Error" -> Some ({ constructor = (Core.BuiltinCase { name = "Error" } : Core.constructor); field_names = ["error"]; field_types = [error]; result = Types.Types.result_of value error } : constructor_shape)
        | _ -> None

      let imported_case (name : string) (context : context) : Symbols.case_symbol option =
        match Resolution.Names.imported_names name (context : context).place (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace with
        | [full] -> Lang.Options.option_filter (Collections.Maps.map_get (((((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.cases full) (fun c -> Globals.visible (c : Symbols.case_symbol).Symbols.owner context && not (Definitions.Conversion.is_abstract_here (c : Symbols.case_symbol).Symbols.owner (context : context).place ((context : context).environment : environment).definitions))
        | _ -> None

      let visible_case (name : string) (at : Parser.position) (qualifier : string option) (qualifier_module : Symbols.module_symbol option) (context : context) : Definitions.case_info option =
        let via_import = if Option.is_none qualifier then imported_case name context else None in
        let candidates = match via_import with
          | Some c -> [c]
          | None -> List.filter (fun c -> (Globals.visible (c : Symbols.case_symbol).Symbols.owner context && not (Definitions.Conversion.is_abstract_here (c : Symbols.case_symbol).Symbols.owner (context : context).place ((context : context).environment : environment).definitions)) && (match qualifier_module with
                  | Some m -> ((c : Symbols.case_symbol).Symbols.owner : Symbols.symbol).Symbols.path = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) (Symbols.Symbols.module_name m) "."
                  | None -> Resolution.Visibility.is_inside (context : context).place ((c : Symbols.case_symbol).Symbols.owner : Symbols.symbol).Symbols.path)) (Collections.Maps.map_get_or_default ((context : context).environment : environment).cases_by_name name []) in
        match candidates with
        | [] -> None
        | [c] -> List.find_opt (fun info -> ((info : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name = ((c : Symbols.case_symbol).Symbols.owner : Symbols.symbol).Symbols.name && ((info : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name = ((c : Symbols.case_symbol).Symbols.definition : Parser.case_definition).Parser.name) (Collections.Maps.map_get_or_default (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.cases ((c : Symbols.case_symbol).Symbols.owner : Symbols.symbol).Symbols.name [])
        | first :: _ -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (let fk_arg1 = String.concat " and " (List.map Fun.id (List.map (fun it -> Symbols.Symbols.simple_name (it : Symbols.case_symbol).Symbols.owner) candidates)) in
               let fk_arg2 = Symbols.Symbols.simple_name (first : Symbols.case_symbol).Symbols.owner in
               "'" ^ name ^ "' is a case of " ^ fk_arg1 ^ "; write " ^ fk_arg2 ^ "." ^ name ^ ", or annotate the expected type"))) with
            | _ -> (assert false)

      let case_shape (name : string) (hint : Types.type_ option) (at : Parser.position) (as_value : bool) (qualifier : string option) (qualifier_type : Symbols.symbol option) (qualifier_module : Symbols.module_symbol option) (context : context) : constructor_shape option =
        let hinted = Option.map (fun it -> Types.Types.resolved it) hint in
        let wants_result = match hinted with
          | Some (Types.Named { name = "Result"; arguments = _; region = _ }) -> true
          | Some (Types.FunctionOf { parameters = _; result = result; effects = _ }) -> Types.Types.is_named (Types.Types.resolved result) "Result"
          | _ -> false in
        if (Option.is_none qualifier && wants_result) && (name = "Ok" || name = "Error") then result_case name else if Option.is_none qualifier && name = "Some" then (let a = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
             Some ({ constructor = (Core.BuiltinCase { name = "Some" } : Core.constructor); field_names = ["value"]; field_types = [a]; result = Types.Types.option_of a } : constructor_shape)) else if Option.is_none qualifier && name = "None" then Some ({ constructor = (Core.BuiltinCase { name = "None" } : Core.constructor); field_names = []; field_types = []; result = Types.Types.option_of (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) } : constructor_shape) else (let hinted_type = Option.bind (match hinted with
                  | Some (Types.Named { name = n; arguments = _; region = _ }) -> Some n
                  | Some (Types.FunctionOf { parameters = _; result = result; effects = _ }) when as_value -> (match Types.Types.resolved result with
                       | Types.Named { name = n; arguments = _; region = _ } -> Some n
                       | _ -> None)
                  | _ -> None) (fun n -> case_type_named n context) in
               let all_cases = (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.cases in
               let found = match qualifier_type with
                 | Some t -> (match List.filter (fun it -> ((it : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name = name) (Collections.Maps.map_get_or_default all_cases (t : Symbols.symbol).Symbols.name []) with
                      | [c] -> Some c
                      | [] -> (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (Symbols.Symbols.simple_name t ^ " has no case '" ^ name ^ "'"))) with
                           | _ -> (assert false))
                      | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (Symbols.Symbols.simple_name t ^ " has several cases named '" ^ name ^ "'"))) with
                          | _ -> (assert false))
                 | None -> match Option.value (Option.map (fun h -> List.filter (fun it -> ((it : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name = name) (Collections.Maps.map_get_or_default all_cases (h : Symbols.symbol).Symbols.name [])) hinted_type) ~default:[] with
                     | [c] -> Some c
                     | _ -> visible_case name at qualifier qualifier_module context in
               match found with
               | None -> if Option.is_none qualifier then result_case name else None
               | Some c -> let home = Option.value (Lang.Options.option_or_else (Lang.Options.option_filter hinted_type (fun h -> List.exists (fun it -> Definitions.Cases.same it c) (Collections.Maps.map_get_or_default all_cases (h : Symbols.symbol).Symbols.name []))) (fun () -> qualifier_type)) ~default:(c : Definitions.case_info).Definitions.origin in
                   let arguments = List.map (fun it -> (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_)) (Definitions.Cases.type_parameters_of home) in
                   let definitions = ((context : context).environment : environment).definitions in
                   let region = Definitions.Conversion.new_region home definitions in
                   let field_types = Option.value (Option.map (fun (_, types) -> types) (List.find_opt (fun (info, _) -> Definitions.Cases.same info c) (Definitions.Conversion.cases_with_fields home arguments region definitions (Some (context : context).place)))) ~default:[] in
                   Some ({ constructor = (Core.CaseConstructor { c = ({ Symbols.name = ((c : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name ^ "." ^ ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name; owner = (c : Definitions.case_info).Definitions.origin; definition = (c : Definitions.case_info).Definitions.definition } : Symbols.case_symbol) } : Core.constructor); field_names = List.map (fun it -> (it : Parser.field).Parser.name) ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.fields; field_types = field_types; result = (Types.Named { name = (home : Symbols.symbol).Symbols.name; arguments = arguments; region = region } : Types.type_) } : constructor_shape))

      let constructor_shape (name : string) (hint : Types.type_ option) (at : Parser.position) (as_value : bool) (qualifier : string option) (building : bool) (scope : scope) (context : context) : constructor_shape option =
        let namespace = (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace in
        let qualifier_type = Option.bind qualifier (fun q -> refusing (Resolution.Lookups.case_type q (context : context).place namespace (Resolution.Refusing : Resolution.strictness)) at context) in
        Option.iter (fun t -> if Definitions.Conversion.is_abstract_here t (context : context).place ((context : context).environment : environment).definitions then (match Effect.perform (Diagnostics.Abandoning_abandon (opaque t at context)) with
              | _ -> (assert false)) else ()) qualifier_type;
        let qualifier_module = match (qualifier, qualifier_type) with
          | (Some q, None) -> refusing (Resolution.Lookups.module_named q (context : context).place namespace (Resolution.Refusing : Resolution.strictness)) at context
          | _ -> None in
        if (Option.is_some qualifier && Option.is_none qualifier_type) && Option.is_none qualifier_module then None else (let record = match (qualifier, qualifier_module) with
             | (_, Some m) -> Option.map (fun r -> match Resolution.Visibility.why_hidden r (context : context).place (namespace : Resolution.namespace).Resolution.table with
                    | Some why -> (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at why)) with
                         | _ -> (assert false))
                    | None -> r) (Collections.Maps.map_get ((namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.records (Symbols.Symbols.module_name m ^ "." ^ name))
             | (None, _) -> refusing (Resolution.Lookups.record name (context : context).place namespace (Resolution.Refusing : Resolution.strictness)) at context
             | _ -> None in
           match record with
           | Some r -> Some (record_shape r at building context)
           | None -> case_shape name hint at as_value qualifier qualifier_type qualifier_module context)

      let spelled_case (shape : constructor_shape) : Symbols.case_symbol option =
        match (shape : constructor_shape).constructor with
        | Core.CaseConstructor { c = c } -> Some c
        | _ -> None

      let qualified_case (target : Parser.expression) (scope : scope) (context : context) : string option =
        let namespace = (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace in
        match dotted_unbound target scope with
        | None -> None
        | Some qualifier -> let is_value = match target with
              | Parser.Name { at = _; name = _ } -> Option.is_some (Resolution.Lookups.found (Globals.find qualifier context (Resolution.Skipping : Resolution.strictness)))
              | _ -> false in
            if is_value then None else if Option.is_some (Resolution.Lookups.found (Resolution.Lookups.case_type qualifier (context : context).place namespace (Resolution.Skipping : Resolution.strictness))) || Option.is_some (Resolution.Lookups.found (Resolution.Lookups.module_named qualifier (context : context).place namespace (Resolution.Skipping : Resolution.strictness))) then Some qualifier else None

      let argument_expression (argument : argument_value) : Parser.expression =
        match argument with
        | WrittenValue { expression = e } -> e
        | TrailingBlock { at = at; parameters = parameters; block = block } -> (Parser.Lambda { at = at; parameters = Option.value parameters ~default:[]; body = block; ignores_arguments = false } : Parser.expression)
        | DefaultValue { at = at; function_ = function_ } -> (Parser.Call { at = at; callee = (Parser.Name { at = at; name = function_ } : Parser.expression); arguments = []; type_arguments = [] } : Parser.expression)

      let called (function_ : Symbols.symbol) (arguments : Core.core list) : Core.core =
        if Symbols.Signatures.is_external function_ then (Core.ExternalApplied { function_ = function_; arguments = arguments } : Core.core) else (Core.Applied { function_ = (Core.GlobalRead { function_ = function_ } : Core.core); arguments = arguments } : Core.core)

      let builtin_method (name : string) (receiver : Types.type_) (arguments : call_argument list) (at : Parser.position) (context : context) : Types.type_ option =
        let wanted = match (name, receiver) with
          | ("toString", _) -> Some 0
          | ("joinToString", Types.Named { name = "List"; arguments = _; region = _ }) -> Some 1
          | _ -> None in
        Option.map (fun n -> if List.length arguments <> n then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ("'" ^ name ^ "' takes " ^ string_of_int n ^ " arguments, not " ^ string_of_int (List.length arguments)))) with
              | _ -> (assert false)) else Types.Types.string) wanted

      let builtin_core (name : string) (receiver_core : Core.core) (receiver : Types.type_) (arguments : Core.core list) : Core.core =
        if name = "toString" then if Types.Types.resolved receiver = Types.Types.string then receiver_core else (Core.Shown { value = receiver_core; t = receiver } : Core.core) else (match (Types.Types.resolved receiver, arguments) with
           | (Types.Named { name = "List"; arguments = [element]; region = _ }, [separator]) -> (Core.Joined { list = receiver_core; separator = separator; element = element } : Core.core)
           | _ -> (Core.Pending { what = name ^ ", one of the language's own methods" } : Core.core))

      let fits_receiver (s : Symbols.symbol) (t : Types.type_) (context : context) : bool =
        Option.is_some (Globals.fit (Globals.receiver_type s context) t)

      let method_import_hint (name : string) (receiver : Types.type_) (context : context) : string =
        let linked = List.map (fun s -> String.concat "." (List.map Fun.id (s : Symbols.symbol).Symbols.path)) (List.filter (fun s -> (Globals.visible s context && not (Globals.in_scope s context)) && fits_receiver s receiver context) (Collections.Maps.map_get_or_default ((context : context).environment : environment).extensions name [])) in
        let namespace = (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace in
        let modules = Lang.Lists.list_distinct (if List.is_empty linked then List.map (fun it -> Lang.Strings.string_remove_suffix it ("." ^ name)) (List.filter (fun it -> String.ends_with ~suffix:("." ^ name) it) (Resolution.ImportHints.imports_for name (namespace : Resolution.namespace).Resolution.hints)) else linked) in
        if List.is_empty modules then "" else ("; " ^ String.concat ", or " (List.map Fun.id (List.map (fun it -> "import " ^ it ^ ".*") modules))) ^ " has one"

      let comparisons =
        ["=="; "!="; "<"; "<="; ">"; ">="]

      let is_constant (e : Parser.expression) : bool =
        match e with
        | Parser.IntConstant { at = _; value = _ } -> true
        | Parser.FloatConstant { at = _; value = _ } -> true
        | Parser.BooleanConstant { at = _; value = _ } -> true
        | Parser.CharConstant { at = _; value = _ } -> true
        | Parser.StringTemplate { at = _; parts = parts } -> Lang.Lists.list_none parts (fun p -> match p with
               | Parser.Interpolation { expression = _ } -> true
               | Parser.TemplateText { text = _ } -> false)
        | Parser.Unary { at = _; operator = "-"; operand = Parser.IntConstant { at = _; value = _ } } -> true
        | Parser.Unary { at = _; operator = "-"; operand = Parser.FloatConstant { at = _; value = _ } } -> true
        | _ -> false

      let starts_lower_case (name : string) : bool =
        Option.value (Option.map (fun it -> Lang.Strings.char_is_lower_case it) ((fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in if n < 0 || i >= String.length s then None else Some (Uchar.to_int (Uchar.utf_decode_uchar (String.get_utf_8_uchar s i)))) name 0)) ~default:false

      let written (a : Parser.argument) : call_argument =
        ({ name = (a : Parser.argument).Parser.name; value = (WrittenValue { expression = (a : Parser.argument).Parser.value } : argument_value); text = (a : Parser.argument).Parser.text; operands = (a : Parser.argument).Parser.operands } : call_argument)

      let block_as_last_by_name (callee : Parser.expression) (given : call_argument list) (scope : scope) (context : context) : string option =
        match callee with
        | Parser.Name { at = _; name = name } when Option.is_none (Scopes.lookup scope name) -> Option.bind (Resolution.Lookups.found (Globals.find name context (Resolution.Skipping : Resolution.strictness))) (fun declared -> let parameters = Option.value (Symbols.Signatures.parameters_of declared) ~default:[] in
               Lang.Options.option_filter (Option.map (fun it -> (it : Parser.parameter).Parser.name) (Lang.Lists.list_last_or_none parameters)) (fun last -> let in_order = List.length (Lang.Lists.list_take_while given (fun it -> Option.is_none (it : call_argument).name)) in
                  ((let fk_arg1 = List.length parameters in
                    let fk_arg2 = List.length given + 1 in
                    fk_arg1 > fk_arg2) && Lang.Lists.list_none given (fun it -> (it : call_argument).name = Some last)) && List.for_all (fun p -> Option.is_some (p : Parser.parameter).Parser.default || List.exists (fun it -> (it : call_argument).name = Some (p : Parser.parameter).Parser.name) given) (List.drop in_order (Lang.Lists.list_drop_last parameters 1))))
        | _ -> None

      let known (expected : Types.type_ option) : Types.type_ option =
        Lang.Options.option_filter expected (fun t -> match Types.Types.resolved t with
           | Types.Variable { variable = _ } -> false
           | _ -> true)

      let effect_named (name : string) (context : context) : Symbols.symbol option =
        Collections.Maps.map_get (((((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.specs name

      let joined (parts : Core.core list) : Core.core =
        match parts with
        | [] -> (Core.Value { literal = (Core.StringLiteral { value = "" } : Core.literal) } : Core.core)
        | [one] -> one
        | _ -> (Core.Operated { primitive = (Core.Concatenated : Core.primitive); operands = parts } : Core.core)

      let operation_value (operation : operation) (at : Parser.position) (context : context) : Types.type_ =
        let (t, label) = operation_type operation at context in
        match t with
        | Types.FunctionOf { parameters = parameters; result = result; effects = _ } -> (Types.FunctionOf { parameters = parameters; result = result; effects = (let fk_arg1 = performed operation label context in
             let fk_arg2 = Some (Effect.perform (Types.Solving_fresh ())) in
             ({ Types.labels = fk_arg1; rest = fk_arg2 } : Types.row)) } : Types.type_)
        | _ -> Effect.perform (Doing_perform (({ Types.labels = [label]; rest = None } : Types.row), at));
            t

      let operation_core (operation : operation) : Core.core =
        match ((operation : operation).value : Parser.spec_value).Parser.parameters with
        | None -> (Core.Performed { effect_ = (operation : operation).effect_; operation = ((operation : operation).value : Parser.spec_value).Parser.name; arguments = [] } : Core.core)
        | Some ps -> let names = List.mapi (fun i _ -> "fk_given" ^ string_of_int (i + 1)) ps in
            let fk_arg1 = List.map (fun it -> (Core.NameMatcher { name = it } : Core.matcher)) names in
            let fk_arg2 = (Core.Performed { effect_ = (operation : operation).effect_; operation = ((operation : operation).value : Parser.spec_value).Parser.name; arguments = List.map (fun it -> (Core.LocalRead { name = it; is_var = false } : Core.core)) names } : Core.core) in
            (Core.FunctionValue { parameters = fk_arg1; body = fk_arg2; drops_result = false } : Core.core)

      let constructor_value (shape : constructor_shape) : Core.core =
        if List.is_empty (shape : constructor_shape).field_types then (Core.Constructed { constructor = (shape : constructor_shape).constructor; fields = []; t = (shape : constructor_shape).result } : Core.core) else (let names = List.mapi (fun i _ -> "field" ^ string_of_int i) (shape : constructor_shape).field_types in
           let fk_arg1 = List.map (fun it -> (Core.NameMatcher { name = it } : Core.matcher)) names in
           let fk_arg2 = (Core.Constructed { constructor = (shape : constructor_shape).constructor; fields = List.map (fun it -> (Core.LocalRead { name = it; is_var = false } : Core.core)) names; t = (shape : constructor_shape).result } : Core.core) in
           (Core.FunctionValue { parameters = fk_arg1; body = fk_arg2; drops_result = false } : Core.core))

      let builtin_function (name : string) : Types.type_ option =
        match name with
        | "Unit" -> Some Types.Types.unit
        | "assert" -> Some (Types.FunctionOf { parameters = [Types.Types.boolean]; result = Types.Types.unit; effects = ({ Types.labels = []; rest = Some (Effect.perform (Types.Solving_fresh ())) } : Types.row) } : Types.type_)
        | "assertEquals" -> let a = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
            Some (Types.FunctionOf { parameters = [a; a]; result = Types.Types.unit; effects = ({ Types.labels = []; rest = Some (Effect.perform (Types.Solving_fresh ())) } : Types.row) } : Types.type_)
        | _ -> None

      let infer_name (at : Parser.position) (name : string) (expected : Types.type_ option) (scope : scope) (context : context) : typed =
        match Scopes.lookup scope name with
        | Some local -> if (local : local).hides then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at "this block's 'it' hides the 'it' outside it: name this block's parameter, { x -> ... }")) with
               | _ -> (assert false)) else ({ t = (local : local).t; spelled = None; core = (Core.LocalRead { name = name; is_var = Option.is_some (local : local).region } : Core.core) } : typed)
        | None -> match Globals.find_or_refuse name at context with
            | Some global -> let fk_arg1 = Globals.type_of global at context in
                let fk_arg2 = if Symbols.Signatures.is_external global then (Core.ExternalRead { function_ = global } : Core.core) else (Core.GlobalRead { function_ = global } : Core.core) in
                ({ t = fk_arg1; spelled = None; core = fk_arg2 } : typed)
            | None -> match operation_named name at context with
                | Some operation -> let fk_arg1 = operation_value operation at context in
                    let fk_arg2 = operation_core operation in
                    ({ t = fk_arg1; spelled = None; core = fk_arg2 } : typed)
                | None -> match constructor_shape name expected at true None true scope context with
                    | Some shape -> let fk_arg1 = if List.is_empty (shape : constructor_shape).field_types then (shape : constructor_shape).result else (Types.FunctionOf { parameters = (shape : constructor_shape).field_types; result = (shape : constructor_shape).result; effects = ({ Types.labels = []; rest = Some (Effect.perform (Types.Solving_fresh ())) } : Types.row) } : Types.type_) in
                        let fk_arg2 = spelled_case shape in
                        let fk_arg3 = constructor_value shape in
                        ({ t = fk_arg1; spelled = fk_arg2; core = fk_arg3 } : typed)
                    | None -> match builtin_function name with
                        | Some t -> ({ t = t; spelled = None; core = (if name = "Unit" then (Core.Value { literal = (Core.UnitLiteral : Core.literal) } : Core.core) else (Core.Pending { what = name ^ ", used as a value" } : Core.core)) } : typed)
                        | None -> match Resolution.Lookups.found (Resolution.Lookups.module_named name (context : context).place (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace (Resolution.Skipping : Resolution.strictness)) with
                            | Some m -> module_as_value m at context
                            | None -> if name = "it" then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at "there's no 'it' here: only a block given as a function of one parameter has one, as in xs.filter { it > 1 }")) with
                                   | _ -> (assert false)) else (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ("unknown name '" ^ name ^ "'" ^ Resolution.ImportHints.for_name name (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace))) with
                                   | _ -> (assert false))

      let is_spread (e : Parser.expression) : bool =
        match e with
        | Parser.Spread { at = _; list = _ } -> true
        | _ -> false

      let smallest_with_all (branches : (Parser.expression * typed) list) (with_cases : (string * Types.type_) list) (at : Parser.position) (context : context) : Types.type_ =
        let all_cases = (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.cases in
        let needed = List.concat_map (fun (_, typed) -> match (typed : typed).spelled with
             | Some c -> List.take 1 (List.filter (fun it -> is_case it c) (Collections.Maps.map_get_or_default all_cases ((c : Symbols.case_symbol).Symbols.owner : Symbols.symbol).Symbols.name []))
             | None -> Option.value (Option.map (fun it -> Collections.Maps.map_get_or_default all_cases it []) (case_type_of (typed : typed).t context)) ~default:[]) branches in
        let covers = fun name -> List.for_all (fun n -> List.exists (fun it -> Definitions.Cases.same it n) (Collections.Maps.map_get_or_default all_cases name [])) needed in
        let size = fun name -> List.length (Collections.Maps.map_get_or_default all_cases name []) in
        let from_branches = Option.map (fun (_, t) -> t) (Lang.Lists.list_min_by_or_none (List.filter (fun (name, _) -> covers name) with_cases) (fun (name, _) -> size name)) in
        let declared = fun () -> Option.map (fun (name, _) -> (Types.Named { name = name; arguments = []; region = None } : Types.type_)) (Lang.Lists.list_min_by_or_none (List.filter (fun (name, s) -> List.is_empty (Definitions.Cases.type_parameters_of s) && covers name) (Collections.Maps.map_to_list (((((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.case_types)) (fun (name, _) -> size name)) in
        match Lang.Options.option_or_else from_branches declared with
        | Some t -> t
        | None -> let shown = String.concat ", " (List.map Fun.id (List.map (fun it -> ((it : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name ^ "." ^ ((it : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name) (Lang.Lists.list_distinct_by needed (fun it -> ((it : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name ^ "." ^ ((it : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name)))) in
            match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ("no type has all of " ^ shown ^ "; declare one that does, or annotate the type"))) with
            | _ -> (assert false)

      let join (branches : (Parser.expression * typed) list) (at : Parser.position) (context : context) : Types.type_ =
        let types = List.map (fun (_, typed) -> (typed : typed).t) branches in
        let with_cases = Lang.Lists.list_map_not_null types (fun t -> Option.map (fun name -> (name, Types.Types.resolved t)) (case_type_of t context)) in
        let result = if List.length (Lang.Lists.list_distinct (List.map (fun (name, _) -> name) with_cases)) <= 1 then (let fk_arg1 = List.nth_opt types 0 in
             let fk_arg2 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
             Option.value fk_arg1 ~default:fk_arg2) else smallest_with_all branches with_cases at context in
        List.iter (fun (e, typed) -> assign e typed result context) branches;
        result

      let rec in_order (items : Parser.expression list) (elements : Core.core list) (spreads : Core.core list) : Core.list_item list =
        match items with
        | [] -> []
        | Parser.Spread { at = _; list = _ } :: rest -> let fk_arg1 = Option.value (Option.map (fun it -> [(Core.SpreadItems { list = it } : Core.list_item)]) (List.nth_opt spreads 0)) ~default:[] in
            let fk_arg2 = in_order rest elements (List.drop 1 spreads) in
            fk_arg1 @ fk_arg2
        | _ :: rest -> let fk_arg1 = Option.value (Option.map (fun it -> [(Core.OneItem { value = it } : Core.list_item)]) (List.nth_opt elements 0)) ~default:[] in
            let fk_arg2 = in_order rest (List.drop 1 elements) spreads in
            fk_arg1 @ fk_arg2

      let bare_cases (case_type : Symbols.symbol) (at : Parser.position) (context : context) : unit =
        match List.find_opt (fun it -> Lang.Lists.list_is_not_empty ((it : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.fields) (Collections.Maps.map_get_or_default (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.cases (case_type : Symbols.symbol).Symbols.name []) with
        | Some c -> (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (let fk_arg1 = Symbols.Symbols.simple_name case_type in
                let fk_arg2 = String.concat ", " (List.map Fun.id (List.map (fun it -> (it : Parser.field).Parser.name) ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.fields)) in
                "only a type whose cases carry nothing has values and name, and " ^ fk_arg1 ^ "'s " ^ ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name ^ " carries " ^ fk_arg2))) with
             | _ -> (assert false))
        | None -> ()

      let case_values (at : Parser.position) (name : string) (qualifier : string) (context : context) : Types.type_ option =
        if name <> "values" then None else (match Resolution.Lookups.found (Resolution.Lookups.case_type qualifier (context : context).place (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace (Resolution.Skipping : Resolution.strictness)) with
           | None -> None
           | Some case_type -> if List.exists (fun it -> ((it : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name = name) (Collections.Maps.map_get_or_default (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.cases (case_type : Symbols.symbol).Symbols.name []) then None else (bare_cases case_type at context;
                  Some (Types.Types.list_of (Types.Named { name = (case_type : Symbols.symbol).Symbols.name; arguments = List.map (fun it -> (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_)) (Definitions.Cases.type_parameters_of case_type); region = None } : Types.type_))))

      let values_core (qualifier : string) (t : Types.type_) (context : context) : Core.core =
        let element = match t with
          | Types.Named { name = "List"; arguments = [e]; region = _ } -> e
          | _ -> t in
        match Resolution.Lookups.found (Resolution.Lookups.case_type qualifier (context : context).place (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace (Resolution.Skipping : Resolution.strictness)) with
        | Some case_type -> (Core.ListMade { items = List.map (fun c -> (Core.OneItem { value = (Core.Constructed { constructor = (Core.CaseConstructor { c = ({ Symbols.name = ((c : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name ^ "." ^ ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name; owner = (c : Definitions.case_info).Definitions.origin; definition = (c : Definitions.case_info).Definitions.definition } : Symbols.case_symbol) } : Core.constructor); fields = []; t = element } : Core.core) } : Core.list_item)) (Collections.Maps.map_get_or_default (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.cases (case_type : Symbols.symbol).Symbols.name []) } : Core.core)
        | None -> (Core.Pending { what = "a type's values" } : Core.core)

      let is_effect_module (m : Symbols.module_symbol) (context : context) : bool =
        match m with
        | Symbols.DeclaredModule { symbol = s } -> Option.value (Option.map (fun spec -> Annotations.Annotations.is_effect spec (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace) (Collections.Maps.map_get ((context : context).environment : environment).module_specs (s : Symbols.symbol).Symbols.name)) ~default:false
        | Symbols.PackageModule { name = _ } -> false

      let property_of (at : Parser.position) (target : Parser.expression) (target_core : Core.core) (name : string) (receiver : Types.type_) (scope : scope) (context : context) : typed =
        match extension_for at name receiver context with
        | Some extension -> if not (Symbols.Signatures.is_property extension) then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ("'" ^ name ^ "' is a method; call it with ()"))) with
               | _ -> (assert false)) else (match Types.Types.resolved (Globals.type_of extension at context) with
               | Types.FunctionOf { parameters = receiver_type :: _; result = result; effects = effects } -> assign target (let fk_arg1 = typed_default_spelled () in
                    let fk_arg2 = typed_default_core () in
                    ({ t = receiver; spelled = fk_arg1; core = fk_arg2 } : typed)) receiver_type context;
                   Effect.perform (Doing_perform (effects, at));
                   ({ t = result; spelled = None; core = called extension [target_core] } : typed)
               | other -> ({ t = other; spelled = None; core = (Core.Pending { what = "a property that isn't a function" } : Core.core) } : typed))
        | None -> let named = if name = "name" then Option.bind (case_type_of receiver context) (fun it -> case_type_named it context) else None in
            match named with
            | Some case_type when List.for_all (fun it -> List.is_empty ((it : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.fields) (Collections.Maps.map_get_or_default (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.cases (case_type : Symbols.symbol).Symbols.name []) -> bare_cases case_type at context;
                ({ t = Types.Types.string; spelled = None; core = (Core.CaseName { value = target_core; cases = List.map (fun c -> ({ Symbols.name = ((c : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name ^ "." ^ ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name; owner = (c : Definitions.case_info).Definitions.origin; definition = (c : Definitions.case_info).Definitions.definition } : Symbols.case_symbol)) (Collections.Maps.map_get_or_default (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.cases (case_type : Symbols.symbol).Symbols.name []) } : Core.core) } : typed)
            | _ -> match receiver with
                | Types.Variable { variable = _ } -> (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ("can't tell what '" ^ name ^ "' is: the receiver's type isn't known here; annotate it"))) with
                     | _ -> (assert false))
                | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (no_field at target name receiver context)) with
                    | _ -> (assert false)

      let no_operator (operator : string) (method_ : string) (t : Types.type_) (context : context) : string =
        if List.exists (fun it -> fits_receiver it t context) (Globals.extensions_named method_ context) then "its " ^ method_ ^ " isn't an operator; mark it operator to use '" ^ operator ^ "' for it" else "there's no operator " ^ method_ ^ method_import_hint method_ t context

      let owns_operators (t : Types.type_) : bool =
        match t with
        | Types.Named { name = name; arguments = _; region = _ } -> not (List.mem name ["Int"; "Float"; "String"; "List"])
        | Types.Variable { variable = _ } -> false
        | Types.FunctionOf { parameters = _; result = _; effects = _ } -> false
        | Types.Effects { row = _ } -> false
        | _ -> true

      let is_numeric (t : Types.type_) : bool =
        Types.Types.is_named t "Int" || Types.Types.is_named t "Float"

      let comparison (operator : string) : Core.primitive =
        match operator with
        | "<" -> (Core.Less : Core.primitive)
        | "<=" -> (Core.LessOrEqual : Core.primitive)
        | ">" -> (Core.Greater : Core.primitive)
        | _ -> (Core.GreaterOrEqual : Core.primitive)

      let arithmetic_on (operator : string) (is_float : bool) : Core.primitive =
        match operator with
        | "+" -> if is_float then (Core.FloatPlus : Core.primitive) else (Core.IntPlus : Core.primitive)
        | "-" -> if is_float then (Core.FloatMinus : Core.primitive) else (Core.IntMinus : Core.primitive)
        | "*" -> if is_float then (Core.FloatTimes : Core.primitive) else (Core.IntTimes : Core.primitive)
        | "/" -> if is_float then (Core.FloatDivide : Core.primitive) else (Core.IntDivide : Core.primitive)
        | _ -> if is_float then (Core.FloatRemainder : Core.primitive) else (Core.IntRemainder : Core.primitive)

      let is_member (e : Parser.expression) : bool =
        match e with
        | Parser.Member { at = _; target = _; name = _ } -> true
        | _ -> false

      let is_constructor_name (e : Parser.expression) (scope : scope) (context : context) : bool =
        match e with
        | Parser.Name { at = at; name = name } -> (Option.is_none (Scopes.lookup scope name) && Option.is_none (Resolution.Lookups.found (Globals.find name context (Resolution.Skipping : Resolution.strictness)))) && Option.is_some (constructor_shape name None at false None true scope context)
        | _ -> false

      let piped (value : Core.core) (call : Core.core -> Core.core) : Core.core =
        if Core.Cores.runs value then (Core.Bound { pattern = (Core.NameMatcher { name = "fk_piped" } : Core.matcher); value = value; body = call (Core.LocalRead { name = "fk_piped"; is_var = false } : Core.core) } : Core.core) else call value

      let rec conditions (branches : (Core.core option * Core.core) list) : Core.core =
        match branches with
        | [] -> (Core.Value { literal = (Core.UnitLiteral : Core.literal) } : Core.core)
        | [(_, body)] -> body
        | (None, body) :: _ -> body
        | (Some condition, body) :: rest -> (Core.Conditional { condition = condition; then_ = body; otherwise = conditions rest } : Core.core)

      let checked_pattern_default_matcher () : Core.matcher =
        (Core.AnyMatcher : Core.matcher)

      let rec constant_text (e : Parser.expression) : string =
        match e with
        | Parser.IntConstant { at = _; value = value } -> string_of_int value
        | Parser.FloatConstant { at = _; value = value } -> fk_show_float value
        | Parser.CharConstant { at = _; value = value } -> "'" ^ fk_show_char value ^ "'"
        | Parser.StringTemplate { at = _; parts = parts } -> ("\"" ^ String.concat "" (List.map Fun.id (List.map (fun p -> match p with
                  | Parser.TemplateText { text = text } -> text
                  | Parser.Interpolation { expression = _ } -> "$") parts))) ^ "\""
        | Parser.Unary { at = _; operator = operator; operand = operand } -> operator ^ constant_text operand
        | _ -> "?"

      let constant_matches (e : Parser.expression) : Coverage.matches =
        match e with
        | Parser.BooleanConstant { at = _; value = value } -> ({ Coverage.shape = Some (Coverage.BooleanShape { value = value } : Coverage.shape); fields = [] } : Coverage.matches)
        | _ -> ({ Coverage.shape = Some (Coverage.LiteralShape { text = constant_text e } : Coverage.shape); fields = [] } : Coverage.matches)

      let literal_of (core : Core.core) : Core.literal =
        match core with
        | Core.Value { literal = literal } -> literal
        | Core.Operated { primitive = Core.IntNegate; operands = [Core.Value { literal = Core.IntLiteral { value = n } }] } -> (Core.IntLiteral { value = Int.neg n } : Core.literal)
        | Core.Operated { primitive = Core.FloatNegate; operands = [Core.Value { literal = Core.FloatLiteral { value = x } }] } -> (Core.FloatLiteral { value = Float.neg x } : Core.literal)
        | _ -> (Core.UnitLiteral : Core.literal)

      let product (choices : Coverage.matches list list) : Coverage.matches list list =
        List.fold_left (fun acc options -> List.concat_map (fun prefix -> List.map (fun it -> prefix @ [it]) options) acc) [[]] choices

      let narrow (at : Parser.position) (name : string) (target : Symbols.symbol) (subject_type : Types.type_) (scope : scope) (subject : Parser.expression option) (context : context) : checked_pattern =
        let subject_case_type = match subject_type with
          | Types.Named { name = n; arguments = _; region = _ } when Option.is_some (case_type_named n context) -> subject_type
          | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ("'is " ^ name ^ "' needs the subject to be a type with cases, not " ^ Types.TypeText.shown subject_type))) with
              | _ -> (assert false) in
        let narrowed = let fk_arg1 = List.map (fun it -> (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_)) (Definitions.Cases.type_parameters_of target) in
          let fk_arg2 = Definitions.Conversion.new_region target ((context : context).environment : environment).definitions in
          (Types.Named { name = (target : Symbols.symbol).Symbols.name; arguments = fk_arg1; region = fk_arg2 } : Types.type_) in
        let all_cases = (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.cases in
        if not (is_case_subset narrowed subject_case_type context) then (let subject_name = match subject_case_type with
             | Types.Named { name = n; arguments = _; region = _ } -> n
             | _ -> "" in
           let missing = List.filter (fun c -> Lang.Lists.list_none (Collections.Maps.map_get_or_default all_cases subject_name []) (fun it -> Definitions.Cases.same it c)) (Collections.Maps.map_get_or_default all_cases (target : Symbols.symbol).Symbols.name []) in
           match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ((target : Symbols.symbol).Symbols.name ^ " isn't part of " ^ subject_name ^ ": " ^ subject_name ^ " has no " ^ String.concat ", " (List.map Fun.id (List.map (fun it -> ((it : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name ^ "." ^ ((it : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name) missing))))) with
           | _ -> (assert false)) else ();
        let narrowed_scope = match subject with
          | Some (Parser.Name { at = _; name = local }) -> (match Scopes.lookup scope local with
               | Some existing -> Scopes.bind scope local ({ t = narrowed; region = (existing : local).region; narrowed = None; hides = (existing : local).hides } : local)
               | None -> scope)
          | _ -> scope in
        let fk_arg1 = List.map (fun c -> ({ Coverage.shape = Some (Coverage.CaseShape { owner = ((c : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name; name = ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name } : Coverage.shape); fields = List.map (fun it -> Coverage.Coverage.anything) ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.fields } : Coverage.matches)) (Collections.Maps.map_get_or_default all_cases (target : Symbols.symbol).Symbols.name []) in
        let fk_arg2 = checked_pattern_default_matcher () in
        ({ scope = narrowed_scope; matches = fk_arg1; matcher = fk_arg2 } : checked_pattern)

      let subject_case (at : Parser.position) (name : string) (qualifier : string option) (st : Symbols.symbol) (type_arguments : Types.type_ list) (region : Types.type_ option) (context : context) : constructor_shape =
        let namespace = (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace in
        let all_cases = (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.cases in
        let qualifier_cases = Option.map (fun q -> match Resolution.Lookups.case_type q (context : context).place namespace (Resolution.Refusing : Resolution.strictness) with
             | Resolution.Found { value = s } -> if Definitions.Conversion.is_abstract_here s (context : context).place ((context : context).environment : environment).definitions then (match Effect.perform (Diagnostics.Abandoning_abandon (opaque s at context)) with
                    | _ -> (assert false)) else ();
                 Collections.Maps.map_get_or_default all_cases (s : Symbols.symbol).Symbols.name []
             | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at why)) with
                  | _ -> (assert false))
             | Resolution.NotFound -> match Resolution.Lookups.module_named q (context : context).place namespace (Resolution.Refusing : Resolution.strictness) with
                 | Resolution.Found { value = m } -> List.concat_map (fun (_, cs) -> cs) (List.filter (fun (type_name, _) -> let fk_arg1 = String.concat "." (List.map Fun.id (Lang.Lists.list_drop_last ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) type_name ".") 1)) in
                         let fk_arg2 = Symbols.Symbols.module_name m in
                         fk_arg1 = fk_arg2) (Collections.Maps.map_to_list all_cases))
                 | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at why)) with
                      | _ -> (assert false))
                 | Resolution.NotFound -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ("unknown type or module '" ^ q ^ "'"))) with
                     | _ -> (assert false)) qualifier in
        let matches = List.filter (fun (c, _) -> ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name = name && Option.value (Option.map (fun qs -> List.exists (fun it -> Definitions.Cases.same it c) qs) qualifier_cases) ~default:true) (Definitions.Conversion.cases_with_fields st type_arguments region ((context : context).environment : environment).definitions (Some (context : context).place)) in
        match matches with
        | [(c, field_types)] -> ({ constructor = (Core.CaseConstructor { c = ({ Symbols.name = ((c : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name ^ "." ^ ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name; owner = (c : Definitions.case_info).Definitions.origin; definition = (c : Definitions.case_info).Definitions.definition } : Symbols.case_symbol) } : Core.constructor); field_names = List.map (fun it -> (it : Parser.field).Parser.name) ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.fields; field_types = field_types; result = (Types.Named { name = (st : Symbols.symbol).Symbols.name; arguments = type_arguments; region = region } : Types.type_) } : constructor_shape)
        | [] -> (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ((st : Symbols.symbol).Symbols.name ^ " has no case '" ^ Option.value (Option.map (fun it -> it ^ ".") qualifier) ~default:"" ^ name ^ "'"))) with
             | _ -> (assert false))
        | (first, _) :: _ -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ((st : Symbols.symbol).Symbols.name ^ " has several cases named '" ^ name ^ "'; qualify it, as in " ^ ((first : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name ^ "." ^ name))) with
            | _ -> (assert false)

      let is_shared (name : string) (context : context) : bool =
        List.exists (fun (owner, cs) -> List.exists (fun c -> ((c : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name <> owner && (owner = name || ((c : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name = name)) cs) (Collections.Maps.map_to_list (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.cases)

      let narrowed_to (shape : constructor_shape) (is_check : bool) (scope : scope) (subject : Parser.expression option) (context : context) : scope =
        match (is_check, (shape : constructor_shape).constructor, subject) with
        | (true, Core.CaseConstructor { c = c }, Some (Parser.Name { at = _; name = local })) when Lang.Lists.list_is_not_empty (shape : constructor_shape).field_types -> (match Scopes.lookup scope local with
             | Some existing -> Scopes.bind scope local ({ t = (existing : local).t; region = (existing : local).region; narrowed = Some (let fk_arg1 = Collections.Maps.list_tuple_to_map (Lang.Lists.list_zip (shape : constructor_shape).field_names (shape : constructor_shape).field_types) in
                  let fk_arg2 = is_shared ((c : Symbols.case_symbol).Symbols.owner : Symbols.symbol).Symbols.name context in
                  ({ case_name = ((c : Symbols.case_symbol).Symbols.definition : Parser.case_definition).Parser.name; case_type = ((c : Symbols.case_symbol).Symbols.owner : Symbols.symbol).Symbols.name; fields = ((c : Symbols.case_symbol).Symbols.definition : Parser.case_definition).Parser.fields; types = fk_arg1; shared = fk_arg2 } : narrowing)); hides = (existing : local).hides } : local)
             | None -> scope)
        | _ -> scope

      let shape_of (shape : constructor_shape) : Coverage.shape =
        match (shape : constructor_shape).constructor with
        | Core.RecordConstructor { record = record } -> (Coverage.RecordShape { name = (record : Symbols.symbol).Symbols.name } : Coverage.shape)
        | Core.CaseConstructor { c = c } -> (Coverage.CaseShape { owner = ((c : Symbols.case_symbol).Symbols.owner : Symbols.symbol).Symbols.name; name = ((c : Symbols.case_symbol).Symbols.definition : Parser.case_definition).Parser.name } : Coverage.shape)
        | Core.BuiltinCase { name = name } -> (Coverage.CaseShape { owner = ""; name = name } : Coverage.shape)

      let block_so_far_default_lines () : block_step list =
        []

      let is_bind (s : Parser.statement) : bool =
        match s with
        | Parser.Bind { at = _; pattern = _; value = _ } -> true
        | _ -> false

      let rec irrefutable (p : Parser.pattern) : bool =
        match p with
        | Parser.NamePattern { at = _; name = _ } -> true
        | Parser.Wildcard { at = _ } -> true
        | Parser.TuplePattern { at = _; elements = elements } -> List.for_all (fun it -> irrefutable it) elements
        | _ -> false

      let statement_position (s : Parser.statement) : Parser.position =
        match s with
        | Parser.Binding { at = at; name = _; parameters = _; value_type = _; value = _; variable = _ } -> at
        | Parser.Evaluation { at = at; expression = _ } -> at
        | Parser.Destructuring { at = at; pattern = _; value = _ } -> at
        | Parser.Bind { at = at; pattern = _; value = _ } -> at

      let with_scope (so_far : block_so_far) (scope : scope) (assigned : bool) : block_so_far =
        ({ scope = scope; rest = (so_far : block_so_far).rest; steps = (so_far : block_so_far).steps; pending = (so_far : block_so_far).pending; after = (so_far : block_so_far).after; assigned = assigned; lines = (so_far : block_so_far).lines } : block_so_far)

      let rec irrefutable_matcher (p : Parser.pattern) : Core.matcher =
        match p with
        | Parser.NamePattern { at = _; name = name } -> (Core.NameMatcher { name = name } : Core.matcher)
        | Parser.TuplePattern { at = _; elements = parts } -> (Core.TupleMatcher { parts = List.map (fun it -> irrefutable_matcher it) parts } : Core.matcher)
        | _ -> (Core.AnyMatcher : Core.matcher)

      let name_of (monad : monad_functions) : string =
        match monad with
        | Binding { name = name; at = _; bind = _; pure = _ } -> name
        | Mapping { name = name; at = _; map = _; product = _; pure = _ } -> name

      let position_of_monad (monad : monad_functions) : Parser.position =
        match monad with
        | Binding { name = _; at = at; bind = _; pure = _ } -> at
        | Mapping { name = _; at = at; map = _; product = _; pure = _ } -> at

      let instance (monad : monad_functions) (function_ : Symbols.symbol) (arity : int) (what : string) (context : context) : Types.type_ =
        let at = position_of_monad monad in
        match Types.Types.resolved (Globals.type_of function_ at context) with
        | Types.FunctionOf { parameters = parameters; result = result; effects = effects } when List.length parameters = arity -> Effect.perform (Doing_perform (effects, at));
            (Types.FunctionOf { parameters = parameters; result = result; effects = effects } : Types.type_)
        | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ((function_ : Symbols.symbol).Symbols.name ^ " should take " ^ what))) with
            | _ -> (assert false)

      let map_type (monad : monad_functions) (map : Symbols.symbol) (context : context) : Types.type_ * Types.type_ * Types.type_ * Types.type_ =
        let what = "a value and a function to apply to what it holds" in
        let wrong = fun () -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context (position_of_monad monad) ((map : Symbols.symbol).Symbols.name ^ " should take " ^ what))) with
            | _ -> (assert false) in
        match instance monad map 2 what context with
        | Types.FunctionOf { parameters = [mapped; f]; result = map_result; effects = _ } -> (match Types.Types.resolved f with
             | Types.FunctionOf { parameters = [held]; result = f_result; effects = _ } -> (mapped, map_result, held, f_result)
             | _ -> wrong ())
        | _ -> wrong ()

      let bind_type (monad : monad_functions) (context : context) : Types.type_ * Types.type_ * Types.type_ =
        match monad with
        | Binding { name = _; at = at; bind = bind; pure = _ } -> (let shape = match Types.Types.resolved (Globals.type_of bind at context) with
               | Types.FunctionOf { parameters = [value; next]; result = result; effects = effects } -> (match Types.Types.resolved next with
                    | Types.FunctionOf { parameters = [_]; result = _; effects = _ } -> Some (value, Types.Types.resolved next, result, effects)
                    | _ -> None)
               | _ -> None in
             match shape with
             | Some (value, next, result, effects) -> Effect.perform (Doing_perform (effects, at));
                 (value, next, result)
             | None -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ((bind : Symbols.symbol).Symbols.name ^ " should take a value and a function to go on with, as Monad's bind does"))) with
                 | _ -> (assert false))
        | Mapping { name = _; at = _; map = _; product = _; pure = _ } -> let fk_arg1 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
            let fk_arg2 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
            let fk_arg3 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
            (fk_arg1, fk_arg2, fk_arg3)

      let around (lines : block_step list) (result : Core.core) : Core.core =
        List.fold_left (fun rest step -> match step with
           | RunStep { core = core } -> (Core.Sequenced { first = core; then_ = rest } : Core.core)
           | BindStep { pattern = pattern; value = value } -> (Core.Bound { pattern = pattern; value = value; body = rest } : Core.core)
           | VarStep { name = name; value = value } -> (Core.VarBound { name = name; value = value; body = rest } : Core.core)
           | FunctionStep { name = name; parameters = parameters; body = body } -> (Core.FunctionBound { name = name; parameters = parameters; body = body; rest = rest } : Core.core)
           | ByStep { pattern = _; value = _ } -> (Core.Pending { what = "'by' outside a module's block" } : Core.core)) result (List.rev lines)

      let combine (monad : monad_functions) (steps : (Types.type_ * Types.type_) list) (at : Parser.position) (context : context) : Types.type_ * Types.type_ =
        match (monad, steps) with
        | (Mapping { name = _; at = monad_at; map = map; product = product; pure = _ }, (first_value, first_held) :: others) -> let (values, held) = List.fold_left (fun acc s -> let (vs, h) = acc in
                 let (value, element) = s in
                 match instance monad product 2 "two values, to pair what they hold" context with
                 | Types.FunctionOf { parameters = [p; q]; result = result; effects = _ } -> expect vs p at context;
                     expect value q at context;
                     (result, (Types.TupleOf { elements = [h; element] } : Types.type_))
                 | _ -> acc) (first_value, first_held) others in
            let (mapped, map_result, given, f_result) = map_type monad map context in
            expect values mapped at context;
            if not (Types.Unification.unify given held) then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context monad_at ((product : Symbols.symbol).Symbols.name ^ " should pair what its two values hold, as (A, B)"))) with
               | _ -> (assert false)) else (f_result, map_result)
        | _ -> let fk_arg1 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
            let fk_arg2 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
            (fk_arg1, fk_arg2)

      let around_monadic (lines : block_step list) (result : Core.core) (monad : monad_functions) : Core.core =
        match monad with
        | Binding { name = _; at = _; bind = bind; pure = _ } -> List.fold_left (fun rest step -> match step with
               | ByStep { pattern = pattern; value = value } -> (Core.Applied { function_ = (Core.GlobalRead { function_ = bind } : Core.core); arguments = [value; (Core.FunctionValue { parameters = [pattern]; body = rest; drops_result = false } : Core.core)] } : Core.core)
               | other -> around [other] rest) result (List.rev lines)
        | Mapping { name = _; at = _; map = map; product = product; pure = _ } -> let before = Lang.Lists.list_take_while lines (fun it -> match it with
                 | ByStep it_as_by_step -> false
                 | _ -> true) in
            let steps = Lang.Lists.list_take_while (List.drop (List.length before) lines) (fun it -> match it with
                 | ByStep it_as_by_step -> true
                 | _ -> false) in
            let after = List.drop (let fk_arg1 = List.length before in
               let fk_arg2 = List.length steps in
               fk_arg1 + fk_arg2) lines in
            let paired = Lang.Lists.list_map_not_null steps (fun s -> match s with
                 | ByStep { pattern = pattern; value = value } -> Some (value, pattern)
                 | _ -> None) in
            let mapped = match paired with
              | [] -> around after result
              | (first_value, first_pattern) :: others -> let (values, pattern) = List.fold_left (fun acc next -> let (vs, ps) = acc in
                       let (value, p) = next in
                       ((Core.Applied { function_ = (Core.GlobalRead { function_ = product } : Core.core); arguments = [vs; value] } : Core.core), (Core.TupleMatcher { parts = [ps; p] } : Core.matcher))) (first_value, first_pattern) others in
                  (Core.Applied { function_ = (Core.GlobalRead { function_ = map } : Core.core); arguments = [values; (Core.FunctionValue { parameters = [pattern]; body = around after result; drops_result = false } : Core.core)] } : Core.core) in
            around before mapped

      let pure_of (monad : monad_functions) : Symbols.symbol option =
        match monad with
        | Binding { name = _; at = _; bind = _; pure = pure } -> Some pure
        | Mapping { name = _; at = _; map = _; product = _; pure = pure } -> pure

      let monad_functions (m : Symbols.module_symbol) (shown : string) (at : Parser.position) (context : context) : monad_functions =
        let module_name = Symbols.Symbols.module_name m in
        let member = fun what -> Lang.Options.option_filter (Collections.Maps.map_get ((context : context).environment : environment).functions (module_name ^ "." ^ what)) (fun it -> Globals.visible it context) in
        match let fk_arg1 = member "bind" in
        let fk_arg2 = member "pure" in
        let fk_arg3 = member "map" in
        let fk_arg4 = member "product" in
        (fk_arg1, fk_arg2, fk_arg3, fk_arg4) with
        | (Some bind, Some pure, _, _) -> (Binding { name = shown; at = at; bind = bind; pure = pure } : monad_functions)
        | (_, pure, Some map, Some product) -> (Mapping { name = shown; at = at; map = map; product = product; pure = pure } : monad_functions)
        | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (shown ^ " has neither bind and pure nor map and product, so it can't run a block; give it pure and bind, as Monad has"))) with
            | _ -> (assert false)

      let kind_of (e : Parser.expression) : string =
        match e with
        | Parser.Compiled { at = _ } -> "compiled code"
        | Parser.Assign { at = _; target = _; value = _ } -> "an assignment"
        | Parser.Handle { at = _; handler = _; block = _; parameters = _ } -> "a handler's block"
        | Parser.IntConstant { at = _; value = _ } -> "an Int"
        | Parser.FloatConstant { at = _; value = _ } -> "a Float"
        | Parser.BooleanConstant { at = _; value = _ } -> "a Boolean"
        | Parser.CharConstant { at = _; value = _ } -> "a Char"
        | Parser.Tuple { at = _; elements = _ } -> "a tuple"
        | Parser.Spread { at = _; list = _ } -> "a spread list"
        | Parser.StringTemplate { at = _; parts = _ } -> "a string"
        | Parser.Name { at = _; name = name } -> "the name " ^ name
        | Parser.ListOf { at = _; items = _ } -> "a list"
        | Parser.Call { at = _; callee = Parser.Name { at = _; name = name }; arguments = _; type_arguments = _ } -> "a call of " ^ name
        | Parser.Call { at = _; callee = Parser.Member { at = _; target = _; name = name }; arguments = _; type_arguments = _ } -> "a call of ." ^ name
        | Parser.Call { at = _; callee = _; arguments = _; type_arguments = _ } -> "a call"
        | Parser.Member { at = _; target = _; name = name } -> "." ^ name
        | Parser.Binary { at = _; operator = operator; left = _; right = _ } -> "'" ^ operator ^ "'"
        | Parser.Unary { at = _; operator = operator; operand = _ } -> "'" ^ operator ^ "'"
        | Parser.Lambda { at = _; parameters = _; body = _; ignores_arguments = _ } -> "a lambda"
        | Parser.Pipe { at = _; value = _; function_ = _ } -> "a pipe"
        | Parser.If { at = _; condition = _; then_ = _; otherwise = _; has_else = _ } -> "an if"
        | Parser.When { at = _; subject = _; branches = _ } -> "a when"
        | Parser.Block { at = _; statements = _; result = _; ends_in_binding = _ } -> "a block"
        | Parser.Monadic { at = _; monad = _; block = _ } -> "a module's block"

      let rec infer_block (at : Parser.position) (statements : Parser.statement list) (result : Parser.expression) (ends_in_binding : bool) (expected : Types.type_ option) (scope : scope) (monad : monad_functions option) (context : context) : typed =
        let whole = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
        let independent = match monad with
          | Some (Mapping { name = _; at = _; map = _; product = _; pure = _ }) -> true
          | _ -> false in
        let start = let fk_arg1 = Scopes.inside scope in
          let fk_arg2 = block_so_far_default_lines () in
          ({ scope = fk_arg1; rest = whole; steps = []; pending = []; after = None; assigned = false; lines = fk_arg2 } : block_so_far) in
        let done_ = List.fold_left (fun so_far statement -> line statement so_far independent monad context) start statements in
        if ends_in_binding && not (done_ : block_so_far).assigned then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context (Option.value (Option.map (fun it -> statement_position it) (Lang.Lists.list_last_or_none statements)) ~default:at) "a block must end with an expression, not a binding")) with
           | _ -> (assert false)) else ();
        match monad with
        | None -> let typed = infer result expected (done_ : block_so_far).scope context in
            ({ t = (typed : typed).t; spelled = None; core = around (done_ : block_so_far).lines (typed : typed).core } : typed)
        | Some m -> if independent && Lang.Lists.list_is_not_empty (done_ : block_so_far).steps then (let inner = bind_steps (done_ : block_so_far).pending (done_ : block_so_far).scope context in
               let (result_type, block_type) = combine m (done_ : block_so_far).steps at context in
               let result_core = check result result_type inner context in
               ({ t = block_type; spelled = None; core = around_monadic (done_ : block_so_far).lines result_core m } : typed)) else (match pure_of m with
               | None -> (match Effect.perform (Diagnostics.Abandoning_abandon (let fk_arg1 = position_of_monad m in
                      let fk_arg2 = name_of m ^ " has no pure, so its block needs a 'by' line" in
                      Globals.problem context fk_arg1 fk_arg2)) with
                    | _ -> (assert false))
               | Some pure -> match Types.Types.resolved (Globals.type_of pure (position_of_monad m) context) with
                   | Types.FunctionOf { parameters = [value]; result = pure_result; effects = _ } -> expect pure_result (done_ : block_so_far).rest (Symbols.Positions.of_ result) context;
                       let result_core = check result value (done_ : block_so_far).scope context in
                       ({ t = whole; spelled = None; core = around_monadic (done_ : block_so_far).lines (Core.Applied { function_ = (Core.GlobalRead { function_ = pure } : Core.core); arguments = [result_core] } : Core.core) m } : typed)
                   | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context (position_of_monad m) ((pure : Symbols.symbol).Symbols.name ^ " should take one value, as Monad's pure does"))) with
                       | _ -> (assert false))
      and line (statement : Parser.statement) (before : block_so_far) (independent : bool) (monad : monad_functions option) (context : context) : block_so_far =
        let so_far = if (independent && not (is_bind statement)) && Lang.Lists.list_is_not_empty (before : block_so_far).steps then (let fk_arg1 = bind_steps (before : block_so_far).pending (before : block_so_far).scope context in
             let fk_arg2 = Lang.Options.option_or_else (before : block_so_far).after (fun () -> Some (statement_position statement)) in
             ({ scope = fk_arg1; rest = (before : block_so_far).rest; steps = (before : block_so_far).steps; pending = []; after = fk_arg2; assigned = (before : block_so_far).assigned; lines = (before : block_so_far).lines } : block_so_far)) else before in
        let inner = (so_far : block_so_far).scope in
        match statement with
        | Parser.Evaluation { at = _; expression = e } -> let typed = infer e None inner context in
            { (with_scope so_far inner false : block_so_far) with lines = (so_far : block_so_far).lines @ [(RunStep { core = (typed : typed).core } : block_step)] }
        | Parser.Destructuring { at = at; pattern = pattern; value = value } -> let typed = infer value None inner context in
            let fk_arg1 = with_scope so_far (bind_pattern at pattern (typed : typed).t inner false context) false in
            let fk_arg2 = (so_far : block_so_far).lines @ [(BindStep { pattern = irrefutable_matcher pattern; value = (typed : typed).core } : block_step)] in
            { (fk_arg1 : block_so_far) with lines = fk_arg2 }
        | Parser.Bind { at = at; pattern = pattern; value = value } -> by_line at pattern value so_far independent monad context
        | Parser.Binding { at = at; name = name; parameters = parameters; value_type = value_type; value = value; variable = variable } -> binding at name parameters value_type value variable so_far context
      and binding (at : Parser.position) (name : string) (parameters : Parser.parameter list option) (value_type : Parser.type_ref option) (value : Parser.expression) (variable : bool) (so_far : block_so_far) (context : context) : block_so_far =
        let inner = (so_far : block_so_far).scope in
        let existing = Scopes.lookup inner name in
        let changed = if (not variable && Option.is_none parameters) && Option.is_none value_type then Option.bind existing (fun local -> Option.map (fun r -> (local, r)) (local : local).region) else None in
        match changed with
        | Some (local, region) -> let core = check value (local : local).t inner context in
            Effect.perform (Doing_perform (mutating region, at));
            { (with_scope so_far inner true : block_so_far) with lines = (so_far : block_so_far).lines @ [(RunStep { core = (Core.VarWritten { name = name; value = core } : Core.core) } : block_step)] }
        | None -> if Scopes.binds_here inner name then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ("'" ^ name ^ "' is already defined in this block; to change it, declare it with var " ^ name ^ " = ..."))) with
               | _ -> (assert false)) else ();
            match parameters with
            | None -> let declared = Option.map (fun t -> Definitions.Conversion.type_of t (Globals.type_context context) ((context : context).environment : environment).definitions) value_type in
                let typed = infer value declared inner context in
                Option.iter (fun d -> assign value typed d context) declared;
                let region = if variable then Some (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) else None in
                let step = if variable then (VarStep { name = name; value = (typed : typed).core } : block_step) else (BindStep { pattern = (Core.NameMatcher { name = name } : Core.matcher); value = (typed : typed).core } : block_step) in
                { (with_scope so_far (Scopes.bind inner name (let fk_arg1 = local_default_narrowed () in
                  let fk_arg2 = local_default_hides () in
                  ({ t = (typed : typed).t; region = region; narrowed = fk_arg1; hides = fk_arg2 } : local))) false : block_so_far) with lines = (so_far : block_so_far).lines @ [step] }
            | Some ps -> check_distinct (List.map (fun p -> ((p : Parser.parameter).Parser.name, (p : Parser.parameter).Parser.at)) ps) context;
                let row = ({ Types.labels = []; rest = Some (Effect.perform (Types.Solving_fresh ())) } : Types.row) in
                let parameter_types = List.map (fun p -> let fk_arg1 = Option.map (fun it -> parameter_type it row context) (p : Parser.parameter).Parser.parameter_type in
                     let fk_arg2 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
                     Option.value fk_arg1 ~default:fk_arg2) ps in
                let result = let fk_arg1 = Option.map (fun t -> Definitions.Conversion.type_of t (Globals.type_context context) ((context : context).environment : environment).definitions) value_type in
                  let fk_arg2 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
                  Option.value fk_arg1 ~default:fk_arg2 in
                let with_function = Scopes.bind inner name (let fk_arg1 = local_default_region () in
                   let fk_arg2 = local_default_narrowed () in
                   let fk_arg3 = local_default_hides () in
                   ({ t = (Types.FunctionOf { parameters = parameter_types; result = result; effects = row } : Types.type_); region = fk_arg1; narrowed = fk_arg2; hides = fk_arg3 } : local)) in
                let body = let fk_arg1 = Lang.Lists.list_zip ps parameter_types in
                  let fk_arg2 = Scopes.inside with_function in
                  List.fold_left (fun s entry -> let (p, t) = entry in
                     Scopes.bind s (p : Parser.parameter).Parser.name (let fk_arg1 = local_default_region () in
                      let fk_arg2 = local_default_narrowed () in
                      let fk_arg3 = local_default_hides () in
                      ({ t = t; region = fk_arg1; narrowed = fk_arg2; hides = fk_arg3 } : local))) fk_arg2 fk_arg1 in
                let core = doing_in row context (fun () -> check value result body context) in
                let fk_arg1 = with_scope so_far with_function false in
                let fk_arg2 = (so_far : block_so_far).lines @ [(FunctionStep { name = name; parameters = List.map (fun p -> (Core.NameMatcher { name = (p : Parser.parameter).Parser.name } : Core.matcher)) ps; body = core } : block_step)] in
                { (fk_arg1 : block_so_far) with lines = fk_arg2 }
      and by_line (at : Parser.position) (pattern : Parser.pattern) (value : Parser.expression) (so_far : block_so_far) (independent : bool) (monad : monad_functions option) (context : context) : block_so_far =
        match monad with
        | None -> (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at "'by' needs a block to bind in, such as Options { ... }, directly around it")) with
             | _ -> (assert false))
        | Some m -> if independent then (Option.iter (fun after_at -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context after_at (name_of m ^ " has no bind, so its 'by' lines go together: move this line above the first 'by' or below the last"))) with
                  | _ -> (assert false)) (so_far : block_so_far).after;
               let refs = Symbols.References.of_ value [] in
               Option.iter (fun used -> match Effect.perform (Diagnostics.Abandoning_abandon (let fk_arg1 = Symbols.Positions.of_ value in
                    let fk_arg2 = name_of m ^ " has no bind, so a step can't use " ^ used ^ " from an earlier step" in
                    Globals.problem context fk_arg1 fk_arg2)) with
                  | _ -> (assert false)) (List.find_opt (fun it -> List.mem it refs) (List.concat_map (fun (_, p, _) -> Symbols.References.names_in p) (so_far : block_so_far).pending));
               let (value_type, held, core) = step m value (so_far : block_so_far).scope context in
               ({ scope = (so_far : block_so_far).scope; rest = (so_far : block_so_far).rest; steps = (so_far : block_so_far).steps @ [(value_type, held)]; pending = (so_far : block_so_far).pending @ [(at, pattern, held)]; after = (so_far : block_so_far).after; assigned = false; lines = (so_far : block_so_far).lines @ [(ByStep { pattern = irrefutable_matcher pattern; value = core } : block_step)] } : block_so_far)) else (let (value_type, next, result) = bind_type m context in
               expect result (so_far : block_so_far).rest at context;
               let wanted = generic_text value_type in
               let actual = infer value (Some value_type) (so_far : block_so_far).scope context in
               if not (is_subtype (actual : typed).t value_type context) then (match Effect.perform (Diagnostics.Abandoning_abandon (let fk_arg1 = Symbols.Positions.of_ value in
                    let fk_arg2 = let fk_arg1 = name_of m in
                      let fk_arg2 = Types.TypeText.shown (actual : typed).t in
                      fk_arg1 ^ " binds " ^ wanted ^ ", but this is " ^ fk_arg2 in
                    Globals.problem context fk_arg1 fk_arg2)) with
                  | _ -> (assert false)) else ();
               let (next_value, next_result) = match next with
                 | Types.FunctionOf { parameters = [p]; result = r; effects = _ } -> (p, r)
                 | _ -> let fk_arg1 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
                     let fk_arg2 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
                     (fk_arg1, fk_arg2) in
               let fk_arg1 = bind_pattern at pattern next_value (so_far : block_so_far).scope true context in
               let fk_arg2 = (so_far : block_so_far).lines @ [(ByStep { pattern = irrefutable_matcher pattern; value = (actual : typed).core } : block_step)] in
               ({ scope = fk_arg1; rest = next_result; steps = (so_far : block_so_far).steps; pending = (so_far : block_so_far).pending; after = (so_far : block_so_far).after; assigned = false; lines = fk_arg2 } : block_so_far))
      and bind_steps (pending : (Parser.position * Parser.pattern * Types.type_) list) (scope : scope) (context : context) : scope =
        List.fold_left (fun s entry -> let (at, pattern, t) = entry in
           bind_pattern at pattern t s true context) scope pending
      and bind_pattern (at : Parser.position) (pattern : Parser.pattern) (t : Types.type_) (scope : scope) (is_by : bool) (context : context) : scope =
        let names = Symbols.References.names_in pattern in
        check_distinct (List.map (fun it -> (it, at)) names) context;
        Option.iter (fun name -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ("'" ^ name ^ "' is already defined in this block"))) with
           | _ -> (assert false)) (List.find_opt (fun it -> Scopes.binds_here scope it) names);
        if not (irrefutable pattern) then (let what = if is_by then "'by'" else "a destructuring binding" in
           match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (what ^ " takes only names and '_'; use 'when' to match other patterns"))) with
           | _ -> (assert false)) else ();
        let bound = (check_pattern pattern t (Scopes.inside scope) None context : checked_pattern).scope in
        Scopes.bind_all scope (Collections.Maps.map_to_list (bound : scope).own)
      and infer_monadic (at : Parser.position) (monad : Parser.expression) (block : Parser.expression) (scope : scope) (context : context) : typed =
        let monad_at = Symbols.Positions.of_ monad in
        let name = dotted_unbound monad scope in
        let shown = Option.value name ~default:"this" in
        let found = Option.bind name (fun n -> Resolution.Lookups.found (Resolution.Lookups.module_named n (context : context).place (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace (Resolution.Skipping : Resolution.strictness))) in
        match found with
        | None -> (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context monad_at (let fk_arg1 = Option.value name ~default:"null" in
                let fk_arg2 = Option.value (Option.map (fun n -> Resolution.ImportHints.for_name n (((context : context).environment : environment).definitions : Definitions.definitions).Definitions.namespace) name) ~default:"" in
                shown ^ " isn't a module, so " ^ fk_arg1 ^ " { ... } has nothing to bind with" ^ fk_arg2))) with
             | _ -> (assert false))
        | Some m -> let effect_ = match m with
              | Symbols.DeclaredModule { symbol = s } -> Option.map (fun spec -> (s, spec)) (Lang.Options.option_filter (Collections.Maps.map_get ((context : context).environment : environment).module_specs (s : Symbols.symbol).Symbols.name) (fun _ -> is_effect_module m context))
              | Symbols.PackageModule { name = _ } -> None in
            match effect_ with
            | Some (s, spec) -> (match module_handler s spec at context with
                 | Types.Handler { effect_ = effect_name; arguments = [answer; answers] } -> let handled = handling effect_name [] answer answers block None scope at context in
                     ({ t = (handled : typed).t; spelled = None; core = (Core.Handled { effect_ = spec; handler = (Core.ModuleHandler { module_ = s; effect_ = spec } : Core.core); block = (handled : typed).core } : Core.core) } : typed)
                 | other -> ({ t = other; spelled = None; core = (Core.Pending { what = "a module's handler" } : Core.core) } : typed))
            | None -> let functions = monad_functions m shown monad_at context in
                match block with
                | Parser.Block { at = block_at; statements = statements; result = result; ends_in_binding = ends_in_binding } -> infer_block block_at statements result ends_in_binding None scope (Some functions) context
                | other -> infer other None scope context
      and step (monad : monad_functions) (value : Parser.expression) (scope : scope) (context : context) : Types.type_ * Types.type_ * Core.core =
        match monad with
        | Mapping { name = name; at = _; map = map; product = _; pure = _ } -> let (mapped, _, held, _) = map_type monad map context in
            let wanted = generic_text mapped in
            let actual = infer value (Some mapped) scope context in
            if not (is_subtype (actual : typed).t mapped context) then (match Effect.perform (Diagnostics.Abandoning_abandon (let fk_arg1 = Symbols.Positions.of_ value in
                 let fk_arg2 = name ^ " maps " ^ wanted ^ ", but this is " ^ Types.TypeText.shown (actual : typed).t in
                 Globals.problem context fk_arg1 fk_arg2)) with
               | _ -> (assert false)) else (mapped, held, (actual : typed).core)
        | Binding { name = _; at = _; bind = _; pure = _ } -> let fk_arg1 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
            let fk_arg2 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
            (fk_arg1, fk_arg2, (Core.Pending { what = "a step" } : Core.core))
      and infer_call (at : Parser.position) (callee : Parser.expression) (arguments : call_argument list) (type_arguments : Parser.type_ref list) (expected : Types.type_ option) (scope : scope) (context : context) : typed =
        match lifted_module at context with
        | Some made -> module_as_value made at context
        | None -> infer_unlifted at callee arguments type_arguments expected scope context
      and infer_unlifted (at : Parser.position) (callee : Parser.expression) (arguments : call_argument list) (type_arguments : Parser.type_ref list) (expected : Types.type_ option) (scope : scope) (context : context) : typed =
        match declared_callee callee scope context with
        | Some global when Symbols.Signatures.is_function global -> call_declared at global arguments type_arguments scope context
        | declared -> let callable = if Option.is_some declared then None else operation_called callee scope context in
            match callable with
            | Some operation -> without_type_arguments type_arguments at context (call_operation at operation arguments scope context)
            | None -> without_type_arguments type_arguments at context (call_other at callee declared arguments type_arguments expected scope context)
      and call_declared (at : Parser.position) (global : Symbols.symbol) (arguments : call_argument list) (type_arguments : Parser.type_ref list) (scope : scope) (context : context) : typed =
        match Types.Types.resolved (Globals.type_for_call global type_arguments at context) with
        | Types.FunctionOf { parameters = parameter_types; result = result; effects = effects } -> let (parameters, owners) = parameter_defaults global context in
            let given = with_defaults at arguments parameters (global : Symbols.symbol).Symbols.name true owners in
            let order = let fk_arg1 = List.map (fun (name, _) -> name) parameters in
              let fk_arg2 = "'" ^ Symbols.Symbols.simple_name global ^ "'" in
              argument_order given fk_arg1 at fk_arg2 context in
            let cores = check_arguments given order parameter_types scope context in
            Effect.perform (Doing_perform (effects, at));
            ({ t = result; spelled = None; core = Core.Cores.in_written_order cores order (fun args -> if Symbols.Signatures.is_external global then (Core.ExternalApplied { function_ = global; arguments = args } : Core.core) else (Core.Applied { function_ = (Core.GlobalRead { function_ = global } : Core.core); arguments = args } : Core.core)) } : typed)
        | other -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (let fk_arg1 = Symbols.Symbols.simple_name global in
               let fk_arg2 = Types.TypeText.shown other in
               "'" ^ fk_arg1 ^ "' is a " ^ fk_arg2 ^ ", not a function"))) with
            | _ -> (assert false)
      and call_other (at : Parser.position) (callee : Parser.expression) (declared : Symbols.symbol option) (arguments : call_argument list) (type_arguments : Parser.type_ref list) (expected : Types.type_ option) (scope : scope) (context : context) : typed =
        let unbound = fun name -> Option.is_none declared && Option.is_none (Scopes.lookup scope name) in
        let handler_spec = match callee with
          | Parser.Name { at = _; name = name } when unbound name -> effect_spec_named name context
          | _ -> None in
        let constructed = match callee with
          | Parser.Name { at = callee_at; name = name } when Option.is_none handler_spec && unbound name -> Option.map (fun shape -> construct at shape name arguments expected scope context) (constructor_shape name expected callee_at false None true scope context)
          | Parser.Member { at = member_at; target = target; name = name } when Option.is_none declared -> (match qualified_case target scope context with
               | Some qualifier -> (match constructor_shape name expected member_at false (Some qualifier) true scope context with
                    | Some shape -> Some (construct at shape (qualifier ^ "." ^ name) arguments expected scope context)
                    | None -> match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context member_at (qualifier ^ " has no '" ^ name ^ "'"))) with
                        | _ -> (assert false))
               | None -> None)
          | _ -> None in
        match handler_spec with
        | Some spec -> make_handler at spec arguments scope context
        | None -> match constructed with
            | Some typed -> typed
            | None -> let method_ = match callee with
                  | Parser.Member { at = member_at; target = target; name = name } -> infer_method_call at member_at target name arguments type_arguments scope context
                  | _ -> (CalledField { arguments = arguments } : method_call) in
                match method_ with
                | CalledMethod { typed = typed } -> typed
                | CalledField { arguments = given } -> call_value at callee given scope context
      and call_value (at : Parser.position) (callee : Parser.expression) (arguments : call_argument list) (scope : scope) (context : context) : typed =
        if List.exists (fun it -> Option.is_some (it : call_argument).name) arguments then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at "named arguments need a call to a declared function or type")) with
           | _ -> (assert false)) else ();
        let callee_typed = infer callee None scope context in
        let (parameters, result, effects) = match Types.Types.resolved (callee_typed : typed).t with
          | Types.FunctionOf { parameters = ps; result = r; effects = row } -> (ps, r, row)
          | Types.Variable { variable = v } -> let (ps, r, row) = let fk_arg1 = List.map (fun it -> (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_)) arguments in
                let fk_arg2 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
                let fk_arg3 = ({ Types.labels = []; rest = Some (Effect.perform (Types.Solving_fresh ())) } : Types.row) in
                (fk_arg1, fk_arg2, fk_arg3) in
              Types.Unification.unify (Types.Variable { variable = v } : Types.type_) (Types.FunctionOf { parameters = ps; result = r; effects = row } : Types.type_);
              (ps, r, row)
          | other -> match Effect.perform (Diagnostics.Abandoning_abandon (let fk_arg1 = Symbols.Positions.of_ callee in
                let fk_arg2 = "a " ^ Types.TypeText.shown other ^ " is not a function" in
                Globals.problem context fk_arg1 fk_arg2)) with
              | _ -> (assert false) in
        if let fk_arg1 = List.length parameters in
        let fk_arg2 = List.length arguments in
        fk_arg1 <> fk_arg2 then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (let fk_arg1 = string_of_int (List.length parameters) in
              let fk_arg2 = string_of_int (List.length arguments) in
              "this function takes " ^ fk_arg1 ^ " arguments, not " ^ fk_arg2))) with
           | _ -> (assert false)) else ();
        let is_builtin = fun name -> match callee with
            | Parser.Name { at = _; name = called } when called = name -> Option.is_none (Scopes.lookup scope name) && Option.is_none (Resolution.Lookups.found (Globals.find name context (Resolution.Skipping : Resolution.strictness)))
            | _ -> false in
        let is_assert_equals = is_builtin "assertEquals" in
        let order = if is_assert_equals then [1; 0] else List.mapi (fun i _ -> i) arguments in
        let checked = Lang.Lists.list_map_not_null order (fun i -> match let fk_arg1 = Lang.Lists.list_get_or_none arguments i in
             let fk_arg2 = Lang.Lists.list_get_or_none parameters i in
             (fk_arg1, fk_arg2) with
             | (Some argument, Some t) -> Some (i, check_argument (argument : call_argument).value t scope context)
             | _ -> None) in
        Effect.perform (Doing_perform (effects, at));
        let cores = List.map (fun (_, core) -> core) (Lang.Lists.list_sorted_by checked (fun (i, _) -> i)) in
