              | Some args -> if let fk_arg1 = List.length args in
                  let fk_arg2 = List.length (shape : constructor_shape).field_types in
                  fk_arg1 <> fk_arg2 then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at (let fk_arg1 = string_of_int (List.length (shape : constructor_shape).field_types) in
                        let fk_arg2 = string_of_int (List.length args) in
                        "'" ^ name ^ "' has " ^ fk_arg1 ^ " fields, not " ^ fk_arg2))) with
                     | _ -> (assert false)) else ();
                  let (s, m, matchers) = check_each args (shape : constructor_shape).field_types scope context in
                  (s, m, Some matchers)
              | None -> if not is_check && Lang.Lists.list_is_not_empty (shape : constructor_shape).field_types then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at ("'" ^ name ^ "' has fields: match them with " ^ name ^ "(...) or use 'is " ^ name ^ "'"))) with
                     | _ -> (assert false)) else (scope, List.map (fun it -> [Coverage.Coverage.anything]) (shape : constructor_shape).field_types, None) in
            let fk_arg1 = narrowed_to shape is_check after subject context in
            let fk_arg2 = List.map (fun it -> ({ Coverage.shape = Some (shape_of shape); fields = it } : Coverage.matches)) (product field_matches) in
            ({ scope = fk_arg1; matches = fk_arg2; matcher = (Core.CaseMatcher { constructor = (shape : constructor_shape).constructor; fields = field_matchers; narrowed = narrowed_local } : Core.matcher) } : checked_pattern)
      and check (e : Parser.expression) (expected : Types.type_) (scope : scope) (context : context) : Core.core =
        let typed = infer e (Some expected) scope context in
        assign e typed expected context;
        match let fk_arg1 = Types.Types.resolved (typed : typed).t in
        let fk_arg2 = Types.Types.resolved expected in
        (fk_arg1, fk_arg2) with
        | (Types.Named { name = narrower; arguments = _; region = _ }, Types.Named { name = wider; arguments = _; region = _ }) when (narrower <> wider && Option.is_some (case_type_named narrower context)) && Option.is_some (case_type_named wider context) -> (Core.Widened { value = (typed : typed).core; t = expected } : Core.core)
        | _ -> (typed : typed).core
      and infer_when (at : Parser.position) (subject : Parser.expression option) (branches : Parser.branch list) (expected : Types.type_ option) (scope : scope) (context : context) : typed =
        let wanted = known expected in
        let (bodies, core) = match subject with
          | None -> if List.is_empty branches || Option.value (Option.map (fun it -> Option.is_some (it : Parser.branch).Parser.condition) (Lang.Lists.list_last_or_none branches)) ~default:true then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context at "a 'when' without a subject needs an 'else' branch")) with
                 | _ -> (assert false)) else ();
              let checked = List.map (fun branch -> let condition = Option.map (fun it -> check it Types.Types.boolean scope context) (branch : Parser.branch).Parser.condition in
                   let (body, body_core) = branch_body (branch : Parser.branch).Parser.body wanted scope context in
                   (body, condition, body_core)) branches in
              let fk_arg1 = List.map (fun (body, _, _) -> body) checked in
              let fk_arg2 = conditions (List.map (fun (_, condition, body_core) -> (condition, body_core)) checked) in
              (fk_arg1, fk_arg2)
          | Some s -> let subject_typed = infer s None scope context in
              let checked = List.map (fun branch -> check_branch branch s (subject_typed : typed).t wanted scope context) branches in
              let covered = List.concat_map (fun (_, c) -> (c : checked_branch).matches) (List.filter (fun (branch, _) -> Option.is_none (branch : Parser.branch).Parser.guard) (Lang.Lists.list_zip branches checked)) in
              Effect.perform (Covering_cover ({ file = ((((context : context).place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; patterns = covered; subject = (subject_typed : typed).t } : pending_when));
              let fk_arg1 = List.map (fun c -> (c : checked_branch).body) checked in
              let fk_arg2 = (Core.Matched { subject = (subject_typed : typed).core; branches = List.map (fun c -> (c : checked_branch).core) checked } : Core.core) in
              (fk_arg1, fk_arg2) in
        match wanted with
        | Some t -> ({ t = t; spelled = None; core = core } : typed)
        | None -> ({ t = join (Lang.Lists.list_map_not_null bodies (fun it -> it)) at context; spelled = None; core = core } : typed)
      and branch_body (body : Parser.expression) (wanted : Types.type_ option) (scope : scope) (context : context) : (Parser.expression * typed) option * Core.core =
        match wanted with
        | Some t -> (None, check body t scope context)
        | None -> let typed = infer body None scope context in
            (Some (body, typed), (typed : typed).core)
      and check_branch (branch : Parser.branch) (subject : Parser.expression) (subject_type : Types.type_) (wanted : Types.type_ option) (scope : scope) (context : context) : checked_branch =
        if List.length (branch : Parser.branch).Parser.patterns > 1 && List.exists (fun it -> Lang.Lists.list_is_not_empty (Symbols.References.names_in it)) (branch : Parser.branch).Parser.patterns then (match Effect.perform (Diagnostics.Abandoning_abandon (Globals.problem context (branch : Parser.branch).Parser.at "a branch with several patterns can't bind names")) with
           | _ -> (assert false)) else ();
        let (inner, matches, matchers) = List.fold_left (fun acc p -> let (s, found, ms) = acc in
             let checked = check_pattern p subject_type s (Some subject) context in
             ((checked : checked_pattern).scope, found @ (checked : checked_pattern).matches, ms @ [(checked : checked_pattern).matcher])) (Scopes.inside scope, [], []) (branch : Parser.branch).Parser.patterns in
        let guard = Option.map (fun it -> check it Types.Types.boolean inner context) (branch : Parser.branch).Parser.guard in
        let (body, body_core) = branch_body (branch : Parser.branch).Parser.body wanted inner context in
        ({ body = body; matches = (if List.is_empty (branch : Parser.branch).Parser.patterns then [Coverage.Coverage.anything] else matches); core = ({ Core.patterns = matchers; guard = guard; body = body_core } : Core.match_branch) } : checked_branch)

      let check_body (s : signature) (environment : environment) : Core.core_function option =
        let f = (s : signature).function_ in
        let context = context_of f (s : signature).type_variables environment (match (s : signature).t with
           | Types.FunctionOf { parameters = types; result = _; effects = _ } -> named (Option.value (Symbols.Signatures.parameters_of f) ~default:[]) types
           | _ -> Collections.Maps.empty_map ()) in
        if Symbols.Signatures.is_compiled f then (let does = if Defaults.is_default f then [] else allowed f environment in
           Types.Unification.unify_rows (s : signature).row (let fk_arg1 = List.map (fun it -> ({ Types.name = it; arguments = [] } : Types.effect_label)) does in
            let fk_arg2 = Some (Effect.perform (Types.Solving_fresh ())) in
            ({ Types.labels = fk_arg1; rest = fk_arg2 } : Types.row));
           None) else if Symbols.Signatures.is_external f then (let parameters = match (s : signature).t with
               | Types.FunctionOf { parameters = ps; result = _; effects = _ } -> ps
               | _ -> [] in
             Types.Unification.unify_rows (s : signature).row (declared_row f parameters environment);
             None) else (match Symbols.Signatures.body_of f with
             | None -> None
             | Some body -> doing_in (s : signature).row context (fun () -> let parameters = Option.value (Symbols.Signatures.parameters_of f) ~default:[] in
                    match (s : signature).t with
                    | Types.FunctionOf { parameters = parameter_types; result = result; effects = _ } -> let scope = List.fold_left (fun scope entry -> let (p, t) = entry in
                             Scopes.bind scope (p : Parser.parameter).Parser.name (let fk_arg1 = local_default_region () in
                              let fk_arg2 = local_default_narrowed () in
                              let fk_arg3 = local_default_hides () in
                              ({ t = t; region = fk_arg1; narrowed = fk_arg2; hides = fk_arg3 } : local))) Scopes.empty (Lang.Lists.list_zip parameters parameter_types) in
                        Some (let fk_arg1 = List.map (fun it -> (it : Parser.parameter).Parser.name) parameters in
                         let fk_arg2 = check body result scope context in
                         ({ Core.parameters = fk_arg1; body = fk_arg2 } : Core.core_function))
                    | other -> Some ({ Core.parameters = []; body = check body other Scopes.empty context } : Core.core_function)))

      let masked (row : Types.row) (t : Types.type_) : Types.row =
        let flat = Types.Types.flattened row in
        let visible = regions_in t (Some row) in
        ({ Types.labels = List.filter (fun label -> (label : Types.effect_label).Types.name <> Types.Types.mutating || (match (label : Types.effect_label).Types.arguments with
            | region :: _ -> (match Types.Types.resolved region with
                 | Types.Variable { variable = v } -> List.mem (Types.Variable { variable = v } : Types.type_) visible
                 | _ -> true)
            | [] -> true)) (flat : Types.row).Types.labels; rest = (flat : Types.row).Types.rest } : Types.row)

      let check_declared_arguments (s : signature) (done_ : Types.row) (environment : environment) : unit =
        let f = (s : signature).function_ in
        let context = context_of f (s : signature).type_variables environment (context_of_default_value_parameters ()) in
        let namespace = ((environment : environment).definitions : Definitions.definitions).Definitions.namespace in
        List.iter (fun a -> match Lang.Options.option_filter (Annotations.Annotations.declaration_of a ({ Resolution.file = (f : Symbols.symbol).Symbols.file; path = (f : Symbols.symbol).Symbols.path } : Resolution.place) namespace) (fun it -> Symbols.Symbols.is_spec it) with
           | Some effect_ -> let says = List.map (fun t -> Definitions.Conversion.type_of t (Globals.type_context context) (environment : environment).definitions) (a : Parser.annotation).Parser.type_arguments in
               Option.iter (fun did -> if not (List.for_all (fun (x, y) -> Types.Unification.unify x y) (Lang.Lists.list_zip (did : Types.effect_label).Types.arguments says)) then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((f : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = (let fk_arg1 = Symbols.Symbols.simple_name f in
                       let fk_arg2 = Symbols.Symbols.simple_name effect_ in
                       let fk_arg3 = String.concat ", " (List.map Fun.id (List.map (fun it -> Types.TypeText.shown it) (did : Types.effect_label).Types.arguments)) in
                       let fk_arg4 = String.concat ", " (List.map Fun.id (List.map (fun it -> Types.TypeText.shown it) says)) in
                       "'" ^ fk_arg1 ^ "' does @" ^ fk_arg2 ^ "<" ^ fk_arg3 ^ ">, but says <" ^ fk_arg4 ^ ">") } : Diagnostics.diagnostic)) with
                     | _ -> (assert false)) else ()) (List.find_opt (fun it -> (it : Types.effect_label).Types.name = (effect_ : Symbols.symbol).Symbols.name) (Types.Types.flattened done_ : Types.row).Types.labels)
           | None -> ()) (List.filter (fun a -> Lang.Lists.list_is_not_empty (a : Parser.annotation).Parser.type_arguments) ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations)

      let needs_handler (name : string) (environment : environment) : bool =
        Option.value (Option.map (fun spec -> Annotations.Annotations.is_effect spec ((environment : environment).definitions : Definitions.definitions).Definitions.namespace && Lang.Lists.list_is_not_empty (spec_values spec)) (Collections.Maps.map_get ((((environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.specs name)) ~default:false

      let default_handler (name : string) (environment : environment) : Symbols.symbol option =
        let namespace = ((environment : environment).definitions : Definitions.definitions).Definitions.namespace in
        Option.bind (Collections.Maps.map_get ((namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.specs name) (fun spec -> let place = ({ Resolution.file = (spec : Symbols.symbol).Symbols.file; path = (spec : Symbols.symbol).Symbols.path } : Resolution.place) in
           Option.bind (List.find_opt (fun a -> Option.map (fun it -> (it : Symbols.symbol).Symbols.name) (Annotations.Annotations.declaration_of a place namespace) = Some "fckt.lang.HandledBy") ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations) (fun a -> match (a : Parser.annotation).Parser.arguments with
              | [({ Parser.name = _; value = Parser.Reference { at = _; name = module_name; type_arguments = _; arguments = _ } } : Parser.annotation_argument)] -> (match Resolution.Lookups.found (Resolution.Lookups.module_named module_name place namespace (Resolution.Skipping : Resolution.strictness)) with
                   | Some (Symbols.DeclaredModule { symbol = m }) -> Some m
                   | _ -> None)
              | _ -> None))

      let check_main_handled (main : Symbols.symbol) (done_ : Types.row) (environment : environment) : unit =
        List.iter (fun label -> if needs_handler (label : Types.effect_label).Types.name environment && Option.is_none (default_handler (label : Types.effect_label).Types.name environment) then (let effect_ = Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) (label : Types.effect_label).Types.name ".")) ~default:(label : Types.effect_label).Types.name in
              match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((main : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((main : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = "main does @" ^ effect_ ^ ", but nothing handles it: run it in a handler, like " ^ effect_ ^ "(...) { ... }" } : Diagnostics.diagnostic)) with
              | _ -> (assert false)) else ()) (Types.Types.flattened done_ : Types.row).Types.labels

      let check_effects (f : Symbols.symbol) (done_ : Types.row) (environment : environment) : unit =
        if (f : Symbols.symbol).Symbols.name = "main" || Defaults.is_default f then () else if Option.is_some (Resolution.Names.enclosing_application (f : Symbols.symbol).Symbols.path ((environment : environment).definitions : Definitions.definitions).Definitions.namespace) then () else (let theirs = parameter_effects (f : Symbols.symbol).Symbols.path environment in
             let did = List.filter (fun it -> not (List.mem it theirs)) (Lang.Lists.list_distinct (Types.Types.effect_names done_)) in
             let own = Symbols.Symbols.simple_name f in
             if not (Symbols.Signatures.is_function f) then if Lang.Lists.list_is_not_empty did then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((f : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = "'" ^ own ^ "' does " ^ Doings.shown did ^ ", but a top-level value runs when the program starts; make it a function: " ^ own ^ "() = ..." } : Diagnostics.diagnostic)) with
                  | _ -> (assert false)) else () else (let undeclared = List.filter (fun it -> not (List.mem it (allowed f environment))) did in
                if List.is_empty undeclared then () else (match ceiling (f : Symbols.symbol).Symbols.path environment with
                   | Some (m, effects) -> (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((f : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = (let fk_arg1 = Doings.shown undeclared in
                          let fk_arg2 = Symbols.Symbols.simple_name m in
                          let fk_arg3 = allows effects in
                          "'" ^ own ^ "' does " ^ fk_arg1 ^ ", but it's in " ^ fk_arg2 ^ ", which may only " ^ fk_arg3) } : Diagnostics.diagnostic)) with
                        | _ -> (assert false))
                   | None when ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.visibility = (Parser.Private : Parser.visibility) -> ()
                   | None -> match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((f : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = (let fk_arg1 = Doings.shown undeclared in
                         let fk_arg2 = Doings.shown undeclared in
                         "'" ^ own ^ "' does " ^ fk_arg1 ^ ", so it must say so: " ^ fk_arg2 ^ " " ^ own ^ "(...)") } : Diagnostics.diagnostic)) with
                       | _ -> (assert false))))

      let check_type_parameters_stayed (s : signature) : unit =
        let f = (s : signature).function_ in
        List.fold_left (fun seen entry -> let (name, v) = entry in
           if String.starts_with ~prefix:"@" name then (let row = Types.Types.as_row (Types.Variable { variable = v } : Types.type_) in
              match (row : Types.row).Types.rest with
              | Some rest when List.is_empty (row : Types.row).Types.labels && not (List.mem (Types.Variable { variable = rest } : Types.type_) seen) -> seen @ [(Types.Variable { variable = rest } : Types.type_)]
              | _ -> match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((f : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = (let fk_arg1 = Symbols.Symbols.simple_name f in
                    let fk_arg2 = Doings.shown (List.map (fun it -> (it : Types.effect_label).Types.name) (row : Types.row).Types.labels) in
                    "effect parameter " ^ name ^ " of '" ^ fk_arg1 ^ "' always does " ^ fk_arg2 ^ " here") } : Diagnostics.diagnostic)) with
                  | _ -> (assert false)) else (match Types.Types.resolved (Types.Variable { variable = v } : Types.type_) with
              | Types.Variable { variable = w } when not (List.mem (Types.Variable { variable = w } : Types.type_) seen) -> seen @ [(Types.Variable { variable = w } : Types.type_)]
              | other -> match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((f : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = "type parameter " ^ name ^ " of '" ^ (f : Symbols.symbol).Symbols.name ^ "' is always " ^ Types.TypeText.shown other ^ " here" } : Diagnostics.diagnostic)) with
                  | _ -> (assert false))) [] (s : signature).type_variables;
        ()

      let rec mentions (ref : Parser.type_ref) (p : string) : bool =
        match ref with
        | Parser.NamedType { at = _; name = name; arguments = arguments } -> name = p || List.exists (fun it -> mentions it p) arguments
        | Parser.FunctionType { at = _; parameters = parameters; result = result; effects = effects } -> (List.exists (fun it -> mentions it p) parameters || mentions result p) || List.exists (fun it -> "@" ^ (it : Parser.annotation).Parser.name = p) effects
        | Parser.TupleType { at = _; elements = elements } -> List.exists (fun it -> mentions it p) elements
        | Parser.EffectsType { at = _; effects = effects } -> List.exists (fun it -> "@" ^ (it : Parser.annotation).Parser.name = p) effects
        | Parser.GivenType { at = _; name = _; given = given } -> mentions given p

      let rec only (ref : Parser.type_ref) (p : string) (positive : bool) (own : string) : bool =
        match ref with
        | Parser.NamedType { at = _; name = name; arguments = arguments } -> if name = p then positive else if Lang.Lists.list_none arguments (fun it -> mentions it p) then true else if List.mem name ["List"; "Option"; "Result"; "Lazy"] || name = own then List.for_all (fun it -> only it p positive own) arguments else false
        | Parser.FunctionType { at = _; parameters = parameters; result = result; effects = effects } -> (List.for_all (fun it -> only it p (not positive) own) parameters && only result p positive own) && (positive || Lang.Lists.list_none effects (fun it -> "@" ^ (it : Parser.annotation).Parser.name = p))
        | Parser.TupleType { at = _; elements = elements } -> List.for_all (fun it -> only it p positive own) elements
        | Parser.EffectsType { at = _; effects = effects } -> positive || Lang.Lists.list_none effects (fun it -> "@" ^ (it : Parser.annotation).Parser.name = p)
        | Parser.GivenType { at = _; name = _; given = given } -> only given p positive own

      let holds_only_given (parameters : string list) (fields : Parser.field list) (index : int) (own : string) : bool =
        match Lang.Lists.list_get_or_none parameters index with
        | Some p -> List.for_all (fun f -> if (f : Parser.field).Parser.variable then not (mentions (f : Parser.field).Parser.field_type p) else only (f : Parser.field).Parser.field_type p true own) fields
        | None -> false

      let last_part (name : string) : string =
        Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".")) ~default:name

      let is_covariant (name : string) (index : int) (table : Symbols.symbol_table) : bool =
        if List.mem name ["List"; "Option"; "Result"; "Lazy"] then true else (match Option.map (fun it -> ((it : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition) (Lang.Options.option_or_else (Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.records name) (fun () -> Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.case_types name)) with
           | Some (Parser.RecordDefinition { type_parameters = parameters; fields = fields; private_constructor = _; annotation = _; external_ = None }) -> holds_only_given parameters fields index (last_part name)
           | Some (Parser.CasesDefinition { type_parameters = parameters; cases = cases; case_refs = _; includes = _ }) -> let fk_arg1 = List.concat_map (fun it -> (it : Parser.case_definition).Parser.fields) cases in
               let fk_arg2 = last_part name in
               holds_only_given parameters fk_arg1 index fk_arg2
           | _ -> false)

      let rec widened_in (t : Types.type_) (positive : bool) (open_ : Types.row -> Types.row) (table : Symbols.symbol_table) : Types.type_ =
        match t with
        | Types.FunctionOf { parameters = parameters; result = result; effects = effects } -> let fk_arg1 = List.map (fun it -> widened_in it (not positive) open_ table) parameters in
            let fk_arg2 = widened_in result positive open_ table in
            let fk_arg3 = if positive then open_ effects else effects in
            (Types.FunctionOf { parameters = fk_arg1; result = fk_arg2; effects = fk_arg3 } : Types.type_)
        | Types.Effects { row = row } -> if positive then (Types.Effects { row = open_ row } : Types.type_) else t
        | Types.Named { name = _; arguments = _; region = Some _ } -> t
        | Types.Named { name = name; arguments = arguments; region = None } -> (Types.Named { name = name; arguments = List.mapi (fun i a -> if is_covariant name i table then widened_in a positive open_ table else a) arguments; region = None } : Types.type_)
        | Types.TupleOf { elements = elements } -> (Types.TupleOf { elements = List.map (fun it -> widened_in it positive open_ table) elements } : Types.type_)
        | _ -> t

      let widened (t : Types.type_) (table : Symbols.symbol_table) : Types.scheme =
        let opened = ref [] in
        let open_ = fun row -> match (row : Types.row).Types.rest with
            | Some _ -> row
            | None -> let v = Effect.perform (Types.Solving_fresh ()) in
                opened := ! opened @ [v];
                ({ Types.labels = (row : Types.row).Types.labels; rest = Some v } : Types.row) in
        let widened_type = widened_in t true open_ table in
        ({ Types.variables = ! opened; template = widened_type } : Types.scheme)

      let with_scheme (s : signature) (done_ : Types.row) (known : known) (table : Symbols.symbol_table) : known =
        let f = (s : signature).function_ in
        check_type_parameters_stayed s;
        let t = Types.Types.resolved_fully (match (s : signature).t with
           | Types.FunctionOf { parameters = parameters; result = result; effects = _ } -> (Types.FunctionOf { parameters = parameters; result = result; effects = done_ } : Types.type_)
           | other -> other) in
        let is_value = not (Symbols.Signatures.is_function f) in
        if is_value then List.iter (fun r -> match r with
             | Types.Variable { variable = _ } -> Types.Unification.unify r Types.Types.global_region;
                 ()
             | _ -> ()) (regions_in t None) else ();
        let final = Types.Types.resolved_fully t in
        let scheme = if is_value then widened final table else ({ Types.variables = Types.Types.variables_in final; template = final } : Types.scheme) in
        let outside = Option.map (fun o -> let shown = Types.Types.resolved_fully (match o with
                | Types.FunctionOf { parameters = parameters; result = result; effects = _ } -> (Types.FunctionOf { parameters = parameters; result = result; effects = done_ } : Types.type_)
                | other -> other) in
             if is_value then widened shown table else ({ Types.variables = Types.Types.variables_in shown; template = shown } : Types.scheme)) (s : signature).outside in
        let variables = Collections.Maps.list_tuple_to_map (Lang.Lists.list_map_not_null (List.filter (fun (name, _) -> not (String.starts_with ~prefix:"@" name)) (s : signature).type_variables) (fun (name, v) -> match Types.Types.resolved (Types.Variable { variable = v } : Types.type_) with
              | Types.Variable { variable = w } -> Some (name, w)
              | _ -> None)) in
        let fk_arg1 = Collections.Maps.map_put (known : known).schemes (f : Symbols.symbol).Symbols.name scheme in
        let fk_arg2 = Option.value (Option.map (fun o -> Collections.Maps.map_put (known : known).outside (f : Symbols.symbol).Symbols.name o) outside) ~default:(known : known).outside in
        let fk_arg3 = Collections.Maps.map_put (known : known).type_parameter_variables (f : Symbols.symbol).Symbols.name variables in
        let fk_arg4 = Collections.Maps.empty_map () in
        let fk_arg5 = Collections.Maps.empty_map () in
        { (known : known) with schemes = fk_arg1; outside = fk_arg2; type_parameter_variables = fk_arg3; provisional = fk_arg4; viewed = fk_arg5 }

      let rec settled_core (c : Core.core) : Core.core =
        match c with
        | Core.Value { literal = _ } -> c
        | Core.LocalRead { name = _; is_var = _ } -> c
        | Core.GlobalRead { function_ = _ } -> c
        | Core.ExternalRead { function_ = _ } -> c
        | Core.Applied { function_ = function_; arguments = arguments } -> let fk_arg1 = settled_core function_ in
            let fk_arg2 = List.map (fun it -> settled_core it) arguments in
            (Core.Applied { function_ = fk_arg1; arguments = fk_arg2 } : Core.core)
        | Core.ExternalApplied { function_ = function_; arguments = arguments } -> (Core.ExternalApplied { function_ = function_; arguments = List.map (fun it -> settled_core it) arguments } : Core.core)
        | Core.Performed { effect_ = effect_; operation = operation; arguments = arguments } -> (Core.Performed { effect_ = effect_; operation = operation; arguments = List.map (fun it -> settled_core it) arguments } : Core.core)
        | Core.Operated { primitive = primitive; operands = operands } -> (Core.Operated { primitive = primitive; operands = List.map (fun it -> settled_core it) operands } : Core.core)
        | Core.Shown { value = value; t = t } -> let fk_arg1 = settled_core value in
            let fk_arg2 = Types.Types.resolved_fully t in
            (Core.Shown { value = fk_arg1; t = fk_arg2 } : Core.core)
        | Core.ListMade { items = items } -> (Core.ListMade { items = List.map (fun item -> match item with
               | Core.OneItem { value = value } -> (Core.OneItem { value = settled_core value } : Core.list_item)
               | Core.SpreadItems { list = list } -> (Core.SpreadItems { list = settled_core list } : Core.list_item)) items } : Core.core)
        | Core.TupleMade { parts = parts } -> (Core.TupleMade { parts = List.map (fun it -> settled_core it) parts } : Core.core)
        | Core.Constructed { constructor = constructor; fields = fields; t = t } -> let fk_arg1 = List.map (fun it -> settled_core it) fields in
            let fk_arg2 = Types.Types.resolved_fully t in
            (Core.Constructed { constructor = constructor; fields = fk_arg1; t = fk_arg2 } : Core.core)
        | Core.FieldRead { record = record; owner = owner; field = field } -> (Core.FieldRead { record = settled_core record; owner = owner; field = field } : Core.core)
        | Core.Copied { record = record; owner = owner; changes = changes } -> let fk_arg1 = settled_core record in
            let fk_arg2 = List.map (fun (name, value) -> (name, settled_core value)) changes in
            (Core.Copied { record = fk_arg1; owner = owner; changes = fk_arg2 } : Core.core)
        | Core.FieldWritten { record = record; owner = owner; field = field; value = value } -> let fk_arg1 = settled_core record in
            let fk_arg2 = settled_core value in
            (Core.FieldWritten { record = fk_arg1; owner = owner; field = field; value = fk_arg2 } : Core.core)
        | Core.NarrowedWritten { local = local; case_name = case_name; case_type = case_type; field = field; value = value } -> (Core.NarrowedWritten { local = local; case_name = case_name; case_type = case_type; field = field; value = settled_core value } : Core.core)
        | Core.CaseName { value = value; cases = cases } -> (Core.CaseName { value = settled_core value; cases = cases } : Core.core)
        | Core.Matched { subject = subject; branches = branches } -> let fk_arg1 = settled_core subject in
            let fk_arg2 = List.map (fun b -> let fk_arg1 = Option.map (fun it -> settled_core it) (b : Core.match_branch).Core.guard in
                 let fk_arg2 = settled_core (b : Core.match_branch).Core.body in
                 ({ Core.patterns = (b : Core.match_branch).Core.patterns; guard = fk_arg1; body = fk_arg2 } : Core.match_branch)) branches in
            (Core.Matched { subject = fk_arg1; branches = fk_arg2 } : Core.core)
        | Core.NarrowedRead { local = _; case_name = _; case_type = _; field = _ } -> c
        | Core.Joined { list = list; separator = separator; element = element } -> let fk_arg1 = settled_core list in
            let fk_arg2 = settled_core separator in
            let fk_arg3 = Types.Types.resolved_fully element in
            (Core.Joined { list = fk_arg1; separator = fk_arg2; element = fk_arg3 } : Core.core)
        | Core.Assertion { condition = condition; summary = summary; facts = facts } -> let fk_arg1 = settled_core condition in
            let fk_arg2 = List.map (fun (key, fact) -> (key, settled_core fact)) facts in
            (Core.Assertion { condition = fk_arg1; summary = summary; facts = fk_arg2 } : Core.core)
        | Core.EqualityAssertion { expected = expected; actual = actual; t = t; where = where; source = source } -> let fk_arg1 = settled_core expected in
            let fk_arg2 = settled_core actual in
            let fk_arg3 = Types.Types.resolved_fully t in
            (Core.EqualityAssertion { expected = fk_arg1; actual = fk_arg2; t = fk_arg3; where = where; source = source } : Core.core)
        | Core.Conditional { condition = condition; then_ = then_; otherwise = otherwise } -> let fk_arg1 = settled_core condition in
            let fk_arg2 = settled_core then_ in
            let fk_arg3 = settled_core otherwise in
            (Core.Conditional { condition = fk_arg1; then_ = fk_arg2; otherwise = fk_arg3 } : Core.core)
        | Core.Bound { pattern = pattern; value = value; body = body } -> let fk_arg1 = settled_core value in
            let fk_arg2 = settled_core body in
            (Core.Bound { pattern = pattern; value = fk_arg1; body = fk_arg2 } : Core.core)
        | Core.VarBound { name = name; value = value; body = body } -> let fk_arg1 = settled_core value in
            let fk_arg2 = settled_core body in
            (Core.VarBound { name = name; value = fk_arg1; body = fk_arg2 } : Core.core)
        | Core.VarWritten { name = name; value = value } -> (Core.VarWritten { name = name; value = settled_core value } : Core.core)
        | Core.FunctionBound { name = name; parameters = parameters; body = body; rest = rest } -> let fk_arg1 = settled_core body in
            let fk_arg2 = settled_core rest in
            (Core.FunctionBound { name = name; parameters = parameters; body = fk_arg1; rest = fk_arg2 } : Core.core)
        | Core.Sequenced { first = first; then_ = then_ } -> let fk_arg1 = settled_core first in
            let fk_arg2 = settled_core then_ in
            (Core.Sequenced { first = fk_arg1; then_ = fk_arg2 } : Core.core)
        | Core.FunctionValue { parameters = parameters; body = body; drops_result = drops } -> (Core.FunctionValue { parameters = parameters; body = settled_core body; drops_result = drops } : Core.core)
        | Core.Absurd { call = call } -> (Core.Absurd { call = settled_core call } : Core.core)
        | Core.Widened { value = value; t = t } -> let fk_arg1 = settled_core value in
            let fk_arg2 = Types.Types.resolved_fully t in
            (Core.Widened { value = fk_arg1; t = fk_arg2 } : Core.core)
        | Core.ModulePacked { module_ = _; spec = _ } -> c
        | Core.ModuleMemberRead { value = value; spec = spec; member = member } -> (Core.ModuleMemberRead { value = settled_core value; spec = spec; member = member } : Core.core)
        | Core.HandlerMade { effect_ = effect_; answers = answers } -> (Core.HandlerMade { effect_ = effect_; answers = List.map (fun a -> { (a : Core.answer) with Core.answer = settled_core (a : Core.answer).Core.answer }) answers } : Core.core)
        | Core.ModuleHandler { module_ = _; effect_ = _ } -> c
        | Core.Handled { effect_ = effect_; handler = handler; block = block } -> let fk_arg1 = settled_core handler in
            let fk_arg2 = settled_core block in
            (Core.Handled { effect_ = effect_; handler = fk_arg1; block = fk_arg2 } : Core.core)
        | Core.Pending { what = _ } -> c

      let settled (f : Core.core_function) : Core.core_function =
        { (f : Core.core_function) with Core.body = settled_core (f : Core.core_function).Core.body }

      let rec own_types_replaced (t : Types.type_) (own : string -> Types.type_ list -> Types.type_) : Types.type_ =
        match Types.Types.resolved t with
        | Types.SpecOwnType { name = name; arguments = arguments } -> own name (List.map (fun it -> own_types_replaced it own) arguments)
        | Types.Named { name = n; arguments = arguments; region = region } -> (Types.Named { name = n; arguments = List.map (fun it -> own_types_replaced it own) arguments; region = region } : Types.type_)
        | Types.Abstract { name = n; arguments = arguments } -> (Types.Abstract { name = n; arguments = List.map (fun it -> own_types_replaced it own) arguments } : Types.type_)
        | Types.ModuleValue { spec = n; arguments = arguments; own_types = names } -> (Types.ModuleValue { spec = n; arguments = List.map (fun it -> own_types_replaced it own) arguments; own_types = names } : Types.type_)
        | Types.Handler { effect_ = n; arguments = arguments } -> (Types.Handler { effect_ = n; arguments = List.map (fun it -> own_types_replaced it own) arguments } : Types.type_)
        | Types.TupleOf { elements = elements } -> (Types.TupleOf { elements = List.map (fun it -> own_types_replaced it own) elements } : Types.type_)
        | Types.FunctionOf { parameters = parameters; result = result; effects = effects } -> let fk_arg1 = List.map (fun it -> own_types_replaced it own) parameters in
            let fk_arg2 = own_types_replaced result own in
            (Types.FunctionOf { parameters = fk_arg1; result = fk_arg2; effects = effects } : Types.type_)
        | other -> other

      let with_module_types (t : Types.type_) (owner : string) (context : Definitions.type_context) (definitions : Definitions.definitions) : Types.type_ =
        own_types_replaced t (fun name arguments -> match type_named (owner ^ "." ^ name) ((definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table with
           | Some d -> Definitions.Conversion.declared d arguments context definitions
           | None -> (Types.SpecOwnType { name = name; arguments = arguments } : Types.type_))

      let module_context (f : Symbols.symbol) (definitions : Definitions.definitions) : Definitions.type_context =
        let fk_arg1 = Collections.Maps.list_tuple_to_map (List.map (fun p -> (p, (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_))) (Definitions.Conversion.module_type_parameters (f : Symbols.symbol).Symbols.path definitions)) in
        let fk_arg2 = Definitions.type_context_default_region () in
        let fk_arg3 = Definitions.type_context_default_arrow_effects () in
        let fk_arg4 = Definitions.type_context_default_expanding () in
        let fk_arg5 = Definitions.type_context_default_spec_types () in
        let fk_arg6 = Definitions.type_context_default_outside_view () in
        let fk_arg7 = Definitions.type_context_default_seen_from () in
        let fk_arg8 = Definitions.type_context_default_value_parameters () in
        let fk_arg9 = Definitions.type_context_default_later_parameters () in
        ({ Definitions.place = ({ Resolution.file = (f : Symbols.symbol).Symbols.file; path = (f : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; region = fk_arg2; arrow_effects = fk_arg3; expanding = fk_arg4; spec_types = fk_arg5; outside_view = fk_arg6; seen_from = fk_arg7; value_parameters = fk_arg8; later_parameters = fk_arg9 } : Definitions.type_context)

      let spec_shown (wanted : Types.scheme) (named : (Types.type_variable * string) list) : string =
        Types.TypeText.shown (Types.Types.substitute (wanted : Types.scheme).Types.template (Collections.Maps.list_tuple_to_map (List.map (fun (variable, name) -> (variable, (Types.TypeParameter { name = name } : Types.type_))) named)))

      let conform_to (f : Symbols.symbol) (owner : string) (spec : Symbols.symbol) (v : Parser.spec_value) (wanted : Types.scheme) (scheme : Types.scheme) (known : known) (environment : environment) : known =
        let definitions = (environment : environment).definitions in
        let own = Symbols.Symbols.simple_name f in
        let spec_name = Symbols.Symbols.simple_name spec in
        let named = Lang.Lists.list_zip (wanted : Types.scheme).Types.variables (v : Parser.spec_value).Parser.type_parameters in
        let open_ = List.map (fun variable -> (variable, (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_))) (List.drop (List.length named) (wanted : Types.scheme).Types.variables) in
        let rigid = Collections.Maps.list_tuple_to_map (List.map (fun (variable, name) -> (variable, (Types.TypeParameter { name = name } : Types.type_))) named @ open_) in
        let inside = let fk_arg1 = Types.Types.substitute (wanted : Types.scheme).Types.template rigid in
          let fk_arg2 = module_context f definitions in
          with_module_types fk_arg1 owner fk_arg2 definitions in
        let actual = Types.Types.instantiate scheme (Types.Types.instantiate_default_given ()) in
        let shown_actual = Types.TypeText.shown actual in
        if not (Types.Unification.unify actual inside) then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((f : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = (let fk_arg1 = spec_shown wanted named in
             let fk_arg2 = Types.TypeText.shown inside in
             "'" ^ own ^ "' has type " ^ shown_actual ^ ", but " ^ spec_name ^ " needs " ^ fk_arg1 ^ ", which here is " ^ fk_arg2) } : Diagnostics.diagnostic)) with
           | _ -> (assert false)) else ();
        let declared = spec_effects spec v (let fk_arg1 = Collections.Maps.empty_map () in
           let fk_arg2 = context_default_value_parameters () in
           ({ environment = environment; place = ({ Resolution.file = (f : Symbols.symbol).Symbols.file; path = (f : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; value_parameters = fk_arg2 } : context)) in
        let hidden = hides spec v (let fk_arg1 = Collections.Maps.empty_map () in
           let fk_arg2 = context_default_value_parameters () in
           ({ environment = environment; place = ({ Resolution.file = (f : Symbols.symbol).Symbols.file; path = (f : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; value_parameters = fk_arg2 } : context)) in
        let done_ = match Types.Types.resolved inside with
          | Types.FunctionOf { parameters = _; result = _; effects = effects } -> Lang.Lists.list_distinct (Types.Types.effect_names effects)
          | _ -> [] in
        let extra = List.filter (fun it -> not (List.mem it declared)) done_ in
        if (Lang.Lists.list_is_not_empty extra && Lang.Lists.list_is_not_empty declared) && not hidden then (match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((f : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = (let fk_arg1 = Doings.shown extra in
             let fk_arg2 = Doings.shown extra in
             "'" ^ own ^ "' does " ^ fk_arg1 ^ ", but " ^ spec_name ^ "'s " ^ own ^ " doesn't say it can: declare it there, as " ^ fk_arg2 ^ " " ^ own ^ "(...)") } : Diagnostics.diagnostic)) with
           | _ -> (assert false)) else ();
        if hidden then Option.iter (fun name -> let effect_ = Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".")) ~default:name in
             match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((f : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = (let fk_arg1 = "'" ^ own ^ "' does " ^ Doings.shown [name] ^ ", which needs a handler and has no default, so " ^ spec_name ^ " can't hide it: " in
               let fk_arg2 = "handle it inside " ^ Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) owner ".")) ~default:owner ^ ", or give " ^ effect_ ^ " a default with @HandledBy" in
               fk_arg1 ^ fk_arg2) } : Diagnostics.diagnostic)) with
             | _ -> (assert false)) (List.find_opt (fun name -> needs_handler name environment && Option.is_none (default_handler name environment)) extra) else ();
        let module_variables = List.map (fun p -> (p, Effect.perform (Types.Solving_fresh ()))) (Definitions.Conversion.module_type_parameters (f : Symbols.symbol).Symbols.path definitions) in
        let outside_context = let fk_arg1 = Collections.Maps.list_tuple_to_map (List.map (fun (p, variable) -> (p, (Types.Variable { variable = variable } : Types.type_))) module_variables) in
          let fk_arg2 = Definitions.type_context_default_region () in
          let fk_arg3 = Definitions.type_context_default_arrow_effects () in
          let fk_arg4 = Definitions.type_context_default_expanding () in
          let fk_arg5 = Definitions.type_context_default_spec_types () in
          let fk_arg6 = Definitions.type_context_default_outside_view () in
          let fk_arg7 = Definitions.type_context_default_seen_from () in
          let fk_arg8 = Definitions.type_context_default_value_parameters () in
          let fk_arg9 = Definitions.type_context_default_later_parameters () in
          ({ Definitions.place = ({ Resolution.file = (f : Symbols.symbol).Symbols.file; path = (f : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; region = fk_arg2; arrow_effects = fk_arg3; expanding = fk_arg4; spec_types = fk_arg5; outside_view = fk_arg6; seen_from = fk_arg7; value_parameters = fk_arg8; later_parameters = fk_arg9 } : Definitions.type_context) in
        let shown_type = own_types_replaced (wanted : Types.scheme).Types.template (fun name arguments -> Definitions.Conversion.outside_type owner name arguments outside_context definitions) in
        let variables = (wanted : Types.scheme).Types.variables @ List.map (fun (_, variable) -> variable) module_variables in
        let outside = match (List.is_empty declared, shown_type) with
          | (true, Types.FunctionOf { parameters = parameters; result = result; effects = _ }) -> let rest = Effect.perform (Types.Solving_fresh ()) in
              ({ Types.variables = variables @ [rest]; template = (Types.FunctionOf { parameters = parameters; result = result; effects = Types.Types.row_of done_ (Some rest) } : Types.type_) } : Types.scheme)
          | _ -> ({ Types.variables = variables; template = shown_type } : Types.scheme) in
        { (known : known) with outside = Collections.Maps.map_put (known : known).outside (f : Symbols.symbol).Symbols.name outside }

      let conform (f : Symbols.symbol) (known : known) (environment : environment) : known =
        let owner = String.concat "." (List.map Fun.id (f : Symbols.symbol).Symbols.path) in
        let value = Option.bind (Collections.Maps.map_get (environment : environment).module_specs owner) (fun spec -> Option.bind (List.find_opt (fun it -> (it : Parser.spec_value).Parser.name = ((f : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.name) (spec_values spec)) (fun v -> Option.map (fun wanted -> (spec, v, wanted)) (Option.bind (Collections.Maps.map_get (environment : environment).spec_types (spec : Symbols.symbol).Symbols.name) (fun types -> Collections.Maps.map_get (types : spec_types).values (v : Parser.spec_value).Parser.name)))) in
        match (value, Collections.Maps.map_get (known : known).schemes (f : Symbols.symbol).Symbols.name) with
        | (Some (spec, v, wanted), Some scheme) -> conform_to f owner spec v wanted scheme known environment
        | _ -> known

      let check_functions (group : function_group) (environment : environment) : known =
        let signatures = List.map (fun f -> signature_of f environment) (group : function_group).functions in
        let provisional = Collections.Maps.list_tuple_to_map (List.map (fun s -> (((s : signature).function_ : Symbols.symbol).Symbols.name, (s : signature).t)) signatures) in
        let viewed = if List.length (group : function_group).functions > 1 then Collections.Maps.list_tuple_to_map (Lang.Lists.list_map_not_null signatures (fun s -> Option.map (fun t -> (((s : signature).function_ : Symbols.symbol).Symbols.name, t)) (viewed_as s environment))) else Collections.Maps.empty_map () in
        let known = (environment : environment).known in
        let checking = ({ definitions = (environment : environment).definitions; functions = (environment : environment).functions; ordered_functions = (environment : environment).ordered_functions; extensions = (environment : environment).extensions; cases_by_name = (environment : environment).cases_by_name; module_specs = (environment : environment).module_specs; spec_types = (environment : environment).spec_types; operations = (environment : environment).operations; known = { (known : known) with provisional = provisional; viewed = viewed } } : environment) in
        let bodies = Lang.Lists.list_map_not_null signatures (fun s -> Option.map (fun b -> (((s : signature).function_ : Symbols.symbol).Symbols.name, b)) (check_body s checking)) in
        let done_ = List.map (fun s -> masked (s : signature).row (s : signature).t) signatures in
        List.iter (fun (s, row) -> check_declared_arguments s row environment) (Lang.Lists.list_zip signatures done_);
        Option.iter (fun (s, row) -> check_main_handled (s : signature).function_ row environment) (List.find_opt (fun (s, _) -> ((s : signature).function_ : Symbols.symbol).Symbols.name = "main") (Lang.Lists.list_zip signatures done_));
        List.iter (fun (s, row) -> if not (Symbols.Signatures.is_external (s : signature).function_) && not (Symbols.Signatures.is_compiled (s : signature).function_) then check_effects (s : signature).function_ row environment else ()) (Lang.Lists.list_zip signatures done_);
        let with_schemes = let fk_arg1 = List.fold_left (fun k entry -> let (s, row) = entry in
               with_scheme s row k (((environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table) known (Lang.Lists.list_zip signatures done_) in
          let fk_arg2 = List.fold_left (fun all entry -> let (name, body) = entry in
               Collections.Maps.map_put all name (settled body)) (known : known).bodies bodies in
          { (fk_arg1 : known) with bodies = fk_arg2 } in
        List.fold_left (fun k s -> conform (s : signature).function_ k environment) with_schemes signatures

      let alternatives_of (t : Types.type_) (environment : environment) : Types.type_ Coverage.alternative list option =
        let definitions = (environment : environment).definitions in
        let table = ((definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table in
        match Types.Types.resolved t with
        | Types.Named { name = name; arguments = arguments; region = region } -> (match Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.case_types name with
             | Some case_type -> Some (List.map (fun (c, fields) -> ({ Coverage.shape = (Coverage.CaseShape { owner = ((c : Definitions.case_info).Definitions.origin : Symbols.symbol).Symbols.name; name = ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name } : Coverage.shape); fields = fields } : Types.type_ Coverage.alternative)) (Definitions.Conversion.cases_with_fields case_type arguments region definitions (Definitions.Conversion.cases_with_fields_default_seen_from ())))
             | None -> match Collections.Maps.map_get (table : Symbols.symbol_table).Symbols.records name with
                 | Some record -> Some [({ Coverage.shape = (Coverage.RecordShape { name = (record : Symbols.symbol).Symbols.name } : Coverage.shape); fields = Definitions.Conversion.record_fields record arguments region definitions (Definitions.Conversion.record_fields_default_seen_from ()) } : Types.type_ Coverage.alternative)]
                 | None -> match (name, arguments) with
                     | ("List", [element]) -> Some [({ Coverage.shape = (Coverage.EmptyList : Coverage.shape); fields = [] } : Types.type_ Coverage.alternative); ({ Coverage.shape = (Coverage.NonEmptyList : Coverage.shape); fields = [element; Types.Types.resolved t] } : Types.type_ Coverage.alternative)]
                     | ("Option", [element]) -> Some [({ Coverage.shape = (Coverage.CaseShape { owner = ""; name = "Some" } : Coverage.shape); fields = [element] } : Types.type_ Coverage.alternative); ({ Coverage.shape = (Coverage.CaseShape { owner = ""; name = "None" } : Coverage.shape); fields = [] } : Types.type_ Coverage.alternative)]
                     | ("Result", [value; error]) -> Some [({ Coverage.shape = (Coverage.CaseShape { owner = ""; name = "Ok" } : Coverage.shape); fields = [value] } : Types.type_ Coverage.alternative); ({ Coverage.shape = (Coverage.CaseShape { owner = ""; name = "Error" } : Coverage.shape); fields = [error] } : Types.type_ Coverage.alternative)]
                     | ("Boolean", []) -> Some [({ Coverage.shape = (Coverage.BooleanShape { value = true } : Coverage.shape); fields = [] } : Types.type_ Coverage.alternative); ({ Coverage.shape = (Coverage.BooleanShape { value = false } : Coverage.shape); fields = [] } : Types.type_ Coverage.alternative)]
                     | _ -> None)
        | Types.TupleOf { elements = elements } -> Some [({ Coverage.shape = (Coverage.TupleShape { size = List.length elements } : Coverage.shape); fields = elements } : Types.type_ Coverage.alternative)]
        | _ -> None

      let check_covers (pending : pending_when) (environment : environment) : unit =
        let subject = Types.Types.resolved_fully (pending : pending_when).subject in
        let missing = Coverage.Coverage.missing (pending : pending_when).patterns subject (fun t -> alternatives_of t environment) in
        if List.is_empty missing then () else (match missing with
           | [({ Coverage.shape = None; fields = _ } : Coverage.matches)] -> (let what = match Types.Types.resolved subject with
                  | Types.Variable { variable = _ } -> "every value"
                  | other -> "every " ^ Types.TypeText.shown other in
                match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (pending : pending_when).file; at = (pending : pending_when).at; message = "this when doesn't cover " ^ what ^ "; add an else" } : Diagnostics.diagnostic)) with
                | _ -> (assert false))
           | _ -> let shown = List.map (fun it -> Coverage.Coverage.shown it) missing in
               let listed = if List.length shown > 10 then (let fk_arg1 = String.concat ", " (List.map Fun.id (List.take 8 shown)) in
                    let fk_arg2 = " and " ^ string_of_int (List.length shown - 8) ^ " more" in
                    fk_arg1 ^ fk_arg2) else String.concat ", " (List.map Fun.id shown) in
               match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (pending : pending_when).file; at = (pending : pending_when).at; message = "this when doesn't cover " ^ listed ^ "; add " ^ (if List.length shown = 1 then "it" else "them") ^ ", or an else" } : Diagnostics.diagnostic)) with
               | _ -> (assert false))

      let check_group_alone (group : function_group) (environment : environment) (coverage : bool) : known =
        let pending = ref [] in
