        | (Some application, Some (Symbols.DeclaredModule { symbol = app })) -> let at = Option.value (Option.map (fun it -> it ^ ":") (d : Diagnostics.diagnostic).Diagnostics.file) ~default:"" ^ string_of_int ((d : Diagnostics.diagnostic).Diagnostics.at : Parser.position).Parser.line ^ ":" ^ string_of_int ((d : Diagnostics.diagnostic).Diagnostics.at : Parser.position).Parser.column in
