      let exposes (user : Symbols.symbol) (hidden : Symbols.symbol) : bool =
        (((user : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.visibility <> (Parser.Private : Parser.visibility) && Lang.Lists.list_is_not_empty (hidden : Symbols.symbol).Symbols.path) && not ((let fk_arg1 = List.length (user : Symbols.symbol).Symbols.path in
