                   let fk_arg3 = Definitions.type_context_default_arrow_effects () in
                   let fk_arg4 = Definitions.type_context_default_expanding () in
                   let fk_arg5 = Definitions.type_context_default_spec_types () in
                   let fk_arg6 = Definitions.type_context_default_outside_view () in
                   let fk_arg7 = Definitions.type_context_default_seen_from () in
                   let fk_arg8 = Definitions.type_context_default_value_parameters () in
                   let fk_arg9 = Definitions.type_context_default_later_parameters () in
                   ({ Definitions.place = ({ Resolution.file = (d : Symbols.symbol).Symbols.file; path = (d : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = fk_arg1; region = fk_arg2; arrow_effects = fk_arg3; expanding = fk_arg4; spec_types = fk_arg5; outside_view = fk_arg6; seen_from = fk_arg7; value_parameters = fk_arg8; later_parameters = fk_arg9 } : Definitions.type_context) in
                 List.iter (fun c -> check_field_names d (c : Parser.case_definition).Parser.fields;
                    List.iter (fun f -> Definitions.Conversion.type_of (f : Parser.field).Parser.field_type context definitions;
                       ()) (c : Parser.case_definition).Parser.fields) cases;
                 List.iter (fun i -> Definitions.Conversion.type_of i context definitions;
                    ()) includes
             | _ -> ()) (table : Symbols.symbol_table).Symbols.declarations

        let reporting_abandoned (block : unit -> unit) : unit =
          Diagnostics.Diagnostics.recovering block;
          ()

        let function_types (definitions : Definitions.definitions) (coverage : bool) : inferred =
          check_type_declarations definitions;
          let meta_types = Definitions.MetaTypes.all definitions in
          let environment = Environments.of_ definitions in
          check_modules_define environment;
          check_arguments_define environment;
          let groups = Groups.ordered (environment : environment).ordered_functions environment in
          let known = List.fold_left (fun k group -> let checking = ({ definitions = (environment : environment).definitions; functions = (environment : environment).functions; ordered_functions = (environment : environment).ordered_functions; extensions = (environment : environment).extensions; cases_by_name = (environment : environment).cases_by_name; module_specs = (environment : environment).module_specs; spec_types = (environment : environment).spec_types; operations = (environment : environment).operations; known = k } : environment) in
               match Diagnostics.Diagnostics.attempting (fun () -> check_group group checking coverage) with
               | Ok checked -> checked
               | Error diagnostic -> Effect.perform (Diagnostics.Reporting_report diagnostic);
                   failed group k) (environment : environment).known groups in
          reporting_abandoned (fun () -> check_exposure environment known);
          ({ environment = environment; known = known; functions = Lang.Lists.list_map_not_null (environment : environment).ordered_functions (fun f -> Option.map (fun s -> ({ function_ = f; scheme = s; body = Collections.Maps.map_get (known : known).bodies (f : Symbols.symbol).Symbols.name } : checked_function)) (Collections.Maps.map_get (known : known).schemes (f : Symbols.symbol).Symbols.name)); meta_types = meta_types; groups = groups } : inferred)

        let check_main (environment : environment) (known : known) : unit =
          match let fk_arg1 = Collections.Maps.map_get (environment : environment).functions "main" in
          let fk_arg2 = Collections.Maps.map_get (known : known).schemes "main" in
          (fk_arg1, fk_arg2) with
          | (Some main, Some scheme) -> (let problem = fun message -> Effect.perform (Diagnostics.Reporting_report ({ Diagnostics.file = (((main : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((main : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = message } : Diagnostics.diagnostic)) in
               match Types.Types.resolved (scheme : Types.scheme).Types.template with
               | Types.FunctionOf { parameters = parameters; result = result; effects = _ } -> if List.length parameters > 1 || List.length parameters = 1 && not (let fk_arg1 = Option.value (List.nth_opt parameters 0) ~default:Types.Types.unit in
                    let fk_arg2 = Types.Types.list_of Types.Types.string in
                    Types.Unification.unify fk_arg1 fk_arg2) then problem "main must be declared as main() = ... or main(args: List<String>) = ..." else if not (Types.Unification.unify result Types.Types.unit) then problem ("main must return Unit, not " ^ Types.TypeText.shown result) else ()
               | _ -> problem "main must be declared as main() = ... or main(args: List<String>) = ...")
          | _ -> ()
      end

      let inferred_default_groups () : function_group list =
        []

      let checked_function_default_body () : Core.core_function option =
        None

      let rec inside_out (left : default_handler list) (does : (string, string list) Collections.Maps.map) : default_handler list =
        match left with
        | [] -> []
        | _ -> let unneeded = List.filter (fun d -> Lang.Lists.list_none left (fun other -> other <> d && List.mem ((d : default_handler).effect_ : Symbols.symbol).Symbols.name (Collections.Maps.map_get_or_default does ((other : default_handler).effect_ : Symbols.symbol).Symbols.name []))) left in
            let inner = if List.is_empty unneeded then left else unneeded in
            inner @ inside_out (List.filter (fun it -> not (List.mem it inner)) left) does

      let default_handlers (environment : environment) (known : known) : default_handler list =
        let defaults = Lang.Lists.list_sorted_by (Lang.Lists.list_map_not_null (List.filter (fun (name, _) -> needs_handler name environment) (Collections.Maps.map_to_list ((((environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.specs)) (fun (name, spec) -> Option.map (fun m -> ({ effect_ = spec; handler = m } : default_handler)) (default_handler name environment))) (fun it -> ((it : default_handler).effect_ : Symbols.symbol).Symbols.name) in
        let does = Collections.Maps.list_tuple_to_map (List.map (fun d -> let done_ = List.concat_map (fun v -> Option.value (Option.map (fun s -> match (s : Types.scheme).Types.template with
                       | Types.FunctionOf { parameters = _; result = _; effects = row } -> Types.Types.effect_names row
                       | _ -> []) (Collections.Maps.map_get (known : known).schemes (((d : default_handler).handler : Symbols.symbol).Symbols.name ^ "." ^ (v : Parser.spec_value).Parser.name))) ~default:[]) (spec_values (d : default_handler).effect_) in
              (((d : default_handler).effect_ : Symbols.symbol).Symbols.name, Lang.Lists.list_distinct (List.filter (fun it -> it <> ((d : default_handler).effect_ : Symbols.symbol).Symbols.name) done_))) defaults) in
        inside_out defaults does

      let declared_effect (spec : Symbols.symbol) (environment : environment) : Core.declared_effect =
        let type_parameters = match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = _; values = _; type_parameters = ps; copy_of = _; parents = _ } -> List.filter (fun it -> not (String.starts_with ~prefix:"@" it)) ps
          | _ -> [] in
        let every = match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.SpecDefinition { types = _; values = _; type_parameters = ps; copy_of = _; parents = _ } -> ps
          | _ -> [] in
        let operations = List.map (fun value -> let own = Collections.Maps.list_tuple_to_map (List.map (fun it -> (it, (Types.TypeParameter { name = it } : Types.type_))) (every @ (value : Parser.spec_value).Parser.type_parameters)) in
             let type_context = let fk_arg1 = Definitions.type_context_default_region () in
               let fk_arg2 = Definitions.type_context_default_arrow_effects () in
               let fk_arg3 = Definitions.type_context_default_expanding () in
               let fk_arg4 = Definitions.type_context_default_spec_types () in
               let fk_arg5 = Definitions.type_context_default_outside_view () in
               let fk_arg6 = Definitions.type_context_default_seen_from () in
               let fk_arg7 = Definitions.type_context_default_value_parameters () in
               let fk_arg8 = Definitions.type_context_default_later_parameters () in
               ({ Definitions.place = ({ Resolution.file = (spec : Symbols.symbol).Symbols.file; path = (spec : Symbols.symbol).Symbols.path } : Resolution.place); type_parameters = own; region = fk_arg1; arrow_effects = fk_arg2; expanding = fk_arg3; spec_types = fk_arg4; outside_view = fk_arg5; seen_from = fk_arg6; value_parameters = fk_arg7; later_parameters = fk_arg8 } : Definitions.type_context) in
             let type_of = fun t -> Definitions.Conversion.type_of t type_context (environment : environment).definitions in
             let fails = Option.is_some (value : Parser.spec_value).Parser.parameters && List.mem fail_effect (Annotations.Annotations.effects_of (value : Parser.spec_value).Parser.annotations (Annotations.Annotations.place_of spec) (value : Parser.spec_value).Parser.at ((environment : environment).definitions : Definitions.definitions).Definitions.namespace) in
             let fk_arg1 = List.filter (fun it -> not (String.starts_with ~prefix:"@" it)) (value : Parser.spec_value).Parser.type_parameters in
             let fk_arg2 = Option.map (fun ps -> List.map (fun p -> let fk_arg1 = Option.map (fun it -> type_of it) (p : Parser.parameter).Parser.parameter_type in
                     let fk_arg2 = (Types.Variable { variable = Effect.perform (Types.Solving_fresh ()) } : Types.type_) in
                     Option.value fk_arg1 ~default:fk_arg2) ps) (value : Parser.spec_value).Parser.parameters in
             let fk_arg3 = type_of (value : Parser.spec_value).Parser.value_type in
             ({ Core.name = (value : Parser.spec_value).Parser.name; type_parameters = fk_arg1; parameters = fk_arg2; result = fk_arg3; fails_at_call = fails } : Core.declared_operation)) (spec_values spec) in
        ({ Core.effect_ = spec; type_parameters = type_parameters; operations = operations } : Core.declared_effect)

      let declared_effects (environment : environment) : Core.declared_effect list =
        Lang.Lists.list_map_not_null (List.filter (fun (name, _) -> needs_handler name environment) (Collections.Maps.map_to_list ((((environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.specs)) (fun (_, spec) -> match Diagnostics.Diagnostics.attempting (fun () -> declared_effect spec environment) with
           | Ok effect_ -> Some effect_
           | Error _ -> None)

      let declared_specs (environment : environment) : Core.declared_spec list =
        List.map (fun (_, spec) -> let types = match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
             | Parser.SpecDefinition { types = spec_types; values = _; type_parameters = _; copy_of = _; parents = _ } -> List.map (fun t -> ((t : Parser.spec_type).Parser.name, (t : Parser.spec_type).Parser.type_parameters)) spec_types
             | _ -> [] in
           let schemes = let fk_arg1 = Option.map (fun it -> (it : spec_types).values) (Collections.Maps.map_get (environment : environment).spec_types (spec : Symbols.symbol).Symbols.name) in
             let fk_arg2 = Collections.Maps.empty_map () in
             Option.value fk_arg1 ~default:fk_arg2 in
           ({ Core.spec = spec; types = types; values = Lang.Lists.list_map_not_null (spec_values spec) (fun v -> Option.map (fun s -> ((v : Parser.spec_value).Parser.name, (s : Types.scheme).Types.template)) (Collections.Maps.map_get schemes (v : Parser.spec_value).Parser.name)) } : Core.declared_spec)) (List.filter (fun (_, spec) -> not (Annotations.Annotations.is_effect spec ((environment : environment).definitions : Definitions.definitions).Definitions.namespace)) (Collections.Maps.map_to_list ((((environment : environment).definitions : Definitions.definitions).Definitions.namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.specs))

      let field_type (field : field_reference) : Types.type_ =
        match field with
        | RecordField { record = _; t = t } -> t
        | NarrowedField { narrowing = _; t = t } -> t
        | ModuleMember { spec = _; value = _; t = t } -> t
    end

    type checked_program = { workspace : Sources.workspace; functions : Inference.checked_function list; default_handlers : Inference.default_handler list; groups : Inference.function_group list; types : Core.type_declaration list; to_strings : (string, Symbols.symbol) Collections.Maps.map; effects : Core.declared_effect list; specs : Core.declared_spec list; environment : Inference.environment option }

    let rec show_checked_program (v : checked_program) =
      "CheckedProgram(" ^ "workspace=" ^ Sources.show_workspace v.workspace ^ ", functions=" ^ fk_show_list Inference.show_checked_function v.functions ^ ", defaultHandlers=" ^ fk_show_list Inference.show_default_handler v.default_handlers ^ ", groups=" ^ fk_show_list Inference.show_function_group v.groups ^ ", types=" ^ fk_show_list Core.show_type_declaration v.types ^ ", toStrings=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Symbols.show_symbol) v.to_strings ^ ", effects=" ^ fk_show_list Core.show_declared_effect v.effects ^ ", specs=" ^ fk_show_list Core.show_declared_spec v.specs ^ ", environment=" ^ fk_show_option Inference.show_environment v.environment ^ ")"

    let checked_program_default_default_handlers () : Inference.default_handler list =
      []

    let checked_program_default_groups () : Inference.function_group list =
      []

    let checked_program_default_environment () : Inference.environment option =
      None

    module Metadata = struct
      module AnnotationChecks = struct
        let ceiling_of (path : string list) (environment : Inference.environment) : (Symbols.symbol * string list) option =
          let namespace = ((environment : Inference.environment).Inference.definitions : Definitions.definitions).Definitions.namespace in
          List.nth_opt (Lang.Lists.list_map_not_null (List.mapi (fun i _ -> List.take (List.length path - i) path) path) (fun p -> let name = String.concat "." (List.map Fun.id p) in
              let around = Lang.Options.option_or_else (Option.map (fun made -> (Symbols.DeclaredModule { symbol = (made : Resolution.made).Resolution.functor_ } : Symbols.module_symbol)) (Collections.Maps.map_get ((namespace : Resolution.namespace).Resolution.modules : Resolution.modules).Resolution.applications name)) (fun () -> Collections.Maps.map_get ((namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.modules name) in
              match around with
              | Some (Symbols.DeclaredModule { symbol = m }) -> let effects = Annotations.Annotations.effects_of ((m : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations ({ Resolution.file = (m : Symbols.symbol).Symbols.file; path = (m : Symbols.symbol).Symbols.path } : Resolution.place) ((m : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at namespace in
                  if List.is_empty effects then None else Some (m, effects)
              | _ -> None)) 0

        let check_narrows (m : Symbols.symbol) (environment : Inference.environment) : unit =
          let namespace = ((environment : Inference.environment).Inference.definitions : Definitions.definitions).Definitions.namespace in
          let effects = Annotations.Annotations.effects_of ((m : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations ({ Resolution.file = (m : Symbols.symbol).Symbols.file; path = (m : Symbols.symbol).Symbols.path } : Resolution.place) ((m : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at namespace in
          Option.iter (fun entry -> let (outer, allowed) = entry in
             let beyond = List.filter (fun it -> not (List.mem it allowed)) effects in
             if Lang.Lists.list_is_not_empty effects && Lang.Lists.list_is_not_empty beyond then (let doing = List.filter (fun it -> it <> "fckt.lang.Pure") allowed in
                let allows = if List.is_empty doing then "be pure" else "do " ^ Inference.Doings.shown doing in
                match Effect.perform (Diagnostics.Abandoning_abandon ({ Diagnostics.file = (((m : Symbols.symbol).Symbols.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = ((m : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.at; message = (let fk_arg1 = Symbols.Symbols.simple_name m in
                  let fk_arg2 = Symbols.Symbols.simple_name outer in
                  let fk_arg3 = Inference.Doings.shown beyond in
                  fk_arg1 ^ " is in " ^ fk_arg2 ^ ", which may only " ^ allows ^ ", so it can't be " ^ fk_arg3) } : Diagnostics.diagnostic)) with
                | _ -> (assert false)) else ()) (ceiling_of (m : Symbols.symbol).Symbols.path environment)

        let value_at (v : Parser.annotation_value) : Parser.position =
          match v with
          | Parser.Constant { expression = e } -> Symbols.Positions.of_ e
          | Parser.Reference { at = at; name = _; type_arguments = _; arguments = _ } -> at
          | Parser.ValueList { at = at; items = _ } -> at
          | Parser.ValueTuple { at = at; items = _ } -> at

        let wrong_argument (meta : Definitions.meta_type) (at : Parser.position) (context : Inference.context) : fk_nothing =
          match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at ("this should be " ^ Definitions.MetaTypes.described meta))) with
          | _ -> (assert false)

        let rec expression_of (v : Parser.annotation_value) (context : Inference.context) : Parser.expression =
          match v with
          | Parser.Constant { expression = e } -> e
          | Parser.ValueList { at = at; items = items } -> (Parser.ListOf { at = at; items = List.map (fun it -> expression_of it context) items } : Parser.expression)
          | Parser.ValueTuple { at = at; items = items } -> (Parser.Tuple { at = at; elements = List.map (fun it -> expression_of it context) items } : Parser.expression)
          | Parser.Reference { at = at; name = name; type_arguments = type_arguments; arguments = arguments } -> if Option.is_some type_arguments then (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at "a type goes only where an annotation's field is a Type, like List<User>")) with
                 | _ -> (assert false)) else ();
              let parts = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name "." in
              let callee = let fk_arg1 = List.drop 1 parts in
                let fk_arg2 = (Parser.Name { at = at; name = Option.value (List.nth_opt parts 0) ~default:name } : Parser.expression) in
                List.fold_left (fun target n -> (Parser.Member { at = at; target = target; name = n } : Parser.expression)) fk_arg2 fk_arg1 in
              match arguments with
              | Some args -> (Parser.Call { at = at; callee = callee; arguments = List.map (fun a -> let fk_arg1 = expression_of (a : Parser.annotation_argument).Parser.value context in
                     let fk_arg2 = Parser.argument_default_text () in
                     let fk_arg3 = Parser.argument_default_operands () in
                     ({ Parser.name = (a : Parser.annotation_argument).Parser.name; value = fk_arg1; text = fk_arg2; operands = fk_arg3 } : Parser.argument)) args; type_arguments = [] } : Parser.expression)
              | None -> callee

        let constructs (callee : Parser.expression) (context : Inference.context) : bool =
          match callee with
          | Parser.Name { at = at; name = name } -> Option.is_none (Resolution.Lookups.found (Inference.Globals.find name context (Resolution.Skipping : Resolution.strictness))) && Option.is_some (Inference.constructor_shape name None at false None true Inference.Scopes.empty context)
          | Parser.Member { at = at; target = target; name = name } -> Option.is_none (Inference.module_member at target name Inference.Scopes.empty context) && Option.is_some (Inference.qualified_case target Inference.Scopes.empty context)
          | _ -> false

        let rec constant (e : Parser.expression) (context : Inference.context) : unit =
          match e with
          | Parser.Call { at = at; callee = callee; arguments = arguments; type_arguments = _ } -> if not (constructs callee context) then (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at "an annotation's arguments are constants and references, so not a call: pass the function itself")) with
                 | _ -> (assert false)) else ();
              List.iter (fun it -> constant (it : Parser.argument).Parser.value context) arguments
          | Parser.Member { at = at; target = target; name = name } -> if Option.is_some (Inference.module_member at target name Inference.Scopes.empty context) || Option.is_some (Inference.qualified_case target Inference.Scopes.empty context) then () else (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at "an annotation's arguments are constants and references, so not a field of a value")) with
                 | _ -> (assert false))
          | Parser.ListOf { at = _; items = items } -> List.iter (fun it -> constant it context) items
          | Parser.Tuple { at = _; elements = elements } -> List.iter (fun it -> constant it context) elements
          | _ -> ()

        let check_constant (v : Parser.annotation_value) (t : Types.type_) (context : Inference.context) : unit =
          let e = expression_of v context in
          Inference.Doings.doing ({ Types.labels = []; rest = Some (Effect.perform (Types.Solving_fresh ())) } : Types.row) ((((context : Inference.context).Inference.place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path (fun () -> Inference.handle_covering ({ cover = (fun x0 k -> k ((fun _ -> ()) x0)) } : _ Inference.covering_handler) (fun () -> Inference.check e t Inference.Scopes.empty context;
                constant e context))

        let rec type_ref_of (v : Parser.annotation_value) : Parser.type_ref option =
          match v with
          | Parser.Reference { at = at; name = name; type_arguments = type_arguments; arguments = None } -> Some (Parser.NamedType { at = at; name = name; arguments = Option.value type_arguments ~default:[] } : Parser.type_ref)
          | Parser.ValueTuple { at = at; items = items } -> let refs = Lang.Lists.list_map_not_null items (fun it -> type_ref_of it) in
              if let fk_arg1 = List.length refs in
              let fk_arg2 = List.length items in
              fk_arg1 = fk_arg2 then Some (Parser.TupleType { at = at; elements = refs } : Parser.type_ref) else None
          | _ -> None

        let check_case (name : string) (case_type : Types.type_) (at : Parser.position) (context : Inference.context) : unit =
          let definitions = ((context : Inference.context).Inference.environment : Inference.environment).Inference.definitions in
          let namespace = (definitions : Definitions.definitions).Definitions.namespace in
          let parts = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name "." in
          let qualifier = if List.length parts > 1 then Some (String.concat "." (List.map Fun.id (Lang.Lists.list_drop_last parts 1))) else None in
          let qualifying = Option.map (fun q -> match Resolution.Lookups.case_type q (context : Inference.context).Inference.place namespace (Resolution.Refusing : Resolution.strictness) with
               | Resolution.Found { value = s } -> s
               | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at why)) with
                    | _ -> (assert false))
               | Resolution.NotFound -> match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at ("unknown type '" ^ q ^ "'"))) with
                   | _ -> (assert false)) qualifier in
          let case_name = Option.value (Lang.Lists.list_last_or_none parts) ~default:name in
          let found = match Types.Types.resolved case_type with
            | Types.Named { name = n; arguments = arguments; region = region } -> Option.value (Option.map (fun s -> List.exists (fun c -> ((c : Definitions.case_info).Definitions.definition : Parser.case_definition).Parser.name = case_name && Option.value (Option.map (fun q -> List.exists (fun it -> Definitions.Cases.same it c) (Collections.Maps.map_get_or_default (definitions : Definitions.definitions).Definitions.cases (q : Symbols.symbol).Symbols.name [])) qualifying) ~default:true) (List.map (fun (c, _) -> c) (Definitions.Conversion.cases_with_fields s arguments region definitions (Some (context : Inference.context).Inference.place)))) (Collections.Maps.map_get ((namespace : Resolution.namespace).Resolution.table : Symbols.symbol_table).Symbols.case_types n)) ~default:false
            | _ -> false in
          if not found then (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at ("'" ^ name ^ "' isn't a case of " ^ Types.TypeText.shown case_type))) with
             | _ -> (assert false)) else ()

        let check_field (name : string) (record : Types.type_) (field_type : Types.type_ option) (at : Parser.position) (context : Inference.context) : unit =
          let definitions = ((context : Inference.context).Inference.environment : Inference.environment).Inference.definitions in
          let parts = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name "." in
          let field_name = Option.value (Lang.Lists.list_last_or_none parts) ~default:name in
          if List.length parts < 2 then (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at ("write a field with its type, like " ^ Types.TypeText.shown record ^ "." ^ name))) with
             | _ -> (assert false)) else ();
          let owner = String.concat "." (List.map Fun.id (Lang.Lists.list_drop_last parts 1)) in
          let (wanted_name, arguments) = match Types.Types.resolved record with
            | Types.Named { name = n; arguments = args; region = _ } -> (n, args)
            | _ -> ("", []) in
          let declared = match Resolution.Lookups.record owner (context : Inference.context).Inference.place (definitions : Definitions.definitions).Definitions.namespace (Resolution.Refusing : Resolution.strictness) with
            | Resolution.Found { value = r } when (r : Symbols.symbol).Symbols.name = wanted_name -> r
            | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at why)) with
                 | _ -> (assert false))
            | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at ("expected a field of " ^ Types.TypeText.shown record ^ ", not of " ^ owner))) with
                | _ -> (assert false) in
          let fields = Inference.record_fields_of declared in
          let index = Lang.Lists.list_index_of_first fields (fun it -> (it : Parser.field).Parser.name = field_name) in
          if index < 0 then (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at (Symbols.Symbols.simple_name declared ^ " has no field '" ^ field_name ^ "'"))) with
             | _ -> (assert false)) else ();
          let actual = Option.value (Lang.Lists.list_get_or_none (Definitions.Conversion.record_fields declared arguments None definitions (Definitions.Conversion.record_fields_default_seen_from ())) index) ~default:Types.Types.unit in
          Option.iter (fun t -> let shown_actual = Types.TypeText.shown actual in
             if not (Types.Unification.unify actual t) then (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at (name ^ " is a " ^ shown_actual ^ ", not a " ^ Types.TypeText.shown t))) with
                | _ -> (assert false)) else ()) field_type

        let rec check_annotation (a : Parser.annotation) (place : Resolution.place) (inferred : Inference.inferred) : unit =
          let environment = (inferred : Inference.inferred).Inference.environment in
          let namespace = ((environment : Inference.environment).Inference.definitions : Definitions.definitions).Definitions.namespace in
          let context = let fk_arg1 = Collections.Maps.empty_map () in
            let fk_arg2 = Inference.context_default_value_parameters () in
            ({ Inference.environment = environment; place = place; type_parameters = fk_arg1; value_parameters = fk_arg2 } : Inference.context) in
          let problem = fun at message -> ({ Diagnostics.file = (((place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = at; message = message } : Diagnostics.diagnostic) in
          let as_effect = match Resolution.Lookups.annotation_type (a : Parser.annotation).Parser.name place namespace (Resolution.Skipping : Resolution.strictness) with
            | Resolution.Found { value = _ } -> None
            | _ -> Lang.Options.option_filter (Resolution.Lookups.found (Resolution.Lookups.spec (a : Parser.annotation).Parser.name place namespace (Resolution.Skipping : Resolution.strictness))) (fun s -> Annotations.Annotations.is_effect s namespace) in
          match as_effect with
          | Some spec -> let type_parameters = match ((spec : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
                | Parser.SpecDefinition { types = _; values = _; type_parameters = ps; copy_of = _; parents = _ } -> ps
                | _ -> [] in
              if Lang.Lists.list_is_not_empty (a : Parser.annotation).Parser.arguments then (match Effect.perform (Diagnostics.Abandoning_abandon (problem (a : Parser.annotation).Parser.at "an effect takes no arguments")) with
                 | _ -> (assert false)) else ();
              if Lang.Lists.list_is_not_empty (a : Parser.annotation).Parser.type_arguments && (let fk_arg1 = List.length (a : Parser.annotation).Parser.type_arguments in
               let fk_arg2 = List.length type_parameters in
               fk_arg1 <> fk_arg2) then (match Effect.perform (Diagnostics.Abandoning_abandon (problem (a : Parser.annotation).Parser.at (let fk_arg1 = Symbols.Symbols.simple_name spec in
                    let fk_arg2 = string_of_int (List.length type_parameters) in
                    let fk_arg3 = if List.length type_parameters = 1 then "" else "s" in
                    let fk_arg4 = string_of_int (List.length (a : Parser.annotation).Parser.type_arguments) in
                    fk_arg1 ^ " takes " ^ fk_arg2 ^ " type argument" ^ fk_arg3 ^ ", not " ^ fk_arg4))) with
                 | _ -> (assert false)) else ()
          | None -> if Lang.Lists.list_is_not_empty (a : Parser.annotation).Parser.type_arguments then (match Effect.perform (Diagnostics.Abandoning_abandon (problem (a : Parser.annotation).Parser.at "only a generic effect takes type arguments, as @Yielding<Int> does")) with
                 | _ -> (assert false)) else ();
              let declaration = match Resolution.Lookups.annotation_type (a : Parser.annotation).Parser.name place namespace (Resolution.Refusing : Resolution.strictness) with
                | Resolution.Found { value = d } -> d
                | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (problem (a : Parser.annotation).Parser.at why)) with
                     | _ -> (assert false))
                | Resolution.NotFound -> let is_type = Option.is_some (Resolution.Lookups.found (Resolution.Lookups.record (a : Parser.annotation).Parser.name place namespace (Resolution.Skipping : Resolution.strictness))) || Option.is_some (Resolution.Lookups.found (Resolution.Lookups.case_type (a : Parser.annotation).Parser.name place namespace (Resolution.Skipping : Resolution.strictness))) in
                    match Effect.perform (Diagnostics.Abandoning_abandon (problem (a : Parser.annotation).Parser.at (if is_type then "'" ^ (a : Parser.annotation).Parser.name ^ "' isn't an annotation; declare one with annotation type " ^ Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) (a : Parser.annotation).Parser.name ".")) ~default:(a : Parser.annotation).Parser.name ^ "(...)" else "unknown annotation '" ^ (a : Parser.annotation).Parser.name ^ "'" ^ Resolution.ImportHints.for_name (a : Parser.annotation).Parser.name namespace))) with
                    | _ -> (assert false) in
              check_arguments a declaration context inferred
        and check_arguments (a : Parser.annotation) (declaration : Symbols.symbol) (context : Inference.context) (inferred : Inference.inferred) : unit =
          let fields = match ((declaration : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
            | Parser.RecordDefinition { type_parameters = _; fields = fs; private_constructor = _; annotation = _; external_ = _ } -> fs
            | _ -> [] in
          let types = Collections.Maps.map_get_or_default (inferred : Inference.inferred).Inference.meta_types (declaration : Symbols.symbol).Symbols.name [] in
          let what = "@" ^ (a : Parser.annotation).Parser.name in
          let given = fun arguments -> List.map (fun argument -> ((argument : Parser.annotation_argument).Parser.name, value_at (argument : Parser.annotation_argument).Parser.value)) arguments in
          match Lang.Options.option_filter (Lang.Lists.list_last_or_none fields) (fun it -> (it : Parser.field).Parser.vararg) with
          | None -> let order = let fk_arg1 = given (a : Parser.annotation).Parser.arguments in
                let fk_arg2 = List.map (fun it -> (it : Parser.field).Parser.name) fields in
                Inference.order_of fk_arg1 fk_arg2 (a : Parser.annotation).Parser.at what context in
              List.iter (fun (t, i) -> Option.iter (fun argument -> check_meta (argument : Parser.annotation_argument).Parser.value t context inferred) (Lang.Lists.list_get_or_none (a : Parser.annotation).Parser.arguments i)) (Lang.Lists.list_zip types order)
          | Some vararg -> let fixed = List.length fields - 1 in
              let in_order = Lang.Lists.list_take_while (a : Parser.annotation).Parser.arguments (fun it -> Option.is_none (it : Parser.annotation_argument).Parser.name) in
              let listed = List.find_opt (fun it -> (it : Parser.annotation_argument).Parser.name = Some (vararg : Parser.field).Parser.name) (a : Parser.annotation).Parser.arguments in
              Option.iter (fun l -> if List.length in_order > fixed then (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context (value_at (l : Parser.annotation_argument).Parser.value) ("'" ^ (vararg : Parser.field).Parser.name ^ "' is passed twice"))) with
                    | _ -> (assert false)) else ()) listed;
              let others = let fk_arg1 = List.take fixed in_order in
                let fk_arg2 = List.filter (fun argument -> Some argument <> listed) (List.drop (List.length in_order) (a : Parser.annotation).Parser.arguments) in
                fk_arg1 @ fk_arg2 in
              let order = let fk_arg1 = given others in
                let fk_arg2 = List.map (fun it -> (it : Parser.field).Parser.name) (Lang.Lists.list_drop_last fields 1) in
                Inference.order_of fk_arg1 fk_arg2 (a : Parser.annotation).Parser.at what context in
              List.iter (fun (t, i) -> Option.iter (fun argument -> check_meta (argument : Parser.annotation_argument).Parser.value t context inferred) (Lang.Lists.list_get_or_none others i)) (Lang.Lists.list_zip (Lang.Lists.list_drop_last types 1) order);
              let last = Option.value (Lang.Lists.list_last_or_none types) ~default:(Definitions.MetaList { item = (Definitions.MetaFunction : Definitions.meta_type) } : Definitions.meta_type) in
              match listed with
              | Some l -> check_meta (l : Parser.annotation_argument).Parser.value last context inferred
              | None -> let item = match last with
                    | Definitions.MetaList { item = i } -> i
                    | Definitions.MetaValue { t = Types.Named { name = "List"; arguments = [item_type]; region = _ } } -> (Definitions.MetaValue { t = item_type } : Definitions.meta_type)
                    | other -> other in
                  List.iter (fun argument -> check_meta (argument : Parser.annotation_argument).Parser.value item context inferred) (List.drop fixed in_order)
        and check_meta (v : Parser.annotation_value) (meta : Definitions.meta_type) (context : Inference.context) (inferred : Inference.inferred) : unit =
          let at = value_at v in
          let namespace = (((context : Inference.context).Inference.environment : Inference.environment).Inference.definitions : Definitions.definitions).Definitions.namespace in
          let definitions = ((context : Inference.context).Inference.environment : Inference.environment).Inference.definitions in
          let wrong = fun () -> match wrong_argument meta at context with
              | _ -> (assert false) in
          let name = fun () -> match v with
              | Parser.Reference { at = _; name = n; type_arguments = None; arguments = None } -> n
              | _ -> match wrong_argument meta at context with
                  | _ -> (assert false) in
          match meta with
          | Definitions.MetaValue { t = t } -> check_constant v t context
          | Definitions.MetaList { item = item } -> (match v with
               | Parser.ValueList { at = _; items = items } -> List.iter (fun it -> check_meta it item context inferred) items
               | _ -> wrong ())
          | Definitions.MetaTuple { items = item_types } -> (match v with
               | Parser.ValueTuple { at = _; items = items } when let fk_arg1 = List.length items in
                   let fk_arg2 = List.length item_types in
                   fk_arg1 = fk_arg2 -> List.iter (fun (item, t) -> check_meta item t context inferred) (Lang.Lists.list_zip items item_types)
               | _ -> wrong ())
          | Definitions.MetaTypeReference -> (match type_ref_of v with
               | Some ref -> Definitions.Conversion.type_of ref (Inference.Globals.type_context context) definitions;
                   ()
               | None -> wrong ())
          | Definitions.MetaSpec -> (match Resolution.Lookups.spec (name ()) (context : Inference.context).Inference.place namespace (Resolution.Refusing : Resolution.strictness) with
               | Resolution.Found { value = _ } -> ()
               | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at why)) with
                    | _ -> (assert false))
               | Resolution.NotFound -> match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at ("unknown spec '" ^ name () ^ "'"))) with
                   | _ -> (assert false))
          | Definitions.MetaFunction -> (match Inference.Globals.find_or_refuse (name ()) at context with
               | Some f -> if not (Symbols.Signatures.is_function f) then (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at (Symbols.Symbols.simple_name f ^ " is a value, not a function"))) with
                      | _ -> (assert false)) else ()
               | None -> match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at ("unknown function '" ^ name () ^ "'"))) with
                   | _ -> (assert false))
          | Definitions.MetaModule { spec = spec } -> (match Resolution.Lookups.module_named (name ()) (context : Inference.context).Inference.place namespace (Resolution.Refusing : Resolution.strictness) with
               | Resolution.Found { value = Symbols.DeclaredModule { symbol = m } } -> let own = Symbols.Symbols.simple_name m in
                   if Lang.Lists.list_is_not_empty (Inference.functor_parameters m) then (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at (own ^ " is a functor; pass a module it makes, module Name = " ^ own ^ "(...)"))) with
                      | _ -> (assert false)) else ();
                   Option.iter (fun s -> if Option.map (fun it -> (it : Symbols.symbol).Symbols.name) (Collections.Maps.map_get ((context : Inference.context).Inference.environment : Inference.environment).Inference.module_specs (m : Symbols.symbol).Symbols.name) <> Some (s : Symbols.symbol).Symbols.name then (let simple = Symbols.Symbols.simple_name s in
                         match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at (own ^ " doesn't follow " ^ simple ^ ": declare it as module " ^ own ^ " : " ^ simple))) with
                         | _ -> (assert false)) else ()) spec
               | Resolution.Refused { message = why } -> (match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at why)) with
                    | _ -> (assert false))
               | _ -> match Effect.perform (Diagnostics.Abandoning_abandon (Inference.Globals.problem context at ("unknown module '" ^ name () ^ "'"))) with
                   | _ -> (assert false))
          | Definitions.MetaCase { case_type = case_type } -> check_case (name ()) case_type at context
          | Definitions.MetaField { record = record; field_type = field_type } -> check_field (name ()) record field_type at context
          | Definitions.MetaAnnotation { annotation = wanted } -> match v with
              | Parser.Reference { at = _; name = n; type_arguments = None; arguments = arguments } -> let found = Resolution.Lookups.found (Resolution.Lookups.annotation_type n (context : Inference.context).Inference.place namespace (Resolution.Refusing : Resolution.strictness)) in
                  if Option.map (fun it -> (it : Symbols.symbol).Symbols.name) found <> Some (wanted : Symbols.symbol).Symbols.name then (match wrong_argument meta at context with
                     | _ -> (assert false)) else check_annotation ({ Parser.at = at; name = n; arguments = Option.value arguments ~default:[]; type_arguments = [] } : Parser.annotation) (context : Inference.context).Inference.place inferred
              | _ -> wrong ()

        let check_all (given : Inference.inferred) : unit =
          let inferred = { (given : Inference.inferred) with Inference.environment = { ((given : Inference.inferred).Inference.environment : Inference.environment) with Inference.known = (given : Inference.inferred).Inference.known } } in
          let environment = (inferred : Inference.inferred).Inference.environment in
          let namespace = ((environment : Inference.environment).Inference.definitions : Definitions.definitions).Definitions.namespace in
          let table = (namespace : Resolution.namespace).Resolution.table in
          List.iter (fun m -> check_narrows m environment) (List.filter (fun it -> Symbols.Symbols.is_module it) (table : Symbols.symbol_table).Symbols.declarations);
          let seen = ref [] in
          let check = fun place annotations -> List.iter (fun a -> let site = ({ Resolution.file = (((place : Resolution.place).Resolution.file : Sources.loaded_file).Sources.source : Sources.source_text).Sources.path; at = (a : Parser.annotation).Parser.at } : Resolution.call_site) in
                 if not (List.mem site (! seen)) then (seen := ! seen @ [site];
                    check_annotation a place inferred) else ()) annotations;
              Option.iter (fun first -> Annotations.Annotations.reached annotations place (first : Parser.annotation).Parser.at namespace;
                 ()) (List.nth_opt annotations 0) in
          List.iter (fun d -> let place = ({ Resolution.file = (d : Symbols.symbol).Symbols.file; path = (d : Symbols.symbol).Symbols.path } : Resolution.place) in
             check place ((d : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.annotations;
             match ((d : Symbols.symbol).Symbols.declaration : Parser.declaration).Parser.definition with
             | Parser.RecordDefinition { type_parameters = _; fields = fields; private_constructor = _; annotation = _; external_ = _ } -> List.iter (fun f -> check place (f : Parser.field).Parser.annotations) fields
             | Parser.CasesDefinition { type_parameters = _; cases = cases; case_refs = _; includes = _ } -> List.iter (fun c -> check place (c : Parser.case_definition).Parser.annotations;
                    List.iter (fun f -> check place (f : Parser.field).Parser.annotations) (c : Parser.case_definition).Parser.fields) cases
             | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = parameters; result = _; body = _; external_ = _; operator = _ } -> List.iter (fun p -> check place (p : Parser.parameter).Parser.annotations) (Option.value parameters ~default:[])
             | Parser.SpecDefinition { types = _; values = values; type_parameters = _; copy_of = _; parents = _ } -> List.iter (fun v -> check place (v : Parser.spec_value).Parser.annotations) values
             | _ -> ()) (let fk_arg1 = List.filter (fun it -> not (Symbols.Symbols.is_module it)) (table : Symbols.symbol_table).Symbols.declarations in
           let fk_arg2 = List.filter (fun it -> Symbols.Symbols.is_module it) (table : Symbols.symbol_table).Symbols.declarations in
           fk_arg1 @ fk_arg2)
      end
    end

    module Checker = struct
      let type_names (entry : Sources.source_text) (tree : Sources.source_tree) : Resolution.resolved_file list * Diagnostics.diagnostic list =
        Diagnostics.Diagnostics.collecting (fun () -> let resolved = Diagnostics.Diagnostics.recovering (fun () -> let workspace = Expansion.Expansion.expanded (Sources.Loader.load entry tree) in
                let namespace = Functors.Functors.applied (Resolution.Resolution.namespace workspace tree) in
                List.map (fun file -> ({ Resolution.file = file; types = Resolution.Resolution.resolved_types file namespace (workspace : Sources.workspace).Sources.borrowed } : Resolution.resolved_file)) (workspace : Sources.workspace).Sources.files) in
           Option.value resolved ~default:[])

      let checking (entry : Sources.source_text) (tree : Sources.source_tree) (coverage : bool) : checked_program option * Diagnostics.diagnostic list =
        Diagnostics.Diagnostics.collecting (fun () -> Types.Solutions.solving (fun () -> Diagnostics.Diagnostics.recovering (fun () -> let workspace = Expansion.Expansion.expanded (Sources.Loader.load entry tree) in
                 let namespace = Functors.Functors.applied (Resolution.Resolution.namespace workspace tree) in
                 let definitions = let fk_arg1 = Definitions.Cases.all namespace in
                   let fk_arg2 = Definitions.Regions.regioned namespace in
                   ({ Definitions.namespace = namespace; cases = fk_arg1; regioned = fk_arg2 } : Definitions.definitions) in
                 let (inferred, errors) = Diagnostics.Diagnostics.collecting (fun () -> let inferred = Inference.Inference.function_types definitions coverage in
                      Diagnostics.Diagnostics.recovering (fun () -> Metadata.AnnotationChecks.check_all inferred);
                      inferred) in
                 List.iter (fun it -> Effect.perform (Diagnostics.Reporting_report it)) errors;
                 if List.is_empty errors then Inference.Inference.check_main (inferred : Inference.inferred).Inference.environment (inferred : Inference.inferred).Inference.known else ();
                 let fk_arg1 = Inference.default_handlers (inferred : Inference.inferred).Inference.environment (inferred : Inference.inferred).Inference.known in
                 let fk_arg2 = Definitions.TypeDeclarations.all definitions in
                 let fk_arg3 = Definitions.TypeDeclarations.to_strings definitions in
                 let fk_arg4 = Inference.declared_effects (inferred : Inference.inferred).Inference.environment in
                 let fk_arg5 = Inference.declared_specs (inferred : Inference.inferred).Inference.environment in
                 ({ workspace = workspace; functions = (inferred : Inference.inferred).Inference.functions; default_handlers = fk_arg1; groups = (inferred : Inference.inferred).Inference.groups; types = fk_arg2; to_strings = fk_arg3; effects = fk_arg4; specs = fk_arg5; environment = Some (inferred : Inference.inferred).Inference.environment } : checked_program))))

      let check (entry : Sources.source_text) (tree : Sources.source_tree) (coverage : bool) : checked_program option * Diagnostics.diagnostic list =
        let (checked, errors) = checking entry tree coverage in
        (checked, Diagnostics.Diagnostics.ordered errors)
    end
  end

  module Ocaml = struct
    type constant =
      | IntConstant of { value : int }
      | FloatConstant of { value : float }
      | StringConstant of { value : string }
      | BooleanConstant of { value : bool }
      | UnitConstant

    let rec show_constant (v : constant) =
      match v with
      | IntConstant r -> "IntConstant(" ^ "value=" ^ string_of_int r.value ^ ")"
      | FloatConstant r -> "FloatConstant(" ^ "value=" ^ fk_show_float r.value ^ ")"
      | StringConstant r -> "StringConstant(" ^ "value=" ^ Fun.id r.value ^ ")"
      | BooleanConstant r -> "BooleanConstant(" ^ "value=" ^ string_of_bool r.value ^ ")"
      | UnitConstant -> "UnitConstant"

    type typexpr =
      | TypeVar of { name : string }
      | TypeApplication of { name : string; arguments : typexpr list }
      | Arrow of { parameter : typexpr; result : typexpr }
      | Product of { parts : typexpr list }
      | Polymorphic of { variables : string list; body : typexpr }

    let rec show_typexpr (v : typexpr) =
      match v with
      | TypeVar r -> "TypeVar(" ^ "name=" ^ Fun.id r.name ^ ")"
      | TypeApplication r -> "TypeApplication(" ^ "name=" ^ Fun.id r.name ^ ", arguments=" ^ fk_show_list show_typexpr r.arguments ^ ")"
      | Arrow r -> "Arrow(" ^ "parameter=" ^ show_typexpr r.parameter ^ ", result=" ^ show_typexpr r.result ^ ")"
      | Product r -> "Product(" ^ "parts=" ^ fk_show_list show_typexpr r.parts ^ ")"
      | Polymorphic r -> "Polymorphic(" ^ "variables=" ^ fk_show_list Fun.id r.variables ^ ", body=" ^ show_typexpr r.body ^ ")"

    type effect_operation = { name : string; parameters : typexpr list; result : typexpr }

    let rec show_effect_operation (v : effect_operation) =
      "EffectOperation(" ^ "name=" ^ Fun.id v.name ^ ", parameters=" ^ fk_show_list show_typexpr v.parameters ^ ", result=" ^ show_typexpr v.result ^ ")"

    type field_declaration = { name : string; typexpr : typexpr; mutable_ : bool }

    let rec show_field_declaration (v : field_declaration) =
      "FieldDeclaration(" ^ "name=" ^ Fun.id v.name ^ ", typexpr=" ^ show_typexpr v.typexpr ^ ", mutable=" ^ string_of_bool v.mutable_ ^ ")"

    type carried =
      | Bare
      | Values of { typexprs : typexpr list }
      | InlineRecord of { fields : field_declaration list }

    let rec show_carried (v : carried) =
      match v with
      | Bare -> "Bare"
      | Values r -> "Values(" ^ "typexprs=" ^ fk_show_list show_typexpr r.typexprs ^ ")"
      | InlineRecord r -> "InlineRecord(" ^ "fields=" ^ fk_show_list show_field_declaration r.fields ^ ")"

    type constructor_declaration = { name : string; carries : carried }

    let rec show_constructor_declaration (v : constructor_declaration) =
      "ConstructorDeclaration(" ^ "name=" ^ Fun.id v.name ^ ", carries=" ^ show_carried v.carries ^ ")"

    type field_pat = { name : string; pattern : pat }
    and pat =
      | AnyPat
      | VariablePat of { name : string }
      | ConstantPat of { constant : constant }
      | TuplePat of { parts : pat list }
      | ListPat of { items : pat list }
      | ConsPat of { head : pat; tail : pat }
      | ConstructorPat of { name : string; argument : pat option }
      | RecordPat of { fields : field_pat list; open_ : bool }
      | AliasPat of { pattern : pat; name : string }
      | TypedPat of { pattern : pat; typexpr : typexpr }
      | OrPat of { left : pat; right : pat }
      | PackedPat of { module_ : string; signature : string }
      | TypePat of { type_name : string }
      | EffectPat of { operation : pat; continuation : string }

    let rec show_field_pat (v : field_pat) =
      "FieldPat(" ^ "name=" ^ Fun.id v.name ^ ", pattern=" ^ show_pat v.pattern ^ ")"
    and show_pat (v : pat) =
      match v with
      | AnyPat -> "AnyPat"
      | VariablePat r -> "VariablePat(" ^ "name=" ^ Fun.id r.name ^ ")"
      | ConstantPat r -> "ConstantPat(" ^ "constant=" ^ show_constant r.constant ^ ")"
      | TuplePat r -> "TuplePat(" ^ "parts=" ^ fk_show_list show_pat r.parts ^ ")"
      | ListPat r -> "ListPat(" ^ "items=" ^ fk_show_list show_pat r.items ^ ")"
      | ConsPat r -> "ConsPat(" ^ "head=" ^ show_pat r.head ^ ", tail=" ^ show_pat r.tail ^ ")"
      | ConstructorPat r -> "ConstructorPat(" ^ "name=" ^ Fun.id r.name ^ ", argument=" ^ fk_show_option show_pat r.argument ^ ")"
      | RecordPat r -> "RecordPat(" ^ "fields=" ^ fk_show_list show_field_pat r.fields ^ ", open=" ^ string_of_bool r.open_ ^ ")"
      | AliasPat r -> "AliasPat(" ^ "pattern=" ^ show_pat r.pattern ^ ", name=" ^ Fun.id r.name ^ ")"
      | TypedPat r -> "TypedPat(" ^ "pattern=" ^ show_pat r.pattern ^ ", typexpr=" ^ show_typexpr r.typexpr ^ ")"
      | OrPat r -> "OrPat(" ^ "left=" ^ show_pat r.left ^ ", right=" ^ show_pat r.right ^ ")"
      | PackedPat r -> "PackedPat(" ^ "module=" ^ Fun.id r.module_ ^ ", signature=" ^ Fun.id r.signature ^ ")"
      | TypePat r -> "TypePat(" ^ "typeName=" ^ Fun.id r.type_name ^ ")"
      | EffectPat r -> "EffectPat(" ^ "operation=" ^ show_pat r.operation ^ ", continuation=" ^ Fun.id r.continuation ^ ")"

    type binding = { pattern : pat; parameters : pat list; result : typexpr option; body : expr }
    and case = { pattern : pat; guard : expr option; body : expr }
    and expr =
      | Identifier of { path : string }
      | ConstantExpr of { constant : constant }
      | Application of { function_ : expr; arguments : expr list }
      | Infix of { operator : string; left : expr; right : expr }
      | Fun of { parameters : pat list; body : expr }
      | LetIn of { recursive : bool; bindings : binding list; body : expr }
      | Sequence of { first : expr; then_ : expr }
      | IfThenElse of { condition : expr; then_ : expr; otherwise : expr }
      | Match of { subject : expr; cases : case list }
      | TupleExpr of { parts : expr list }
      | ListExpr of { items : expr list }
      | RecordExpr of { fields : field_value list; base : expr option }
      | FieldAccess of { record : expr; field : string }
      | FieldUpdate of { record : expr; field : string; value : expr }
      | Construction of { name : string; argument : expr option }
      | Annotated of { expression : expr; typexpr : typexpr }
      | Coerced of { expression : expr; typexpr : typexpr }
      | Labelled of { label : string; value : expr }
      | Verbatim of { code : string }
    and field_value = { name : string; value : expr }

    let rec show_binding (v : binding) =
      "Binding(" ^ "pattern=" ^ show_pat v.pattern ^ ", parameters=" ^ fk_show_list show_pat v.parameters ^ ", result=" ^ fk_show_option show_typexpr v.result ^ ", body=" ^ show_expr v.body ^ ")"
    and show_case (v : case) =
      "Case(" ^ "pattern=" ^ show_pat v.pattern ^ ", guard=" ^ fk_show_option show_expr v.guard ^ ", body=" ^ show_expr v.body ^ ")"
    and show_expr (v : expr) =
      match v with
      | Identifier r -> "Identifier(" ^ "path=" ^ Fun.id r.path ^ ")"
      | ConstantExpr r -> "ConstantExpr(" ^ "constant=" ^ show_constant r.constant ^ ")"
      | Application r -> "Application(" ^ "function=" ^ show_expr r.function_ ^ ", arguments=" ^ fk_show_list show_expr r.arguments ^ ")"
      | Infix r -> "Infix(" ^ "operator=" ^ Fun.id r.operator ^ ", left=" ^ show_expr r.left ^ ", right=" ^ show_expr r.right ^ ")"
      | Fun r -> "Fun(" ^ "parameters=" ^ fk_show_list show_pat r.parameters ^ ", body=" ^ show_expr r.body ^ ")"
      | LetIn r -> "LetIn(" ^ "recursive=" ^ string_of_bool r.recursive ^ ", bindings=" ^ fk_show_list show_binding r.bindings ^ ", body=" ^ show_expr r.body ^ ")"
      | Sequence r -> "Sequence(" ^ "first=" ^ show_expr r.first ^ ", then=" ^ show_expr r.then_ ^ ")"
      | IfThenElse r -> "IfThenElse(" ^ "condition=" ^ show_expr r.condition ^ ", then=" ^ show_expr r.then_ ^ ", otherwise=" ^ show_expr r.otherwise ^ ")"
      | Match r -> "Match(" ^ "subject=" ^ show_expr r.subject ^ ", cases=" ^ fk_show_list show_case r.cases ^ ")"
      | TupleExpr r -> "TupleExpr(" ^ "parts=" ^ fk_show_list show_expr r.parts ^ ")"
      | ListExpr r -> "ListExpr(" ^ "items=" ^ fk_show_list show_expr r.items ^ ")"
      | RecordExpr r -> "RecordExpr(" ^ "fields=" ^ fk_show_list show_field_value r.fields ^ ", base=" ^ fk_show_option show_expr r.base ^ ")"
      | FieldAccess r -> "FieldAccess(" ^ "record=" ^ show_expr r.record ^ ", field=" ^ Fun.id r.field ^ ")"
      | FieldUpdate r -> "FieldUpdate(" ^ "record=" ^ show_expr r.record ^ ", field=" ^ Fun.id r.field ^ ", value=" ^ show_expr r.value ^ ")"
      | Construction r -> "Construction(" ^ "name=" ^ Fun.id r.name ^ ", argument=" ^ fk_show_option show_expr r.argument ^ ")"
      | Annotated r -> "Annotated(" ^ "expression=" ^ show_expr r.expression ^ ", typexpr=" ^ show_typexpr r.typexpr ^ ")"
      | Coerced r -> "Coerced(" ^ "expression=" ^ show_expr r.expression ^ ", typexpr=" ^ show_typexpr r.typexpr ^ ")"
      | Labelled r -> "Labelled(" ^ "label=" ^ Fun.id r.label ^ ", value=" ^ show_expr r.value ^ ")"
      | Verbatim r -> "Verbatim(" ^ "code=" ^ Fun.id r.code ^ ")"
    and show_field_value (v : field_value) =
      "FieldValue(" ^ "name=" ^ Fun.id v.name ^ ", value=" ^ show_expr v.value ^ ")"

    type tag = { name : string; carries : typexpr list }

    let rec show_tag (v : tag) =
      "Tag(" ^ "name=" ^ Fun.id v.name ^ ", carries=" ^ fk_show_list show_typexpr v.carries ^ ")"

    type type_body =
      | AbstractType
      | AliasType of { typexpr : typexpr }
      | RecordType of { fields : field_declaration list }
      | VariantType of { constructors : constructor_declaration list }
      | PolymorphicVariantType of { tags : tag list }

    let rec show_type_body (v : type_body) =
      match v with
      | AbstractType -> "AbstractType"
      | AliasType r -> "AliasType(" ^ "typexpr=" ^ show_typexpr r.typexpr ^ ")"
      | RecordType r -> "RecordType(" ^ "fields=" ^ fk_show_list show_field_declaration r.fields ^ ")"
      | VariantType r -> "VariantType(" ^ "constructors=" ^ fk_show_list show_constructor_declaration r.constructors ^ ")"
      | PolymorphicVariantType r -> "PolymorphicVariantType(" ^ "tags=" ^ fk_show_list show_tag r.tags ^ ")"

    type type_definition = { name : string; parameters : string list; body : type_body }

    let rec show_type_definition (v : type_definition) =
      "TypeDefinition(" ^ "name=" ^ Fun.id v.name ^ ", parameters=" ^ fk_show_list Fun.id v.parameters ^ ", body=" ^ show_type_body v.body ^ ")"

    type signature_item =
      | TypeSignature of { definition : type_definition }
      | ValueSignature of { name : string; typexpr : typexpr }

    let rec show_signature_item (v : signature_item) =
      match v with
      | TypeSignature r -> "TypeSignature(" ^ "definition=" ^ show_type_definition r.definition ^ ")"
      | ValueSignature r -> "ValueSignature(" ^ "name=" ^ Fun.id r.name ^ ", typexpr=" ^ show_typexpr r.typexpr ^ ")"

    type item =
      | LetItem of { recursive : bool; bindings : binding list }
      | TypeItem of { definitions : type_definition list }
      | ModuleItem of { name : string; definition : module_expr }
      | EffectItem of { operations : effect_operation list }
      | CommentItem of { text : string }
      | ModuleTypeItem of { name : string; signature : signature_item list }
      | VerbatimItem of { code : string }
    and module_expr =
      | Structure of { items : item list }
      | ModulePath of { path : string }

    let rec show_item (v : item) =
      match v with
      | LetItem r -> "LetItem(" ^ "recursive=" ^ string_of_bool r.recursive ^ ", bindings=" ^ fk_show_list show_binding r.bindings ^ ")"
      | TypeItem r -> "TypeItem(" ^ "definitions=" ^ fk_show_list show_type_definition r.definitions ^ ")"
      | ModuleItem r -> "ModuleItem(" ^ "name=" ^ Fun.id r.name ^ ", definition=" ^ show_module_expr r.definition ^ ")"
      | EffectItem r -> "EffectItem(" ^ "operations=" ^ fk_show_list show_effect_operation r.operations ^ ")"
      | CommentItem r -> "CommentItem(" ^ "text=" ^ Fun.id r.text ^ ")"
      | ModuleTypeItem r -> "ModuleTypeItem(" ^ "name=" ^ Fun.id r.name ^ ", signature=" ^ fk_show_list show_signature_item r.signature ^ ")"
      | VerbatimItem r -> "VerbatimItem(" ^ "code=" ^ Fun.id r.code ^ ")"
    and show_module_expr (v : module_expr) =
      match v with
      | Structure r -> "Structure(" ^ "items=" ^ fk_show_list show_item r.items ^ ")"
      | ModulePath r -> "ModulePath(" ^ "path=" ^ Fun.id r.path ^ ")"

    module Printer = struct
      type place =
        | Anywhere
        | LetValue
        | SequenceFirst
        | Branch
        | CaseBody of { last : bool }
        | Element
        | Operand of { level : int }
        | Head
        | Argument
        | Target

      let rec show_place (v : place) =
        match v with
        | Anywhere -> "Anywhere"
        | LetValue -> "LetValue"
        | SequenceFirst -> "SequenceFirst"
        | Branch -> "Branch"
        | CaseBody r -> "CaseBody(" ^ "last=" ^ string_of_bool r.last ^ ")"
        | Element -> "Element"
        | Operand r -> "Operand(" ^ "level=" ^ string_of_int r.level ^ ")"
        | Head -> "Head"
        | Argument -> "Argument"
        | Target -> "Target"

      let arrow_level =
        1

      let product_level =
        2

      let applied =
        3

      let arrow_parameter =
        2

      let product_part =
        3

      let rec typexpr (t : typexpr) (minimum : int) : string =
        let level = match t with
          | Polymorphic { variables = _; body = _ } -> 0
          | Arrow { parameter = _; result = _ } -> arrow_level
          | Product { parts = _ } -> product_level
          | _ -> applied in
        let text = match t with
          | TypeVar { name = name } -> name
          | TypeApplication { name = name; arguments = [] } -> name
          | TypeApplication { name = name; arguments = [argument] } -> (typexpr argument applied ^ " ") ^ name
          | TypeApplication { name = name; arguments = arguments } -> (("(" ^ String.concat ", " (List.map Fun.id (List.map (fun it -> typexpr it 0) arguments))) ^ ") ") ^ name
          | Arrow { parameter = parameter; result = result } -> let fk_arg1 = typexpr parameter arrow_parameter ^ " -> " in
              let fk_arg2 = typexpr result arrow_level in
              fk_arg1 ^ fk_arg2
          | Product { parts = parts } -> String.concat " * " (List.map Fun.id (List.map (fun it -> typexpr it product_part) parts))
          | Polymorphic { variables = variables; body = body } -> let fk_arg1 = String.concat " " (List.map Fun.id variables) ^ ". " in
              let fk_arg2 = typexpr body 0 in
              fk_arg1 ^ fk_arg2 in
        if level < minimum then "(" ^ text ^ ")" else text

      let alias_pattern =
        1

      let or_pattern =
        2

      let cons_pattern =
        3

      let constructor_pattern =
        4

      let atomic_pattern =
        5

      let float_text (x : float) : string =
        let text = fk_show_float x in
        if text = "NaN" then "nan" else if text = "Infinity" then "infinity" else if text = "-Infinity" then "neg_infinity" else if x < 0.0 then "(" ^ text ^ ")" else text

      let escaped (c : int) : string =
        if c = 34 then "\\\"" else if c = 92 then "\\\\" else if c = 10 then "\\n" else if c = 9 then "\\t" else if c = 13 then "\\r" else if Fun.id c < 32 then (let fk_arg1 = "\\" ^ (if Fun.id c < 10 then "00" else "0") in
                     let fk_arg2 = string_of_int (Fun.id c) in
                     fk_arg1 ^ fk_arg2) else fk_show_char c

      let quoted (text : string) : string =
        ("\"" ^ String.concat "" (List.map Fun.id (List.map (fun c -> escaped c) ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) text)))) ^ "\""

      let constant (c : constant) : string =
        match c with
        | IntConstant { value = n } -> if n < 0 then "(" ^ string_of_int n ^ ")" else string_of_int n
        | FloatConstant { value = x } -> float_text x
        | StringConstant { value = s } -> quoted s
        | BooleanConstant { value = b } -> string_of_bool b
        | UnitConstant -> "()"

      let rec pat (p : pat) (minimum : int) : string =
        let level = match p with
          | AliasPat { pattern = _; name = _ } -> alias_pattern
          | OrPat { left = _; right = _ } -> or_pattern
          | ConsPat { head = _; tail = _ } -> cons_pattern
          | ConstructorPat { name = _; argument = Some _ } -> constructor_pattern
          | _ -> atomic_pattern in
        let text = match p with
          | AnyPat -> "_"
          | VariablePat { name = name } -> name
          | ConstantPat { constant = c } -> constant c
          | TuplePat { parts = parts } -> ("(" ^ String.concat ", " (List.map Fun.id (List.map (fun it -> pat it or_pattern) parts))) ^ ")"
          | ListPat { items = items } -> ("[" ^ String.concat "; " (List.map Fun.id (List.map (fun it -> pat it or_pattern) items))) ^ "]"
          | ConsPat { head = head; tail = tail } -> let fk_arg1 = pat head constructor_pattern ^ " :: " in
              let fk_arg2 = pat tail cons_pattern in
              fk_arg1 ^ fk_arg2
          | ConstructorPat { name = name; argument = None } -> name
          | ConstructorPat { name = name; argument = Some argument } -> (name ^ " ") ^ pat argument atomic_pattern
          | RecordPat { fields = fields; open_ = open_ } -> ("{ " ^ String.concat "; " (List.map Fun.id (List.map (fun f -> (f : field_pat).name ^ " = " ^ pat (f : field_pat).pattern or_pattern) fields @ (if open_ then ["_"] else [])))) ^ " }"
          | AliasPat { pattern = pattern; name = name } -> (pat pattern or_pattern ^ " as ") ^ name
          | TypedPat { pattern = pattern; typexpr = t } -> (let fk_arg1 = ("(" ^ pat pattern alias_pattern) ^ " : " in
               let fk_arg2 = typexpr t 0 in
               fk_arg1 ^ fk_arg2) ^ ")"
          | OrPat { left = left; right = right } -> let fk_arg1 = pat left or_pattern ^ " | " in
              let fk_arg2 = pat right cons_pattern in
              fk_arg1 ^ fk_arg2
          | EffectPat { operation = operation; continuation = k } -> (("effect " ^ pat operation atomic_pattern) ^ ", ") ^ k
          | TypePat { type_name = name } -> "#" ^ name
          | PackedPat { module_ = module_; signature = signature } -> "(module " ^ module_ ^ " : " ^ signature ^ ")" in
        if level < minimum then "(" ^ text ^ ")" else text

      let head (b : binding) : string =
        let fk_arg1 = let fk_arg1 = pat (b : binding).pattern atomic_pattern in
          let fk_arg2 = String.concat "" (List.map Fun.id (List.map (fun it -> " " ^ pat it atomic_pattern) (b : binding).parameters)) in
          fk_arg1 ^ fk_arg2 in
        let fk_arg2 = Option.value (Option.map (fun it -> " : " ^ typexpr it 0) (b : binding).result) ~default:"" in
        fk_arg1 ^ fk_arg2

      let open_level =
        0

      let sequence_level =
        10

      let if_level =
        15

      let update_level =
        20

      let operator_level (operator : string) : int =
        if operator = "**" then 80 else if List.exists (fun it -> String.starts_with ~prefix:it operator) ["*"; "/"; "%"; "mod"; "land"; "lor"; "lxor"; "lsl"; "lsr"; "asr"] && operator <> "**" then 70 else if operator = "::" then 55 else if String.starts_with ~prefix:"+" operator || String.starts_with ~prefix:"-" operator then 60 else if String.starts_with ~prefix:"@" operator || String.starts_with ~prefix:"^" operator then 50 else if operator = "&&" || operator = "&" then 35 else if operator = "||" || operator = "or" then 30 else if operator = ":=" then 25 else 40

      let application_level =
        90

      let field_level =
        95

      let atomic_level =
        100

      let level (e : expr) : int =
        match e with
        | Fun { parameters = _; body = _ } -> open_level
        | LetIn { recursive = _; bindings = _; body = _ } -> open_level
        | Match { subject = _; cases = _ } -> open_level
        | Sequence { first = _; then_ = _ } -> sequence_level
        | IfThenElse { condition = _; then_ = _; otherwise = _ } -> if_level
        | FieldUpdate { record = _; field = _; value = _ } -> update_level
        | Infix { operator = operator; left = _; right = _ } -> operator_level operator
        | Application { function_ = _; arguments = _ } -> application_level
        | Construction { name = _; argument = Some _ } -> application_level
        | FieldAccess { record = _; field = _ } -> field_level
        | _ -> atomic_level

      let ends_open (e : expr) : bool =
        level e = open_level

      let rec ends_in_match (e : expr) : bool =
        match e with
        | Match { subject = _; cases = _ } -> true
        | Fun { parameters = _; body = body } -> ends_in_match body
        | LetIn { recursive = _; bindings = _; body = body } -> ends_in_match body
        | Sequence { first = _; then_ = then_ } -> ends_in_match then_
        | _ -> false

      let needs_parentheses (e : expr) (place : place) : bool =
        match place with
        | Anywhere -> false
        | LetValue -> level e = sequence_level
        | SequenceFirst -> level e <= sequence_level || ends_open e
        | Branch -> level e < if_level
        | CaseBody { last = last } -> not last && ends_in_match e
        | Element -> level e <= update_level
        | Operand { level = minimum } -> level e < minimum
        | Head -> level e < application_level
        | Argument -> level e < field_level
        | Target -> level e < field_level

      let right_associative =
        ["**"; "::"; "@"; "^"; "&&"; "||"; ":="]

      let rec expr (e : expr) (place : place) (indent : string) : string =
        if needs_parentheses e place then ("(" ^ bare e (indent ^ " ")) ^ ")" else bare e indent
      and bare (e : expr) (indent : string) : string =
        match e with
        | Identifier { path = path } -> path
        | ConstantExpr { constant = c } -> constant c
        | Application { function_ = function_; arguments = arguments } -> let fk_arg1 = expr function_ (Head : place) indent in
            let fk_arg2 = String.concat "" (List.map Fun.id (List.map (fun it -> " " ^ expr it (Argument : place) indent) arguments)) in
            fk_arg1 ^ fk_arg2
        | Infix { operator = operator; left = left; right = right } -> let level = operator_level operator in
            let from_right = List.mem operator right_associative in
            let fk_arg1 = expr left (Operand { level = (if from_right then level + 1 else level) } : place) indent ^ " " ^ operator ^ " " in
            let fk_arg2 = expr right (Operand { level = (if from_right then level else level + 1) } : place) indent in
            fk_arg1 ^ fk_arg2
        | Fun { parameters = parameters; body = body } -> let fk_arg1 = ("fun " ^ String.concat " " (List.map Fun.id (List.map (fun it -> pat it atomic_pattern) parameters))) ^ " -> " in
            let fk_arg2 = expr body (Anywhere : place) (indent ^ "  ") in
            fk_arg1 ^ fk_arg2
        | LetIn { recursive = recursive; bindings = bindings; body = body } -> let keyword = if recursive then "let rec" else "let" in
            let fk_arg1 = String.concat "" (List.map Fun.id (List.mapi (fun n b -> let fk_arg1 = ((if n = 0 then keyword ^ " " else "\n" ^ indent ^ "and ") ^ head b) ^ " = " in
                   let fk_arg2 = expr (b : binding).body (LetValue : place) (indent ^ "  ") in
                   fk_arg1 ^ fk_arg2) bindings)) ^ " in\n" ^ indent in
            let fk_arg2 = expr body (Anywhere : place) indent in
            fk_arg1 ^ fk_arg2
        | Sequence { first = first; then_ = then_ } -> let fk_arg1 = expr first (SequenceFirst : place) indent ^ ";\n" ^ indent in
            let fk_arg2 = expr then_ (Anywhere : place) indent in
            fk_arg1 ^ fk_arg2
        | IfThenElse { condition = condition; then_ = then_; otherwise = otherwise } -> let fk_arg1 = expr condition (LetValue : place) indent in
            let fk_arg2 = expr then_ (Branch : place) (indent ^ "  ") in
            let fk_arg3 = expr otherwise (Branch : place) (indent ^ "  ") in
            "if " ^ fk_arg1 ^ " then " ^ fk_arg2 ^ " else " ^ fk_arg3
        | Match { subject = subject; cases = cases } -> let inner = indent ^ "    " in
            let fk_arg1 = "match " ^ expr subject (LetValue : place) indent ^ " with" in
            let fk_arg2 = String.concat "" (List.map Fun.id (List.mapi (fun n c -> let guard = Option.value (Option.map (fun it -> " when " ^ expr it (LetValue : place) inner) (c : case).guard) ~default:"" in
                   let fk_arg1 = pat (c : case).pattern 0 in
                   let fk_arg2 = expr (c : case).body (CaseBody { last = n = List.length cases - 1 } : place) inner in
                   "\n" ^ indent ^ "| " ^ fk_arg1 ^ guard ^ " -> " ^ fk_arg2) cases)) in
            fk_arg1 ^ fk_arg2
        | TupleExpr { parts = parts } -> ("(" ^ String.concat ", " (List.map Fun.id (List.map (fun it -> expr it (Element : place) indent) parts))) ^ ")"
        | ListExpr { items = items } -> ("[" ^ String.concat "; " (List.map Fun.id (List.map (fun it -> expr it (Element : place) indent) items))) ^ "]"
        | RecordExpr { fields = fields; base = base } -> (let fk_arg1 = "{ " ^ Option.value (Option.map (fun it -> expr it (Argument : place) indent ^ " with ") base) ~default:"" in
             let fk_arg2 = String.concat "; " (List.map Fun.id (List.map (fun f -> (f : field_value).name ^ " = " ^ expr (f : field_value).value (Element : place) indent) fields)) in
             fk_arg1 ^ fk_arg2) ^ " }"
        | FieldAccess { record = record; field = field } -> (expr record (Target : place) indent ^ ".") ^ field
        | FieldUpdate { record = record; field = field; value = value } -> let fk_arg1 = ((expr record (Target : place) indent ^ ".") ^ field) ^ " <- " in
            let fk_arg2 = expr value (Operand { level = update_level + 1 } : place) indent in
            fk_arg1 ^ fk_arg2
        | Construction { name = name; argument = None } -> name
        | Construction { name = name; argument = Some argument } -> (name ^ " ") ^ expr argument (Argument : place) indent
        | Annotated { expression = inner; typexpr = t } -> (let fk_arg1 = ("(" ^ expr inner (Anywhere : place) indent) ^ " : " in
             let fk_arg2 = typexpr t 0 in
             fk_arg1 ^ fk_arg2) ^ ")"
        | Coerced { expression = inner; typexpr = t } -> (let fk_arg1 = ("(" ^ expr inner (Anywhere : place) indent) ^ " :> " in
             let fk_arg2 = typexpr t 0 in
             fk_arg1 ^ fk_arg2) ^ ")"
        | Labelled { label = label; value = value } -> ("~" ^ label ^ ":") ^ expr value (Argument : place) indent
        | Verbatim { code = code } -> "(" ^ code ^ ")"

      let binding (b : binding) (indent : string) : string =
        let inner = indent ^ "  " in
        let fk_arg1 = head b in
        let fk_arg2 = expr (b : binding).body (Anywhere : place) inner in
        fk_arg1 ^ " =\n" ^ inner ^ fk_arg2

      let binding_group (keyword : string) (bindings : binding list) (indent : string) : string =
        String.concat "\n" (List.map Fun.id (List.mapi (fun n b -> (if n = 0 then keyword ^ " " else indent ^ "and ") ^ binding b indent) bindings))

      let type_parameters (parameters : string list) : string =
        match parameters with
        | [] -> ""
        | [one] -> one ^ " "
        | _ -> "(" ^ String.concat ", " (List.map Fun.id parameters) ^ ") "

      let record_fields (fields : field_declaration list) : string =
        ("{ " ^ String.concat "; " (List.map Fun.id (List.map (fun f -> (if (f : field_declaration).mutable_ then "mutable " else "") ^ (f : field_declaration).name ^ " : " ^ typexpr (f : field_declaration).typexpr 0) fields))) ^ " }"

      let constructor_declaration (c : constructor_declaration) : string =
        (c : constructor_declaration).name ^ (match (c : constructor_declaration).carries with
         | Bare -> ""
         | Values { typexprs = typexprs } -> " of " ^ String.concat " * " (List.map Fun.id (List.map (fun it -> typexpr it product_part) typexprs))
         | InlineRecord { fields = fields } -> " of " ^ record_fields fields)

      let type_definition (d : type_definition) (indent : string) : string =
        let fk_arg1 = type_parameters (d : type_definition).parameters ^ (d : type_definition).name in
        let fk_arg2 = match (d : type_definition).body with
          | AbstractType -> ""
          | AliasType { typexpr = t } -> " = " ^ typexpr t 0
          | RecordType { fields = fields } -> " = " ^ record_fields fields
          | VariantType { constructors = constructors } -> " =" ^ String.concat "" (List.map Fun.id (List.map (fun it -> ("\n" ^ indent ^ "  | ") ^ constructor_declaration it) constructors))
          | PolymorphicVariantType { tags = tags } -> (" = [ " ^ String.concat " | " (List.map Fun.id (List.map (fun t -> ("`" ^ (t : tag).name) ^ (if List.is_empty (t : tag).carries then "" else " of " ^ String.concat " * " (List.map Fun.id (List.map (fun it -> typexpr it product_part) (t : tag).carries)))) tags))) ^ " ]" in
        fk_arg1 ^ fk_arg2

      let effect_operation (o : effect_operation) : string =
        let carried = match (o : effect_operation).parameters with
          | [] -> (TypeApplication { name = "unit"; arguments = [] } : typexpr)
          | [one] -> one
          | _ -> (Product { parts = (o : effect_operation).parameters } : typexpr) in
        (let fk_arg1 = (((o : effect_operation).name ^ " : ") ^ typexpr carried arrow_parameter) ^ " -> " in
         let fk_arg2 = typexpr (o : effect_operation).result applied in
         fk_arg1 ^ fk_arg2) ^ " Effect.t"

      let signature_item (i : signature_item) (indent : string) : string =
        match i with
        | TypeSignature { definition = d } -> "type " ^ type_definition d indent
        | ValueSignature { name = name; typexpr = t } -> ("val " ^ name ^ " : ") ^ typexpr t 0

      let rec item (i : item) (indent : string) : string =
        match i with
        | LetItem { recursive = recursive; bindings = bindings } -> binding_group (if recursive then "let rec" else "let") bindings indent
        | TypeItem { definitions = definitions } -> String.concat "\n" (List.map Fun.id (List.mapi (fun n d -> (if n = 0 then "type " else indent ^ "and ") ^ type_definition d indent) definitions))
        | ModuleItem { name = name; definition = definition } -> "module " ^ name ^ " = " ^ module_expr definition indent
        | EffectItem { operations = operations } -> "type _ Effect.t +=" ^ String.concat "" (List.map Fun.id (List.map (fun it -> "\n" ^ indent ^ "  | " ^ effect_operation it) operations))
        | CommentItem { text = text } -> "(* " ^ text ^ " *)"
        | VerbatimItem { code = code } -> code
        | ModuleTypeItem { name = name; signature = signature } -> let inner = indent ^ "  " in
            (("module type " ^ name ^ " = sig") ^ String.concat "" (List.map Fun.id (List.map (fun it -> ("\n" ^ inner) ^ signature_item it inner) signature))) ^ "\n" ^ indent ^ "end"
      and module_expr (m : module_expr) (indent : string) : string =
        match m with
        | Structure { items = items } -> let inner = indent ^ "  " in
            ("struct\n" ^ String.concat "\n\n" (List.map Fun.id (List.map (fun it -> inner ^ item it inner) items))) ^ "\n" ^ indent ^ "end"
        | ModulePath { path = path } -> path

      let file (items : item list) : string =
        String.concat "\n\n" (List.map Fun.id (List.map (fun it -> item it "") items)) ^ "\n"

      let expression (e : expr) (indent : string) : string =
        expr e (Anywhere : place) indent
    end
  end

  module Lowering = struct
    type own_code = { groups : (Checker.Inference.function_group * (Checker.Symbols.symbol * Checker.Types.type_ * Checker.Core.core_function) list) list; types : Checker.Core.type_declaration list; effects : Checker.Core.declared_effect list; specs : Checker.Core.declared_spec list; modules : string list list; besides : (string list * Ocaml.item) list }

    let rec show_own_code (v : own_code) =
      "OwnCode(" ^ "groups=" ^ fk_show_list (fun (x0, x1) -> "(" ^ Checker.Inference.show_function_group x0 ^ ", " ^ fk_show_list (fun (x0, x1, x2) -> "(" ^ Checker.Symbols.show_symbol x0 ^ ", " ^ Checker.Types.show_type x1 ^ ", " ^ Checker.Core.show_core_function x2 ^ ")") x1 ^ ")") v.groups ^ ", types=" ^ fk_show_list Checker.Core.show_type_declaration v.types ^ ", effects=" ^ fk_show_list Checker.Core.show_declared_effect v.effects ^ ", specs=" ^ fk_show_list Checker.Core.show_declared_spec v.specs ^ ", modules=" ^ fk_show_list (fk_show_list Fun.id) v.modules ^ ", besides=" ^ fk_show_list (fun (x0, x1) -> "(" ^ fk_show_list Fun.id x0 ^ ", " ^ Ocaml.show_item x1 ^ ")") v.besides ^ ")"

    type part =
      | TypesPart of { types : Checker.Core.type_declaration list }
      | EffectPart of { effect_ : Checker.Core.declared_effect }
      | SpecPart of { spec : Checker.Core.declared_spec }
      | GroupPart of { group : Checker.Inference.function_group }
      | ModulePart of { path : string list }

    let rec show_part (v : part) =
      match v with
      | TypesPart r -> "TypesPart(" ^ "types=" ^ fk_show_list Checker.Core.show_type_declaration r.types ^ ")"
      | EffectPart r -> "EffectPart(" ^ "effect=" ^ Checker.Core.show_declared_effect r.effect_ ^ ")"
      | SpecPart r -> "SpecPart(" ^ "spec=" ^ Checker.Core.show_declared_spec r.spec ^ ")"
      | GroupPart r -> "GroupPart(" ^ "group=" ^ Checker.Inference.show_function_group r.group ^ ")"
      | ModulePart r -> "ModulePart(" ^ "path=" ^ fk_show_list Fun.id r.path ^ ")"

    type _ Effect.t +=
      | Lowering_toStringOf : string -> Checker.Symbols.symbol option Effect.t
      | Lowering_declarationOf : string -> Checker.Core.type_declaration option Effect.t
      | Lowering_isShared : string -> bool Effect.t
      | Lowering_specOf : string -> Checker.Core.declared_spec option Effect.t
      | Lowering_effectOf : string -> Checker.Core.declared_effect option Effect.t
      | Lowering_isModule : string list -> bool Effect.t
      | Lowering_isHidden : string list -> bool Effect.t
      | Lowering_inside : unit -> string list Effect.t

    type 'fk_answer lowering_handler = { to_string_of : string -> (Checker.Symbols.symbol option -> 'fk_answer) -> 'fk_answer; declaration_of : string -> (Checker.Core.type_declaration option -> 'fk_answer) -> 'fk_answer; is_shared : string -> (bool -> 'fk_answer) -> 'fk_answer; spec_of : string -> (Checker.Core.declared_spec option -> 'fk_answer) -> 'fk_answer; effect_of : string -> (Checker.Core.declared_effect option -> 'fk_answer) -> 'fk_answer; is_module : string list -> (bool -> 'fk_answer) -> 'fk_answer; is_hidden : string list -> (bool -> 'fk_answer) -> 'fk_answer; inside : (string list -> 'fk_answer) -> 'fk_answer }

    let handle_lowering (h : 'fk_answer lowering_handler) (f : unit -> 'fk_answer) : 'fk_answer =
      match f () with
      | v -> v
      | effect (Lowering_toStringOf x0), k -> h.to_string_of x0 (fun v -> Effect.Deep.continue k v)
      | effect (Lowering_declarationOf x0), k -> h.declaration_of x0 (fun v -> Effect.Deep.continue k v)
      | effect (Lowering_isShared x0), k -> h.is_shared x0 (fun v -> Effect.Deep.continue k v)
      | effect (Lowering_specOf x0), k -> h.spec_of x0 (fun v -> Effect.Deep.continue k v)
      | effect (Lowering_effectOf x0), k -> h.effect_of x0 (fun v -> Effect.Deep.continue k v)
      | effect (Lowering_isModule x0), k -> h.is_module x0 (fun v -> Effect.Deep.continue k v)
      | effect (Lowering_isHidden x0), k -> h.is_hidden x0 (fun v -> Effect.Deep.continue k v)
      | effect (Lowering_inside ()), k -> h.inside (fun v -> Effect.Deep.continue k v)

    module Naming = struct
      let outer_alias (module_ : string) : string =
        "Fk_outer_" ^ module_

      let module_name (name : string) : string =
        match (fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) name with
        | [] -> name
        | first :: rest -> let fk_arg1 = fk_show_char (Lang.Strings.char_uppercase first) in
            let fk_arg2 = String.concat "" (List.map Fun.id (List.map (fun it -> fk_show_char it) rest)) in
            fk_arg1 ^ fk_arg2

      let relative (path : string list) : string list =
        let here = Effect.perform (Lowering_inside ()) in
        let common = List.length (Lang.Lists.list_take_while (Lang.Lists.list_zip path here) (fun (a, b) -> a = b)) in
        match List.drop common path with
        | first :: rest when Effect.perform (Lowering_isHidden (List.take (common + 1) path)) && List.exists (fun k -> let nearer = List.take k here @ [first] in
               nearer <> List.take (common + 1) path && Effect.perform (Lowering_isModule nearer)) (Lang.Maths.int_range_to (common + 1) (List.length here)) -> outer_alias (module_name first) :: rest
        | other -> other

      let keywords =
        ["and"; "as"; "assert"; "asr"; "begin"; "class"; "constraint"; "do"; "done"; "downto"; "effect"; "else"; "end"; "exception"; "external"; "false"; "for"; "fun"; "function"; "functor"; "if"; "in"; "include"; "inherit"; "initializer"; "land"; "lazy"; "let"; "lor"; "lsl"; "lsr"; "lxor"; "match"; "method"; "mod"; "module"; "mutable"; "new"; "nonrec"; "object"; "of"; "open"; "or"; "private"; "rec"; "sig"; "struct"; "then"; "to"; "true"; "try"; "type"; "val"; "virtual"; "when"; "while"; "with"]

      let escaped (name : string) : string =
        if List.mem name keywords then name ^ "_" else name

      let rec underscored (chars : int list) (previous : int option) (done_ : string) : string =
        match chars with
        | [] -> done_
        | c :: rest -> let starts_word = Lang.Strings.char_is_upper_case c && (match previous with
               | Some p -> (Lang.Strings.char_is_lower_case p || Lang.Strings.char_is_digit p) || Lang.Strings.char_is_upper_case p && Option.value (Option.map (fun it -> Lang.Strings.char_is_lower_case it) (List.nth_opt rest 0)) ~default:false
               | None -> false) in
            underscored rest (Some c) ((done_ ^ (if starts_word then "_" else "")) ^ fk_show_char (Lang.Strings.char_lowercase c))

      let rec snake (name : string) : string =
        escaped (if Lang.Strings.string_contains name "$" then String.concat "_" (List.map Fun.id (List.map (fun it -> Lang.Strings.string_remove_suffix (snake it) "_") ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name "$"))) else underscored ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) name) None "")

      let own_name (s : Checker.Symbols.symbol) : string =
        if List.is_empty (s : Checker.Symbols.symbol).Checker.Symbols.path then (s : Checker.Symbols.symbol).Checker.Symbols.name else (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in String.sub s i (String.length s - i)) (s : Checker.Symbols.symbol).Checker.Symbols.name ((fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) (String.concat "." (List.map Fun.id (s : Checker.Symbols.symbol).Checker.Symbols.path)) + 1)

      let reference (s : Checker.Symbols.symbol) (own : string -> string) : string =
        String.concat "." (List.map Fun.id (let fk_arg1 = List.map (fun it -> module_name it) (relative (s : Checker.Symbols.symbol).Checker.Symbols.path) in
          let fk_arg2 = [own (own_name s)] in
          fk_arg1 @ fk_arg2))

      let value_reference (s : Checker.Symbols.symbol) : string =
        reference s (fun it -> snake it)

      let module_path (m : Checker.Symbols.symbol) : string =
        String.concat "." (List.map Fun.id (List.map (fun it -> module_name it) (relative ((m : Checker.Symbols.symbol).Checker.Symbols.path @ [own_name m]))))
    end

    module Declarations = struct
      let parameters (t : Checker.Core.type_declaration) : string list =
        match t with
        | Checker.Core.DeclaredRecord { record = _; type_parameters = ps; fields = _ } -> ps
        | Checker.Core.DeclaredCases { case_type = _; type_parameters = ps; cases = _ } -> ps
        | Checker.Core.DeclaredAlias { alias = _; type_parameters = ps; target = _ } -> ps
        | Checker.Core.DeclaredExternal { external_ = _; type_parameters = ps; ocaml = _ } -> ps

      let declared_at (t : Checker.Core.type_declaration) : Checker.Symbols.symbol =
        match t with
        | Checker.Core.DeclaredRecord { record = s; type_parameters = _; fields = _ } -> s
        | Checker.Core.DeclaredCases { case_type = s; type_parameters = _; cases = _ } -> s
        | Checker.Core.DeclaredAlias { alias = s; type_parameters = _; target = _ } -> s
        | Checker.Core.DeclaredExternal { external_ = s; type_parameters = _; ocaml = _ } -> s
    end

    module OcamlTypes = struct
      let ocaml_parameters (names : string list) : string list =
        List.filter (fun it -> not (String.starts_with ~prefix:"@" it)) names

      let type_reference (full : string) : string =
        let parts = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) full "." in
        String.concat "." (List.map Fun.id (let fk_arg1 = List.map (fun it -> Naming.module_name it) (Naming.relative (Lang.Lists.list_drop_last parts 1)) in
          let fk_arg2 = [Naming.snake (Option.value (Lang.Lists.list_last_or_none parts) ~default:full)] in
          fk_arg1 @ fk_arg2))

      let ocaml_arguments (name : string) (arguments : Checker.Types.type_ list) : Checker.Types.type_ list =
        match Option.map (fun it -> Declarations.parameters it) (Effect.perform (Lowering_declarationOf name)) with
        | Some parameters when let fk_arg1 = List.length parameters in
            let fk_arg2 = List.length arguments in
            fk_arg1 = fk_arg2 -> List.map (fun (_, a) -> a) (List.filter (fun (p, _) -> not (String.starts_with ~prefix:"@" p)) (Lang.Lists.list_zip parameters arguments))
        | _ -> List.filter (fun it -> match it with
               | Checker.Types.Effects it_as_effects -> false
               | _ -> true) arguments

      let own_name (full : string) : string =
        Naming.snake (Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) full ".")) ~default:full)

      let type_module_reference (full : string) : string =
        let parts = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) full "." in
        String.concat "." (List.map Fun.id (List.map (fun it -> Naming.module_name it) (let fk_arg1 = Naming.relative (Lang.Lists.list_drop_last parts 1) in
           let fk_arg2 = [Option.value (Lang.Lists.list_last_or_none parts) ~default:full] in
           fk_arg1 @ fk_arg2)))

      let own_types (spec : string) : string list =
        Option.value (Option.map (fun d -> List.map (fun (name, _) -> Lang.Strings.string_remove_suffix (Naming.snake name) "_") (d : Checker.Core.declared_spec).Checker.Core.types) (Effect.perform (Lowering_specOf spec))) ~default:[]

      let package_type (spec : string) (given : string list) : string =
        let fk_arg1 = type_module_reference spec in
        let fk_arg2 = String.concat "" (List.map Fun.id (List.mapi (fun i entry -> let (t, type_given) = entry in
               ((((if i = 0 then " with" else " and") ^ " type ") ^ t) ^ " = ") ^ type_given) (Lang.Lists.list_zip (own_types spec) given))) in
        fk_arg1 ^ fk_arg2

      let parameter (name : string) : string =
        "'" ^ String.lowercase_ascii name

      let external_text (ocaml : string) (parameters : string list) (given : Ocaml.typexpr list) : string =
        List.fold_left (fun text entry -> let (p, t) = entry in
           let fk_arg1 = parameter p in
           let fk_arg2 = ("(" ^ Ocaml.Printer.typexpr t 0) ^ ")" in
           Lang.Strings.string_replace text fk_arg1 fk_arg2) ocaml (Lang.Lists.list_zip parameters given)

      let builtin_or_declared (name : string) (given : Ocaml.typexpr list) : Ocaml.typexpr =
        match name with
        | "Int" -> (Ocaml.TypeApplication { name = "int"; arguments = [] } : Ocaml.typexpr)
        | "Float" -> (Ocaml.TypeApplication { name = "float"; arguments = [] } : Ocaml.typexpr)
        | "Double" -> (Ocaml.TypeApplication { name = "float"; arguments = [] } : Ocaml.typexpr)
        | "String" -> (Ocaml.TypeApplication { name = "string"; arguments = [] } : Ocaml.typexpr)
        | "Boolean" -> (Ocaml.TypeApplication { name = "bool"; arguments = [] } : Ocaml.typexpr)
        | "Unit" -> (Ocaml.TypeApplication { name = "unit"; arguments = [] } : Ocaml.typexpr)
        | "Nothing" -> (Ocaml.TypeApplication { name = "fk_nothing"; arguments = [] } : Ocaml.typexpr)
        | "Char" -> (Ocaml.TypeApplication { name = "int"; arguments = [] } : Ocaml.typexpr)
        | "Byte" -> (Ocaml.TypeApplication { name = "char"; arguments = [] } : Ocaml.typexpr)
        | "List" -> (Ocaml.TypeApplication { name = "list"; arguments = given } : Ocaml.typexpr)
        | "Option" -> (Ocaml.TypeApplication { name = "option"; arguments = given } : Ocaml.typexpr)
        | "Result" -> (Ocaml.TypeApplication { name = "result"; arguments = given } : Ocaml.typexpr)
        | "Lazy" -> (Ocaml.TypeApplication { name = "Lazy.t"; arguments = given } : Ocaml.typexpr)
        | _ -> (Ocaml.TypeApplication { name = type_reference name; arguments = given } : Ocaml.typexpr)

      let rec typexpr_naming (t : Checker.Types.type_) (variables : (Checker.Types.type_variable * string) list) : Ocaml.typexpr =
        match t with
        | Checker.Types.Variable { variable = v } -> (Ocaml.TypeVar { name = Option.value (Option.map (fun (_, name) -> name) (List.find_opt (fun (variable, _) -> variable = v) variables)) ~default:"_" } : Ocaml.typexpr)
        | Checker.Types.TypeParameter { name = name } -> (Ocaml.TypeVar { name = "'" ^ String.lowercase_ascii name } : Ocaml.typexpr)
        | Checker.Types.SpecOwnType { name = name; arguments = arguments } -> let fk_arg1 = Lang.Strings.string_remove_suffix (Naming.snake name) "_" in
            let fk_arg2 = List.map (fun it -> typexpr_naming it variables) arguments in
            (Ocaml.TypeApplication { name = fk_arg1; arguments = fk_arg2 } : Ocaml.typexpr)
        | Checker.Types.ModuleValue { spec = spec; arguments = arguments; own_types = _ } -> (Ocaml.TypeApplication { name = ("(module " ^ package_type spec (List.map (fun it -> Ocaml.Printer.typexpr (typexpr_naming it variables) 0) arguments)) ^ ")"; arguments = [] } : Ocaml.typexpr)
        | Checker.Types.Named { name = name; arguments = arguments; region = _ } -> named name arguments variables
        | Checker.Types.Abstract { name = name; arguments = arguments } -> named name arguments variables
        | Checker.Types.TupleOf { elements = parts } -> (Ocaml.Product { parts = List.map (fun it -> typexpr_naming it variables) parts } : Ocaml.typexpr)
        | Checker.Types.FunctionOf { parameters = parameters; result = result; effects = _ } -> let fk_arg1 = List.rev (if List.is_empty parameters then [(Ocaml.TypeApplication { name = "unit"; arguments = [] } : Ocaml.typexpr)] else List.map (fun it -> typexpr_naming it variables) parameters) in
            let fk_arg2 = typexpr_naming result variables in
            List.fold_left (fun r p -> (Ocaml.Arrow { parameter = p; result = r } : Ocaml.typexpr)) fk_arg2 fk_arg1
        | _ -> (Ocaml.TypeVar { name = "_" } : Ocaml.typexpr)
      and named (name : string) (arguments : Checker.Types.type_ list) (variables : (Checker.Types.type_variable * string) list) : Ocaml.typexpr =
        let given = List.map (fun it -> typexpr_naming it variables) (ocaml_arguments name arguments) in
        match Effect.perform (Lowering_declarationOf name) with
        | Some (Checker.Core.DeclaredExternal { external_ = _; type_parameters = parameters; ocaml = ocaml }) -> (Ocaml.TypeApplication { name = ("(" ^ external_text ocaml parameters given) ^ ")"; arguments = [] } : Ocaml.typexpr)
        | _ -> builtin_or_declared name given

      let typexpr (t : Checker.Types.type_) : Ocaml.typexpr =
        typexpr_naming t []
    end

    module Constructors = struct
      let label (record : Checker.Symbols.symbol) (field : string) : string =
        String.concat "." (List.map Fun.id (let fk_arg1 = List.map (fun it -> Naming.module_name it) (Naming.relative (record : Checker.Symbols.symbol).Checker.Symbols.path) in
          let fk_arg2 = [Naming.snake field] in
          fk_arg1 @ fk_arg2))

      let labelled (record : Checker.Symbols.symbol) (names : string list) (values : Ocaml.expr list) : Ocaml.field_value list =
        List.mapi (fun i entry -> let (name, value) = entry in
           ({ Ocaml.name = (if i = 0 then label record name else Naming.snake name); value = value } : Ocaml.field_value)) (Lang.Lists.list_zip names values)

      let field_names (record : Checker.Symbols.symbol) : string list =
        match ((record : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.RecordDefinition { type_parameters = _; fields = fields; private_constructor = _; annotation = _; external_ = _ } -> List.map (fun it -> (it : Parser.field).Parser.name) fields
        | _ -> []

      let tag_name (c : Checker.Symbols.case_symbol) : string =
        (Lang.Strings.string_replace ((c : Checker.Symbols.case_symbol).Checker.Symbols.owner : Checker.Symbols.symbol).Checker.Symbols.name "." "_" ^ "_") ^ ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.name

      let tag (c : Checker.Symbols.case_symbol) : string =
        "`" ^ tag_name c

      let case_name (c : Checker.Symbols.case_symbol) : string =
        if Effect.perform (Lowering_isShared ((c : Checker.Symbols.case_symbol).Checker.Symbols.owner : Checker.Symbols.symbol).Checker.Symbols.name) then tag c else String.concat "." (List.map Fun.id (List.map (fun it -> Naming.module_name it) (Naming.relative ((c : Checker.Symbols.case_symbol).Checker.Symbols.owner : Checker.Symbols.symbol).Checker.Symbols.path) @ [((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.name]))

      let built (constructor : Checker.Core.constructor) (fields : Ocaml.expr list) : Ocaml.expr =
        match constructor with
        | Checker.Core.RecordConstructor { record = record } -> (Ocaml.RecordExpr { fields = labelled record (field_names record) fields; base = None } : Ocaml.expr)
        | Checker.Core.CaseConstructor { c = c } when Effect.perform (Lowering_isShared ((c : Checker.Symbols.case_symbol).Checker.Symbols.owner : Checker.Symbols.symbol).Checker.Symbols.name) -> let fk_arg1 = tag c in
            let fk_arg2 = match fields with
              | [] -> None
              | [one] -> Some one
              | _ -> Some (Ocaml.TupleExpr { parts = fields } : Ocaml.expr) in
            (Ocaml.Construction { name = fk_arg1; argument = fk_arg2 } : Ocaml.expr)
        | Checker.Core.CaseConstructor { c = c } -> if List.is_empty ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.fields then (Ocaml.Construction { name = case_name c; argument = None } : Ocaml.expr) else (let fk_arg1 = case_name c in
               let fk_arg2 = Some (Ocaml.RecordExpr { fields = List.map (fun (name, value) -> ({ Ocaml.name = Naming.snake name; value = value } : Ocaml.field_value)) (Lang.Lists.list_zip (List.map (fun it -> (it : Parser.field).Parser.name) ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.fields) fields); base = None } : Ocaml.expr) in
               (Ocaml.Construction { name = fk_arg1; argument = fk_arg2 } : Ocaml.expr))
        | Checker.Core.BuiltinCase { name = name } -> (Ocaml.Construction { name = name; argument = List.nth_opt fields 0 } : Ocaml.expr)

      let record_type (owner : Checker.Symbols.symbol) : Ocaml.typexpr =
        let parameters = OcamlTypes.ocaml_parameters (Option.value (Option.map (fun it -> Declarations.parameters it) (Effect.perform (Lowering_declarationOf (owner : Checker.Symbols.symbol).Checker.Symbols.name))) ~default:[]) in
        let fk_arg1 = OcamlTypes.type_reference (owner : Checker.Symbols.symbol).Checker.Symbols.name in
        let fk_arg2 = List.map (fun it -> (Ocaml.TypeVar { name = "_" } : Ocaml.typexpr)) parameters in
        (Ocaml.TypeApplication { name = fk_arg1; arguments = fk_arg2 } : Ocaml.typexpr)

      let narrowed_name (local : string) (case_name : string) : string =
        let fk_arg1 = Naming.snake local ^ "_as_" in
        let fk_arg2 = Lang.Strings.string_remove_suffix (Naming.snake case_name) "_" in
        fk_arg1 ^ fk_arg2

      let pattern (constructor : Checker.Core.constructor) (fields : Ocaml.pat list option) (narrowed : string option) : Ocaml.pat =
        match constructor with
        | Checker.Core.RecordConstructor { record = record } -> (match fields with
             | Some ps -> let fk_arg1 = (Ocaml.RecordPat { fields = List.mapi (fun i entry -> let (name, p) = entry in
                      ({ Ocaml.name = (if i = 0 then label record name else Naming.snake name); pattern = p } : Ocaml.field_pat)) (Lang.Lists.list_zip (field_names record) ps); open_ = false } : Ocaml.pat) in
                 let fk_arg2 = record_type record in
                 (Ocaml.TypedPat { pattern = fk_arg1; typexpr = fk_arg2 } : Ocaml.pat)
             | None -> (Ocaml.AnyPat : Ocaml.pat))
        | Checker.Core.CaseConstructor { c = c } when Effect.perform (Lowering_isShared ((c : Checker.Symbols.case_symbol).Checker.Symbols.owner : Checker.Symbols.symbol).Checker.Symbols.name) -> let given = Option.value fields ~default:(List.map (fun f -> Option.value (Option.map (fun local -> (Ocaml.VariablePat { name = (let fk_arg1 = narrowed_name local ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.name ^ "_" in
                       let fk_arg2 = Naming.snake (f : Parser.field).Parser.name in
                       fk_arg1 ^ fk_arg2) } : Ocaml.pat)) narrowed) ~default:(Ocaml.AnyPat : Ocaml.pat)) ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.fields) in
            let fk_arg1 = tag c in
            let fk_arg2 = match given with
              | [] -> None
              | [one] -> Some one
              | _ -> Some (Ocaml.TuplePat { parts = given } : Ocaml.pat) in
            (Ocaml.ConstructorPat { name = fk_arg1; argument = fk_arg2 } : Ocaml.pat)
        | Checker.Core.CaseConstructor { c = c } -> if List.is_empty ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.fields then (Ocaml.ConstructorPat { name = case_name c; argument = None } : Ocaml.pat) else (let fk_arg1 = case_name c in
               let fk_arg2 = Some (match fields with
                  | Some ps -> (Ocaml.RecordPat { fields = List.map (fun (name, p) -> ({ Ocaml.name = Naming.snake name; pattern = p } : Ocaml.field_pat)) (Lang.Lists.list_zip (List.map (fun it -> (it : Parser.field).Parser.name) ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.fields) ps); open_ = false } : Ocaml.pat)
                  | None -> Option.value (Option.map (fun local -> (Ocaml.VariablePat { name = narrowed_name local ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.name } : Ocaml.pat)) narrowed) ~default:(Ocaml.AnyPat : Ocaml.pat)) in
               (Ocaml.ConstructorPat { name = fk_arg1; argument = fk_arg2 } : Ocaml.pat))
        | Checker.Core.BuiltinCase { name = "None" } -> (Ocaml.ConstructorPat { name = "None"; argument = None } : Ocaml.pat)
        | Checker.Core.BuiltinCase { name = name } -> (Ocaml.ConstructorPat { name = name; argument = Some (Option.value (Option.bind fields (fun it -> List.nth_opt it 0)) ~default:(Ocaml.AnyPat : Ocaml.pat)) } : Ocaml.pat)

      let annotated_record (record : Ocaml.expr) (owner : Checker.Symbols.symbol) : Ocaml.expr =
        (Ocaml.Annotated { expression = record; typexpr = record_type owner } : Ocaml.expr)
    end

    module Externals = struct
      let rec parenthesised (chars : int list) (at : int) (depth : int) : int =
        match Lang.Lists.list_get_or_none chars at with
        | None -> at
        | Some 40 -> parenthesised chars (at + 1) (depth + 1)
        | Some 41 -> if depth = 1 then at + 1 else parenthesised chars (at + 1) (depth - 1)
        | Some _ -> parenthesised chars (at + 1) depth

      let rec quoted (chars : int list) (at : int) : int =
        match Lang.Lists.list_get_or_none chars at with
        | None -> at
        | Some 92 -> quoted chars (at + 2)
        | Some 34 -> at + 1
        | Some _ -> quoted chars (at + 1)

      let rec atoms_from (chars : int list) (done_ : string list) : string list =
        match chars with
        | [] -> done_
        | c :: rest when Lang.Strings.char_is_whitespace c -> atoms_from rest done_
        | 40 :: _ -> let n = parenthesised chars 0 0 in
            let fk_arg1 = List.drop n chars in
            let fk_arg2 = done_ @ [String.concat "" (List.map Fun.id (List.map (fun it -> fk_show_char it) (List.take n chars)))] in
            atoms_from fk_arg1 fk_arg2
        | 34 :: rest -> let n = quoted rest 0 + 1 in
            let fk_arg1 = List.drop n chars in
            let fk_arg2 = done_ @ [String.concat "" (List.map Fun.id (List.map (fun it -> fk_show_char it) (List.take n chars)))] in
            atoms_from fk_arg1 fk_arg2
        | _ -> let word = Lang.Lists.list_take_while chars (fun it -> not (Lang.Strings.char_is_whitespace it) && it <> 40) in
            let fk_arg1 = List.drop (List.length word) chars in
            let fk_arg2 = done_ @ [String.concat "" (List.map Fun.id (List.map (fun it -> fk_show_char it) word))] in
            atoms_from fk_arg1 fk_arg2

      let atoms (text : string) : string list =
        atoms_from ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) text) []

      let text_of (function_ : Checker.Symbols.symbol) : string =
        match ((function_ : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = Some text; operator = _ } -> text
        | _ -> ""

      let argument_for (parameters : string list) (name : string) (arguments : Ocaml.expr list) : Ocaml.expr =
        Option.value (Lang.Lists.list_get_or_none arguments (Lang.Lists.list_index_of parameters name)) ~default:(Ocaml.Identifier { path = name } : Ocaml.expr)

      let applied (function_ : Checker.Symbols.symbol) (arguments : Ocaml.expr list) : Ocaml.expr =
        let parameters = List.map (fun it -> (it : Parser.parameter).Parser.name) (Option.value (Checker.Symbols.Signatures.parameters_of function_) ~default:[]) in
        let pieces = List.concat_map (fun atom -> let label = Lang.Strings.string_remove_prefix atom "~" in
             if List.mem atom parameters then [argument_for parameters atom arguments] else if String.starts_with ~prefix:"~" atom && List.mem label parameters then [(Ocaml.Labelled { label = label; value = argument_for parameters label arguments } : Ocaml.expr)] else [(Ocaml.Identifier { path = atom } : Ocaml.expr)]) (atoms (text_of function_)) in
        match pieces with
        | [] -> (Ocaml.Identifier { path = "()" } : Ocaml.expr)
        | [one] -> one
        | head :: rest -> (Ocaml.Application { function_ = head; arguments = rest } : Ocaml.expr)

      let as_value (function_ : Checker.Symbols.symbol) : Ocaml.expr =
        match Checker.Symbols.Signatures.parameters_of function_ with
        | None -> applied function_ []
        | Some parameters -> let pieces = atoms (text_of function_) in
            if let fk_arg1 = List.drop 1 pieces in
            let fk_arg2 = List.map (fun it -> (it : Parser.parameter).Parser.name) parameters in
            fk_arg1 = fk_arg2 then (Ocaml.Identifier { path = Option.value (List.nth_opt pieces 0) ~default:"()" } : Ocaml.expr) else (let names = List.mapi (fun i _ -> "x" ^ string_of_int i) parameters in
               let fk_arg1 = if List.is_empty names then [(Ocaml.ConstantPat { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.pat)] else List.map (fun it -> (Ocaml.VariablePat { name = it } : Ocaml.pat)) names in
               let fk_arg2 = applied function_ (List.map (fun it -> (Ocaml.Identifier { path = it } : Ocaml.expr)) names) in
               (Ocaml.Fun { parameters = fk_arg1; body = fk_arg2 } : Ocaml.expr))
    end

    module HandledEffects = struct
      let operation_constructor (effect_ : Checker.Symbols.symbol) (operation : string) : string =
        Naming.reference effect_ (fun it -> it ^ "_" ^ operation)

      let fails_at_call (effect_ : Checker.Symbols.symbol) (operation : string) : bool =
        Option.value (Option.map (fun it -> (it : Checker.Core.declared_operation).Checker.Core.fails_at_call) (Option.bind (Effect.perform (Lowering_effectOf (effect_ : Checker.Symbols.symbol).Checker.Symbols.name)) (fun d -> List.find_opt (fun it -> (it : Checker.Core.declared_operation).Checker.Core.name = operation) (d : Checker.Core.declared_effect).Checker.Core.operations))) ~default:false

      let fail_effect =
        "fckt.effects.Fail"

      let failing (reason : Ocaml.expr) : Ocaml.expr =
        match Effect.perform (Lowering_effectOf fail_effect) with
        | Some fail -> (Ocaml.Match { subject = (Ocaml.Application { function_ = (Ocaml.Identifier { path = "Effect.perform" } : Ocaml.expr); arguments = [(Ocaml.Construction { name = operation_constructor (fail : Checker.Core.declared_effect).Checker.Core.effect_ "fail"; argument = Some reason } : Ocaml.expr)] } : Ocaml.expr); cases = [({ Ocaml.pattern = (Ocaml.AnyPat : Ocaml.pat); guard = None; body = (Ocaml.Verbatim { code = "assert false" } : Ocaml.expr) } : Ocaml.case)] } : Ocaml.expr)
        | None -> (Ocaml.Application { function_ = (Ocaml.Identifier { path = "failwith" } : Ocaml.expr); arguments = [reason] } : Ocaml.expr)

      let performed (effect_ : Checker.Symbols.symbol) (operation : string) (carried : Ocaml.expr) : Ocaml.expr =
        let performing = (Ocaml.Application { function_ = (Ocaml.Identifier { path = "Effect.perform" } : Ocaml.expr); arguments = [(Ocaml.Construction { name = operation_constructor effect_ operation; argument = Some carried } : Ocaml.expr)] } : Ocaml.expr) in
        if not (fails_at_call effect_ operation) then performing else (Ocaml.Match { subject = performing; cases = [({ Ocaml.pattern = (Ocaml.ConstructorPat { name = "Ok"; argument = Some (Ocaml.VariablePat { name = "v" } : Ocaml.pat) } : Ocaml.pat); guard = None; body = (Ocaml.Identifier { path = "v" } : Ocaml.expr) } : Ocaml.case); ({ Ocaml.pattern = (Ocaml.ConstructorPat { name = "Error"; argument = Some (Ocaml.VariablePat { name = "reason" } : Ocaml.pat) } : Ocaml.pat); guard = None; body = failing (Ocaml.Identifier { path = "reason" } : Ocaml.expr) } : Ocaml.case)] } : Ocaml.expr)

      let operations_of (effect_ : Checker.Symbols.symbol) : Parser.spec_value list =
        match ((effect_ : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.SpecDefinition { types = _; values = values; type_parameters = _; copy_of = _; parents = _ } -> values
        | _ -> []

      let caught (answer : Ocaml.expr) : Ocaml.expr =
        match Effect.perform (Lowering_effectOf fail_effect) with
        | Some fail -> (Ocaml.Match { subject = answer; cases = [({ Ocaml.pattern = (Ocaml.VariablePat { name = "v" } : Ocaml.pat); guard = None; body = (Ocaml.Construction { name = "Ok"; argument = Some (Ocaml.Identifier { path = "v" } : Ocaml.expr) } : Ocaml.expr) } : Ocaml.case); ({ Ocaml.pattern = (Ocaml.EffectPat { operation = (Ocaml.ConstructorPat { name = operation_constructor (fail : Checker.Core.declared_effect).Checker.Core.effect_ "fail"; argument = Some (Ocaml.VariablePat { name = "reason" } : Ocaml.pat) } : Ocaml.pat); continuation = "_" } : Ocaml.pat); guard = None; body = (Ocaml.Construction { name = "Error"; argument = Some (Ocaml.Identifier { path = "reason" } : Ocaml.expr) } : Ocaml.expr) } : Ocaml.case)] } : Ocaml.expr)
        | None -> (Ocaml.Construction { name = "Ok"; argument = Some answer } : Ocaml.expr)

      let next_to (effect_ : Checker.Symbols.symbol) (local : string) : string =
        String.concat "." (List.map Fun.id (List.map (fun it -> Naming.module_name it) (Naming.relative (effect_ : Checker.Symbols.symbol).Checker.Symbols.path) @ [local]))

      let simple_snake (effect_ : Checker.Symbols.symbol) : string =
        Lang.Strings.string_remove_suffix (Naming.snake (Naming.own_name effect_)) "_"

      let type_parameters_of (effect_ : Checker.Symbols.symbol) : string list =
        match ((effect_ : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.SpecDefinition { types = _; values = _; type_parameters = type_parameters; copy_of = _; parents = _ } -> List.filter (fun it -> not (String.starts_with ~prefix:"@" it)) type_parameters
        | _ -> []

      let answers (effect_ : Checker.Symbols.symbol) (given : (string * Ocaml.expr * bool) list) : Ocaml.expr =
        let operations = operations_of effect_ in
        let record = (Ocaml.RecordExpr { fields = List.map (fun (name, a, resumes) -> let op = List.find_opt (fun it -> (it : Parser.spec_value).Parser.name = name) operations in
             let fails = fails_at_call effect_ name in
             let fk_arg1 = Naming.snake name in
             let fk_arg2 = match Option.bind op (fun it -> (it : Parser.spec_value).Parser.parameters) with
               | Some parameters -> let names = List.mapi (fun i _ -> "x" ^ string_of_int i) parameters in
                   let arguments = if List.is_empty names then [(Ocaml.ConstantExpr { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.expr)] else List.map (fun it -> (Ocaml.Identifier { path = it } : Ocaml.expr)) names in
                   let taking = List.map (fun it -> (Ocaml.VariablePat { name = it } : Ocaml.pat)) names @ [(Ocaml.VariablePat { name = "k" } : Ocaml.pat)] in
                   if resumes && not fails then a else if resumes then (Ocaml.Fun { parameters = taking; body = (Ocaml.Application { function_ = a; arguments = arguments @ [(Ocaml.Fun { parameters = [(Ocaml.VariablePat { name = "v" } : Ocaml.pat)]; body = (Ocaml.Application { function_ = (Ocaml.Identifier { path = "k" } : Ocaml.expr); arguments = [(Ocaml.Construction { name = "Ok"; argument = Some (Ocaml.Identifier { path = "v" } : Ocaml.expr) } : Ocaml.expr)] } : Ocaml.expr) } : Ocaml.expr)] } : Ocaml.expr) } : Ocaml.expr) else if not fails then (Ocaml.Fun { parameters = taking; body = (Ocaml.Application { function_ = (Ocaml.Identifier { path = "k" } : Ocaml.expr); arguments = [(Ocaml.Application { function_ = a; arguments = arguments } : Ocaml.expr)] } : Ocaml.expr) } : Ocaml.expr) else (Ocaml.Fun { parameters = taking; body = (Ocaml.Application { function_ = (Ocaml.Identifier { path = "k" } : Ocaml.expr); arguments = [caught (Ocaml.Application { function_ = a; arguments = arguments } : Ocaml.expr)] } : Ocaml.expr) } : Ocaml.expr)
               | None -> a in
             ({ Ocaml.name = fk_arg1; value = fk_arg2 } : Ocaml.field_value)) given; base = None } : Ocaml.expr) in
        (Ocaml.Annotated { expression = record; typexpr = (let fk_arg1 = next_to effect_ (simple_snake effect_ ^ "_handler") in
         let fk_arg2 = List.map (fun it -> (Ocaml.TypeVar { name = "_" } : Ocaml.typexpr)) (type_parameters_of effect_ @ ["answer"]) in
         (Ocaml.TypeApplication { name = fk_arg1; arguments = fk_arg2 } : Ocaml.typexpr)) } : Ocaml.expr)

      let made_handler (effect_ : Checker.Symbols.symbol) (given : (string * Ocaml.expr * bool) list) : Ocaml.expr =
        answers effect_ given

      let module_path (m : Checker.Symbols.symbol) : string =
        String.concat "." (List.map Fun.id (List.map (fun it -> Naming.module_name it) (Naming.relative ((m : Checker.Symbols.symbol).Checker.Symbols.path @ [Naming.own_name m]))))

      let module_handler (module_ : Checker.Symbols.symbol) (effect_ : Checker.Symbols.symbol) : Ocaml.expr =
        answers effect_ (List.map (fun op -> ((op : Parser.spec_value).Parser.name, (Ocaml.Identifier { path = (let fk_arg1 = module_path module_ ^ "." in
             let fk_arg2 = Naming.snake (op : Parser.spec_value).Parser.name in
             fk_arg1 ^ fk_arg2) } : Ocaml.expr), false)) (operations_of effect_))

      let handled (effect_ : Checker.Symbols.symbol) (handler : Ocaml.expr) (block : Ocaml.expr) : Ocaml.expr =
        (Ocaml.Application { function_ = (Ocaml.Identifier { path = next_to effect_ ("handle_" ^ simple_snake effect_) } : Ocaml.expr); arguments = [handler; (Ocaml.Fun { parameters = [(Ocaml.ConstantPat { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.pat)]; body = block } : Ocaml.expr)] } : Ocaml.expr)

      let answer =
        "'fk_answer"

      let performed_type (op : Checker.Core.declared_operation) : Ocaml.typexpr =
        if (op : Checker.Core.declared_operation).Checker.Core.fails_at_call then (Ocaml.TypeApplication { name = "result"; arguments = [OcamlTypes.typexpr (op : Checker.Core.declared_operation).Checker.Core.result; (Ocaml.TypeApplication { name = "string"; arguments = [] } : Ocaml.typexpr)] } : Ocaml.typexpr) else OcamlTypes.typexpr (op : Checker.Core.declared_operation).Checker.Core.result

      let declarations (d : Checker.Core.declared_effect) : Ocaml.item list =
        let own = simple_snake (d : Checker.Core.declared_effect).Checker.Core.effect_ in
        let generic = Lang.Lists.list_is_not_empty (d : Checker.Core.declared_effect).Checker.Core.type_parameters in
        let variables = List.map (fun it -> (Ocaml.TypeVar { name = OcamlTypes.parameter it } : Ocaml.typexpr)) (OcamlTypes.ocaml_parameters (d : Checker.Core.declared_effect).Checker.Core.type_parameters) in
        let answering = (Ocaml.TypeVar { name = answer } : Ocaml.typexpr) in
        let constructors = List.map (fun op -> let fk_arg1 = (Naming.own_name (d : Checker.Core.declared_effect).Checker.Core.effect_ ^ "_") ^ (op : Checker.Core.declared_operation).Checker.Core.name in
             let fk_arg2 = List.map (fun it -> OcamlTypes.typexpr it) (Option.value (op : Checker.Core.declared_operation).Checker.Core.parameters ~default:[]) in
             let fk_arg3 = performed_type op in
             ({ Ocaml.name = fk_arg1; parameters = fk_arg2; result = fk_arg3 } : Ocaml.effect_operation)) (d : Checker.Core.declared_effect).Checker.Core.operations in
        let record = let fk_arg1 = List.map (fun it -> OcamlTypes.parameter it) (OcamlTypes.ocaml_parameters (d : Checker.Core.declared_effect).Checker.Core.type_parameters) @ [answer] in
          let fk_arg2 = (Ocaml.RecordType { fields = List.map (fun op -> let answers = match (op : Checker.Core.declared_operation).Checker.Core.parameters with
                 | None -> OcamlTypes.typexpr (op : Checker.Core.declared_operation).Checker.Core.result
                 | Some ps -> List.fold_left (fun r p -> (Ocaml.Arrow { parameter = p; result = r } : Ocaml.typexpr)) answering (List.rev (let fk_arg1 = List.map (fun it -> OcamlTypes.typexpr it) ps in
                       let fk_arg2 = [(Ocaml.Arrow { parameter = performed_type op; result = answering } : Ocaml.typexpr)] in
                       fk_arg1 @ fk_arg2)) in
               let own = List.map (fun it -> OcamlTypes.parameter it) (OcamlTypes.ocaml_parameters (op : Checker.Core.declared_operation).Checker.Core.type_parameters) in
               let fk_arg1 = Naming.snake (op : Checker.Core.declared_operation).Checker.Core.name in
               let fk_arg2 = if List.is_empty own then answers else (Ocaml.Polymorphic { variables = own; body = answers } : Ocaml.typexpr) in
               ({ Ocaml.name = fk_arg1; typexpr = fk_arg2; mutable_ = false } : Ocaml.field_declaration)) (d : Checker.Core.declared_effect).Checker.Core.operations } : Ocaml.type_body) in
          ({ Ocaml.name = own ^ "_handler"; parameters = fk_arg1; body = fk_arg2 } : Ocaml.type_definition) in
        let known = fun e -> if generic then (Ocaml.Application { function_ = (Ocaml.Identifier { path = "Obj.magic" } : Ocaml.expr); arguments = [e] } : Ocaml.expr) else e in
        let cases = List.map (fun op -> let names = List.mapi (fun i _ -> "x" ^ string_of_int i) (Option.value (op : Checker.Core.declared_operation).Checker.Core.parameters ~default:[]) in
             let carried = match names with
               | [] -> (Ocaml.ConstantPat { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.pat)
               | [one] -> (Ocaml.VariablePat { name = one } : Ocaml.pat)
               | _ -> (Ocaml.TuplePat { parts = List.map (fun it -> (Ocaml.VariablePat { name = it } : Ocaml.pat)) names } : Ocaml.pat) in
             let field = (Ocaml.FieldAccess { record = (Ocaml.Identifier { path = "h" } : Ocaml.expr); field = Naming.snake (op : Checker.Core.declared_operation).Checker.Core.name } : Ocaml.expr) in
             let answered = match (op : Checker.Core.declared_operation).Checker.Core.parameters with
               | None -> (Ocaml.Application { function_ = (Ocaml.Identifier { path = "Effect.Deep.continue" } : Ocaml.expr); arguments = [(Ocaml.Identifier { path = "k" } : Ocaml.expr); known field] } : Ocaml.expr)
               | Some _ -> (Ocaml.Application { function_ = field; arguments = (let fk_arg1 = List.map (fun it -> known (Ocaml.Identifier { path = it } : Ocaml.expr)) names in
                    let fk_arg2 = [(Ocaml.Fun { parameters = [(Ocaml.VariablePat { name = "v" } : Ocaml.pat)]; body = (Ocaml.Application { function_ = (Ocaml.Identifier { path = "Effect.Deep.continue" } : Ocaml.expr); arguments = [(Ocaml.Identifier { path = "k" } : Ocaml.expr); known (Ocaml.Identifier { path = "v" } : Ocaml.expr)] } : Ocaml.expr) } : Ocaml.expr)] in
                    fk_arg1 @ fk_arg2) } : Ocaml.expr) in
             ({ Ocaml.pattern = (Ocaml.EffectPat { operation = (Ocaml.ConstructorPat { name = (Naming.own_name (d : Checker.Core.declared_effect).Checker.Core.effect_ ^ "_") ^ (op : Checker.Core.declared_operation).Checker.Core.name; argument = Some carried } : Ocaml.pat); continuation = "k" } : Ocaml.pat); guard = None; body = answered } : Ocaml.case)) (d : Checker.Core.declared_effect).Checker.Core.operations in
        let handler_type = (Ocaml.TypeApplication { name = own ^ "_handler"; arguments = variables @ [answering] } : Ocaml.typexpr) in
        let handle = ({ Ocaml.pattern = (Ocaml.VariablePat { name = "handle_" ^ own } : Ocaml.pat); parameters = [(Ocaml.TypedPat { pattern = (Ocaml.VariablePat { name = "h" } : Ocaml.pat); typexpr = handler_type } : Ocaml.pat); (Ocaml.TypedPat { pattern = (Ocaml.VariablePat { name = "f" } : Ocaml.pat); typexpr = (Ocaml.Arrow { parameter = (Ocaml.TypeApplication { name = "unit"; arguments = [] } : Ocaml.typexpr); result = answering } : Ocaml.typexpr) } : Ocaml.pat)]; result = Some answering; body = (Ocaml.Match { subject = (Ocaml.Application { function_ = (Ocaml.Identifier { path = "f" } : Ocaml.expr); arguments = [(Ocaml.ConstantExpr { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.expr)] } : Ocaml.expr); cases = [({ Ocaml.pattern = (Ocaml.VariablePat { name = "v" } : Ocaml.pat); guard = None; body = (Ocaml.Identifier { path = "v" } : Ocaml.expr) } : Ocaml.case)] @ cases } : Ocaml.expr) } : Ocaml.binding) in
        [(Ocaml.EffectItem { operations = constructors } : Ocaml.item); (Ocaml.TypeItem { definitions = [record] } : Ocaml.item); (Ocaml.LetItem { recursive = false; bindings = [handle] } : Ocaml.item)]

      let running_main (main : Checker.Symbols.symbol) (takes_arguments : bool) (defaults : Checker.Inference.default_handler list) : Ocaml.expr =
        let arguments = if takes_arguments then (Ocaml.Application { function_ = (Ocaml.Identifier { path = "List.tl" } : Ocaml.expr); arguments = [(Ocaml.Application { function_ = (Ocaml.Identifier { path = "Array.to_list" } : Ocaml.expr); arguments = [(Ocaml.Identifier { path = "Sys.argv" } : Ocaml.expr)] } : Ocaml.expr)] } : Ocaml.expr) else (Ocaml.ConstantExpr { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.expr) in
        List.fold_left (fun inner d -> handled (d : Checker.Inference.default_handler).Checker.Inference.effect_ (module_handler (d : Checker.Inference.default_handler).Checker.Inference.handler (d : Checker.Inference.default_handler).Checker.Inference.effect_) inner) (Ocaml.Application { function_ = (Ocaml.Identifier { path = Naming.value_reference main } : Ocaml.expr); arguments = [arguments] } : Ocaml.expr) defaults
    end

    module Shows = struct
      let rec joined (parts : Ocaml.expr list) : Ocaml.expr =
        match parts with
        | [] -> (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = "" } : Ocaml.constant) } : Ocaml.expr)
        | [one] -> one
        | first :: rest -> (Ocaml.Infix { operator = "^"; left = first; right = joined rest } : Ocaml.expr)

      let rec between (items : Ocaml.expr list) (separator : Ocaml.expr) : Ocaml.expr list =
        match items with
        | [] -> []
        | [one] -> [one]
        | first :: rest -> first :: separator :: between rest separator

      let show_name (full : string) : string =
        "show_" ^ Lang.Strings.string_remove_suffix (OcamlTypes.own_name full) "_"

      let show_reference (full : string) : string =
        let parts = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) full "." in
        String.concat "." (List.map Fun.id (let fk_arg1 = List.map (fun it -> Naming.module_name it) (Naming.relative (Lang.Lists.list_drop_last parts 1)) in
          let fk_arg2 = [show_name full] in
          fk_arg1 @ fk_arg2))

      let rec show (t : Checker.Types.type_) : Ocaml.expr =
        match t with
        | Checker.Types.Named { name = "Int"; arguments = []; region = _ } -> (Ocaml.Identifier { path = "string_of_int" } : Ocaml.expr)
        | Checker.Types.Named { name = "Boolean"; arguments = []; region = _ } -> (Ocaml.Identifier { path = "string_of_bool" } : Ocaml.expr)
        | Checker.Types.Named { name = "Char"; arguments = []; region = _ } -> (Ocaml.Identifier { path = "fk_show_char" } : Ocaml.expr)
        | Checker.Types.Named { name = "Float"; arguments = []; region = _ } -> (Ocaml.Identifier { path = "fk_show_float" } : Ocaml.expr)
        | Checker.Types.Named { name = "String"; arguments = []; region = _ } -> (Ocaml.Identifier { path = "Fun.id" } : Ocaml.expr)
        | Checker.Types.Named { name = "Unit"; arguments = []; region = _ } -> (Ocaml.Fun { parameters = [(Ocaml.ConstantPat { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.pat)]; body = (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = "()" } : Ocaml.constant) } : Ocaml.expr) } : Ocaml.expr)
        | Checker.Types.Named { name = "Byte"; arguments = []; region = _ } -> (Ocaml.Fun { parameters = [(Ocaml.VariablePat { name = "b" } : Ocaml.pat)]; body = (Ocaml.Application { function_ = (Ocaml.Identifier { path = "string_of_int" } : Ocaml.expr); arguments = [(Ocaml.Application { function_ = (Ocaml.Identifier { path = "Char.code" } : Ocaml.expr); arguments = [(Ocaml.Identifier { path = "b" } : Ocaml.expr)] } : Ocaml.expr)] } : Ocaml.expr) } : Ocaml.expr)
        | Checker.Types.Named { name = "Nothing"; arguments = []; region = _ } -> (Ocaml.Fun { parameters = [(Ocaml.AnyPat : Ocaml.pat)]; body = (Ocaml.Verbatim { code = "assert false" } : Ocaml.expr) } : Ocaml.expr)
        | Checker.Types.Named { name = "Lazy"; arguments = _; region = _ } -> (Ocaml.Fun { parameters = [(Ocaml.AnyPat : Ocaml.pat)]; body = (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = "Lazy(...)" } : Ocaml.constant) } : Ocaml.expr) } : Ocaml.expr)
        | Checker.Types.Named { name = "List"; arguments = [element]; region = _ } -> (Ocaml.Application { function_ = (Ocaml.Identifier { path = "fk_show_list" } : Ocaml.expr); arguments = [show element] } : Ocaml.expr)
        | Checker.Types.Named { name = "Option"; arguments = [element]; region = _ } -> (Ocaml.Application { function_ = (Ocaml.Identifier { path = "fk_show_option" } : Ocaml.expr); arguments = [show element] } : Ocaml.expr)
        | Checker.Types.Named { name = "Result"; arguments = [value; error]; region = _ } -> (Ocaml.Application { function_ = (Ocaml.Identifier { path = "fk_show_result" } : Ocaml.expr); arguments = (let fk_arg1 = show value in
             let fk_arg2 = show error in
             [fk_arg1; fk_arg2]) } : Ocaml.expr)
        | Checker.Types.TupleOf { elements = elements } -> let names = List.mapi (fun i _ -> "x" ^ string_of_int i) elements in
            let shown = List.mapi (fun i e -> (Ocaml.Application { function_ = show e; arguments = [(Ocaml.Identifier { path = "x" ^ string_of_int i } : Ocaml.expr)] } : Ocaml.expr)) elements in
            let parts = (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = "(" } : Ocaml.constant) } : Ocaml.expr) :: (between shown (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = ", " } : Ocaml.constant) } : Ocaml.expr) @ (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = ")" } : Ocaml.constant) } : Ocaml.expr) :: []) in
            let fk_arg1 = [(Ocaml.TuplePat { parts = List.map (fun it -> (Ocaml.VariablePat { name = it } : Ocaml.pat)) names } : Ocaml.pat)] in
            let fk_arg2 = joined parts in
            (Ocaml.Fun { parameters = fk_arg1; body = fk_arg2 } : Ocaml.expr)
        | Checker.Types.FunctionOf { parameters = _; result = _; effects = _ } -> (Ocaml.Fun { parameters = [(Ocaml.AnyPat : Ocaml.pat)]; body = (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = "<fun>" } : Ocaml.constant) } : Ocaml.expr) } : Ocaml.expr)
        | Checker.Types.TypeParameter { name = name } -> (Ocaml.Identifier { path = "show_" ^ String.lowercase_ascii name } : Ocaml.expr)
        | Checker.Types.Abstract { name = name; arguments = arguments } -> show (Checker.Types.Named { name = name; arguments = arguments; region = None } : Checker.Types.type_)
        | Checker.Types.Named { name = name; arguments = _; region = _ } when Option.value (Option.map (fun it -> match it with
                | Checker.Core.DeclaredExternal it_as_declared_external -> true
                | _ -> false) (Effect.perform (Lowering_declarationOf name))) ~default:false -> (Ocaml.Fun { parameters = [(Ocaml.AnyPat : Ocaml.pat)]; body = (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = ("<" ^ Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".")) ~default:name) ^ ">" } : Ocaml.constant) } : Ocaml.expr) } : Ocaml.expr)
        | Checker.Types.Named { name = name; arguments = arguments; region = _ } -> (let shown = List.map (fun it -> show it) (OcamlTypes.ocaml_arguments name arguments) in
             match Effect.perform (Lowering_toStringOf name) with
             | Some f -> (Ocaml.Fun { parameters = [(Ocaml.VariablePat { name = "v" } : Ocaml.pat)]; body = (Ocaml.Application { function_ = (Ocaml.Identifier { path = Naming.value_reference f } : Ocaml.expr); arguments = (Ocaml.Identifier { path = "v" } : Ocaml.expr) :: shown } : Ocaml.expr) } : Ocaml.expr)
             | None -> if List.is_empty shown then (Ocaml.Identifier { path = show_reference name } : Ocaml.expr) else (Ocaml.Application { function_ = (Ocaml.Identifier { path = show_reference name } : Ocaml.expr); arguments = shown } : Ocaml.expr))
        | other -> match Effect.perform (Effects.Fail_fail ("showing a value of type " ^ Checker.Types.show_type other)) with
            | _ -> (assert false)
    end

    module Expressions = struct
      let constant (literal : Checker.Core.literal) : Ocaml.constant =
        match literal with
        | Checker.Core.IntLiteral { value = n } -> (Ocaml.IntConstant { value = n } : Ocaml.constant)
        | Checker.Core.FloatLiteral { value = x } -> (Ocaml.FloatConstant { value = x } : Ocaml.constant)
        | Checker.Core.BooleanLiteral { value = b } -> (Ocaml.BooleanConstant { value = b } : Ocaml.constant)
        | Checker.Core.CharLiteral { code = code } -> (Ocaml.IntConstant { value = code } : Ocaml.constant)
        | Checker.Core.StringLiteral { value = s } -> (Ocaml.StringConstant { value = s } : Ocaml.constant)
        | Checker.Core.UnitLiteral -> (Ocaml.UnitConstant : Ocaml.constant)

      let primitive_applied (primitive : Checker.Core.primitive) (operands : Ocaml.expr list) : Ocaml.expr =
        match (primitive, operands) with
        | (Checker.Core.IntPlus, [a; b]) -> (Ocaml.Infix { operator = "+"; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.IntMinus, [a; b]) -> (Ocaml.Infix { operator = "-"; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.IntTimes, [a; b]) -> (Ocaml.Infix { operator = "*"; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.IntDivide, [a; b]) -> (Ocaml.Infix { operator = "/"; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.IntRemainder, [a; b]) -> (Ocaml.Infix { operator = "mod"; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.FloatPlus, [a; b]) -> (Ocaml.Infix { operator = "+."; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.FloatMinus, [a; b]) -> (Ocaml.Infix { operator = "-."; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.FloatTimes, [a; b]) -> (Ocaml.Infix { operator = "*."; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.FloatDivide, [a; b]) -> (Ocaml.Infix { operator = "/."; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.FloatRemainder, [a; b]) -> (Ocaml.Application { function_ = (Ocaml.Identifier { path = "Float.rem" } : Ocaml.expr); arguments = [a; b] } : Ocaml.expr)
        | (Checker.Core.IntNegate, [Ocaml.ConstantExpr { constant = Ocaml.IntConstant { value = n } }]) -> (Ocaml.ConstantExpr { constant = (Ocaml.IntConstant { value = Int.neg n } : Ocaml.constant) } : Ocaml.expr)
        | (Checker.Core.IntNegate, [a]) -> (Ocaml.Application { function_ = (Ocaml.Identifier { path = "Int.neg" } : Ocaml.expr); arguments = [a] } : Ocaml.expr)
        | (Checker.Core.FloatNegate, [Ocaml.ConstantExpr { constant = Ocaml.FloatConstant { value = x } }]) -> (Ocaml.ConstantExpr { constant = (Ocaml.FloatConstant { value = Float.neg x } : Ocaml.constant) } : Ocaml.expr)
        | (Checker.Core.FloatNegate, [a]) -> (Ocaml.Application { function_ = (Ocaml.Identifier { path = "Float.neg" } : Ocaml.expr); arguments = [a] } : Ocaml.expr)
        | (Checker.Core.Promoted, [a]) -> (Ocaml.Application { function_ = (Ocaml.Identifier { path = "float_of_int" } : Ocaml.expr); arguments = [a] } : Ocaml.expr)
        | (Checker.Core.Concatenated, parts) -> Shows.joined parts
        | (Checker.Core.Appended, [a; b]) -> (Ocaml.Infix { operator = "@"; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.Equal, [a; b]) -> (Ocaml.Infix { operator = "="; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.NotEqual, [a; b]) -> (Ocaml.Infix { operator = "<>"; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.Less, [a; b]) -> (Ocaml.Infix { operator = "<"; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.LessOrEqual, [a; b]) -> (Ocaml.Infix { operator = "<="; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.Greater, [a; b]) -> (Ocaml.Infix { operator = ">"; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.GreaterOrEqual, [a; b]) -> (Ocaml.Infix { operator = ">="; left = a; right = b } : Ocaml.expr)
        | (Checker.Core.Not, [a]) -> (Ocaml.Application { function_ = (Ocaml.Identifier { path = "not" } : Ocaml.expr); arguments = [a] } : Ocaml.expr)
        | _ -> match Effect.perform (Effects.Fail_fail "an operation given the wrong number of operands") with
            | _ -> (assert false)

      let rec pat (m : Checker.Core.matcher) : Ocaml.pat =
        match m with
        | Checker.Core.AnyMatcher -> (Ocaml.AnyPat : Ocaml.pat)
        | Checker.Core.NameMatcher { name = name } -> (Ocaml.VariablePat { name = Naming.snake name } : Ocaml.pat)
        | Checker.Core.TupleMatcher { parts = parts } -> (Ocaml.TuplePat { parts = List.map (fun it -> pat it) parts } : Ocaml.pat)
        | Checker.Core.ConstantMatcher { literal = literal } -> (Ocaml.ConstantPat { constant = constant literal } : Ocaml.pat)
        | Checker.Core.CaseMatcher { constructor = constructor; fields = fields; narrowed = narrowed } -> Constructors.pattern constructor (Option.map (fun fs -> List.map (fun it -> pat it) fs) fields) narrowed
        | Checker.Core.CaseTypeMatcher { case_type = case_type; narrowed = narrowed } -> if not (Effect.perform (Lowering_isShared (case_type : Checker.Symbols.symbol).Checker.Symbols.name)) then (Ocaml.AnyPat : Ocaml.pat) else (let fk_arg1 = Option.map (fun local -> let fk_arg1 = (Ocaml.TypePat { type_name = OcamlTypes.type_reference (case_type : Checker.Symbols.symbol).Checker.Symbols.name } : Ocaml.pat) in
                    let fk_arg2 = Naming.snake local in
                    (Ocaml.AliasPat { pattern = fk_arg1; name = fk_arg2 } : Ocaml.pat)) narrowed in
               let fk_arg2 = (Ocaml.TypePat { type_name = OcamlTypes.type_reference (case_type : Checker.Symbols.symbol).Checker.Symbols.name } : Ocaml.pat) in
               Option.value fk_arg1 ~default:fk_arg2)
        | Checker.Core.ListMatcher { items = items; rest = None } -> (Ocaml.ListPat { items = List.map (fun it -> pat it) items } : Ocaml.pat)
        | Checker.Core.ListMatcher { items = items; rest = Some rest } -> let fk_arg1 = List.rev items in
            let fk_arg2 = pat rest in
            List.fold_left (fun tail item -> (Ocaml.ConsPat { head = pat item; tail = tail } : Ocaml.pat)) fk_arg2 fk_arg1

      let parameters_of (parameters : Checker.Core.matcher list) : Ocaml.pat list =
        if List.is_empty parameters then [(Ocaml.ConstantPat { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.pat)] else List.map (fun it -> pat it) parameters

      let rec expression (c : Checker.Core.core) : Ocaml.expr =
        match c with
        | Checker.Core.Value { literal = literal } -> (Ocaml.ConstantExpr { constant = constant literal } : Ocaml.expr)
        | Checker.Core.LocalRead { name = name; is_var = is_var } -> if is_var then (Ocaml.Application { function_ = (Ocaml.Identifier { path = "!" } : Ocaml.expr); arguments = [(Ocaml.Identifier { path = Naming.snake name } : Ocaml.expr)] } : Ocaml.expr) else (Ocaml.Identifier { path = Naming.snake name } : Ocaml.expr)
        | Checker.Core.GlobalRead { function_ = function_ } -> (Ocaml.Identifier { path = Naming.value_reference function_ } : Ocaml.expr)
        | Checker.Core.ExternalRead { function_ = function_ } -> Externals.as_value function_
        | Checker.Core.Applied { function_ = function_; arguments = arguments } -> in_order arguments (fun given -> let fk_arg1 = expression function_ in
               let fk_arg2 = if List.is_empty given then [(Ocaml.ConstantExpr { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.expr)] else given in
               (Ocaml.Application { function_ = fk_arg1; arguments = fk_arg2 } : Ocaml.expr))
        | Checker.Core.ExternalApplied { function_ = function_; arguments = arguments } -> in_order arguments (fun given -> Externals.applied function_ given)
        | Checker.Core.Performed { effect_ = effect_; operation = operation; arguments = arguments } -> in_order arguments (fun given -> let carried = match given with
                 | [] -> (Ocaml.ConstantExpr { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.expr)
                 | [one] -> one
                 | _ -> (Ocaml.TupleExpr { parts = given } : Ocaml.expr) in
               HandledEffects.performed effect_ operation carried)
        | Checker.Core.Operated { primitive = Checker.Core.And; operands = [left; right] } -> let fk_arg1 = expression left in
            let fk_arg2 = expression right in
            (Ocaml.Infix { operator = "&&"; left = fk_arg1; right = fk_arg2 } : Ocaml.expr)
        | Checker.Core.Operated { primitive = Checker.Core.Or; operands = [left; right] } -> let fk_arg1 = expression left in
            let fk_arg2 = expression right in
            (Ocaml.Infix { operator = "||"; left = fk_arg1; right = fk_arg2 } : Ocaml.expr)
        | Checker.Core.Operated { primitive = primitive; operands = operands } -> in_order operands (fun given -> primitive_applied primitive given)
        | Checker.Core.Shown { value = value; t = t } -> let fk_arg1 = Shows.show t in
            let fk_arg2 = [expression value] in
            (Ocaml.Application { function_ = fk_arg1; arguments = fk_arg2 } : Ocaml.expr)
        | Checker.Core.ListMade { items = items } -> list_made items
        | Checker.Core.TupleMade { parts = parts } -> in_order parts (fun given -> (Ocaml.TupleExpr { parts = given } : Ocaml.expr))
        | Checker.Core.Joined { list = list; separator = separator; element = element } -> in_order [separator; list] (fun given -> match given with
               | [s; l] -> (Ocaml.Application { function_ = (Ocaml.Identifier { path = "String.concat" } : Ocaml.expr); arguments = [s; (Ocaml.Application { function_ = (Ocaml.Identifier { path = "List.map" } : Ocaml.expr); arguments = [Shows.show element; l] } : Ocaml.expr)] } : Ocaml.expr)
               | _ -> match Effect.perform (Effects.Fail_fail "joining") with
                   | _ -> (assert false))
        | Checker.Core.Assertion { condition = condition; summary = summary; facts = facts } -> let fk_arg1 = expression condition in
            let fk_arg2 = (Ocaml.Application { function_ = (Ocaml.Identifier { path = "fk_assertion_failed" } : Ocaml.expr); arguments = [(Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = summary } : Ocaml.constant) } : Ocaml.expr); (Ocaml.ListExpr { items = List.map (fun (key, fact) -> (Ocaml.TupleExpr { parts = [(Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = key } : Ocaml.constant) } : Ocaml.expr); expression fact] } : Ocaml.expr)) facts } : Ocaml.expr)] } : Ocaml.expr) in
            (Ocaml.IfThenElse { condition = fk_arg1; then_ = (Ocaml.ConstantExpr { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.expr); otherwise = fk_arg2 } : Ocaml.expr)
        | Checker.Core.EqualityAssertion { expected = expected; actual = actual; t = t; where = where; source = source } -> in_order [expected; actual] (fun given -> (Ocaml.Application { function_ = (Ocaml.Identifier { path = "fk_assert_equals" } : Ocaml.expr); arguments = Shows.show t :: (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = where } : Ocaml.constant) } : Ocaml.expr) :: (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = source } : Ocaml.constant) } : Ocaml.expr) :: given } : Ocaml.expr))
        | Checker.Core.Conditional { condition = condition; then_ = then_; otherwise = otherwise } -> let fk_arg1 = expression condition in
            let fk_arg2 = expression then_ in
            let fk_arg3 = expression otherwise in
            (Ocaml.IfThenElse { condition = fk_arg1; then_ = fk_arg2; otherwise = fk_arg3 } : Ocaml.expr)
        | Checker.Core.Bound { pattern = pattern; value = value; body = body } -> let fk_arg1 = [(let fk_arg1 = pat pattern in
               let fk_arg2 = expression value in
               ({ Ocaml.pattern = fk_arg1; parameters = []; result = None; body = fk_arg2 } : Ocaml.binding))] in
            let fk_arg2 = expression body in
            (Ocaml.LetIn { recursive = false; bindings = fk_arg1; body = fk_arg2 } : Ocaml.expr)
        | Checker.Core.VarBound { name = name; value = value; body = body } -> let fk_arg1 = [(let fk_arg1 = (Ocaml.VariablePat { name = Naming.snake name } : Ocaml.pat) in
               let fk_arg2 = (Ocaml.Application { function_ = (Ocaml.Identifier { path = "ref" } : Ocaml.expr); arguments = [expression value] } : Ocaml.expr) in
               ({ Ocaml.pattern = fk_arg1; parameters = []; result = None; body = fk_arg2 } : Ocaml.binding))] in
            let fk_arg2 = expression body in
            (Ocaml.LetIn { recursive = false; bindings = fk_arg1; body = fk_arg2 } : Ocaml.expr)
        | Checker.Core.VarWritten { name = name; value = value } -> let fk_arg1 = (Ocaml.Identifier { path = Naming.snake name } : Ocaml.expr) in
            let fk_arg2 = expression value in
            (Ocaml.Infix { operator = ":="; left = fk_arg1; right = fk_arg2 } : Ocaml.expr)
        | Checker.Core.FunctionBound { name = name; parameters = parameters; body = body; rest = rest } -> let fk_arg1 = [(let fk_arg1 = (Ocaml.VariablePat { name = Naming.snake name } : Ocaml.pat) in
               let fk_arg2 = parameters_of parameters in
               let fk_arg3 = expression body in
               ({ Ocaml.pattern = fk_arg1; parameters = fk_arg2; result = None; body = fk_arg3 } : Ocaml.binding))] in
            let fk_arg2 = expression rest in
            (Ocaml.LetIn { recursive = true; bindings = fk_arg1; body = fk_arg2 } : Ocaml.expr)
        | Checker.Core.Sequenced { first = first; then_ = then_ } -> let fk_arg1 = expression first in
            let fk_arg2 = expression then_ in
            (Ocaml.Sequence { first = fk_arg1; then_ = fk_arg2 } : Ocaml.expr)
        | Checker.Core.FunctionValue { parameters = parameters; body = body; drops_result = drops_result } -> let fk_arg1 = parameters_of parameters in
            let fk_arg2 = if drops_result then (Ocaml.Application { function_ = (Ocaml.Identifier { path = "ignore" } : Ocaml.expr); arguments = [expression body] } : Ocaml.expr) else expression body in
            (Ocaml.Fun { parameters = fk_arg1; body = fk_arg2 } : Ocaml.expr)
        | Checker.Core.Constructed { constructor = Checker.Core.BuiltinCase { name = name }; fields = fields; t = _ } -> in_order fields (fun given -> Constructors.built (Checker.Core.BuiltinCase { name = name } : Checker.Core.constructor) given)
        | Checker.Core.Constructed { constructor = Checker.Core.CaseConstructor { c = c }; fields = fields; t = _ } when Effect.perform (Lowering_isShared ((c : Checker.Symbols.case_symbol).Checker.Symbols.owner : Checker.Symbols.symbol).Checker.Symbols.name) -> in_order fields (fun given -> Constructors.built (Checker.Core.CaseConstructor { c = c } : Checker.Core.constructor) given)
        | Checker.Core.Constructed { constructor = constructor; fields = fields; t = t } -> in_order fields (fun given -> let fk_arg1 = Constructors.built constructor given in
               let fk_arg2 = OcamlTypes.typexpr t in
               (Ocaml.Annotated { expression = fk_arg1; typexpr = fk_arg2 } : Ocaml.expr))
        | Checker.Core.FieldRead { record = record; owner = owner; field = field } -> let fk_arg1 = Constructors.annotated_record (expression record) owner in
            let fk_arg2 = Constructors.label owner field in
            (Ocaml.FieldAccess { record = fk_arg1; field = fk_arg2 } : Ocaml.expr)
        | Checker.Core.Copied { record = record; owner = owner; changes = changes } -> in_order ([record] @ List.map (fun (_, c) -> c) changes) (fun given -> match given with
               | r :: values -> let base = Constructors.annotated_record r owner in
                   (Ocaml.RecordExpr { fields = List.mapi (fun i entry -> let ((name, _), value) = entry in
                      ({ Ocaml.name = (if i = 0 then Constructors.label owner name else Naming.snake name); value = value } : Ocaml.field_value)) (Lang.Lists.list_zip changes values); base = Some base } : Ocaml.expr)
               | _ -> match Effect.perform (Effects.Fail_fail "copying a record") with
                   | _ -> (assert false))
        | Checker.Core.NarrowedRead { local = local; case_name = case_name; case_type = case_type; field = field } -> if Effect.perform (Lowering_isShared case_type) then (Ocaml.Identifier { path = (let fk_arg1 = Constructors.narrowed_name local case_name ^ "_" in
               let fk_arg2 = Naming.snake field in
               fk_arg1 ^ fk_arg2) } : Ocaml.expr) else (let fk_arg1 = (Ocaml.Identifier { path = Constructors.narrowed_name local case_name } : Ocaml.expr) in
               let fk_arg2 = Naming.snake field in
               (Ocaml.FieldAccess { record = fk_arg1; field = fk_arg2 } : Ocaml.expr))
        | Checker.Core.FieldWritten { record = record; owner = owner; field = field; value = value } -> in_order [record; value] (fun given -> match given with
               | [r; v] -> (Ocaml.FieldUpdate { record = r; field = Constructors.label owner field; value = v } : Ocaml.expr)
               | _ -> match Effect.perform (Effects.Fail_fail "changing a field") with
                   | _ -> (assert false))
        | Checker.Core.NarrowedWritten { local = local; case_name = case_name; case_type = _; field = field; value = value } -> let fk_arg1 = (Ocaml.Identifier { path = Constructors.narrowed_name local case_name } : Ocaml.expr) in
            let fk_arg2 = Naming.snake field in
            let fk_arg3 = expression value in
            (Ocaml.FieldUpdate { record = fk_arg1; field = fk_arg2; value = fk_arg3 } : Ocaml.expr)
        | Checker.Core.CaseName { value = value; cases = cases } -> let fk_arg1 = expression value in
            let fk_arg2 = List.map (fun c -> ({ Ocaml.pattern = (Ocaml.ConstructorPat { name = Constructors.case_name c; argument = None } : Ocaml.pat); guard = None; body = (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.name } : Ocaml.constant) } : Ocaml.expr) } : Ocaml.case)) cases in
            (Ocaml.Match { subject = fk_arg1; cases = fk_arg2 } : Ocaml.expr)
        | Checker.Core.Matched { subject = subject; branches = branches } -> let fk_arg1 = expression subject in
            let fk_arg2 = List.map (fun b -> let pattern = match (b : Checker.Core.match_branch).Checker.Core.patterns with
                   | [] -> (Ocaml.AnyPat : Ocaml.pat)
                   | first :: rest -> List.fold_left (fun either p -> (Ocaml.OrPat { left = either; right = pat p } : Ocaml.pat)) (pat first) rest in
                 let fk_arg1 = Option.map (fun it -> expression it) (b : Checker.Core.match_branch).Checker.Core.guard in
                 let fk_arg2 = expression (b : Checker.Core.match_branch).Checker.Core.body in
                 ({ Ocaml.pattern = pattern; guard = fk_arg1; body = fk_arg2 } : Ocaml.case)) branches in
            (Ocaml.Match { subject = fk_arg1; cases = fk_arg2 } : Ocaml.expr)
        | Checker.Core.HandlerMade { effect_ = effect_; answers = answers } -> HandledEffects.made_handler effect_ (List.map (fun a -> ((a : Checker.Core.answer).Checker.Core.operation, expression (a : Checker.Core.answer).Checker.Core.answer, (a : Checker.Core.answer).Checker.Core.resumes)) answers)
        | Checker.Core.ModuleHandler { module_ = module_; effect_ = effect_ } -> HandledEffects.module_handler module_ effect_
        | Checker.Core.Handled { effect_ = effect_; handler = handler; block = block } -> let fk_arg1 = expression handler in
            let fk_arg2 = expression block in
            HandledEffects.handled effect_ fk_arg1 fk_arg2
        | Checker.Core.Widened { value = value; t = t } -> (match t with
             | Checker.Types.Named { name = name; arguments = _; region = _ } when Effect.perform (Lowering_isShared name) -> let fk_arg1 = expression value in
                 let fk_arg2 = OcamlTypes.typexpr t in
                 (Ocaml.Coerced { expression = fk_arg1; typexpr = fk_arg2 } : Ocaml.expr)
             | _ -> expression value)
        | Checker.Core.ModulePacked { module_ = module_; spec = spec } -> (Ocaml.Verbatim { code = (let fk_arg1 = ("module " ^ Naming.module_path module_) ^ " : " in
             let fk_arg2 = OcamlTypes.package_type (spec : Checker.Symbols.symbol).Checker.Symbols.name (List.map (fun t -> (Naming.module_path module_ ^ ".") ^ t) (OcamlTypes.own_types (spec : Checker.Symbols.symbol).Checker.Symbols.name)) in
             fk_arg1 ^ fk_arg2) } : Ocaml.expr)
        | Checker.Core.ModuleMemberRead { value = value; spec = spec; member = member } -> let own_types = OcamlTypes.own_types (spec : Checker.Symbols.symbol).Checker.Symbols.name in
            if List.is_empty own_types then (let fk_arg1 = expression value in
               let fk_arg2 = [(let fk_arg1 = (Ocaml.PackedPat { module_ = "Value"; signature = OcamlTypes.type_module_reference (spec : Checker.Symbols.symbol).Checker.Symbols.name } : Ocaml.pat) in
                  let fk_arg2 = (Ocaml.Identifier { path = "Value." ^ Naming.snake member } : Ocaml.expr) in
                  ({ Ocaml.pattern = fk_arg1; guard = None; body = fk_arg2 } : Ocaml.case))] in
               (Ocaml.Match { subject = fk_arg1; cases = fk_arg2 } : Ocaml.expr)) else (let names = List.mapi (fun i _ -> "fk_t" ^ string_of_int i) own_types in
               let opening = (let fk_arg1 = (let fk_arg1 = ("let open_value " ^ String.concat " " (List.map Fun.id (List.map (fun it -> ("(type " ^ it) ^ ")") names))) ^ " (m : (module " in
                     let fk_arg2 = OcamlTypes.package_type (spec : Checker.Symbols.symbol).Checker.Symbols.name names in
                     fk_arg1 ^ fk_arg2) ^ ")) = let module Value = (val m) in Value." in
                  let fk_arg2 = Naming.snake member in
                  fk_arg1 ^ fk_arg2) ^ " in open_value" in
               (Ocaml.Application { function_ = (Ocaml.Verbatim { code = opening } : Ocaml.expr); arguments = [expression value] } : Ocaml.expr))
        | Checker.Core.Absurd { call = call } -> (Ocaml.Match { subject = expression call; cases = [({ Ocaml.pattern = (Ocaml.AnyPat : Ocaml.pat); guard = None; body = (Ocaml.Verbatim { code = "assert false" } : Ocaml.expr) } : Ocaml.case)] } : Ocaml.expr)
        | Checker.Core.Pending { what = what } -> match Effect.perform (Effects.Fail_fail what) with
            | _ -> (assert false)
      and list_made (items : Checker.Core.list_item list) : Ocaml.expr =
        let parts = List.map (fun item -> match item with
             | Checker.Core.OneItem { value = value } -> value
             | Checker.Core.SpreadItems { list = list } -> list) items in
        in_order parts (fun given -> if List.for_all (fun it -> match it with
              | Checker.Core.OneItem it_as_one_item -> true
              | _ -> false) items then (Ocaml.ListExpr { items = given } : Ocaml.expr) else Option.value (List.fold_left (fun rest entry -> let (item, e) = entry in
                 Some (match item with
                  | Checker.Core.OneItem { value = _ } -> (Ocaml.Infix { operator = "::"; left = e; right = Option.value rest ~default:(Ocaml.ListExpr { items = [] } : Ocaml.expr) } : Ocaml.expr)
                  | Checker.Core.SpreadItems { list = _ } -> match rest with
                      | Some r -> (Ocaml.Infix { operator = "@"; left = e; right = r } : Ocaml.expr)
                      | None -> e)) None (List.rev (Lang.Lists.list_zip items given))) ~default:(Ocaml.ListExpr { items = [] } : Ocaml.expr))
      and in_order (parts : Checker.Core.core list) (build : Ocaml.expr list -> Ocaml.expr) : Ocaml.expr =
        let running = List.filter (fun it -> Checker.Core.Cores.runs it) parts in
        if List.length running < 2 then build (List.map (fun it -> expression it) parts) else (let (names, _) = List.fold_left (fun acc part -> let (found, n) = acc in
                if Checker.Core.Cores.runs part then (found @ [Some ("fk_arg" ^ string_of_int (n + 1))], n + 1) else (found @ [None], n)) ([], 0) parts in
           let given = List.map (fun (part, name) -> let fk_arg1 = Option.map (fun it -> (Ocaml.Identifier { path = it } : Ocaml.expr)) name in
                let fk_arg2 = expression part in
                Option.value fk_arg1 ~default:fk_arg2) (Lang.Lists.list_zip parts names) in
           let fk_arg1 = List.rev (Lang.Lists.list_zip parts names) in
           let fk_arg2 = build given in
           List.fold_left (fun body entry -> let (part, name) = entry in
              match name with
              | Some n -> (Ocaml.LetIn { recursive = false; bindings = [({ Ocaml.pattern = (Ocaml.VariablePat { name = n } : Ocaml.pat); parameters = []; result = None; body = expression part } : Ocaml.binding)]; body = body } : Ocaml.expr)
              | None -> body) fk_arg2 fk_arg1)
    end

    module Helpers = struct
      let items =
        "type fk_nothing = |\n\nlet fk_show_float f =\n  if Float.is_nan f then \"NaN\"\n  else if f = Float.infinity then \"Infinity\"\n  else if f = Float.neg_infinity then \"-Infinity\"\n  else if f = 0.0 then (if 1.0 /. f < 0.0 then \"-0.0\" else \"0.0\")\n  else\n    let rec shortest p = let s = Printf.sprintf \"%.*e\" (p - 1) (Float.abs f) in if p >= 17 || float_of_string s = Float.abs f then s else shortest (p + 1) in\n    let s = shortest 1 in\n    let i = String.index s 'e' in\n    let digits = String.concat \"\" (String.split_on_char '.' (String.sub s 0 i)) in\n    let exponent = String.sub s (i + 1) (String.length s - i - 1) in\n    let e = int_of_string (if exponent.[0] = '+' then String.sub exponent 1 (String.length exponent - 1) else exponent) in\n    let n = String.length digits in\n    let a = Float.abs f in\n    let body =\n      if a >= 1e-3 && a < 1e7 then\n        if e >= 0 then\n          (if n > e + 1 then String.sub digits 0 (e + 1) else digits ^ String.make (e + 1 - n) '0') ^ \".\" ^\n            (if n > e + 1 then String.sub digits (e + 1) (n - e - 1) else \"0\")\n        else \"0.\" ^ String.make (- e - 1) '0' ^ digits\n      else String.sub digits 0 1 ^ \".\" ^ (if n > 1 then String.sub digits 1 (n - 1) else \"0\") ^ \"E\" ^ string_of_int e\n    in\n    (if f < 0.0 then \"-\" else \"\") ^ body\n\nlet fk_show_char c = let b = Buffer.create 4 in Buffer.add_utf_8_uchar b (Uchar.of_int c); Buffer.contents b\n\nlet fk_assertion_facts facts =\n  let escape v = let b = Buffer.create (String.length v) in String.iter (function '\\\\' -> Buffer.add_string b \"\\\\\\\\\" | '\\n' -> Buffer.add_string b \"\\\\n\" | c -> Buffer.add_char b c) v; Buffer.contents b in\n  \"\\nfckt-assertion 1\" ^ String.concat \"\" (List.map (fun (k, v) -> \"\\n\" ^ k ^ \" \" ^ escape v) facts)\n\nlet fk_assertion_failed summary facts = failwith (summary ^ fk_assertion_facts facts)\n\nlet fk_assert_equals show where source expected actual =\n  if expected = actual then () else\n    let e = show expected and a = show actual in\n    let source = if source = \"\" then [] else [(\"source\", source)] in\n    failwith (where ^ \": expected:<\" ^ e ^ \"> but was:<\" ^ a ^ \">\"\n      ^ fk_assertion_facts ([(\"assertion\", \"assertEquals\"); (\"where\", where)] @ source @ [(\"expected\", e); (\"actual\", a)]))\n\nlet fk_show_list show l = \"[\" ^ String.concat \", \" (List.map show l) ^ \"]\"\n\nlet fk_show_option show o = match o with Some x -> \"Some(\" ^ show x ^ \")\" | None -> \"None\"\n\nlet fk_show_result show show_error r = match r with Ok x -> \"Ok(\" ^ show x ^ \")\" | Error e -> \"Error(\" ^ show_error e ^ \")\"\n"
    end

    module TypeItems = struct
      let field (f : Checker.Core.declared_field) : Ocaml.field_declaration =
        let fk_arg1 = Naming.snake (f : Checker.Core.declared_field).Checker.Core.name in
        let fk_arg2 = OcamlTypes.typexpr (f : Checker.Core.declared_field).Checker.Core.t in
        ({ Ocaml.name = fk_arg1; typexpr = fk_arg2; mutable_ = (f : Checker.Core.declared_field).Checker.Core.variable } : Ocaml.field_declaration)

      let definition (d : Checker.Core.type_declaration) : Ocaml.type_definition =
        match d with
        | Checker.Core.DeclaredRecord { record = record; type_parameters = parameters; fields = fields } -> let fk_arg1 = OcamlTypes.own_name (record : Checker.Symbols.symbol).Checker.Symbols.name in
            let fk_arg2 = List.map (fun it -> OcamlTypes.parameter it) (OcamlTypes.ocaml_parameters parameters) in
            let fk_arg3 = (Ocaml.RecordType { fields = List.map (fun it -> field it) fields } : Ocaml.type_body) in
            ({ Ocaml.name = fk_arg1; parameters = fk_arg2; body = fk_arg3 } : Ocaml.type_definition)
        | Checker.Core.DeclaredCases { case_type = case_type; type_parameters = parameters; cases = cases } when Effect.perform (Lowering_isShared (case_type : Checker.Symbols.symbol).Checker.Symbols.name) -> let fk_arg1 = OcamlTypes.own_name (case_type : Checker.Symbols.symbol).Checker.Symbols.name in
            let fk_arg2 = List.map (fun it -> OcamlTypes.parameter it) (OcamlTypes.ocaml_parameters parameters) in
            let fk_arg3 = (Ocaml.PolymorphicVariantType { tags = List.map (fun c -> let fk_arg1 = Constructors.tag_name (c : Checker.Core.declared_case).Checker.Core.case in
                 let fk_arg2 = List.map (fun it -> OcamlTypes.typexpr (it : Checker.Core.declared_field).Checker.Core.t) (c : Checker.Core.declared_case).Checker.Core.fields in
                 ({ Ocaml.name = fk_arg1; carries = fk_arg2 } : Ocaml.tag)) cases } : Ocaml.type_body) in
            ({ Ocaml.name = fk_arg1; parameters = fk_arg2; body = fk_arg3 } : Ocaml.type_definition)
        | Checker.Core.DeclaredCases { case_type = case_type; type_parameters = parameters; cases = cases } -> let fk_arg1 = OcamlTypes.own_name (case_type : Checker.Symbols.symbol).Checker.Symbols.name in
            let fk_arg2 = List.map (fun it -> OcamlTypes.parameter it) (OcamlTypes.ocaml_parameters parameters) in
            let fk_arg3 = (Ocaml.VariantType { constructors = List.map (fun c -> ({ Ocaml.name = (((c : Checker.Core.declared_case).Checker.Core.case : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.name; carries = (if List.is_empty (c : Checker.Core.declared_case).Checker.Core.fields then (Ocaml.Bare : Ocaml.carried) else (Ocaml.InlineRecord { fields = List.map (fun it -> field it) (c : Checker.Core.declared_case).Checker.Core.fields } : Ocaml.carried)) } : Ocaml.constructor_declaration)) cases } : Ocaml.type_body) in
            ({ Ocaml.name = fk_arg1; parameters = fk_arg2; body = fk_arg3 } : Ocaml.type_definition)
        | Checker.Core.DeclaredAlias { alias = alias; type_parameters = parameters; target = target } -> let fk_arg1 = OcamlTypes.own_name (alias : Checker.Symbols.symbol).Checker.Symbols.name in
            let fk_arg2 = List.map (fun it -> OcamlTypes.parameter it) (OcamlTypes.ocaml_parameters parameters) in
            let fk_arg3 = (Ocaml.AliasType { typexpr = OcamlTypes.typexpr target } : Ocaml.type_body) in
            ({ Ocaml.name = fk_arg1; parameters = fk_arg2; body = fk_arg3 } : Ocaml.type_definition)
        | Checker.Core.DeclaredExternal { external_ = external_; type_parameters = parameters; ocaml = ocaml } -> let fk_arg1 = OcamlTypes.own_name (external_ : Checker.Symbols.symbol).Checker.Symbols.name in
            let fk_arg2 = List.map (fun it -> OcamlTypes.parameter it) (OcamlTypes.ocaml_parameters parameters) in
            ({ Ocaml.name = fk_arg1; parameters = fk_arg2; body = (Ocaml.AliasType { typexpr = (Ocaml.TypeApplication { name = "(" ^ ocaml ^ ")"; arguments = [] } : Ocaml.typexpr) } : Ocaml.type_body) } : Ocaml.type_definition)

      let definitions (types : Checker.Core.type_declaration list) : Ocaml.item list =
        if List.is_empty types then [] else [(Ocaml.TypeItem { definitions = List.map (fun it -> definition it) types } : Ocaml.item)]

      let show_function (full : string) (parameters : string list) (body : Ocaml.expr) : Ocaml.binding =
        let own = OcamlTypes.ocaml_parameters parameters in
        let t = let fk_arg1 = OcamlTypes.own_name full in
          let fk_arg2 = List.map (fun it -> (Ocaml.TypeVar { name = OcamlTypes.parameter it } : Ocaml.typexpr)) own in
          (Ocaml.TypeApplication { name = fk_arg1; arguments = fk_arg2 } : Ocaml.typexpr) in
        let fk_arg1 = (Ocaml.VariablePat { name = Shows.show_name full } : Ocaml.pat) in
        let fk_arg2 = List.map (fun it -> (Ocaml.VariablePat { name = "show_" ^ String.lowercase_ascii it } : Ocaml.pat)) own @ [(Ocaml.TypedPat { pattern = (Ocaml.VariablePat { name = "v" } : Ocaml.pat); typexpr = t } : Ocaml.pat)] in
        ({ Ocaml.pattern = fk_arg1; parameters = fk_arg2; result = None; body = body } : Ocaml.binding)

      let fields_text (label : string) (fields : Checker.Core.declared_field list) (record : Ocaml.expr) : Ocaml.expr =
        Shows.joined (([(Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = label ^ "(" } : Ocaml.constant) } : Ocaml.expr)] @ List.concat_map (fun it -> it) (List.mapi (fun i f -> [(Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = ((if i > 0 then ", " else "") ^ (f : Checker.Core.declared_field).Checker.Core.name) ^ "=" } : Ocaml.constant) } : Ocaml.expr); (let fk_arg1 = Shows.show (f : Checker.Core.declared_field).Checker.Core.t in
               let fk_arg2 = [(Ocaml.FieldAccess { record = record; field = Naming.snake (f : Checker.Core.declared_field).Checker.Core.name } : Ocaml.expr)] in
               (Ocaml.Application { function_ = fk_arg1; arguments = fk_arg2 } : Ocaml.expr))]) fields)) @ [(Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = ")" } : Ocaml.constant) } : Ocaml.expr)])

      let show_binding (d : Checker.Core.type_declaration) : Ocaml.binding option =
        match d with
        | Checker.Core.DeclaredRecord { record = record; type_parameters = parameters; fields = fields } -> Some (show_function (record : Checker.Symbols.symbol).Checker.Symbols.name parameters (fields_text (Naming.own_name record) fields (Ocaml.Identifier { path = "v" } : Ocaml.expr)))
        | Checker.Core.DeclaredCases { case_type = case_type; type_parameters = parameters; cases = cases } when Effect.perform (Lowering_isShared (case_type : Checker.Symbols.symbol).Checker.Symbols.name) -> Some (show_function (case_type : Checker.Symbols.symbol).Checker.Symbols.name parameters (Ocaml.Match { subject = (Ocaml.Identifier { path = "v" } : Ocaml.expr); cases = List.map (fun c -> let name = (((c : Checker.Core.declared_case).Checker.Core.case : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.name in
                let names = List.mapi (fun i _ -> "x" ^ string_of_int i) (c : Checker.Core.declared_case).Checker.Core.fields in
                let payload = match names with
                  | [] -> None
                  | [one] -> Some (Ocaml.VariablePat { name = one } : Ocaml.pat)
                  | _ -> Some (Ocaml.TuplePat { parts = List.map (fun it -> (Ocaml.VariablePat { name = it } : Ocaml.pat)) names } : Ocaml.pat) in
                let shown = if List.is_empty (c : Checker.Core.declared_case).Checker.Core.fields then (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = name } : Ocaml.constant) } : Ocaml.expr) else Shows.joined (([(Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = name ^ "(" } : Ocaml.constant) } : Ocaml.expr)] @ List.concat_map (fun it -> it) (List.mapi (fun i f -> [(Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = ((if i > 0 then ", " else "") ^ (f : Checker.Core.declared_field).Checker.Core.name) ^ "=" } : Ocaml.constant) } : Ocaml.expr); (Ocaml.Application { function_ = Shows.show (f : Checker.Core.declared_field).Checker.Core.t; arguments = [(Ocaml.Identifier { path = "x" ^ string_of_int i } : Ocaml.expr)] } : Ocaml.expr)]) (c : Checker.Core.declared_case).Checker.Core.fields)) @ [(Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = ")" } : Ocaml.constant) } : Ocaml.expr)]) in
                ({ Ocaml.pattern = (Ocaml.ConstructorPat { name = Constructors.tag (c : Checker.Core.declared_case).Checker.Core.case; argument = payload } : Ocaml.pat); guard = None; body = shown } : Ocaml.case)) cases } : Ocaml.expr))
        | Checker.Core.DeclaredCases { case_type = case_type; type_parameters = parameters; cases = cases } -> Some (show_function (case_type : Checker.Symbols.symbol).Checker.Symbols.name parameters (Ocaml.Match { subject = (Ocaml.Identifier { path = "v" } : Ocaml.expr); cases = List.map (fun c -> let name = (((c : Checker.Core.declared_case).Checker.Core.case : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.name in
                if List.is_empty (c : Checker.Core.declared_case).Checker.Core.fields then ({ Ocaml.pattern = (Ocaml.ConstructorPat { name = name; argument = None } : Ocaml.pat); guard = None; body = (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = name } : Ocaml.constant) } : Ocaml.expr) } : Ocaml.case) else ({ Ocaml.pattern = (Ocaml.ConstructorPat { name = name; argument = Some (Ocaml.VariablePat { name = "r" } : Ocaml.pat) } : Ocaml.pat); guard = None; body = fields_text name (c : Checker.Core.declared_case).Checker.Core.fields (Ocaml.Identifier { path = "r" } : Ocaml.expr) } : Ocaml.case)) cases } : Ocaml.expr))
        | Checker.Core.DeclaredAlias { alias = alias; type_parameters = parameters; target = target } -> Some (show_function (alias : Checker.Symbols.symbol).Checker.Symbols.name parameters (Ocaml.Application { function_ = Shows.show target; arguments = [(Ocaml.Identifier { path = "v" } : Ocaml.expr)] } : Ocaml.expr))
        | Checker.Core.DeclaredExternal { external_ = external_; type_parameters = parameters; ocaml = _ } -> Some (show_function (external_ : Checker.Symbols.symbol).Checker.Symbols.name parameters (Ocaml.ConstantExpr { constant = (Ocaml.StringConstant { value = "<" ^ Naming.own_name external_ ^ ">" } : Ocaml.constant) } : Ocaml.expr))

      let shows (types : Checker.Core.type_declaration list) : Ocaml.item list =
        let bindings = Lang.Lists.list_map_not_null (List.filter (fun t -> Option.is_none (Effect.perform (Lowering_toStringOf (Declarations.declared_at t : Checker.Symbols.symbol).Checker.Symbols.name))) types) (fun it -> show_binding it) in
        if List.is_empty bindings then [] else [(Ocaml.LetItem { recursive = true; bindings = bindings } : Ocaml.item)]
    end

    module Specs = struct
      let rec unknowns (t : Checker.Types.type_) (found : Checker.Types.type_variable list) : Checker.Types.type_variable list =
        match t with
        | Checker.Types.Variable { variable = v } -> if List.mem v found then found else found @ [v]
        | Checker.Types.Named { name = _; arguments = arguments; region = _ } -> List.fold_left (fun f a -> unknowns a f) found arguments
        | Checker.Types.Abstract { name = _; arguments = arguments } -> List.fold_left (fun f a -> unknowns a f) found arguments
        | Checker.Types.SpecOwnType { name = _; arguments = arguments } -> List.fold_left (fun f a -> unknowns a f) found arguments
        | Checker.Types.TupleOf { elements = parts } -> List.fold_left (fun f a -> unknowns a f) found parts
        | Checker.Types.FunctionOf { parameters = parameters; result = result; effects = _ } -> unknowns result (List.fold_left (fun f a -> unknowns a f) found parameters)
        | _ -> found

      let named (t : Checker.Types.type_) : (Checker.Types.type_variable * string) list =
        List.mapi (fun i v -> (v, ("'" ^ Option.value (Option.map (fun it -> fk_show_char it) (Lang.Lists.list_get_or_none ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) "abcdefghijklmnopqrstuvwxyz") (i mod 26))) ~default:"a") ^ (if i >= 26 then string_of_int (i / 26) else ""))) (unknowns t [])

      let module_type (d : Checker.Core.declared_spec) : Ocaml.item =
        let fk_arg1 = Naming.own_name (d : Checker.Core.declared_spec).Checker.Core.spec in
        let fk_arg2 = let fk_arg1 = List.map (fun (name, parameters) -> (Ocaml.TypeSignature { definition = (let fk_arg1 = Lang.Strings.string_remove_suffix (Naming.snake name) "_" in
                let fk_arg2 = List.map (fun it -> OcamlTypes.parameter it) (OcamlTypes.ocaml_parameters parameters) in
                ({ Ocaml.name = fk_arg1; parameters = fk_arg2; body = (Ocaml.AbstractType : Ocaml.type_body) } : Ocaml.type_definition)) } : Ocaml.signature_item)) (d : Checker.Core.declared_spec).Checker.Core.types in
          let fk_arg2 = List.map (fun (name, t) -> let fk_arg1 = Naming.snake name in
               let fk_arg2 = OcamlTypes.typexpr_naming t (named t) in
               (Ocaml.ValueSignature { name = fk_arg1; typexpr = fk_arg2 } : Ocaml.signature_item)) (d : Checker.Core.declared_spec).Checker.Core.values in
          fk_arg1 @ fk_arg2 in
        (Ocaml.ModuleTypeItem { name = fk_arg1; signature = fk_arg2 } : Ocaml.item)
    end

    module Structures = struct
      type using = { part : part; references : Checker.Symbols.symbol list; type_names : string list }

      let rec show_using (v : using) =
        "Using(" ^ "part=" ^ show_part v.part ^ ", references=" ^ fk_show_list Checker.Symbols.show_symbol v.references ^ ", typeNames=" ^ fk_show_list Fun.id v.type_names ^ ")"

      let alias_of (path : string list) : Ocaml.item list =
        if Effect.perform (Lowering_isHidden path) then (let name = Naming.module_name (Option.value (Lang.Lists.list_last_or_none path) ~default:"") in
           [(Ocaml.ModuleItem { name = Naming.outer_alias name; definition = (Ocaml.ModulePath { path = name } : Ocaml.module_expr) } : Ocaml.item)]) else []

      let within (inner : string list) (outer : string list) : bool =
        (let fk_arg1 = List.length inner in
         let fk_arg2 = List.length outer in
         fk_arg1 >= fk_arg2) && List.take (List.length outer) inner = outer

      let is_in (s : Checker.Symbols.symbol) (part : part) : bool =
        match part with
        | TypesPart { types = types } -> List.exists (fun it -> (Declarations.declared_at it : Checker.Symbols.symbol).Checker.Symbols.name = (s : Checker.Symbols.symbol).Checker.Symbols.name) types
        | EffectPart { effect_ = effect_ } -> ((effect_ : Checker.Core.declared_effect).Checker.Core.effect_ : Checker.Symbols.symbol).Checker.Symbols.name = (s : Checker.Symbols.symbol).Checker.Symbols.name
        | SpecPart { spec = spec } -> ((spec : Checker.Core.declared_spec).Checker.Core.spec : Checker.Symbols.symbol).Checker.Symbols.name = (s : Checker.Symbols.symbol).Checker.Symbols.name
        | GroupPart { group = group } -> List.exists (fun it -> (it : Checker.Symbols.symbol).Checker.Symbols.name = (s : Checker.Symbols.symbol).Checker.Symbols.name) (group : Checker.Inference.function_group).Checker.Inference.functions
        | ModulePart { path = path } -> within (s : Checker.Symbols.symbol).Checker.Symbols.path path || within ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) (s : Checker.Symbols.symbol).Checker.Symbols.name ".") path

      let type_is_in (name : string) (part : part) : bool =
        match part with
        | TypesPart { types = types } -> List.exists (fun it -> (Declarations.declared_at it : Checker.Symbols.symbol).Checker.Symbols.name = name) types
        | SpecPart { spec = spec } -> ((spec : Checker.Core.declared_spec).Checker.Core.spec : Checker.Symbols.symbol).Checker.Symbols.name = name
        | ModulePart { path = path } -> within (Lang.Lists.list_drop_last ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".") 1) path
        | _ -> false

      let uses (u : using) (other : part) : bool =
        List.exists (fun s -> is_in s other) (u : using).references || List.exists (fun name -> type_is_in name other) (u : using).type_names

      let rec placing (left : using list) (placed : part list) : part list =
        match left with
        | [] -> placed
        | first :: _ -> let ready = Option.value (List.find_opt (fun u -> Lang.Lists.list_none left (fun other -> (other : using).part <> (u : using).part && uses u (other : using).part)) left) ~default:first in
            placing (List.filter (fun it -> (it : using).part <> (ready : using).part) left) (placed @ [(ready : using).part])

      let functions_of (part : part) (own : own_code) : (Checker.Symbols.symbol * Checker.Types.type_ * Checker.Core.core_function) list =
        List.concat_map (fun (_, functions) -> functions) (List.filter (fun (g, _) -> match part with
            | GroupPart { group = group } -> g = group
            | ModulePart { path = path } -> List.exists (fun f -> within (f : Checker.Symbols.symbol).Checker.Symbols.path path) (g : Checker.Inference.function_group).Checker.Inference.functions
            | _ -> false) (own : own_code).groups)

      let references_of (part : part) (own : own_code) : Checker.Symbols.symbol list =
        List.concat_map (fun (_, _, body) -> Checker.Core.Cores.references (body : Checker.Core.core_function).Checker.Core.body) (functions_of part own)

      let rec type_names (t : Checker.Types.type_) : string list =
        match t with
        | Checker.Types.Named { name = name; arguments = arguments; region = _ } -> [name] @ List.concat_map (fun it -> type_names it) arguments
        | Checker.Types.Abstract { name = name; arguments = arguments } -> [name] @ List.concat_map (fun it -> type_names it) arguments
        | Checker.Types.TupleOf { elements = parts } -> List.concat_map (fun it -> type_names it) parts
        | Checker.Types.FunctionOf { parameters = parameters; result = result; effects = _ } -> let fk_arg1 = List.concat_map (fun it -> type_names it) parameters in
            let fk_arg2 = type_names result in
            fk_arg1 @ fk_arg2
        | Checker.Types.ModuleValue { spec = spec; arguments = arguments; own_types = _ } -> [spec] @ List.concat_map (fun it -> type_names it) arguments
        | _ -> []

      let declared_type_names (t : Checker.Core.type_declaration) : string list =
        match t with
        | Checker.Core.DeclaredRecord { record = _; type_parameters = _; fields = fields } -> List.concat_map (fun it -> type_names (it : Checker.Core.declared_field).Checker.Core.t) fields
        | Checker.Core.DeclaredCases { case_type = _; type_parameters = _; cases = cases } -> List.concat_map (fun c -> [(((c : Checker.Core.declared_case).Checker.Core.case : Checker.Symbols.case_symbol).Checker.Symbols.owner : Checker.Symbols.symbol).Checker.Symbols.name] @ List.concat_map (fun it -> type_names (it : Checker.Core.declared_field).Checker.Core.t) (c : Checker.Core.declared_case).Checker.Core.fields) cases
        | Checker.Core.DeclaredAlias { alias = _; type_parameters = _; target = target } -> type_names target
        | Checker.Core.DeclaredExternal { external_ = _; type_parameters = _; ocaml = _ } -> []

      let effect_type_names (e : Checker.Core.declared_effect) : string list =
        List.concat_map (fun op -> let fk_arg1 = List.concat_map (fun it -> type_names it) (Option.value (op : Checker.Core.declared_operation).Checker.Core.parameters ~default:[]) in
           let fk_arg2 = type_names (op : Checker.Core.declared_operation).Checker.Core.result in
           fk_arg1 @ fk_arg2) (e : Checker.Core.declared_effect).Checker.Core.operations

      let type_names_of (part : part) (own : own_code) : string list =
        let fk_arg1 = List.concat_map (fun (_, t, _) -> type_names t) (functions_of part own) in
        let fk_arg2 = match part with
          | TypesPart { types = types } -> List.concat_map (fun it -> declared_type_names it) types
          | EffectPart { effect_ = effect_ } -> effect_type_names effect_
          | SpecPart { spec = spec } -> List.concat_map (fun (_, t) -> type_names t) (spec : Checker.Core.declared_spec).Checker.Core.values
          | GroupPart { group = _ } -> []
          | ModulePart { path = path } -> let fk_arg1 = List.concat_map (fun it -> declared_type_names it) (List.filter (fun t -> within (Declarations.declared_at t : Checker.Symbols.symbol).Checker.Symbols.path path) (own : own_code).types) in
              let fk_arg2 = List.concat_map (fun it -> effect_type_names it) (List.filter (fun e -> within ((e : Checker.Core.declared_effect).Checker.Core.effect_ : Checker.Symbols.symbol).Checker.Symbols.path path) (own : own_code).effects) in
              fk_arg1 @ fk_arg2 in
        fk_arg1 @ fk_arg2

      let ordered (parts : part list) (own : own_code) : part list =
        placing (List.map (fun p -> let fk_arg1 = references_of p own in
            let fk_arg2 = Lang.Lists.list_distinct (type_names_of p own) in
            ({ part = p; references = fk_arg1; type_names = fk_arg2 } : using)) parts) []

      let rec reachable (to_visit : int list) (seen : int list) (named : int list list) : int list =
        match to_visit with
        | [] -> seen
        | i :: rest -> if List.mem i seen then reachable rest seen named else reachable (rest @ Option.value (Lang.Lists.list_get_or_none named i) ~default:[]) (seen @ [i]) named

      let type_groups (types : Checker.Core.type_declaration list) : Checker.Core.type_declaration list list =
        let names = List.map (fun it -> (Declarations.declared_at it : Checker.Symbols.symbol).Checker.Symbols.name) types in
        let named = List.map (fun t -> List.filter (fun it -> it >= 0) (List.map (fun n -> Lang.Lists.list_index_of names n) (declared_type_names t))) types in
        let reaching = List.map (fun i -> reachable [i] [] named) ((fun from e -> List.init (max 0 (e - from)) (fun i -> from + i)) 0 (List.length types)) in
        let reaches = fun from to_ -> Option.value (Option.map (fun it -> List.mem to_ it) (Lang.Lists.list_get_or_none reaching from)) ~default:false in
        let (groups, _) = List.fold_left (fun acc i -> let (found, placed) = acc in
             if List.mem i placed then acc else (let group = List.filter (fun j -> j = i || reaches i j && reaches j i) ((fun from e -> List.init (max 0 (e - from)) (fun i -> from + i)) 0 (List.length types)) in
                (found @ [group], placed @ group))) ([], []) ((fun from e -> List.init (max 0 (e - from)) (fun i -> from + i)) 0 (List.length types)) in
        List.map (fun group -> Lang.Lists.list_map_not_null group (fun it -> Lang.Lists.list_get_or_none types it)) groups

      let parts_at (path : string list) (own : own_code) : part list =
        let types = List.filter (fun t -> (Declarations.declared_at t : Checker.Symbols.symbol).Checker.Symbols.path = path && (match t with
              | Checker.Core.DeclaredExternal t_as_declared_external -> false
              | _ -> true)) (own : own_code).types in
        let effects = List.map (fun it -> (EffectPart { effect_ = it } : part)) (List.filter (fun it -> ((it : Checker.Core.declared_effect).Checker.Core.effect_ : Checker.Symbols.symbol).Checker.Symbols.path = path) (own : own_code).effects) in
        let specs = List.map (fun it -> (SpecPart { spec = it } : part)) (List.filter (fun it -> ((it : Checker.Core.declared_spec).Checker.Core.spec : Checker.Symbols.symbol).Checker.Symbols.path = path) (own : own_code).specs) in
        let from_groups = Lang.Lists.list_distinct (Lang.Lists.list_map_not_null (own : own_code).groups (fun (g, _) -> let group_path = Option.value (Option.map (fun it -> (it : Checker.Symbols.symbol).Checker.Symbols.path) (List.nth_opt (g : Checker.Inference.function_group).Checker.Inference.functions 0)) ~default:[] in
              if group_path = path then Some (GroupPart { group = g } : part) else if (let fk_arg1 = List.length group_path in
                 let fk_arg2 = List.length path in
                 fk_arg1 > fk_arg2) && List.take (List.length path) group_path = path then Some (ModulePart { path = List.take (List.length path + 1) group_path } : part) else None)) in
        let others = List.map (fun it -> (ModulePart { path = it } : part)) (List.filter (fun m -> (let fk_arg1 = List.length m in
               let fk_arg2 = List.length path + 1 in
               fk_arg1 = fk_arg2) && List.take (List.length path) m = path) (own : own_code).modules) in
        (let fk_arg1 = (List.map (fun it -> (TypesPart { types = it } : part)) (type_groups types) @ specs) @ effects in
         let fk_arg2 = List.filter (fun it -> not (List.mem it from_groups)) others in
         fk_arg1 @ fk_arg2) @ from_groups

      let binding (function_ : Checker.Symbols.symbol) (t : Checker.Types.type_) (body : Checker.Core.core_function) : Ocaml.binding =
        let name = (Ocaml.VariablePat { name = Naming.snake (Naming.own_name function_) } : Ocaml.pat) in
        let value = Expressions.expression (body : Checker.Core.core_function).Checker.Core.body in
        match t with
        | Checker.Types.FunctionOf { parameters = parameter_types; result = result; effects = _ } when Checker.Symbols.Signatures.is_function function_ -> let parameters = if List.is_empty (body : Checker.Core.core_function).Checker.Core.parameters then [(Ocaml.ConstantPat { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.pat)] else List.map (fun (p, pt) -> let fk_arg1 = (Ocaml.VariablePat { name = Naming.snake p } : Ocaml.pat) in
                   let fk_arg2 = OcamlTypes.typexpr pt in
                   (Ocaml.TypedPat { pattern = fk_arg1; typexpr = fk_arg2 } : Ocaml.pat)) (Lang.Lists.list_zip (body : Checker.Core.core_function).Checker.Core.parameters parameter_types) in
            ({ Ocaml.pattern = name; parameters = parameters; result = Some (OcamlTypes.typexpr result); body = value } : Ocaml.binding)
        | _ -> ({ Ocaml.pattern = name; parameters = []; result = None; body = value } : Ocaml.binding)

      let rec items (path : string list) (own : own_code) : Ocaml.item list =
        let besides = List.concat_map (fun (p, item) -> match item with
             | Ocaml.ModuleItem { name = name; definition = _ } -> item :: alias_of (p @ [(let fk_arg1 = String.lowercase_ascii ((fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in String.sub s 0 (at 0 n)) name 1) in
                   let fk_arg2 = (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in String.sub s i (String.length s - i)) name 1 in
                   fk_arg1 ^ fk_arg2)])
             | _ -> [item]) (List.filter (fun (p, _) -> p = path) (own : own_code).besides) in
        besides @ List.concat_map (fun it -> part_items it own) (ordered (parts_at path own) own)
      and part_items (part : part) (own : own_code) : Ocaml.item list =
        match part with
        | TypesPart { types = types } -> let fk_arg1 = TypeItems.definitions types in
            let fk_arg2 = TypeItems.shows types in
            fk_arg1 @ fk_arg2
        | EffectPart { effect_ = effect_ } -> HandledEffects.declarations effect_
        | SpecPart { spec = spec } -> [Specs.module_type spec]
        | GroupPart { group = group } -> let bindings = Option.value (Option.map (fun (_, functions) -> List.map (fun (f, t, body) -> binding f t body) functions) (List.find_opt (fun (g, _) -> g = group) (own : own_code).groups)) ~default:[] in
            if List.is_empty bindings then [] else [(Ocaml.LetItem { recursive = (group : Checker.Inference.function_group).Checker.Inference.recursive; bindings = bindings } : Ocaml.item)]
        | ModulePart { path = path } -> let name = Option.value (Lang.Lists.list_last_or_none path) ~default:"" in
            let inner = handle_lowering ({ to_string_of = (fun x0 k -> k ((fun type_name -> Effect.perform (Lowering_toStringOf type_name)) x0)); declaration_of = (fun x0 k -> k ((fun type_name -> Effect.perform (Lowering_declarationOf type_name)) x0)); is_shared = (fun x0 k -> k ((fun type_name -> Effect.perform (Lowering_isShared type_name)) x0)); spec_of = (fun x0 k -> k ((fun spec_name -> Effect.perform (Lowering_specOf spec_name)) x0)); effect_of = (fun x0 k -> k ((fun effect_name -> Effect.perform (Lowering_effectOf effect_name)) x0)); is_module = (fun x0 k -> k ((fun p -> Effect.perform (Lowering_isModule p)) x0)); is_hidden = (fun x0 k -> k ((fun p -> Effect.perform (Lowering_isHidden p)) x0)); inside = (fun k -> k ((fun () -> path) ())) } : _ lowering_handler) (fun () -> items path own) in
            let fk_arg1 = (Ocaml.ModuleItem { name = Naming.module_name name; definition = (Ocaml.Structure { items = inner } : Ocaml.module_expr) } : Ocaml.item) in
            let fk_arg2 = alias_of path in
            fk_arg1 :: fk_arg2
    end

    module Programs = struct
      let unit_of (f : Checker.Sources.loaded_file) : string option =
        if ((f : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.project = (Checker.Sources.CoreProject : Checker.Sources.project) then Some "Fckt_core" else ((f : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.compiled_in

      let compiled_apart (f : Checker.Sources.loaded_file) : bool =
        Option.is_some (unit_of f)

      let rec modules_in (declarations : Parser.declaration list) (path : string list) : string list list =
        List.concat_map (fun d -> match (d : Parser.declaration).Parser.definition with
           | Parser.ModuleDefinition { declarations = inner; spec = _; parameters = _; application = None; type_parameters = _ } -> [path @ [(d : Parser.declaration).Parser.name]] @ modules_in inner (path @ [(d : Parser.declaration).Parser.name])
           | _ -> []) declarations

      let modules_of (program : Checker.checked_program) (whole : bool) : string list list =
        Lang.Lists.list_distinct (List.concat_map (fun f -> let packages = List.map (fun n -> List.take n (f : Checker.Sources.loaded_file).Checker.Sources.package) (Lang.Maths.int_range_to 1 (List.length (f : Checker.Sources.loaded_file).Checker.Sources.package)) in
            packages @ modules_in (f : Checker.Sources.loaded_file).Checker.Sources.declarations (f : Checker.Sources.loaded_file).Checker.Sources.package) (List.filter (fun f -> whole || not (compiled_apart f)) ((program : Checker.checked_program).Checker.workspace : Checker.Sources.workspace).Checker.Sources.files))

      let outermost_compiled (program : Checker.checked_program) : (string list * string) list =
        let compiled = Lang.Lists.list_distinct (Lang.Lists.list_map_not_null (List.filter (fun it -> Lang.Lists.list_is_not_empty (it : Checker.Sources.loaded_file).Checker.Sources.package) ((program : Checker.checked_program).Checker.workspace : Checker.Sources.workspace).Checker.Sources.files) (fun f -> Option.map (fun unit -> ((f : Checker.Sources.loaded_file).Checker.Sources.package, unit)) (unit_of f))) in
        List.filter (fun (pkg, unit) -> Lang.Lists.list_none compiled (fun (other, other_unit) -> (other_unit = unit && (let fk_arg1 = List.length other in
                let fk_arg2 = List.length pkg in
                fk_arg1 < fk_arg2)) && List.take (List.length other) pkg = other)) compiled

      let prefixes (path : string list) : string list list =
        List.map (fun n -> List.take n path) (Lang.Maths.int_range_to 1 (List.length path))

      let hidden_among (modules : string list list) : string list list =
        List.filter (fun t -> let parent = Lang.Lists.list_drop_last t 1 in
           List.exists (fun u -> ((let fk_arg1 = List.length u in
                let fk_arg2 = List.length t in
                fk_arg1 > fk_arg2) && (let fk_arg1 = Lang.Lists.list_last_or_none u in
                let fk_arg2 = Lang.Lists.list_last_or_none t in
                fk_arg1 = fk_arg2)) && List.take (List.length parent) u = parent) modules) modules

      let sharing (program : Checker.checked_program) : string list =
        Lang.Lists.list_distinct (List.concat_map (fun t -> match t with
            | Checker.Core.DeclaredCases { case_type = case_type; type_parameters = _; cases = cases } -> List.concat_map (fun c -> [(case_type : Checker.Symbols.symbol).Checker.Symbols.name; (((c : Checker.Core.declared_case).Checker.Core.case : Checker.Symbols.case_symbol).Checker.Symbols.owner : Checker.Symbols.symbol).Checker.Symbols.name]) (List.filter (fun c -> (((c : Checker.Core.declared_case).Checker.Core.case : Checker.Symbols.case_symbol).Checker.Symbols.owner : Checker.Symbols.symbol).Checker.Symbols.name <> (case_type : Checker.Symbols.symbol).Checker.Symbols.name) cases)
            | _ -> []) (program : Checker.checked_program).Checker.types)

      let owned_by_program (s : Checker.Symbols.symbol) : bool =
        not (compiled_apart (s : Checker.Symbols.symbol).Checker.Symbols.file)

      let made_by_program (program : Checker.checked_program) : string list list =
        List.concat_map (fun m -> match m with
           | Checker.Symbols.DeclaredModule { symbol = s } when owned_by_program s -> (match ((s : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.definition with
                | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _; application = Some _; type_parameters = _ } -> [(fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) (s : Checker.Symbols.symbol).Checker.Symbols.name "."]
                | _ -> [])
           | _ -> []) (Option.value (Option.map (fun e -> Collections.Maps.map_values ((((e : Checker.Inference.environment).Checker.Inference.definitions : Checker.Definitions.definitions).Checker.Definitions.namespace : Checker.Resolution.namespace).Checker.Resolution.table : Checker.Symbols.symbol_table).Checker.Symbols.modules) (program : Checker.checked_program).Checker.environment) ~default:[])

      let aliases (program : Checker.checked_program) : (string list * Ocaml.item) list =
        List.map (fun (pkg, unit) -> let name = Naming.module_name (Option.value (Lang.Lists.list_last_or_none pkg) ~default:"") in
           let path = String.concat "." (List.map Fun.id ([unit] @ List.map (fun it -> Naming.module_name it) pkg)) in
           (Lang.Lists.list_drop_last pkg 1, (Ocaml.ModuleItem { name = name; definition = (Ocaml.ModulePath { path = path } : Ocaml.module_expr) } : Ocaml.item))) (outermost_compiled program)

      let rec functors_in (declarations : Parser.declaration list) (path : string list) : string list list =
        List.concat_map (fun d -> match (d : Parser.declaration).Parser.definition with
           | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _ :: _; application = _; type_parameters = _ } -> [path @ [(d : Parser.declaration).Parser.name]]
           | Parser.ModuleDefinition { declarations = inner; spec = _; parameters = []; application = None; type_parameters = _ } -> functors_in inner (path @ [(d : Parser.declaration).Parser.name])
           | _ -> []) declarations

      let functors_of (program : Checker.checked_program) (whole : bool) : string list list =
        List.concat_map (fun f -> functors_in (f : Checker.Sources.loaded_file).Checker.Sources.declarations (f : Checker.Sources.loaded_file).Checker.Sources.package) (List.filter (fun f -> whole || not (compiled_apart f)) ((program : Checker.checked_program).Checker.workspace : Checker.Sources.workspace).Checker.Sources.files)

      let items (program : Checker.checked_program) (whole : bool) : Ocaml.item list =
        let made = made_by_program program in
        let is_own = fun s -> (whole || owned_by_program s) || List.exists (fun m -> List.take (List.length m) (s : Checker.Symbols.symbol).Checker.Symbols.path = m) made in
        let bodies = Lang.Lists.list_map_not_null (List.filter (fun f -> is_own (f : Checker.Inference.checked_function).Checker.Inference.function_) (program : Checker.checked_program).Checker.functions) (fun f -> Option.map (fun b -> ((f : Checker.Inference.checked_function).Checker.Inference.function_, ((f : Checker.Inference.checked_function).Checker.Inference.scheme : Checker.Types.scheme).Checker.Types.template, b)) (f : Checker.Inference.checked_function).Checker.Inference.body) in
        let groups = Lang.Lists.list_map_not_null (program : Checker.checked_program).Checker.groups (fun g -> let functions = Lang.Lists.list_map_not_null (g : Checker.Inference.function_group).Checker.Inference.functions (fun f -> List.find_opt (fun (s, _, _) -> (s : Checker.Symbols.symbol).Checker.Symbols.name = (f : Checker.Symbols.symbol).Checker.Symbols.name) bodies) in
             if List.is_empty functions then None else Some (g, functions)) in
        let compiled = if whole then [] else aliases program in
        let functors = functors_of program whole in
        let lowered = fun s -> is_own s && Lang.Lists.list_none functors (fun f -> (let fk_arg1 = List.length (s : Checker.Symbols.symbol).Checker.Symbols.path in
                let fk_arg2 = List.length f in
                fk_arg1 >= fk_arg2) && List.take (List.length f) (s : Checker.Symbols.symbol).Checker.Symbols.path = f) in
        let own = let fk_arg1 = Lang.Lists.list_map_not_null groups (fun (g, functions) -> let kept = List.filter (fun (f, _, _) -> lowered f) functions in
               if List.is_empty kept then None else Some (g, kept)) in
          let fk_arg2 = List.filter (fun t -> lowered (Declarations.declared_at t)) (program : Checker.checked_program).Checker.types in
          let fk_arg3 = List.filter (fun e -> lowered (e : Checker.Core.declared_effect).Checker.Core.effect_) (program : Checker.checked_program).Checker.effects in
          let fk_arg4 = List.filter (fun s -> lowered (s : Checker.Core.declared_spec).Checker.Core.spec) (program : Checker.checked_program).Checker.specs in
          let fk_arg5 = Lang.Lists.list_distinct (let fk_arg1 = List.filter (fun m -> Lang.Lists.list_none functors (fun f -> (let fk_arg1 = List.length m in
                      let fk_arg2 = List.length f in
                      fk_arg1 >= fk_arg2) && List.take (List.length f) m = f)) (modules_of program whole) in
             let fk_arg2 = List.concat_map (fun (at, _) -> prefixes at) compiled in
             fk_arg1 @ fk_arg2) in
          ({ groups = fk_arg1; types = fk_arg2; effects = fk_arg3; specs = fk_arg4; modules = fk_arg5; besides = compiled } : own_code) in
        let main = Option.map (fun f -> let takes_arguments = Option.value (Option.map (fun it -> Lang.Lists.list_is_not_empty it) (Checker.Symbols.Signatures.parameters_of (f : Checker.Inference.checked_function).Checker.Inference.function_)) ~default:false in
             (Ocaml.LetItem { recursive = false; bindings = [({ Ocaml.pattern = (Ocaml.ConstantPat { constant = (Ocaml.UnitConstant : Ocaml.constant) } : Ocaml.pat); parameters = []; result = None; body = HandledEffects.running_main (f : Checker.Inference.checked_function).Checker.Inference.function_ takes_arguments (program : Checker.checked_program).Checker.default_handlers } : Ocaml.binding)] } : Ocaml.item)) (List.find_opt (fun f -> (is_own (f : Checker.Inference.checked_function).Checker.Inference.function_ && List.is_empty ((f : Checker.Inference.checked_function).Checker.Inference.function_ : Checker.Symbols.symbol).Checker.Symbols.path) && Naming.own_name (f : Checker.Inference.checked_function).Checker.Inference.function_ = "main") (program : Checker.checked_program).Checker.functions) in
        let fk_arg1 = [(Ocaml.VerbatimItem { code = Helpers.items } : Ocaml.item)] @ Structures.items [] own in
        let fk_arg2 = Option.to_list main in
        fk_arg1 @ fk_arg2

      let ocaml (program : Checker.checked_program) (whole : bool) : Ocaml.item list =
        let modules = let fk_arg1 = modules_of program whole in
          let fk_arg2 = if whole then [] else List.concat_map (fun (pkg, _) -> prefixes pkg) (outermost_compiled program) in
          fk_arg1 @ fk_arg2 in
        let known = Collections.Sets.list_to_set (List.map (fun it -> String.concat "." (List.map Fun.id it)) modules) in
        let hidden = Collections.Sets.list_to_set (List.map (fun it -> String.concat "." (List.map Fun.id it)) (hidden_among modules)) in
        handle_lowering ({ to_string_of = (fun x0 k -> k ((fun name -> Collections.Maps.map_get (program : Checker.checked_program).Checker.to_strings name) x0)); declaration_of = (fun x0 k -> k ((fun name -> List.find_opt (fun it -> (Declarations.declared_at it : Checker.Symbols.symbol).Checker.Symbols.name = name) (program : Checker.checked_program).Checker.types) x0)); is_shared = (fun x0 k -> k ((fun name -> List.mem name (sharing program)) x0)); spec_of = (fun x0 k -> k ((fun name -> List.find_opt (fun it -> ((it : Checker.Core.declared_spec).Checker.Core.spec : Checker.Symbols.symbol).Checker.Symbols.name = name) (program : Checker.checked_program).Checker.specs) x0)); effect_of = (fun x0 k -> k ((fun name -> List.find_opt (fun it -> ((it : Checker.Core.declared_effect).Checker.Core.effect_ : Checker.Symbols.symbol).Checker.Symbols.name = name) (program : Checker.checked_program).Checker.effects) x0)); is_module = (fun x0 k -> k ((fun path -> Collections.Sets.set_contains known (String.concat "." (List.map Fun.id path))) x0)); is_hidden = (fun x0 k -> k ((fun path -> Collections.Sets.set_contains hidden (String.concat "." (List.map Fun.id path))) x0)); inside = (fun k -> k ((fun () -> []) ())) } : _ lowering_handler) (fun () -> items program whole)

      let ocaml_default_whole () : bool =
        false
    end
  end

  module Compiler = struct
    type json =
      | JsonNull
      | JsonBoolean of { value : bool }
      | JsonNumber of { text : string }
      | JsonString of { value : string }
      | JsonArray of { items : json list }
      | JsonObject of { fields : (string * json) list }

    let rec show_json (v : json) =
      match v with
      | JsonNull -> "JsonNull"
      | JsonBoolean r -> "JsonBoolean(" ^ "value=" ^ string_of_bool r.value ^ ")"
      | JsonNumber r -> "JsonNumber(" ^ "text=" ^ Fun.id r.text ^ ")"
      | JsonString r -> "JsonString(" ^ "value=" ^ Fun.id r.value ^ ")"
      | JsonArray r -> "JsonArray(" ^ "items=" ^ fk_show_list show_json r.items ^ ")"
      | JsonObject r -> "JsonObject(" ^ "fields=" ^ fk_show_list (fun (x0, x1) -> "(" ^ Fun.id x0 ^ ", " ^ show_json x1 ^ ")") r.fields ^ ")"

    module Interfaces = struct
      let import_line (i : Parser.import) : string =
        let alias = Option.value (Option.map (fun it -> " as " ^ it) (i : Parser.import).Parser.alias) ~default:"" in
        ((("import " ^ String.concat "." (List.map Fun.id (i : Parser.import).Parser.path)) ^ (if (i : Parser.import).Parser.wildcard then ".*" else "")) ^ alias) ^ "\n"

      let seen (declarations : Parser.declaration list) : Parser.declaration list =
        List.filter (fun it -> (it : Parser.declaration).Parser.visibility = (Parser.Public : Parser.visibility)) declarations

      let offset (text : string) (at : Parser.position) : int =
        Lang.Lists.list_sum_of (List.take ((at : Parser.position).Parser.line - 1) (Lang.Strings.string_lines text)) (fun it -> (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) it + 1) + (at : Parser.position).Parser.column - 1

      let rec closing (tokens : Parser.token list) (depth : int) : Parser.position option =
        match tokens with
        | [] -> None
        | t :: rest -> match (t : Parser.token).Parser.kind with
            | Parser.LeftBrace -> closing rest (depth + 1)
            | Parser.RightBrace -> if depth = 1 then Some (t : Parser.token).Parser.at else closing rest (depth - 1)
            | _ -> closing rest depth

      let verbatim (d : Parser.declaration) (text : string) : string =
        let starts = (d : Parser.declaration).Parser.at :: List.map (fun it -> (it : Parser.annotation).Parser.at) (d : Parser.declaration).Parser.annotations in
        let start = Option.value (Lang.Lists.list_min_by_or_none starts (fun it -> offset text it)) ~default:(d : Parser.declaration).Parser.at in
        let tokens = match Parser.Lexer.tokens text (Parser.Lexer.tokens_default_from ()) with
          | Ok all -> Lang.Lists.list_drop_while all (fun t -> ((t : Parser.token).Parser.at : Parser.position).Parser.line < ((d : Parser.declaration).Parser.at : Parser.position).Parser.line || ((t : Parser.token).Parser.at : Parser.position).Parser.line = ((d : Parser.declaration).Parser.at : Parser.position).Parser.line && ((t : Parser.token).Parser.at : Parser.position).Parser.column < ((d : Parser.declaration).Parser.at : Parser.position).Parser.column)
          | Error _ -> [] in
        let end_ = closing (Lang.Lists.list_drop_while tokens (fun it -> (it : Parser.token).Parser.kind <> (Parser.LeftBrace : Parser.kind))) 0 in
        let fk_arg1 = offset text start in
        let fk_arg2 = let fk_arg1 = Option.map (fun it -> offset text it + 1) end_ in
          let fk_arg2 = (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) text in
          Option.value fk_arg1 ~default:fk_arg2 in
        Lang.Strings.string_substring text fk_arg1 fk_arg2

      let is_effect (d : Parser.declaration) : bool =
        List.exists (fun it -> (it : Parser.annotation).Parser.name = "Effect") (d : Parser.declaration).Parser.annotations && (match (d : Parser.declaration).Parser.definition with
         | Parser.SpecDefinition { types = _; values = _; type_parameters = _; copy_of = _; parents = _ } -> true
         | Parser.RecordDefinition { type_parameters = _; fields = fields; private_constructor = _; annotation = true; external_ = _ } -> List.is_empty fields
         | _ -> false)

      let bracketed (open_ : string) (items : string list) (close : string) : string =
        (open_ ^ String.concat ", " (List.map Fun.id items)) ^ close

      let escaped (text : string) (quote : int) : string =
        String.concat "" (List.map Fun.id (List.map (fun c -> match c with
             | 92 -> "\\\\"
             | 36 -> "\\$"
             | 10 -> "\\n"
             | 9 -> "\\t"
             | 13 -> "\\r"
             | _ -> if c = quote then "\\" ^ fk_show_char c else fk_show_char c) ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) text)))

      let string (text : string) : string =
        ("\"" ^ escaped text 34) ^ "\""

      let rec constant (e : Parser.expression) : string =
        match e with
        | Parser.IntConstant { at = _; value = n } -> string_of_int n
        | Parser.FloatConstant { at = _; value = x } -> fk_show_float x
        | Parser.BooleanConstant { at = _; value = b } -> string_of_bool b
        | Parser.CharConstant { at = _; value = c } -> ("'" ^ escaped (fk_show_char c) 39) ^ "'"
        | Parser.StringTemplate { at = _; parts = parts } -> string (String.concat "" (List.map Fun.id (List.map (fun p -> match p with
                  | Parser.TemplateText { text = t } -> t
                  | Parser.Interpolation { expression = _ } -> "") parts)))
        | Parser.Unary { at = _; operator = operator; operand = operand } -> operator ^ constant operand
        | _ -> ""

      let rec type_text (t : Parser.type_ref) : string =
        match t with
        | Parser.NamedType { at = _; name = name; arguments = [] } -> name
        | Parser.NamedType { at = _; name = name; arguments = arguments } -> name ^ bracketed "<" (List.map (fun it -> type_text it) arguments) ">"
        | Parser.FunctionType { at = _; parameters = parameters; result = result; effects = effects } -> let fk_arg1 = (let fk_arg1 = String.concat "" (List.map Fun.id (List.map (fun it -> effect_text it ^ " ") effects)) in
               let fk_arg2 = bracketed "(" (List.map (fun it -> type_text it) parameters) ")" in
               fk_arg1 ^ fk_arg2) ^ " -> " in
            let fk_arg2 = type_text result in
            fk_arg1 ^ fk_arg2
        | Parser.TupleType { at = _; elements = elements } -> bracketed "(" (List.map (fun it -> type_text it) elements) ")"
        | Parser.EffectsType { at = _; effects = effects } -> String.concat " " (List.map Fun.id (List.map (fun it -> effect_text it) effects))
        | Parser.GivenType { at = _; name = name; given = given } -> name ^ " = " ^ type_text given
      and effect_text (a : Parser.annotation) : string =
        let arguments = List.map (fun it -> type_text it) (a : Parser.annotation).Parser.type_arguments in
        ("@" ^ (a : Parser.annotation).Parser.name) ^ (if List.is_empty arguments then "" else bracketed "<" arguments ">")

      let rec argument (a : Parser.annotation_argument) : string =
        let fk_arg1 = Option.value (Option.map (fun it -> it ^ " = ") (a : Parser.annotation_argument).Parser.name) ~default:"" in
        let fk_arg2 = value (a : Parser.annotation_argument).Parser.value in
        fk_arg1 ^ fk_arg2
      and value (v : Parser.annotation_value) : string =
        match v with
        | Parser.Constant { expression = e } -> constant e
        | Parser.Reference { at = _; name = name; type_arguments = type_arguments; arguments = arguments } -> let fk_arg1 = name ^ Option.value (Option.map (fun ts -> bracketed "<" (List.map (fun it -> type_text it) ts) ">") type_arguments) ~default:"" in
            let fk_arg2 = Option.value (Option.map (fun args -> bracketed "(" (List.map (fun it -> argument it) args) ")") arguments) ~default:"" in
            fk_arg1 ^ fk_arg2
        | Parser.ValueList { at = _; items = items } -> bracketed "[" (List.map (fun it -> value it) items) "]"
        | Parser.ValueTuple { at = _; items = items } -> bracketed "(" (List.map (fun it -> value it) items) ")"

      let annotations (annotations : Parser.annotation list) : string =
        String.concat "" (List.map Fun.id (List.map (fun a -> let given = if List.is_empty (a : Parser.annotation).Parser.arguments then "" else bracketed "(" (List.map (fun it -> argument it) (a : Parser.annotation).Parser.arguments) ")" in
             (effect_text a ^ given) ^ " ") annotations))

      let type_parameter_list (names : string list) : string =
        if List.is_empty names then "" else ("<" ^ String.concat ", " (List.map Fun.id names)) ^ ">"

      let applied (application : Parser.application) : string =
        (let fk_arg1 = type_text (application : Parser.application).Parser.functor_ ^ "(" in
         let fk_arg2 = String.concat ", " (List.map Fun.id (List.map (fun a -> let fk_arg1 = Option.value (Option.map (fun it -> it ^ " = ") (a : Parser.module_argument).Parser.name) ~default:"" in
                let fk_arg2 = type_text (a : Parser.module_argument).Parser.value in
                fk_arg1 ^ fk_arg2) (application : Parser.application).Parser.arguments)) in
         fk_arg1 ^ fk_arg2) ^ ")"

      let field_list (fields : Parser.field list) : string =
        ("(" ^ String.concat ", " (List.map Fun.id (List.map (fun f -> let fk_arg1 = let fk_arg1 = (annotations (f : Parser.field).Parser.annotations ^ (if (f : Parser.field).Parser.variable then "var " else "")) ^ (if (f : Parser.field).Parser.vararg then "vararg " else "") in
                let fk_arg2 = (f : Parser.field).Parser.name ^ ": " ^ type_text (f : Parser.field).Parser.field_type in
                fk_arg1 ^ fk_arg2 in
              let fk_arg2 = if Option.is_some (f : Parser.field).Parser.default then " = compiled" else "" in
              fk_arg1 ^ fk_arg2) fields))) ^ ")"

      let rec names_in (t : Parser.type_ref) : string list =
        match t with
        | Parser.NamedType { at = _; name = name; arguments = [] } -> [name]
        | Parser.NamedType { at = _; name = _; arguments = arguments } -> List.concat_map (fun it -> names_in it) arguments
        | Parser.TupleType { at = _; elements = elements } -> List.concat_map (fun it -> names_in it) elements
        | Parser.FunctionType { at = _; parameters = parameters; result = result; effects = _ } -> List.concat_map (fun it -> names_in it) (parameters @ [result])
        | Parser.EffectsType { at = _; effects = _ } -> []
        | Parser.GivenType { at = _; name = _; given = given } -> names_in given

      let receiver_text (t : Parser.type_ref) : string =
        match t with
        | Parser.FunctionType { at = _; parameters = _; result = _; effects = _ } -> "(" ^ type_text t ^ ")"
        | _ -> type_text t

      let parameter_text (p : Parser.parameter) : string =
        let fk_arg1 = let fk_arg1 = annotations (p : Parser.parameter).Parser.annotations ^ (p : Parser.parameter).Parser.name in
          let fk_arg2 = Option.value (Option.map (fun it -> ": " ^ type_text it) (p : Parser.parameter).Parser.parameter_type) ~default:"" in
          fk_arg1 ^ fk_arg2 in
        let fk_arg2 = if Option.is_some (p : Parser.parameter).Parser.default then " = compiled" else "" in
        fk_arg1 ^ fk_arg2

      let rec declaration (d : Parser.declaration) (indent : string) (text : string) : string =
        match (d : Parser.declaration).Parser.definition with
        | Parser.SpecDefinition { types = _; values = _; type_parameters = _; copy_of = None; parents = _ } -> (indent ^ verbatim d text) ^ "\n"
        | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _ :: _; application = _; type_parameters = _ } -> (indent ^ verbatim d text) ^ "\n"
        | definition -> let effect_ = is_effect d in
            let kept = List.filter (fun a -> not (effect_ && (a : Parser.annotation).Parser.name = "Effect")) (d : Parser.declaration).Parser.annotations in
            let opaque = if (d : Parser.declaration).Parser.opaque then "opaque " else "" in
            let fk_arg1 = (indent ^ annotations kept) ^ opaque in
            let fk_arg2 = match definition with
              | Parser.ModuleDefinition { declarations = _; spec = _; parameters = _; application = Some application; type_parameters = type_parameters } -> let fk_arg1 = type_parameter_list type_parameters in
                  let fk_arg2 = applied application in
                  "module " ^ (d : Parser.declaration).Parser.name ^ fk_arg1 ^ " = " ^ fk_arg2 ^ "\n"
              | other -> definition_text (d : Parser.declaration).Parser.name other effect_ indent text ^ "\n" in
            fk_arg1 ^ fk_arg2
      and definition_text (name : string) (definition : Parser.definition) (effect_ : bool) (indent : string) (text : string) : string =
        match definition with
        | Parser.RecordDefinition { type_parameters = _; fields = _; private_constructor = _; annotation = _; external_ = _ } when effect_ -> "effect " ^ name
        | Parser.RecordDefinition { type_parameters = _; fields = fields; private_constructor = _; annotation = true; external_ = _ } -> ("annotation type " ^ name) ^ (if List.is_empty fields then "" else field_list fields)
        | Parser.RecordDefinition { type_parameters = type_parameters; fields = _; private_constructor = _; annotation = _; external_ = Some external_ } -> let fk_arg1 = type_parameter_list type_parameters in
            let fk_arg2 = string external_ in
            "external type " ^ name ^ fk_arg1 ^ " = " ^ fk_arg2
        | Parser.RecordDefinition { type_parameters = type_parameters; fields = fields; private_constructor = private_constructor; annotation = _; external_ = None } -> let fk_arg1 = ("type " ^ name ^ type_parameter_list type_parameters) ^ (if private_constructor then " private" else "") in
            let fk_arg2 = field_list fields in
            fk_arg1 ^ fk_arg2
        | Parser.CasesDefinition { type_parameters = type_parameters; cases = cases; case_refs = case_refs; includes = includes } -> let own = List.map (fun c -> let fields = if List.is_empty (c : Parser.case_definition).Parser.fields then "" else field_list (c : Parser.case_definition).Parser.fields in
                 indent ^ "  " ^ annotations (c : Parser.case_definition).Parser.annotations ^ (c : Parser.case_definition).Parser.name ^ fields ^ ",\n") cases in
            let referred = List.map (fun c -> indent ^ "  " ^ (c : Parser.case_ref).Parser.owner ^ "." ^ (c : Parser.case_ref).Parser.case_name ^ ",\n") case_refs in
            let included = List.map (fun t -> indent ^ "  *" ^ type_text t ^ ",\n") includes in
            let items = String.concat "" (List.map Fun.id ((own @ referred) @ included)) in
            (("type " ^ name ^ type_parameter_list type_parameters ^ " {\n") ^ items) ^ indent ^ "}"
        | Parser.AliasDefinition { type_parameters = type_parameters; target = target } -> let fk_arg1 = type_parameter_list type_parameters in
            let fk_arg2 = type_text target in
            "type " ^ name ^ fk_arg1 ^ " = " ^ fk_arg2
        | Parser.FunctionDefinition { type_parameters = type_parameters; receiver = receiver; parameters = parameters; result = result; body = _; external_ = external_; operator = operator } -> let own = match receiver with
              | Some r -> List.filter (fun it -> not (List.mem it (names_in r))) type_parameters
              | None -> type_parameters in
            let fk_arg1 = let fk_arg1 = let fk_arg1 = let fk_arg1 = (let fk_arg1 = (if operator then "operator " else "") ^ (if Option.is_some external_ then "external " else "") in
                     let fk_arg2 = Option.value (Option.map (fun r -> receiver_text r ^ ".") receiver) ~default:"" in
                     fk_arg1 ^ fk_arg2) ^ name in
                  let fk_arg2 = type_parameter_list own in
                  fk_arg1 ^ fk_arg2 in
                let fk_arg2 = Option.value (Option.map (fun ps -> bracketed "(" (List.map (fun it -> parameter_text it) ps) ")") parameters) ~default:"" in
                fk_arg1 ^ fk_arg2 in
              let fk_arg2 = Option.value (Option.map (fun it -> ": " ^ type_text it) result) ~default:"" in
              fk_arg1 ^ fk_arg2 in
            let fk_arg2 = Option.value (Option.map (fun it -> " = " ^ string it) external_) ~default:"" in
            fk_arg1 ^ fk_arg2
        | Parser.ModuleDefinition { declarations = declarations; spec = spec; parameters = parameters; application = _; type_parameters = type_parameters } -> let given = if List.is_empty parameters then "" else ("(" ^ String.concat ", " (List.map Fun.id (List.map (fun p -> let fk_arg1 = (p : Parser.module_parameter).Parser.name ^ ": " ^ type_text (p : Parser.module_parameter).Parser.spec in
                      let fk_arg2 = Option.value (Option.map (fun it -> " = " ^ type_text it) (p : Parser.module_parameter).Parser.default) ~default:"" in
                      fk_arg1 ^ fk_arg2) parameters))) ^ ")" in
            let inner = String.concat "" (List.map Fun.id (List.map (fun it -> declaration it (indent ^ "  ") text) (seen declarations))) in
            let follows = Option.value (Option.map (fun it -> " : " ^ type_text it) spec) ~default:"" in
            (("module " ^ name ^ type_parameter_list type_parameters ^ given ^ follows ^ " {\n") ^ inner) ^ indent ^ "}"
        | Parser.SpecDefinition { types = _; values = _; type_parameters = _; copy_of = copy_of; parents = _ } -> let copied = Option.value (Option.map (fun it -> " = " ^ type_text it) copy_of) ~default:"" in
            ((if effect_ then "effect " else "spec ") ^ name) ^ copied

      let write (file : Parser.source_file) (path : string) (text : string) (hidden : string list) : string =
        let header = ("// The interface of " ^ path ^ ", which fckt --library wrote: ") ^ "its declarations, without their code.\n" in
        let shown = List.filter (fun i -> let full = String.concat "." (List.map Fun.id (i : Parser.import).Parser.path) in
             not (List.exists (fun it -> full = it || String.starts_with ~prefix:(it ^ ".") full) hidden)) (file : Parser.source_file).Parser.imports in
        let imports = String.concat "" (List.map Fun.id (List.map (fun i -> import_line i) shown)) in
        let declarations = List.map (fun d -> "\n" ^ declaration d "" text) (seen (file : Parser.source_file).Parser.declarations) in
        let fk_arg1 = header ^ (if String.equal "" imports then "" else "\n" ^ imports) in
        let fk_arg2 = String.concat "" (List.map Fun.id declarations) in
        fk_arg1 ^ fk_arg2

      let write_default_hidden () : string list =
        []

      let sees_any (file : Parser.source_file) : bool =
        Lang.Lists.list_is_not_empty (seen (file : Parser.source_file).Parser.declarations)

      let rec untyped (declarations : Parser.declaration list) : (Parser.position * string) list =
        List.concat_map (fun d -> untyped_in d) (seen declarations)
      and untyped_in (d : Parser.declaration) : (Parser.position * string) list =
        match (d : Parser.declaration).Parser.definition with
        | Parser.ModuleDefinition { declarations = inner; spec = _; parameters = _; application = _; type_parameters = _ } -> untyped inner
        | Parser.FunctionDefinition { type_parameters = _; receiver = receiver; parameters = parameters; result = result; body = _; external_ = _; operator = _ } -> let lacking = List.map (fun it -> (it : Parser.parameter).Parser.name) (List.filter (fun it -> Option.is_none (it : Parser.parameter).Parser.parameter_type) (Option.value parameters ~default:[])) in
            let in_interface = "'" ^ (d : Parser.declaration).Parser.name ^ "' is in a library's interface, which programs are checked against, so" in
            if Lang.Lists.list_is_not_empty lacking then [((d : Parser.declaration).Parser.at, in_interface ^ " its parameters need types: " ^ String.concat ", " (List.map Fun.id lacking))] else if (Option.is_none result && Option.is_none parameters) && Option.is_none receiver then [((d : Parser.declaration).Parser.at, in_interface ^ " it needs a type: " ^ (d : Parser.declaration).Parser.name ^ ": Type = ...")] else if Option.is_none result then [((d : Parser.declaration).Parser.at, in_interface ^ " it needs a result type: " ^ (d : Parser.declaration).Parser.name ^ "(...): Type = ...")] else []
        | _ -> []
    end

    module Jsons = struct
      let char_at (cs : ((int) array)) (at : int) : int option =
        if at >= 0 && at < Array.length cs then Some (Array.get cs at) else None

      let rec spaces (cs : ((int) array)) (at : int) : int =
        match char_at cs at with
        | Some c when ((c = 32 || c = 10) || c = 13) || c = 9 -> spaces cs (at + 1)
        | _ -> at

      let digit (c : int) : int option =
        if Lang.Strings.char_is_digit c then Some (Fun.id c - 48) else if c >= 97 && c <= 102 then Some (Fun.id c - 87) else if c >= 65 && c <= 70 then Some (Fun.id c - 55) else None

      let hex (cs : ((int) array)) (at : int) : int option =
        List.fold_left (fun sum k -> Option.bind sum (fun n -> Option.map (fun it -> n * 16 + it) (Option.bind (char_at cs (at + k)) (fun it -> digit it)))) (Some 0) ((fun from e -> List.init (max 0 (e - from)) (fun i -> from + i)) 0 4)

      let escaped (c : int) : int option =
        if (c = 34 || c = 92) || c = 47 then Some c else if c = 110 then Some 10 else if c = 116 then Some 9 else if c = 114 then Some 13 else if c = 98 then Some ((fun n -> Uchar.to_int (Uchar.of_int n)) 8) else if c = 102 then Some ((fun n -> Uchar.to_int (Uchar.of_int n)) 12) else None

      let rec string (cs : ((int) array)) (at : int) (found : int list) : (string * int) option =
        match char_at cs at with
        | None -> None
        | Some c -> if c = 34 then Some (String.concat "" (List.map Fun.id (List.map (fun it -> fk_show_char it) (List.rev found))), at + 1) else if c <> 92 then string cs (at + 1) ([c] @ found) else (match char_at cs (at + 1) with
                 | Some 117 -> Option.bind (hex cs (at + 2)) (fun code -> if ((code >= 55296 && code <= 56319) && char_at cs (at + 6) = Some 92) && char_at cs (at + 7) = Some 117 then Option.bind (hex cs (at + 8)) (fun low -> let combined = 65536 + (code - 55296) * 1024 + (low - 56320) in
                             string cs (at + 12) ([(fun n -> Uchar.to_int (Uchar.of_int n)) combined] @ found)) else if code >= 55296 && code <= 57343 then string cs (at + 6) ([(fun n -> Uchar.to_int (Uchar.of_int n)) 65533] @ found) else string cs (at + 6) ([(fun n -> Uchar.to_int (Uchar.of_int n)) code] @ found))
                 | Some e -> Option.bind (escaped e) (fun it -> string cs (at + 2) ([it] @ found))
                 | None -> None)

      let slice (cs : ((int) array)) (from : int) (to_ : int) : string =
        String.concat "" (List.map Fun.id (List.map (fun it -> fk_show_char (Array.get cs it)) ((fun from e -> List.init (max 0 (e - from)) (fun i -> from + i)) from (min to_ (Array.length cs)))))

      let literal (cs : ((int) array)) (at : int) (word : string) (json : json) : (json * int) option =
        if slice cs at (at + (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) word) = word then Some (json, at + (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) word) else None

      let rec number_end (cs : ((int) array)) (at : int) : int =
        match char_at cs at with
        | Some c when ((((Lang.Strings.char_is_digit c || c = 45) || c = 43) || c = 46) || c = 101) || c = 69 -> number_end cs (at + 1)
        | _ -> at

      let rec value (cs : ((int) array)) (at : int) : (json * int) option =
        let i = spaces cs at in
        match char_at cs i with
        | None -> None
        | Some c -> if c = 123 then fields cs (i + 1) [] else if c = 91 then items cs (i + 1) [] else if c = 34 then Option.map (fun (s, after) -> ((JsonString { value = s } : json), after)) (string cs (i + 1) []) else if c = 116 then literal cs i "true" (JsonBoolean { value = true } : json) else if c = 102 then literal cs i "false" (JsonBoolean { value = false } : json) else if c = 110 then literal cs i "null" (JsonNull : json) else if c = 45 || Lang.Strings.char_is_digit c then (let end_ = number_end cs i in
                           Some ((JsonNumber { text = slice cs i end_ } : json), end_)) else None
      and fields (cs : ((int) array)) (at : int) (found : (string * json) list) : (json * int) option =
        let i = spaces cs at in
        if List.is_empty found && char_at cs i = Some 125 then Some ((JsonObject { fields = [] } : json), i + 1) else if char_at cs i <> Some 34 then None else Option.bind (string cs (i + 1) []) (fun key -> let (name, after_name) = key in
               let colon = spaces cs after_name in
               if char_at cs colon <> Some 58 then None else Option.bind (value cs (colon + 1)) (fun parsed -> let (item, after_value) = parsed in
                    let next = spaces cs after_value in
                    let all = found @ [(name, item)] in
                    match char_at cs next with
                    | Some 44 -> fields cs (next + 1) all
                    | Some 125 -> Some ((JsonObject { fields = all } : json), next + 1)
                    | _ -> None))
      and items (cs : ((int) array)) (at : int) (found : json list) : (json * int) option =
        let i = spaces cs at in
        if List.is_empty found && char_at cs i = Some 93 then Some ((JsonArray { items = [] } : json), i + 1) else Option.bind (value cs i) (fun parsed -> let (item, after_value) = parsed in
             let next = spaces cs after_value in
             let all = found @ [item] in
             match char_at cs next with
             | Some 44 -> items cs (next + 1) all
             | Some 93 -> Some ((JsonArray { items = all } : json), next + 1)
             | _ -> None)

      let parse (text : string) : json option =
        let chars = Array.of_list ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) text) in
        Option.bind (value chars 0) (fun parsed -> let (json, after) = parsed in
           if let fk_arg1 = spaces chars after in
           let fk_arg2 = Array.length chars in
           fk_arg1 = fk_arg2 then Some json else None)

      let rec hex_of (n : int) : string =
        if n < 16 then Option.value (Option.map (fun it -> fk_show_char it) ((fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in if n < 0 || i >= String.length s then None else Some (Uchar.to_int (Uchar.utf_decode_uchar (String.get_utf_8_uchar s i)))) "0123456789abcdef" n)) ~default:"" else (let fk_arg1 = hex_of (n / 16) in
           let fk_arg2 = hex_of (n mod 16) in
           fk_arg1 ^ fk_arg2)

      let quoted (text : string) : string =
        ("\"" ^ String.concat "" (List.map Fun.id (List.map (fun c -> if c = 34 then "\\\"" else if c = 92 then "\\\\" else if c = 10 then "\\n" else if c = 13 then "\\r" else if c = 9 then "\\t" else if Fun.id c < 32 then "\\u" ^ Lang.Strings.string_pad_start (hex_of (Fun.id c)) 4 48 else fk_show_char c) ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) text)))) ^ "\""

      let rec render (json : json) : string =
        match json with
        | JsonNull -> "null"
        | JsonBoolean { value = value } -> if value then "true" else "false"
        | JsonNumber { text = text } -> text
        | JsonString { value = value } -> quoted value
        | JsonArray { items = items } -> ("[" ^ String.concat "," (List.map Fun.id (List.map (fun it -> render it) items))) ^ "]"
        | JsonObject { fields = fields } -> ("{" ^ String.concat "," (List.map Fun.id (List.map (fun (name, value) -> let fk_arg1 = quoted name ^ ":" in
                  let fk_arg2 = render value in
                  fk_arg1 ^ fk_arg2) fields))) ^ "}"

      let json_field (this : json) (name : string) : json option =
        match this with
        | JsonObject { fields = fields } -> Option.map (fun (_, value) -> value) (List.find_opt (fun (n, _) -> n = name) fields)
        | _ -> None

      let json_text (this : json) : string option =
        match this with
        | JsonString { value = value } -> Some value
        | _ -> None

      let json_int (this : json) : int option =
        match this with
        | JsonNumber { text = text } -> int_of_string_opt text
        | _ -> None

      let json_items (this : json) : json list =
        match this with
        | JsonArray { items = items } -> items
        | _ -> []

      let number (n : int) : json =
        (JsonNumber { text = string_of_int n } : json)
    end

    module Layout = struct
      type splittable = { open_ : Parser.token; close : Parser.token; commas : Parser.token list }

      let rec show_splittable (v : splittable) =
        "Splittable(" ^ "open=" ^ Parser.show_token v.open_ ^ ", close=" ^ Parser.show_token v.close ^ ", commas=" ^ fk_show_list Parser.show_token v.commas ^ ")"

      let tokens_of (source : string) : ((Parser.token) array) option =
        match Parser.Lexer.tokens source (Parser.Lexer.tokens_default_from ()) with
        | Ok tokens -> Some (Array.of_list tokens)
        | Error _ -> None

      let adjacent (before : Parser.token) (after : Parser.token) : bool =
        ((before : Parser.token).Parser.at : Parser.position).Parser.line = ((after : Parser.token).Parser.at : Parser.position).Parser.line && ((before : Parser.token).Parser.at : Parser.position).Parser.column + (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) (before : Parser.token).Parser.text = ((after : Parser.token).Parser.at : Parser.position).Parser.column

      let rec matching_greater (tokens : ((Parser.token) array)) (j : int) (depth : int) : int option =
        if j >= Array.length tokens then None else (match (Array.get tokens j : Parser.token).Parser.kind with
           | Parser.Less -> matching_greater tokens (j + 1) (depth + 1)
           | Parser.Greater -> if depth = 0 then Some j else matching_greater tokens (j + 1) (depth - 1)
           | Parser.LeftBrace -> None
           | Parser.RightBrace -> None
           | Parser.Newline -> None
           | Parser.Assign -> None
           | Parser.Semicolon -> None
           | _ -> matching_greater tokens (j + 1) depth)

      let type_arguments (tokens : ((Parser.token) array)) (i : int) : bool =
        ((i > 0 && (Array.get tokens (i - 1) : Parser.token).Parser.kind = (Parser.Identifier : Parser.kind)) && (let fk_arg1 = Array.get tokens (i - 1) in
          let fk_arg2 = Array.get tokens i in
          adjacent fk_arg1 fk_arg2)) && Option.is_some (matching_greater tokens (i + 1) 0)

      let rec matching_less (tokens : ((Parser.token) array)) (j : int) (depth : int) : int option =
        if j < 0 then None else (match (Array.get tokens j : Parser.token).Parser.kind with
           | Parser.Greater -> matching_less tokens (j - 1) (depth + 1)
           | Parser.Less -> if depth <> 0 then matching_less tokens (j - 1) (depth - 1) else if type_arguments tokens j then Some j else None
           | Parser.LeftBrace -> None
           | Parser.RightBrace -> None
           | Parser.Newline -> None
           | Parser.Assign -> None
           | Parser.Semicolon -> None
           | _ -> matching_less tokens (j - 1) depth)

      let closes (tokens : ((Parser.token) array)) (i : int) : bool =
        match (Array.get tokens i : Parser.token).Parser.kind with
        | Parser.RightParen -> true
        | Parser.RightBracket -> true
        | Parser.RightBrace -> true
        | Parser.Greater -> Option.is_some (matching_less tokens (i - 1) 0)
        | _ -> false

      let opens (tokens : ((Parser.token) array)) (i : int) : bool =
        match (Array.get tokens i : Parser.token).Parser.kind with
        | Parser.LeftParen -> true
        | Parser.LeftBracket -> true
        | Parser.LeftBrace -> true
        | Parser.Less -> type_arguments tokens i
        | _ -> false

      let depths_of (tokens : ((Parser.token) array)) : ((int) array) =
        let depths = Array.make (Array.length tokens) 0 in
        List.fold_left (fun depth i -> let here = if closes tokens i then depth - 1 else depth in
           Array.set depths i here;
           if opens tokens i then here + 1 else here) 0 (Lang.Maths.int_range_to 0 (Array.length tokens - 1));
        depths

      let width =
        100

      let indent_of (line : string) : string =
        String.concat "" (List.map Fun.id (List.map (fun it -> fk_show_char it) (Lang.Lists.list_take_while ((fun s -> let rec go i acc = if i >= String.length s then List.rev acc else let d = String.get_utf_8_uchar s i in go (i + Uchar.utf_decode_length d) (Uchar.to_int (Uchar.utf_decode_uchar d) :: acc) in go 0 []) line) (fun it -> it = 32))))

      let rec candidates (tokens : ((Parser.token) array)) (depths : ((int) array)) (line : int) (outermost : int) (left : int list) (found : (int * int * int list) list) : (int * int * int list) list =
        match left with
        | [] -> found
        | index :: rest -> let open_ = Array.get tokens index in
            let skip = fun () -> candidates tokens depths line outermost rest found in
            if (Array.get depths index <> outermost || not (opens tokens index)) || (open_ : Parser.token).Parser.kind = (Parser.Less : Parser.kind) then skip () else if (open_ : Parser.token).Parser.kind <> (Parser.LeftParen : Parser.kind) && (open_ : Parser.token).Parser.kind <> (Parser.LeftBracket : Parser.kind) then found else (match List.find_opt (fun it -> Array.get depths it = outermost && closes tokens it) (Lang.Maths.int_range_to (index + 1) (Array.length tokens - 1)) with
                 | None -> found
                 | Some close -> if ((Array.get tokens close : Parser.token).Parser.at : Parser.position).Parser.line <> line then found else (let before = if index > 0 then Some (Array.get tokens (index - 1)) else None in
                        let before_kind = Option.map (fun it -> (it : Parser.token).Parser.kind) before in
                        let before_text = Option.value (Option.map (fun it -> (it : Parser.token).Parser.text) before) ~default:"" in
                        let lambda = close + 1 < Array.length tokens && (Array.get tokens (close + 1) : Parser.token).Parser.kind = (Parser.Arrow : Parser.kind) in
                        let condition = ((before_kind = Some (Parser.IfKeyword : Parser.kind) || before_kind = Some (Parser.WhenKeyword : Parser.kind)) || before_text = "while") || before_text = "for" in
                        let not_call = ((open_ : Parser.token).Parser.kind = (Parser.LeftParen : Parser.kind) && before_kind <> Some (Parser.Identifier : Parser.kind)) && before_kind <> Some (Parser.Greater : Parser.kind) in
                        let commas = List.filter (fun j -> (Array.get tokens j : Parser.token).Parser.kind = (Parser.Comma : Parser.kind) && Array.get depths j = outermost + 1) (Lang.Maths.int_range_to (index + 1) (close - 1)) in
                        let spreads = (Array.get tokens (Option.value (Option.map (fun it -> it + 1) (Lang.Lists.list_last_or_none commas)) ~default:(index + 1)) : Parser.token).Parser.kind = (Parser.Star : Parser.kind) in
                        if (((close = index + 1 || lambda) || condition) || not_call) || spreads then skip () else candidates tokens depths line outermost rest (found @ [(index, close, commas)])))

      let splittable (tokens : ((Parser.token) array)) (depths : ((int) array)) (line : int) : splittable option =
        let on_line = List.filter (fun it -> ((Array.get tokens it : Parser.token).Parser.at : Parser.position).Parser.line = line) (Lang.Maths.int_range_to 0 (Array.length tokens - 1)) in
        if List.is_empty on_line then None else (let outermost = Option.value (Lang.Lists.list_min_or_none (List.map (fun it -> Array.get depths it) on_line)) ~default:0 in
           let found = candidates tokens depths line outermost on_line [] in
           match found with
           | [] -> None
           | (open_, close, commas) :: _ -> let after = if close + 1 < Array.length tokens then Some (Array.get tokens (close + 1) : Parser.token).Parser.kind else None in
               let declaring = after = Some (Parser.Colon : Parser.kind) || after = Some (Parser.Assign : Parser.kind) in
               let declares = (Array.get tokens open_ : Parser.token).Parser.kind = (Parser.LeftParen : Parser.kind) && declaring in
               let first = (open_, close, commas) in
               let (o, c, cs) = if declares then first else Option.value (Lang.Lists.list_last_or_none found) ~default:first in
               Some (let fk_arg1 = Array.get tokens o in
                let fk_arg2 = Array.get tokens c in
                let fk_arg3 = List.map (fun it -> Array.get tokens it) cs in
                ({ open_ = fk_arg1; close = fk_arg2; commas = fk_arg3 } : splittable)))

      let rec after_dots (on_line : ((Parser.token) array)) (i : int) : int =
        if (i + 1 < Array.length on_line && (Array.get on_line i : Parser.token).Parser.kind = (Parser.Dot : Parser.kind)) && (Array.get on_line (i + 1) : Parser.token).Parser.kind = (Parser.Identifier : Parser.kind) then after_dots on_line (i + 2) else i

      let rec after_parentheses (on_line : ((Parser.token) array)) (i : int) (depth : int) : int =
        if i >= Array.length on_line then i + 1 else (let t = Array.get on_line i in
           let inner = if (t : Parser.token).Parser.kind = (Parser.LeftParen : Parser.kind) then depth + 1 else if (t : Parser.token).Parser.kind = (Parser.RightParen : Parser.kind) then depth - 1 else depth in
           if (t : Parser.token).Parser.kind = (Parser.RightParen : Parser.kind) && inner = 0 then i + 1 else after_parentheses on_line (i + 1) inner)

      let rec annotation_ends (on_line : ((Parser.token) array)) (i : int) (ends : int list) : int list option =
        if i >= Array.length on_line || (Array.get on_line i : Parser.token).Parser.kind <> (Parser.At : Parser.kind) then Some ends else (let named = if i + 1 < Array.length on_line && (Array.get on_line (i + 1) : Parser.token).Parser.kind = (Parser.Identifier : Parser.kind) then i + 2 else i + 1 in
           let dotted = after_dots on_line named in
           let called = ((dotted > 0 && dotted < Array.length on_line) && (Array.get on_line dotted : Parser.token).Parser.kind = (Parser.LeftParen : Parser.kind)) && (let fk_arg1 = Array.get on_line (dotted - 1) in
              let fk_arg2 = Array.get on_line dotted in
              adjacent fk_arg1 fk_arg2) in
           let next = if called then after_parentheses on_line dotted 0 else dotted in
           if next < Array.length on_line then annotation_ends on_line next (ends @ [((Array.get on_line next : Parser.token).Parser.at : Parser.position).Parser.column - 1]) else None)

      let annotations_apart (tokens : ((Parser.token) array)) (line : int) (first : string) (indent : string) : string list option =
        let on_line = Array.of_list (List.filter (fun it -> ((it : Parser.token).Parser.at : Parser.position).Parser.line = line) (Array.to_list tokens)) in
        match annotation_ends on_line 0 [] with
        | Some ends when Lang.Lists.list_is_not_empty ends && Lang.Strings.string_is_blank (Lang.Strings.string_substring first 0 ((fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) indent)) -> let starts = let fk_arg1 = [(fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) indent] in
              let fk_arg2 = Lang.Lists.list_drop_last ends 1 in
              fk_arg1 @ fk_arg2 in
            let last = Option.value (Lang.Lists.list_last_or_none ends) ~default:0 in
            Some (let fk_arg1 = List.map (fun (from, to_) -> indent ^ String.trim (Lang.Strings.string_substring first from to_)) (Lang.Lists.list_zip starts ends) in
             let fk_arg2 = [indent ^ String.trim (Lang.Strings.string_substring first last ((fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) first))] in
             fk_arg1 @ fk_arg2)
        | _ -> None

      let annotated_apart (tokens : ((Parser.token) array)) (line : int) (first : string) (indent : string) : string list =
        if (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) first <= width then [first] else Option.value (annotations_apart tokens line first indent) ~default:[first]

      let fits (lines : string list) : bool =
        Option.value (Option.map (fun it -> (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) it <= width) (Lang.Lists.list_last_or_none lines)) ~default:true

      let split_at (lines : string list) (tokens : ((Parser.token) array)) (depths : ((int) array)) (i : int) : string option =
        let line = Option.value (Lang.Lists.list_get_or_none lines i) ~default:"" in
        if (fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) line <= width then None else (let indent = indent_of line in
           let replaced = match splittable tokens depths (i + 1) with
             | Some ({ open_ = open_; close = close; commas = commas } : splittable) -> let cuts = ([((open_ : Parser.token).Parser.at : Parser.position).Parser.column] @ List.map (fun it -> ((it : Parser.token).Parser.at : Parser.position).Parser.column) commas) @ [((close : Parser.token).Parser.at : Parser.position).Parser.column] in
                 let items = List.filter (fun it -> Lang.Strings.string_is_not_empty it) (List.map (fun (from, to_) -> String.trim (Lang.Strings.string_substring line from (to_ - 1))) (Lang.Lists.list_zip cuts (List.drop 1 cuts))) in
                 Some (let fk_arg1 = let fk_arg1 = annotated_apart tokens (i + 1) (Lang.Strings.string_trim_end (Lang.Strings.string_substring line 0 ((open_ : Parser.token).Parser.at : Parser.position).Parser.column)) indent in
                    let fk_arg2 = List.map (fun it -> indent ^ "  " ^ it ^ ",") items in
                    fk_arg1 @ fk_arg2 in
                  let fk_arg2 = [indent ^ Lang.Strings.string_substring line (((close : Parser.token).Parser.at : Parser.position).Parser.column - 1) ((fun s -> let rec go i n = if i >= String.length s then n else go (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n + 1) in go 0 0) line)] in
