        session.said <- Collections.Maps.map_put (session : session).said ((project : project).root : Io.path).Io.value (Collections.Maps.map_keys by_file)

      let checked (session : session) (uri : string) : unit =
        match Effects.Failure.attempt (fun () -> check session uri) with
        | Ok _ -> ()
        | Error why -> Io.Channels.print_error ("fckt: can't check " ^ uri ^ ": " ^ why)

      let rec served (session : session) : unit =
        match received () with
        | None -> (match Effect.perform (Io.Process_exit (if (session : session).stopping then 0 else 1)) with
             | _ -> (assert false))
        | Some message -> handled session message;
            if Lang.Lists.list_is_not_empty (session : session).changed && not ((fun s -> try let (r, _, _) = Unix.select [Unix.stdin] [] [] s in r <> [] with Unix.Unix_error _ -> false) 0.15) then (let changed = (session : session).changed in
               session.changed <- [];
               List.iter (fun it -> checked session it) (Collections.Maps.map_values (List.fold_left (fun by_root u -> Collections.Maps.map_put by_root ((project_of (path_of u) : project).root : Io.path).Io.value u) (Collections.Maps.empty_map ()) changed))) else ();
            served session

      let serve () : unit =
        served (let fk_arg1 = Collections.Maps.empty_map () in
         let fk_arg2 = Collections.Maps.empty_map () in
         let fk_arg3 = Collections.Maps.empty_map () in
         ({ open_ = fk_arg1; said = fk_arg2; programs = fk_arg3; stopping = false; changed = [] } : session))
    end

    module Symbols = struct
      type writing = { environment : Checker.Inference.environment; names : (string, string) Collections.Maps.map; metas : (string, Checker.Definitions.meta_type list) Collections.Maps.map }

      let rec show_writing (v : writing) =
        "Writing(" ^ "environment=" ^ Checker.Inference.show_environment v.environment ^ ", names=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id Fun.id) v.names ^ ", metas=" ^ (fun v -> Collections.Maps.map_to_string v Fun.id (fk_show_list Checker.Definitions.show_meta_type)) v.metas ^ ")"

      let version =
        1

      let empty =
        "fckt-symbols " ^ string_of_int version ^ "\n"

      let position_key (f : Checker.Sources.loaded_file) (at : Parser.position) : string =
        Option.value ((f : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path ~default:"" ^ ":" ^ string_of_int (at : Parser.position).Parser.line ^ ":" ^ string_of_int (at : Parser.position).Parser.column

      let line (depth : int) (text : string) : string =
        (Lang.Strings.string_repeat "  " depth ^ text) ^ "\n"

      let at (depth : int) (p : Parser.position) (file : Checker.Sources.loaded_file) : string =
        line depth ("at " ^ string_of_int (p : Parser.position).Parser.line ^ " " ^ string_of_int (p : Parser.position).Parser.column ^ " " ^ Option.value ((file : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path ~default:"")

