        let parts = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name "." in
        let own = Option.value (Lang.Lists.list_last_or_none parts) ~default:name in
        let found = if List.length parts > 1 then (let owner = String.concat "." (List.map Fun.id (Lang.Lists.list_drop_last parts 1)) in
             let namespace = (((context : Checker.Inference.context).Checker.Inference.environment : Checker.Inference.environment).Checker.Inference.definitions : Checker.Definitions.definitions).Checker.Definitions.namespace in
             Option.value (Option.map (fun t -> List.map (fun c -> ((c : Checker.Definitions.case_info).Checker.Definitions.origin, (c : Checker.Definitions.case_info).Checker.Definitions.definition)) (List.filter (fun c -> ((c : Checker.Definitions.case_info).Checker.Definitions.definition : Parser.case_definition).Parser.name = own) (Collections.Maps.map_get_or_default (((context : Checker.Inference.context).Checker.Inference.environment : Checker.Inference.environment).Checker.Inference.definitions : Checker.Definitions.definitions).Checker.Definitions.cases (t : Checker.Symbols.symbol).Checker.Symbols.name []))) (Checker.Resolution.Lookups.found (Checker.Resolution.Lookups.case_type owner (context : Checker.Inference.context).Checker.Inference.place namespace (Checker.Resolution.Skipping : Checker.Resolution.strictness)))) ~default:[]) else List.map (fun c -> ((c : Checker.Symbols.case_symbol).Checker.Symbols.owner, (c : Checker.Symbols.case_symbol).Checker.Symbols.definition)) (Collections.Maps.map_get_or_default ((context : Checker.Inference.context).Checker.Inference.environment : Checker.Inference.environment).Checker.Inference.cases_by_name own []) in
        match found with
        | [only] -> Some only
        | _ -> None

      let reference (e : Parser.expression) (at : Parser.position) (context : Checker.Inference.context) : string =
        let name = Option.value (dotted e) ~default:"" in
        let namespace = (((context : Checker.Inference.context).Checker.Inference.environment : Checker.Inference.environment).Checker.Inference.definitions : Checker.Definitions.definitions).Checker.Definitions.namespace in
        match Checker.Resolution.Lookups.found (Checker.Inference.Globals.find name context (Checker.Resolution.Skipping : Checker.Resolution.strictness)) with
        | Some f -> (if Checker.Symbols.Signatures.is_function f then "function " else "value ") ^ (f : Checker.Symbols.symbol).Checker.Symbols.name
        | None -> match Checker.Resolution.Lookups.found (Checker.Resolution.Lookups.record name (context : Checker.Inference.context).Checker.Inference.place namespace (Checker.Resolution.Skipping : Checker.Resolution.strictness)) with
            | Some r -> "make " ^ (r : Checker.Symbols.symbol).Checker.Symbols.name ^ "()"
            | None -> match case_named name context with
                | Some found -> let (owner, c) = found in
                    "case " ^ (owner : Checker.Symbols.symbol).Checker.Symbols.name ^ "." ^ (c : Parser.case_definition).Parser.name
                | None -> match Effect.perform (Checker.Diagnostics.Abandoning_abandon (Checker.Inference.Globals.problem context at "this can't be written as a symbol")) with
                    | _ -> (assert false)

