        let namespace = (((context : Checker.Inference.context).Checker.Inference.environment : Checker.Inference.environment).Checker.Inference.definitions : Checker.Definitions.definitions).Checker.Definitions.namespace in
        match Checker.Resolution.Lookups.found (Checker.Resolution.Lookups.record name (context : Checker.Inference.context).Checker.Inference.place namespace (Checker.Resolution.Skipping : Checker.Resolution.strictness)) with
