               ((owner : Checker.Symbols.symbol).Checker.Symbols.name ^ "." ^ (c : Parser.case_definition).Parser.name, (c : Parser.case_definition).Parser.fields)) (case_named name context)

      let rec expression (e : Parser.expression) (context : Checker.Inference.context) : string =
        match e with
        | Parser.IntConstant { at = _; value = n } -> string_of_int n
        | Parser.FloatConstant { at = _; value = x } -> fk_show_float x
        | Parser.BooleanConstant { at = _; value = b } -> string_of_bool b
        | Parser.CharConstant { at = _; value = c } -> ("'" ^ escaped (fk_show_char c) 39) ^ "'"
        | Parser.StringTemplate { at = _; parts = parts } -> ("\"" ^ escaped (String.concat "" (List.map Fun.id (List.map (fun p -> match p with
                   | Parser.TemplateText { text = t } -> t
                   | Parser.Interpolation { expression = _ } -> "") parts))) 34) ^ "\""
        | Parser.Unary { at = _; operator = operator; operand = operand } -> operator ^ expression operand context
        | Parser.ListOf { at = _; items = items } -> bracketed "[" (List.map (fun it -> expression it context) items) "]"
        | Parser.Tuple { at = _; elements = elements } -> bracketed "(" (List.map (fun it -> expression it context) elements) ")"
        | Parser.Name { at = at; name = _ } -> reference e at context
        | Parser.Member { at = at; target = _; name = _ } -> reference e at context
        | Parser.Call { at = at; callee = callee; arguments = arguments; type_arguments = _ } -> (match constructor_of callee context with
             | Some found -> let (name, fields) = found in
                 let written = fields in
                 let positional = Lang.Lists.list_take_while arguments (fun it -> Option.is_none (it : Parser.argument).Parser.name) in
                 let given = List.mapi (fun i f -> Option.map (fun a -> (f : Parser.field).Parser.name ^ " = " ^ expression (a : Parser.argument).Parser.value context) (Lang.Options.option_or_else (List.find_opt (fun it -> (it : Parser.argument).Parser.name = Some (f : Parser.field).Parser.name) arguments) (fun () -> Lang.Lists.list_get_or_none positional i))) written in
                 ("make " ^ name) ^ bracketed "(" (Lang.Lists.list_map_not_null given (fun it -> it)) ")"
             | None -> let why = "only a record or case made of constants can be written as a symbol" in
                 match Effect.perform (Checker.Diagnostics.Abandoning_abandon (Checker.Inference.Globals.problem context at why)) with
                 | _ -> (assert false))
        | _ -> match Effect.perform (Checker.Diagnostics.Abandoning_abandon (Checker.Inference.Globals.problem context (Checker.Symbols.Positions.of_ e) "this can't be written as a symbol")) with
            | _ -> (assert false)

      let rec type_ref_of (v : Parser.annotation_value) : Parser.type_ref option =
        match v with
        | Parser.Reference { at = at; name = name; type_arguments = type_arguments; arguments = None } -> Some (Parser.NamedType { at = at; name = name; arguments = Option.value type_arguments ~default:[] } : Parser.type_ref)
        | Parser.ValueTuple { at = at; items = items } -> let refs = Lang.Lists.list_map_not_null items (fun it -> type_ref_of it) in
            if let fk_arg1 = List.length refs in
            let fk_arg2 = List.length items in
            fk_arg1 = fk_arg2 then Some (Parser.TupleType { at = at; elements = refs } : Parser.type_ref) else None
        | _ -> None

      let rec type_text (t : Checker.Types.type_) : string =
        match Checker.Types.Types.resolved t with
        | Checker.Types.Variable { variable = _ } -> "_"
        | Checker.Types.TupleOf { elements = elements } -> bracketed "(" (List.map (fun it -> type_text it) elements) ")"
        | Checker.Types.Named { name = name; arguments = arguments; region = _ } -> name ^ (if List.is_empty arguments then "" else bracketed "<" (List.map (fun it -> type_text it) arguments) ">")
        | Checker.Types.FunctionOf { parameters = parameters; result = result; effects = _ } -> let fk_arg1 = bracketed "(" (List.map (fun it -> type_text it) parameters) ")" ^ " -> " in
            let fk_arg2 = type_text result in
            fk_arg1 ^ fk_arg2
        | other -> Checker.Types.TypeText.shown other

      let unwritable (v : Parser.annotation_value) (context : Checker.Inference.context) : fk_nothing =
        let at = match v with
          | Parser.Constant { expression = e } -> Checker.Symbols.Positions.of_ e
          | Parser.Reference { at = p; name = _; type_arguments = _; arguments = _ } -> p
          | Parser.ValueList { at = p; items = _ } -> p
          | Parser.ValueTuple { at = p; items = _ } -> p in
        match Effect.perform (Checker.Diagnostics.Abandoning_abandon (Checker.Inference.Globals.problem context at "this can't be written as a symbol")) with
        | _ -> (assert false)

      let rec arguments (a : Parser.annotation) (declaration : Checker.Symbols.symbol) (place : Checker.Resolution.place) (writing : writing) : (string * string) list =
        match ((declaration : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.RecordDefinition { type_parameters = _; fields = fields; private_constructor = _; annotation = _; external_ = _ } -> let metas = Collections.Maps.map_get_or_default (writing : writing).metas (declaration : Checker.Symbols.symbol).Checker.Symbols.name [] in
            let names = List.map (fun it -> (it : Parser.field).Parser.name) fields in
            let vararg = Lang.Options.option_filter (Lang.Lists.list_last_or_none fields) (fun it -> (it : Parser.field).Parser.vararg) in
            let by_name = List.map (fun arg -> (Option.value (arg : Parser.annotation_argument).Parser.name ~default:"", (arg : Parser.annotation_argument).Parser.value)) (List.filter (fun it -> Option.is_some (it : Parser.annotation_argument).Parser.name) (a : Parser.annotation).Parser.arguments) in
            let in_order = List.map (fun it -> (it : Parser.annotation_argument).Parser.value) (Lang.Lists.list_take_while (a : Parser.annotation).Parser.arguments (fun it -> Option.is_none (it : Parser.annotation_argument).Parser.name)) in
            let positional = List.map (fun (v, name) -> (name, v)) (Lang.Lists.list_zip in_order names) in
            let spread = Option.value (Option.map (fun v -> [((v : Parser.field).Parser.name, (Parser.ValueList { at = (a : Parser.annotation).Parser.at; items = List.drop (List.length names - 1) in_order } : Parser.annotation_value))]) (Lang.Options.option_filter vararg (fun v -> Lang.Lists.list_none by_name (fun (n, _) -> n = (v : Parser.field).Parser.name)))) ~default:[] in
            let unspread = List.filter (fun (n, _) -> Lang.Lists.list_none spread (fun (m, _) -> m = n)) positional in
            let given = Collections.Maps.list_tuple_to_map ((unspread @ spread) @ by_name) in
            Lang.Lists.list_map_not_null (Lang.Lists.list_zip names metas) (fun (name, meta) -> Option.map (fun v -> (name, value v meta place writing)) (Collections.Maps.map_get given name))
        | _ -> []
      and value (v : Parser.annotation_value) (meta : Checker.Definitions.meta_type) (place : Checker.Resolution.place) (writing : writing) : string =
        let context = let fk_arg1 = Collections.Maps.empty_map () in
          let fk_arg2 = Checker.Inference.context_default_value_parameters () in
          ({ Checker.Inference.environment = (writing : writing).environment; place = place; type_parameters = fk_arg1; value_parameters = fk_arg2 } : Checker.Inference.context) in
        let namespace = (((writing : writing).environment : Checker.Inference.environment).Checker.Inference.definitions : Checker.Definitions.definitions).Checker.Definitions.namespace in
        let name = match v with
          | Parser.Reference { at = _; name = n; type_arguments = _; arguments = _ } -> n
          | _ -> "" in
        match meta with
        | Checker.Definitions.MetaList { item = item } -> (match v with
             | Parser.ValueList { at = _; items = items } -> bracketed "[" (List.map (fun it -> value it item place writing) items) "]"
             | _ -> expression (Checker.Metadata.AnnotationChecks.expression_of v context) context)
        | Checker.Definitions.MetaTuple { items = item_types } -> (match v with
             | Parser.ValueTuple { at = _; items = items } -> let values = List.map (fun (item, t) -> value item t place writing) (Lang.Lists.list_zip items item_types) in
                 bracketed "(" values ")"
             | _ -> expression (Checker.Metadata.AnnotationChecks.expression_of v context) context)
        | Checker.Definitions.MetaValue { t = _ } -> expression (Checker.Metadata.AnnotationChecks.expression_of v context) context
        | Checker.Definitions.MetaTypeReference -> (match type_ref_of v with
             | Some ref -> let t = Checker.Definitions.Conversion.type_of ref (Checker.Inference.Globals.type_context context) ((writing : writing).environment : Checker.Inference.environment).Checker.Inference.definitions in
                 "type " ^ type_text t
             | None -> match unwritable v context with
                 | _ -> (assert false))
        | Checker.Definitions.MetaSpec -> (match Checker.Resolution.Lookups.found (Checker.Resolution.Lookups.spec name place namespace (Checker.Resolution.Skipping : Checker.Resolution.strictness)) with
             | Some spec -> "spec " ^ (spec : Checker.Symbols.symbol).Checker.Symbols.name
             | None -> match unwritable v context with
                 | _ -> (assert false))
        | Checker.Definitions.MetaFunction -> (match Checker.Resolution.Lookups.found (Checker.Inference.Globals.find name context (Checker.Resolution.Skipping : Checker.Resolution.strictness)) with
             | Some f -> "function " ^ (f : Checker.Symbols.symbol).Checker.Symbols.name
             | None -> match unwritable v context with
                 | _ -> (assert false))
        | Checker.Definitions.MetaModule { spec = _ } -> (match Checker.Resolution.Lookups.found (Checker.Resolution.Lookups.module_named name place namespace (Checker.Resolution.Skipping : Checker.Resolution.strictness)) with
             | Some (Checker.Symbols.DeclaredModule { symbol = m }) -> "module " ^ (m : Checker.Symbols.symbol).Checker.Symbols.name
             | _ -> match unwritable v context with
                 | _ -> (assert false))
        | Checker.Definitions.MetaCase { case_type = case_type } -> (match Checker.Types.Types.resolved case_type with
             | Checker.Types.Named { name = n; arguments = _; region = _ } -> "case " ^ n ^ "." ^ Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".")) ~default:name
             | _ -> match unwritable v context with
                 | _ -> (assert false))
        | Checker.Definitions.MetaField { record = record; field_type = _ } -> (match Checker.Types.Types.resolved record with
             | Checker.Types.Named { name = n; arguments = _; region = _ } -> "field " ^ n ^ "." ^ Option.value (Lang.Lists.list_last_or_none ((fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) name ".")) ~default:name
             | _ -> "field " ^ name)
        | Checker.Definitions.MetaAnnotation { annotation = _ } -> match v with
            | Parser.Reference { at = at; name = n; type_arguments = _; arguments = given } -> (let inner = ({ Parser.at = at; name = n; arguments = Option.value given ~default:[]; type_arguments = [] } : Parser.annotation) in
                 match Checker.Annotations.Annotations.declaration_of inner place namespace with
                 | Some d -> let given = List.map (fun (an, av) -> an ^ " = " ^ av) (arguments inner d place writing) in
                     ("@" ^ (d : Checker.Symbols.symbol).Checker.Symbols.name) ^ bracketed "(" given ")"
                 | None -> match unwritable v context with
                     | _ -> (assert false))
            | _ -> match unwritable v context with
                | _ -> (assert false)

      let annotation (depth : int) (a : Parser.annotation) (place : Checker.Resolution.place) (writing : writing) : string =
        match Checker.Annotations.Annotations.declaration_of a place (((writing : writing).environment : Checker.Inference.environment).Checker.Inference.definitions : Checker.Definitions.definitions).Checker.Definitions.namespace with
        | None -> ""
        | Some declaration -> let given = arguments a declaration place writing in
            let fk_arg1 = line depth ("annotation " ^ (declaration : Checker.Symbols.symbol).Checker.Symbols.name) in
            let fk_arg2 = String.concat "" (List.map Fun.id (List.map (fun (name, v) -> line (depth + 1) ("argument " ^ name ^ " " ^ v)) given)) in
            fk_arg1 ^ fk_arg2

      let header (s : Checker.Symbols.symbol) (type_parameters : string list) (place : Checker.Resolution.place) (writing : writing) : string =
        let fk_arg1 = let fk_arg1 = let fk_arg1 = let fk_arg1 = at 1 ((s : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.at (s : Checker.Symbols.symbol).Checker.Symbols.file in
              let fk_arg2 = if ((s : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.visibility = (Parser.Internal : Parser.visibility) then line 1 "internal" else "" in
              fk_arg1 ^ fk_arg2 in
            let fk_arg2 = if ((s : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.opaque then line 1 "opaque" else "" in
            fk_arg1 ^ fk_arg2 in
          let fk_arg2 = String.concat "" (List.map Fun.id (List.map (fun it -> line 1 ("parameter " ^ it)) type_parameters)) in
          fk_arg1 ^ fk_arg2 in
        let fk_arg2 = String.concat "" (List.map Fun.id (List.map (fun it -> annotation 1 it place writing) ((s : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.annotations)) in
        fk_arg1 ^ fk_arg2

      let rec written (t : Parser.type_ref) (file : Checker.Sources.loaded_file) (type_parameters : string list) (writing : writing) : string =
        let each = fun ts -> List.map (fun it -> written it file type_parameters writing) ts in
        match t with
        | Parser.NamedType { at = at; name = name; arguments = arguments } -> let as_written = if name = "Double" then "Float" else name in
            let full = if List.mem name type_parameters then name else Option.value (Collections.Maps.map_get (writing : writing).names (position_key file at)) ~default:as_written in
            full ^ (if List.is_empty arguments then "" else bracketed "<" (each arguments) ">")
        | Parser.TupleType { at = _; elements = elements } -> bracketed "(" (each elements) ")"
        | Parser.FunctionType { at = _; parameters = parameters; result = result; effects = _ } -> let fk_arg1 = bracketed "(" (each parameters) ")" ^ " -> " in
            let fk_arg2 = String.concat "" (List.map Fun.id (each [result])) in
            fk_arg1 ^ fk_arg2
        | Parser.EffectsType { at = at; effects = _ } -> (match Effect.perform (Checker.Diagnostics.Abandoning_abandon ({ Checker.Diagnostics.file = ((file : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path; at = at; message = "effects can't be written as a symbol's type" } : Checker.Diagnostics.diagnostic)) with
             | _ -> (assert false))
        | Parser.GivenType { at = _; name = name; given = given } -> name ^ " = " ^ written given file type_parameters writing

      let field (depth : int) (f : Parser.field) (file : Checker.Sources.loaded_file) (type_parameters : string list) (place : Checker.Resolution.place) (writing : writing) : string =
        let fk_arg1 = let fk_arg1 = let fk_arg1 = line depth ("field " ^ (f : Parser.field).Parser.name ^ " " ^ written (f : Parser.field).Parser.field_type file type_parameters writing) in
            let fk_arg2 = if (f : Parser.field).Parser.variable then line (depth + 1) "var" else "" in
            fk_arg1 ^ fk_arg2 in
          let fk_arg2 = if Option.is_some (f : Parser.field).Parser.default then line (depth + 1) "default" else "" in
          fk_arg1 ^ fk_arg2 in
        let fk_arg2 = String.concat "" (List.map Fun.id (List.map (fun it -> annotation (depth + 1) it place writing) (f : Parser.field).Parser.annotations)) in
        fk_arg1 ^ fk_arg2

      let case_lines (c : Checker.Symbols.case_symbol) (owner : Checker.Symbols.symbol) (type_parameters : string list) (writing : writing) : string =
        let origin = (c : Checker.Symbols.case_symbol).Checker.Symbols.owner in
        let place = ({ Checker.Resolution.file = (origin : Checker.Symbols.symbol).Checker.Symbols.file; path = (origin : Checker.Symbols.symbol).Checker.Symbols.path } : Checker.Resolution.place) in
        let origin_parameters = match ((origin : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.definition with
          | Parser.CasesDefinition { type_parameters = ps; cases = _; case_refs = _; includes = _ } -> ps
          | _ -> [] in
        let fk_arg1 = let fk_arg1 = let fk_arg1 = let fk_arg1 = line 1 ("case " ^ ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.name) in
              let fk_arg2 = at 2 ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.at (origin : Checker.Symbols.symbol).Checker.Symbols.file in
              fk_arg1 ^ fk_arg2 in
            let fk_arg2 = if (origin : Checker.Symbols.symbol).Checker.Symbols.name <> (owner : Checker.Symbols.symbol).Checker.Symbols.name then line 2 ("from " ^ (origin : Checker.Symbols.symbol).Checker.Symbols.name) else "" in
            fk_arg1 ^ fk_arg2 in
          let fk_arg2 = String.concat "" (List.map Fun.id (List.map (fun it -> annotation 2 it place writing) ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.annotations)) in
          fk_arg1 ^ fk_arg2 in
        let fk_arg2 = String.concat "" (List.map Fun.id (List.map (fun f -> field 2 f (origin : Checker.Symbols.symbol).Checker.Symbols.file (type_parameters @ origin_parameters) place writing) ((c : Checker.Symbols.case_symbol).Checker.Symbols.definition : Parser.case_definition).Parser.fields)) in
        fk_arg1 ^ fk_arg2

      let type_lines (s : Checker.Symbols.symbol) (program : Checker.checked_program) (writing : writing) : string =
        let place = ({ Checker.Resolution.file = (s : Checker.Symbols.symbol).Checker.Symbols.file; path = (s : Checker.Symbols.symbol).Checker.Symbols.path } : Checker.Resolution.place) in
        match ((s : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.definition with
        | Parser.RecordDefinition { type_parameters = type_parameters; fields = fields; private_constructor = private_constructor; annotation = _; external_ = _ } -> let fk_arg1 = let fk_arg1 = let fk_arg1 = line 0 ("record " ^ (s : Checker.Symbols.symbol).Checker.Symbols.name) in
                let fk_arg2 = header s type_parameters place writing in
                fk_arg1 ^ fk_arg2 in
              let fk_arg2 = if private_constructor then line 1 "private-constructor" else "" in
              fk_arg1 ^ fk_arg2 in
            let fk_arg2 = String.concat "" (List.map Fun.id (List.map (fun it -> field 1 it (s : Checker.Symbols.symbol).Checker.Symbols.file type_parameters place writing) fields)) in
            fk_arg1 ^ fk_arg2
        | Parser.CasesDefinition { type_parameters = type_parameters; cases = _; case_refs = _; includes = _ } -> let cases = Option.value (Option.map (fun t -> match t with
                  | Checker.Core.DeclaredCases { case_type = _; type_parameters = _; cases = cs } -> cs
                  | _ -> []) (List.find_opt (fun t -> match t with
                   | Checker.Core.DeclaredCases { case_type = c; type_parameters = _; cases = _ } -> (c : Checker.Symbols.symbol).Checker.Symbols.name = (s : Checker.Symbols.symbol).Checker.Symbols.name
                   | _ -> false) (program : Checker.checked_program).Checker.types)) ~default:[] in
            let fk_arg1 = let fk_arg1 = line 0 ("cases " ^ (s : Checker.Symbols.symbol).Checker.Symbols.name) in
              let fk_arg2 = header s type_parameters place writing in
              fk_arg1 ^ fk_arg2 in
            let fk_arg2 = String.concat "" (List.map Fun.id (List.map (fun c -> case_lines (c : Checker.Core.declared_case).Checker.Core.case s type_parameters writing) cases)) in
            fk_arg1 ^ fk_arg2
        | _ -> ""

      let write (program : Checker.checked_program) (paths : string list) : string =
        match (program : Checker.checked_program).Checker.environment with
        | None -> empty
        | Some environment -> let namespace = ((environment : Checker.Inference.environment).Checker.Inference.definitions : Checker.Definitions.definitions).Checker.Definitions.namespace in
            let files = List.filter (fun f -> Option.value (Option.map (fun it -> List.mem it paths) ((f : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path) ~default:false) ((program : Checker.checked_program).Checker.workspace : Checker.Sources.workspace).Checker.Sources.files in
            let names = Collections.Maps.list_tuple_to_map (List.concat_map (fun f -> Lang.Lists.list_map_not_null (Checker.Resolution.Resolution.resolved_types f namespace ((program : Checker.checked_program).Checker.workspace : Checker.Sources.workspace).Checker.Sources.borrowed) (fun r -> let key = position_key f ((r : Checker.Resolution.resolved_type).Checker.Resolution.written : Checker.Resolution.written_type).Checker.Resolution.at in
                     match (r : Checker.Resolution.resolved_type).Checker.Resolution.meaning with
                     | Checker.Resolution.DeclaredType { symbol = s } -> Some (key, (s : Checker.Symbols.symbol).Checker.Symbols.name)
                     | Checker.Resolution.SpecModuleType { spec = spec } -> Some (key, "module " ^ (spec : Checker.Symbols.symbol).Checker.Symbols.name)
                     | _ -> None)) files) in
            let writing = ({ environment = environment; names = names; metas = Checker.Definitions.MetaTypes.all (environment : Checker.Inference.environment).Checker.Inference.definitions } : writing) in
            let declared = List.filter (fun s -> List.exists (fun it -> ((it : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path = (((s : Checker.Symbols.symbol).Checker.Symbols.file : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path) files && ((s : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.visibility <> (Parser.Private : Parser.visibility)) (Lang.Lists.list_map_not_null (program : Checker.checked_program).Checker.types (fun t -> match t with
                  | Checker.Core.DeclaredRecord { record = s; type_parameters = _; fields = _ } -> (match ((s : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.definition with
                       | Parser.RecordDefinition { type_parameters = _; fields = _; private_constructor = _; annotation = false; external_ = None } -> Some s
                       | _ -> None)
                  | Checker.Core.DeclaredCases { case_type = s; type_parameters = _; cases = _ } -> Some s
                  | _ -> None)) in
            let sorted = Lang.Lists.list_sorted_by declared (fun s -> (Option.value (((s : Checker.Symbols.symbol).Checker.Symbols.file : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path ~default:"", (((s : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.at : Parser.position).Parser.line, (((s : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.at : Parser.position).Parser.column)) in
            empty ^ String.concat "" (List.map Fun.id (List.map (fun s -> type_lines s program writing) sorted))
    end

    module Tests = struct
      type marks = { marker : string; runner : string; fixtures : string option; runner_tests : bool }

      let rec show_marks (v : marks) =
        "Marks(" ^ "marker=" ^ Fun.id v.marker ^ ", runner=" ^ Fun.id v.runner ^ ", fixtures=" ^ fk_show_option Fun.id v.fixtures ^ ", runnerTests=" ^ string_of_bool v.runner_tests ^ ")"

      type test_file = { source : Checker.Sources.source_text; name : string; parsed : Parser.source_file }

      let rec show_test_file (v : test_file) =
        "TestFile(" ^ "source=" ^ Checker.Sources.show_source_text v.source ^ ", name=" ^ Fun.id v.name ^ ", parsed=" ^ Parser.show_source_file v.parsed ^ ")"

      type found = { sections : string list; test : Checker.Symbols.symbol; fixtures : (Parser.position * Checker.Symbols.symbol) list }

      let rec show_found (v : found) =
        "Found(" ^ "sections=" ^ fk_show_list Fun.id v.sections ^ ", test=" ^ Checker.Symbols.show_symbol v.test ^ ", fixtures=" ^ fk_show_list (fun (x0, x1) -> "(" ^ Parser.show_position x0 ^ ", " ^ Checker.Symbols.show_symbol x1 ^ ")") v.fixtures ^ ")"

      let split_name (name : string) (what : string) (example : string) : (string * string, string) result =
        let own = Lang.Strings.string_substring_after_last name "." in
        if not (Lang.Strings.string_contains name ".") || not (Option.value (Option.map (fun it -> Lang.Strings.char_is_upper_case it) ((fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in if n < 0 || i >= String.length s then None else Some (Uchar.to_int (Uchar.utf_decode_uchar (String.get_utf_8_uchar s i)))) own 0)) ~default:false) then Error (what ^ " is named with its package: " ^ example) else Ok (Lang.Strings.string_substring_before_last name ".", own)

      let declares_main (file : Parser.source_file) : bool =
        List.exists (fun d -> (d : Parser.declaration).Parser.name = "main" && (match (d : Parser.declaration).Parser.definition with
            | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = _; operator = _ } -> true
            | _ -> false)) (file : Parser.source_file).Parser.declarations

      let rec has_tests (declarations : Parser.declaration list) (marker : string) : bool =
        List.exists (fun d -> match (d : Parser.declaration).Parser.definition with
           | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = _; operator = _ } -> List.exists (fun it -> (it : Parser.annotation).Parser.name = marker) (d : Parser.declaration).Parser.annotations
           | Parser.ModuleDefinition { declarations = inner; spec = _; parameters = _; application = _; type_parameters = _ } -> has_tests inner marker
           | _ -> false) declarations

      let rec walked (declarations : Parser.declaration list) (sections : string list) (marker_name : string) (marker : string) (imported : bool) (at : Parser.position -> string -> Checker.Diagnostics.diagnostic) : string list * Checker.Diagnostics.diagnostic list =
        let each = List.map (fun d -> let marked = List.exists (fun it -> (it : Parser.annotation).Parser.name = marker_name) (d : Parser.declaration).Parser.annotations in
             match (d : Parser.declaration).Parser.definition with
             | Parser.ModuleDefinition { declarations = inner; spec = _; parameters = _; application = _; type_parameters = _ } -> let (named, problems) = walked inner (sections @ [(d : Parser.declaration).Parser.name]) marker_name marker imported at in
                 let hidden = if (d : Parser.declaration).Parser.visibility = (Parser.Private : Parser.visibility) && has_tests inner marker_name then [at (d : Parser.declaration).Parser.at "a section is run from outside its file, so it can't be private"] else [] in
                 (named, hidden @ problems)
             | Parser.FunctionDefinition { type_parameters = type_parameters; receiver = receiver; parameters = parameters; result = _; body = _; external_ = _; operator = _ } when marked -> let problem = if not imported then Some ("a test is marked with " ^ marker ^ ": import " ^ marker) else (match parameters with
                      | None -> Some ("a test is a function, run as " ^ (d : Parser.declaration).Parser.name ^ "(): write " ^ (d : Parser.declaration).Parser.name ^ "() = ...")
                      | Some ps -> if (Option.is_some receiver || Lang.Lists.list_is_not_empty ps) || Lang.Lists.list_is_not_empty type_parameters then Some ("a test takes no parameters, as it's run as " ^ (d : Parser.declaration).Parser.name ^ "()") else if (d : Parser.declaration).Parser.visibility = (Parser.Private : Parser.visibility) then Some "a test is run from outside its file, so it can't be private" else None) in
                 let fk_arg1 = [String.concat "." (List.map Fun.id (sections @ [(d : Parser.declaration).Parser.name]))] in
                 let fk_arg2 = Option.to_list (Option.map (fun it -> at (d : Parser.declaration).Parser.at it) problem) in
                 (fk_arg1, fk_arg2)
             | _ -> ([], [])) declarations in
        let fk_arg1 = List.concat_map (fun (named, _) -> named) each in
        let fk_arg2 = List.concat_map (fun (_, problems) -> problems) each in
        (fk_arg1, fk_arg2)

      let written (files : test_file list) (marks : marks) : string list * Checker.Diagnostics.diagnostic list =
        let marker_package = Lang.Strings.string_substring_before_last (marks : marks).marker "." in
        let marker_name = Lang.Strings.string_substring_after_last (marks : marks).marker "." in
        let runner_package = Lang.Strings.string_substring_before_last (marks : marks).runner "." in
        let each = List.map (fun f -> let at = fun p message -> ({ Checker.Diagnostics.file = ((f : test_file).source : Checker.Sources.source_text).Checker.Sources.path; at = p; message = message } : Checker.Diagnostics.diagnostic) in
             let importing = List.map (fun i -> at (i : Parser.import).Parser.at ((runner_package ^ " runs the tests, so they can't use it: ") ^ "a test uses what it's written with, as " ^ (marks : marks).marker)) (List.filter (fun i -> let path = String.concat "." (List.map Fun.id (i : Parser.import).Parser.path) in
                   not (marks : marks).runner_tests && (path = runner_package || String.starts_with ~prefix:(runner_package ^ ".") path)) ((f : test_file).parsed : Parser.source_file).Parser.imports) in
             let imported = List.exists (fun i -> let named = if (i : Parser.import).Parser.wildcard then marker_package else (marks : marks).marker in
                  Option.is_none (i : Parser.import).Parser.alias && String.concat "." (List.map Fun.id (i : Parser.import).Parser.path) = named) ((f : test_file).parsed : Parser.source_file).Parser.imports in
             let (named, problems) = walked ((f : test_file).parsed : Parser.source_file).Parser.declarations [] marker_name (marks : marks).marker imported at in
             (named, importing @ problems)) (List.filter (fun it -> not (declares_main (it : test_file).parsed)) files) in
        let fk_arg1 = List.concat_map (fun (named, _) -> named) each in
        let fk_arg2 = List.concat_map (fun (_, problems) -> problems) each in
        (fk_arg1, fk_arg2)

      let stub (marks : marks) (named : string list) : string =
        let module_ = Lang.Strings.string_substring_after_last (marks : marks).runner "." in
        let calls = String.concat "" (List.map Fun.id (List.map (fun it -> "    " ^ it ^ "()\n") named)) in
        ("import " ^ (marks : marks).runner ^ "\n\nmain(args: List<String>) = {\n  named = () -> {\n" ^ calls ^ "  }\n") ^ "  runs = " ^ module_ ^ ".test\n  Unit\n}\n"

      let effective (enclosing : Parser.declaration list) (d : Parser.declaration) (file : Checker.Sources.loaded_file) (sections : string list) (namespace : Checker.Resolution.namespace) : (Parser.annotation * Checker.Symbols.symbol option) list =
        let resolved_at = fun annotations place -> List.map (fun a -> (a, Checker.Annotations.Annotations.declaration_of a place namespace)) annotations in
        let levels = let fk_arg1 = List.mapi (fun i m -> List.filter (fun (_, s) -> Option.value (Option.map (fun it -> Checker.Annotations.Annotations.is_marked it "fckt.lang.Propagates" namespace) s) ~default:false) (resolved_at (m : Parser.declaration).Parser.annotations ({ Checker.Resolution.file = file; path = (file : Checker.Sources.loaded_file).Checker.Sources.package @ List.take i sections } : Checker.Resolution.place))) enclosing in
          let fk_arg2 = [resolved_at (d : Parser.declaration).Parser.annotations ({ Checker.Resolution.file = file; path = (file : Checker.Sources.loaded_file).Checker.Sources.package @ sections } : Checker.Resolution.place)] in
          fk_arg1 @ fk_arg2 in
        let none = [] in
        List.fold_left (fun result level -> List.fold_left (fun kept entry -> let (_, s) = entry in
              let replaced = match s with
                | Some t when not (Checker.Annotations.Annotations.is_marked t Checker.Annotations.Annotations.repeatable namespace) -> List.filter (fun (_, other) -> Option.map (fun it -> (it : Checker.Symbols.symbol).Checker.Symbols.name) other <> Some (t : Checker.Symbols.symbol).Checker.Symbols.name) kept
                | _ -> kept in
              replaced @ [entry]) result level) none levels

      let value_at (v : Parser.annotation_value) : Parser.position =
        match v with
        | Parser.Constant { expression = e } -> Checker.Symbols.Positions.of_ e
        | Parser.Reference { at = at; name = _; type_arguments = _; arguments = _ } -> at
        | Parser.ValueList { at = at; items = _ } -> at
        | Parser.ValueTuple { at = at; items = _ } -> at

      let fixtures_of (annotations : (Parser.annotation * Checker.Symbols.symbol option) list) (place : Checker.Resolution.place) (environment : Checker.Inference.environment) (marks : marks) : (Parser.position * Checker.Symbols.symbol) list * Checker.Diagnostics.diagnostic list =
        let path = (((place : Checker.Resolution.place).Checker.Resolution.file : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path in
        let listing = List.filter (fun (_, s) -> Option.is_some (marks : marks).fixtures && Option.map (fun it -> (it : Checker.Symbols.symbol).Checker.Symbols.name) s = (marks : marks).fixtures) annotations in
        let values = List.concat_map (fun (a, _) -> List.concat_map (fun argument -> match (argument : Parser.annotation_argument).Parser.value with
                | Parser.ValueList { at = _; items = items } -> items
                | other -> [other]) (a : Parser.annotation).Parser.arguments) listing in
        let each = List.map (fun v -> match v with
             | Parser.Reference { at = at; name = name; type_arguments = _; arguments = _ } -> (match Checker.Resolution.Lookups.found (Checker.Inference.Globals.find name (let fk_arg1 = Collections.Maps.empty_map () in
                    let fk_arg2 = Checker.Inference.context_default_value_parameters () in
                    ({ Checker.Inference.environment = environment; place = place; type_parameters = fk_arg1; value_parameters = fk_arg2 } : Checker.Inference.context)) (Checker.Resolution.Skipping : Checker.Resolution.strictness)) with
                  | Some f -> let own = Lowering.Naming.own_name f in
                      let problem = if ((f : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.visibility = (Parser.Private : Parser.visibility) then Some (own ^ " runs a test from outside its file, so it can't be private") else if Checker.Symbols.Signatures.is_extension f || Option.map (fun it -> List.length it) (Checker.Symbols.Signatures.written_parameters_of f) <> Some 1 then Some ("a fixture takes what it runs, as its one parameter: " ^ own ^ "<A>(test: () -> A): A") else None in
                      ([(at, f)], Option.to_list (Option.map (fun it -> ({ Checker.Diagnostics.file = path; at = at; message = it } : Checker.Diagnostics.diagnostic)) problem))
                  | None -> ([], [({ Checker.Diagnostics.file = path; at = at; message = "a fixture is a function, by name" } : Checker.Diagnostics.diagnostic)]))
             | _ -> ([], [({ Checker.Diagnostics.file = path; at = value_at v; message = "a fixture is a function, by name" } : Checker.Diagnostics.diagnostic)])) values in
        let fk_arg1 = List.concat_map (fun (found, _) -> found) each in
        let fk_arg2 = List.concat_map (fun (_, problems) -> problems) each in
        (fk_arg1, fk_arg2)

      let rec found_in (file : Checker.Sources.loaded_file) (declarations : Parser.declaration list) (enclosing : Parser.declaration list) (sections : string list) (program : Checker.checked_program) (environment : Checker.Inference.environment) (marks : marks) : found list * Checker.Diagnostics.diagnostic list =
        let namespace = ((environment : Checker.Inference.environment).Checker.Inference.definitions : Checker.Definitions.definitions).Checker.Definitions.namespace in
        let each = List.map (fun d -> match (d : Parser.declaration).Parser.definition with
             | Parser.ModuleDefinition { declarations = inner; spec = _; parameters = _; application = _; type_parameters = _ } -> found_in file inner (enclosing @ [d]) (sections @ [(d : Parser.declaration).Parser.name]) program environment marks
             | Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = _; operator = _ } -> (let place = ({ Checker.Resolution.file = file; path = (file : Checker.Sources.loaded_file).Checker.Sources.package @ sections } : Checker.Resolution.place) in
                  let marked = effective enclosing d file sections namespace in
                  let test = List.find_opt (fun f -> ((((f : Checker.Inference.checked_function).Checker.Inference.function_ : Checker.Symbols.symbol).Checker.Symbols.file : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path = ((file : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path && (((f : Checker.Inference.checked_function).Checker.Inference.function_ : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.at = (d : Parser.declaration).Parser.at) (program : Checker.checked_program).Checker.functions in
                  match test with
                  | Some t when List.exists (fun (_, s) -> Option.map (fun it -> (it : Checker.Symbols.symbol).Checker.Symbols.name) s = Some (marks : marks).marker) marked -> let (fixtures, problems) = fixtures_of marked place environment marks in
                      ([({ sections = sections; test = (t : Checker.Inference.checked_function).Checker.Inference.function_; fixtures = fixtures } : found)], problems)
                  | _ -> ([], []))
             | _ -> ([], [])) declarations in
        let fk_arg1 = List.concat_map (fun (found, _) -> found) each in
        let fk_arg2 = List.concat_map (fun (_, problems) -> problems) each in
        (fk_arg1, fk_arg2)

      let type_of (program : Checker.checked_program) (name : string) : Checker.Types.type_ option =
        Option.map (fun it -> ((it : Checker.Inference.checked_function).Checker.Inference.scheme : Checker.Types.scheme).Checker.Types.template) (List.find_opt (fun it -> ((it : Checker.Inference.checked_function).Checker.Inference.function_ : Checker.Symbols.symbol).Checker.Symbols.name = name) (program : Checker.checked_program).Checker.functions)

      let effects_of (t : Checker.Types.type_) : string list =
        match t with
        | Checker.Types.FunctionOf { parameters = _; result = _; effects = row } -> List.map (fun it -> (it : Checker.Types.effect_label).Checker.Types.name) (row : Checker.Types.row).Checker.Types.labels
        | _ -> []

      let last_parameter_effects (t : Checker.Types.type_) : string list =
        match t with
        | Checker.Types.FunctionOf { parameters = parameters; result = _; effects = _ } -> Option.value (Option.map (fun it -> effects_of it) (Lang.Lists.list_last_or_none parameters)) ~default:[]
        | _ -> []

      let shown (names : string list) : string =
        String.concat " " (List.map Fun.id (List.map (fun it -> "@" ^ Lang.Strings.string_substring_after_last it ".") (Lang.Lists.list_sorted names)))

      let first_parameter_effects (t : Checker.Types.type_) : string list =
        match t with
        | Checker.Types.FunctionOf { parameters = first :: _; result = _; effects = _ } -> effects_of first
        | _ -> []

      let unhandled_by (program : Checker.checked_program) (marks : marks) (t : found) : Checker.Diagnostics.diagnostic list =
        let needs = List.map (fun it -> ((it : Checker.Core.declared_effect).Checker.Core.effect_ : Checker.Symbols.symbol).Checker.Symbols.name) (List.filter (fun it -> Lang.Lists.list_is_not_empty (it : Checker.Core.declared_effect).Checker.Core.operations) (program : Checker.checked_program).Checker.effects) in
        let runs = type_of program ((marks : marks).runner ^ ".test") in
        let defaults = List.map (fun it -> ((it : Checker.Inference.default_handler).Checker.Inference.effect_ : Checker.Symbols.symbol).Checker.Symbols.name) (program : Checker.checked_program).Checker.default_handlers in
        let start = defaults @ Option.value (Option.map (fun it -> last_parameter_effects it) runs) ~default:[] in
        let (handled, fixture_problems) = List.fold_left (fun state fixture -> let (handled_so_far, problems) = state in
             let (at, f) = fixture in
             let fixture_type = type_of program (f : Checker.Symbols.symbol).Checker.Symbols.name in
             let missing = Lang.Lists.list_distinct (List.filter (fun it -> List.mem it needs && not (List.mem it handled_so_far)) (Option.value (Option.map (fun it -> effects_of it) fixture_type) ~default:[])) in
             let problem = if List.is_empty missing then [] else [({ Checker.Diagnostics.file = ((((t : found).test : Checker.Symbols.symbol).Checker.Symbols.file : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path; at = at; message = (let fk_arg1 = Lowering.Naming.own_name f in
                  let fk_arg2 = shown missing in
                  "the fixture " ^ fk_arg1 ^ " does " ^ fk_arg2 ^ ", which nothing it runs in ") ^ "handles: list a fixture that does before it" } : Checker.Diagnostics.diagnostic)] in
             let given = Option.value (Option.map (fun it -> first_parameter_effects it) fixture_type) ~default:[] in
             (handled_so_far @ given, problems @ problem)) (start, []) (t : found).fixtures in
        let missing = Lang.Lists.list_distinct (List.filter (fun it -> List.mem it needs && not (List.mem it handled)) (Option.value (Option.map (fun it -> effects_of it) (type_of program ((t : found).test : Checker.Symbols.symbol).Checker.Symbols.name)) ~default:[])) in
        let fixture_names = String.concat ", " (List.map Fun.id (List.map (fun (_, f) -> Lowering.Naming.own_name f) (t : found).fixtures)) in
        let by = if List.is_empty (t : found).fixtures then "nothing it runs in handles" else "neither the runner nor its fixtures, " ^ fixture_names ^ ", handle" in
        let test_problem = if List.is_empty missing then [] else [({ Checker.Diagnostics.file = ((((t : found).test : Checker.Symbols.symbol).Checker.Symbols.file : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path; at = (((t : found).test : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.at; message = (let fk_arg1 = Lowering.Naming.own_name (t : found).test in
             let fk_arg2 = shown missing in
             "'" ^ fk_arg1 ^ "' does " ^ fk_arg2 ^ ", which " ^ by ^ ": ") ^ "list a fixture that does, as @Fixtures(...)" } : Checker.Diagnostics.diagnostic)] in
        fixture_problems @ test_problem

      let rec effects_in (t : Checker.Types.type_) : string list =
        match t with
        | Checker.Types.FunctionOf { parameters = parameters; result = result; effects = row } -> let fk_arg1 = let fk_arg1 = List.filter (fun it -> not (Lang.Strings.string_contains it " ")) (List.map (fun it -> (it : Checker.Types.effect_label).Checker.Types.name) (row : Checker.Types.row).Checker.Types.labels) in
              let fk_arg2 = List.concat_map (fun it -> effects_in it) parameters in
              fk_arg1 @ fk_arg2 in
            let fk_arg2 = effects_in result in
            fk_arg1 @ fk_arg2
        | Checker.Types.Named { name = _; arguments = arguments; region = _ } -> List.concat_map (fun it -> effects_in it) arguments
        | Checker.Types.Abstract { name = _; arguments = arguments } -> List.concat_map (fun it -> effects_in it) arguments
        | Checker.Types.TupleOf { elements = elements } -> List.concat_map (fun it -> effects_in it) elements
        | _ -> []

      let string (text : string) : string =
        ("\"" ^ Lang.Strings.string_replace (Lang.Strings.string_replace (Lang.Strings.string_replace text "\\" "\\\\") "\"" "\\\"") "$" "\\$") ^ "\""

      let planned (program : Checker.checked_program) (marks : marks) (found : (string * found list) list) : string =
        let module_ = Lang.Strings.string_substring_after_last (marks : marks).runner "." in
        let files = Lang.Lists.list_sorted_by (List.filter (fun (_, tests) -> Lang.Lists.list_is_not_empty tests) found) (fun (file, _) -> file) in
        let suites = List.map (fun (file, tests) -> let lines = List.map (fun t -> let in_fixtures = fun inner -> List.fold_left (fun rest fixture -> let (_, f) = fixture in
                         (f : Checker.Symbols.symbol).Checker.Symbols.name ^ "(() -> " ^ rest ^ ")") inner (List.rev (t : found).fixtures) in
                  let t0 = type_of program ((t : found).test : Checker.Symbols.symbol).Checker.Symbols.name in
                  let effects = List.map (fun it -> string it) (Lang.Lists.list_sorted (Lang.Lists.list_distinct (Option.value (Option.map (fun it -> effects_in it) t0) ~default:[]))) in
                  let sections = String.concat ", " (List.map Fun.id (List.map (fun it -> string it) (t : found).sections)) in
                  let own = string (Lowering.Naming.own_name (t : found).test) in
                  let id = let fk_arg1 = string file ^ ", [" ^ sections ^ "], " ^ own ^ ", " ^ string_of_int ((((t : found).test : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.at : Parser.position).Parser.line ^ ", " in
                    let fk_arg2 = "[" ^ String.concat ", " (List.map Fun.id effects) ^ "]" in
                    fk_arg1 ^ fk_arg2 in
                  let call = ((t : found).test : Checker.Symbols.symbol).Checker.Symbols.name in
                  let gives_unit = match t0 with
                    | Some (Checker.Types.FunctionOf { parameters = _; result = result; effects = _ }) -> result = Checker.Types.Types.unit
                    | _ -> true in
                  if gives_unit then "    " ^ module_ ^ ".test(" ^ id ^ ", () -> " ^ in_fixtures (call ^ "()") ^ "),\n" else "    " ^ module_ ^ ".cases(" ^ id ^ ", () -> " ^ call ^ "(), check -> " ^ in_fixtures "check()" ^ "),\n") (Lang.Lists.list_sorted_by tests (fun it -> ((((it : found).test : Checker.Symbols.symbol).Checker.Symbols.declaration : Parser.declaration).Parser.at : Parser.position).Parser.line)) in
             (let fk_arg1 = "  " ^ module_ ^ ".suite(" ^ string file ^ ", [\n" in
              let fk_arg2 = String.concat "" (List.map Fun.id lines) in
              fk_arg1 ^ fk_arg2) ^ "  ]),\n") files in
        (("import " ^ (marks : marks).runner ^ "\n\nmain(args: List<String>) = " ^ module_ ^ ".main(args, " ^ module_ ^ ".plan([\n") ^ String.concat "" (List.map Fun.id suites)) ^ "]))\n"

      let plan (program : Checker.checked_program) (files : test_file list) (marks : marks) : (string, Checker.Diagnostics.diagnostic list) result =
        match (program : Checker.checked_program).Checker.environment with
        | None -> Error []
        | Some environment -> let paths = List.map (fun it -> ((it : test_file).source : Checker.Sources.source_text).Checker.Sources.path) files in
            let test_files = List.filter (fun f -> List.mem ((f : Checker.Sources.loaded_file).Checker.Sources.source : Checker.Sources.source_text).Checker.Sources.path paths) ((program : Checker.checked_program).Checker.workspace : Checker.Sources.workspace).Checker.Sources.files in
            let each = List.map (fun f -> found_in f (f : Checker.Sources.loaded_file).Checker.Sources.declarations [] [] program environment marks) test_files in
            let problems = List.concat_map (fun (_, problems) -> problems) each in
            let found = List.map (fun (f, entry) -> let (tests, _) = entry in
                 (Checker.Sources.Loader.file_name (f : Checker.Sources.loaded_file).Checker.Sources.source ^ ".fk", tests)) (Lang.Lists.list_zip test_files each) in
            if Lang.Lists.list_is_not_empty problems then Error problems else (let unhandled = List.concat_map (fun (_, tests) -> List.concat_map (fun t -> unhandled_by program marks t) tests) found in
               if Lang.Lists.list_is_not_empty unhandled then Error unhandled else Ok (planned program marks found))
    end
  end
end

let version =
  "0.1.0-SNAPSHOT"

let build () : string =
  (fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in String.sub s 0 (at 0 n)) ((fun t -> Digest.to_hex (Digest.string t)) (Fckt.Io.Files.path_read_bytes (Effect.perform (Fckt.Io.Process_executable ())))) 12

let failing (problems : string list) : unit =
  List.iter (fun it -> Fckt.Io.Channels.print_error it) problems;
  match Effect.perform (Fckt.Io.Process_exit 1) with
  | _ -> (assert false)

let shown (e : Fckt.Checker.Diagnostics.diagnostic) (file : string) : string =
  Option.value (e : Fckt.Checker.Diagnostics.diagnostic).Fckt.Checker.Diagnostics.file ~default:file ^ ":" ^ string_of_int ((e : Fckt.Checker.Diagnostics.diagnostic).Fckt.Checker.Diagnostics.at : Fckt.Parser.position).Fckt.Parser.line ^ ":" ^ string_of_int ((e : Fckt.Checker.Diagnostics.diagnostic).Fckt.Checker.Diagnostics.at : Fckt.Parser.position).Fckt.Parser.column ^ ": error: " ^ (e : Fckt.Checker.Diagnostics.diagnostic).Fckt.Checker.Diagnostics.message

let checked_program (entry : Fckt.Checker.Sources.source_text) (file : string) (tree : Fckt.Checker.Sources.source_tree) (use : Fckt.Checker.checked_program -> unit) : unit =
  let (program, errors) = Fckt.Checker.Checker.check entry tree true in
  match (program, errors) with
  | (Some p, []) -> use p
  | _ -> failing (List.map (fun it -> shown it file) errors)

let checked (entry : Fckt.Checker.Sources.source_text) (file : string) (tree : Fckt.Checker.Sources.source_tree) (whole : bool) (write : string -> unit) : unit =
  checked_program entry file tree (fun p -> match Fckt.Effects.Failure.attempt (fun () -> Fckt.Lowering.Programs.ocaml p whole) with
     | Ok items -> write (Fckt.Ocaml.Printer.file items)
     | Error why -> failing ["can't lower " ^ why])

let write_output (output : string) (ml : string) : unit =
  if output = "-" then Effect.perform (Fckt.Io.Console_print ml) else Fckt.Io.Files.path_write_text (Fckt.Io.Paths.path output) ml

let core_unit (out : string) : unit =
  let entry = let fk_arg1 = Fckt.Checker.Sources.source_text_default_compiled_in () in
    let fk_arg2 = Fckt.Checker.Sources.source_text_default_interface () in
    let fk_arg3 = Fckt.Checker.Sources.source_text_default_trusted () in
    ({ Fckt.Checker.Sources.path = None; project = (Fckt.Checker.Sources.ProgramProject : Fckt.Checker.Sources.project); text = ""; compiled_in = fk_arg1; interface = fk_arg2; trusted = fk_arg3 } : Fckt.Checker.Sources.source_text) in
  checked entry "the core" (let fk_arg1 = Fckt.Compiler.Sources.merged (Fckt.Compiler.Sources.core (Fckt.Compiler.Sources.home ())) in
   let fk_arg2 = Fckt.Checker.Sources.source_tree_default_imports () in
   ({ Fckt.Checker.Sources.packages = fk_arg1; imports = fk_arg2 } : Fckt.Checker.Sources.source_tree)) true (fun ml -> write_output out ml)

let rec sources_in (p : Fckt.Io.path) (top : bool) : Fckt.Io.path list =
  if not (Fckt.Io.Files.path_is_directory p) then if top || Fckt.Io.Paths.path_extension p = "fk" then [p] else [] else if not top && Fckt.Io.Paths.path_name p = "build" then [] else List.concat_map (fun it -> sources_in it false) (Fckt.Io.Files.path_list_files p)

let laid_out (paths : string list) (checking : bool) : unit =
  let files = Fckt.Lang.Lists.list_sorted_by (List.concat_map (fun p -> sources_in (Fckt.Io.Paths.path p) true) paths) (fun it -> (it : Fckt.Io.path).Fckt.Io.value) in
  let unformatted = List.concat_map (fun file -> let source = Fckt.Io.Files.path_read_text file in
       if checking then List.map (fun line -> ((file : Fckt.Io.path).Fckt.Io.value ^ ":" ^ string_of_int line ^ ": wider than " ^ string_of_int Fckt.Compiler.Layout.width ^ " columns: ") ^ "put each item of the list on a line of its own, or run fckt --format") (Fckt.Compiler.Layout.unformatted source) else (let laid = Fckt.Compiler.Layout.formatted source in
          if laid <> source then Fckt.Io.Files.path_write_text file laid else ();
          [])) files in
  if Fckt.Lang.Lists.list_is_not_empty unformatted then failing unformatted else ()

let compile (file : string) (out : string) (folders : string list) (whole : bool) : unit =
  let own = List.concat_map (fun folder -> let fk_arg1 = Fckt.Io.Paths.path folder in
       let fk_arg2 = Fckt.Compiler.Sources.packages_in_default_compiled_in () in
       let fk_arg3 = Fckt.Compiler.Sources.packages_in_default_interface () in
       Fckt.Compiler.Sources.packages_in fk_arg1 [] (Fckt.Checker.Sources.ProgramProject : Fckt.Checker.Sources.project) (folder ^ "/") fk_arg2 fk_arg3) folders in
  let tree = let fk_arg1 = Fckt.Compiler.Sources.merged ((let fk_arg1 = Fckt.Compiler.Sources.core (Fckt.Io.Paths.path ".") in
        let fk_arg2 = Fckt.Compiler.Sources.standard (Fckt.Io.Paths.path ".") in
        fk_arg1 @ fk_arg2) @ own) in
    let fk_arg2 = Fckt.Checker.Sources.source_tree_default_imports () in
    ({ Fckt.Checker.Sources.packages = fk_arg1; imports = fk_arg2 } : Fckt.Checker.Sources.source_tree) in
  let entry = let fk_arg1 = Fckt.Io.Files.path_read_text (Fckt.Io.Paths.path file) in
    let fk_arg2 = Fckt.Checker.Sources.source_text_default_compiled_in () in
    let fk_arg3 = Fckt.Checker.Sources.source_text_default_interface () in
    let fk_arg4 = Fckt.Checker.Sources.source_text_default_trusted () in
    ({ Fckt.Checker.Sources.path = None; project = (Fckt.Checker.Sources.ProgramProject : Fckt.Checker.Sources.project); text = fk_arg1; compiled_in = fk_arg2; interface = fk_arg3; trusted = fk_arg4 } : Fckt.Checker.Sources.source_text) in
  checked entry file tree whole (fun ml -> Fckt.Io.Files.path_write_text (Fckt.Io.Paths.path out) ml)

let rec options (args : string list) (o : options) : options option =
  match args with
  | [] -> Some o
  | "-o" :: out :: rest -> options rest { (o : options) with output = Some out }
  | "-I" :: dir :: rest -> options rest { (o : options) with own = (o : options).own @ [dir] }
  | "--other-project" :: dir :: rest -> options rest { (o : options) with others = (o : options).others @ [dir] }
  | "-L" :: dir :: rest -> options rest { (o : options) with libraries = (o : options).libraries @ [dir] }
  | "--no-std" :: rest -> options rest { (o : options) with no_std = true }
  | "--separate" :: rest -> options rest { (o : options) with separate = true }
  | "--library" :: dir :: rest -> options rest { (o : options) with library = Some dir }
  | "--symbols" :: out :: rest -> options rest { (o : options) with symbols = Some out }
  | "--import" :: name :: rest -> options rest { (o : options) with imports = (o : options).imports @ [name] }
  | "--test" :: dir :: rest -> options rest { (o : options) with test = Some dir }
  | "--marker" :: name :: rest -> options rest { (o : options) with marker = Some name }
  | "--runner" :: name :: rest -> options rest { (o : options) with runner = Some name }
  | "--fixtures" :: name :: rest -> options rest { (o : options) with fixtures = Some name }
  | "--runner-tests" :: rest -> options rest { (o : options) with runner_tests = true }
  | arg :: rest when not (String.starts_with ~prefix:"-" arg) -> options rest { (o : options) with inputs = (o : options).inputs @ [arg] }
  | _ -> None

let options_default_test () : string option =
  None

let options_default_marker () : string option =
  None

let options_default_runner () : string option =
  None

let options_default_fixtures () : string option =
  None

let options_default_runner_tests () : bool =
  false

let options_default_imports () : string list =
  []

let options_default_symbols () : string option =
  None

let own_packages (o : options) : (string list * Fckt.Checker.Sources.source_text list) list =
  List.concat_map (fun dir -> let fk_arg1 = Fckt.Io.Paths.path dir in
     let fk_arg2 = Fckt.Compiler.Sources.packages_in_default_compiled_in () in
     let fk_arg3 = Fckt.Compiler.Sources.packages_in_default_interface () in
     Fckt.Compiler.Sources.packages_in fk_arg1 [] (Fckt.Checker.Sources.ProgramProject : Fckt.Checker.Sources.project) (dir ^ "/") fk_arg2 fk_arg3) (o : options).own

let tree (o : options) (own : (string list * Fckt.Checker.Sources.source_text list) list) : Fckt.Checker.Sources.source_tree =
  let home = Fckt.Compiler.Sources.home () in
  let others = List.concat_map (fun dir -> let fk_arg1 = Fckt.Io.Paths.path dir in
       let fk_arg2 = (Fckt.Checker.Sources.OtherProject { root = (Fckt.Io.Files.path_canonical (Fckt.Io.Paths.path dir) : Fckt.Io.path).Fckt.Io.value } : Fckt.Checker.Sources.project) in
       let fk_arg3 = Fckt.Compiler.Sources.packages_in_default_compiled_in () in
       let fk_arg4 = Fckt.Compiler.Sources.packages_in_default_interface () in
       Fckt.Compiler.Sources.packages_in fk_arg1 [] fk_arg2 (dir ^ "/") fk_arg3 fk_arg4) (o : options).others in
  let libraries = List.concat_map (fun dir -> Fckt.Compiler.Sources.interfaces_in (Fckt.Io.Paths.path dir)) (o : options).libraries in
  ({ Fckt.Checker.Sources.packages = Fckt.Compiler.Sources.merged ((((let fk_arg1 = Fckt.Compiler.Sources.core home in
      let fk_arg2 = if (o : options).no_std then [] else Fckt.Compiler.Sources.standard home in
      fk_arg1 @ fk_arg2) @ own) @ others) @ libraries); imports = (o : options).imports } : Fckt.Checker.Sources.source_tree)

let tests (o : options) (dir : string) : unit =
  let named = fun option what example -> Option.map (fun name -> match Fckt.Compiler.Tests.split_name name what example with
         | Ok _ -> name
         | Error why -> failing ["error: " ^ why];
             name) option in
  let marks = let fk_arg1 = Option.value (named (o : options).marker "what marks a test" "uk.m4xy.fktests.api.Test") ~default:"" in
    let fk_arg2 = Option.value (named (o : options).runner "a test runner" "uk.m4xy.fktests.runner.Runner") ~default:"" in
    let fk_arg3 = named (o : options).fixtures "what lists a test's fixtures" "uk.m4xy.fktests.api.Fixtures" in
    ({ Fckt.Compiler.Tests.marker = fk_arg1; runner = fk_arg2; fixtures = fk_arg3; runner_tests = (o : options).runner_tests } : Fckt.Compiler.Tests.marks) in
  if Option.is_none (o : options).marker || Option.is_none (o : options).runner then failing ["fckt: --test needs --marker and --runner"] else ();
  let given = own_packages o in
  let own = if List.mem dir (o : options).own then given else given @ (let fk_arg1 = Fckt.Io.Paths.path dir in
       let fk_arg2 = Fckt.Compiler.Sources.packages_in_default_compiled_in () in
       let fk_arg3 = Fckt.Compiler.Sources.packages_in_default_interface () in
       Fckt.Compiler.Sources.packages_in fk_arg1 [] (Fckt.Checker.Sources.ProgramProject : Fckt.Checker.Sources.project) (dir ^ "/") fk_arg2 fk_arg3) in
  let outermost = List.concat_map (fun (_, sources) -> sources) (List.filter (fun (p, _) -> List.is_empty p) own) in
  let files = Fckt.Lang.Lists.list_sorted_by (Fckt.Lang.Lists.list_map_not_null outermost (fun source -> let name = Fckt.Lang.Strings.string_remove_prefix (Option.value (source : Fckt.Checker.Sources.source_text).Fckt.Checker.Sources.path ~default:"") (dir ^ "/") in
        let lower_case = Option.value (Option.map (fun it -> Fckt.Lang.Strings.char_is_lower_case it) ((fun s n -> let rec at i n = if n <= 0 || i >= String.length s then i else at (i + Uchar.utf_decode_length (String.get_utf_8_uchar s i)) (n - 1) in let i = at 0 n in if n < 0 || i >= String.length s then None else Some (Uchar.to_int (Uchar.utf_decode_uchar (String.get_utf_8_uchar s i)))) name 0)) ~default:false in
        if (String.starts_with ~prefix:(dir ^ "/") (Option.value (source : Fckt.Checker.Sources.source_text).Fckt.Checker.Sources.path ~default:"") && not (Fckt.Lang.Strings.string_contains name "/")) && lower_case then (match Fckt.Parser.Parser.parse (source : Fckt.Checker.Sources.source_text).Fckt.Checker.Sources.text with
           | Ok parsed -> Some ({ Fckt.Compiler.Tests.source = source; name = name; parsed = parsed } : Fckt.Compiler.Tests.test_file)
           | Error _ -> None) else None)) (fun it -> (it : Fckt.Compiler.Tests.test_file).Fckt.Compiler.Tests.name) in
  let tree = tree o own in
  let (names, problems) = Fckt.Compiler.Tests.written files marks in
  let stub = let fk_arg1 = Fckt.Compiler.Tests.stub marks names in
    let fk_arg2 = Fckt.Checker.Sources.source_text_default_compiled_in () in
    let fk_arg3 = Fckt.Checker.Sources.source_text_default_interface () in
    let fk_arg4 = Fckt.Checker.Sources.source_text_default_trusted () in
    ({ Fckt.Checker.Sources.path = None; project = (Fckt.Checker.Sources.ProgramProject : Fckt.Checker.Sources.project); text = fk_arg1; compiled_in = fk_arg2; interface = fk_arg3; trusted = fk_arg4 } : Fckt.Checker.Sources.source_text) in
  checked_program stub dir tree (fun stubbed -> match Fckt.Compiler.Tests.plan stubbed files marks with
     | Ok main -> if Fckt.Lang.Lists.list_is_not_empty problems then failing (List.map (fun it -> shown it dir) problems) else checked (let fk_arg1 = Fckt.Checker.Sources.source_text_default_compiled_in () in
            let fk_arg2 = Fckt.Checker.Sources.source_text_default_interface () in
            let fk_arg3 = Fckt.Checker.Sources.source_text_default_trusted () in
            ({ Fckt.Checker.Sources.path = None; project = (Fckt.Checker.Sources.ProgramProject : Fckt.Checker.Sources.project); text = main; compiled_in = fk_arg1; interface = fk_arg2; trusted = fk_arg3 } : Fckt.Checker.Sources.source_text)) dir tree false (fun ml -> write_output (Option.value (o : options).output ~default:(dir ^ "/tests.ml")) ml)
     | Error found -> failing (List.map (fun it -> shown it dir) (problems @ found)))

let declares_main (file : Fckt.Parser.source_file) : bool =
  List.exists (fun d -> (d : Fckt.Parser.declaration).Fckt.Parser.name = "main" && (match (d : Fckt.Parser.declaration).Fckt.Parser.definition with
      | Fckt.Parser.FunctionDefinition { type_parameters = _; receiver = _; parameters = _; result = _; body = _; external_ = _; operator = _ } -> true
      | _ -> false)) (file : Fckt.Parser.source_file).Fckt.Parser.declarations

let symbols (o : options) (out : string) (packages : string list) : unit =
  let given = own_packages o in
  let with_code = List.filter (fun (p, sources) -> Fckt.Lang.Lists.list_is_not_empty p && Fckt.Lang.Lists.list_is_not_empty sources) given in
  let named = if List.is_empty packages then Fckt.Lang.Lists.list_distinct (List.map (fun (p, _) -> p) with_code) else List.map (fun it -> (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) it ".") packages in
  let missing = List.filter (fun p -> Fckt.Lang.Lists.list_none given (fun (q, _) -> q = p)) named in
  let folders = String.concat ", " (List.map Fun.id (o : options).own) in
  if Fckt.Lang.Lists.list_is_not_empty missing then failing (List.map (fun it -> "error: " ^ String.concat "." (List.map Fun.id it) ^ " isn't a package in " ^ folders) missing) else ();
  let of_code = fun source -> match Fckt.Parser.Parser.parse (source : Fckt.Checker.Sources.source_text).Fckt.Checker.Sources.text with
      | Ok parsed -> not (declares_main parsed)
      | Error _ -> true in
  let own = List.map (fun (p, sources) -> (p, List.map (fun s -> if List.mem p named && of_code s then { (s : Fckt.Checker.Sources.source_text) with Fckt.Checker.Sources.trusted = true } else s) sources)) given in
  let paths = List.concat_map (fun (_, sources) -> Fckt.Lang.Lists.list_map_not_null (List.filter (fun it -> (it : Fckt.Checker.Sources.source_text).Fckt.Checker.Sources.trusted) sources) (fun it -> (it : Fckt.Checker.Sources.source_text).Fckt.Checker.Sources.path)) own in
  if List.is_empty paths then write_output out Fckt.Compiler.Symbols.empty else (let imports = String.concat "" (List.map Fun.id (List.map (fun it -> "import " ^ String.concat "." (List.map Fun.id it) ^ ".*\n") named)) in
     let entry = let fk_arg1 = Fckt.Checker.Sources.source_text_default_compiled_in () in
       let fk_arg2 = Fckt.Checker.Sources.source_text_default_interface () in
       let fk_arg3 = Fckt.Checker.Sources.source_text_default_trusted () in
       ({ Fckt.Checker.Sources.path = None; project = (Fckt.Checker.Sources.ProgramProject : Fckt.Checker.Sources.project); text = imports; compiled_in = fk_arg1; interface = fk_arg2; trusted = fk_arg3 } : Fckt.Checker.Sources.source_text) in
     let (program, errors) = Fckt.Checker.Checker.check entry (tree o own) false in
     match (program, errors) with
     | (Some p, []) -> (let (written, problems) = Fckt.Checker.Diagnostics.Diagnostics.collecting (fun () -> Fckt.Checker.Types.Solutions.solving (fun () -> Fckt.Checker.Diagnostics.Diagnostics.recovering (fun () -> Fckt.Compiler.Symbols.write p paths))) in
          match (written, problems) with
          | (Some text, []) -> write_output out text
          | _ -> failing (List.map (fun it -> shown it "the symbols") problems))
     | _ -> failing (List.map (fun it -> shown it "the symbols") errors))

let unit_name (file : string) : string =
  Fckt.Lowering.Naming.module_name (Fckt.Lang.Strings.string_remove_suffix (Fckt.Io.Paths.path_name (Fckt.Io.Paths.path file)) ".ml")

let library (o : options) (interface : Fckt.Io.path) (packages : string list) : unit =
  if List.is_empty packages then failing ["fckt: a library needs packages"] else ();
  let own = own_packages o in
  let missing = List.filter (fun pkg -> Fckt.Lang.Lists.list_none own (fun (p, _) -> p = (fun s t -> let n = String.length s and m = String.length t in if m = 0 then [s] else let rec go start i acc = if i + m > n then List.rev (String.sub s start (n - start) :: acc) else if String.sub s i m = t then go (i + m) (i + m) (String.sub s start (i - start) :: acc) else go start (i + 1) acc in go 0 0 []) pkg ".")) packages in
  if Fckt.Lang.Lists.list_is_not_empty missing then failing (List.map (fun it -> "fckt: " ^ it ^ " isn't a package in " ^ String.concat ", " (List.map Fun.id (o : options).own)) missing) else ();
  let entry = let fk_arg1 = String.concat "" (List.map Fun.id (List.map (fun it -> "import " ^ it ^ ".*\n") packages)) in
    let fk_arg2 = Fckt.Checker.Sources.source_text_default_compiled_in () in
    let fk_arg3 = Fckt.Checker.Sources.source_text_default_interface () in
    let fk_arg4 = Fckt.Checker.Sources.source_text_default_trusted () in
    ({ Fckt.Checker.Sources.path = None; project = (Fckt.Checker.Sources.ProgramProject : Fckt.Checker.Sources.project); text = fk_arg1; compiled_in = fk_arg2; interface = fk_arg3; trusted = fk_arg4 } : Fckt.Checker.Sources.source_text) in
  checked entry "the library" (tree o own) false (fun ml -> let files = List.concat_map (fun (pkg, sources) -> Fckt.Lang.Lists.list_map_not_null sources (fun source -> match Fckt.Parser.Parser.parse (source : Fckt.Checker.Sources.source_text).Fckt.Checker.Sources.text with
             | Ok parsed when not (declares_main parsed) -> Some (pkg, source, parsed)
             | _ -> None)) (List.filter (fun (p, _) -> List.mem (String.concat "." (List.map Fun.id p)) packages) own) in
     let untyped = List.concat_map (fun (_, source, parsed) -> List.map (fun (at, message) -> Option.value (source : Fckt.Checker.Sources.source_text).Fckt.Checker.Sources.path ~default:"" ^ ":" ^ string_of_int (at : Fckt.Parser.position).Fckt.Parser.line ^ ":" ^ string_of_int (at : Fckt.Parser.position).Fckt.Parser.column ^ ": error: " ^ message) (Fckt.Compiler.Interfaces.untyped (parsed : Fckt.Parser.source_file).Fckt.Parser.declarations)) files in
     if Fckt.Lang.Lists.list_is_not_empty untyped then failing untyped else ();
     let hidden = List.concat_map (fun (pkg, _, parsed) -> List.map (fun it -> String.concat "." (List.map Fun.id (pkg @ [(it : Fckt.Parser.declaration).Fckt.Parser.name]))) (List.filter (fun it -> (it : Fckt.Parser.declaration).Fckt.Parser.visibility <> (Fckt.Parser.Public : Fckt.Parser.visibility)) (parsed : Fckt.Parser.source_file).Fckt.Parser.declarations)) files in
     Fckt.Io.Files.path_delete interface;
     List.iter (fun (pkg, source, parsed) -> let source_path = Option.value (source : Fckt.Checker.Sources.source_text).Fckt.Checker.Sources.path ~default:"" in
        let folder = Fckt.Io.Paths.path_resolve interface (String.concat "/" (List.map Fun.id pkg)) in
        Fckt.Io.Files.path_make_dirs folder;
        let written = Fckt.Compiler.Interfaces.write parsed source_path (source : Fckt.Checker.Sources.source_text).Fckt.Checker.Sources.text hidden in
        Fckt.Io.Files.path_write_text (Fckt.Io.Paths.path_resolve folder (Fckt.Checker.Sources.Loader.file_name source ^ ".fki")) written) (List.filter (fun (_, _, parsed) -> Fckt.Compiler.Interfaces.sees_any parsed) files);
     Fckt.Io.Files.path_make_dirs interface;
     (let fk_arg1 = Fckt.Io.Paths.path_resolve interface "unit" in
      let fk_arg2 = unit_name (Option.value (o : options).output ~default:"") ^ "\n" in
      Fckt.Io.Files.path_write_text fk_arg1 fk_arg2);
     write_output (Option.value (o : options).output ~default:"-") ml)

let program (o : options) (file : string) : unit =
  let folder = Option.value (Option.map (fun it -> (it : Fckt.Io.path).Fckt.Io.value) (Fckt.Io.Paths.path_parent (Fckt.Io.Paths.path file))) ~default:"." in
  let given = List.map (fun it -> (Fckt.Io.Files.path_canonical (Fckt.Io.Paths.path it) : Fckt.Io.path).Fckt.Io.value) (o : options).own in
  let with_folder = if List.mem (Fckt.Io.Files.path_canonical (Fckt.Io.Paths.path folder) : Fckt.Io.path).Fckt.Io.value given then o else { (o : options) with own = [folder] @ (o : options).own } in
  let whole = not (o : options).separate && List.is_empty (o : options).libraries in
  let entry = let fk_arg1 = Fckt.Io.Files.path_read_text (Fckt.Io.Paths.path file) in
    let fk_arg2 = Fckt.Checker.Sources.source_text_default_compiled_in () in
    let fk_arg3 = Fckt.Checker.Sources.source_text_default_interface () in
    let fk_arg4 = Fckt.Checker.Sources.source_text_default_trusted () in
    ({ Fckt.Checker.Sources.path = None; project = (Fckt.Checker.Sources.ProgramProject : Fckt.Checker.Sources.project); text = fk_arg1; compiled_in = fk_arg2; interface = fk_arg3; trusted = fk_arg4 } : Fckt.Checker.Sources.source_text) in
  checked entry file (tree with_folder (own_packages with_folder)) whole (fun ml -> write_output (Option.value (o : options).output ~default:(Fckt.Lang.Strings.string_remove_suffix file ".fk" ^ ".ml")) ml)

let unknown (args : string list) : unit =
  Effect.perform (Fckt.Io.Console_println ("fckt: can't tell what to do with " ^ String.concat " " (List.map Fun.id args)));
  Effect.perform (Fckt.Io.Console_println "usage: fckt <file.fk> [-o <out.ml>] [-I <folder>]... [--other-project <folder>]...");
  Effect.perform (Fckt.Io.Console_println "         [-L <interface>]... [--no-std] [--separate] [--import <name>]...");
  Effect.perform (Fckt.Io.Console_println "       fckt --library <interface> -o <out.ml> [options] <package>...");
  Effect.perform (Fckt.Io.Console_println "       fckt --test <folder> -o <out.ml> --marker <name> --runner <name> [options]");
  Effect.perform (Fckt.Io.Console_println "       fckt --symbols <out> [options] [<package>...]");
  Effect.perform (Fckt.Io.Console_println "       fckt --core -o <out.ml> | --format <path>... | --check-format <path>...");
  Effect.perform (Fckt.Io.Console_println "       fckt --std-path | --version | --language-server");
  match Effect.perform (Fckt.Io.Process_exit 2) with
  | _ -> (assert false)

let main (args : string list) : unit =
  match args with
  | ["--version"] -> Effect.perform (Fckt.Io.Console_println ("fckt " ^ version ^ " (self-hosted, build " ^ build () ^ ")"))
  | ["--core"; "-o"; out] -> core_unit out
  | "--format" :: paths -> laid_out paths false
  | "--check-format" :: paths -> laid_out paths true
  | ["--language-server"] -> Fckt.Compiler.LanguageServer.serve ()
  | ["--std-path"] -> Effect.perform (Fckt.Io.Console_println (Fckt.Io.Files.path_canonical (Fckt.Io.Paths.path_resolve (Fckt.Compiler.Sources.home ()) "std/src") : Fckt.Io.path).Fckt.Io.value)
  | "--whole" :: file :: out :: folders -> compile file out folders true
  | file :: out :: folders when not (List.exists (fun it -> String.starts_with ~prefix:"-" it) args) -> compile file out folders false
  | _ -> match options args (let fk_arg1 = options_default_test () in
       let fk_arg2 = options_default_marker () in
       let fk_arg3 = options_default_runner () in
       let fk_arg4 = options_default_fixtures () in
       let fk_arg5 = options_default_runner_tests () in
       let fk_arg6 = options_default_imports () in
       let fk_arg7 = options_default_symbols () in
       ({ inputs = []; output = None; own = []; others = []; libraries = []; no_std = false; separate = false; library = None; test = fk_arg1; marker = fk_arg2; runner = fk_arg3; fixtures = fk_arg4; runner_tests = fk_arg5; imports = fk_arg6; symbols = fk_arg7 } : options)) with
      | Some o -> (match ((o : options).library, (o : options).inputs) with
           | _ when Option.is_some (o : options).test -> tests o (Option.value (o : options).test ~default:".")
           | _ when Option.is_some (o : options).symbols -> symbols o (Option.value (o : options).symbols ~default:"-") (o : options).inputs
           | (Some interface, packages) -> library o (Fckt.Io.Paths.path interface) packages
           | (None, [file]) -> program o file
           | _ -> unknown args)
      | None -> unknown args

